function SWUAddToDiscard(int $player, string $cardID, string $from, string $modifier = '', ?object $sourceObject = null): ?object {
    global $gTurnNumber;
    // ⚠ TOKENS CEASE TO EXIST when they leave play — a Shield / Experience / token unit / Credit / Force
    // token NEVER enters a discard pile. Enforced here because this is the single funnel every leave-play
    // path uses (unit defeat, the host-subcard strip on a defeated unit, forced discards), so guarding it
    // once covers them all. No entry is created and NO "when discarded" observer fires (a token that
    // ceases was not discarded). This is load-bearing beyond cosmetics: discard COUNT and CONTENTS gate
    // real effects ("play a unit from your discard", discard-size conditions, SOR_091-style returns), and
    // a token sitting in a discard pile is both an illegal state and a replayable card that shouldn't be.
    // ⚠ Ordered BEFORE the Clone rewrite below on purpose: a Clone leaves play as TWI_116, a REAL card
    // that must still be discarded normally — only genuinely token-typed cards cease.
    if (strncmp((string)(CardType($cardID) ?? ''), 'Token', 5) === 0
        || CardType($cardID) === 'Credit Token' || CardType($cardID) === 'Force Token') {
        return null;
    }
    // TWI_116 Clone — a Clone copy leaves play as the REAL card (TWI_116), never as the card it copied:
    // the printed copy only exists while in play, so it returns to its owner's discard as Clone. (Its
    // When Defeated / "a <copied card> was defeated" triggers still fire from the copied identity, which
    // the defeat path captured before calling here.)
    if ($sourceObject !== null && !empty($sourceObject->IsClone)) {
        $cardID = 'TWI_116';
    }
    $entry = AddDiscard($player, $cardID, $from, intval($gTurnNumber), $modifier);
    OnCardDiscarded($player, $cardID, $entry, $sourceObject);
    // SHD_163 Migs Mayfeld observes FORCED hand-discards (SWUDiscardCards / DISCARD_FROM_OWN_HAND route
    // through here with from='HAND'; self-chosen discards go through DoDiscardCard's MZMove instead).
    if ($from === 'HAND') {
        // Per-card hand-discard counters (LAW_179 "1 less per card discarded from your hand this phase";
        // LAW_076 boolean gate). Every forced-discard path lands here, so counting centrally covers them
        // all. DoDiscardCard's MZMove does NOT route through here, so it sets these itself (no double).
        //
        // ⚠ EXCLUDE THE EVENT'S OWN PLAY. An event resolving to its CONTROLLER's discard reaches this
        // funnel with from='HAND' (the play path tags it that way; a FOREIGN-owned event uses 'PLAY' and
        // never gets here) — but PLAYING a card is not DISCARDING it. Without this guard, merely playing
        // ANY event set LAW_076's "discarded from your hand or deck this phase" gate, bumped LAW_179's
        // per-card cost reduction, and fired SHD_163 Migs Mayfeld's reaction.
        // Same marker and same CardID comparison LAW_206 That's a Rock already uses to keep its own
        // "when discarded from hand or deck" trigger off a normal play.
        // Accepted narrow edge (shared with LAW_206): if an effect discards a card with the SAME CardID as
        // the event currently resolving, that discard is skipped here.
        if (($GLOBALS['gPlayingEventCardID'] ?? '') !== $cardID) {
            AddGlobalEffects($player, 'SWU_DISCARDED_HAND');
            AddGlobalEffects($player, 'SWU_DISCARDED_PHASE');
            if (function_exists('_SWUShd163React')) _SWUShd163React();
        }
    }
    return $entry;
}

function OnCardDiscarded(int $player, string $cardID, object $entry, ?object $sourceObject = null): void {
    global $cardDiscardedHandlers;
    // A source unit that has LOST ALL ABILITIES (e.g. blanked by JTL_244 before it was defeated) fires no
    // when-defeated / when-discarded triggered ability — that grant is one of the abilities it lost.
    if ($sourceObject !== null && function_exists('LostAbilities') && LostAbilities($sourceObject)) return;
    $key = $cardID . ':0';
    if (isset($cardDiscardedHandlers[$key])) {
        $cardDiscardedHandlers[$key]($player, $entry, $sourceObject);
    }
}

global $cardDiscardedHandlers;
$cardDiscardedHandlers = $cardDiscardedHandlers ?? [];

// Cards that offer an optional alternate cost (e.g. "discard a [Aspect] card instead").
// Keyed by cardID → true. Checked in ActivateCard and SWUComputeActionsData.
global $hasAlternateCostCards;
$hasAlternateCostCards = ['SOR_199' => true];

function HasTrait(string $cardID, string $trait): bool {
    $raw = CardTrait($cardID);
    if ($raw === null || $raw === '') return false;
    foreach (explode(',', $raw) as $t) {
        if (trim($t) === $trait) return true;
    }
    return false;
}

// Owner-aware trait check for a card that may be OUT OF PLAY (hand/deck/discard). Extends the bare-CardID
// HasTrait with LAW_212 Malakili's grant: "each Creature unit you OWN that isn't in play gains the
// Underworld trait" — while its owner controls a Malakili in play. $owner is the card's owner (for an
// at-play check, the player who played it). Use this at trait-check sites that read a bare CardID, where
// _SWUUnitHasTrait's in-play object isn't available.
function _SWUCardHasTrait(int $owner, string $cardID, string $trait): bool {
    if (HasTrait($cardID, $trait)) return true;
    if (strtoupper($trait) === 'UNDERWORLD' && HasTrait($cardID, 'Creature')
        && $owner > 0 && _SWUCountUnitsWithCardID($owner, 'LAW_212') > 0) return true;
    return false;
}

function _SWUUnitHasUpgrade(object $unit, string $upgradeCardID): bool {
    if (!is_array($unit->Subcards ?? null)) return false;
    foreach ($unit->Subcards as $sub) {
        $subCardID  = is_array($sub) ? ($sub['CardID'] ?? '') : ($sub->CardID ?? '');
        $subRemoved = is_array($sub) ? !empty($sub['removed']) : !empty($sub->removed);
        if (!$subRemoved && $subCardID === $upgradeCardID) return true;
    }
    return false;
}

// True if $player controls a unit in play bearing $upgradeCardID (JTL_260 granted-discount check).
function _SWUControlsUnitBearingUpgrade(int $player, string $upgradeCardID): bool {
    foreach (GetField($player) as $u) {
        if (SWUObjGone($u)) continue;
        if (_SWUUnitHasUpgrade($u, $upgradeCardID)) return true;
    }
    return false;
}

