// Parse a TurnEffects entry into ['base','params','duration','raw']. Inline "@duration" wins;
// else the registry default for the base; else "phase".
function SWUParseTurnEffect(string $s): array {
    global $turnEffectRegistry;
    $raw = $s;
    // Optional "^SOURCECARDID" provenance suffix (stripped first, before @/-): lets a synthetic-base
    // keyword token (e.g. "SENTINEL^LOF_003", "RESTORE-1@attack^JTL_097") name the card that granted
    // it so the Active Effects popup can render that card's art. CardID-base tokens don't need it.
    $source = null;
    $caret = strpos($s, '^');
    if ($caret !== false) { $source = substr($s, $caret + 1); $s = substr($s, 0, $caret); }
    $duration = null;
    $at = strpos($s, '@');
    if ($at !== false) { $duration = substr($s, $at + 1); $s = substr($s, 0, $at); }
    $params = [];
    // Dynamic per-instance values are dash-delimited: "CARDID-p1-p2" (e.g. a -3/-3 debuff is
    // "SOR_051-3-3"). The base CardID/synthetic token never contains a dash, so the first '-'
    // cleanly separates the base from its value params. ('#' is reserved for handler step keys.)
    $dash = strpos($s, '-');
    if ($dash !== false) {
        $payload = substr($s, $dash + 1);
        $params = ($payload === '') ? [] : explode('-', $payload);
        $s = substr($s, 0, $dash);
    }
    $base = $s;
    if ($duration === null) $duration = $turnEffectRegistry[$base]['duration'] ?? SWU_DUR_PHASE;
    return ['base' => $base, 'params' => $params, 'duration' => $duration, 'source' => $source, 'raw' => $raw];
}

// Build a canonical TurnEffects token. The "@duration" suffix is emitted only when it differs
// from the registry default for $base, keeping tokens short and back-compatible with bare names.
function SWUMakeTurnEffect(string $base, array $params = [], ?string $duration = null, ?string $source = null): string {
    global $turnEffectRegistry;
    $s = $base;
    if (!empty($params)) $s .= '-' . implode('-', array_map('strval', $params));
    $default = $turnEffectRegistry[$base]['duration'] ?? SWU_DUR_PHASE;
    if ($duration !== null && $duration !== $default) $s .= '@' . $duration;
    // Provenance suffix last (see SWUParseTurnEffect). Only for synthetic bases; a CardID base is
    // already its own source, so callers pass $source only when $base is a bare keyword token.
    if ($source !== null && $source !== '') $s .= '^' . $source;
    return $s;
}

// Registry kind for a base token (null if unregistered).
function SWUEffectKind(string $base): ?string {
    global $turnEffectRegistry;
    return $turnEffectRegistry[$base]['kind'] ?? null;
}

// Parsed, registry-resolved view of every TurnEffect on $obj:
//   [ ['base','kind','value','params','duration','label','sourceCardID','raw'], ... ]
// sourceCardID is the base when it looks like a CardID (SET_NNN / SET_T##), else null.
// Drives both the reader helpers and the Active Effects UI (SWUDescribeActiveEffects).
function SWUParsedTurnEffects($obj): array {
    global $turnEffectRegistry;
    if (is_string($obj)) $obj = GetZoneObject($obj);
    if ($obj === null || empty($obj->TurnEffects)) return [];
    $out = [];
    foreach ($obj->TurnEffects as $te) {
        $p = SWUParseTurnEffect((string)$te);
        $reg = $turnEffectRegistry[$p['base']] ?? null;
        $isCardID = (bool)preg_match('/^[A-Z]{2,5}_(T?\d{2,3})$/', $p['base']);
        $out[] = [
            'base'         => $p['base'],
            'kind'         => $reg['kind']  ?? null,
            'value'        => $reg['value'] ?? null,
            'amount'       => $reg['amount'] ?? null,   // static value-keyword value (CardID-derived); null ⇒ read from params
            'params'       => $p['params'],
            'duration'     => $p['duration'],
            'label'        => $reg['label'] ?? null,
            'sourceCardID' => $p['source'] ?? ($isCardID ? $p['base'] : null),
            'raw'          => $p['raw'],
        ];
    }
    return $out;
}

// True if $obj has any TurnEffect that grants keyword $keyword (boolean grant). Resolves both
// the synthetic bare token ("SENTINEL") and a CardID grant token (kind GRANT_KEYWORD, value match).
function SWUHasTurnEffectKeyword($obj, string $keyword): bool {
    foreach (SWUParsedTurnEffects($obj) as $e) {
        if ($e['kind'] === 'GRANT_KEYWORD' && $e['value'] === $keyword) return true;
    }
    return false;
}

// Highest granted value for a value-keyword ($keyword = "RAID"|"RESTORE"|"EXPLOIT"). 0 if none.
// (CR: Raid/Restore use the highest instance; Exploit is summed — callers that need the sum use
// SWUTurnEffectKeywordValueSum.)
function SWUTurnEffectKeywordValue($obj, string $keyword): int {
    $val = 0;
    foreach (SWUParsedTurnEffects($obj) as $e) {
        if ($e['kind'] === 'GRANT_KEYWORD_VALUE' && $e['value'] === $keyword) {
            $amt = $e['amount'] ?? intval($e['params'][0] ?? 0);  // CardID-derived value, else dash param
            $val = max($val, intval($amt));
        }
    }
    return $val;
}

// Sum of granted values for a value-keyword (Exploit stacks additively, CR 16.b).
function SWUTurnEffectKeywordValueSum($obj, string $keyword): int {
    $sum = 0;
    foreach (SWUParsedTurnEffects($obj) as $e) {
        if ($e['kind'] === 'GRANT_KEYWORD_VALUE' && $e['value'] === $keyword) {
            $sum += $e['amount'] ?? intval($e['params'][0] ?? 0);  // CardID-derived value, else dash param
        }
    }
    return $sum;
}

// Net "for this phase" stat bonus on $obj for $stat ('power'|'hp'): STAT_BUFF minus STAT_DEBUFF.
// (Attack-duration STAT_ATK_POWER is NOT included — combat reads that separately.)
function SWUTurnEffectStatBonus($obj, string $stat): int {
    $idx = ($stat === 'hp') ? 1 : 0;
    $net = 0;
    foreach (SWUParsedTurnEffects($obj) as $e) {
        if ($e['kind'] === 'STAT_BUFF')   $net += intval($e['params'][$idx] ?? 0);
        if ($e['kind'] === 'STAT_DEBUFF') $net -= intval($e['params'][$idx] ?? 0);
    }
    return $net;
}

// UI-facing summary of a unit's active TurnEffects for the "Active Effects" popup.
// Returns [['label'=>string, 'duration'=>'attack'|'phase'|'perm', 'sourceCardID'=>string|null], …].
// Only REGISTERED tokens are described; unregistered tokens (internal bookkeeping like SWU_PAID_*,
// the inline-consumed combat one-shots, and dead GA tokens) are skipped so the popup shows only
// meaningful, player-facing effects. {0},{1},… in a registry label interpolate the token #params.
function SWUDescribeActiveEffects($obj): array {
    $out = [];
    foreach (SWUParsedTurnEffects($obj) as $e) {
        if ($e['kind'] === null) continue;                       // unregistered → not shown
        $label = $e['label'] ?? ($e['sourceCardID'] ?? $e['base']);
        if (strpos($label, '{') !== false) {
            foreach ($e['params'] as $i => $p) {
                $label = str_replace('{' . $i . '}', (string)$p, $label);
            }
        }
        $out[] = [
            'label'        => $label,
            'duration'     => $e['duration'],
            'sourceCardID' => $e['sourceCardID'],
        ];
    }
    return $out;
}

// Centralized duration-driven expiry. Drops expiring TurnEffects from every arena unit:
//   $scope 'attack' → drop only attack-duration effects (run at attack end).
//   $scope 'phase'  → drop attack- AND phase-duration effects (run at RegroupPhaseStart).
// 'perm' effects are never dropped (they ride until the unit leaves play). ONLY registry-known
// tokens are affected — unregistered tokens (legacy stat strings still handled by the old
// RegroupPhaseStart predicate during the migration, and dead GA tokens) are left untouched, so
// this can run alongside the legacy predicate without double-handling.
function SWUExpireTurnEffects(string $scope): void {
    global $turnEffectRegistry;
    $dropPhaseToo = ($scope === SWU_DUR_PHASE);
    $shouldDrop = function($te) use ($turnEffectRegistry, $dropPhaseToo, $scope): bool {
        $p = SWUParseTurnEffect((string)$te);
        if (!isset($turnEffectRegistry[$p['base']])) return false;   // unregistered → untouched
        if ($p['duration'] === SWU_DUR_ATTACK) return true;          // attack drops in both scopes
        if ($p['duration'] === SWU_DUR_PHASE)  return $dropPhaseToo;  // phase drops only in phase scope
        if ($p['duration'] === SWU_DUR_ROUND)  return ($scope === SWU_DUR_ROUND); // round drops only at round-end
        return false;                                                 // perm never drops
    };
    $keep = fn($e) => !$shouldDrop($e);
    for ($p = 1; $p <= SeatCountForGame(); $p++) {
        $g = &GetGroundArena($p);
        for ($i = 0; $i < count($g); $i++) {
            if (!empty($g[$i]->removed)) continue;
            $g[$i]->TurnEffects = array_values(array_filter($g[$i]->TurnEffects ?? [], $keep));
        }
        unset($g);
        $s = &GetSpaceArena($p);
        for ($i = 0; $i < count($s); $i++) {
            if (!empty($s[$i]->removed)) continue;
            $s[$i]->TurnEffects = array_values(array_filter($s[$i]->TurnEffects ?? [], $keep));
        }
        unset($s);
    }
}

// Apply a "for this phase" buff (+$power/+$hp) to the unit at $mzID by tagging it with a
// "{source}-{power}-{hp}" TurnEffect (registry kind STAT_BUFF, phase duration). The base is the
// $source CardID (Active Effects provenance) when it has a registry row; otherwise it falls back
// to the synthetic 'SWUBUFF' base so the stat still applies and still expires even if a source
// row was forgotten. Read by ObjectCurrentPower/HP via SWUTurnEffectStatBonus; expired centrally
// by SWUExpireTurnEffects. Unlike a shrink, a buff never defeats a unit, so no sweep here.
// Append a unique per-application suffix to a "{base}-{power}-{hp}" stat token so two IDENTICAL
// buffs/debuffs applied to the SAME unit STACK instead of AddTurnEffect de-duping the identical
// string down to one. They are two separate continuous effects per CR (e.g. LOF_070 Anakin's two
// When-Played "-3/-3 this phase" windows both aimed at one unit → -6/-6). The '^N' suffix is stripped
// for registry/kind resolution (SWUParseTurnEffect), so the token still parses as its STAT_BUFF/
// STAT_DEBUFF base and each application's params still sum. Mirrors the SEC_081 combat-buff fix.
function _SWUStackingStatToken(string $mzID, string $prefix): string {
    $obj = GetZoneObject($mzID);
    $n = 0;
    if ($obj !== null) foreach (($obj->TurnEffects ?? []) as $te) { if (strpos((string)$te, "{$prefix}^") === 0) $n++; }
    return "{$prefix}^{$n}";
}

function SWUApplyPhaseBuff(string $mzID, int $power, int $hp, string $source = ''): void {
    global $turnEffectRegistry;
    $base = ($source !== '' && isset($turnEffectRegistry[$source])) ? $source : 'SWUBUFF';
    AddTurnEffect($mzID, _SWUStackingStatToken($mzID, "{$base}-{$power}-{$hp}"));
}

// "+N power for THIS ATTACK" (Surprise Strike SOR_220, attack-with riders SOR_227/SOR_240).
// Unlike SWUApplyPhaseBuff this is NOT a persistent stat — it's a one-shot combat-damage
// bonus that SWUCombatDamage adds to attack power and REMOVES (mirrors Raid). So the unit's
// ObjectCurrentPower is unchanged before/after; only the dealt damage is boosted. The cards
// are all +N/+0, so power-only. Cleared in RegroupPhaseStart too, in case an attack fizzles.
function SWUAddAttackPowerBonus(string $mzID, int $power): void {
    if ($power <= 0) return;
    AddTurnEffect($mzID, "SWU_ATK_POWER_{$power}");
}

// ── Uniqueness rule (CR 8.19.1.b / 29.3) ────────────────────────────────────
// A player may control only ONE in-play copy of a given unique card at a time. Copies are matched by
// name + subtitle (NOT CardID) so cross-set reprints of the same character still collide. If a player
// ever controls more than one, they must immediately choose and defeat copies until only one remains
// — this is a game RULE, not a triggered ability, and it resolves as the action finishes (before the
// turn passes). Called from SWUAfterAction, the single action-end chokepoint.
//
// Returns true (and queues an interactive choose-and-defeat via UNIQUENESS_DEFEAT) when a violation
// exists, so the caller can defer the action-end. Returns false when every unique card the player
// controls is a singleton. Scope: arena units (ground + space); unique upgrades / pilot upgrades
// (CR 29.3.a) are not yet covered (see SWUSim/Tests/Cases/core/UniquenessRule_* / TODO).
function SWUEnforceUniqueness(int $player, ?int $actingPlayer = null): bool {
    $actingPlayer = $actingPlayer ?? intval($player);
    global $playerID, $titleData, $subtitleData, $uniqueData;
    $saved = $playerID;
    $playerID = intval($player); // ZoneSearch("my…") is relative to $playerID; the chosen mzID is
                                 // answered by $player, so "myGroundArena-N" resolves the same on both ends.

    // CR 29.3.a mixed unit/pilot: a unique card the player controls as an arena UNIT can't ALSO be in
    // play as an attached pilot/upgrade copy of the same card. Auto-defeat any such subcard (keep the
    // unit — the unit-play path that reached here is what put a fresh copy on the board). No prompt.
    // The reverse direction (a pilot was just played while the unit was in an arena) is resolved earlier,
    // in SWUEnforceUpgradeUniqueness during the attach — so by here the unit is the copy to keep.
    $unitCardIDs = [];
    foreach (['myGroundArena', 'mySpaceArena'] as $zone) {
        foreach (ZoneSearch($zone, AnyUnitFilter) as $mz) {
            $o = GetZoneObject($mz);
            if (SWUObjGone($o)) continue;
            if (!empty($o->IsClone)) continue;   // TWI_116 Clone copy — not unique (ruling)
            $cid = $o->CardID ?? '';
            if (!empty($uniqueData[$cid])) $unitCardIDs[$cid] = true;
        }
    }
    foreach (array_keys($unitCardIDs) as $cid) {
        $guard = 0;
        while ($guard++ < 40) {
            $found = false;
            foreach (['myGroundArena', 'mySpaceArena'] as $zone) {
                foreach (ZoneSearch($zone, AnyUnitFilter) as $hostMz) {
                    $host = GetZoneObject($hostMz);
                    if (SWUObjGone($host) || !is_array($host->Subcards ?? null)) continue;
                    $upgIdx = 0;
                    foreach ($host->Subcards as $sub) {
                        $isCaptive = is_array($sub) ? !empty($sub['IsCaptive']) : !empty($sub->IsCaptive);
                        $isRemoved = is_array($sub) ? !empty($sub['removed'])   : !empty($sub->removed);
                        if ($isCaptive || $isRemoved) continue;
                        $subCid = is_array($sub) ? ($sub['CardID'] ?? '') : ($sub->CardID ?? '');
                        if ($subCid === $cid) {
                            SWUDefeatUpgrade(intval($player), $hostMz, $upgIdx);
                            DecisionQueueController::CleanupRemovedCards();
                            $found = true;
                            break 3;
                        }
                        $upgIdx++;
                    }
                }
            }
            if (!$found) break;
        }
    }

    $groups = []; // "name|subtitle" => [mzID, …]
    foreach (['myGroundArena', 'mySpaceArena'] as $zone) {
        foreach (ZoneSearch($zone, AnyUnitFilter) as $mz) {
            $o = GetZoneObject($mz);
            if (SWUObjGone($o)) continue;
            if (!empty($o->IsClone)) continue;   // TWI_116 Clone copy — not unique (ruling)
            $cid = $o->CardID ?? '';
            if (empty($uniqueData[$cid])) continue;
            $key = ($titleData[$cid] ?? $cid) . '|' . ($subtitleData[$cid] ?? '');
            $groups[$key][] = $mz;
        }
    }
    $playerID = $saved;
    foreach ($groups as $mzIDs) {
        if (count($mzIDs) > 1) {
            // The continuation carries the ACTING player: the chooser may be the NON-acting seat
            // (an exchange/control-give handed THEM the duplicate), and the post-defeat re-entry
            // must resume the acting player's action-end, not the chooser's.
            SWUQueueChooseTarget(intval($player), $mzIDs,
                "Uniqueness_rule_choose_a_copy_to_defeat", "UNIQUENESS_DEFEAT|" . intval($actingPlayer));
            return true;
        }
    }
    return false;
}

// CR 8.19.1.b / 29.3 — uniqueness for UPGRADES (incl. PILOTS). A player may control only one copy of a
// unique card. When a new copy attaches (via _SWUFinalizeUpgradeAttach), every OTHER controlled copy of
// the same card is defeated AUTOMATICALLY — no prompt (unlike the unit case) — keeping the just-played
// one. Copies are matched by CardID (a card played as a pilot upgrade shares its CardID with the same
// card played as a unit — CR 29.3.a). $keepSub is the subcard just attached; it is skipped by object
// identity so only the OTHER copy(ies) are defeated. Each pass defeats one copy and re-scans (defeats
// rebuild Subcards / compact arenas), covering the rare 3+ copy pile. Two forms of "other copy":
//   (a) the same card sitting in an arena as a UNIT (the pilot's unit form) → SWUDefeatUnit.
//   (b) another copy attached as a subcard (pilot/upgrade) on some unit    → SWUDefeatUpgrade.
function SWUEnforceUpgradeUniqueness(int $player, string $cardID, object $keepSub): void {
    global $uniqueData, $playerID;
    if (empty($uniqueData[$cardID])) return;
    $saved = $playerID;
    $playerID = intval($player);
    $guard = 0;
    while ($guard++ < 40) {
        $defeated = false;
        // (a) An arena UNIT of the same card (the unit form of a pilot) — keep the just-played pilot.
        foreach (['myGroundArena', 'mySpaceArena'] as $zone) {
            foreach (ZoneSearch($zone, AnyUnitFilter) as $unitMz) {
                $u = GetZoneObject($unitMz);
                if (SWUObjGone($u)) continue;
                if (($u->CardID ?? '') === $cardID) {
                    SWUDefeatUnit(intval($player), $unitMz);
                    DecisionQueueController::CleanupRemovedCards();
                    $defeated = true;
                    break 2;
                }
            }
        }
        if ($defeated) continue;
        // (b) Another copy attached as a subcard elsewhere — skip the just-attached $keepSub.
        foreach (['myGroundArena', 'mySpaceArena'] as $zone) {
            foreach (ZoneSearch($zone, AnyUnitFilter) as $hostMz) {
                $host = GetZoneObject($hostMz);
                if (SWUObjGone($host) || !is_array($host->Subcards ?? null)) continue;
                $upgIdx = 0; // index among non-captive, non-removed subcards — matches SWUDefeatUpgrade
                foreach ($host->Subcards as $sub) {
                    $isCaptive = is_array($sub) ? !empty($sub['IsCaptive']) : !empty($sub->IsCaptive);
                    $isRemoved = is_array($sub) ? !empty($sub['removed'])   : !empty($sub->removed);
                    if ($isCaptive || $isRemoved) continue;
                    $subCid = is_array($sub) ? ($sub['CardID'] ?? '') : ($sub->CardID ?? '');
                    if ($subCid === $cardID && !(is_object($sub) && $sub === $keepSub)) {
                        SWUDefeatUpgrade(intval($player), $hostMz, $upgIdx);
                        DecisionQueueController::CleanupRemovedCards();
                        $defeated = true;
                        break 3;
                    }
                    $upgIdx++;
                }
            }
        }
        // (c) A copy attached to this player's BASE (Fortify — HMW_206 The Tarkin Doctrine is unique).
        // The arena sweeps above never look at bases, so without this the player would illegally
        // control two copies of a unique upgrade.
        if (!$defeated) {
            $baseZone = &GetBase(intval($player));
            if (isset($baseZone[0]) && is_array($baseZone[0]->Subcards ?? null)) {
                foreach ($baseZone[0]->Subcards as $bIdx => $bSub) {
                    // Round-tripped subcards are associative arrays, not objects — read both shapes.
                    // The index is needed for SWUDefeatUpgrade, so this can't use GetUpgradesOnUnit.
                    $bCid = is_array($bSub) ? ($bSub['CardID'] ?? '') : ($bSub->CardID ?? '');
                    if ($bCid !== $cardID) continue;
                    if (is_object($bSub) && $bSub === $keepSub) continue;   // never the copy just attached
                    SWUDefeatUpgrade(intval($player), 'myBase-0', $bIdx);
                    DecisionQueueController::CleanupRemovedCards();
                    $defeated = true;
                    break;
                }
            }
            unset($baseZone);
        }
        if (!$defeated) break;
    }
    $playerID = $saved;
}

// ── Targeted-effect queue helpers ───────────────────────────────────────────
// Collapse the ubiquitous "choose one target, then run $handler on it" tail:
// 1 target → PASSPARAMETER (auto); 2+ → MZCHOOSE; then CUSTOM $handler (which reads the
// chosen mzID from $lastDecision). No-op on an empty list. $handler may carry args, e.g.
// "GIVE_EXPERIENCE|1". Pass $block to match the surrounding decisions' priority (default 1).
// $may: emit MZMAYCHOOSE (declinable) instead of MZCHOOSE (mandatory). Set it for any offer whose
// printed text is optional — "you may", "up to N", "any number of". This became load-bearing on
// 2026-08-14: MZCHOOSE is now genuinely non-declinable (SWUValidateDecisionAnswer), so an optional
// effect typed MZCHOOSE would trap the player into resolving it.
//
// ⚠ The single-target shortcut is skipped when $may is set. Auto-resolving a lone target is right for
// a mandatory effect (there is no decision to make) and WRONG for an optional one: it silently
// resolves the very thing the player was entitled to decline, and it made a card's optionality depend
// on how many legal targets happened to be on the board — declinable with two, forced with one.
function SWUQueueChooseTarget(int $player, array $targets, string $tooltip, string $handler, int $block = 1, bool $may = false): void {
    if (empty($targets)) return;
    if (count($targets) === 1 && !$may) DecisionQueueController::AddDecision($player, 'PASSPARAMETER', $targets[0], $block);
    else DecisionQueueController::AddDecision($player, $may ? 'MZMAYCHOOSE' : 'MZCHOOSE', implode('&', $targets), $block, $tooltip);
    DecisionQueueController::AddDecision($player, 'CUSTOM', $handler, $block);
}

// Server-side answer validation for targeted choices (closes the arbitrary-target hole: a client
// could answer a pending MZCHOOSE/MZMAYCHOOSE with ANY mzID — e.g. a unit outside the offered pool —
// and the CUSTOM continuation would act on it; the UI constrains clicks but the server must not
// trust input). Only the MZ choose types are validated: other decision types (YESNO, OPTIONCHOOSE,
// search-by-CardID) keep their existing handling; MZMULTICHOOSE is validated as a subset (below). PASS/'-' decline tokens are
// always allowed — decline semantics per type are enforced downstream, not here. Called by
// production's answer entry point (EngineActionRunner mode=100, gated by function_exists so other
// sims are untouched) and by the test harness's answerDecision (which throws on an invalid answer
// so a mis-encoded test fails loudly instead of silently acting out of pool).
function SWUValidateDecisionAnswer(int $player, string $answer): bool {
    $head = null;
    foreach (GetDecisionQueue($player) as $d) {
        if (empty($d->removed)) { $head = $d; break; }
    }
    if ($head === null) return true;
    $type = (string)($head->Type ?? '');
    // A DECLINE is only legal where the decision is declinable. MZCHOOSE means MANDATORY — that is the
    // whole difference between it and MZMAYCHOOSE — but this validator used to accept 'PASS'/'-'/''
    // for every type before it looked at one, so a mandatory choose could be walked away from.
    // USER RULING (2026-08-14, Fleet Lieutenant SOR_240): you may pass on an "attack with a unit"
    // offer, but ONCE YOU HAVE CHOSEN THE ATTACKER YOU MUST CHOOSE THE TARGET. Declining at the target
    // stage abandoned the whole attack with the attacker still READY.
    // ⚠ Consequence: an offer whose card text really is optional ("you may", "up to N", "any number")
    // must be queued as MZMAYCHOOSE. Typing it MZCHOOSE and relying on this function's old blanket
    // acceptance is no longer a working way to be declinable.
    // PASSPARAMETER is a FORCED auto-resolve, not a question: SWUQueueChooseTarget emits it instead of
    // MZCHOOSE when exactly one target is legal, and its Param IS the answer. It was unvalidated,
    // because everything outside the MZ family fell through the early return below — so the only legal
    // value was never enforced and the CUSTOM continuation ran on whatever was submitted.
    // Harmless for the ACTING player (it drains inside the same request, so no answer is ever solicited)
    // but live CROSS-PLAYER: one queued for the OTHER seat stays pending until that seat's next request,
    // and in that window any value was accepted. Measured on LAW_099 Governor's Shuttle: the opponent
    // could defeat a unit they did not control, and a garbage answer silently walked away from a
    // MANDATORY "each player chooses". Note this is also why the decline check must come AFTER: a forced
    // resolve is not declinable, so PASS/'-' must be refused here too.
    if ($type === 'PASSPARAMETER') return $answer === (string)($head->Param ?? '');
    if ($answer === 'PASS' || $answer === '-' || $answer === '') return $type !== 'MZCHOOSE';
    if ($type !== 'MZCHOOSE' && $type !== 'MZMAYCHOOSE' && $type !== 'MZMULTICHOOSE'
            && $type !== 'MZSPLITASSIGN') return true;
    global $playerID;
    $saved = $playerID;
    $playerID = intval($player);   // Param mzIDs are in the deciding player's frame
    // MZMULTICHOOSE carries "min|max|spec&spec&…" and its answer is an '&'-joined SUBSET, so both the
    // pool and the answer need splitting. Until 2026-08-14 this type was unvalidated entirely, which
    // made every multi-select section able to "choose" cards the offer never contained — the exact
    // shape that let SOR_245 Medal Ceremony's resolution-only section pass VACUOUSLY against a
    // friendly-only pool. Each picked mzID must be in the pool; an out-of-pool pick fails the whole answer.
    if ($type === 'MZMULTICHOOSE') {
        // 'DONE' is the multi-select TERMINATOR ("I have finished picking"), the multichoose analogue of
        // PASS/'-' — it is never an mzID and must not be pool-checked. Handlers read a non-mzID answer as
        // "nothing selected". 9 existing sections use it legitimately.
        if ($answer === 'DONE') { $playerID = $saved; return true; }
        $parts = explode('|', (string)($head->Param ?? ''), 3);
        $poolStr = count($parts) >= 3 ? $parts[2] : '';
        $allOk = true;
        foreach (explode('&', $answer) as $pick) {
            $pick = trim($pick);
            if ($pick === '' || $pick === '-' || $pick === 'PASS') continue;
            $hit = false;
            foreach (explode('&', $poolStr) as $rawSpec) {
                $spec = explode(':', $rawSpec)[0];
                if ($spec === '') continue;
                if (preg_match('/^(.+)-(\d+)(?:\.u(\d+))?$/', $spec)) { if ($pick === $spec) { $hit = true; break; } }
                elseif (preg_match('/^' . preg_quote($spec, '/') . '-\d+$/', $pick)) {
                    $o = GetZoneObject($pick);
                    if ($o !== null && empty($o->removed)) { $hit = true; break; }
                }
            }
            if (!$hit) { $allOk = false; break; }
        }
        $playerID = $saved;
        return $allOk;
    }
    // MZSPLITASSIGN carries "total|spec&spec&…" (with an optional trailing flag such as |UPTO) and its
    // answer is "mzID:amount,mzID:amount". Until now this type was NOT validated at all: only the
    // per-target caps were enforced, and those are applied downstream by the appliers. So a client could
    // assign MORE THAN THE POOL — 6+3+4 against Midnight Repairs' 8 healed all 13. Same hole, same shape,
    // as the MZCHOOSE and MZMULTICHOOSE ones closed before it; the UI happens to gate on
    // remaining==0, which is exactly why nothing server-side did.
    // Validate BOTH halves: every mzID must be in the offered pool, and the TOTAL must not exceed it.
    // Under-assigning stays legal — "up to N" and a soft pass of 0 are both real plays.
    if ($type === 'MZSPLITASSIGN') {
        $paramParts = explode('|', (string)($head->Param ?? ''));
        $poolTotal  = intval($paramParts[0] ?? 0);
        $specStr    = $paramParts[1] ?? '';
        $assigned   = 0;
        $allOk      = true;
        foreach (explode(',', $answer) as $pair) {
            $pair = trim($pair);
            if ($pair === '') continue;
            $bits = explode(':', $pair);
            if (count($bits) < 2) { $allOk = false; break; }
            $mz  = trim($bits[0]);
            $amt = intval($bits[1]);
            if ($amt < 0) { $allOk = false; break; }
            $assigned += $amt;
            $hit = false;
            foreach (explode('&', $specStr) as $rawSpec) {
                $spec = explode(':', $rawSpec)[0];
                if ($spec === '') continue;
                // A singleton zone is addressable bare ('myBase') or indexed ('myBase-0'); both are
                // long-standing legal answer forms, so normalize before comparing.
                if ($mz === $spec || $mz . '-0' === $spec) { $hit = true; break; }
            }
            if (!$hit) { $allOk = false; break; }
        }
        if ($poolTotal > 0 && $assigned > $poolTotal) $allOk = false;
        $playerID = $saved;
        return $allOk;
    }
    $ok = false;
    foreach (explode('&', (string)($head->Param ?? '')) as $rawSpec) {
        $spec = explode(':', $rawSpec)[0];
        if ($spec === '') continue;
        // The optional `.uN` tail is the SUBCARD form (an upgrade/token addressed on its host — see
        // MZParseSubcardID). It is matched HERE, in the explicitly-listed-candidate branch, rather
        // than in the zone-prefix branch below: a subcard is always offered as a named candidate, and
        // routing it through the prefix branch would build the nonsense pattern
        // "^myGroundArena\-0\.u2-\d+$" and reject every legal answer.
        if (preg_match('/^(.+)-(\d+)(?:\.u(\d+))?$/', $spec)) {
            // Explicitly-listed candidate: the string match alone accepts. No liveness re-check —
            // some windows (e.g. prevent-during-damage offers) legitimately list an object whose
            // zone state is mid-transition when the answer arrives; the pool author vouched for it.
            if ($answer === $spec) { $ok = true; break; }
        } else {
            if (!preg_match('/^' . preg_quote($spec, '/') . '-\d+$/', $answer)) continue;
            $o = GetZoneObject($answer);
            if ($o !== null && empty($o->removed)) { $ok = true; break; }
        }
    }
    $playerID = $saved;
    return $ok;
}

// "You may: choose a target, then run $handler." Emits a single MZMAYCHOOSE — one popup
// where the player picks a target OR declines (the Pass button). On decline the chosen
// value is '-', so $handler must no-op on a '-'/''/PASS lastDecision (all the universal
// effect handlers — DEAL_UNIT_DAMAGE, GIVE_SHIELD, GIVE_EXPERIENCE, HEAL_TARGET,
// EXHAUST_UNIT, BOUNCE_UNIT — already do). This replaces the old YESNO + MAY_CHOOSE
// re-collection chain, saving a click. $handler may carry args ("GIVE_EXPERIENCE|1") —
// no pipe-escaping needed since it's queued as its own CUSTOM decision (like
// SWUQueueChooseTarget). $yesTooltip is retained for call-site readability/compat; the
// $chooseTooltip is the selection-mode prompt. Use SWUQueueChooseTarget for mandatory
// (non-"may") effects.
// $dontSkipOnPass — set it when the continuation must STILL RUN after the player hits the Pass button.
// A "PASS" answer is sticky in the decision queue: ExecuteStaticMethods skips every following CUSTOM that
// is not flagged (the same reason SWUQueueAfterAction and _SWUQueueOrchestration carry it). That default
// is right for a plain optional effect — its handler self-guards on '-'/'PASS' and has nothing to do —
// but WRONG when the continuation is the loop itself and its decline branch still owes the player
// something. ASH_053 Pre Vizsla is the case that found this: declining the next pick is what finishes the
// ability and creates one Mandalorian token per unit already defeated, so a skipped CUSTOM left the
// defeats standing with no tokens (bug #972). Guarded by that card's
// PASS_WithTargetsStillInThePool_StillCreatesTheTokens.
function SWUQueueMayChooseTarget(int $player, array $targets, string $yesTooltip, string $chooseTooltip, string $handler, int $block = 1, int $dontSkipOnPass = 0): void {
    if (empty($targets)) return;
    DecisionQueueController::AddDecision($player, 'MZMAYCHOOSE', implode('&', $targets), $block, $chooseTooltip);
    DecisionQueueController::AddDecision($player, 'CUSTOM', $handler, $block, '', $dontSkipOnPass);
}

// "Choose two (different modes), in any order" modal (SOR_058/107/155/203 — the aspect events).
// Reuses sequential OPTIONCHOOSE — NO new decision type / UI. Queue a mode picker (all remaining
// labels); MODAL_CHOOSE resolves the chosen mode (its own effect decisions go on at block 1) then
// appends the NEXT picker (also block 1) so it runs AFTER the prior mode's effects (block-1 FIFO +
// append-at-end-of-block insertion sequences them). $picksLeft counts modes still to choose.
function SWUQueueModalChoose(int $player, string $cardID, array $labels, int $picksLeft, int $block = 1): void {
    if ($picksLeft <= 0 || count($labels) === 0) return;
    // Each successive picker sits at a HIGHER block so a multi-step mode (whose chained sub-decisions
    // run at block 1) fully resolves before the next pick is offered.
    DecisionQueueController::AddDecision($player, "OPTIONCHOOSE", implode("&", $labels), $block,
        tooltip:"Choose_a_mode");
    DecisionQueueController::AddDecision($player, "CUSTOM",
        "MODAL_CHOOSE|{$cardID}|{$picksLeft}|{$block}|" . implode(",", $labels), $block);
}

// "An opponent chooses one of THEIR units, then $handler runs on it" — the reusable cross-player
// choose pattern (generalizes SOR_167's inline cross-player discard). $caster's opponent picks; the
// targets are the opponent's own units (collected under $playerID=$opponent so myGroundArena/
// mySpaceArena resolve to THEIR arenas). $nonLeader excludes deployed leaders (NonLeaderUnitFilter).
//  - 0 units → no-op.
//  - 1 unit  → the choice is forced, so resolve $handler SYNCHRONOUSLY under the opponent (a
//              cross-player single-target PASSPARAMETER auto-resolve is fragile — cf. SOR_167).
//  - 2+ units → queue an MZCHOOSE answered BY THE OPPONENT + the CUSTOM $handler (which resolves the
//              picked relative mzID under the opponent). Leaves $playerID = opponent on return so the
//              harness's MZCountChoices resolves the relative mzIDs under the opponent (queuing gotcha).
// Because a trigger dispatch (DispatchTrigger) restores $playerID after the closure, the calling card
// must queue this via an intermediate CUSTOM (e.g. OPP_DEFEAT_OWN_UNIT) rather than calling it inline
// from a WhenPlayed/OnAttack closure — the CUSTOM path (ExecuteStaticMethods) does not restore $playerID.
function SWUOpponentChoosesOwnUnit(int $caster, bool $nonLeader, string $tooltip, string $handler): void {
    global $playerID, $customDQHandlers;
    $opp = OtherPlayer($caster);
    $savedPID = $playerID;
    $playerID = $opp;
    $filter = $nonLeader ? NonLeaderUnitFilter : AnyUnitFilter;
    $units = array_values(array_merge(
        ZoneSearch('myGroundArena', $filter),
        ZoneSearch('mySpaceArena',  $filter)
    ));
    if (empty($units)) { $playerID = $savedPID; return; }
    if (count($units) === 1) {
        $hp = explode('|', $handler);
        $hn = array_shift($hp);
        if (isset($customDQHandlers[$hn])) $customDQHandlers[$hn]($opp, $hp, $units[0]);
        $playerID = $savedPID;
        return;
    }
    DecisionQueueController::AddDecision($opp, 'MZCHOOSE', implode('&', $units), 1, tooltip:$tooltip);
    DecisionQueueController::AddDecision($opp, 'CUSTOM', $handler, 1);
    // intentionally leave $playerID = $opp (MZCountChoices resolves the relative mzIDs under it)
}

// "(You may) attack with another [Rebel] unit" — the post-attack follow-up shared by Leia's leader
// action / deployed OnAttackEnd (SOR_009) and Rebel Assault (SOR_103). Collects eligible READY
// units (optionally Rebel-only), excluding $excludeUID (the "another" clause = the just-attacked
// unit). Queues a mandatory MZCHOOSE or an optional MZMAYCHOOSE, then CUSTOM CHAINED_ATTACK|{bonus},
// which applies a one-shot +{bonus}/+0 ("for this attack") and begins the attack. Fizzles (no-op)
// if no eligible unit. Caller must already be in a post-combat trigger context (OnAttackEnd or the
// ChainedAttack trigger) so SWUAfterAction stays deferred until this second attack resolves.
// $constraint (optional): "space"/"ground" restricts the chained attacker by current arena; any other
// non-empty value is treated as a required trait (e.g. "Vehicle"). $rebelOnly is the legacy Rebel filter.
// JTL_247 — true if $obj has a (non-captive) Pilot subcard attached.
function _SWUHasPilotOnIt($obj): bool {
    if (!is_array($obj->Subcards ?? null)) return false;
    foreach ($obj->Subcards as $sub) {
        $cap = is_array($sub) ? !empty($sub['IsCaptive']) : !empty($sub->IsCaptive);
        $rem = is_array($sub) ? !empty($sub['removed'])   : !empty($sub->removed);
        $pil = is_array($sub) ? !empty($sub['IsPilot'])   : !empty($sub->IsPilot);
        $scid = is_array($sub) ? ($sub['CardID'] ?? '')   : ($sub->CardID ?? '');
        if (!$cap && !$rem && ($pil || ($scid !== '' && HasTrait($scid, 'Pilot')))) return true;
    }
    return false;
}

// JTL_141 IG-88 — true if any enemy unit (an opponent of $obj's controller) is damaged.
function _SWUEnemyUnitDamaged($obj): bool {
    $opp = OtherPlayer(intval($obj->Controller ?? 0));
    if ($opp <= 0) return false;
    foreach (array_merge(GetGroundArena($opp), GetSpaceArena($opp)) as $u) {
        if (empty($u->removed) && intval($u->Damage) > 0) return true;
    }
    return false;
}

// JTL_093 Nien Nunb — count friendly Pilots ("Pilot unit and upgrade") the controller controls, excluding
// the unit at $excludeUid. If $excludeOneUpgrade, subtract one (the JTL_093 pilot upgrade counting itself).
function _SWUCountFriendlyPilots(int $controller, int $excludeUid, bool $excludeOneUpgrade): int {
    $count = 0;
    foreach (GetUnitsInPlay($controller) as $u) {
        if (intval($u->UniqueID ?? 0) !== $excludeUid && HasTrait($u->CardID ?? '', 'Pilot')) $count++;
        foreach (GetUpgradesOnUnit($u) as $up) {
            if (HasTrait($up->CardID ?? '', 'Pilot')) $count++;
        }
    }
    if ($excludeOneUpgrade) $count = max(0, $count - 1);
    return $count;
}

// Count $controller's in-play units carrying $trait, excluding one UniqueID — i.e. "each OTHER friendly
// <trait> unit" (HMW_164 Chief Chirpa). Two deliberate choices:
//   • TraitContains (object-aware), NOT bare-CardID HasTrait, so a GRANTED trait counts and a
//     per-instance trait loss is honoured — the deployed-leader/trait-override family.
//   • GetUnitsInPlay includes DEPLOYED LEADER units, which are units for "each other friendly X unit"
//     (HMW_014 Wicket is an Ewok leader, so he counts for Chirpa).
function _SWUCountFriendlyTraitUnits(int $controller, string $trait, int $excludeUid): int {
    $count = 0;
    foreach (GetUnitsInPlay($controller) as $u) {
        if (SWUObjGone($u)) continue;
        if (intval($u->UniqueID ?? 0) === $excludeUid) continue;
        if (TraitContains($u, $trait)) $count++;
    }
    return $count;
}

function SWUQueueAnotherAttack(int $player, bool $rebelOnly, bool $mayDecline, int $bonus, int $excludeUID, string $constraint = ''): void {
    global $playerID;
    $playerID = $player;
    $units = array_values(array_filter(array_merge(
        ZoneSearch('myGroundArena', AnyUnitFilter),
        ZoneSearch('mySpaceArena',  AnyUnitFilter)
    ), function($mz) use ($rebelOnly, $excludeUID, $constraint) {
        $o = GetZoneObject($mz);
        if ($o === null || intval($o->Status) !== 1) return false;
        if (intval($o->UniqueID ?? 0) === $excludeUID) return false;
        if ($rebelOnly && !HasTrait($o->CardID, 'Rebel')) return false;
        $loc = $o->Location ?? '';
        if ($constraint === 'space'  && $loc !== 'SpaceArena')  return false;
        if ($constraint === 'ground' && $loc !== 'GroundArena') return false;
        // SEC_006 Colonel Yularen — cost-capped chain: "costlt:N" = cost < N (leader, "less than it"),
        // "costle:N" = cost ≤ N (deployed, "costs 4 or less").
        if (strpos($constraint, 'costlt:') === 0) {
            if (intval(CardCost($o->CardID)) >= intval(substr($constraint, 7))) return false;
        } elseif (strpos($constraint, 'costle:') === 0) {
            if (intval(CardCost($o->CardID)) >  intval(substr($constraint, 7))) return false;
        } elseif ($constraint !== '' && $constraint !== 'space' && $constraint !== 'ground'
            && !HasTrait($o->CardID, $constraint)) return false;
        return true;
    }));
    if (empty($units)) return;
    $handler = "CHAINED_ATTACK|{$bonus}";
    if ($mayDecline) {
        SWUQueueMayChooseTarget($player, $units, 'Attack_with_another_unit', 'Choose_another_unit_to_attack_with', $handler);
    } else {
        SWUQueueChooseTarget($player, $units, 'Attack_with_another_unit', $handler);
    }
}

// SEC_103 Mon Mothma — offer the next "you may attack with another unit (even if exhausted)". The loop
// var SWU_MONMOTHMA_LOOP holds the CSV of UIDs to exclude (Mon Mothma + every unit that already attacked
// this When Played). Offers a MAY-choose over the remaining OTHER friendly units in BOTH arenas,
// regardless of ready/exhausted status; an empty pool clears the loop var (the loop ends). Re-fired after
// each attack resolves (via the SWU_TRIGGER_RESUME stack-empty branch). Units can't attack bases here —
// MONMOTHMA_ATTACK calls BeginSWUAttack with noBases=true.
function _SWUMonMothmaOffer(int $player): void {
    global $playerID; $playerID = $player;
    $loop = GetSWUVar('SWU_MONMOTHMA_LOOP', '');
    if ($loop === '') return;
    $excl = array_values(array_filter(explode(',', $loop), fn($x) => $x !== ''));
    $units = [];
    foreach (['myGroundArena', 'mySpaceArena'] as $zone) {
        $arr = GetZone($zone);
        for ($i = 0; $i < count($arr); $i++) {
            $u = $arr[$i];
            if (SWUObjGone($u)) continue;
            if (in_array(strval(intval($u->UniqueID ?? 0)), $excl, true)) continue;
            $units[] = "{$zone}-{$i}";
        }
    }
    if (empty($units)) { SetSWUVar('SWU_MONMOTHMA_LOOP', ''); return; }   // no more eligible units → stop
    SWUQueueMayChooseTarget($player, $units, 'Attack_with_another_unit_even_if_exhausted',
        'Choose_a_unit_to_attack_with', 'MONMOTHMA_ATTACK');
}

// HMW_009 Chewbacca (Relentless Rebel), BOTH sides — "Attack with a unit, even if it's exhausted. It
// can't attack bases for this attack." Every friendly unit in either arena is a candidate REGARDLESS of
// ready/exhausted status (that is the whole point of the card), minus the hard "can't attack" cases. A
// unit with no valid NON-BASE target is excluded: the base is not a legal target here, so picking it
// could accomplish nothing. An empty list means the ability fizzles.
function _SWUHmw009Attackers(int $player): array {
    global $playerID; $playerID = $player;
    $units = [];
    foreach (['myGroundArena' => 'GroundArena', 'mySpaceArena' => 'SpaceArena'] as $zone => $arena) {
        $arr = GetZone($zone);
        for ($i = 0; $i < count($arr); $i++) {
            $u = $arr[$i];
            if (SWUObjGone($u)) continue;
            if (_SWUUnitHardCantAttack($u)) continue;
            // LOF_063 Oggdo Bogdo — "can't attack unless it's damaged."
            if (($u->CardID ?? '') === 'LOF_063' && intval($u->Damage ?? 0) <= 0 && !LostAbilities($u)) continue;
            if (empty(SWUGetAllValidAttackTargets($player, $u, $arena, true))) continue; // noBases
            $units[] = "{$zone}-{$i}";
        }
    }
    return $units;
}

// SHD_145 Headhunting — "Attack with up to 3 units (one at a time). They can't attack bases for these
// attacks. Each Bounty Hunter that attacks this way gets +2/+0 for its attack." Count-capped attack loop
// (SWU_SHD145_LOOP = comma-CSV "{remaining},{uid1},{uid2},…" — NOT pipe: SWUVar values are pipe-delimited
// internally): offers a MAY-choose over ready friendly units that have a valid NON-BASE target and haven't
// attacked this way. Re-fired after each attack via the SWU_TRIGGER_RESUME stack-empty branch; a decline /
// count 0 / empty pool clears the loop var (it ends).
function _SWUShd145Offer(int $player): void {
    global $playerID; $playerID = $player;
    $loop = GetSWUVar('SWU_SHD145_LOOP', '');
    if ($loop === '') return;
    $lp = explode(',', $loop);
    if (intval($lp[0] ?? 0) <= 0) { SetSWUVar('SWU_SHD145_LOOP', ''); return; }
    $excl = array_values(array_filter(array_slice($lp, 1), fn($x) => $x !== ''));
    $units = [];
    foreach (['myGroundArena', 'mySpaceArena'] as $zone) {
        $arr = GetZone($zone);
        for ($i = 0; $i < count($arr); $i++) {
            $u = $arr[$i];
            if (SWUObjGone($u) || intval($u->Status) !== 1) continue;   // ready (a unit attacks once)
            if (in_array(strval(intval($u->UniqueID ?? 0)), $excl, true)) continue;
            if (empty(SWUGetAllValidAttackTargets($player, $u, $u->Location ?? '', true))) continue; // noBases: needs a unit target (union all opponents)
            $units[] = "{$zone}-{$i}";
        }
    }
    if (empty($units)) { SetSWUVar('SWU_SHD145_LOOP', ''); return; }
    SWUQueueMayChooseTarget($player, $units, 'Attack_with_a_unit_(up_to_3,_no_bases)?',
        'Choose_a_unit_to_attack_with', 'SHD145_ATTACK');
}

// TS26_59 Brothers — count-capped loop (SWU_TS26059_LOOP = comma-CSV "{remaining},{uid1},{uid2}"): offers a
// MAY-choose over ready UNIQUE friendly units that have a valid attack target (bases allowed) and haven't
// attacked this way. Re-fired after each attack via the SWU_TRIGGER_RESUME stack-empty branch.
function _SWUTs26059Offer(int $player): void {
    global $playerID; $playerID = $player;
    $loop = GetSWUVar('SWU_TS26059_LOOP', '');
    if ($loop === '') return;
    $lp = explode(',', $loop);
    if (intval($lp[0] ?? 0) <= 0) { SetSWUVar('SWU_TS26059_LOOP', ''); return; }
    $excl = array_values(array_filter(array_slice($lp, 1), fn($x) => $x !== ''));
    $units = [];
    foreach (['myGroundArena', 'mySpaceArena'] as $zone) {
        $arr = GetZone($zone);
        for ($i = 0; $i < count($arr); $i++) {
            $u = $arr[$i];
            if (SWUObjGone($u) || intval($u->Status) !== 1) continue;   // ready
            if (!CardUnique($u->CardID ?? '')) continue;                                     // unique only
            if (in_array(strval(intval($u->UniqueID ?? 0)), $excl, true)) continue;
            if (empty(SWUGetValidAttackTargets(OtherPlayer($player), $u, $u->Location ?? '', false))) continue; // bases allowed
            $units[] = "{$zone}-{$i}";
        }
    }
    if (empty($units)) { SetSWUVar('SWU_TS26059_LOOP', ''); return; }
    SWUQueueMayChooseTarget($player, $units, 'Attack_with_a_unique_unit_(up_to_2)?',
        'Choose_a_unique_unit_to_attack_with', 'TS26059_ATTACK');
}

// Field-presence "other friendly {trait} units get +1/+1" buff. Returns +1 (to
// either stat) for each OTHER unit the controller has with CardID $sourceCardID,
// when $obj itself has trait $trait. "Other" excludes $obj by UniqueID, so the
// commander never buffs itself and two commanders buff each other. (SOR_230
// General Veers / Imperial, SOR_242 General Dodonna / Rebel.)
// LAW_150 Fulcrum — the wearer grants "+2/+2 to each OTHER friendly Rebel unit." Returns the total
// +stat for $obj: +2 per OTHER friendly unit wearing LAW_150, but only if $obj is a Rebel (granted
// Rebel via _SWUUnitHasTrait counts too). Added to both ObjectCurrentPower and ObjectCurrentHP.
// Count the DISTINCT keywords on $obj (ASH_100 Gallius Rax "2 or more different keywords").
function _SWUCountDistinctKeywords($obj): int {
    if ($obj === null) return 0;
    $n = 0;
    foreach (['Sentinel', 'Ambush', 'Overwhelm', 'Grit', 'Saboteur', 'Shielded', 'Bounty', 'Hidden', 'Smuggle', 'Plot', 'Piloting', 'Support'] as $kw) {
        $fn = "HasKeyword_{$kw}";
        if (function_exists($fn) && $fn($obj)) $n++;
    }
    foreach (['Raid', 'Restore', 'Exploit'] as $vkw) {
        $fn = "GetKeyword_{$vkw}_Value";
        if (function_exists($fn)) { $v = $fn($obj); if ($v !== null && intval($v) > 0) $n++; }
    }
    return $n;
}

// ASH_100 Gallius Rax — "Other friendly units with 2+ different keywords get +2/+2." +2 for $obj if its
// controller controls another Gallius Rax and $obj has ≥2 distinct keywords.
function _SWUAsh100Bonus($obj): int {
    if ($obj === null) return 0;
    $ctrl = intval($obj->Controller ?? 0);
    if ($ctrl <= 0) return 0;
    $selfUid = intval($obj->UniqueID ?? 0);
    $hasOther = false;
    foreach (GetUnitsInPlay($ctrl) as $u) {
        if (empty($u->removed) && ($u->CardID ?? '') === 'ASH_100' && intval($u->UniqueID ?? 0) !== $selfUid) { $hasOther = true; break; }
    }
    if (!$hasOther) return 0;
    return _SWUCountDistinctKeywords($obj) >= 2 ? 2 : 0;
}

// SHD_008 Boba Fett (deployed Leader Unit) — "Each OTHER friendly unit that has 1 or more keywords gets
// +1/+0." +1 power for $obj if its controller controls another SHD_008 in play and $obj has ≥1 keyword.
// (Power only — no HP call. Inactive while SHD_008 is undeployed: it isn't a unit in play then.)
function _SWUShd008Bonus($obj): int {
    if ($obj === null) return 0;
    $ctrl = intval($obj->Controller ?? 0);
    if ($ctrl <= 0) return 0;
    $selfUid = intval($obj->UniqueID ?? 0);
    $hasOther = false;
    foreach (GetUnitsInPlay($ctrl) as $u) {
        if (empty($u->removed) && ($u->CardID ?? '') === 'SHD_008' && intval($u->UniqueID ?? 0) !== $selfUid) { $hasOther = true; break; }
    }
    if (!$hasOther) return 0;
    return _SWUCountDistinctKeywords($obj) >= 1 ? 1 : 0;
}

function _SWULaw150Bonus($obj): int {
    $controller = intval($obj->Controller ?? $obj->Owner ?? 0);
    if ($controller <= 0) return 0;
    if (!TraitContains($obj, 'Rebel')) return 0;
    $n = 0;
    foreach (GetUnitsInPlay($controller) as $fu) {
        if (empty($fu->removed) && !LostAbilities($fu)
            && intval($fu->UniqueID ?? -1) !== intval($obj->UniqueID ?? -2)
            && _SWUUnitHasUpgrade($fu, 'LAW_150')) $n++;
    }
    return 2 * $n;
}

function SWUTraitCommanderBonus($obj, string $sourceCardID, string $trait): int {
    $controller = intval($obj->Controller ?? $obj->Owner ?? 0);
    if ($controller <= 0) return 0;
    if (!HasTrait($obj->CardID, $trait)) return 0;
    $bonus = 0;
    foreach (array_merge(GetGroundArena($controller) ?? [], GetSpaceArena($controller) ?? []) as $u) {
        if (!empty($u->removed)) continue;
        if (($u->CardID ?? '') !== $sourceCardID) continue;
        if (intval($u->UniqueID ?? -1) === intval($obj->UniqueID ?? -2)) continue; // not self
        if (LostAbilities($u)) continue; // a source that lost its abilities no longer grants the bonus
        $bonus += 1;
    }
    return $bonus;
}

// TWI_114 Clone Commander Cody — "Coordinate - Each OTHER friendly unit gets +1/+1 and gains
// Overwhelm." The +1/+1 half: +1 per OTHER in-play Cody the unit's controller has, while that
// controller's Coordinate is active. (Overwhelm grant is in HasConditionalKeyword_Overwhelm.)
function _SWUTwi114Bonus($obj): int {
    $controller = intval($obj->Controller ?? $obj->Owner ?? 0);
    if ($controller <= 0 || !IsCoordinateActive($controller)) return 0;
    $bonus = 0;
    foreach (array_merge(GetGroundArena($controller) ?? [], GetSpaceArena($controller) ?? []) as $u) {
        if (!empty($u->removed)) continue;
        if (($u->CardID ?? '') !== 'TWI_114') continue;
        if (intval($u->UniqueID ?? -1) === intval($obj->UniqueID ?? -2)) continue; // "each OTHER"
        if (LostAbilities($u)) continue;
        $bonus += 1;
    }
    return $bonus;
}

// LOF_237 The Son — "While the Force is with you, each friendly unit gets +2/+0." Power-only field
// passive; gated on the controller currently controlling their Force token. Applies to EVERY friendly
// unit including The Son itself (so, unlike SWUTraitCommanderBonus, no self-exclusion). Stacks per copy.
function _SWUTheSonBonus($obj): int {
    $controller = intval($obj->Controller ?? $obj->Owner ?? 0);
    if ($controller <= 0) return 0;
    if (!PlayerHasTheForce($controller)) return 0;
    $bonus = 0;
    foreach (array_merge(GetGroundArena($controller) ?? [], GetSpaceArena($controller) ?? []) as $u) {
        if (!empty($u->removed)) continue;
        if (($u->CardID ?? '') !== 'LOF_237') continue;
        if (LostAbilities($u)) continue; // a Son that lost its abilities stops granting
        $bonus += 2;
    }
    return $bonus;
}

// LOF_191 BD-1 — "Choose another friendly unit. While this unit is in play, the chosen unit gets +1/+0 and
// gains Saboteur." True if $obj is the chosen target of any LOF_191 still in play (the link is the global
// effect SWU_LOF191_{sourceUID}_{targetUID}; once BD-1 leaves play the loop finds no source, ending the buff).
function _SWULof191HasBuff($obj): bool {
    if ($obj === null) return false;
    $player = intval($obj->Controller ?? $obj->Owner ?? 0);
    if ($player <= 0) return false;
    $tgtUID = intval($obj->UniqueID ?? -1);
    foreach (array_merge(GetGroundArena($player) ?? [], GetSpaceArena($player) ?? []) as $u) {
        if (!empty($u->removed) || ($u->CardID ?? '') !== 'LOF_191' || LostAbilities($u)) continue;
        if (GlobalEffectCount($player, 'SWU_LOF191_' . intval($u->UniqueID ?? -1) . '_' . $tgtUID) > 0) return true;
    }
    return false;
}

// TWI_110 Huyang — "When Played: Choose another friendly unit. While this unit is in play, the chosen
// unit gets +2/+2." Mirror of _SWULof191HasBuff (link SWU_TWI110_{sourceUID}_{targetUID}; auto-ends when
// Huyang leaves play).
function _SWUTwi110HasBuff($obj): bool {
    return _SWUTwi110BuffCount($obj) > 0;
}
// Count the number of stacked "+2/+2 while Huyang is in play" instances on $obj — each is a separate
// continuous effect (CR), so they STACK. A Huyang played twice on the same target (Qui-Gon's Aethersprite
// LOF_197 repeating Huyang's When-Played) leaves the SWU_TWI110_{src}_{tgt} key at count 2 → +4/+4; two
// different Huyang sources each add their own key. The power/HP getters add 2× this count.
function _SWUTwi110BuffCount($obj): int {
    if ($obj === null) return 0;
    $player = intval($obj->Controller ?? $obj->Owner ?? 0);
    if ($player <= 0) return 0;
    $tgtUID = intval($obj->UniqueID ?? -1);
    $count = 0;
    // ⚠ Do NOT filter the source scan to CardID === 'TWI_110'. The grant is keyed by the SOURCE UID, and
    // the source is not always a Huyang: TS26_34 Fives enters play "with the When Played abilities of
    // another unit", so a copied Huyang writes SWU_TWI110_{FIVES_uid}_{tgt}. A CardID-filtered reader
    // never scanned Fives' UID, so the copied buff was recorded but permanently invisible — the target
    // never got +2/+2. The flag is self-authenticating (only TWI_110#0, or a copy of it, ever writes this
    // key), so scanning every friendly in-play unit by UID is both correct and sufficient — and it gives
    // "while THIS unit is in play" the right semantics for the copy: the buff ends when FIVES leaves.
    foreach (array_merge(GetGroundArena($player) ?? [], GetSpaceArena($player) ?? []) as $u) {
        if (!empty($u->removed)) continue;
        $count += GlobalEffectCount($player, 'SWU_TWI110_' . intval($u->UniqueID ?? -1) . '_' . $tgtUID);
    }
    return $count;
}

// True if $player controls a Force unit OR a Force upgrade (on any of their units). (LOF_060.)
function _SWUControlsForceUnitOrUpgrade(int $player): bool {
    foreach (GetUnitsInPlay($player) as $u) {
        if (!empty($u->removed)) continue;
        if (TraitContains($u, 'Force')) return true;
        foreach (GetUpgradesOnUnit($u) as $up) {
            if (TraitContains($up, 'Force')) return true;
        }
    }
    return false;
}

// True if $player controls a LEADER UNIT — derived from the LIVE arenas via IsLeaderUnit, never from
// the leader zone's Deployed flag. The flag lies in both directions: Poe Dameron JTL_013's flip-and-
// attach sets Deployed=true while his host is explicitly NOT a leader unit (his attach text lacks
// "attached unit is a leader unit"), and a Darksaber ASH_135 host IS a leader unit with no zone flag
// at all. The arena scan also covers deployed leaders and leader-pilot hosts (Kazuda), and gets the
// TWI_017 "Flipatine" exclusion for free (its flip creates no arena unit).
function SWUControlsLeaderUnit(int $player): bool {
    global $playerID;
    $saved = $playerID;
    $playerID = intval($player);
    $found = false;
    foreach (['myGroundArena', 'mySpaceArena'] as $z) {
        foreach (ZoneSearch($z, AnyUnitFilter) as $mz) {
            $o = GetZoneObject($mz);
            if (!SWUObjGone($o) && IsLeaderUnit($o)) { $found = true; break 2; }
        }
    }
    $playerID = $saved;
    return $found;
}

// True if $player has the specific leader $cardID deployed (its leader-unit side in play).
// Used for deployed-leader passives (e.g. SOR_018 Jyn Erso's defender debuff).
function _SWULeaderDeployed(int $player, string $cardID): bool {
    foreach (GetLeader($player) as $l) {
        if (!empty($l->removed)) continue;
        if (($l->CardID ?? '') === $cardID && !empty($l->Deployed)) return true;
    }
    return false;
}

// Number of SHD_037 (Supreme Leader Snoke) controlled by $obj's opponent.
// Only non-leader units are affected by Snoke's passive; leaders/leader units return 0.
function SWUEnemySnokeCount($obj): int {
    if (IsLeaderUnit($obj)) return 0;
    $controller = intval($obj->Controller ?? $obj->Owner ?? 0);
    if ($controller <= 0) return 0;
    $opp = GetOpponent($controller);
    $count = 0;
    foreach (array_merge(GetGroundArena($opp) ?? [], GetSpaceArena($opp) ?? []) as $u) {
        if (!empty($u->removed)) continue;
        if (($u->CardID ?? '') === 'SHD_037' && !LostAbilities($u)) $count++;
    }
    return $count;
}

// Apply a "for this phase" shrink (–$power/–$hp) to the unit at $mzID, then run a
// state-based defeat check: a shrink lowers HP directly (it is NOT damage, so shields
// do not prevent it), and a unit reduced to 0 remaining HP is defeated.
// Caller must have $playerID set so the relative $mzID resolves to the right arena.
// $deferDefeatCheck: when applying a defeating debuff to MULTIPLE units in a loop, pass true so the
// per-unit state-based defeat check is skipped — a mid-loop defeat removes its unit and shifts the other
// units' mzIDs, which would leave later units in the loop undebuffed (and any defeat/heal reaction would
// interrupt the resolution). The caller runs SWUCheckShrinkDefeats() ONCE after applying to every unit,
// matching the rules (all "give each enemy -X/-X" reductions apply simultaneously, then defeats resolve).
function SWUApplyPhaseDebuff(string $mzID, int $power, int $hp, string $source = '', bool $deferDefeatCheck = false): void {
    global $turnEffectRegistry;
    // "{source}-{power}-{hp}" (registry kind STAT_DEBUFF, phase). CardID base for provenance when
    // registered; synthetic 'SWUDEBUFF' fallback otherwise. params are amounts to SUBTRACT.
    $base = ($source !== '' && isset($turnEffectRegistry[$source])) ? $source : 'SWUDEBUFF';
    AddTurnEffect($mzID, _SWUStackingStatToken($mzID, "{$base}-{$power}-{$hp}"));
    if (!$deferDefeatCheck) SWUCheckShrinkDefeats();
}

// SOR_004 Chirrut Îmwe (deployed): "During the action phase, this unit isn't defeated by having
// no remaining HP. (During the regroup phase, if he has no remaining HP, defeat him.)" So the
// deployed Chirrut leader unit is immune to HP-defeat in EVERY phase except the regroup phase —
// the RegroupPhaseStart sweep (SWUCheckShrinkDefeats, which runs while GetCurrentPhase()==='RGS')
// then defeats him if his damage still meets/exceeds his HP. This is HP-defeat only; an effect
// that defeats him directly ("defeat target unit") is unaffected.
function SWUImmuneToHpDefeat($obj): bool {
    if ($obj === null) return false;
    $cid = $obj->CardID ?? '';
    // SOR_004 Chirrut: not defeated by no remaining HP while it's not the regroup phase.
    if ($cid === 'SOR_004' && IsLeaderUnit($obj)) return GetCurrentPhase() !== 'RGS';
    // SEC_012 Cassian Andor (deployed): "While you have the initiative, this unit isn't defeated by
    // having no remaining HP." Innate leader-unit ability, so it's lost if the unit loses all abilities
    // (Intended: he is immediately defeated if an effect causes him to lose all abilities.)
    if ($cid === 'SEC_012' && IsLeaderUnit($obj) && !LostAbilities($obj)
            && _SWUHasInitiative(intval($obj->Controller ?? 0))) return true;
    // LOF_043 The Tragedy of Plagueis — a chosen unit "can't be defeated by having no remaining HP" for
    // this phase (NO_HP_DEFEAT turn-effect marker; expires at RegroupPhaseStart).
    if (is_array($obj->TurnEffects ?? null) && in_array('NO_HP_DEFEAT', $obj->TurnEffects, true)) return true;
    return false;
}

// LOF_220 — consume a one-shot "prevent 2 of the next damage" marker on $obj (if present) and return the
// reduced amount. Called at every damage instance (combat + effect) so whichever lands first consumes it.
// $peek=true computes the post-prevention amount WITHOUT consuming any one-shot marker (LOF_220's
// PREVENT_DMG_2) or spending SEC_067's once-per-phase — used to decide shield-vs-reduction ordering.
function _SWUApplyDamagePrevention($obj, int $amount, bool $peek = false, ?string $sourceMzID = null): int {
    if ($obj === null || $amount <= 0) return $amount;
    // LOF_220 one-shot "prevent 2 of the next damage" marker (combat or effect).
    if (is_array($obj->TurnEffects ?? null)) {
        $idx = array_search('PREVENT_DMG_2', $obj->TurnEffects, true);
        if ($idx !== false) { if (!$peek) array_splice($obj->TurnEffects, $idx, 1); $amount = max(0, $amount - 2); }
    }
    if ($amount <= 0) return 0;
    // JTL_193 I Have You Now — "prevent all damage that would be dealt to this unit this attack" (ANY source).
    // Combat damage to the attacker is also short-circuited inline in CombatLogic; routing it here too covers
    // triggered redirects (e.g. Tarfful) that deal ABILITY damage back to the protected attacker during the
    // attack. (TWI_096/TS26_59 are COMBAT-only preventions → they stay inline in CombatLogic, not here.)
    if (is_array($obj->TurnEffects ?? null)) {
        foreach ($obj->TurnEffects as $te) {
            if (SWUParseTurnEffect((string)$te)['base'] === 'JTL_193') return 0;
        }
    }
    $ctrl = intval($obj->Controller ?? 0);
    $uid  = intval($obj->UniqueID ?? 0);
    // SEC_067 Umbaran Mobile Cannon — "the first time this unit would take damage each phase, prevent
    // that damage." Per-unit per-phase flag; cleared at RegroupPhaseStart.
    if (($obj->CardID ?? '') === 'SEC_067' && $ctrl > 0
            && GlobalEffectCount($ctrl, 'SWU_SEC067_USED_' . $uid) <= 0) {
        if (!$peek) AddGlobalEffects($ctrl, 'SWU_SEC067_USED_' . $uid);
        return 0;
    }
    // SEC_050 Vigil — "If damage would be dealt to ANOTHER friendly unit, prevent 1 of that damage."
    // (Vigil's own INCREASE half is a replacement effect and is applied further down, after every
    // prevention, so that damage already reduced to zero is never increased back up.)
    if (($obj->CardID ?? '') !== 'SEC_050' && $ctrl > 0) {
        foreach (GetUnitsInPlay($ctrl) as $u) {
            if (empty($u->removed) && ($u->CardID ?? '') === 'SEC_050' && intval($u->UniqueID ?? 0) !== $uid) {
                $amount = max(0, $amount - 1); break;
            }
        }
    }
    // SHD_224 Boba Fett's Armor — "If attached unit is Boba Fett and damage would be dealt to him,
    // prevent 2 of that damage." Continuous while attached; applies to every damage instance.
    if ($amount > 0 && SWUObjectTitle($obj) === 'Boba Fett' && _SWUUnitHasUpgrade($obj, 'SHD_224')) {
        $amount = max(0, $amount - 2);
    }
    // TWI_053 Finn — "For this phase, if damage would be dealt to that unit, prevent 1 of that damage."
    // Continuous phase-duration marker on the chosen unit; reduces EVERY incoming damage instance by 1.
    if ($amount > 0 && is_array($obj->TurnEffects ?? null) && in_array('TWI_053', $obj->TurnEffects, true)) {
        $amount = max(0, $amount - 1);
    }
    // SEC_050 Vigil — "If damage would be dealt to THIS unit BY ANOTHER CARD, deal that much plus 1
    // instead." Two gates, both load-bearing:
    //   • $amount > 0 — it is a replacement for damage that WOULD BE DEALT, so once preventions have
    //     reduced the instance to zero there is nothing left to replace and no +1 applies.
    //   • the source must be ANOTHER card — an ability of Vigil's own, including one granted to it by an
    //     attached upgrade (JTL_046 Paige Tico's "deal 1 damage to it"), is not another card.
    if ($amount > 0 && ($obj->CardID ?? '') === 'SEC_050') {
        $src     = ($sourceMzID !== null && $sourceMzID !== '') ? GetZoneObject($sourceMzID) : null;
        $srcSelf = ($src !== null && $uid > 0 && intval($src->UniqueID ?? 0) === $uid);
        if (!$srcSelf) $amount += 1;
    }
    // ASH_150 Deadly Vulnerability — "If attached unit would take damage, it takes twice as much instead."
    // Applied last (after prevention) so it doubles the net damage. Covers combat AND ability paths (both
    // route through this function).
    if ($amount > 0 && _SWUUnitHasUpgrade($obj, 'ASH_150')) $amount *= 2;
    return $amount;
}

// True if $player currently holds the initiative. GetInitiativeCounter() returns 'P1_CLAIMED'/'P2_…'.
function _SWUHasInitiative(int $player): bool {
    return strpos((string)GetInitiativeCounter(), 'P' . $player) === 0;
}

// True if $obj bears at least one non-captive, non-removed upgrade subcard ("upgraded unit").
function _SWUIsUpgraded($obj): bool {
    if ($obj === null || !is_array($obj->Subcards ?? null)) return false;
    foreach ($obj->Subcards as $sub) {
        $isCap = is_array($sub) ? !empty($sub['IsCaptive']) : !empty($sub->IsCaptive);
        $isRem = is_array($sub) ? !empty($sub['removed'])   : !empty($sub->removed);
        if (!$isCap && !$isRem) return true;
    }
    return false;
}

// ── "Can't be X by enemy card abilities" immunity helpers ──────────────────────────────────────────
// Each returns true if $obj currently has the relevant immunity, via: its own CardID, a granted
// attached upgrade, or a controller field-passive. CALL SITES apply these only for ENEMY-sourced
// ability actions (actor ≠ the unit's controller/owner) — these immunities never restrict the
// controller's own abilities, combat, or state-based "no remaining HP" defeat (see SWUImmuneToHpDefeat).
// ⚠ These immunities are ABILITIES of the unit (innate, or gained from an attached upgrade), so a unit
// that has LOST ALL ABILITIES (SOR_138 Force Lightning, SHD_072, etc. — see LostAbilities()) no longer
// has them. Gate the self/attached-grant sources on !LostAbilities. A FIELD-PASSIVE granted by ANOTHER
// card's constant ability (LOF_073 Mythosaur) is NOT the unit's own ability, so losing the unit's
// abilities does not remove it — those checks stay OUTSIDE the gate.
function SWUAvoidsDefeat($obj): bool {
    if ($obj === null) return false;
    if (LostAbilities($obj)) return false;
    $cid = $obj->CardID ?? '';
    if ($cid === 'SHD_187' || $cid === 'JTL_103' || $cid === 'LAW_149') return true;        // self
    // SEC_012 Cassian Andor (deployed): "While you have the initiative, this unit can't be defeated by
    // enemy card abilities." (LostAbilities gated above.)
    if ($cid === 'SEC_012' && IsLeaderUnit($obj) && _SWUHasInitiative(intval($obj->Controller ?? 0))) return true;
    if (_SWUUnitHasUpgrade($obj, 'TWI_220')) return true;  // Shadowed Intentions (attached grant)
    if (_SWUUnitHasUpgrade($obj, 'JTL_103')) return true;  // Chewbacca as a Pilot (attached grant)
    return false;
}
function SWUAvoidsBounce($obj): bool {
    if ($obj === null) return false;
    if (!LostAbilities($obj)) {
        $cid = $obj->CardID ?? '';
        if ($cid === 'JTL_103') return true;                                                 // self
        if (_SWUUnitHasUpgrade($obj, 'TWI_220')) return true;  // Shadowed Intentions
        if (_SWUUnitHasUpgrade($obj, 'JTL_103')) return true;  // Chewbacca as a Pilot
    }
    // LOF_073 Mythosaur: friendly UPGRADED units can't be returned to hand by enemy abilities.
    // External field-passive — survives the unit losing its OWN abilities.
    if (_SWUIsUpgraded($obj) && _SWUCountUnitsWithCardID(intval($obj->Controller ?? 0), 'LOF_073') > 0) return true;
    return false;
}
function SWUAvoidsCapture($obj): bool {
    if ($obj === null) return false;
    if (LostAbilities($obj)) return false;
    if (($obj->CardID ?? '') === 'SHD_187') return true;                                     // self
    if (_SWUUnitHasUpgrade($obj, 'TWI_220')) return true;  // Shadowed Intentions
    return false;
}
function SWUAvoidsAbilityDamage($obj): bool {
    if ($obj === null) return false;
    if (LostAbilities($obj)) return false;
    return ($obj->CardID ?? '') === 'SHD_187';  // "can't be damaged by enemy card abilities"
}
function SWUAvoidsTakeControl($obj): bool {
    if ($obj === null) return false;
    if (LostAbilities($obj)) return false;
    return ($obj->CardID ?? '') === 'LAW_149';  // "Opponents can't take control of this unit."
}
function SWUAvoidsExhaust($obj): bool {
    if ($obj === null) return false;
    // LOF_040 Kylo Ren's Lightsaber: attached FORCE unit can't be exhausted by enemy abilities.
    // A gained ability of the host → removed if the host has lost all abilities.
    if (!LostAbilities($obj) && _SWUUnitHasUpgrade($obj, 'LOF_040') && TraitContains($obj, 'Force')) return true;
    // LOF_073 Mythosaur: friendly UPGRADED units can't be exhausted by enemy abilities.
    // External field-passive — survives the unit losing its OWN abilities.
    if (_SWUIsUpgraded($obj) && _SWUCountUnitsWithCardID(intval($obj->Controller ?? 0), 'LOF_073') > 0) return true;
    return false;
}

// State-based defeat sweep: any unit whose effective HP (after shrinks/Snoke) minus
// its damage is 0 or less is defeated. Re-scans after each defeat because removing a
// unit shifts indices and can change other units' stats (e.g. a defeated Snoke).
function SWUCheckShrinkDefeats(): void {
    global $playerID;
    $saved = $playerID;
    $guard = 0;
    do {
        $defeated = false;
        for ($p = 1; $p <= 2 && !$defeated; $p++) {
            $playerID = $p;
            foreach (['myGroundArena', 'mySpaceArena'] as $zone) {
                foreach (ZoneSearch($zone, AnyUnitFilter) as $mz) {
                    $obj = GetZoneObject($mz);
                    if (SWUObjGone($obj)) continue;
                    if (ObjectCurrentHP($obj) - intval($obj->Damage ?? 0) <= 0 && !SWUImmuneToHpDefeat($obj)) {
                        SWUDefeatUnit($p, $mz);
                        $defeated = true;
                        break 2;
                    }
                }
            }
        }
        $guard++;
    } while ($defeated && $guard < 100);
    $playerID = $saved;
    DecisionQueueController::CleanupRemovedCards();
}

// GA initiative helper (note: intentional typo from GA codebase).
// Returns true if the given player holds the initiative counter this round.
function PlayerHasIniative($player) {
    $ic = GetInitiativeCounter();
    return ($ic === "P{$player}_UNCLAIMED" || $ic === "P{$player}_CLAIMED");
}

// Returns the flat array of aspect icons provided by a player's leader + base.
// Each icon appears once per source card that provides it (e.g. two Aggression
// sources → ['Aggression', 'Aggression']). Empty/null aspect entries are ignored.
function PlayerAspects($player): array {
    $aspects = [];
    foreach ([GetLeader($player) ?? [], GetBase($player) ?? []] as $zone) {
        for ($i = 0; $i < count($zone); $i++) {
            if (isset($zone[$i]->removed) && $zone[$i]->removed) continue;
            // TWI_017 Chancellor Palpatine "Flipatine" — the printed card lists all three aspects
            // (Cunning,Villainy,Heroism), but each FACE provides only two: Cunning + Heroism on the
            // Heroism (undeployed) face, Cunning + Villainy on the flipped Villainy (Deployed) face.
            if (($zone[$i]->CardID ?? '') === 'TWI_017') {
                $aspects[] = 'Cunning';
                $aspects[] = empty($zone[$i]->Deployed) ? 'Heroism' : 'Villainy';
                continue;
            }
            $raw = CardAspect($zone[$i]->CardID);
            if ($raw === null || $raw === '') continue;
            foreach (explode(',', $raw) as $a) {
                $a = trim($a);
                if ($a !== '') $aspects[] = $a;
            }
        }
    }
    // ASH_135 The Darksaber — "While you are paying costs, the attached unit provides its aspect icons."
    // Add each Darksaber-wearing unit's printed aspects to the player's available cost-payment icons. A
    // DEPLOYED LEADER host is skipped: its aspects are already contributed once by the GetLeader() loop above,
    // so re-adding them here would double-count the leader's own aspects (CR — the Darksaber provides the
    // attached unit's icons, and a leader unit's icons are its leader card's, already counted).
    $ldrDeployedUID = -1;
    foreach (GetLeader($player) ?? [] as $l) {
        if (!empty($l->Deployed)) { $ldrDeployedUID = intval($l->DeployedUniqueID ?? -1); break; }
    }
    foreach (GetUnitsInPlay($player) as $u) {
        if (empty($u->removed) && _SWUUnitHasUpgrade($u, 'ASH_135')) {
            if ($ldrDeployedUID >= 0 && intval($u->UniqueID ?? -2) === $ldrDeployedUID) continue;   // leader host → already counted
            $raw = CardAspect($u->CardID ?? '');
            if ($raw) foreach (explode(',', $raw) as $a) { $a = trim($a); if ($a !== '') $aspects[] = $a; }
        }
    }
    return $aspects;
}

// True if $player controls a non-removed unit (either arena, incl. leader units) whose printed
// aspects include $aspect. Used by JTL_250 Sabine's Masterpiece (per-aspect On-Attack effects).
function _SWUControlsUnitWithAspect(int $player, string $aspect): bool {
    foreach (array_merge(GetGroundArena($player) ?? [], GetSpaceArena($player) ?? []) as $u) {
        if (!empty($u->removed)) continue;
        $raw = CardAspect($u->CardID ?? '');
        if ($raw === null || $raw === '') continue;
        foreach (explode(',', $raw) as $a) {
            if (trim($a) === $aspect) return true;
        }
    }
    return false;
}

// Returns the aspect penalty cost (in resources) for a player playing a card.
// CR 8.1: +2 per card aspect icon not covered by the player's leader + base.
// Matching is multiset: if card needs 2× Aggression, player needs 2× Aggression.
// SOR_008 Hera Syndulla — true while $player controls the Hera leader (deployed or not; the leader-zone
// entry persists either way). Her passive (both sides) ignores the aspect penalty on Spectre cards.
function _SWUControlsHera(int $player): bool {
    foreach (GetLeader($player) as $l) {
        if ($l !== null && empty($l->removed) && ($l->CardID ?? '') === 'SOR_008') return true;
    }
    return false;
}
// HMW_004 Grand Moff Tarkin — the aspect waiver is printed on BOTH faces ("Ignore the aspect penalties on
// upgrades with Fortify you play"), so the player has it while HMW_004 is their leader, deployed or not
// (the leader-zone entry persists either way). Same shape as _SWUControlsHera / _SWUControlsMonMothma.
function _SWUControlsTarkinHmw004(int $player): bool {
    foreach (GetLeader($player) as $l) {
        if ($l !== null && empty($l->removed) && ($l->CardID ?? '') === 'HMW_004') return true;
    }
    return false;
}
// SEC_009 Mon Mothma — both the leader front side and the deployed unit carry the same passive, so the
// player has it while SEC_009 is their leader (undeployed or deployed — the leader-zone entry persists).
function _SWUControlsMonMothma(int $player): bool {
    foreach (GetLeader($player) as $l) {
        if ($l !== null && empty($l->removed) && ($l->CardID ?? '') === 'SEC_009') return true;
    }
    return false;
}
// SEC_008 Bail Organa (deployed) — "When you play a card from your resources: Heal 1 damage from your
// base." Called after a Smuggle or Plot play; heals 1 per controlled SEC_008.
function _SWUSec008HealOnResourcePlay(int $player): void {
    $n = _SWUCountUnitsWithCardID($player, 'SEC_008');
    for ($i = 0; $i < $n; $i++) OnHealBase($player, $player, 1);
}
function SWUAspectPenalty($player, $cardID): int {
    $raw = CardAspect($cardID);
    if ($raw === null || $raw === '') return 0;

    // TWI_040 A Fine Addition — "play an upgrade ... ignoring its aspect penalty." A one-shot flag set
    // around the affordability check + the actual attach payment for the single upgrade being played this
    // way (both cost paths — SWUComputePlayCost and SWUComputePilotCost — route through here).
    if (!empty($GLOBALS['gTwi040IgnoreAspect'])) return 0;

    // SOR_008 Hera Syndulla: "Ignore the aspect penalty on SPECTRE cards you play." Single chokepoint,
    // so every play path (hand / discard / affordability glow) is covered.
    if (HasTrait($cardID, 'Spectre') && _SWUControlsHera(intval($player))) return 0;

    // IC27_078 Anakin Skywalker (Destined For Darkness): "While this unit is in your DISCARD PILE,
    // ignore the aspect penalties on cards you play named Darth Vader." Matched by TITLE (subtitle
    // excluded), and live only from the discard — not from play, hand or deck. Deploying a Darth Vader
    // LEADER is not "playing a card", but a deploy has no aspect penalty anyway so it never reaches here.
    if (CardTitle($cardID) === 'Darth Vader' && _SWUAnakinIC27078InDiscard(intval($player))) return 0;

    // TWI_001 Nala Se (both sides): "Ignore the aspect penalty on Clone units you play."
    if (stripos(CardType($cardID) ?? '', 'Unit') !== false && HasTrait($cardID, 'Clone')) {
        foreach (GetLeader(intval($player)) as $l) {
            if (empty($l->removed) && ($l->CardID ?? '') === 'TWI_001') return 0;
        }
    }

    // SEC_009 Mon Mothma: "Ignore the aspect penalties on non-Villainy Official units you play."
    if (stripos(CardType($cardID) ?? '', 'Unit') !== false && HasTrait($cardID, 'Official')
            && strpos($raw, 'Villainy') === false && _SWUControlsMonMothma(intval($player))) {
        return 0;
    }

    // HMW_004 Grand Moff Tarkin (both sides): "Ignore the aspect penalties on upgrades with Fortify you
    // play." Scoped to Fortify upgrades — a plain upgrade still pays its penalty.
    if (isset($GLOBALS['Fortify_Cards'][$cardID]) && _SWUControlsTarkinHmw004(intval($player))) return 0;

    // ASH_212 Peli Motto: "Ignore the aspect penalties of the first non-unit card you play each phase."
    // The waiver applies until SWU_ASH212_USED is set (locked in by ActivateCard on the first non-unit play).
    if (stripos(CardType($cardID) ?? '', 'Unit') === false
            && GlobalEffectCount(intval($player), 'SWU_ASH212_USED') <= 0
            && _SWUControlsCardInPlay(intval($player), 'ASH_212')) {
        return 0;
    }

    $cardAspects = array_filter(array_map('trim', explode(',', $raw)), fn($a) => $a !== '');
    if (empty($cardAspects)) return 0;

    // SHD_046 Rey: "While playing this unit, ignore her Heroism aspect penalty if you control Kylo Ren."
    // Drop one Heroism pip from the requirement so it's never penalized (the Vigilance pip still applies).
    if ($cardID === 'SHD_046' && _SWUControlsTitle(intval($player), ['Kylo Ren'])) {
        $hidx = array_search('Heroism', $cardAspects);
        if ($hidx !== false) unset($cardAspects[$hidx]);
        $cardAspects = array_values($cardAspects);
        if (empty($cardAspects)) return 0;
    }
    // SHD_141 Kylo Ren: "While playing this unit, ignore his Villainy aspect penalty if you control Rey."
    if ($cardID === 'SHD_141' && _SWUControlsTitle(intval($player), ['Rey'])) {
        $vidx = array_search('Villainy', $cardAspects);
        if ($vidx !== false) unset($cardAspects[$vidx]);
        $cardAspects = array_values($cardAspects);
        if (empty($cardAspects)) return 0;
    }

    // SHD_198 Clone Trooper: "Ignore the aspect penalty on the first Clone unit you play each round."
    // While the controller has an unused SHD_198 charge and this is a Clone unit, waive the whole penalty.
    // The charge is marked used in ActivateCard once the (already-waived) cost is locked; cleared at RGS.
    if (strpos(CardType($cardID) ?? '', 'Unit') !== false && HasTrait($cardID, 'Clone')
            && _SWUControlsCardInPlay(intval($player), 'SHD_198')
            && GlobalEffectCount(intval($player), 'SWU_SHD198_USED') <= 0) {
        return 0;
    }

    $provided = PlayerAspects($player);
    $penalty  = 0;
    foreach ($cardAspects as $need) {
        $idx = array_search($need, $provided);
        if ($idx !== false) {
            array_splice($provided, $idx, 1); // consume one matching icon
        } else {
            $penalty += 2;
        }
    }
    return $penalty;
}

// LAW common bases (LAW_020/021/022/024/025/027/028/030) Epic Action: "Play a card from your hand,
// ignoring 1 of its Vigilance, Command, Aggression, or Cunning aspect penalties." Returns the resource
// value waived: 2 if — after matching the player's provided aspects (same greedy match as
// SWUAspectPenalty) — at least one UNMATCHED pip is a battlefield aspect (the player ignores that one
// pip); 0 otherwise (no penalty, or the only unmatched pip is an alignment aspect the base can't waive).
// Callers cap at SWUAspectPenalty so it never over-discounts (e.g. a Hera/Mon-Mothma 0-penalty card).
function _SWUCommonBaseWaivePenalty(int $player, string $cardID): int {
    $raw = CardAspect($cardID);
    if ($raw === null || $raw === '') return 0;
    $cardAspects = array_filter(array_map('trim', explode(',', $raw)), fn($a) => $a !== '');
    if (empty($cardAspects)) return 0;
    $provided    = PlayerAspects($player);
    $battlefield = ['Vigilance', 'Command', 'Aggression', 'Cunning'];
    $unmatched   = [];
    foreach ($cardAspects as $need) {
        $idx = array_search($need, $provided);
        if ($idx !== false) array_splice($provided, $idx, 1);
        else $unmatched[] = $need;
    }
    foreach ($unmatched as $u) {
        if (in_array($u, $battlefield, true)) return 2; // waive exactly one battlefield pip
    }
    return 0;
}

// ── SWU play-cost: single source of truth (M9 conditional cost reduction) ─────
// Per-card play-cost modifiers register a delta closure here:
//   $playCostModifiers[$cardID] = fn($player, $subjectObj): int   (negative = cheaper)
// SWUComputePlayCost consults this registry plus any generated PlayCostModifier
// abilities, so the cost the UI shows (CanAffordActivationReserve) and the cost
// ActivateCard charges can never drift. To add a new cost-reducing card, add a
// closure here — do NOT hand-edit the cost math in ActivateCard/affordability.
$playCostModifiers = [];

// IC27_022 Moff Gideon (Cold Calling): costs 2 less if a FRIENDLY unit was defeated this phase.
// Mirror-image of SHD_182 below (which reads SWU_ENEMY_DEFEATED). Lives here, not in the per-card
// file, because $playCostModifiers is initialized just above — AFTER cards/_loader.php runs — so a
// registration from a per-card file would be wiped. Same reason LAW_179 / TS26_71 sit here.
$playCostModifiers["IC27_022"] = function($player, $subjectObj) {
    return GlobalEffectCount(intval($player), 'SWU_FRIENDLY_DEFEATED') > 0 ? -2 : 0;
};

// SHD_182 Bravado: costs 2 less if you've defeated an enemy unit this phase.
$playCostModifiers["SHD_182"] = function($player, $subjectObj) {
    return GlobalEffectCount($player, 'SWU_ENEMY_DEFEATED') > 0 ? -2 : 0;
};

// LAW_179 Fear and Dead Men: costs 1 less per card discarded from your hand this phase.
$playCostModifiers["LAW_179"] = function($player, $subjectObj) {
    return -GlobalEffectCount($player, 'SWU_DISCARDED_HAND');
};

// TWI_254 Volunteer Soldier: "If you control a Trooper unit, this unit costs 1 resource less to play."
$playCostModifiers["TWI_254"] = function($player, $subjectObj) {
    foreach (GetUnitsInPlay(intval($player)) as $u) {
        if (empty($u->removed) && TraitContains($u, 'Trooper')) return -1;
    }
    return 0;
};

// TWI_098 Republic Defense Carrier: "costs 1 less for each unit controlled by the opponent who controls
// the most units." Twin Suns: take the MAX unit count over all opponents (2-player → the single opponent).
$playCostModifiers["TWI_098"] = function($player, $subjectObj) {
    $max = 0;
    foreach (OpponentsOf(intval($player)) as $opp) {
        $n = 0;
        foreach (GetUnitsInPlay($opp) as $u) {
            if (empty($u->removed)) $n++;
        }
        if ($n > $max) $max = $n;
    }
    return -$max;
};

// TS26_14 Yoda: "If you control 7 or more resources, this unit costs 2 resources less to play."
$playCostModifiers["TS26_14"] = function($player, $subjectObj) {
    return SWUResourceCount(intval($player)) >= 7 ? -2 : 0;
};

// TS26_61 Encircle: "This event costs 1 resource less to play for each friendly unit."
$playCostModifiers["TS26_61"] = function($player, $subjectObj) {
    $n = 0;
    foreach (GetUnitsInPlay(intval($player)) as $u) { if (empty($u->removed)) $n++; }
    return -$n;
};

// TS26_36 Tribunal: "This unit costs 2 resources less to play for each other card you played this
// phase." SWU_CARDS_PLAYED counts cards played BEFORE this one — ActivateCard bumps it after the cost is
// computed precisely so this reads "each OTHER card" and matches the pre-play UI affordability check.
$playCostModifiers["TS26_36"] = function($player, $subjectObj) {
    return -2 * GlobalEffectCount(intval($player), 'SWU_CARDS_PLAYED');
};

// TS26_71 Take Action / TS26_60 Take Charge / TS26_47 Take Cover / TS26_83 Take Aim: "costs 1
// resource less to play for each friendly leader unit."
$playCostModifiers["TS26_71"] = $playCostModifiers["TS26_60"] = $playCostModifiers["TS26_47"]
    = $playCostModifiers["TS26_83"] = function($player, $subjectObj) {
    $n = 0;
    foreach (GetUnitsInPlay(intval($player)) as $u) { if (empty($u->removed) && IsLeaderUnit($u)) $n++; }
    return -$n;
};

// TWI_197 Republic Attack Pod: "If you control 3 or more units, this unit costs 1 resource less to play."
$playCostModifiers["TWI_197"] = function($player, $subjectObj) {
    $n = 0;
    foreach (GetUnitsInPlay(intval($player)) as $u) { if (empty($u->removed)) $n++; }
    return $n >= 3 ? -1 : 0;
};

// TWI_151 Resolute: "This unit costs 1 resource less to play for every 5 damage on your base."
$playCostModifiers["TWI_151"] = function($player, $subjectObj) {
    $b = GetBase(intval($player));
    if (empty($b) || !isset($b[0])) return 0;
    return -intdiv(intval($b[0]->Damage ?? 0), 5);
};

// TWI_051 For The Republic: "If you control 3 or more Republic units, this upgrade costs 2 resources less."
$playCostModifiers["TWI_051"] = function($player, $subjectObj) {
    $n = 0;
    foreach (GetUnitsInPlay(intval($player)) as $u) {
        if (empty($u->removed) && TraitContains($u, 'Republic')) $n++;
    }
    return $n >= 3 ? -2 : 0;
};

// ASH_104 Dathomiri Magicks: "If you control a Force unit, this event costs 1 resource less to play."
$playCostModifiers["ASH_104"] = function($player, $subjectObj) {
    foreach (GetUnitsInPlay(intval($player)) as $u) {
        if (empty($u->removed) && TraitContains($u, 'Force')) return -1;
    }
    return 0;
};

// LAW_110 Phoenix Squadron Fighters: costs 1 less per friendly damaged unit (counted at play time).
$playCostModifiers["LAW_110"] = function($player, $subjectObj) {
    $n = 0;
    foreach (GetUnitsInPlay($player) as $u) {
        if (empty($u->removed) && intval($u->Damage ?? 0) > 0) $n++;
    }
    return -$n;
};

// SEC_131 Let's Talk: costs 3 less if a friendly unit left play this phase.
$playCostModifiers["SEC_131"] = function($player, $subjectObj) {
    return GlobalEffectCount($player, 'SWU_FRIENDLY_LEFT_PLAY') > 0 ? -3 : 0;
};

// SOR_248 Volunteer Soldier: costs 1 less if you control a Trooper unit.
// (It is still in hand when this runs, so it never counts itself.)
$playCostModifiers["SOR_248"] = function($player, $subjectObj) {
    foreach (GetField($player) as $u) {
        if (SWUObjGone($u)) continue;
        if (HasTrait($u->CardID, 'Trooper')) return -1;
    }
    return 0;
};

// SHD_091 Jabba's Rancor — costs 1 less while you control Jabba the Hutt (as a leader or unit).
$playCostModifiers["SHD_091"] = function($player, $subjectObj) {
    return _SWUControlsTitle(intval($player), ['Jabba the Hutt']) ? -1 : 0;
};

// SHD_117 Reputable Hunter — costs 1 less if an enemy unit has a Bounty.
$playCostModifiers["SHD_117"] = function($player, $subjectObj) {
    foreach (GetUnitsInPlay(OtherPlayer(intval($player))) as $u) {
        if (empty($u->removed) && ObjectHasBounty($u) > 0) return -1;
    }
    return 0;
};

// SOR_139 Force Choke: costs 1 less if you control a Force unit. (Force is a TRAIT,
// not an aspect.) The event is in hand/discard when this runs, so it never self-counts.
$playCostModifiers["SOR_139"] = function($player, $subjectObj) {
    foreach (GetField($player) as $u) {
        if (SWUObjGone($u)) continue;
        if (TraitContains($u, 'Force')) return -1;
    }
    return 0;
};

// LOF_056 Size Matters Not: costs 1 less if you control a Force unit.
$playCostModifiers["LOF_056"] = function($player, $subjectObj) {
    foreach (GetField($player) as $u) {
        if (SWUObjGone($u)) continue;
        if (TraitContains($u, 'Force')) return -1;
    }
    return 0;
};

// JTL_204 Home One: costs 3 less if an opponent controls 3 or more space units.
$playCostModifiers["JTL_204"] = function($player, $subjectObj) {
    $opp = GetOpponent($player);
    $cnt = 0;
    foreach (GetSpaceArena($opp) as $u) {
        if (empty($u->removed)) $cnt++;
    }
    return $cnt >= 3 ? -3 : 0;
};

// JTL_191 Invincible: costs 1 less if you control a unique Separatist card (unit, upgrade, or leader).
$playCostModifiers["JTL_191"] = function($player, $subjectObj) {
    return _SWUControlsUniqueSeparatist($player) ? -1 : 0;
};

// JTL_101 Red Leader: costs 1 less to play for each friendly Pilot unit and upgrade.
$playCostModifiers["JTL_101"] = function($player, $subjectObj) {
    return -1 * _SWUCountFriendlyPilots($player, 0, false);
};

// True if $player controls a UNIQUE Separatist card — a friendly unit/leader (trait Separatist + unique)
// or an attached Separatist upgrade that is unique.
function _SWUControlsUniqueSeparatist(int $player): bool {
    if ($player <= 0) return false;
    foreach (GetLeader($player) as $l) {
        if (empty($l->removed) && HasTrait($l->CardID ?? '', 'Separatist') && CardUnique($l->CardID ?? '')) return true;
    }
    foreach (GetUnitsInPlay($player) as $u) {
        if (HasTrait($u->CardID ?? '', 'Separatist') && CardUnique($u->CardID ?? '')) return true;
        foreach (GetUpgradesOnUnit($u) as $up) {
            if (HasTrait($up->CardID ?? '', 'Separatist') && CardUnique($up->CardID ?? '')) return true;
        }
    }
    return false;
}

// JTL_138 Decimator of Dissidents: costs 1 less if you dealt indirect damage this phase.
$playCostModifiers["JTL_138"] = function($player, $subjectObj) {
    return GlobalEffectCount($player, 'SWU_DEALT_INDIRECT') > 0 ? -1 : 0;
};

// JTL_163 AT-DP Occupier: costs 1 less for each damaged ground unit (any player's).
$playCostModifiers["JTL_163"] = function($player, $subjectObj) {
    $cnt = 0;
    foreach ([1, 2] as $p) {
        foreach (GetGroundArena($p) as $u) {
            if (empty($u->removed) && intval($u->Damage) > 0) $cnt++;
        }
    }
    return -1 * $cnt;
};

// SEC_122 Vuutun Palaa: costs 1 resource less for each friendly Droid unit in play.
// "Droid" is a TRAIT in SWU (CardSubtypes always returns '' — traits live in $traitData).
// HasTrait checks $traitData. GetField covers both ground and space arenas, and includes
// all unit types (Token Unit, Leader Unit) because AddGroundArena/AddSpaceArena puts
// everything into those arrays regardless of whether it's a token or deployed leader.
// Battle Droid tokens (TWI_T01, trait Separatist,Droid,Trooper) count correctly.
$playCostModifiers["SEC_122"] = function($player, $subjectObj) {
    $count = 0;
    foreach (GetField($player) as $u) {
        if (SWUObjGone($u)) continue;
        if (HasTrait($u->CardID, 'Droid')) $count++;
    }
    return -1 * $count;
};

// Source/field-presence play-cost modifiers: a unit IN PLAY that changes the cost
// of OTHER cards being played. Keyed by the SOURCE card's ID; consulted by
// SWUComputePlayCost for every field object of either player.
//   fn($subjectObj, $subjectPlayer, $sourceObj): int   (positive = more expensive)
$playCostFieldModifiers = [];

// SOR_181 Jabba the Hutt: each TRICK event YOU (Jabba's controller) play costs 1 less.
$playCostFieldModifiers["SOR_181"] = function($subjectObj, $subjectPlayer, $sourceObj) {
    $srcController = intval($sourceObj->Controller ?? 0);
    if ($srcController <= 0 || $srcController !== intval($subjectPlayer)) return 0; // only your own
    if (!HasTrait($subjectObj->CardID, 'Trick')) return 0;
    if (stripos(CardType($subjectObj->CardID) ?? '', 'Event') === false) return 0;
    return -1;
};

// JTL_188 Moff Gideon: after he deals combat damage to an opponent's base (sets SWU_GIDEON_TAX on that
// opponent), each unit that opponent plays this phase costs 1 more. Gated on Gideon being in play.
$playCostFieldModifiers["JTL_188"] = function($subjectObj, $subjectPlayer, $sourceObj) {
    $srcController = intval($sourceObj->Controller ?? 0);
    if ($srcController <= 0 || $srcController === intval($subjectPlayer)) return 0; // only Gideon's opponent
    if (stripos(CardType($subjectObj->CardID) ?? '', 'Unit') === false) return 0;  // units only
    if (GlobalEffectCount(intval($subjectPlayer), 'SWU_GIDEON_TAX') <= 0) return 0;
    return 1;
};

// SOR_034 Del Meeko: each event an opponent plays costs 1 more.
$playCostFieldModifiers["SOR_034"] = function($subjectObj, $subjectPlayer, $sourceObj) {
    $srcController = intval($sourceObj->Controller ?? 0);
    if ($srcController <= 0 || $srcController === intval($subjectPlayer)) return 0; // only opponents
    if (stripos(CardType($subjectObj->CardID) ?? '', 'Event') === false) return 0;
    return 1;
};

// JTL_032 Director Krennic: the FIRST unit you play each round that has a "When Defeated" ability costs
// 1 resource less. Eligibility = source JTL_032 in play, subject is YOUR unit with a WhenDefeated
// ability, and the once-per-round SWU_KRENNIC_USED flag isn't set yet (set in ActivateCard after the
// first such play; cleared at RegroupPhaseStart). The flag-set happens AFTER cost is charged, so the
// first qualifying play still receives the -1 (flag was 0 during cost computation).
$playCostFieldModifiers["JTL_032"] = function($subjectObj, $subjectPlayer, $sourceObj) {
    $srcController = intval($sourceObj->Controller ?? 0);
    if ($srcController <= 0 || $srcController !== intval($subjectPlayer)) return 0; // only your own plays
    if (!HasWhenDefeatedAbility($subjectObj->CardID ?? '')) return 0;
    if (GlobalEffectCount(intval($subjectPlayer), 'SWU_KRENNIC_USED') > 0) return 0; // already used this round
    return -1;
};

// LOF_108 Malakili: the FIRST Creature unit you play each phase costs 1 resource less. Mirrors JTL_032
// (SWU_LOF108_CREATURE_USED set in ActivateCard after the first Creature play; cleared at RegroupPhaseStart;
// the flag-set happens AFTER cost is charged, so the first Creature still receives the -1).
$playCostFieldModifiers["LOF_108"] = function($subjectObj, $subjectPlayer, $sourceObj) {
    $srcController = intval($sourceObj->Controller ?? 0);
    if ($srcController <= 0 || $srcController !== intval($subjectPlayer)) return 0; // only your own plays
    if (!TraitContains($subjectObj, 'Creature')) return 0;
    if (stripos(CardType($subjectObj->CardID) ?? '', 'Unit') === false) return 0;  // Creature UNIT
    if (GlobalEffectCount(intval($subjectPlayer), 'SWU_LOF108_CREATURE_USED') > 0) return 0;
    return -1;
};

// True if $player controls Director Krennic (JTL_032) as a unit in either arena.
function _SWUControlsKrennic(int $player): bool {
    if ($player <= 0) return false;
    foreach (GetField($player) as $u) {
        if (empty($u->removed) && ($u->CardID ?? '') === 'JTL_032') return true;
    }
    return false;
}

// LOF_108 Malakili rider — true when a $sourceMzID Creature would deal damage to friendly $targetUnit
// and the shared controller has Malakili (LOF_108) in play, so the damage must be prevented. Source +
// target must share a controller (friendly→friendly); the source must carry the Creature trait.
function _SWULof108PreventsCreatureDamage(string $sourceMzID, $targetUnit): bool {
    $src = GetZoneObject($sourceMzID);
    if (SWUObjGone($src)) return false;
    if (!TraitContains($src, 'Creature')) return false;
    $srcController = intval($src->Controller ?? -1);
    if ($srcController < 0 || $srcController !== intval($targetUnit->Controller ?? -2)) return false;
    foreach (GetField($srcController) as $u) {
        if (empty($u->removed) && ($u->CardID ?? '') === 'LOF_108') return true;
    }
    return false;
}

// JTL_005 Admiral Piett (deployed leader unit): each Capital Ship unit YOU (Piett's controller) play
// costs 2 resources less. Only fires while Piett is in play as a Leader Unit (GetField includes deployed
// leaders), so the leader-side action discount (–1) and this deployed passive never stack.
$playCostFieldModifiers["JTL_005"] = function($subjectObj, $subjectPlayer, $sourceObj) {
    $srcController = intval($sourceObj->Controller ?? 0);
    if ($srcController <= 0 || $srcController !== intval($subjectPlayer)) return 0; // only your own plays
    if (!HasTrait($subjectObj->CardID, 'Capital Ship')) return 0;
    return -2;
};

// A card is "non-[Heroism], non-[Villainy]" (neutral) when its aspect string carries
// neither alignment — used by SOR_056 Bendu's "next neutral card costs 2 less".
function _SWUIsNeutralCard($cardID): bool {
    $asp = CardAspect($cardID) ?? '';
    return stripos($asp, 'Heroism') === false && stripos($asp, 'Villainy') === false;
}

// True if $player controls a unit with the Force trait (SOR_138 / SOR_167 conditional bonuses).
function _SWUControlsForceUnit(int $player): bool {
    foreach (GetField($player) as $u) {
        if (SWUObjGone($u)) continue;
        if (TraitContains($u, 'Force')) return true;
    }
    return false;
}

// SOR_061 Guardian of the Whills: "the first upgrade you play on this unit each round costs 1 less."
// True if $player controls a Guardian whose per-round upgrade-discount charge is still unused (flag
// SWU_GUARDIAN_UPG_USED_{uid}, set on attach, cleared at ActionPhaseStart). Each Guardian has its own
// charge, so multiple Guardians grant multiple discounts.
function _SWUFirstUpgradeGuardianAvailable(int $player): bool {
    foreach (GetField($player) as $u) {
        if (SWUObjGone($u) || !in_array($u->CardID ?? '', ['SOR_061', 'LOF_058'], true)) continue;
        $uid = intval($u->UniqueID ?? 0);
        if (GlobalEffectCount($player, 'SWU_GUARDIAN_UPG_USED_' . $uid) <= 0) return true;
    }
    return false;
}

// Final cost to play $obj from $player's hand: base cost + aspect penalty + all
// modifiers, floored at 0. The single source of truth for play cost.
//
// $host (optional): when provided at payment time (upgrade path, post-host-selection),
// the SOR_061 Guardian discount is host-specific — −1 only if the chosen host IS a
// controlled SOR_061 with an unused per-round charge. When $host is null (affordability /
// GLOW check), the old best-case logic applies: −1 if ANY Guardian has a spare charge.

// True if the card being played (a hand/resource object) is a Unit / an Event (by printed type).
function _SWUObjIsUnit($o): bool  { return stripos(CardType($o->CardID ?? '') ?? '', 'Unit')  !== false; }
function _SWUObjIsEvent($o): bool { return stripos(CardType($o->CardID ?? '') ?? '', 'Event') !== false; }

// One-shot "next X costs N less" play charges — the drift-prone set. Both the cost PEEK
// (_SWUPlayCostModifierDelta) and the CONSUME (_SWUConsumeOneShotCharges) iterate THIS one table, so peek
// and consume — on every play path (normal + Smuggle) — can never diverge. Adding such a card = one row.
//   'flag'    armed GlobalEffect; the discount applies only while GlobalEffectCount(flag) > 0.
//   'applies' fn($player,$obj,$host):bool — the type/trait gate for the DISCOUNT (the flag>0 check is done
//             by the caller). This gates the cost peek.
//   'consumeApplies' (optional) fn(...):bool — the gate for SPENDING the charge, when it differs from
//             'applies'. Defaults to 'applies'. LOF_005 needs it: the "next unit you play" charge is spent
//             on the next unit REGARDLESS of whether the conditional keyword-share discount applied.
//   'amount'  fn($player,$obj):int — resources to subtract (count-based rows return the live count).
//   'consume' 'remove' = spend one charge; 'clearPrefix' = spend all (count-based).
$oneShotPlayCharges = [
    ['flag'=>'SWU_NEUTRAL_DISCOUNT',        'applies'=>fn($p,$o,$h)=>_SWUIsNeutralCard($o->CardID ?? ''),                                   'amount'=>fn($p,$o)=>2, 'consume'=>'remove'],       // SOR_056 Bendu
    ['flag'=>'SWU_SNAP_DISCOUNT',           'applies'=>fn($p,$o,$h)=>HasTrait($o->CardID ?? '', 'Resistance'),                             'amount'=>fn($p,$o)=>1, 'consume'=>'remove'],       // JTL_098 Snap
    ['flag'=>'SWU_PILOT_DISCOUNT',          'applies'=>fn($p,$o,$h)=>HasTrait($o->CardID ?? '', 'Pilot'),                                  'amount'=>fn($p,$o)=>1, 'consume'=>'remove'],       // JTL_008 Wedge (as-unit half)
    ['flag'=>'SWU_LOF005_DISCOUNT_NEXT',    'applies'=>fn($p,$o,$h)=>_SWUObjIsUnit($o) && _SWULof005SharesKeywordWithFriendly(intval($p), $o->CardID ?? ''), 'consumeApplies'=>fn($p,$o,$h)=>_SWUObjIsUnit($o), 'amount'=>fn($p,$o)=>1, 'consume'=>'remove'], // LOF_005 Morgan (charge spent on the next unit even if it doesn't share a keyword)
    ['flag'=>'SWU_SEC110_DISCOUNT_NEXT',    'applies'=>fn($p,$o,$h)=>_SWUObjIsUnit($o),                                                    'amount'=>fn($p,$o)=>1, 'consume'=>'remove'],       // SEC_110 GNK
    ['flag'=>'SWU_TWI121_DISCOUNT_NEXT',    'applies'=>fn($p,$o,$h)=>_SWUObjIsUnit($o),                                                    'amount'=>fn($p,$o)=>2, 'consume'=>'remove'],       // TWI_121 General's Blade
    ['flag'=>'SWU_TS26035_DISCOUNT_NEXT',   'applies'=>fn($p,$o,$h)=>_SWUObjIsEvent($o),                                                   'amount'=>fn($p,$o)=>2 * GlobalEffectCount(intval($p), 'SWU_TS26035_DISCOUNT_NEXT'), 'consume'=>'clearPrefix'], // TS26_35 Ahsoka's Lightsabers — two copies triggering before you play anything stack to -4 on that one event, and both are spent (cf. Rex/ASH_027)
    ['flag'=>'SWU_REX_DISCOUNT_NEXT',       'applies'=>fn($p,$o,$h)=>_SWUObjIsEvent($o),                                                   'amount'=>fn($p,$o)=>GlobalEffectCount(intval($p), 'SWU_REX_DISCOUNT_NEXT'), 'consume'=>'clearPrefix'], // TS26_06 Rex
    ['flag'=>'SWU_TWI246_DISCOUNT',         'applies'=>fn($p,$o,$h)=>HasTrait($o->CardID ?? '', 'Republic'),                               'amount'=>fn($p,$o)=>1, 'consume'=>'remove'],       // TWI_246 Tranquility
    ['flag'=>'SWU_SEC261_OFFICIAL_DISCOUNT','applies'=>fn($p,$o,$h)=>_SWUObjIsUnit($o) && HasTrait($o->CardID ?? '', 'Official'),          'amount'=>fn($p,$o)=>1, 'consume'=>'remove'],       // SEC_261 Inspiring Senator
    ['flag'=>'SWU_LAW058_DISCOUNT_NEXT',    'applies'=>fn($p,$o,$h)=>_SWUObjIsUnit($o),                                                    'amount'=>fn($p,$o)=>1, 'consume'=>'remove'],       // LAW_058 Honor-Bound Partisan
    ['flag'=>'SWU_ASH027_DISCOUNT_NEXT',    'applies'=>fn($p,$o,$h)=>_SWUObjIsUnit($o),                                                    'amount'=>fn($p,$o)=>GlobalEffectCount(intval($p), 'SWU_ASH027_DISCOUNT_NEXT'), 'consume'=>'clearPrefix'], // ASH_027 Enoch
    ['flag'=>'SWU_SHD006_DISCOUNT_NEXT',    'applies'=>fn($p,$o,$h)=>_SWUObjIsUnit($o),                                                    'amount'=>fn($p,$o)=>GlobalEffectCount(intval($p), 'SWU_SHD006_DISCOUNT_NEXT'), 'consume'=>'clearPrefix'], // SHD_006 Jabba's bounty
    ['flag'=>'SWU_LAW158_DISCOUNT_NEXT',    'applies'=>fn($p,$o,$h)=>_SWUObjIsUnit($o) && HasTrait($o->CardID ?? '', 'Underworld'),        'amount'=>fn($p,$o)=>1, 'consume'=>'remove'],       // LAW_158 Khetanna
    ['flag'=>'SWU_ASH237_DISCOUNT_NEXT',    'applies'=>fn($p,$o,$h)=>_SWUObjIsUnit($o) && HasTrait($o->CardID ?? '', 'Imperial'),          'amount'=>fn($p,$o)=>1, 'consume'=>'remove'],       // ASH_237 Mouse Droid
];

// Spend every one-shot play charge (from $oneShotPlayCharges) that applies to $obj. Called by the
// normal-play commit (ActivateCard) and the Smuggle commit — both go through this ONE function, so the
// set consumed always matches the set the peek applied. Idempotent for un-armed / non-matching charges.
function _SWUConsumeOneShotCharges($player, $obj, $host = null): void {
    global $oneShotPlayCharges;
    foreach ($oneShotPlayCharges as $chg) {
        $gate = $chg['consumeApplies'] ?? $chg['applies'];
        if (GlobalEffectCount(intval($player), $chg['flag']) > 0 && $gate($player, $obj, $host)) {
            if ($chg['consume'] === 'clearPrefix') SWUClearGlobalEffectsByPrefix(intval($player), $chg['flag']);
            else                                   RemoveGlobalEffect(intval($player), $chg['flag']);
        }
    }
}

// Consume the once-per-round/phase UNIT-play cost-discount "used" flags on ANY qualifying unit play — even
// before the source unit is in play and even when no discount applied (CR-consistent: the "first slot" is
// spent regardless, so a qualifying unit played THEN the source leaves the next one un-discounted):
// JTL_032 Director Krennic (first When-Defeated unit each round) and LOF_108 Malakili (first Creature unit
// each phase). Shared by the normal unit-play path (ActivateCard) and the smuggled-unit commit
// (SWUSmuggleResource) so the two stay consistent. (LAW_229 Gambit is NOT here — it fires for any card
// type, not just units, and no Smuggle card carries the Gambit trait; it stays in ActivateCard's top block.)
function _SWUMarkUnitPlayUsedFlags($player, $cardID): void {
    if (GlobalEffectCount(intval($player), 'SWU_KRENNIC_USED') <= 0 && HasWhenDefeatedAbility($cardID)) {
        AddGlobalEffects(intval($player), 'SWU_KRENNIC_USED');
    }
    if (GlobalEffectCount(intval($player), 'SWU_LOF108_CREATURE_USED') <= 0 && HasTrait($cardID, 'Creature')) {
        AddGlobalEffects(intval($player), 'SWU_LOF108_CREATURE_USED');
    }
}

// Base-cost-INDEPENDENT play-cost modifier delta shared by every play path (normal play, Smuggle) so the
// cost math never drifts between them. Returns the signed sum of surcharges (+) and discounts (-) for
// playing $obj. NEVER consumes a charge (read-only) — consumption happens at each path's commit site
// (ActivateCard / SWUSmuggleResource / ATTACH_UPGRADE).
//   $host: chosen upgrade host for host-conditional discounts; null on affordability / best-case scans.
//   $includeUsedFlagBucket: pass FALSE on the Smuggle path until Phase 3 wires the used-flag consume, so a
//     path only ever APPLIES a discount bucket it can also CONSUME (no double-dip). See the design doc
//     docs/superpowers/specs/2026-07-22-smuggle-cost-pipeline-unification-design.md.
// NOTE: the printed base cost, printed aspect penalty, aspect-penalty waivers (SHD_126/TWI_236/TWI_034/
// LAW_009), and the JTL_232 free override are NOT here — they are path-specific and live in
// SWUComputePlayCost. The delta is a commutative sum, so block order does not affect the result.
// The "first upgrade you play each round/phase costs 1 less" discounts, as a negative delta:
//   SOR_061 / LOF_058 Guardian of the Whills — first upgrade ON THIS UNIT each round
//   SEC_064 Congress of Malastare          — first upgrade each phase (any host)
//   ASH_075 Pit Droid Team                 — first upgrade on ANOTHER FRIENDLY unit each phase
// $host === null → affordability peek, apply the best case; $host !== null → the real chosen host, so the
// host-conditional ones are exact. All three are spent by _SWUConsumeUpgradeUsedFlags at attach time.
//
// $pilotPlay = true when a unit is being played as a Pilot upgrade. That IS "playing an upgrade", and the
// consume already fires on that path — so omitting these here burned the charge without granting the
// discount. The Guardian one is excluded for pilots: it requires the HOST to be Guardian of the Whills,
// which is not a Vehicle and so can never host a pilot — applying it to the peek would make the pilot look
// 1 cheaper than the charge.
function _SWUFirstUpgradePlayDiscount(int $player, $host = null, bool $pilotPlay = false): int {
    $delta = 0;
    if (!$pilotPlay) {
        if ($host === null) {
            if (_SWUFirstUpgradeGuardianAvailable($player)) $delta += -1;
        } else {
            $hostUid = intval($host->UniqueID ?? 0);
            if (in_array($host->CardID ?? '', ['SOR_061', 'LOF_058'], true)
                && GlobalEffectCount($player, 'SWU_GUARDIAN_UPG_USED_' . $hostUid) <= 0) {
                $delta += -1;
            }
        }
    }
    if (GlobalEffectCount($player, 'SWU_SEC064_USED') <= 0
            && _SWUCountUnitsWithCardID($player, 'SEC_064') > 0) {
        $delta += -1;
    }
    if (GlobalEffectCount($player, 'SWU_ASH075_USED') <= 0
            && _SWUCountUnitsWithCardID($player, 'ASH_075') > 0
            && ($host === null || (intval($host->Controller ?? 0) === $player && ($host->CardID ?? '') !== 'ASH_075'))) {
        $delta += -1;
    }
    return $delta;
}

function _SWUPlayCostModifierDelta($player, $obj, $host = null, bool $includeUsedFlagBucket = true): int {
    if ($obj === null || !isset($obj->CardID)) return 0;
    global $playCostModifiers, $playCostFieldModifiers, $Plot_Cards;
    $cardID = $obj->CardID;
    $delta  = 0;

    // ── Always-included bucket (no consume, or one-shot charges the table/Smuggle both consume) ──
    // SHD_202 Qi'ra — "each card with that name costs 3 resources more for your opponents." Surcharge
    // follows the player who PLAYED Qi'ra (matched by UID; survives a steal); matched by TITLE (excludes
    // subtitle). +3 iff the opponent has an in-play Qi'ra that named this title.
    $qiraPlayer  = OtherPlayer(intval($player));
    $playedTitle = CardTitle($cardID);
    $qiraUids    = [];
    foreach ([GetGroundArena(1), GetGroundArena(2), GetSpaceArena(1), GetSpaceArena(2)] as $qArena) {
        foreach ($qArena as $qUnit) {
            if (($qUnit->CardID ?? '') === 'SHD_202' && empty($qUnit->removed)) $qiraUids[] = intval($qUnit->UniqueID ?? 0);
        }
    }
    if (!empty($qiraUids)) {
        foreach (GetGlobalEffects($qiraPlayer) as $ge202) {
            $key = $ge202->CardID ?? '';
            if (strpos($key, 'SWU_SHD202_NAMED|') !== 0) continue;
            $rest  = substr($key, strlen('SWU_SHD202_NAMED|'));
            $piece = explode('|', $rest, 2);
            if (count($piece) === 2) {                       // per-uid form → that Qi'ra must be in play
                if (!in_array(intval($piece[0]), $qiraUids, true)) continue;
                $named = $piece[1];
            } else {                                          // legacy seeded form → any Qi'ra in play suffices
                $named = $piece[0];
            }
            if (CardTitle($named) === $playedTitle) { $delta += 3; break; }
        }
    }
    // Subject-keyed modifiers (the card discounts/surcharges itself). SEC_046 Galen Erso — a named card
    // has lost its own cost-modifier ability.
    if (isset($playCostModifiers[$cardID]) && !_SWUGalenSuppressesCard(intval($player), $cardID)) {
        $delta += intval($playCostModifiers[$cardID]($player, $obj));
    }
    // One-shot "next X costs N less" charges — the drift-prone set, DRIVEN BY the $oneShotPlayCharges
    // descriptor table so the peek here and the consume in _SWUConsumeOneShotCharges can never diverge.
    // (SOR_056 Bendu, JTL_098 Snap, JTL_008 Wedge, LOF_005 Morgan, SEC_110 GNK, TWI_121, TS26_35, TS26_06
    // Rex, TWI_246, SEC_261, LAW_058, ASH_027, SHD_006, LAW_158, ASH_237.) To add such a card, add one row
    // to the table (see $oneShotPlayCharges) — do NOT hand-edit cost math here or in ActivateCard.
    global $oneShotPlayCharges;
    foreach ($oneShotPlayCharges as $chg) {
        if (GlobalEffectCount(intval($player), $chg['flag']) > 0 && $chg['applies']($player, $obj, $host)) {
            $delta -= intval($chg['amount']($player, $obj));
        }
    }
    // SEC_001 Chancellor Palpatine: "next card played using Plot costs 3 less." "Using Plot" = played FROM
    // the resource zone as a Resources object (a normal hand play of a Plot-keyword card is NOT using
    // Plot). Self-gated on `instanceof Resources` → never matches a Smuggle object (Smuggle is not Plot);
    // consumed inline in ActivateCard, so it is deliberately NOT in the one-shot table.
    if (GlobalEffectCount(intval($player), 'SWU_SEC001_PLOT_DISCOUNT') > 0
            && isset($Plot_Cards[$cardID])
            && is_object($obj) && ($obj instanceof Resources)) {
        $delta += -3;
    }
    // JTL_260 Death Star Plans: "first unit each round costs 2 less" (consumed via the SWU_JTL260_USED
    // flag in ActivateCard and, for smuggled units, in SWUSmuggleResource). In the always-included bucket
    // because the Smuggle path applies+consumes it — so it is NOT a used-flag-bucket exclusion.
    if (strpos(CardType($cardID) ?? '', 'Unit') !== false
            && GlobalEffectCount(intval($player), 'SWU_JTL260_USED') <= 0
            && _SWUControlsUnitBearingUpgrade(intval($player), 'JTL_260')) {
        $delta += -2;
    }
    // LAW_129 Mastery — "costs 1 less on a unique host." Host-conditional, no claw-back consume.
    if ($cardID === 'LAW_129') {
        if ($host === null) {
            foreach (GetUnitsInPlay(intval($player)) as $hu) {
                if (empty($hu->removed) && CardUnique($hu->CardID ?? '')) { $delta += -1; break; }
            }
        } elseif (CardUnique($host->CardID ?? '')) {
            $delta += -1;
        }
    }
    // ASH_262 Faith in the Empire — "costs 1 less on an Imperial host." (no-consume, LAW_129 pattern)
    if ($cardID === 'ASH_262') {
        if ($host === null) {
            foreach (GetUnitsInPlay(intval($player)) as $hu) { if (empty($hu->removed) && HasTrait($hu->CardID ?? '', 'Imperial')) { $delta += -1; break; } }
        } elseif (HasTrait($host->CardID ?? '', 'Imperial')) { $delta += -1; }
    }
    // ASH_263 The Way of the Mand'alor — "costs 1 less on a Mandalorian host." (no-consume)
    if ($cardID === 'ASH_263') {
        if ($host === null) {
            foreach (GetUnitsInPlay(intval($player)) as $hu) { if (empty($hu->removed) && TraitContains($hu, 'Mandalorian')) { $delta += -1; break; } }
        } elseif (TraitContains($host, 'Mandalorian')) { $delta += -1; }
    }

    // ── Used-flag bucket (once-per-round/phase & upgrade discounts consumed via a _USED flag). Excluded
    // from the Smuggle path until Phase 3 wires their Smuggle consume (no double-dip). ──
    if ($includeUsedFlagBucket) {
        // LAW_229 The Master Codebreaker: "first Gambit each round costs 1 less" (consumed in ActivateCard).
        if (HasTrait($cardID, 'Gambit')
                && GlobalEffectCount(intval($player), 'SWU_LAW229_USED') <= 0
                && _SWUCountUnitsWithCardID(intval($player), 'LAW_229') > 0) {
            $delta += -1;
        }
        // The "first upgrade you play each …" discounts. Shared with the Piloting cost path — see
        // _SWUFirstUpgradePlayDiscount.
        if (stripos(CardType($cardID) ?? '', 'Upgrade') !== false) {
            $delta += _SWUFirstUpgradePlayDiscount(intval($player), $host, false);
        }
    }

    // ── Passive field-presence + generated PlayCostModifier abilities, over both players' fields. ──
    // JTL_032 Krennic / LOF_108 Malakili are field modifiers with a _USED consume, so they belong to the
    // used-flag bucket — skip them when it is off (Smuggle Phases 1–2) to avoid a double-dip.
    $hasGenerated = function_exists('EvaluatePlayCostModifier');
    if ($hasGenerated) {
        $delta += intval(EvaluatePlayCostModifier($cardID, $player, $obj, 0, null));
    }
    foreach ([1, 2] as $fp) {
        foreach (GetField($fp) as $fo) {
            // SEC_046 Galen Erso — a named source unit no longer modifies other cards' costs.
            if (SWUObjGone($fo) || HasNoAbilities($fo) || LostAbilities($fo)) continue;
            if (!$includeUsedFlagBucket && in_array($fo->CardID ?? '', ['JTL_032', 'LOF_108'], true)) continue;
            if (isset($playCostFieldModifiers[$fo->CardID])) {
                $delta += intval($playCostFieldModifiers[$fo->CardID]($obj, $player, $fo));
            }
            if ($hasGenerated) {
                $delta += intval(EvaluatePlayCostModifier($fo->CardID, $player, $obj, 0, $fo));
            }
        }
    }
    return $delta;
}

function SWUComputePlayCost($player, $obj, $host = null): int {
    if ($obj === null || !isset($obj->CardID)) return 0;
    $cardID = $obj->CardID;
    $cost = intval(CardCost($cardID)) + SWUAspectPenalty($player, $cardID);
    // ── Aspect-penalty waivers (path-specific): they subtract the PRINTED aspect penalty (or a flat
    // host-conditional amount), which the Smuggle path never adds — so they stay OUT of the shared delta.
    // SHD_126 The Darksaber — waive aspect penalty on a Mandalorian host.
    if ($cardID === 'SHD_126' && $host !== null && TraitContains($host, 'Mandalorian')) {
        $cost -= SWUAspectPenalty($player, $cardID);
    }
    // TWI_236 Grievous's Wheel Bike — costs 2 less on General Grievous.
    if ($cardID === 'TWI_236' && $host !== null && SWUObjectTitle($host) === 'General Grievous') {
        $cost -= 2;
    }
    // TWI_034 General Grievous — waive aspect penalty on Lightsaber upgrades played on this unit.
    if ($host !== null && ($host->CardID ?? '') === 'TWI_034' && HasTrait($cardID, 'Lightsaber')) {
        $cost -= SWUAspectPenalty($player, $cardID);
    }
    // LAW_009 Hera Syndulla — while controlling 2+ units, waive aspect penalties on Heroism units.
    if (stripos(CardType($cardID) ?? '', 'Unit') !== false
            && strpos(CardAspect($cardID) ?? '', 'Heroism') !== false
            && _SWUControlsTitle(intval($player), ['Hera Syndulla'])) {
        $units = 0;
        foreach (GetUnitsInPlay(intval($player)) as $hu) { if (empty($hu->removed)) $units++; }
        if ($units >= 2) $cost -= SWUAspectPenalty(intval($player), $cardID);
    }
    // ── Shared, base-cost-independent modifier delta (surcharges + discounts + passive/field modifiers). ──
    $cost += _SWUPlayCostModifierDelta($player, $obj, $host, true);
    // JTL_232 Jump to Lightspeed: one-shot "next copy of that unit is free this phase" overrides all other
    // cost math → 0. Consumed in ActivateCard.
    if (GlobalEffectCount(intval($player), 'SWU_JTL232_FREE|' . $cardID) > 0) return 0;
    return max(0, $cost);
}

// Piloting cost: the bracket cost Y from the card's Piloting keyword, plus the
// off-aspect penalty for the player. Used when a pilot is played/deployed as an
// upgrade. Returns 0 for non-pilots / cards with no Piloting cost.
function SWUComputePilotCost($player, $obj, $host = null): int {
    if ($obj === null || !isset($obj->CardID)) return 0;
    $cardID = $obj->CardID;
    $base = CardPilotingCost($cardID);
    if ($base === null) return 0;
    // Playing a Pilot as an upgrade is playing an upgrade, so the "first upgrade you play each …"
    // discounts apply here too (their charge is spent on this path either way).
    $base += _SWUFirstUpgradePlayDiscount(intval($player), $host, true);
    // SWU_PILOT_DISCOUNT: a one-shot "next Piloting play costs N less" (JTL_008 Wedge Antilles).
    // Honored here — the single pilot-cost chokepoint used by BOTH affordability
    // (SWUGetPilotValidTargets) AND the charge (_SWUFinalizeUpgradeAttach) — so the two stay
    // consistent. Consumed once in _SWUFinalizeUpgradeAttach after a successful pilot pay.
    $discount = GlobalEffectCount(intval($player), 'SWU_PILOT_DISCOUNT');
    return max(0, intval($base) + SWUAspectPenalty($player, $cardID) - $discount);
}

// Create a unit token ($tokenID) for $player in the token's printed arena (Ground/Space).
// Tokens enter exhausted by default (Status 0); pass $ready=true for "enters ready" effects.
// No WhenPlayed triggers fire for tokens (mirrors the SOR_087 / JTL_100 free-placement pattern).
// Returns the new token's UniqueID (callers may ignore it; used to further tag the token, e.g. grant
// a phase keyword to a just-created Spy — SEC_082).
// Raw single-token creation (the board mutation + per-token side effects: Shielded-on-create, the
// SWU_CREATED_TOKEN flag, the ASH_017 Greef offer). Callers should use SWUCreateUnitToken /
// SWUCreateUnitTokens instead so ASH_094 Moff Jerjerrod's "create twice that number" replacement is
// offered; this raw helper deliberately skips that offer (used for the doubled tokens themselves).
function _SWUCreateOneToken(int $player, string $tokenID, bool $ready = false): int {
    global $playerID;
    $savedPID = $playerID;
    $playerID = $player;
    // TWI_203 Chancellor Palpatine — "Each token unit you create enters play ready."
    if (!$ready && _SWUCountActiveUnitsWithCardID($player, 'TWI_203') > 0) $ready = true;
    // HMW_234 Ritual Dragon — "friendly units enter play ready" includes created tokens (while HMW_234 is
    // in play and you control a Tatooine base). A token is never HMW_234, so this reads the in-play copy.
    if (!$ready && _SWURitualDragonEntersReady($player, $tokenID)) $ready = true;
    $uid    = NextUniqueID();
    $status = $ready ? 1 : 0;
    if (CardTargetArena($tokenID) === 'SpaceArena') {
        $newCard = AddSpaceArena($player, CardID: $tokenID, Status: $status, Owner: $player,
            Damage: 0, Controller: $player, UniqueID: $uid);
    } else {
        $newCard = AddGroundArena($player, CardID: $tokenID, Status: $status, Owner: $player,
            Damage: 0, Controller: $player, UniqueID: $uid);
    }
    // Shielded (e.g. ASH_T01 Mandalorian token, or a Vehicle token while JTL_047 Yularen grants Shielded)
    // applies when the unit enters play, including by being created — give it a Shield token now. Creation
    // is NOT "playing", so WhenPlayed entry triggers deliberately don't fire here.
    if ($newCard !== null && empty($newCard->removed) && HasKeyword_Shielded($newCard)) {
        DoGiveShieldToken($player, $newCard->GetMzID());
    }
    // AMBUSH fires on creation too (USER RULING 2026-08-13, the Wedge SOR_100 case: a created Vehicle
    // token under Wedge's aura gets its Ambush attack). Mirror the play-path collection: live keyword
    // check (grants included), units-only targets, UID carried so dispatch re-resolves fresh.
    if ($newCard !== null && empty($newCard->removed) && HasKeyword_Ambush($newCard)) {
        $ambushTargets = SWUGetAllValidAmbushTargets($player, $newCard, CardTargetArena($tokenID) === 'SpaceArena' ? 'SpaceArena' : 'GroundArena');
        if (!empty($ambushTargets)) {
            AddTrigger($player, 'Ambush', $tokenID, $newCard->GetMzID(), (string)$uid);
            // Creation can run on paths whose ceremony never flushes the reaction bag (the
            // bagged-but-never-flushed family) — flush explicitly so the Ambush offer surfaces.
            FlushTriggerBag($player);
        }
    }
    AddGlobalEffects(intval($player), 'SWU_CREATED_TOKEN'); // LAW_016 "if you created a token this phase"
    AddGlobalEffects(intval($player), 'SWU_ENTERED_PHASE_' . intval($uid)); // TS26_02/004 "entered play this phase (incl. tokens)"
    // ASH_017 Greef Karga — "When you play OR create a unit: may exhaust leader → Advantage to that unit."
    // Creation isn't "playing", so queue the offer directly (the play half rides SWUCollectOwnPlayReactions).
    if ($newCard !== null && empty($newCard->removed) && _SWULeaderReadyUndeployed($player, 'ASH_017')) {
        DecisionQueueController::AddDecision($player, "YESNO", "-", 1, tooltip: "Exhaust_Greef_to_give_the_created_unit_an_Advantage_token?");
        DecisionQueueController::AddDecision($player, "CUSTOM", "ASH_017#0|{$uid}", 1);
    } elseif ($newCard !== null && empty($newCard->removed) && _SWULeaderDeployed($player, 'ASH_017')) {
        DoGiveAdvantageToken($player, $newCard->GetMzID());   // deployed side: auto-give, no exhaust
    }
    // ASH_041 Outcast — "When a friendly unit enters play (including this one): +1/+0 for this phase." A created
    // token IS a friendly unit entering play; buff it once per friendly Outcast (creation isn't "playing", so
    // the play-reactions path never reaches it).
    if ($newCard !== null && empty($newCard->removed)) {
        $a041c = 0;
        foreach (GetUnitsInPlay($player) as $u) {
            if (empty($u->removed) && ($u->CardID ?? '') === 'ASH_041') $a041c++;
        }
        for ($i = 0; $i < $a041c; $i++) SWUApplyPhaseBuff($newCard->GetMzID(), 1, 0, 'ASH_041');
    }
    // HMW_171 Trap Field — a created ground token is a non-leader ground unit "entering play", so either
    // player's Trap Field may react. Token creation has no trigger-bag flush of its own (it happens inside
    // another effect's resolution), so flush explicitly when a reaction was armed. $gPendingTriggers is
    // empty here (entry triggers are collected+flushed within their own collector, never spanning a token
    // creation), so this flushes only the Trap Field trigger(s).
    if ($newCard !== null && empty($newCard->removed)
        && SWUCollectTrapFieldReactions($newCard->GetMzID()) > 0) {
        FlushEntryTriggerBag($player);
    }
    $playerID = $savedPID;
    return $uid;
}

// Create ONE token unit for $player, returning its UniqueID. ASH_094 Moff Jerjerrod: if the player
// controls a Jerjerrod, this offers the "defeat Jerjerrod → create twice that number (2) instead"
// replacement after the token is made.
function SWUCreateUnitToken(int $player, string $tokenID, bool $ready = false): int {
    $uid = _SWUCreateOneToken($player, $tokenID, $ready);
    _SWUMaybeOfferJerjerrodDouble($player, $tokenID, 1, $ready);
    return $uid;
}

// Create $count token units of the SAME type for $player (a single "create a number of tokens"
// instruction). Returns the UniqueIDs of the tokens created now. $turnEffect (optional) is applied to each
// created token (e.g. 'CANT_ATTACK_BASES' for JTL_092, 'JTL_130' Sentinel) — it is also carried through
// the Jerjerrod doubling so the doubled tokens get it too. ASH_094 Moff Jerjerrod's doubling is offered
// ONCE for the whole batch (creating $count MORE on accept).
function SWUCreateUnitTokens(int $player, string $tokenID, int $count, bool $ready = false, string $turnEffect = '', string $upgradeToken = ''): array {
    $uids = [];
    if ($count <= 0) return $uids;
    for ($i = 0; $i < $count; $i++) {
        $uid = _SWUCreateOneToken($player, $tokenID, $ready);
        $uids[] = $uid;
        $mz = ($turnEffect !== '' || $upgradeToken !== '') ? SWUFindMzByUID($uid) : null;
        if ($turnEffect !== '' && $mz !== null) AddTurnEffect($mz, $turnEffect);
        // $upgradeToken is the PERSISTENT rider (an Experience/Shield token upgrade) as opposed to the
        // phase-scoped $turnEffect. Both ride through the Jerjerrod doubling below; a card that creates
        // tokens "and gives X to it" must pass its rider here rather than stamping the returned UIDs,
        // or the doubled tokens arrive bare (TS26_14 Yoda's Sentinel, TS26_55 Jedi General's Experience).
        if ($upgradeToken !== '' && $mz !== null) _SWUApplyTokenRider($player, $mz, $upgradeToken);
    }
    _SWUMaybeOfferJerjerrodDouble($player, $tokenID, $count, $ready, $turnEffect, 'unit', $upgradeToken);
    return $uids;
}

// Apply a persistent token-upgrade rider to a freshly created token. Kept in one place so the immediate
// creation and the Jerjerrod-doubled creation cannot drift apart.
function _SWUApplyTokenRider(int $player, string $mz, string $upgradeToken): void {
    if ($upgradeToken === 'EXPERIENCE') { DoGiveExperienceToken($player, $mz); return; }
    if ($upgradeToken === 'SHIELD')     { DoGiveShieldToken($player, $mz); return; }
}

// ASH_094 Moff Jerjerrod — "If you would create a number of tokens, you may defeat this unit. If you do,
// create twice that number of tokens instead." The $count tokens were just created; if $player controls a
// Jerjerrod, offer to defeat it and create $count MORE of the same token (net 2×count). Gated on a
// Jerjerrod being in play, so the no-Jerjerrod path is byte-for-byte the old behavior.
function _SWUMaybeOfferJerjerrodDouble(int $player, string $tokenID, int $count, bool $ready, string $turnEffect = '', string $kind = 'unit', string $upgradeToken = ''): void {
    if ($count < 1) return;
    $jUID = 0;
    foreach (GetUnitsInPlay($player) as $u) {
        if (empty($u->removed) && ($u->CardID ?? '') === 'ASH_094') { $jUID = intval($u->UniqueID ?? 0); break; }
    }
    if ($jUID <= 0) return;
    $r = $ready ? 1 : 0;
    DecisionQueueController::AddDecision($player, 'YESNO', '-', 1,
        tooltip: 'Defeat_Moff_Jerjerrod_to_create_twice_as_many_tokens?');
    DecisionQueueController::AddDecision($player, 'CUSTOM', "ASH_094#0|{$tokenID}|{$count}|{$r}|{$jUID}|{$turnEffect}|{$kind}|{$upgradeToken}", 1);
}

// True if $obj is a valid "Resistance unit OR a unit with a Resistance upgrade on it" target
// (JTL_007 Admiral Holdo). The Resistance trait may be on the unit itself or on any of its
// upgrade subcards (e.g. a Resistance pilot attached to a Vehicle).
function _SWUIsResistanceTarget($obj): bool {
    if (SWUObjGone($obj)) return false;
    if (HasTrait($obj->CardID ?? '', 'Resistance')) return true;
    foreach (GetUpgradesOnUnit($obj) as $u) {
        if (HasTrait($u->CardID ?? '', 'Resistance')) return true;
    }
    return false;
}

// SWU affordability: player has enough ready resources to cover the card's
// cost (including aspect penalty and cost modifiers). Overrides the GA version.
function CanAffordActivationReserve($player, $obj) {
    if ($obj === null || !isset($obj->CardID)) return false;
    // SOR_062 Regional Governor: a card named by an opponent is not playable (don't glow it).
    if (SWUCardPlayBlocked(intval($player), $obj->CardID)) return false;
    // SEC_053 etc.: "can't be played from your hand" — this affordability check is hand-only
    // (called solely for Location==Hand cards), so suppress the hand glow.
    if (_SWUCantPlayFromHand($obj->CardID)) return false;
    $cost    = SWUComputePlayCost($player, $obj);
    $cost    = SWUApplyCostHalving(intval($player), $cost); // JTL_105 The Starhawk — affordable at half
    // Exploit: a unit with Exploit N reduces its own play cost by 2 per friendly unit defeated (up to N,
    // capped by available fodder). So it is POTENTIALLY affordable at cost − 2·min(N, fodder) — glow green
    // when that reduced cost is affordable, given the units currently in play. (The player still chooses at
    // play time how many to defeat; ActivateCard pays the actual reduced cost.)
    $exploitX = SWUEffectivePlayExploit($obj);
    if ($exploitX > 0) {
        $fodderCount = count(SWUExploitFodder($player));
        if ($fodderCount > 0) $cost = max(0, $cost - 2 * min($exploitX, $fodderCount));
    }
    $ready   = 0;
    $res     = GetResources($player);
    for ($i = 0; $i < count($res); $i++) {
        if (isset($res[$i]->removed) && $res[$i]->removed) continue;
        if (SWUIsCreditToken($res[$i]->CardID ?? '')) continue; // Credit tokens aren't resources
        if (intval($res[$i]->Status) === 1) $ready++;
    }
    return $ready >= $cost;
}

// ── Macro ChoiceFunctions ───────────────────────────────────────────────────

function DoDrawCard($player, $amount) {
    global $playerID;
    $savedPID = $playerID;
    $playerID = intval($player);

    // Once the game is decided, no further draws (or deck-out damage) occur — this keeps a loss
    // declared at RegroupPhaseStart (e.g. SHD_208 Final Showdown) from being followed by the
    // ensuing regroup draw dealing deck-out damage to the winner. Check BOTH the in-process $gWinner
    // (authoritative within a request — a winner set at RGS is visible here at DRAW even though the
    // serialized GAMEOVER_WINNER doesn't survive the intra-request phase advance) AND the serialized
    // winner (persists across request boundaries in production).
    global $gWinner;
    if (SWUGetGameWinner() !== 0 || (isset($gWinner) && intval($gWinner) !== 0)) { $playerID = $savedPID; return "-"; }

    $deck  = GetDeck($player);
    $drawn = [];

    for ($i = 0; $i < intval($amount); $i++) {
        // Top of deck = FIRST non-removed entry (index 0). This matches the rest of the engine's
        // deck-top convention — DoScry, the look-at-top family (SOR_119/152/192), the test harness
        // topCardID, and the deck builder (first WithP1Deck = top) — so a card left or placed on
        // top is the next one drawn. (Previously this drew from the LAST index, the lone outlier.)
        $topIdx = null;
        for ($j = 0; $j < count($deck); $j++) {
            if (!isset($deck[$j]->removed) || !$deck[$j]->removed) { $topIdx = $j; break; }
        }
        // Empty deck (CR §6.1): you can't draw, so instead deal 3 damage to your base for EACH card
        // you would have drawn (the remaining $amount - $i), then stop. Per-card damage events (matching
        // the "3 damage … for each card" wording) so per-event caps/prevention (ASH_070, Shield Gate)
        // apply per card. Goldfish P2 (the practice-mode dummy) is exempt — it must never lose to deck-out.
        if ($topIdx === null) {
            $undrawn = intval($amount) - $i;
            if ($undrawn > 0 && !(SWUGameMode() === 'goldfish' && intval($player) === 2)) {
                for ($k = 0; $k < $undrawn; $k++) {
                    if (SWUGetGameWinner() !== 0) break;   // base defeated mid-deck-out → stop
                    SWUDealDamageToBase(3, intval($player));
                }
            }
            break;
        }

        $newObj = MZMove($player, "myDeck-$topIdx", "myHand");
        if ($newObj !== null) {
            if (function_exists('SWUTelemetryBumpCard')) SWUTelemetryBumpCard($player, $newObj->CardID ?? '', 'drawn');
            $hand = GetHand($player);
            for ($k = count($hand) - 1; $k >= 0; $k--) {
                if (!isset($hand[$k]->removed) || !$hand[$k]->removed) {
                    $drawn[] = "myHand-$k";
                    // Deck top slides into the hand. One per card drawn; the client staggers a
                    // multi-card draw by 60ms each and blocks only for the longest, so a 6-card
                    // opening hand costs ~780ms rather than 6 x 420ms.
                    SWUQueueZoneMoveAnim("myDeck-$topIdx", "myHand-$k", intval($player));
                    break;
                }
            }
        }
    }

    $playerID = $savedPID;
    // A draw reveals a hidden card to the drawing player; undoing back through it un-reveals that info,
    // so this action's snapshot needs opponent consent to undo in a public game (undo redesign).
    if (!empty($drawn)) MarkUndoRequiresConsent();
    // Per-phase "cards you've drawn this phase" counter (LAW_051 Beilert Valance). Action phase only;
    // cleared at RegroupPhaseStart.
    if (!empty($drawn) && GetCurrentPhase() === 'MAIN') {
        for ($d = 0; $d < count($drawn); $d++) AddGlobalEffects(intval($player), 'SWU_DREW_PHASE');
    }
    // Reactive "when a player draws 1+ cards during the action phase" hook (JTL_111 / SHD_184).
    if (!empty($drawn) && function_exists('_SWUOnPlayerDrew')) _SWUOnPlayerDrew(intval($player), count($drawn));
    // "When you draw THIS card during the action phase" hook (LOF_148 — needs the drawn card identities).
    if (!empty($drawn)) _SWUOnDrawLof148(intval($player), $drawn);
    return empty($drawn) ? "-" : (count($drawn) === 1 ? $drawn[0] : implode("&", $drawn));
}

// True if $player controls a leader OR base with the Aggression aspect (LOF_148's draw condition).
function _SWUControlsAggressionLeaderOrBase(int $player): bool {
    // The leader CARD never leaves the leader zone, so this covers it in every state — undeployed,
    // deployed as a unit, and attached to a host as a Pilot upgrade (a pilot keeps its own controller,
    // so your leader stays YOUR leader even after an opponent takes control of the host it is flying).
    foreach ([GetLeader($player) ?? [], GetBase($player) ?? []] as $zone) {
        foreach ($zone as $c) {
            if (!empty($c->removed)) continue;
            if (strpos(CardAspect($c->CardID ?? '') ?? '', 'Aggression') !== false) return true;
        }
    }
    // A unit you control that IS a leader unit is also "a leader you control", and it contributes its
    // OWN aspects — a Vehicle carrying a leader-Pilot upgrade becomes a leader unit, so an Aggression
    // Vehicle counts even when the leader flying it has no Aggression (user ruling 2026-08-07).
    // ⚠ Own the $playerID frame here — the caller sets it AFTER this gate runs, so a relative 'my'
    // lookup would otherwise resolve against the wrong seat.
    global $playerID; $savedPID = $playerID; $playerID = intval($player);
    $found = false;
    foreach (SWUAllUnits('my') as $mz) {
        $u = GetZoneObject($mz);
        if ($u === null || !empty($u->removed)) continue;
        if (intval($u->Controller ?? 0) !== intval($player)) continue;
        if (!IsLeaderUnit($u)) continue;
        if (strpos(CardAspect($u->CardID ?? '') ?? '', 'Aggression') !== false) { $found = true; break; }
    }
    $playerID = $savedPID;
    return $found;
}

// LOF_148 — "When you draw this card during the action phase: if you control an Aggression leader or
// base, you may reveal it from your hand. If you do, deal 2 damage to a unit and 2 damage to a base."
function _SWUOnDrawLof148(int $player, array $drawn): void {
    if (GetCurrentPhase() !== 'MAIN') return;                  // action phase only
    if (!_SWUControlsAggressionLeaderOrBase($player)) return;
    global $playerID; $savedPID = $playerID; $playerID = intval($player);
    foreach ($drawn as $mz) {
        $o = GetZoneObject($mz);
        if ($o !== null && empty($o->removed) && ($o->CardID ?? '') === 'LOF_148') {
            DecisionQueueController::AddDecision($player, 'YESNO', '-', 1,
                tooltip: "Reveal_LOF_148_to_deal_2_to_a_unit_and_2_to_a_base?");
            DecisionQueueController::AddDecision($player, 'CUSTOM', "LOF_148#0", 1);
        }
    }
    $playerID = $savedPID;
}

function DoResourceCard($player, $mzID) {
    global $playerID;
    $savedPID = $playerID;
    $playerID = intval($player);
    $newObj   = MZMove($player, $mzID, "myResources");
    if ($newObj !== null && function_exists('SWUTelemetryBumpCard')) SWUTelemetryBumpCard($player, $newObj->CardID ?? '', 'resourced');
    if ($newObj !== null) SWUKeepCreditTokensLast(intval($player)); // Credit tokens stay at the end
    $playerID = $savedPID;
    return $newObj !== null ? $mzID : "-";
}

function DoDiscardCard($player, $mzID) {
    global $playerID;
    $savedPID = $playerID;
    $playerID = intval($player);
    $fromHand = (strpos($mzID, 'Hand') !== false);
    $newObj   = MZMove($player, $mzID, "myDiscard");
    if ($fromHand && $newObj !== null && function_exists('SWUTelemetryBumpCard')) SWUTelemetryBumpCard($player, $newObj->CardID ?? '', 'discarded');
    // "When this card is discarded" handlers (LAW_206 That's a Rock). The forced-discard funnel
    // (SWUAddToDiscard) fires OnCardDiscarded; this self-chosen path went through MZMove and never
    // did — the inverse of the forced-discard-bypasses-Padmé bug. MZMove also leaves the discard
    // entry's From unset (AddDiscard stamps it on the other path) and the handlers gate on it, so
    // stamp the source zone first. Fire while still in the discarding player's frame.
    if ($newObj !== null) {
        if (($newObj->From ?? '') === '') {
            $newObj->From = $fromHand ? 'HAND' : (strpos($mzID, 'Deck') !== false ? 'DECK' : 'PLAY');
        }
        OnCardDiscarded(intval($player), $newObj->CardID ?? '', $newObj);
    }
    $playerID = $savedPID;
    // Per-phase counter of cards discarded from a player's hand (LAW_179 cost reduction). Cleared at
    // RegroupPhaseStart with the other per-phase flags.
    if ($fromHand && $newObj !== null) AddGlobalEffects(intval($player), 'SWU_DISCARDED_HAND');
    // "Discarded a card from your hand OR deck this phase" (LAW_076). Hand discards count here; deck
    // mills add it in SWUMillTopCard. (Excludes played events — those never route through DoDiscardCard.)
    if ($fromHand && $newObj !== null) AddGlobalEffects(intval($player), 'SWU_DISCARDED_PHASE');
    // SEC_016 Padmé Amidala — "When you discard 1 or more cards from your hand: …" (per-call; a single
    // effect discarding multiple cards over-triggers the deploy side — a rare edge).
    if ($fromHand && $newObj !== null && function_exists('_SWUSec016React')) _SWUSec016React(intval($player));
    // SHD_163 Migs Mayfeld — "When A player discards a card from their hand: you may deal 2 to a unit or
    // base. Once each round." Any player's hand-discard triggers it for each SHD_163 controller.
    if ($fromHand && $newObj !== null) _SWUShd163React();
    return $newObj !== null ? $mzID : "-";
}

// SHD_163 discard observer — fire for each player controlling an SHD_163 that hasn't used it this round.
function _SWUShd163React(): void {
    foreach ([1, 2] as $p) {
        if (GlobalEffectCount($p, 'SWU_SHD163_USED') > 0) continue;
        foreach (GetUnitsInPlay($p) as $u) {
            if (empty($u->removed) && ($u->CardID ?? '') === 'SHD_163' && !LostAbilities($u)) {
                AddTrigger($p, 'SHD_163', 'SHD_163', '');
                // FLUSH IT HERE. AddTrigger only bags the reaction; something else has to drain the bag.
                // On a card-PLAY discard the play ceremony happens to flush afterwards, so Migs worked by
                // ambience — but a discard made inside a LEADER ABILITY (cost or effect) finishes through
                // SWUAfterAction with no flush, so the bagged trigger was dropped at end of request and
                // Migs never fired. Same "bagged but never flushed" family as the token-creation Ambush.
                FlushTriggerBag($p);
                break;   // one Migs reaction per controller
            }
        }
    }
}

// Return the discard entry at $discardMzID (e.g. "myDiscard-2") to the player's
// hand. Used by SOR_101 ("return a unit that costs 2 or less from your discard").
function SWUReturnFromDiscardToHand($player, $discardMzID) {
    global $playerID;
    $savedPID = $playerID;
    $playerID = intval($player);
    $newObj   = MZMove($player, $discardMzID, "myHand");
    $playerID = $savedPID;
    return $newObj !== null;
}

// Return a card from ANY discard pile to its OWNER's hand (the discard pile's player owns its cards,
// CR 7.5). $discardMzID is relative to $player: "myDiscard-N" → $player's hand; "theirDiscard-N" →
// the opponent's hand (re-resolved from the opponent's "myDiscard" perspective). For "return an
// event from a discard pile to its owner's hand" (SOR_183).
function SWUReturnDiscardCardToOwnerHand(int $player, string $discardMzID): bool {
    $parts = explode('-', $discardMzID);
    $idx   = intval($parts[1] ?? 0);
    if (str_starts_with($discardMzID, 'theirDiscard')) {
        return SWUReturnFromDiscardToHand(GetOpponent($player), "myDiscard-{$idx}");
    }
    return SWUReturnFromDiscardToHand($player, $discardMzID);
}

// Return a resource (at $resourceMzID, relative to $player) to its OWNER's hand. Used by Lando
// (SOR_197) "return up to N friendly resources to their owners' hands". Caller batches removals and
// runs a single CleanupRemovedCards (indices shift per removal).
function SWUReturnResourceToHand(int $player, string $resourceMzID): bool {
    global $playerID;
    $saved = $playerID;
    $playerID = intval($player);
    $obj = GetZoneObject($resourceMzID);
    if (SWUObjGone($obj)) { $playerID = $saved; return false; }
    // Resource Owner is often 0 (unset, e.g. fixtures / freshly-resourced cards) — default to the
    // controlling player, else AddHand(0) silently drops the returned card (documented zone-Owner gotcha).
    $owner = intval($obj->Owner ?? 0);
    if ($owner <= 0) $owner = intval($player);
    $obj->removed = true;
    AddHand($owner, CardID:$obj->CardID);
    $playerID = $saved;
    return true;
}

// Returns TRUE when the discard was QUEUED as a choice on the discarding player's queue (hand > $numCards),
// FALSE when it happened INLINE (whole hand discarded, or nothing to discard).
// ⚠ A caller whose next step must observe WHAT was discarded has to branch on this. The queued form puts
// the pick on the OTHER player's queue, so a continuation queued on the caller's own queue runs FIRST and
// reads a pre-discard board (bug report #965, JTL_201 Ahsoka: the "if it's a unit" gate read whatever was
// already on top of the opponent's discard pile and offered its exhaust regardless). Queue the continuation
// behind their pick when this returns true; queue it normally when it returns false, since by then the
// discard has already landed. Do NOT unconditionally queue on the other player's queue either — a lone
// CUSTOM there never drains when that player is not otherwise acting.
function SWUDiscardCards(int $player, int $numCards, ?int $target = null): bool {
    // Twin Suns (Phase 3): $target lets a caller aim a specific opponent (for "each opponent discards"
    // loops); default = the single opponent, so all existing 2-player callers are unchanged.
    $opponent  = $target ?? OtherPlayer($player);
    $hand      = GetHand($opponent);
    $handCount = 0;
    foreach ($hand as $card) {
        if (isset($card->removed) && $card->removed) continue;
        $handCount++;
    }
    if ($handCount === 0) return false;

    if ($handCount <= $numCards) {
        global $playerID;
        $savedPID = $playerID;
        $playerID = $opponent;
        $discarded = false;
        foreach ($hand as $card) {
            if (isset($card->removed) && $card->removed) continue;
            $card->Remove();
            SWUAddToDiscard($opponent, $card->CardID, 'HAND'); // sets the LAW_179/LAW_076 counters
            $discarded = true;
        }
        $playerID = $savedPID;
        // SEC_016 Padmé "when you discard 1+ cards from your hand" — this forced-discard path bypasses
        // DoDiscardCard (which fires the Padmé reaction), so fire it here ONCE for the whole batch
        // (collective: one "discard N" event = one trigger).
        if ($discarded && function_exists('_SWUSec016React')) _SWUSec016React($opponent);
        return false;   // discarded INLINE — the result is already observable
    } else {
        for ($n = 0; $n < $numCards; $n++) {
            DecisionQueueController::AddDecision($opponent, "MZCHOOSE", "myHand", 1,
                tooltip:"Choose_card_to_discard");
            DecisionQueueController::AddDecision($opponent, "CUSTOM", "DISCARD_FROM_OWN_HAND|{$opponent}", 1);
        }
        // Fire the SEC_016 Padmé reaction ONCE after all chosen cards are discarded (collective trigger).
        DecisionQueueController::AddDecision($opponent, "CUSTOM", "SEC016_BATCH_REACT|{$opponent}", 1);
        return true;    // QUEUED on $opponent's queue — see the note on the signature
    }
}

// "$player keeps $keep cards of their choice, discards the rest of their hand" (SOR_174 Smoke and
// Cinders, "each player discards all but 2 of their choice"). Builds the keep-N MZMULTICHOOSE over
// $player's own hand; the follow-up SOR_174 discards every card NOT kept. No-op (no decision)
// when the hand already has ≤ $keep cards. Cleans removed entries FIRST so the spec's mzIDs match the
// compacted indices the resolver will see (the caster's just-played event lingers as a removed entry).
// Leaves $playerID = $player so the harness MZCountChoices resolves the relative mzIDs under $player.
function SWUKeepNDiscardRest(int $player, int $keep, string $tooltip): void {
    global $playerID;
    $playerID = intval($player);
    DecisionQueueController::CleanupRemovedCards();
    $hand = array_values(ZoneSearch("myHand"));
    if (count($hand) <= $keep) return;   // nothing to discard
    DecisionQueueController::AddDecision($player, "MZMULTICHOOSE", "{$keep}|{$keep}|" . implode("&", $hand), 1,
        tooltip:$tooltip);
    DecisionQueueController::AddDecision($player, "CUSTOM", "SOR_174#0|{$player}", 1);
}

// "Look at an opponent's hand" — logs a PRIVATE reveal (visible only to the acting player) of the
// opponent's hand, and returns the opponent's hand cards as MZCHOOSE targets from $player's
// perspective ("theirHand-N"). $filter (optional) restricts which cards are returned as targets
// (e.g. non-unit for SOR_201 Bodhi Rook) — the reveal still lists the WHOLE hand. Used by the
// "look at an opponent's hand [and discard …]" family (SOR_228, SOR_200, SOR_201).
function SWULookAtOpponentHand(int $player, ?callable $filter = null): array {
    global $playerID;
    $savedPID = $playerID; $playerID = intval($player);
    $opp     = OtherPlayer(intval($player));
    $oppHand = GetHand($opp);
    $refs = []; $targets = [];
    foreach ($oppHand as $i => $card) {
        if (!empty($card->removed)) continue;
        $refs[] = GameLogCardRef($card->CardID);
        if ($filter === null || $filter($card->CardID)) $targets[] = "theirHand-$i";
    }
    $msg = 'P' . intval($player) . " looked at P{$opp}'s hand: " . (empty($refs) ? '(empty)' : implode(', ', $refs));
    // For now (2-player) the reveal is visible to both players (effectively public). In a future
    // 4-player Twin Suns format this should be scoped to just the two players involved.
    AddGameLogEntry('REVEAL', $msg, 'ALL');
    $playerID = $savedPID;
    return $targets;
}

// Log a "P looked at an opponent's resources: …" REVEAL entry for the given resource mzIDs (the cards
// the player looked at) — so a "look at an opponent's resources" effect (SEC_242 Elia Kane, LAW_066) is
// scrollable in the game log, like SWULookAtOpponentHand. Visible to both players (2-player simplification).
function SWULogResourceReveal(int $player, array $resMzIDs): void {
    global $playerID;
    $savedPID = $playerID; $playerID = intval($player);
    $opp  = OtherPlayer(intval($player));
    $refs = [];
    foreach ($resMzIDs as $mz) {
        $o = GetZoneObject($mz);
        if ($o !== null && empty($o->removed)) $refs[] = GameLogCardRef($o->CardID ?? '');
    }
    if (!empty($refs)) {
        AddGameLogEntry('REVEAL', 'P' . intval($player) . " looked at P{$opp}'s resources: " . implode(', ', $refs), 'ALL');
    }
    $playerID = $savedPID;
}

// ── Generic resource-reveal shuffler (CR resource-shuffling) ────────────────────
// "Reveal/look at $count of $ownerPlayer's resources." The resource ORDER isn't fixed (a player may
// shuffle their resources), so the engine picks which $count to reveal — ordered for the ACTIVE player's
// benefit, then random among equal-priority cards. Excludes Credit tokens (not resources). Returns the
// chosen mzIDs (in the active player's frame) and logs the reveal. Reusable by SEC_242 Elia Kane,
// SHD_114 Scanning Officer, etc.
//   Priority (descending desirability of being revealed, from the active player's POV):
//     1. READY resources first — so a defeat-and-replace doesn't swap an EXHAUSTED resource for a ready
//        one from the deck (a free resource for the owner). Side effect: this incentivizes keeping your
//        Smuggle/Plot cards exhausted so they aren't the ones revealed/defeated (e.g. vs SHD_114).
//     2. Resources OWNED by the active player first — a defeated one returns to the active player's
//        discard (recur it).
//     3. Random among ties (anti-exploit — the owner can't pre-arrange a known order).
function SWURevealResources(int $activePlayer, int $ownerPlayer, int $count): array {
    global $playerID;
    $saved = $playerID; $playerID = intval($activePlayer);
    $rel = ($ownerPlayer === $activePlayer) ? 'myResources' : 'theirResources';
    $pool = [];
    foreach (ZoneSearch($rel, null) as $mz) {
        $o = GetZoneObject($mz);
        if (SWUObjGone($o)) continue;
        if (SWUIsCreditToken($o->CardID ?? '')) continue;   // Credit tokens aren't resources
        $pool[] = [
            'mz'    => $mz,
            'ready' => (intval($o->Status ?? 0) === 1) ? 1 : 0,
            'own'   => (intval($o->Owner ?? 0) === intval($activePlayer)) ? 1 : 0,
            'rand'  => mt_rand(),
        ];
    }
    usort($pool, function($a, $b) {
        if ($a['ready'] !== $b['ready']) return $b['ready'] - $a['ready']; // ready first
        if ($a['own']   !== $b['own'])   return $b['own']   - $a['own'];   // active-player-owned first
        return $a['rand'] <=> $b['rand'];                                   // random tiebreak
    });
    $chosen = array_slice(array_map(fn($e) => $e['mz'], $pool), 0, max(0, $count));
    SWULogResourceReveal(intval($activePlayer), $chosen);
    $playerID = $saved;
    return $chosen;
}

// Present the opponent's WHOLE hand to $player as an information-only acknowledge popup (card
// images + an OK button), exactly like SOR_228 Viper Probe Droid. No-op on an empty hand.
// The hand is SNAPSHOTTED into the popup param at call time, so the saved state is shown verbatim
// even if a later-resolving decision mutates the hand — call this while the hand is in the state
// you want shown (e.g. BEFORE a pending auto-discard) and the player still sees the saved hand.
// Used when a "look at an opponent's hand" effect would otherwise never surface the hand to the
// player — e.g. SOR_201 Bodhi Rook when the discard auto-resolves (0 or 1 non-unit target, so no
// MZCHOOSE is shown). When an MZCHOOSE *is* shown, it already presents the hand, so don't call this.
function SWUQueueShowOpponentHand(int $player): void {
    global $playerID;
    $savedPID = $playerID; $playerID = intval($player);
    $opp     = OtherPlayer(intval($player));
    $oppHand = GetHand($opp);
    $cards = [];
    foreach ($oppHand as $card) {
        if (empty($card->removed)) $cards[] = '@' . $card->CardID;
    }
    $playerID = $savedPID;
    if (empty($cards)) return;                   // empty hand → nothing to show
    $param = implode('&', $cards) . '&OK';       // "@CardID&@CardID&…&OK" — images then an OK button
    DecisionQueueController::AddDecision($player, "OPTIONCHOOSE", $param, 1, "Opponent's_hand");
    DecisionQueueController::AddDecision($player, "CUSTOM", "ACK", 1);
}

// Present the opponent's WHOLE deck to $player as an information-only acknowledge popup (card images +
// an OK button), the deck counterpart of SWUQueueShowOpponentHand. Used by "search a player's deck"
// effects (e.g. JTL_041 Annihilator) so the searching player actually sees the zone they searched.
// Snapshots the deck into the popup param at call time, so call it while the deck is in the state you
// want shown (e.g. BEFORE a name-hunt discard/shuffle). No-op on an empty deck.
function SWUQueueShowOpponentDeck(int $player): void {
    global $playerID;
    $savedPID = $playerID; $playerID = intval($player);
    $opp     = OtherPlayer(intval($player));
    $oppDeck = GetDeck($opp);
    $cards = [];
    foreach ($oppDeck as $card) {
        if (empty($card->removed)) $cards[] = '@' . $card->CardID;
    }
    $playerID = $savedPID;
    if (empty($cards)) return;                   // empty deck → nothing to show
    $param = implode('&', $cards) . '&OK';       // "@CardID&@CardID&…&OK" — images then an OK button
    DecisionQueueController::AddDecision($player, "OPTIONCHOOSE", $param, 1, "Opponent's_deck");
    DecisionQueueController::AddDecision($player, "CUSTOM", "ACK", 1);
}

// SOR_062 Regional Governor: "While this unit is in play, opponents can't play the named card."
// The named card is stored as a GlobalEffects flag "SWU_NAMEBLOCK|{uid}|{titleNoSpaces}" on the
// Governor's controller (GlobalEffects serialize space-delimited, so the title's spaces are encoded
// to underscores). A play by $player is blocked when an OPPONENT controls a still-in-play unit that
// named this card's title. Stale flags (the naming unit has left play) are removed lazily here, so
// the block ends automatically when the unit leaves — no per-leave-path hook needed.
function _SWUUnitInPlayWithUID(int $player, int $uid): bool {
    if ($uid === 0) return false;
    foreach ([GetGroundArena($player), GetSpaceArena($player)] as $arena) {
        foreach ($arena as $u) {
            if (empty($u->removed) && intval($u->UniqueID ?? 0) === $uid) return true;
        }
    }
    return false;
}

// Cards whose text says "This card can't be played from your hand." — a HAND-only play restriction;
// they may still be played from the resource zone (Plot/Smuggle) or any non-hand source. Gated in
// ActivateCard on the source mzID and in the hand-glow affordability check. Keyed by CardID.
function _SWUCantPlayFromHand(string $cardID): bool {
    static $cards = [
        'SEC_053' => true,   // One in a Million (Plot event)
    ];
    return isset($cards[$cardID]);
}

function SWUCardPlayBlocked(int $player, string $cardID): bool {
    // SEC_145 Confidence in Victory — "Play only as your first action in the action phase."
    if ($cardID === 'SEC_145' && GlobalEffectCount($player, 'SWU_ACTED_PHASE') > 0) return true;
    // SEC_126 Trade Route Taxation — "that opponent can't play events for this phase." The per-phase
    // SWU_EVENT_LOCK flag sits on the blocked player; it blocks only Event-type cards.
    if (GlobalEffectCount($player, 'SWU_EVENT_LOCK') > 0
        && stripos(CardType($cardID) ?? '', 'Event') !== false) return true;
    $titleEnc = str_replace(' ', '_', (string)(CardTitle($cardID) ?? ''));
    if ($titleEnc === '') return false;
    // LAW_243 Transmission Jamming — "Cards with that name can't be played this phase." Phase-duration
    // name-block, set by ANY player (applies to all); cleared at RegroupPhaseStart. Twin Suns: check the
    // player plus every opponent (2-player → [self, the one opponent], byte-identical).
    foreach (array_merge([$player], OpponentsOf($player)) as $pp) {
        if (GlobalEffectCount($pp, "SWU_NAMEBLOCK_PHASE|{$titleEnc}") > 0) return true;
    }
    // A unit-sourced name-block (SWU_NAMEBLOCK|uid|titleEnc) set by ANY opponent blocks the card.
    $prefix  = 'SWU_NAMEBLOCK|';
    $blocked = false;
    foreach (OpponentsOf($player) as $opp) {     // 2-player: the one opponent
        $ge = &GetGlobalEffects($opp);
        for ($i = count($ge) - 1; $i >= 0; $i--) {
            $flag = (string)($ge[$i]->CardID ?? '');
            if (!str_starts_with($flag, $prefix)) continue;
            $parts = explode('|', $flag);        // [SWU_NAMEBLOCK, uid, titleEnc]
            if (!_SWUUnitInPlayWithUID($opp, intval($parts[1] ?? 0))) {
                array_splice($ge, $i, 1);        // naming unit left play → stale flag, drop it
                continue;
            }
            if (($parts[2] ?? '') === $titleEnc) $blocked = true;
        }
        unset($ge);
    }
    return $blocked;
}

// ASH_208 Sabine Wren — "When 1 or more upgrades attach to this unit (including from Shielded): you may
// exhaust a ground unit." Called from every attach point (DoGiveShieldToken + _SWUFinalizeUpgradeAttach).
// Returns true if it queued the optional exhaust (so the attach finalizer doesn't early-finish the action).
function _SWUAsh208OnUpgradeAttach(int $player, $hostObj): bool {
    if (SWUObjGone($hostObj) || ($hostObj->CardID ?? '') !== 'ASH_208') return false;
    $ctrl = intval($hostObj->Controller ?? $player);
    global $playerID; $sp = $playerID; $playerID = $ctrl;
    $tg = array_merge(ZoneSearch('myGroundArena', AnyUnitFilter), ZoneSearch('theirGroundArena', AnyUnitFilter));
    if (empty($tg)) { $playerID = $sp; return false; }
    SWUQueueMayChooseTarget($ctrl, $tg, "Exhaust_a_ground_unit?", "Choose_a_ground_unit", "EXHAUST_UNIT");
    $playerID = $sp;
    return true;
}

// $grantTag: stamps an IDENTITY on the created token so a later effect can find THAT token again — even
// after it has been moved to a different host. Needed by any card that says "defeat THAT token" (SHD_225
// Jetpack). Without it a grant can only be recorded as "some Shield on host UID N", which defeats the
// wrong token once the host has more than one, and loses track entirely once the token moves.
function DoGiveShieldToken($player, $targetMZ, string $grantTag = '') {
    global $playerID;
    $savedPID = $playerID;
    $playerID = $player;
    $obj = GetZoneObject($targetMZ);
    $playerID = $savedPID;
    if ($obj === null || (isset($obj->removed) && $obj->removed)) return "-";
    if (!is_array($obj->Subcards)) $obj->Subcards = [];
    $obj->Subcards[] = (object)[
        'CardID'      => 'SOR_T02',
        'Owner'       => $player,
        'Controller'  => $player,
        'TurnEffects' => [],
        'IsPilot'     => false,
        'GrantTag'    => $grantTag,
    ];
    AddGlobalEffects(intval($player), 'SWU_CREATED_TOKEN'); // LAW_016 "if you created a token this phase"
    _SWUAsh208OnUpgradeAttach(intval($player), $obj);   // a Shield is an upgrade attaching (ASH_208)
    return $targetMZ;
}

// Find and detach ONE Shield token carrying $tag, from whatever unit is currently hosting it, anywhere on
// the board. Returns whether one was found. The board-wide scan is the point: a tagged token may have
// been MOVED to another host since it was created, and "defeat that token" has to follow it.
function _SWUTakeTaggedShieldToken(string $tag): bool {
    if ($tag === '') return false;
    for ($p = 1; $p <= SeatCountForGame(); $p++) {
        foreach ([GetGroundArena($p), GetSpaceArena($p)] as $zone) {
            foreach ($zone as $host) {
                if ($host === null || !empty($host->removed) || !is_array($host->Subcards ?? null)) continue;
                foreach ($host->Subcards as $k => $sub) {
                    $cid = is_array($sub) ? ($sub['CardID'] ?? '')      : ($sub->CardID ?? '');
                    $rem = is_array($sub) ? !empty($sub['removed'])     : !empty($sub->removed);
                    $tg  = is_array($sub) ? ($sub['GrantTag'] ?? '')    : ($sub->GrantTag ?? '');
                    if ($rem || $cid !== 'SOR_T02' || $tg !== $tag) continue;
                    array_splice($host->Subcards, $k, 1);
                    return true;
                }
            }
        }
    }
    return false;
}

// $fireAsh208: fire Sabine ASH_208's "when 1+ upgrades attach" observer (default true — one Experience = one
// attach event). A multi-token giver (LOF_239 gives 2 at once) passes false on each token and fires the
// observer ONCE itself after the batch, so "1 OR MORE upgrades attach" is a single trigger, not one per token.
function DoGiveExperienceToken($player, $targetMZ, bool $fireAsh208 = true) {
    global $playerID;
    $savedPID = $playerID;
    $playerID = $player;
    $obj = GetZoneObject($targetMZ);
    $playerID = $savedPID;
    if ($obj === null || (isset($obj->removed) && $obj->removed)) return "-";
    if (!is_array($obj->Subcards)) $obj->Subcards = [];
    $obj->Subcards[] = (object)[
        'CardID'      => 'SOR_T01',
        'Owner'       => $player,
        'Controller'  => $player,
        'TurnEffects' => [],
        'IsPilot'     => false,
    ];
    AddGlobalEffects(intval($player), 'SWU_CREATED_TOKEN'); // LAW_016 "if you created a token this phase"
    if ($fireAsh208) _SWUAsh208OnUpgradeAttach(intval($player), $obj);   // an Experience token is an upgrade attaching (ASH_208)
    return $targetMZ;
}

// Give one Advantage token (ASH_T02 — a +1/+0 Token Upgrade) to a unit. Mirrors DoGiveExperienceToken.
// Consumed (defeated) when the host's attack OR defense ends (see _SWUDefeatAllAdvantageTokens).
function DoGiveAdvantageToken($player, $targetMZ) {
    global $playerID;
    $savedPID = $playerID;
    $playerID = $player;
    $obj = GetZoneObject($targetMZ);
    $playerID = $savedPID;
    if ($obj === null || (isset($obj->removed) && $obj->removed)) return "-";
    if (!is_array($obj->Subcards)) $obj->Subcards = [];
    $obj->Subcards[] = (object)[
        'CardID'      => 'ASH_T02',
        'Owner'       => $player,
        'Controller'  => $player,
        'TurnEffects' => [],
        'IsPilot'     => false,
    ];
    AddGlobalEffects(intval($player), 'SWU_CREATED_TOKEN'); // LAW_016 "if you created a token this phase"
    return $targetMZ;
}

// Generic token-upgrade attach (HMW_T02 Weakness, and any future token upgrade) — the arbitrary-CardID
// generalisation the hardcoded DoGiveShieldToken/DoGiveExperienceToken/DoGiveAdvantageToken lacked. The
// token's Owner/Controller follow the HOST's controller (an upgrade belongs to the unit it is attached to),
// so a Weakness given to an ENEMY unit is correctly an enemy-controlled upgrade. The token's stat modifier
// (e.g. Weakness -1/-1) flows through the normal upgrade stat loop, controller-agnostic. Returns $targetMZ
// or "-" if the host is gone.
function DoGiveTokenUpgrade($player, $targetMZ, string $tokenCardID) {
    global $playerID;
    $savedPID = $playerID;
    $playerID = $player;
    $obj = GetZoneObject($targetMZ);
    $playerID = $savedPID;
    if ($obj === null || (isset($obj->removed) && $obj->removed)) return "-";
    if (!is_array($obj->Subcards)) $obj->Subcards = [];
    $hostCtrl = intval($obj->Controller ?? $player);
    $obj->Subcards[] = (object)[
        'CardID'      => $tokenCardID,
        'Owner'       => $hostCtrl,
        'Controller'  => $hostCtrl,
        'TurnEffects' => [],
        'IsPilot'     => false,
    ];
    AddGlobalEffects(intval($player), 'SWU_CREATED_TOKEN'); // LAW_016 "if you created a token this phase"
    _SWUAsh208OnUpgradeAttach(intval($player), $obj);       // self-gates to ASH_208 Sabine hosts
    return $targetMZ;
}

// Defeat ALL Advantage tokens (ASH_T02 subcards) on a unit — the token's "When attached unit's attack
// or defense ends: Defeat this upgrade." Tokens are set aside, not discarded (no WhenDefeated). No-op on
// a non-unit mzID (e.g. a base target). Returns the number removed.
function _SWUDefeatAllAdvantageTokens($targetMZ): int {
    $obj = GetZoneObject($targetMZ);
    if (SWUObjGone($obj) || !is_array($obj->Subcards ?? null)) return 0;
    // ASH_149 Eviscerator — "Advantage tokens on friendly units … aren't defeated after combat." Skip the
    // post-combat shed for any unit whose controller has an Eviscerator in play.
    $ctrl149 = intval($obj->Controller ?? 0);
    if ($ctrl149 > 0 && _SWUControlsCardInPlay($ctrl149, 'ASH_149')) return 0;
    $removed = 0;
    foreach ($obj->Subcards as $i => $sub) {
        $cid = is_array($sub) ? ($sub['CardID'] ?? '') : ($sub->CardID ?? '');
        $rem = is_array($sub) ? !empty($sub['removed']) : !empty($sub->removed);
        if (!$rem && $cid === 'ASH_T02') { unset($obj->Subcards[$i]); $removed++; }
    }
    if ($removed > 0) $obj->Subcards = array_values($obj->Subcards);
    return $removed;
}

// Defeat ALL upgrades on a unit (CR 9.3): non-token upgrades → owner's discard; token upgrades (Shield/
// Experience/Advantage) → set aside. Captives are not upgrades and are left intact. Returns count removed.
// Shared "a friendly (real, non-token) upgrade was defeated" observer — called from BOTH upgrade-defeat
// points (SWUDefeatUpgrade for explicit defeats, _SWUDefeatAllUpgradesOn for host-leaves-play). $controller
// is the upgrade's controller; $owner is its owner; $hostObj is the unit it was attached to.
function _SWUOnUpgradeDefeated(int $controller, string $cardID, $hostObj, int $owner): void {
    if ($controller <= 0) return;
    AddGlobalEffects($controller, 'SWU_FRIENDLY_UPGRADE_DEFEATED');   // ASH_039 phase flag
    // ASH_055 Blade of Talzin — "When Defeated: if this upgrade was on a friendly Night unit, return it from
    // your discard pile to your hand." It was just discarded; pull the most recent copy back to hand.
    if ($cardID === 'ASH_055' && $hostObj !== null && TraitContains($hostObj, 'Night')) {
        $disc = &GetDiscard($owner);
        for ($i = count($disc) - 1; $i >= 0; $i--) {
            if (!empty($disc[$i]->removed)) continue;
            if (($disc[$i]->CardID ?? '') === 'ASH_055') {
                $disc[$i]->removed = true;
                DecisionQueueController::CleanupRemovedCards();
                AddHand($owner, CardID: 'ASH_055');
                break;
            }
        }
    }
    // ASH_161 Zeb Orrelios — "When a friendly upgrade is defeated: deal 1 damage to a base." (Controller's.)
    // The OR-clause covers Zeb's OWN upgrades being defeated as Zeb himself leaves play (combat/ability): the
    // live in-play count has already dropped Zeb, but his ability existed when the upgrade was defeated
    // (CR last-known-information), so it still fires — once per own upgrade.
    if (_SWUControlsCardInPlay($controller, 'ASH_161')
        || ($hostObj !== null && ($hostObj->CardID ?? '') === 'ASH_161')) {
        global $playerID; $sp = $playerID; $playerID = $controller;
        SWUOfferBaseTarget($controller, ['continuation'=>'DEAL_BASE_DAMAGE','amount'=>1,'prompt'=>"Deal_1_damage_to_a_base"]);
        $playerID = $sp;
    }
}

function _SWUDefeatAllUpgradesOn($targetMZ): int {
    $obj = GetZoneObject($targetMZ);
    if (SWUObjGone($obj) || !is_array($obj->Subcards ?? null)) return 0;
    $owner = intval($obj->Owner ?? $obj->Controller ?? 0);
    $removed = 0;
    foreach ($obj->Subcards as $i => $sub) {
        $cid       = is_array($sub) ? ($sub['CardID'] ?? '')     : ($sub->CardID ?? '');
        $rem       = is_array($sub) ? !empty($sub['removed'])     : !empty($sub->removed);
        $isCaptive = is_array($sub) ? !empty($sub['IsCaptive'])   : !empty($sub->IsCaptive);
        $subOwner  = is_array($sub) ? intval($sub['Owner'] ?? $owner) : intval($sub->Owner ?? $owner);
        if ($rem || $isCaptive || $cid === '') continue;
        if (strpos(strtolower(CardType($cid) ?? ''), 'token') === false) {
            SWUAddToDiscard($subOwner > 0 ? $subOwner : $owner, $cid, 'PLAY');
            _SWUOnUpgradeDefeated(intval($obj->Controller ?? $owner), $cid, $obj, $subOwner > 0 ? $subOwner : $owner);
        }
        unset($obj->Subcards[$i]); $removed++;
    }
    if ($removed > 0) $obj->Subcards = array_values($obj->Subcards);
    return $removed;
}

// Defeat ONE upgrade subcard of a specific CardID on a unit (CR 9.3): non-token → owner's discard, token
// → set aside. Returns true if one was removed. Used for "defeat this upgrade" (ASH_085 Grav Charge).
function _SWUDefeatNamedUpgrade($obj, string $upgradeCardID): bool {
    if (SWUObjGone($obj) || !is_array($obj->Subcards ?? null)) return false;
    $owner = intval($obj->Owner ?? $obj->Controller ?? 0);
    foreach ($obj->Subcards as $i => $sub) {
        $cid = is_array($sub) ? ($sub['CardID'] ?? '') : ($sub->CardID ?? '');
        $rem = is_array($sub) ? !empty($sub['removed']) : !empty($sub->removed);
        if ($rem || $cid !== $upgradeCardID) continue;
        $subOwner = is_array($sub) ? intval($sub['Owner'] ?? $owner) : intval($sub->Owner ?? $owner);
        if (strpos(strtolower(CardType($cid) ?? ''), 'token') === false) {
            SWUAddToDiscard($subOwner > 0 ? $subOwner : $owner, $cid, 'PLAY');
        }
        unset($obj->Subcards[$i]);
        $obj->Subcards = array_values($obj->Subcards);
        return true;
    }
    return false;
}

// Defeat ONE Advantage token (ASH_T02 subcard) on a unit. Returns true if one was removed.
function _SWUDefeatOneAdvantageToken($targetMZ): bool {
    $obj = GetZoneObject($targetMZ);
    if (SWUObjGone($obj) || !is_array($obj->Subcards ?? null)) return false;
    foreach ($obj->Subcards as $i => $sub) {
        $cid = is_array($sub) ? ($sub['CardID'] ?? '') : ($sub->CardID ?? '');
        $rem = is_array($sub) ? !empty($sub['removed']) : !empty($sub->removed);
        if (!$rem && $cid === 'ASH_T02') { array_splice($obj->Subcards, $i, 1); return true; }
    }
    return false;
}

// Defeat one Experience token (SOR_T01 subcard) on a unit. Returns true if one was removed.
// Reusable for "defeat an Experience token on it/a unit" (LOF_156 self-attrition, LOF_082 Vaneé).
function SWUDefeatExperienceToken($targetMZ): bool {
    $obj = GetZoneObject($targetMZ);
    if (SWUObjGone($obj) || !is_array($obj->Subcards ?? null)) return false;
    foreach ($obj->Subcards as $i => $sub) {
        $cid = is_array($sub) ? ($sub['CardID'] ?? '') : ($sub->CardID ?? '');
        $rem = is_array($sub) ? !empty($sub['removed']) : !empty($sub->removed);
        if (!$rem && $cid === 'SOR_T01') {
            array_splice($obj->Subcards, $i, 1); // tokens are set aside, not discarded
            return true;
        }
    }
    return false;
}

// DoCaptureUnit — ChoiceFunction for the CaptureUnit(capturingMZ, capturedMZ) macro (GameSchema.txt).
// Places the captured unit face-down as a captive subcard under the capturing unit (CR 8.34).
// The captured unit's arena entry is marked removed; its CardID/Owner/Controller are preserved
// in an IsCaptive subcard so RescueUnit can return it later.
// Per CR 8.34.1: defeats the captured unit's non-captive upgrades, fires leave-play reactions
// (Boba SOR_015, SWU_ENEMY_LEFT_PLAY), and offers Bounty to the capturing player.
function DoCaptureUnit($player, $capturingMZ, $capturedMZ) {
    global $playerID;
    $savedPID = $playerID;
    $playerID = intval($player);

    $captor   = GetZoneObject($capturingMZ);
    $captive  = GetZoneObject($capturedMZ);

    $playerID = $savedPID;

    if ($captor === null || ($captor->removed ?? false)) return "-";
    if ($captive === null || ($captive->removed ?? false)) return "-";

    // "Can't be captured by enemy card abilities" (SHD_187 / TWI_220). Capture is always ability-driven;
    // block when the captor belongs to an opponent of the captive's controller.
    if (intval($player) !== intval($captive->Controller ?? $player) && SWUAvoidsCapture($captive)) return "-";

    // SHD_170 IG-11 — "If this unit would be captured, defeat him and deal 3 damage to each enemy ground
    // unit instead." ABSOLUTE replacement — fires for ANY captor, enemy OR friendly. (DJ SEC_018 plays a
    // unit from your hand and has a FRIENDLY unit capture it, so IG-11 can be captured by its own
    // controller.) "Each enemy ground unit" = the ground units of IG-11's CONTROLLER's opponent — for an
    // enemy capture that opponent IS the captor, so the result matches the old capturer-frame version.
    if (($captive->CardID ?? '') === 'SHD_170') {
        $igEnemy = OtherPlayer(intval($captive->Controller ?? $captive->Owner ?? $player));
        SWUDefeatUnit(intval($player), $capturedMZ);   // capturedMZ is in the capturer's frame
        // Resolve "each enemy ground unit" in the IG-11-opponent's frame so the found mzIDs and the damage
        // calls agree.
        $savedPID2 = $playerID; $playerID = $igEnemy;
        $uids = [];
        foreach (ZoneSearch('myGroundArena', AnyUnitFilter) as $mz) {
            $o = GetZoneObject($mz);
            if ($o !== null && empty($o->removed)) $uids[] = intval($o->UniqueID ?? 0);
        }
        foreach ($uids as $uid) {
            $playerID = $igEnemy;
            $mz = SWUFindMzByUID($uid);
            if ($mz !== null) SWUDealDamageToUnit($mz, 3, $igEnemy);
        }
        $playerID = $savedPID2;
        return "-";
    }

    // Tokens can't be captured — a token that would be captured CEASES (set aside; it can never become
    // a captive subcard). JUDGE RULING 2026-08-13: this is NOT a defeat — no When-Defeated observers,
    // no defeat flags; it still counts as having left play (leave-play reactions fire as non-defeat).
    if (strpos(strtolower(CardType($captive->CardID) ?? ''), 'token') !== false) {
        _SWUCeaseTokenUnit(intval($player), $capturedMZ);
        return "-";
    }

    // Record the captured unit's identity before we remove it.
    // TWI_116 Clone — a captured Clone copy is stored as the REAL card (TWI_116); the printed copy only
    // exists while in play. (Ruling: a rescued Clone re-chooses a copy on re-entry — not yet wired here;
    // it currently returns as a plain Clone, a documented edge for the rare capture-then-rescue case.)
    $cardID     = !empty($captive->IsClone) ? 'TWI_116' : $captive->CardID;
    $owner      = intval($captive->Owner ?? $player);
    $controller = intval($captive->Controller ?? $owner);

    // CR 8.34.1: defeat all non-captive, non-removed upgrades on the captured unit before capture.
    // Tokens are set aside (removed from game); non-tokens go to their owner's discard.
    // Snapshot the GRANTED bounties BEFORE the upgrades below are defeated and stripped — the grant
    // lives on the upgrade, so reading it after the strip finds nothing (the defeat path snapshots at
    // the equivalent point for the same reason).
    $grantedBounties = _SWUGrantedBountyRewards($captive, $cardID, $controller);
    // Mirrors the upgrade-defeat pattern in SWUBounceUnit.
    if (!empty($captive->Subcards) && is_array($captive->Subcards)) {
        foreach ($captive->Subcards as $sub) {
            $isCaptive = is_array($sub) ? !empty($sub['IsCaptive']) : !empty($sub->IsCaptive);
            $isRemoved = is_array($sub) ? !empty($sub['removed'])   : !empty($sub->removed);
            if ($isCaptive || $isRemoved) continue;
            $subCardID = is_array($sub) ? ($sub['CardID'] ?? '') : ($sub->CardID ?? '');
            $subOwner  = is_array($sub) ? intval($sub['Owner'] ?? $owner) : intval($sub->Owner ?? $owner);
            if ($subCardID === '') continue;
            if (strpos(strtolower(CardType($subCardID) ?? ''), 'token') === false) {
                SWUAddToDiscard($subOwner, $subCardID, 'PLAY');
                // A captured unit's upgrades are DEFEATED (CR 8.34.1) — fire the friendly-upgrade-defeated
                // observer like the bounce/host-leaves-play paths, so ASH_161 Zeb (incl. his OWN upgrades as
                // he is captured, via the $hostObj===ASH_161 OR-clause), ASH_039, and ASH_055 all react.
                _SWUOnUpgradeDefeated($controller, $subCardID, $captive, $subOwner);
            }
        }
        // Clear all non-captive subcards (upgrades have been defeated above).
        $remaining = [];
        foreach ($captive->Subcards as $sub) {
            $isCaptive = is_array($sub) ? !empty($sub['IsCaptive']) : !empty($sub->IsCaptive);
            if ($isCaptive) $remaining[] = $sub;
        }
        $captive->Subcards = $remaining;
    }

    // CR 8.34.4: if the unit being captured was itself guarding captured units, rescue those
    // captives first (the unit leaving play triggers rescue of its own captives).
    SWURescueCaptivesOf($captive);

    // Remove the captured unit from its arena zone.
    $captive->removed = true;

    // Attach the captured unit as a captive subcard on the captor.
    if (!is_array($captor->Subcards)) $captor->Subcards = [];
    $captor->Subcards[] = (object)[
        'CardID'      => $cardID,
        'Owner'       => $owner,
        'Controller'  => $controller,
        'TurnEffects' => [],
        'IsPilot'     => false,
        'IsCaptive'   => true,
    ];

    // Fire leave-play reactions and Bounty for the capture.
    CollectCaptureTriggers(intval($player), $controller, $cardID, $captive, $grantedBounties);

    return $capturingMZ;
}

// SEC_195 Arrest — "your base captures an enemy non-leader unit." Bases have no Subcards, so the captive
// can't be attached like a unit-captor's. It's removed from play (mirroring DoCaptureUnit's CR 8.34 steps)
// and recorded in a GlobalEffects flag on the capturing player; _SWURescueBaseCaptives (RegroupPhaseStart)
// returns it to its owner. Returns true on a successful capture.
function _SWUBaseCaptureUnit(int $player, string $capturedMZ): bool {
    global $playerID;
    $savedPID = $playerID; $playerID = intval($player);
    $captive = GetZoneObject($capturedMZ);
    if (SWUObjGone($captive)) { $playerID = $savedPID; return false; }
    // "Can't be captured by enemy card abilities" (SHD_187 / TWI_220).
    if (intval($player) !== intval($captive->Controller ?? $player) && SWUAvoidsCapture($captive)) { $playerID = $savedPID; return false; }
    // Tokens can't be captured — the token CEASES (same judge ruling as DoCaptureUnit: not a defeat,
    // no When-Defeated observers; leave-play reactions fire as non-defeat). No base-captive is stored,
    // so _SWURescueBaseCaptives won't return a ceased token at regroup.
    if (strpos(strtolower(CardType($captive->CardID) ?? ''), 'token') !== false) {
        _SWUCeaseTokenUnit(intval($player), $capturedMZ);
        $playerID = $savedPID;
        return false;
    }
    $cardID     = $captive->CardID;
    $owner      = intval($captive->Owner ?? $player);
    $controller = intval($captive->Controller ?? $owner);
    // Snapshot the GRANTED bounties before the upgrades carrying them are defeated below.
    $grantedBounties = _SWUGrantedBountyRewards($captive, $cardID, $controller);
    // CR 8.34.1: defeat all non-captive, non-removed upgrades before capture (mirror DoCaptureUnit).
    if (!empty($captive->Subcards) && is_array($captive->Subcards)) {
        foreach ($captive->Subcards as $sub) {
            $isCaptive = is_array($sub) ? !empty($sub['IsCaptive']) : !empty($sub->IsCaptive);
            $isRemoved = is_array($sub) ? !empty($sub['removed'])   : !empty($sub->removed);
            if ($isCaptive || $isRemoved) continue;
            $subCardID = is_array($sub) ? ($sub['CardID'] ?? '') : ($sub->CardID ?? '');
            $subOwner  = is_array($sub) ? intval($sub['Owner'] ?? $owner) : intval($sub->Owner ?? $owner);
            if ($subCardID === '') continue;
            if (strpos(strtolower(CardType($subCardID) ?? ''), 'token') === false) {
                SWUAddToDiscard($subOwner, $subCardID, 'PLAY');
                _SWUOnUpgradeDefeated($controller, $subCardID, $captive, $subOwner);   // fire upgrade-defeated (ASH_161/039/055)
            }
        }
    }
    SWURescueCaptivesOf($captive);                 // CR 8.34.4: rescue any units IT was guarding
    $captive->removed = true;
    DecisionQueueController::CleanupRemovedCards();
    AddGlobalEffects(intval($player), 'SWU_BASECAPTIVE|' . $cardID . '|' . $owner);  // base captive store
    CollectCaptureTriggers(intval($player), $controller, $cardID, $captive, $grantedBounties);
    $playerID = $savedPID;
    return true;
}

// A base captive (SEC_195 Arrest) is stored in a GlobalEffects flag, NOT as a subcard of a unit in play,
// so any effect that enumerates "captured cards" has to ask for them separately or it silently misses
// them (an unqualified "rescue a captured card" would otherwise be unable to free a base captive at all).
// Returns one row per stored base captive: ['entry' => 'B:<captorSeat>:<cardID>:<owner>', 'cardID' => …].
// The entry string is colon-delimited on purpose so it can ride alongside a unit captor's "UID:subIdx"
// entry in the same comma-joined DQ payload.
function SWUCollectBaseCaptives(): array {
    $rows = [];
    for ($p = 1; $p <= SeatCountForGame(); $p++) {
        foreach (GetGlobalEffects($p) as $ge) {
            $flag = (string)($ge->CardID ?? '');
            if (strpos($flag, 'SWU_BASECAPTIVE|') !== 0) continue;
            $parts  = explode('|', $flag);
            $cardID = $parts[1] ?? ''; $owner = intval($parts[2] ?? 0);
            if ($cardID === '' || $owner <= 0) continue;
            $rows[] = ['entry' => 'B:' . $p . ':' . $cardID . ':' . $owner, 'cardID' => $cardID];
        }
    }
    return $rows;
}

// Consume one entry produced by SWUCollectBaseCaptives: drop its GlobalEffects flag (so the regroup
// sweep won't rescue it a second time) and hand back a captive-shaped object for DoRescueUnit.
// Returns null if the flag is already gone.
function SWUTakeBaseCaptiveByEntry(string $entry) {
    $f = explode(':', $entry);
    if (count($f) < 4 || $f[0] !== 'B') return null;
    $captor = intval($f[1]); $cardID = $f[2]; $owner = intval($f[3]);
    $ge = &GetGlobalEffects($captor);
    for ($i = count($ge) - 1; $i >= 0; $i--) {
        if ((string)($ge[$i]->CardID ?? '') !== 'SWU_BASECAPTIVE|' . $cardID . '|' . $owner) continue;
        array_splice($ge, $i, 1);
        return (object)['CardID' => $cardID, 'Owner' => $owner];
    }
    return null;
}

// Rescue every base captive (SEC_195) to its owner's control, exhausted. Called at RegroupPhaseStart.
function _SWURescueBaseCaptives(): void {
    for ($p = 1; $p <= SeatCountForGame(); $p++) {
        $ge = &GetGlobalEffects($p);
        for ($i = count($ge) - 1; $i >= 0; $i--) {
            $flag = (string)($ge[$i]->CardID ?? '');
            if (strpos($flag, 'SWU_BASECAPTIVE|') !== 0) continue;
            $parts  = explode('|', $flag);
            $cardID = $parts[1] ?? ''; $owner = intval($parts[2] ?? 0);
            if ($cardID !== '' && $owner > 0) DoRescueUnit((object)['CardID' => $cardID, 'Owner' => $owner], null);
            array_splice($ge, $i, 1);
        }
    }
}

// SEC_145 Confidence in Victory — at the start of the regroup phase, if the caster is the ONLY player
// who controls units in the chosen arena, they win. Armed via SWU_CONFIDENCE|{caster}|{Ground|Space};
// one-shot (the flag is consumed here).
function _SWUCheckConfidenceWin(): void {
    global $gWinner;
    for ($p = 1; $p <= SeatCountForGame(); $p++) {
        $ge = &GetGlobalEffects($p);
        for ($i = count($ge) - 1; $i >= 0; $i--) {
            $flag = (string)($ge[$i]->CardID ?? '');
            if (strpos($flag, 'SWU_CONFIDENCE|') !== 0) continue;
            $parts  = explode('|', $flag);
            $caster = intval($parts[1] ?? 0);
            $arena  = $parts[2] ?? '';
            array_splice($ge, $i, 1);                                  // one-shot regardless of outcome
            if ($caster <= 0 || $arena === '') continue;
            $opp     = OtherPlayer($caster);
            $myArr   = ($arena === 'Space') ? GetSpaceArena($caster) : GetGroundArena($caster);
            $oppArr  = ($arena === 'Space') ? GetSpaceArena($opp)    : GetGroundArena($opp);
            $myCnt = 0;  foreach ($myArr  as $u) { if (empty($u->removed)) $myCnt++; }
            $opCnt = 0;  foreach ($oppArr as $u) { if (empty($u->removed)) $opCnt++; }
            if ($myCnt > 0 && $opCnt === 0) {                          // caster is the only one with units there
                SWUDeclareGameWinner($caster);
                AddGameLogEntry('WIN', 'P' . $caster . ' wins the game (Confidence in Victory).', 'ALL');
            }
        }
    }
}

// SHD_208 Final Showdown — "At the start of the regroup phase, you lose the game." Armed via the
// SWU_SHD208_LOSE global effect on the caster (set by its $whenPlayedAbilities handler). Runs at RegroupPhaseStart BEFORE
// the draw step, so the caster loses (and the other player wins) before anyone draws — a deck-out at
// the ensuing draw can't change the result. One-shot: the flag is spliced out regardless.
function _SWUCheckFinalShowdownLose(): void {
    for ($p = 1; $p <= SeatCountForGame(); $p++) {
        $ge = &GetGlobalEffects($p);
        for ($i = count($ge) - 1; $i >= 0; $i--) {
            if ((string)($ge[$i]->CardID ?? '') !== 'SWU_SHD208_LOSE') continue;
            array_splice($ge, $i, 1);                 // one-shot
            if (SeatCountForGame() > 2) {
                // Twin Suns: the loser is eliminated (no damager → no heal); deferred most-HP
                // scoring at the next phase boundary decides the winner among the survivors.
                SWUEliminateSeat($p, null);
                AddGameLogEntry('ELIMINATED', "Player {$p} loses (Final Showdown) and is eliminated!", 'ALL');
            } else {
                $winner = OtherPlayer($p);
                SWUDeclareGameWinner($winner, "GAMEOVER:Player {$p} loses the game (Final Showdown)! Player {$winner} wins!");
                AddGameLogEntry('WIN', 'P' . $winner . ' wins the game (P' . $p . ' — Final Showdown).', 'ALL');
            }
        }
    }
}

// Collect the GRANTED / conditional-innate Bounty rewards carried by a unit that is leaving play, from
// the live object (its turn-effects, subcards and Status are all gone once cleanup runs). A Bounty reads
// "when this unit is defeated OR CAPTURED", so BOTH leave-play paths must build the same reward list —
// this helper is that single source of truth. Before it existed the capture path queued only the innate
// $Bounty_Cards bounty, so every granted-bounty upgrade (SHD_068/071/123/125/173/176/221/222/226/261),
// the SHD_006 phase grant, and the SHD_033/SHD_165 conditional innates were silently skipped on capture.
// A reward = the source CardID + a param (SHD_006: the discount 1/2; SHD_123: 1 if the host was unique →
// top 10; SHD_226: "<cardID>~<owner>" so the reward can find the unit again).
// $obj        : the pre-removal object (null → no granted rewards can be read).
// $cardID     : the leaving unit's CardID.
// $controller : its controller, used as the owner fallback for the SHD_226 param.
function _SWUGrantedBountyRewards(?object $obj, string $cardID, int $controller): array {
    if ($obj === null) return [];
    $rewards = [];
    // Granted via a turn-effect (SHD_006 Jabba's phase grant, SHD_031 The Client).
    foreach (SWUParsedTurnEffects($obj) as $e) {
        if (($e['kind'] ?? '') === 'GRANT_KEYWORD' && ($e['value'] ?? '') === 'BOUNTY') {
            $rewards[] = ['reward' => $e['base'], 'param' => intval($e['params'][0] ?? 0)];
        }
    }
    // Granted by an attached upgrade.
    if (is_array($obj->Subcards ?? null)) {
        foreach ($obj->Subcards as $sub) {
            $scid = is_array($sub) ? ($sub['CardID'] ?? '') : ($sub->CardID ?? '');
            $srem = is_array($sub) ? !empty($sub['removed']) : !empty($sub->removed);
            if (!$srem && in_array($scid, SWUBountyGrantUpgrades(), true)) {
                if ($scid === 'SHD_226') {
                    // Unrefusable Offer — the reward plays the unit that just left play under the
                    // collector's control, so thread its cardID + owner (which side it must be found on).
                    $rewards[] = ['reward' => 'SHD_226',
                        'param' => $cardID . '~' . intval($obj->Owner ?? $controller)];
                } else {
                    $rewards[] = ['reward' => $scid, 'param' => CardUnique($cardID) ? 1 : 0];
                }
            }
        }
    }
    // Conditional innate Bounty (SHD_033 Synara San / SHD_165 Unlicensed Headhunter — "While this unit is
    // exhausted, it gains 'Bounty — …'"): the quoted grant defeats the generator's $Bounty_Cards
    // detection, so it rides here — active only if the unit was EXHAUSTED (Status 0) as it left play.
    if (in_array($cardID, ['SHD_033', 'SHD_165'], true) && intval($obj->Status ?? 1) === 0) {
        $rewards[] = ['reward' => $cardID, 'param' => 0];
    }
    return $rewards;
}

// CollectCaptureTriggers — fires the leave-play reactions and Bounty that apply when a unit is
// captured. Capture is a non-defeat leave-play event (CR 8.34), so:
//   • Boba Fett SOR_015 and SWU_ENEMY_LEFT_PLAY fire (outside $defeated guard).
//   • Gideon/Krell/Kallus do NOT fire (those are defeat-only).
//   • Bounty (CR 7.6.3) is offered to the CAPTURING player (mirrors the defeat path's activePlayer).
// $capturingPlayer : the player who performed the capture (receives Bounty).
// $capturedController : the controller of the unit that just left play (used for leave-play reaction).
// $capturedCardID : the CardID of the captured unit.
// $grantedRewards : the granted/conditional-innate Bounty rewards, snapshotted by the caller BEFORE the
//                   captured unit's upgrades were defeated (the grant lives on the upgrade). Null =
//                   read them from $capturedObj, which is only correct if nothing has stripped it yet.
function CollectCaptureTriggers(int $capturingPlayer, int $capturedController, string $capturedCardID, ?object $capturedObj = null, ?array $grantedRewards = null): void {
    // Leave-play reactions: Boba Fett trigger + SWU_ENEMY_LEFT_PLAY phase flag.
    // Called with $defeated = false so only the non-defeat reactions fire.
    SWUCollectLeavePlayReactions([['player' => $capturedController, 'cardID' => $capturedCardID]], false);

    // Bounty (CR 7.6.3): offered to the capturing player, mirroring the defeat-path bounty block
    // in CollectWhenDefeatedTriggers where it is offered to the $activePlayer (the defeating player).
    global $Bounty_Cards;
    // SEC_046 Galen Erso — a named captured unit has lost its Bounty (no reward offered).
    if (isset($Bounty_Cards[$capturedCardID]) && !_SWUGalenSuppressesCard(intval($capturedController), $capturedCardID)) {
        DecisionQueueController::AddDecision($capturingPlayer, "YESNO", "-", 1, tooltip:"Collect_bounty?");
        DecisionQueueController::AddDecision($capturingPlayer, "CUSTOM", "SWUCollectBounty|{$capturedCardID}", 1);
    }

    // Granted + conditional-innate Bounties (CR 13.b — each is an independent ability). Built from the
    // pre-removal object by the same helper the defeat path uses, so "defeated OR captured" really does
    // reach both. Offered to the capturing player, mirroring the innate bounty above.
    if (!_SWUGalenSuppressesCard(intval($capturedController), $capturedCardID)) {
        $rewards = $grantedRewards ?? _SWUGrantedBountyRewards($capturedObj, $capturedCardID, $capturedController);
        foreach ($rewards as $rw) {
            DecisionQueueController::AddDecision($capturingPlayer, "YESNO", "-", 1, tooltip:"Collect_bounty?");
            DecisionQueueController::AddDecision($capturingPlayer, "CUSTOM", "SWUCollectBounty|{$rw['reward']}|{$rw['param']}", 1);
        }
    }

    // Flush any AddTrigger'd reactions (e.g. Boba BobaLeftPlay) into the DQ.
    // Uses $capturingPlayer as the active player, mirroring CollectWhenDefeatedTriggers
    // which calls FlushTriggerBag($activePlayer) where $activePlayer is the defeating player.
    FlushTriggerBag($capturingPlayer);
}

// DoRescueUnit — CR 8.34.3: return a single captive subcard to play under its owner's control,
// exhausted. Does NOT trigger WhenPlayed or any "enters play" effects (the unit is not played).
// $captiveSubcard : the captive subcard object (or array) stored on the former host.
// $hostObj        : the host unit object (used only for context; its Subcards are managed by caller).
// The card's OWN "this unit enters play ready" replacement, including the conditional variants whose
// printed text SWUUnitEntersReady only text-matches. Shared by every path that puts a unit into an arena
// — the normal play path AND re-entries such as DoRescueUnit — so a rescued Corellian Hounds re-checks
// its condition instead of silently defaulting to exhausted. Excludes the play-source-only overrides
// ($gForceEnterReady, ASH_248 Neel's armed flag), which belong to the play path alone.
function _SWUCardEntersReadyFor(int $player, string $cardID): bool {
    $entersReady = SWUUnitEntersReady($cardID);
    // SEC_170 Corellian Hounds — "If an opponent controls no ground units, this unit enters play ready."
    if ($cardID === 'SEC_170') {
        $oppGround = 0;
        foreach (GetGroundArena(OtherPlayer($player)) as $gu) { if (empty($gu->removed)) $oppGround++; }
        return ($oppGround === 0);
    }
    // LAW_210 Salacious Crumb — "If you control Jabba the Hutt (as a leader or unit)."
    if ($cardID === 'LAW_210') return _SWUControlsTitle($player, ['Jabba the Hutt']);
    // LAW_223 Rose Tico — "If you control a non-unique unit."
    if ($cardID === 'LAW_223') {
        foreach (GetUnitsInPlay($player) as $ru) {
            if (empty($ru->removed) && !CardUnique($ru->CardID ?? '')) return true;
        }
        return false;
    }
    // ASH_224 Elzar Mann — "While you control a Force leader."
    if ($cardID === 'ASH_224') {
        foreach (GetLeader($player) as $el) {
            if (empty($el->removed) && TraitContains($el, 'Force')) return true;
        }
        return false;
    }
    // HMW_234 Ritual Dragon — "friendly units enter play ready" while it is in play with a Tatooine base.
    if (_SWURitualDragonEntersReady($player, $cardID)) return true;
    return $entersReady;
}

function DoRescueUnit($captiveSubcard, $hostObj): void {
    global $playerID;
    $savedPID = $playerID;

    $cardID = is_array($captiveSubcard) ? ($captiveSubcard['CardID'] ?? '') : ($captiveSubcard->CardID ?? '');
    $owner  = is_array($captiveSubcard) ? intval($captiveSubcard['Owner'] ?? 0) : intval($captiveSubcard->Owner ?? 0);

    if ($cardID === '' || $owner === 0) {
        $playerID = $savedPID;
        return;
    }

    // Add the rescued unit directly to the arena as the owner/controller, exhausted (Status:0).
    // Status:0 is the exhausted value used in ActivateCard's $entryStatus default path (CR 8.22.f).
    // We use AddGroundArena/AddSpaceArena directly (not SWUBeginPlayCard/ActivateCard) so that
    // no WhenPlayed or "enters play" triggers fire.
    $playerID = $owner;
    $uid = NextUniqueID();
    $targetArena = CardTargetArena($cardID);
    // SEC_018 DJ (deployed) — "Friendly units that are rescued enter play ready." The rescued unit
    // returns to its owner; if that owner controls a deployed SEC_018, it enters ready (Status:1).
    // The rescued card's OWN enters-ready replacement is re-evaluated here too — it applies whenever the
    // unit ENTERS play, not only when it is played from hand (SEC_170 Corellian Hounds).
    $entryStatus = (_SWULeaderDeployed($owner, 'SEC_018') || _SWUCardEntersReadyFor($owner, $cardID)) ? 1 : 0;
    if ($targetArena === 'SpaceArena') {
        AddSpaceArena($owner, CardID:$cardID, Status:$entryStatus, Owner:$owner, Damage:0, Controller:$owner, UniqueID:$uid);
    } else {
        AddGroundArena($owner, CardID:$cardID, Status:$entryStatus, Owner:$owner, Damage:0, Controller:$owner, UniqueID:$uid);
    }

    $playerID = $savedPID;
}

// SWURescueCaptivesOf — CR 8.34.4: if $hostObj guards any captured units, rescue all of them
// via DoRescueUnit and clear them from the host. No-op when the host has no captives.
// MUST be called BEFORE the host is marked removed / spliced out of the arena array.
//
// SPLIT into detach + materialize (see SWUDetachCaptivesOf below): the DETACH half must run before
// SWUDiscardHostSubcards (or the captives would be discarded as if they were upgrades), but the
// MATERIALIZE half must run AFTER the host's defeat observers are collected — a captive is not in
// play at the moment of the defeat that frees it, so it must not satisfy "when an enemy unit is
// defeated" (LOF_130 HK-47 et al). Callers that don't collect observers in between just use this
// wrapper; the combat defender path drives the two halves itself.
function SWURescueCaptivesOf($hostObj): void {
    $captives = SWUDetachCaptivesOf($hostObj);
    foreach ($captives as $captive) DoRescueUnit($captive, $hostObj);
}

// Detach-only half: strips every live captive subcard off $hostObj and RETURNS them without putting
// anything into play. Callers MUST materialize the result with DoRescueUnit or the captives are lost.
// Detach ONE captive (matched by CardID + owner) from whatever unit is guarding it, anywhere on the
// board; returns whether it was found. Used by a Bounty reward that puts a unit which left play BY
// CAPTURE back into play (SHD_226 Unrefusable Offer): a captured card becomes a face-down subcard on its
// captor and never reaches a discard pile, so the discard lookup such rewards normally use finds nothing.
function _SWUTakeCaptiveByCardID(int $owner, string $cardID): bool {
    if ($cardID === '' || $owner <= 0) return false;
    for ($p = 1; $p <= 2; $p++) {
        foreach ([GetGroundArena($p), GetSpaceArena($p)] as $zone) {
            foreach ($zone as $host) {
                if ($host === null || !empty($host->removed) || !is_array($host->Subcards ?? null)) continue;
                foreach ($host->Subcards as $i => $sub) {
                    $isCaptive = is_array($sub) ? !empty($sub['IsCaptive'])  : !empty($sub->IsCaptive);
                    $isRemoved = is_array($sub) ? !empty($sub['removed'])    : !empty($sub->removed);
                    $scid      = is_array($sub) ? ($sub['CardID'] ?? '')     : ($sub->CardID ?? '');
                    $sown      = is_array($sub) ? intval($sub['Owner'] ?? 0) : intval($sub->Owner ?? 0);
                    if (!$isCaptive || $isRemoved || $scid !== $cardID || $sown !== $owner) continue;
                    $remaining = $host->Subcards;
                    unset($remaining[$i]);
                    $host->Subcards = array_values($remaining);
                    return true;
                }
            }
        }
    }
    return false;
}

function SWUDetachCaptivesOf($hostObj): array {
    if ($hostObj === null || empty($hostObj->Subcards) || !is_array($hostObj->Subcards)) return [];

    // Snapshot captives first to avoid reading stale indices after mutation.
    $captives = [];
    foreach ($hostObj->Subcards as $sub) {
        $isCaptive = is_array($sub) ? !empty($sub['IsCaptive']) : !empty($sub->IsCaptive);
        $isRemoved = is_array($sub) ? !empty($sub['removed'])   : !empty($sub->removed);
        if ($isCaptive && !$isRemoved) {
            $captives[] = $sub;
        }
    }

    if (empty($captives)) return [];

    // Remove captive subcards from the host before rescuing so they don't double-fire later.
    $remaining = [];
    foreach ($hostObj->Subcards as $sub) {
        $isCaptive = is_array($sub) ? !empty($sub['IsCaptive']) : !empty($sub->IsCaptive);
        $isRemoved = is_array($sub) ? !empty($sub['removed'])   : !empty($sub->removed);
        if (!$isCaptive || $isRemoved) $remaining[] = $sub;
    }
    $hostObj->Subcards = $remaining;

    // Also rescue captives nested on a pilot subcard (a captor that became a Pilot upgrade carries its
    // captive on the subcard's Captives list — JTL move/attach subsystem). If the WHOLE host leaves play
    // while such a pilot is attached, those nested captives must release too.
    foreach ($hostObj->Subcards as $sub) {
        $nested = is_array($sub) ? ($sub['Captives'] ?? null) : ($sub->Captives ?? null);
        if (is_array($nested)) foreach ($nested as $cap) $captives[] = $cap;
    }

    if (empty($captives)) return [];

    // Remove captive subcards from the host before rescuing so they don't double-fire later.
    $remaining = [];
    foreach ($hostObj->Subcards as $sub) {
        $isCaptive = is_array($sub) ? !empty($sub['IsCaptive']) : !empty($sub->IsCaptive);
        $isRemoved = is_array($sub) ? !empty($sub['removed'])   : !empty($sub->removed);
        if (!$isCaptive || $isRemoved) {
            // strip any nested captives off a surviving pilot subcard (they're being rescued)
            if (is_array($sub)) unset($sub['Captives']); elseif (isset($sub->Captives)) unset($sub->Captives);
            $remaining[] = $sub;
        }
    }
    $hostObj->Subcards = $remaining;

    return $captives;
}

// ─── JTL move/attach subsystem (Eject/Corvus/Luke unit/L3-37) ──────────────────
// Move a UNIT in play to become a Pilot upgrade attached to $hostMz. The unit's normal (non-captive)
// upgrades are defeated and its damage is dropped (CR: "it's no longer a unit; defeat all upgrades on it
// and remove all damage"); any CAPTIVES it holds ride along on the pilot subcard's Captives list so the
// captor keeps them tucked. The UniqueID is PRESERVED on the subcard so UID-keyed markers (e.g.
// SWU_PLAYED_UNIT_{uid} → Luke SOR_005's "a unit you played this phase") survive the transition.
function SWUMoveUnitToUpgrade(string $unitMz, string $hostMz, bool $isPilot = true): void {
    global $playerID;
    $unit = GetZoneObject($unitMz);
    $host = GetZoneObject($hostMz);
    if (SWUObjGone($unit) || SWUObjGone($host)) return;

    // TWI_116 Clone — a Clone copy leaves the unit slot as the REAL card (TWI_116), never as the card it
    // copied; mirrors the discard/capture/bounce revert paths so an L3-37-cloned pilot attaches as 'clone'.
    $cardID     = !empty($unit->IsClone) ? 'TWI_116' : $unit->CardID;
    $owner      = intval($unit->Owner ?? $playerID);
    $controller = intval($unit->Controller ?? $owner);
    $uid        = intval($unit->UniqueID ?? 0);

    // Snapshot captives; defeat normal upgrades (non-token → owner's discard).
    $captives = [];
    if (is_array($unit->Subcards ?? null)) {
        foreach ($unit->Subcards as $sub) {
            $isCap = is_array($sub) ? !empty($sub['IsCaptive']) : !empty($sub->IsCaptive);
            $isRem = is_array($sub) ? !empty($sub['removed'])   : !empty($sub->removed);
            if ($isRem) continue;
            if ($isCap) { $captives[] = $sub; continue; }
            $scid = is_array($sub) ? ($sub['CardID'] ?? '') : ($sub->CardID ?? '');
            $sown = is_array($sub) ? intval($sub['Owner'] ?? $owner) : intval($sub->Owner ?? $owner);
            if ($scid !== '' && strpos(strtolower(CardType($scid) ?? ''), 'token') === false) {
                SWUAddToDiscard($sown, $scid, 'PLAY');
            }
        }
    }

    // Remove the unit from its arena (NOT defeated — it becomes an upgrade).
    $unit->removed = true;

    // A unit that becomes a NON-pilot special upgrade (JTL_050 Phantom II) leaves play AS A UNIT, so per
    // CR 8.34.4 it rescues any units it had captured — they return to their owner's arena exhausted (the
    // "rescue all captured units" clause of Phantom II's attach rider). A real PILOT (leader deploy-as-pilot
    // / Poe hop) instead keeps its captives on the subcard so SWUMoveUpgradeToUnit can restore them if the
    // pilot later becomes a unit again.
    if (!$isPilot && !empty($captives)) {
        foreach ($captives as $cap) DoRescueUnit($cap, $unit);
        $captives = [];
    }

    if (!is_array($host->Subcards)) $host->Subcards = [];
    // ⚠ A card can only be a PILOT upgrade if it actually has the Pilot trait, so derive rather than
    // trusting the caller's flag. Every "attach this unit as an upgrade" ability passes true because the
    // card that owns the ability is itself a Pilot (Sidon Ithano, Pantoran Starship Thief, Corvus's
    // chosen pilot) — but TS26_34 Fives can COPY those abilities, and Fives is a Trooper, not a Pilot.
    // Flagging him IsPilot made the host count as "has a Pilot on it", which wrongly blocked its
    // controller from later attaching a real Pilot to that Vehicle. Readers already OR this flag with the
    // Pilot trait, so narrowing it is a no-op for every genuine Pilot and only corrects the copied case.
    $isPilot = $isPilot && $cardID !== '' && HasTrait($cardID, 'Pilot');
    $pilotSub = (object)[
        'CardID'      => $cardID,
        'Owner'       => $owner,
        'Controller'  => $controller,
        'TurnEffects' => [],
        'IsPilot'     => $isPilot,
        'UniqueID'    => $uid,
    ];
    if (!empty($captives)) $pilotSub->Captives = $captives;
    $host->Subcards[] = $pilotSub;

    DecisionQueueController::CleanupRemovedCards();

    // A unit becoming a PILOT upgrade must still fire the host's "when a Pilot attaches" reactions (JTL_101
    // Red Leader / JTL_223 Razor Crest) — this path bypasses _SWUFinalizeUpgradeAttach's dispatch. Fire for
    // the host's controller (matters for Sidon Ithano JTL_213 attaching onto an ENEMY host).
    $hostCtl = intval($host->Controller ?? ($host->Owner ?? 0));
    // The reactions are only BAGGED here; this path has no play ceremony to flush them, so flush explicitly.
    if ($isPilot && _SWUFireHostPilotAttachReactions($host, true, $cardID) > 0 && $hostCtl > 0) {
        FlushEntryTriggerBag($hostCtl);
    }
    // …and the newly-attached card's OWN "when this upgrade attaches" ability (JTL_036 Iden Versio),
    // which likewise only ran on the normal play path.
    if ($hostCtl > 0) CollectOnAttachedTriggers($hostCtl, $cardID, $hostMz);
}

// Move a Pilot UPGRADE (subcard at $subIdx on $hostMz) to become a UNIT in $targetArena (defaults to the
// card's natural arena; Eject/Luke force 'GroundArena'). The UniqueID is PRESERVED (or freshly assigned
// if the pilot was never a unit). Any captives carried on the subcard come back as the new unit's captive
// subcards. Enters exhausted by default. Returns the new unit's owner-relative mzID ('' on failure).
function SWUMoveUpgradeToUnit(string $hostMz, int $subIdx, ?string $targetArena = null, bool $exhaust = true): string {
    $host = GetZoneObject($hostMz);
    if (SWUObjGone($host) || !is_array($host->Subcards ?? null)) return '';
    if (!isset($host->Subcards[$subIdx])) return '';
    $sub = $host->Subcards[$subIdx];

    $cardID = is_array($sub) ? ($sub['CardID'] ?? '') : ($sub->CardID ?? '');
    if ($cardID === '') return '';
    $owner      = is_array($sub) ? intval($sub['Owner'] ?? 0) : intval($sub->Owner ?? 0);
    $controller = is_array($sub) ? intval($sub['Controller'] ?? $owner) : intval($sub->Controller ?? $owner);
    $uid        = is_array($sub) ? intval($sub['UniqueID'] ?? 0) : intval($sub->UniqueID ?? 0);
    if ($uid <= 0) $uid = NextUniqueID();
    $carried    = is_array($sub) ? ($sub['Captives'] ?? []) : ($sub->Captives ?? []);
    $newSubs    = is_array($carried) ? array_values($carried) : [];

    // Remove the pilot subcard from the host.
    array_splice($host->Subcards, $subIdx, 1);

    $arena  = $targetArena ?: CardTargetArena($cardID);
    $status = $exhaust ? 0 : 1; // 0=exhausted, 1=ready
    if ($arena === 'SpaceArena') {
        $newObj = AddSpaceArena($owner, CardID:$cardID, Status:$status, Owner:$owner, Damage:0,
            Controller:$controller, Subcards:$newSubs, UniqueID:$uid);
        $idx = $newObj->mzIndex ?? (count(GetSpaceArena($owner)) - 1);
        return "mySpaceArena-{$idx}";
    }
    $newObj = AddGroundArena($owner, CardID:$cardID, Status:$status, Owner:$owner, Damage:0,
        Controller:$controller, Subcards:$newSubs, UniqueID:$uid);
    $idx = $newObj->mzIndex ?? (count(GetGroundArena($owner)) - 1);
    return "myGroundArena-{$idx}";
}

// Move a UNIT from its current arena into $targetArena ('GroundArena'/'SpaceArena'), staying a unit.
// UniqueID, Owner, Controller, Damage, Status, Subcards and TurnEffects are all preserved (so
// SWU_PLAYED_UNIT_{uid}, attached upgrades and damage carry over). Returns the new owner-relative mzID
// ('' on failure). Used by JTL_096 Blue Leader ("move this unit to the ground arena").
function SWUMoveUnitBetweenArenas(string $unitMz, string $targetArena): string {
    global $playerID;
    $u = GetZoneObject($unitMz);
    if (SWUObjGone($u)) return '';
    $owner       = intval($u->Owner ?? $playerID);
    $controller  = intval($u->Controller ?? $owner);
    $uid         = intval($u->UniqueID ?? 0);
    if ($uid <= 0) $uid = NextUniqueID();
    $cardID      = $u->CardID;
    $damage      = intval($u->Damage ?? 0);
    $status      = intval($u->Status ?? 0);
    $subs        = is_array($u->Subcards ?? null)    ? array_values($u->Subcards)    : [];
    $turnEffects = is_array($u->TurnEffects ?? null) ? array_values($u->TurnEffects) : [];

    $savedPID = $playerID;
    $playerID = $owner;
    $u->removed = true;
    if ($targetArena === 'SpaceArena') {
        $newObj = AddSpaceArena($owner, CardID:$cardID, Status:$status, Owner:$owner, Damage:$damage,
            Controller:$controller, TurnEffects:$turnEffects, Subcards:$subs, UniqueID:$uid);
    } else {
        $newObj = AddGroundArena($owner, CardID:$cardID, Status:$status, Owner:$owner, Damage:$damage,
            Controller:$controller, TurnEffects:$turnEffects, Subcards:$subs, UniqueID:$uid);
    }
    DecisionQueueController::CleanupRemovedCards();
    // Re-resolve by UID AFTER cleanup so a compacted source arena can't stale the index.
    $newMz = SWUFindMzByUID($uid) ?? '';
    $playerID = $savedPID;
    return $newMz;
}

// Pilot UPGRADES that "can't be defeated as an upgrade by enemy card abilities" — the immunity lives on
// the pilot subcard itself (protecting it, not its host), and applies only to ENEMY defeats. Currently
// JTL_012 Luke Skywalker (Hero of Yavin). Keep this list as the single source of truth so both the
// upgrade-defeat enforcement (SWUDefeatUpgrade) and any future target-filtering agree.
function _SWUUpgradeImmuneToEnemyDefeat(string $upgradeCardID): bool {
    return $upgradeCardID === 'JTL_012';
}

// Detach the first non-removed upgrade matching $cardID from $hostMz and return it to its owner's hand.
// Used by JTL_197 Anakin ("return this upgrade to its owner's hand").
// SEC_061 Willrow Hood — "While this unit has exactly 1 friendly upgrade on it, that upgrade can't be
// defeated or returned to hand by enemy card abilities." True when the upgrade (controlled by $host's
// controller) is protected from $actor. Only ENEMY abilities are blocked (actor != host controller),
// only FRIENDLY upgrades are protected, and only when the host bears EXACTLY ONE friendly upgrade.
function _SWUWillrowProtectsUpgrade(object $host, int $upgradeController, int $actor): bool {
    if (($host->CardID ?? '') !== 'SEC_061') return false;
    $hostCtrl = intval($host->Controller ?? $host->Owner ?? 0);
    if ($actor === $hostCtrl || $actor <= 0) return false;   // friendly (or unknown) actor — not blocked
    if ($upgradeController !== $hostCtrl)     return false;   // only friendly upgrades are protected
    if (!is_array($host->Subcards ?? null))   return false;
    // An effect that removes SEVERAL upgrades at once ("return EACH upgrade on it") pins the count first
    // — see SWUPinWillrowUpgradeCount. Without the pin the count would be re-read between removals, so a
    // 2-upgrade Willrow would lose one upgrade and then protect the survivor, and the outcome would depend
    // on which upgrade the loop happened to reach first.
    $pinned = $GLOBALS['gSWUWillrowPinnedCount'][intval($host->UniqueID ?? 0)] ?? null;
    if ($pinned !== null) return intval($pinned) === 1;
    return _SWUCountFriendlyUpgrades($host) === 1;
}

// Live friendly-upgrade count on a host (upgrades whose controller is the host's controller).
function _SWUCountFriendlyUpgrades(object $host): int {
    $hostCtrl = intval($host->Controller ?? $host->Owner ?? 0);
    if (!is_array($host->Subcards ?? null)) return 0;
    $friendly = 0;
    foreach ($host->Subcards as $sub) {
        $isCap = is_array($sub) ? !empty($sub['IsCaptive']) : !empty($sub->IsCaptive);
        $isRem = is_array($sub) ? !empty($sub['removed'])   : !empty($sub->removed);
        if ($isCap || $isRem) continue;
        $sc = is_array($sub) ? intval($sub['Controller'] ?? $sub['Owner'] ?? 0)
                             : intval($sub->Controller ?? $sub->Owner ?? 0);
        if ($sc === $hostCtrl) $friendly++;
    }
    return $friendly;
}

// Freeze SEC_061's "exactly 1 friendly upgrade" gate at the state BEFORE a multi-upgrade removal begins,
// so every upgrade in that one effect is judged against the same board. Always pair with the unpin call.
function SWUPinWillrowUpgradeCount(object $host): int {
    $uid = intval($host->UniqueID ?? 0);
    $GLOBALS['gSWUWillrowPinnedCount'][$uid] = _SWUCountFriendlyUpgrades($host);
    return $uid;
}
function SWUUnpinWillrowUpgradeCount(int $hostUID): void {
    unset($GLOBALS['gSWUWillrowPinnedCount'][$hostUID]);
}

// SEC_101 Queen Amidala — "If damage would be dealt to this unit, you may defeat another friendly unit
// that shares a trait with this unit. If you do, prevent that damage." Interactive prevention. These two
// helpers + the AMIDALA_PREVENT_* handlers (CardDQHandlers) implement it; indirect damage modifies Damage
// directly (never through SWUDealDamageToUnit / SWUCombatDamage's unit path) so it's unpreventable for free.
// Friendly trait-sharing units the controller could defeat to prevent (empty = can't prevent).
function _SWUAmidalaPreventTargets(object $amidala): array {
    $ctrl = intval($amidala->Controller ?? 0);
    if ($ctrl <= 0) return [];
    $auid = intval($amidala->UniqueID ?? 0);
    global $playerID, $traitData; $sv = $playerID; $playerID = $ctrl;
    // "shares a trait with THIS unit" — use Amidala's LIVE traits (printed Naboo/Official + any granted, e.g.
    // Foundling SHD_069 → Mandalorian), not a hardcoded pair. Candidate-side grants are handled by
    // _SWUUnitHasTrait. Grantable traits are unioned in so a granted trait on Amidala is discovered.
    $grantable = ['Mandalorian', 'Rebel', 'Underworld', 'Jedi', 'Clone', 'Force'];
    $printed   = array_filter(array_map('trim', explode(',', $traitData[$amidala->CardID ?? ''] ?? '')));
    $amidalaTraits = [];
    foreach (array_unique(array_merge($printed, $grantable)) as $t) {
        if ($t !== '' && TraitContains($amidala, $t)) $amidalaTraits[] = $t;
    }
    $out = [];
    foreach (['myGroundArena', 'mySpaceArena'] as $zone) {
        foreach (ZoneSearch($zone, AnyUnitFilter) as $mz) {
            $o = GetZoneObject($mz);
            if (SWUObjGone($o)) continue;
            if (intval($o->UniqueID ?? 0) === $auid) continue;   // "another" unit
            foreach ($amidalaTraits as $t) {
                if (TraitContains($o, $t)) { $out[] = $mz; break; }   // shares a live trait with Amidala
            }
        }
    }
    $playerID = $sv;
    return $out;
}
// Consume a pending combat prevent-marker on $unit (set by the step-1 offer). True ⇒ skip this damage.
function _SWUConsumeAmidalaPrevent($unit): bool {
    if ($unit === null || ($unit->CardID ?? '') !== 'SEC_101') return false;
    $ctrl = intval($unit->Controller ?? 0);
    $uid  = intval($unit->UniqueID ?? 0);
    if ($ctrl <= 0 || GlobalEffectCount($ctrl, 'SWU_AMIDALA_PREVENT_' . $uid) <= 0) return false;
    RemoveGlobalEffect($ctrl, 'SWU_AMIDALA_PREVENT_' . $uid);
    return true;
}

// ASH_062 The Mandalorian — "Shielded. If damage would be dealt to ANOTHER friendly unit, you may defeat
// a Shield token on this unit. If you do, prevent that damage." Interactive prevention powered by a
// friendly ASH_062 that still has a Shield. These two helpers + the ASH062_PREVENT_* handlers + the combat
// arming implement it; indirect damage writes Damage directly (never through SWUDealDamageToUnit /
// SWUCombatDamage's unit path) so it's unpreventable for free, exactly like SEC_101.
// Given a unit about to take damage, return a friendly ASH_062 (a DIFFERENT unit) that has a Shield to
// defeat — the provider that could prevent the damage. null = no prevention available.
function _SWUAsh062Provider($unit): ?object {
    if (SWUObjGone($unit)) return null;
    $ctrl = intval($unit->Controller ?? 0);
    if ($ctrl <= 0) return null;
    $uuid = intval($unit->UniqueID ?? 0);
    global $playerID; $sv = $playerID; $playerID = $ctrl;
    $provider = null;
    foreach (['myGroundArena', 'mySpaceArena'] as $zone) {
        foreach (ZoneSearch($zone, AnyUnitFilter) as $mz) {
            $o = GetZoneObject($mz);
            if (SWUObjGone($o)) continue;
            if (($o->CardID ?? '') !== 'ASH_062') continue;
            if (intval($o->UniqueID ?? 0) === $uuid) continue;   // "ANOTHER friendly unit" — not itself
            if (_SWUCountShieldSubcards($o) <= 0) continue;
            $provider = $o; break 2;
        }
    }
    $playerID = $sv;
    return $provider;
}
// Consume a pending ASH_062 combat prevent-marker on $unit (set when the offer was accepted). The marker
// keys on the PROTECTED unit's UID (not the provider's). True ⇒ skip this combat damage instance.
function _SWUConsumeAsh062Prevent($unit): bool {
    if ($unit === null) return false;
    $ctrl = intval($unit->Controller ?? 0);
    $uid  = intval($unit->UniqueID ?? 0);
    if ($ctrl <= 0 || GlobalEffectCount($ctrl, 'SWU_ASH062_PREVENT_' . $uid) <= 0) return false;
    RemoveGlobalEffect($ctrl, 'SWU_ASH062_PREVENT_' . $uid);
    return true;
}

// ASH_196 Gorian Shard's Corsair — "Damage dealt by friendly Underworld cards is unpreventable." While a
// player controls an in-play ASH_196, damage whose SOURCE is one of that player's Underworld cards bypasses
// Shields AND every prevention/reduction effect (Amidala, The Mandalorian, prevent-2 markers, Cassian).
// $sourceObj = the dealing card: combat → the attacker (or the defender, for counter-damage); ability →
// the source card when threaded. Combat is the signature case (the source is always a unit object).
function _SWUDamageUnpreventable($sourceObj): bool {
    if (SWUObjGone($sourceObj)) return false;
    if (!HasTrait($sourceObj->CardID ?? '', 'Underworld')) return false;
    $ctrl = intval($sourceObj->Controller ?? 0);
    if ($ctrl <= 0) return false;
    return _SWUCountActiveUnitsWithCardID($ctrl, 'ASH_196') > 0;
}

function SWUReturnUpgradeToHand(string $hostMz, string $cardID, int $actor = 0): void {
    $host = GetZoneObject($hostMz);
    if (SWUObjGone($host) || !is_array($host->Subcards ?? null)) return;
    foreach ($host->Subcards as $i => $sub) {
        $scid  = is_array($sub) ? ($sub['CardID'] ?? '')   : ($sub->CardID ?? '');
        $isRem = is_array($sub) ? !empty($sub['removed'])  : !empty($sub->removed);
        if ($isRem || $scid !== $cardID) continue;
        $owner = is_array($sub) ? intval($sub['Owner'] ?? 0) : intval($sub->Owner ?? 0);
        if ($owner <= 0) $owner = intval($host->Controller ?? $host->Owner ?? 1);
        $sctrl = is_array($sub) ? intval($sub['Controller'] ?? $owner) : intval($sub->Controller ?? $owner);
        if (_SWUWillrowProtectsUpgrade($host, $sctrl, $actor)) return;   // SEC_061 protection
        array_splice($host->Subcards, $i, 1);
        // A leader attached as a Pilot can't be returned to hand — losing its host DEFEATS it, and it
        // returns to the leader zone exhausted. This is a STATE-BASED consequence, not a direct
        // enemy-ability defeat, so the leader's "can't be defeated/returned by enemy abilities" immunity
        // does NOT apply. Mirrors SWUDefeatUpgrade's leader-pilot branch (a leader subcard is always a
        // pilot). Used by ASH_042 Jabba, JTL_197, and every other "return an upgrade to hand" effect.
        if (strpos(CardType($cardID) ?? '', 'Leader') !== false) {
            $ldr = SWUFindLeaderByCardID($owner, $cardID);
            if ($ldr === null) $ldr = SWUGetLeaderByIndex($owner, 0);
            if ($ldr !== null) {
                $ldr->Deployed         = false;
                $ldr->DeployedUniqueID = 0;
                $ldr->Ready            = false;
                $ldr->Damage           = 0;
            }
            return;
        }
        // A TOKEN upgrade (Shield SOR_T02 / Experience SOR_T01 / Advantage ASH_T02) CEASES to exist when it
        // leaves play — it is never placed in hand (and so a "you may play it for free" rider finds nothing).
        if (strpos(strtolower(CardType($cardID) ?? ''), 'token') !== false) {
            DecisionQueueController::CleanupRemovedCards();
            return;
        }
        AddHand($owner, CardID:$cardID);
        return;
    }
}

// Relocate a Pilot subcard (index $subIdx) from one host to another, intact (UniqueID + carried captives
// preserved). Used by Corvus (JTL_038) when it attaches a Pilot that is ALREADY an upgrade on another
// friendly Vehicle (a pilot upgrade has no upgrades/damage of its own, so it simply moves).
// An upgrade that MOVES to a new host has still "attached to" that host, so the same two trigger families
// the normal play path fires (_SWUFinalizeUpgradeAttach) must fire here too:
//   • the HOST's "when a Pilot attaches to this unit" reactions (JTL_101 Red Leader / JTL_223 Razor Crest);
//   • the UPGRADE's OWN "when this upgrade attaches to a unit" ability (JTL_036 Iden Versio re-shielding
//     its new host, SOR_122 Traitorous) — $onAttachedAbilities, whose collector documents itself as firing
//     for "any source" but was wired ONLY into the normal play path, so every relocation silently skipped it.
// Subcards decode as associative ARRAYS after a gamestate round-trip, so read defensively.
function _SWUFireUpgradeAttachTriggersOnMove($sub, ?object $toHost, string $toHostMz): void {
    if ($toHost === null || $sub === null) return;
    $cardID  = is_array($sub) ? ($sub['CardID'] ?? '')  : ($sub->CardID ?? '');
    if ($cardID === '') return;
    $isPilot = is_array($sub) ? !empty($sub['IsPilot']) : !empty($sub->IsPilot);
    $hostController = intval($toHost->Controller ?? ($toHost->Owner ?? 0));
    // ⚠ _SWUFireHostPilotAttachReactions only ADDS to the pending-trigger bag; the normal play path flushes
    // it as part of the play ceremony, but a relocation has no ceremony of its own — so flush explicitly or
    // the reaction is queued and silently never surfaced (JTL_223 Razor Crest looked like it "didn't fire").
    if (_SWUFireHostPilotAttachReactions($toHost, $isPilot, $cardID) > 0 && $hostController > 0) {
        FlushEntryTriggerBag($hostController);
    }
    if ($hostController > 0) CollectOnAttachedTriggers($hostController, $cardID, $toHostMz);
}

function SWURelocatePilotSubcard(string $fromHostMz, int $subIdx, string $toHostMz): void {
    $from = GetZoneObject($fromHostMz);
    $to   = GetZoneObject($toHostMz);
    if (SWUObjGone($from) || SWUObjGone($to)) return;
    if (!is_array($from->Subcards ?? null) || !isset($from->Subcards[$subIdx])) return;
    $sub = $from->Subcards[$subIdx];
    array_splice($from->Subcards, $subIdx, 1);
    if (!is_array($to->Subcards)) $to->Subcards = [];
    $to->Subcards[] = $sub;
    _SWUFireUpgradeAttachTriggersOnMove($sub, $to, $toHostMz);
}

// Move an existing (non-pilot) upgrade SUBCARD from one host to another. Splices it out of $fromHostMz's
// Subcards and appends to $toHostMz's, intact (TurnEffects/Owner preserved). Optionally re-assigns the
// upgrade's Controller (JTL_056/JTL_242 "take control of an upgrade and attach it to a different unit").
function SWUMoveUpgradeCrossUnit(string $fromHostMz, int $subIdx, string $toHostMz, int $newController = 0): void {
    $from = GetZoneObject($fromHostMz);
    $to   = GetZoneObject($toHostMz);
    if (SWUObjGone($from) || SWUObjGone($to)) return;
    if (!is_array($from->Subcards ?? null) || !isset($from->Subcards[$subIdx])) return;
    $sub = $from->Subcards[$subIdx];
    $movedCardID = is_array($sub) ? ($sub['CardID'] ?? '') : ($sub->CardID ?? '');
    array_splice($from->Subcards, $subIdx, 1);
    if ($newController > 0) {
        if (is_array($sub)) $sub['Controller'] = $newController; else $sub->Controller = $newController;
    }
    if (!is_array($to->Subcards)) $to->Subcards = [];
    $to->Subcards[] = $sub;
    // The OLD host's "becomes unattached" observers. A move unattaches the upgrade exactly as a defeat
    // does, so the control-revert half of SOR_122 Traitorous / JTL_083 has to run here too — it used to
    // live only at the SWUDefeatUpgrade chokepoint, which left a stolen host stolen forever once the
    // upgrade was relocated instead of defeated.
    _SWUUpgradeUnattachControlRevert(
        $newController > 0 ? $newController : intval($from->Controller ?? $from->Owner ?? 0),
        (string) $movedCardID, $from, $fromHostMz
    );
    _SWUFireUpgradeAttachTriggersOnMove($sub, $to, $toHostMz);
}

// Predicate for "move an upgrade" target filtering. Pilots and captives are never movable here.
//   'token'    — only Token Upgrades (Shield SOR_T02 / Experience SOR_T01) (JTL_242).
//   'nonpilot' — any non-Pilot upgrade, real or token (JTL_056 "a non-Pilot upgrade").
function _SWUUpgradeMatchesMoveFilter($sub, string $filter): bool {
    $isRem = is_array($sub) ? !empty($sub['removed'])   : !empty($sub->removed);
    $isCap = is_array($sub) ? !empty($sub['IsCaptive']) : !empty($sub->IsCaptive);
    if ($isRem || $isCap) return false;
    $scid = is_array($sub) ? ($sub['CardID'] ?? '') : ($sub->CardID ?? '');
    if ($scid === '') return false;
    $isPilot = is_array($sub) ? !empty($sub['IsPilot']) : !empty($sub->IsPilot);
    if ($isPilot || HasTrait($scid, 'Pilot')) return false; // pilots excluded for both filters
    if ($filter === 'token') return strpos(CardType($scid) ?? '', 'Token') !== false;
    if (strpos($filter, 'cost:') === 0) {   // real upgrade (non-token) costing <= N (SHD_077)
        if (strpos(CardType($scid) ?? '', 'Upgrade') === false) return false;
        return intval(CardCost($scid)) <= intval(substr($filter, 5));
    }
    return true; // 'nonpilot' = any non-pilot upgrade
}

// Find the (hostMz, subIdx) of the FIRST Pilot subcard on $hostMz, or null. Pilots are detected by the
// IsPilot flag OR the Pilot trait (the test harness leaves IsPilot=false on pre-set upgrades).
function _SWUFindPilotSubcard($host): ?int {
    if ($host === null || !is_array($host->Subcards ?? null)) return null;
    foreach ($host->Subcards as $i => $sub) {
        $isRem = is_array($sub) ? !empty($sub['removed']) : !empty($sub->removed);
        if ($isRem) continue;
        $isPilot = is_array($sub) ? !empty($sub['IsPilot']) : !empty($sub->IsPilot);
        $scid    = is_array($sub) ? ($sub['CardID'] ?? '') : ($sub->CardID ?? '');
        if ($isPilot || ($scid !== '' && HasTrait($scid, 'Pilot'))) return $i;
    }
    return null;
}

// Controller-relative mzIDs of $controller's pilot-LESS Vehicle units (either arena), excluding $excludeUid.
function _SWUPilotlessFriendlyVehicleMzs(int $controller, int $excludeUid): array {
    global $playerID;
    $saved = $playerID; $playerID = $controller;
    $out = [];
    foreach (['myGroundArena', 'mySpaceArena'] as $z) {
        foreach (ZoneSearch($z, AnyUnitFilter) as $mz) {
            $o = GetZoneObject($mz);
            if (SWUObjGone($o)) continue;
            if (intval($o->UniqueID ?? 0) === $excludeUid) continue;
            if (!HasTrait($o->CardID, 'Vehicle')) continue;
            if (_SWUFindPilotSubcard($o) !== null) continue; // already piloted
            $out[] = $mz;
        }
    }
    $playerID = $saved;
    return $out;
}

// "If this unit would be defeated, you may instead …" replacement descriptor, or null if unavailable.
// JTL_049 L3-37 → attach as a Pilot upgrade onto a friendly pilot-less Vehicle (only if such a Vehicle
// exists). A unit that has lost its abilities can't replace its defeat.
function _SWUUnitDefeatReplacement($obj): ?array {
    if ($obj === null || empty($obj->CardID) || LostAbilities($obj)) return null;
    if ($obj->CardID === 'JTL_049') {
        $ctrl = intval($obj->Controller ?? $obj->Owner ?? 0);
        if (!empty(_SWUPilotlessFriendlyVehicleMzs($ctrl, intval($obj->UniqueID ?? 0)))) {
            return ['kind' => 'unit_to_upgrade'];
        }
    }
    return null;
}

// Pilot-UPGRADE defeat-replacement (JTL_094 Luke): when a host carrying such a pilot leaves play, the
// pilot "would be defeated". Snapshot it into the deferred bag (the host is gone by drain time, so we
// store the data to rebuild the unit) and offer the controller the move at action end. Called BEFORE
// the host is removed, at every host-leave-play site.
function _SWUDeferPilotDefeatReplacements($hostObj): void {
    global $gDeferredReplacements;
    if ($hostObj === null || !is_array($hostObj->Subcards ?? null)) return;
    foreach ($hostObj->Subcards as $sub) {
        $rem  = is_array($sub) ? !empty($sub['removed']) : !empty($sub->removed);
        if ($rem) continue;
        $scid = is_array($sub) ? ($sub['CardID'] ?? '') : ($sub->CardID ?? '');
        if ($scid !== 'JTL_094') continue; // (generalize to a registry if more such pilots appear)
        $suid = is_array($sub) ? intval($sub['UniqueID'] ?? 0) : intval($sub->UniqueID ?? 0);
        if ($suid <= 0) $suid = NextUniqueID();
        $sown = is_array($sub) ? intval($sub['Owner'] ?? 0) : intval($sub->Owner ?? 0);
        $sctl = is_array($sub) ? intval($sub['Controller'] ?? $sown) : intval($sub->Controller ?? $sown);
        $caps = is_array($sub) ? ($sub['Captives'] ?? []) : ($sub->Captives ?? []);
        $gDeferredReplacements[] = ['kind' => 'upgrade_to_unit', 'uid' => $suid, 'controller' => $sctl,
            'owner' => $sown, 'cardID' => $scid, 'captives' => is_array($caps) ? $caps : []];
    }
}

// Drain the deferred defeat-replacement bag (CR replacement effects). Called at action end (and at
// combat resolution). For each deferred would-be-defeated unit still in play, offer its controller the
// optional replacement; if declined or no valid target remains, the defeat is carried out for real.
// A deferred replacement queues an interactive YESNO and is resolved by the CUSTOM decision behind it —
// but the player ANSWERS in a LATER request, in a fresh process. Any rebuild data parked in an in-memory
// global is therefore gone by the time the handler runs (this used to be `$gReplaceSnapshots`, and the
// handlers silently returned on the miss, so JTL_094 Luke was neither rebuilt nor discarded — he vanished).
// The snapshot instead rides the CUSTOM decision's own Param, which IS serialized with the gamestate, and
// is discarded automatically with the decision. Zone fields are space-delimited, so use base64url (no
// spaces, no '+' or '/') and strip '=' padding.
function _SWUEncodeReplacementSnapshot(array $e): string {
    return rtrim(strtr(base64_encode(json_encode($e)), '+/', '-_'), '=');
}
function _SWUDecodeReplacementSnapshot(string $s): ?array {
    if ($s === '') return null;
    $pad = strlen($s) % 4;
    if ($pad) $s .= str_repeat('=', 4 - $pad);
    $json = base64_decode(strtr($s, '-_', '+/'), true);
    if ($json === false) return null;
    $a = json_decode($json, true);
    return is_array($a) ? $a : null;
}

function SWUFlushDeferredReplacements(): void {
    global $gDeferredReplacements, $playerID;
    if (empty($gDeferredReplacements)) return;
    $bag = $gDeferredReplacements;
    $gDeferredReplacements = [];
    foreach ($bag as $e) {
        $ctrl = intval($e['controller']);
        $uid  = intval($e['uid']);
        if (($e['kind'] ?? '') === 'upgrade_to_unit') {
            // Pilot UPGRADE → ground unit (JTL_094). Host is already gone; rebuild from the snapshot,
            // which rides the CUSTOM param so it survives the request boundary before the answer.
            $snap = _SWUEncodeReplacementSnapshot($e);
            DecisionQueueController::AddDecision($ctrl, "YESNO", "-", 1,
                tooltip:"Move_this_Pilot_to_the_ground_arena_as_a_unit_instead_of_defeating_it?");
            DecisionQueueController::AddDecision($ctrl, "CUSTOM", "DEFEAT_REPLACE_UPG|{$ctrl}|{$uid}|{$snap}", 1);
            continue;
        }
        if (($e['kind'] ?? '') === 'rampart_save') {
            // HMW_060 Vice Admiral Rampart — offer the base controller "defeat Rampart instead of the base
            // upgrade?". The upgrade is still on the base (re-find by the stamped UID). If Rampart has since
            // left play, or the upgrade is already gone, resolve directly with no prompt.
            $hostMz = (string)($e['hostMz'] ?? '');
            $idx = _SWUBaseUpgradeIndexByUID($ctrl, $hostMz, $uid);
            if ($idx < 0) continue;                                   // upgrade already gone
            if (!_SWUControlsCardInPlay($ctrl, 'HMW_060')) {          // no Rampart → defeat the upgrade for real
                SWUDefeatUpgrade($ctrl, $hostMz, $idx, false, true);
                continue;
            }
            $snap = _SWUEncodeReplacementSnapshot($e);
            DecisionQueueController::AddDecision($ctrl, "YESNO", "-", 1,
                tooltip:"Defeat_Vice_Admiral_Rampart_instead_of_the_base_upgrade?");
            DecisionQueueController::AddDecision($ctrl, "CUSTOM", "RAMPART_SAVE|{$ctrl}|{$uid}|{$snap}", 1);
            continue;
        }
        // Unit → pilot upgrade (JTL_049). The unit is still parked in play; re-find by UID.
        $saved = $playerID; $playerID = $ctrl;
        $mz = SWUFindMzByUID($uid);
        $playerID = $saved;
        if ($mz === null) continue; // already gone
        if (empty(_SWUPilotlessFriendlyVehicleMzs($ctrl, $uid))) {
            SWUDefeatUnit($ctrl, $mz, true); // no target → real defeat
            continue;
        }
        DecisionQueueController::AddDecision($ctrl, "YESNO", "-", 1,
            tooltip:"Attach_this_unit_to_a_friendly_Vehicle_instead_of_defeating_it?");
        DecisionQueueController::AddDecision($ctrl, "CUSTOM", "DEFEAT_REPLACE|{$ctrl}|{$uid}", 1);
    }
}

function OnExhaustCard($player, $mzID) {
    global $playerID;
    $savedPID = $playerID;
    $playerID = intval($player);
    $obj = GetZoneObject($mzID);
    if ($obj !== null && !$obj->removed) {
        // "Can't be exhausted by enemy card abilities" (LOF_040 / LOF_073). Self-exhaust (attacking,
        // cost payment — actor == controller) is always allowed; only an opponent's exhaust is blocked.
        if (intval($player) === intval($obj->Controller ?? $player) || !SWUAvoidsExhaust($obj)) {
            $obj->Status = 0;
        }
    }
    $playerID = $savedPID;
    return $mzID;
}

// SEC_037 Cantwell Arrestor Cruiser — "that unit can't ready while THIS unit is in play." The lock is
// per-instance (target UID + source UID): stored on the target's controller as SWU_CR37_{tgtUID}_{srcUID}.
// It holds while the source SEC_037 instance is still in play (any arena) and lifts automatically when
// the source leaves — checked at read time, with stale flags pruned lazily. NOT cleared at round start.
function _SWUReadyLockedWhileSourceInPlay(int $controller, int $targetUID): bool {
    if ($targetUID <= 0) return false;
    $zone = &GetGlobalEffects($controller);
    $prefix = 'SWU_CR37_' . $targetUID . '_';
    $locked = false;
    for ($i = count($zone) - 1; $i >= 0; $i--) {
        $f = $zone[$i]->CardID ?? '';
        if (!str_starts_with($f, $prefix)) continue;
        $srcUID = intval(substr($f, strlen($prefix)));
        if ($srcUID > 0 && SWUFindMzByUID($srcUID) !== null) {
            $locked = true;                 // source still in play → lock holds
        } else {
            array_splice($zone, $i, 1);     // source gone → prune the stale lock
        }
    }
    return $locked;
}

function OnReadyCard($player, $mzID) {
    global $playerID;
    $savedPID = $playerID;
    $playerID = intval($player);
    $obj = GetZoneObject($mzID);
    if ($obj !== null && !$obj->removed) {
        // LOF_098 — "while in the space arena, she can't ready" by any "Ready a unit" effect.
        if (($obj->CardID ?? '') === 'LOF_098' && strpos((string)$mzID, 'SpaceArena') !== false) {
            $playerID = $savedPID; return $mzID;
        }
        // SOR_186 No Good to Me Dead: a unit flagged "can't ready this round" doesn't ready from any
        // effect this round (the regroup ready step is gated separately in RegroupPhaseStart). Log the
        // prevention so a blocked "ready a unit" effect (Bravado SHD_182, Motti SOR_226's When Defeated,
        // etc.) is visible in the game log rather than silently no-op'ing.
        $uid  = intval($obj->UniqueID ?? 0);
        $ctrl = intval($obj->Controller ?? $player);
        if ($uid > 0 && GlobalEffectCount($ctrl, 'SWU_CANT_READY_' . $uid) > 0) {
            AddGameLogEntry('EFFECT', GameLogCardRef((string)($obj->CardID ?? '')) . " can't ready this round (" . GameLogCardRef('SOR_186') . ")");
            $playerID = $savedPID; return $mzID;
        }
        // SEC_037 locked-while-source-in-play / LAW_077 / SHD_193 — see _SWUUnitCantReadyNow.
        if (_SWUUnitCantReadyNow($obj)) { $playerID = $savedPID; return $mzID; }
        $obj->Status = 1;
        _SWUTs26063OnEnemyReady($obj);   // Rex's DC-17s — ready its host when an enemy unit readies (action phase)
        // JTL_192 In Debt to Crimson Dawn — "When attached unit readies: exhaust it unless its controller
        // pays 2 resources." Fires for ANY ready, not just the regroup ready step (which is handled directly
        // in RegroupPhaseStart via SWUQueueJTL192RegroupTriggers, NOT through OnReadyCard — so no double-tax):
        // a mid-phase ready effect (e.g. SOR_169 Keep Fighting) triggers the tax here.
        if (_SWUUnitHasUpgrade($obj, 'JTL_192')) {
            DecisionQueueController::AddDecision($ctrl, 'YESNO', '', 1,
                'Pay_2_resources_to_keep_this_unit_ready?_(No_exhausts_it)');
            DecisionQueueController::AddDecision($ctrl, 'CUSTOM', "JTL_192#0|{$mzID}", 1);
        }
        // ASH_088 The Conflict Within — "When this unit readies: you may pay 3 resources. If you don't,
        // exhaust this unit." Same structure as JTL_192: the regroup ready step is handled directly in
        // RegroupPhaseStart (SWUQueueASH088RegroupTriggers, NOT through OnReadyCard → no double-tax); a
        // mid-phase ready effect (e.g. SOR_169 Keep Fighting) triggers the tax here.
        if (_SWUUnitHasUpgrade($obj, 'ASH_088')) {
            DecisionQueueController::AddDecision($ctrl, 'YESNO', '', 1,
                'Pay_3_resources_to_keep_this_unit_ready?_(No_exhausts_it)');
            DecisionQueueController::AddDecision($ctrl, 'CUSTOM', "ASH_088#0|{$mzID}", 1);
        }
    }
    $playerID = $savedPID;
    return $mzID;
}

// Mid-phase "this unit can't ready" restrictions, shared by OnReadyCard and by any effect that readies a
// unit WITHOUT going through it (TS26_63 Rex's DC-17s writes Status directly to avoid recursing into the
// ready observers). The regroup step has its own, wider list — that one also covers wordings which only
// skip the regroup ready, which these effects must NOT honour.
function _SWUUnitCantReadyNow($obj): bool {
    if ($obj === null) return false;
    $uid  = intval($obj->UniqueID ?? 0);
    $ctrl = intval($obj->Controller ?? 0);
    // SEC_037: locked "can't ready while [the source] is in play."
    if ($uid > 0 && $ctrl > 0 && _SWUReadyLockedWhileSourceInPlay($ctrl, $uid)) return true;
    // LAW_077 Shadow of Stygeon Prime: attached unit can't ready (continuous while attached).
    if (_SWUUnitHasUpgrade($obj, 'LAW_077')) return true;
    // SHD_193 Frozen in Carbonite: attached unit can't ready (continuous while attached).
    if (_SWUUnitHasUpgrade($obj, 'SHD_193')) return true;
    return false;
}

// TS26_63 Rex's DC-17s (upgrade) — "Attached unit gains: When an enemy unit readies during the action
// phase, ready this unit. Once each round." Fires from OnReadyCard after $readied is readied.
function _SWUTs26063OnEnemyReady($readied): void {
    if (GetCurrentPhase() !== 'MAIN') return;                 // action phase only
    $rctrl = intval($readied->Controller ?? 0);
    if ($rctrl <= 0) return;
    $p = OtherPlayer($rctrl);                                 // the host controller (enemy of the readied unit)
    foreach (GetField($p) as $host) {
        if (empty($host->removed) && _SWUUnitHasUpgrade($host, 'TS26_63')) {
            $huid = intval($host->UniqueID ?? 0);
            if (GlobalEffectCount($p, 'SWU_TS26063_USED_' . $huid) > 0) continue;   // once each round
            // Writing Status directly avoids recursing into OnReadyCard's observers, but it also skipped
            // its can't-ready checks — a host under Frozen in Carbonite readied anyway. Check them here.
            // Deliberately BEFORE consuming the once-per-round use: a ready that cannot happen is not a use.
            if (_SWUUnitCantReadyNow($host)) continue;
            // Same reasoning for a host that is ALREADY ready — there is nothing to ready, so the once-per-
            // round use is still available for a later enemy ready in the same round.
            if (intval($host->Status ?? 0) === 1) continue;
            AddGlobalEffects($p, 'SWU_TS26063_USED_' . $huid);
            $host->Status = 1;                                // ready the host directly (no recursion into OnReadyCard)
        }
    }
}

// ── Pregame DQ handlers ─────────────────────────────────────────────────────

// Undo boundary for a pregame step (each mulligan decision + each starting-resource choice). Queued
// immediately BEFORE the step it guards, so the snapshot captures the still-pending decision and the
// pre-step RNG counter: an undo restores both, so re-driving an undone mulligan replays the identical
// redraw (deterministic — requirement #6), and a player can step back through their pregame choices.
// 'pregame-step' is a non-'action' boundary, so in a public game the undo requires opponent consent.
$customDQHandlers["PushPregameSnapshot"] = function($player, $parts, $lastDecision) {
    $seat = isset($parts[0]) ? intval($parts[0]) : intval($player);
    PushUndoSnapshot($seat, 'pregame-step');
};

$customDQHandlers["MulliganDecision"] = function($player, $parts, $lastDecision) {
    $targetPlayer = isset($parts[0]) ? intval($parts[0]) : intval($player);
    if (strtoupper($lastDecision) !== "YES") return;

    // Shuffle hand back into deck then draw 6 (SWU CR 1.8 setup)
    global $playerID;
    $savedPID = $playerID;
    $playerID = $targetPlayer;

    $hand = GetHand($targetPlayer);
    for ($i = count($hand) - 1; $i >= 0; $i--) {
        if (!isset($hand[$i]->removed) || !$hand[$i]->removed) {
            MZMove($targetPlayer, "myHand-$i", "myDeck");
        }
    }
    $deck = &GetDeck($targetPlayer);
    // Deterministic mulligan reshuffle: restoring the counter+seed on undo replays the same redraw,
    // so undo + re-mulligan yields the identical second hand (Task 3, undo redesign).
    EngineShuffle($deck, false);

    // Redraw the player's OWN starting hand size, not a flat 6 — a base may modify it (JTL_021
    // Colossus -1, JTL_028 Nabat Village +3). Same helper QueuePregameSetup uses for the opening hand;
    // hardcoding 6 here meant Colossus dealt 5 to start and then handed back 6 on the mulligan.
    $mullBaseArr = &GetBase($targetPlayer);
    $mullBaseID  = !empty($mullBaseArr) ? ($mullBaseArr[0]->CardID ?? '') : '';
    $mullHandSize = max(0, 6 + SWUStartingHandModifier($mullBaseID));
    for ($i = 0; $i < $mullHandSize; $i++) DoDrawCard($targetPlayer, 1);

    $playerID = $savedPID;
};

// CR 5.2.1.f "resource two cards" — ONE multi-select prompt for both, not two sequential picks:
// the player marks 2 cards in hand and confirms, so they can weigh the pair together.
//
// The count is derived as "how many of the 2 am I still missing" rather than a literal 2. A game
// created BEFORE this change has TWO ChooseStartingResource entries sitting in its saved queue; the
// first now takes both cards and the second sees 2 resources already down and no-ops, so in-flight
// games finish with 2 resources instead of 4. (Also why the handler name is unchanged.)
$customDQHandlers["ChooseStartingResource"] = function($player, $parts, $lastDecision) {
    global $playerID;
    $savedPID = $playerID;
    $playerID = intval($player);
    $hand = GetHand($player);
    $liveHand = 0;
    for ($i = 0; $i < count($hand); $i++) {
        if (!isset($hand[$i]->removed) || !$hand[$i]->removed) $liveHand++;
    }
    $playerID = $savedPID;

    $want = max(0, 2 - SWUResourceCount(intval($player)));
    $n = min($want, $liveHand);
    if ($n <= 0) return;

    // Use zone reference ("myHand") rather than specific indices so the choice
    // remains valid after WriteGamestate rewrites the hand. WriteGamestate strips
    // removed tombstones and resets indices to 0-N; a saved "myHand-6" would point
    // at nothing on the next load, whereas "myHand" always means "any live card".
    // The client expands a bare zone spec into every card of that zone, so the whole
    // hand is selectable inline (glow + "N selected / 2 max" confirm bar).
    DecisionQueueController::AddDecision($player, "MZMULTICHOOSE", "{$n}|{$n}|myHand", 40,
        "Choose_2_cards_to_resource");
    DecisionQueueController::AddDecision($player, "CUSTOM", "ApplyStartingResource", 40);
};

// Answer is the '&'-joined mzID list from the MZMULTICHOOSE. MZMove tombstones the source rather
// than splicing the hand, so every mzID in the list stays valid across the loop.
$customDQHandlers["ApplyStartingResource"] = function($player, $parts, $lastDecision) {
    if (SWUDecisionDeclined($lastDecision)) return;
    $picks = array_values(array_filter(explode('&', $lastDecision),
        fn($s) => $s !== '' && $s !== '-' && $s !== 'PASS'));
    if (empty($picks)) return;

    global $playerID;
    $savedPID = $playerID;
    $playerID = intval($player);
    foreach ($picks as $mz) {
        $newResource = MZMove($player, $mz, "myResources");
        // Hand cards don't carry a Status field; Resources must default to 1 (ready).
        if ($newResource !== null) {
            $newResource->Status = 1;
            if (function_exists('SWUTelemetryBumpCard')) SWUTelemetryBumpCard($player, $newResource->CardID ?? '', 'resourced'); // Plan D telemetry
        }
    }
    $playerID = $savedPID;
};

$customDQHandlers["SWURegroupResource"] = function($player, $parts, $lastDecision) {
    if ($lastDecision !== "YES") return;
    global $playerID;
    $savedPID = $playerID;
    $playerID = intval($player);
    $hand = GetHand($player);
    $hasCards = false;
    for ($i = 0; $i < count($hand); $i++) {
        if (!isset($hand[$i]->removed) || !$hand[$i]->removed) { $hasCards = true; break; }
    }
    if ($hasCards) {
        DecisionQueueController::AddDecision($player, "MZCHOOSE", "myHand", 1, tooltip:"Choose_a_card_to_resource");
        DecisionQueueController::AddDecision($player, "CUSTOM", "SWUApplyRegroupResource", 1);
    }
    $playerID = $savedPID;
};

$customDQHandlers["SWUApplyRegroupResource"] = function($player, $parts, $lastDecision) {
    if ($lastDecision === "-" || $lastDecision === "" || $lastDecision === "PASS") return;
    global $playerID;
    $savedPID = $playerID;
    $playerID = intval($player);
    $newResource = MZMove($player, $lastDecision, "myResources");
    if ($newResource !== null) {
        $newResource->Status = 0; // enters exhausted, readied in ReadyPhase
        // Hand slides into the RESOURCE ZONE ANCHOR (the collapsed badge), scoped to the resourcing
        // player — see the note in SWURampResourceReady for why both apply.
        SWUQueueZoneMoveAnim($lastDecision, 'myResources-0', intval($player), 420, null, intval($player));
        if (function_exists('SWUTelemetryBumpCard')) SWUTelemetryBumpCard($player, $newResource->CardID ?? '', 'resourced'); // Plan D telemetry
        AddGameLogEntry('RESOURCE', 'P' . intval($player) . ' resourced a card');
    }
    $playerID = $savedPID;
};

// ── Phase handlers ──────────────────────────────────────────────────────────

// These stubs are defined before the GA template code so the guards at the
// GA definitions keep these SWUSim versions. Add real logic here as phases
// are implemented.

function MainPhase() {
    // TODO: consecutive-pass tracking and TurnPlayer swap
}

function DrawPhase() {
    // Draw is a step WITHIN the Regroup phase (not a separate phase in the log) — only the
    // "— Regroup Phase —" banner is emitted (by RegroupPhaseStart).
    // CR 5.4.b: each player draws 2 cards. Twin Suns: EVERY live seat draws, not just seats 1-2.
    foreach (GetLiveSeatsArray() as $p) DoDrawCard($p, 2);
}

function ResourcePhase() {
    // Resource is a step WITHIN the Regroup phase (not a separate phase in the log).
    // CR 5.4.c: starting with the active player (initiative holder), each player
    // may resource 1 card from hand. Player selects a card or declines with "-".
    // Twin Suns: go clockwise across EVERY live seat starting from the initiative holder (not just P1/P2).
    $firstPlayer = intval(GetFirstPlayer());
    $order = GetLiveSeatsArray();
    $startIdx = array_search($firstPlayer, $order, true);
    if ($startIdx === false) $startIdx = 0;
    $orderedSeats = array_merge(array_slice($order, $startIdx), array_slice($order, 0, $startIdx));
    // P2 is a passive, non-interactive seat in goldfish (and in an interrupted "Play from Here"
    // replay) — it can never answer a decision. Its regroup-resource MZMAYCHOOSE would otherwise
    // sit in the queue forever and hang the RES step (the ghost has an empty hand + empty deck, so
    // there is nothing to resource anyway). Skip it — mirroring the goldfish auto-pass in
    // SWUSwapTurnPlayer and the $skipGoldfishBot mulligan skip. Real 2-player + hotseat games (where
    // P2 is a live seat that answers its own prompts) are unaffected.
    $isPassiveSeat = function($pl): bool {
        return intval($pl) === 2
            && (SWUGameMode() === 'goldfish'
                || (function_exists('MatchReplayIsInterrupted') && MatchReplayIsInterrupted()));
    };
    $queueResource = function($pl) use ($isPassiveSeat) {
        if ($isPassiveSeat($pl)) return;
        DecisionQueueController::AddDecision($pl, "MZMAYCHOOSE", "myHand", 1, tooltip:"Resource_up_to_1_card");
        DecisionQueueController::AddDecision($pl, "CUSTOM",      "SWUApplyRegroupResource", 1);
    };
    foreach ($orderedSeats as $pl) $queueResource($pl);   // initiative holder first, then clockwise (CR 5.4.c)
    // Undo boundary: snapshot AFTER the resource prompt is queued so a regular Undo from the action-phase
    // start lands here with the resource choice re-presented (re-pick your resource); it also floors Undo
    // Phase (the phase jump stops at the first action ABOVE this boundary).
    PushUndoSnapshot($firstPlayer, 'resource');
}

function ReadyPhase() {
    // CR 5.4.d: ready all exhausted cards for both players (units, resources, leader).
    // Leader.EpicActionUsed is NOT reset — that flag persists the whole game.
    for ($p = 1; $p <= SeatCountForGame(); $p++) {
        $resources = &GetResources($p);
        for ($i = 0; $i < count($resources); $i++) {
            if (!isset($resources[$i]->removed) || !$resources[$i]->removed) $resources[$i]->Status = 1;
        }
        // SOR_186 No Good to Me Dead: a flagged unit doesn't ready this regroup; consume the flag so
        // it readies next round. (Shared by ground + space arenas.)
        $cantReadyRegroup = function($u) use ($p): bool {
            $uid = intval($u->UniqueID ?? 0);
            if ($uid > 0 && GlobalEffectCount($p, 'SWU_CANT_READY_' . $uid) > 0) {
                SWUClearGlobalEffectsByPrefix($p, 'SWU_CANT_READY_' . $uid);
                return true;
            }
            // HMW_095 Carbonite Chamber (and HMW_121) — "doesn't ready during the NEXT regroup phase."
            // Deliberately a SEPARATE flag from SOR_186's SWU_CANT_READY_: that one also blocks explicit
            // mid-phase "ready a unit" effects, which this wording does not. Read only here, and consumed
            // so the unit readies the round after.
            if ($uid > 0 && GlobalEffectCount($p, 'SWU_SKIP_REGROUP_READY_' . $uid) > 0) {
                SWUClearGlobalEffectsByPrefix($p, 'SWU_SKIP_REGROUP_READY_' . $uid);
                return true;
            }
            // JTL_182 Rampart: doesn't ready during regroup unless its power is 4 or more.
            if (($u->CardID ?? '') === 'JTL_182' && ObjectCurrentPower($u) < 4) return true;
            // SEC_037: locked "can't ready while [the source] is in play" (not consumed — lifts when
            // the source leaves play).
            if ($uid > 0 && _SWUReadyLockedWhileSourceInPlay($p, $uid)) return true;
            // LAW_077 Shadow of Stygeon Prime: attached unit can't ready while the upgrade is attached.
            if (_SWUUnitHasUpgrade($u, 'LAW_077')) return true;
            // SHD_193 Frozen in Carbonite: attached unit can't ready while the upgrade is attached.
            if (_SWUUnitHasUpgrade($u, 'SHD_193')) return true;
            return false;
        };
        $ground = &GetGroundArena($p);
        for ($i = 0; $i < count($ground); $i++) {
            if ((!isset($ground[$i]->removed) || !$ground[$i]->removed) && !$cantReadyRegroup($ground[$i])) $ground[$i]->Status = 1;
        }
        $space = &GetSpaceArena($p);
        for ($i = 0; $i < count($space); $i++) {
            // LOF_098 — "while in the space arena, she can't ready." Blocks the regroup ready here (and
            // any "Ready a unit" effect via OnReadyCard); "enters play ready" is a separate path, unaffected.
            if (($space[$i]->CardID ?? '') === 'LOF_098') continue;
            if ((!isset($space[$i]->removed) || !$space[$i]->removed) && !$cantReadyRegroup($space[$i])) $space[$i]->Status = 1;
        }
        $leader = &GetLeader($p);
        for ($i = 0; $i < count($leader); $i++) {
            if (!isset($leader[$i]->removed) || !$leader[$i]->removed) $leader[$i]->Ready = true;
        }
    }
    // LAW_072 Max Rebo: when a second (additional) regroup phase still follows this round, DON'T advance
    // the round here — the increment happens on the final regroup's ready (so the round counter + the
    // "=== Round N ===" banner fire once per round, not once per regroup phase).
    if (!_SWUNeedsExtraRegroup()) {
        global $gTurnNumber;
        $gTurnNumber = intval($gTurnNumber) + 1;
        AddGameLogEntry('PHASE', '=== Round ' . intval($gTurnNumber) . ' ===');
    }

    // SOR_193 Millennium Falcon — "When you ready cards during the regroup phase:
    // Either pay [1 resource] or return this unit to her owner's hand."
    SWUQueueFalconRegroupTriggers();

    // JTL_192 In Debt to Crimson Dawn — "When attached unit readies: exhaust it unless its controller
    // pays 2 resources." Fires for every host that just readied in the regroup ready step.
    SWUQueueJTL192RegroupTriggers();

    // ASH_088 The Conflict Within — "When this unit readies: you may pay 3 resources. If you don't,
    // exhaust this unit." Same shape as JTL_192 (pay 3 instead of 2).
    SWUQueueASH088RegroupTriggers();

    // TWI_068 Foresight — granted "When the regroup phase starts (before drawing cards): Name a card,
    // then look at the top card of your deck. If it's the named card, you may reveal and draw it."
    SWUQueueTWI068RegroupTriggers();
}

// TWI_068 Foresight — queue the name-a-card / peek-top / may-draw for each unit carrying a TWI_068
// upgrade, at the start of the regroup phase (before the draw step). Model: SWUQueueJTL192RegroupTriggers.
function SWUQueueTWI068RegroupTriggers(): void {
    global $playerID;
    $savedPID = $playerID;
    for ($p = 1; $p <= SeatCountForGame(); $p++) {
        $playerID = $p;
        foreach (['myGroundArena', 'mySpaceArena'] as $zone) {
            foreach (ZoneSearch($zone, ['Unit']) as $mzID) {
                $obj = GetZoneObject($mzID);
                if ($obj === null || ($obj->removed ?? false)) continue;
                if (!_SWUUnitHasUpgrade($obj, 'TWI_068')) continue;
                if (empty(GetDeck($p))) continue;   // no deck → nothing to peek
                DecisionQueueController::AddDecision($p, 'NAMECARD', '', 1, 'Name_a_card_(Foresight)');
                DecisionQueueController::AddDecision($p, 'CUSTOM', 'TWI_068#0', 1);
            }
        }
    }
    $playerID = $savedPID;
}

// ASH_088 The Conflict Within — queue a "pay 3 or be exhausted" decision for each unit carrying an
// ASH_088 upgrade that readied during the regroup ready step. (Clone of SWUQueueJTL192RegroupTriggers.)
function SWUQueueASH088RegroupTriggers(): void {
    global $playerID;
    $savedPID = $playerID;
    for ($p = 1; $p <= SeatCountForGame(); $p++) {
        $playerID = $p;
        foreach (['myGroundArena', 'mySpaceArena'] as $zone) {
            foreach (ZoneSearch($zone, ['Unit']) as $mzID) {
                $obj = GetZoneObject($mzID);
                if ($obj === null || ($obj->removed ?? false)) continue;
                if (!_SWUUnitHasUpgrade($obj, 'ASH_088')) continue;
                DecisionQueueController::AddDecision($p, 'YESNO', '', 1,
                    'Pay_3_resources_to_keep_this_unit_ready?_(No_exhausts_it)');
                DecisionQueueController::AddDecision($p, 'CUSTOM', "ASH_088#0|{$mzID}", 1);
            }
        }
    }
    $playerID = $savedPID;
}

// Queue the SOR_193 Millennium Falcon "ready cards" trigger for every Falcon in
// play, controller's first (active player 1, then 2). Each Falcon's controller is
// asked to pay 1 resource (keep) or bounce it to hand.
function SWUQueueFalconRegroupTriggers(): void {
    global $playerID;
    $savedPID = $playerID;
    for ($p = 1; $p <= SeatCountForGame(); $p++) {
        $playerID = $p;
        foreach (['myGroundArena', 'mySpaceArena'] as $zone) {
            foreach (ZoneSearch($zone, ['Unit']) as $mzID) {
                $obj = GetZoneObject($mzID);
                if ($obj === null || ($obj->removed ?? false)) continue;
                if (($obj->CardID ?? '') !== 'SOR_193') continue;
                DecisionQueueController::AddDecision($p, 'YESNO', '', 1,
                    'Pay_1_resource_to_keep_Millennium_Falcon?_(No_returns_her_to_hand)');
                DecisionQueueController::AddDecision($p, 'CUSTOM', "SOR_193#0|{$mzID}", 1);
            }
        }
    }
    $playerID = $savedPID;
}

// JTL_192 In Debt to Crimson Dawn — queue a "pay 2 or be exhausted" decision for each unit carrying a
// JTL_192 upgrade that readied during the regroup ready step. (Modeled on SWUQueueFalconRegroupTriggers.)
function SWUQueueJTL192RegroupTriggers(): void {
    global $playerID;
    $savedPID = $playerID;
    for ($p = 1; $p <= SeatCountForGame(); $p++) {
        $playerID = $p;
        foreach (['myGroundArena', 'mySpaceArena'] as $zone) {
            foreach (ZoneSearch($zone, ['Unit']) as $mzID) {
                $obj = GetZoneObject($mzID);
                if ($obj === null || ($obj->removed ?? false)) continue;
                if (!_SWUUnitHasUpgrade($obj, 'JTL_192')) continue;
                DecisionQueueController::AddDecision($p, 'YESNO', '', 1,
                    'Pay_2_resources_to_keep_this_unit_ready?_(No_exhausts_it)');
                DecisionQueueController::AddDecision($p, 'CUSTOM', "JTL_192#0|{$mzID}", 1);
            }
        }
    }
    $playerID = $savedPID;
}

// ─── Pregame setup modifiers (CR 5.2.1 step d) ────────────────────────────────
// Base cards that change how many cards their controller draws in the starting
// hand. Returns a signed delta off the default 6. Shared by CreateGame's
// QueuePregameSetup (production) and the test harness's Option-B builder so both
// honor the same rule. JTL_024/025 (min-deck-size bases) live in ValidateDeck —
// they change deck legality, not the opening draw, so they are NOT listed here.
function SWUStartingHandModifier($baseID): int {
    static $mods = [
        'JTL_021' => -1,  // Colossus: draw 1 fewer card
        'JTL_028' => +3,  // Nabat Village: draw 3 more cards
    ];
    return $mods[$baseID] ?? 0;
}

// Bases whose controller can't take a mulligan.
function SWUBaseSuppressesMulligan($baseID): bool {
    static $set = ['JTL_028' => true]; // Nabat Village
    return isset($set[$baseID]);
}

function SWUClearDiscardModifiers(): void {
    for ($p = 1; $p <= SeatCountForGame(); $p++) {
        $discard = &GetDiscard($p);
        for ($i = 0; $i < count($discard); $i++) {
            if (isset($discard[$i]->removed) && $discard[$i]->removed) continue;
            if (!empty($discard[$i]->Modifier)) $discard[$i]->Modifier = '';
        }
    }
}

// LAW regroup-start triggers (fire at the start of the regroup phase, before the next ReadyPhase).
function _SWULawRegroupStartTriggers(): void {
    global $playerID; $saved = $playerID;
    for ($p = 1; $p <= SeatCountForGame(); $p++) {
        $playerID = $p;
        // LAW_071 The Max Rebo Band — "When the regroup phase starts: create a Credit token."
        $n071 = _SWUCountActiveUnitsWithCardID($p, 'LAW_071');
        for ($i = 0; $i < $n071; $i++) SWUCreateCreditToken($p, 1);
        // LAW_073 Patient Hunter — "When the regroup phase starts: you may give an Experience token to a
        // non-leader unit; if you do, that unit can't ready during this regroup phase."
        $n073 = _SWUCountActiveUnitsWithCardID($p, 'LAW_073');
        if ($n073 > 0) {
            $targets = [];
            foreach (["myGroundArena", "mySpaceArena", "theirGroundArena", "theirSpaceArena"] as $z) {
                foreach (ZoneSearch($z, NonLeaderUnitFilter) as $mz) {
                    $o = GetZoneObject($mz);
                    if ($o !== null && empty($o->removed)) $targets[] = $mz;
                }
            }
            for ($i = 0; $i < $n073 && !empty($targets); $i++) {
                SWUQueueMayChooseTarget($p, $targets, "Give_an_Experience_token_to_a_non-leader_unit_(it_can't_ready_this_regroup)?", "Choose_a_unit", "LAW_073#0|" . $p);
            }
        }
        // LAW_077 Shadow of Stygeon Prime — granted "When the regroup phase starts: deal 2 damage to
        // your base" (the attached unit's controller's base). Once per attached LAW_077 instance.
        foreach (array_merge(GetGroundArena($p), GetSpaceArena($p)) as $u) {
            if (empty($u->removed) && _SWUUnitHasUpgrade($u, 'LAW_077')) SWUDealDamageToBase(2, $p);
        }
    }
    $playerID = $saved;
}

// HMW_004 Grand Moff Tarkin, DEPLOYED side (The Death Star) — "When the regroup phase starts: You may
// defeat a base with 10 or less remaining HP." The printed text carries no friendly/enemy qualifier, so
// EITHER base is a legal target once it is at 10 or less remaining HP — including your own, which simply
// loses you the game. The threshold wording matters in Twin Suns, where several bases can qualify; in
// 2-player it is my base and their base.
function _SWUHmw004RegroupBaseDefeat(): void {
    global $playerID; $saved = $playerID;
    for ($p = 1; $p <= SeatCountForGame(); $p++) {
        if (!_SWULeaderDeployed($p, 'HMW_004')) continue;   // deployed side only
        $playerID = $p;
        $targets = [];
        foreach (['myBase-0' => $p, 'theirBase-0' => OtherPlayer($p)] as $mz => $owner) {
            $b = GetBase($owner);
            if (empty($b) || !empty($b[0]->removed)) continue;
            if (intval(CardHp($b[0]->CardID)) <= 0) continue;
            if (SWUBaseRemainingHp($owner) <= 10) $targets[] = $mz;
        }
        if (empty($targets)) continue;
        SWUQueueMayChooseTarget($p, $targets, "Defeat_a_base_with_10_or_less_remaining_HP?",
            "Choose_a_base_to_defeat", 'HMW_004#0');
    }
    $playerID = $saved;
}

// ── LAW_072 Max Rebo — "There is an additional regroup phase after the first regroup phase each round." ──
// Each Max Rebo in play adds ONE additional regroup phase — they STACK, so total regroups = 1 + count
// (both players' Max Rebos count). SWU_REGROUP_NUM counts the regroup phases run this round (incremented
// at each RegroupPhaseStart, reset to 0 at ActionPhaseStart).
function _SWUMaxReboCount(): int {
    $n = 0;
    for ($p = 1; $p <= SeatCountForGame(); $p++) {
        foreach (GetGroundArena($p) as $u) {
            if (empty($u->removed) && ($u->CardID ?? '') === 'LAW_072') $n++;
        }
    }
    return $n;
}
// True while another regroup is still owed this round: fewer regroups have run (SWU_REGROUP_NUM) than the
// total owed (1 + Max Rebo count), i.e. SWU_REGROUP_NUM <= count. Read by the READY→ transition
// (TurnController) to loop back to RGS, and by ReadyPhase to DEFER the round increment to the final regroup.
function _SWUNeedsExtraRegroup(): bool {
    return intval(GetSWUVar('SWU_REGROUP_NUM', '0')) <= _SWUMaxReboCount();
}

// Turn-controller transition override (consumed by the generated EvaluateTransition).
// LAW_072 Max Rebo: after a regroup's ready step (READY), loop back to a new regroup
// phase (RGS) instead of advancing to the action phase (APS) while another regroup is
// still owed this round. Returns null for every other phase → normal schedule applies.
function EngineTransitionOverride(?string $currentPhase, $input): ?string {
    if ($currentPhase === 'READY' && _SWUNeedsExtraRegroup()) return 'RGS';
    return null;
}

// ASH_227 Heightened Awareness — "Attached unit gains: 'When the regroup phase starts: give an Advantage
// token to this unit.'" Give one Advantage token per ASH_227 upgrade on each in-play unit (both players).
function _SWUAsh227RegroupStart(): void {
    global $playerID; $savedPID = $playerID;
    for ($p = 1; $p <= SeatCountForGame(); $p++) {
        $playerID = $p;
        foreach (['myGroundArena', 'mySpaceArena'] as $z) {
            foreach (ZoneSearch($z, AnyUnitFilter) as $mz) {
                $o = GetZoneObject($mz);
                if (SWUObjGone($o)) continue;
                $n = 0;
                foreach (GetUpgradesOnUnit($o) as $up) { if (($up->CardID ?? '') === 'ASH_227') $n++; }
                for ($i = 0; $i < $n; $i++) DoGiveAdvantageToken($p, $mz);
            }
        }
    }
    $playerID = $savedPID;
}

// ASH_159 Alphabet Squadron U-Wing — "When the regroup phase starts: give an Advantage token to a unit."
// Each ASH_159 in play lets its controller give 1 Advantage to a unit of their choice.
function _SWUAsh159RegroupStart(): void {
    global $playerID; $savedPID = $playerID;
    for ($p = 1; $p <= SeatCountForGame(); $p++) {
        foreach (GetUnitsInPlay($p) as $src) {
            if (empty($src->removed) && ($src->CardID ?? '') === 'ASH_159') {
                $playerID = $p;
                SWUOfferUnitTarget($p, '', [
                    'continuation' => 'GIVE_ADVANTAGE',
                    'prompt' => "Give_an_Advantage_token_to_a_unit",
                ]);
            }
        }
    }

    $playerID = $savedPID;
}

function RegroupPhaseStart(): void {
    // Twin Suns (CR §12.7): if the action phase that just ended contained the first elimination,
    // the game ends now by highest remaining base HP. No-op for 2-player / no elimination.
    _SWUScoreTwinSunsEndOfPhase();
    if (SWUGetGameWinner() !== 0) return;
    AddGameLogEntry('PHASE', '— Regroup Phase —');
    // Telemetry: finalize each seat's per-round counters into a turnResults entry (once per round).
    if (function_exists('SWUTelemetrySnapshotTurn')) { for ($tp = 1; $tp <= SeatCountForGame(); $tp++) SWUTelemetrySnapshotTurn($tp); }
    SetSWUVar('SWU_REGROUP_NUM', (string)(intval(GetSWUVar('SWU_REGROUP_NUM', '0')) + 1)); // LAW_072: count regroups this round
    for ($udp = 1; $udp <= SeatCountForGame(); $udp++) ResetUndoDenyCount($udp);
    SWUClearDiscardModifiers();
    SetSWUVar('SWU_LAST_ACTION', '');      // SEC_194 per-action tracking resets each phase
    for ($_s = 1; $_s <= SeatCountForGame(); $_s++) SetSWUVar('SWU_LAST_ACTION_' . $_s, '');
    SetSWUVar('SWU_ACTION_BASEATK', '');
    _SWURescueBaseCaptives();              // SEC_195 Arrest — base captives' owners rescue them now
    _SWUCheckConfidenceWin();              // SEC_145 Confidence in Victory — arena-control win check
    _SWUCheckFinalShowdownLose();          // SHD_208 Final Showdown — caster loses the game (before the draw step)
    _SWULawRegroupStartTriggers();         // LAW_071 (credit), LAW_073 (Exp + can't-ready) at regroup start
    _SWUHmw004RegroupBaseDefeat();         // HMW_004 (deployed) — may defeat a base at 10 or less remaining HP
    _SWUHmw070RegroupBaseTriggers();       // HMW_070 Dark Sanctum — attached base draws 1 and takes 2 (per copy)
    // TWI_067 The Zillo Beast — "When the regroup phase starts: Heal 5 damage from this unit."
    for ($zp = 1; $zp <= SeatCountForGame(); $zp++) {
        foreach (GetUnitsInPlay($zp) as $zu) {
            if (empty($zu->removed) && ($zu->CardID ?? '') === 'TWI_067' && intval($zu->Damage ?? 0) > 0) {
                $zmz = SWUFindMzByUID(intval($zu->UniqueID ?? -1));
                if ($zmz !== null) OnHealUnit($zp, $zmz, 5);
            }
        }
    }
    // TS26_23 Assault Lander LAAT — "When the regroup phase starts: Deal 4 damage to this unit."
    for ($lp = 1; $lp <= SeatCountForGame(); $lp++) {
        foreach (GetUnitsInPlay($lp) as $lu) {
            if (empty($lu->removed) && ($lu->CardID ?? '') === 'TS26_23') {
                $lmz = SWUFindMzByUID(intval($lu->UniqueID ?? -1));
                if ($lmz !== null) SWUDealDamageToUnit($lmz, 4, $lp);
            }
        }
    }
    // SHD_225 Jetpack — "At the start of the regroup phase, defeat that [Shield] token." One flag per
    // grant (host UID in the flag). Approximation: removes ONE non-removed Shield subcard from the
    // host — if Jetpack's own shield was already consumed and the host gained another shield since,
    // that other token is removed instead (individual tokens aren't identifiable across requests).
    global $playerID;
    for ($jp = 1; $jp <= SeatCountForGame(); $jp++) {
        $jge = &GetGlobalEffects($jp);
        for ($ji = count($jge) - 1; $ji >= 0; $ji--) {
            $jflag = (string)($jge[$ji]->CardID ?? '');
            if (strpos($jflag, 'SWU_SHD225_TOKEN_') !== 0) continue;
            array_splice($jge, $ji, 1);
            $savedJPID = $playerID; $playerID = $jp;
            // Defeat THAT token by its grant tag, wherever it now lives. This used to take "the first
            // Shield on the original host UID", which defeated the WRONG token when the host carried more
            // than one, and defeated a token on the OLD host after the granted one had been moved away.
            // A tag miss is correct and expected: the token was already spent absorbing damage.
            _SWUTakeTaggedShieldToken('SHD225');
            $playerID = $savedJPID;
        }
    }
    // SHD_203 Zorii Bliss — each attack armed "at the start of the regroup phase, discard a card
    // from your hand." One mandatory discard per armed instance (zone-name MZCHOOSE, Han-loop style;
    // an empty hand auto-resolves to '-' and the handler no-ops). Consumed here, NOT prefix-cleared.
    for ($zp = 1; $zp <= SeatCountForGame(); $zp++) {
        $zPending = GlobalEffectCount($zp, 'SWU_SHD203_DISCARD');
        for ($zk = 0; $zk < $zPending; $zk++) {
            RemoveGlobalEffect($zp, 'SWU_SHD203_DISCARD');
            DecisionQueueController::AddDecision($zp, 'MZCHOOSE', 'myHand', 1,
                'Discard_a_card_from_your_hand_(Zorii_Bliss)');
            DecisionQueueController::AddDecision($zp, 'CUSTOM', "DISCARD_FROM_OWN_HAND|{$zp}", 1);
        }
    }
    _SWUAsh227RegroupStart();              // ASH_227 Heightened Awareness — Advantage token to each wearer
    _SWUAsh159RegroupStart();              // ASH_159 Alphabet Squadron U-Wing — Advantage token to a chosen unit

    // LAW_074 Maz Kanata — "At the start of the regroup phase, put that unit on the bottom of your deck
    // (if it is still in play)." Bottom every unit still carrying the SWU_LAW074_BOTTOM marker, to its
    // owner's deck. Drain loop: SWUUnitToBottomOfDeck shifts arena indices, so re-scan after each.
    global $playerID;
    $savedLawPID = $playerID;
    $law074Found = true;
    while ($law074Found) {
        $law074Found = false;
        for ($lp = 1; $lp <= SeatCountForGame(); $lp++) {
            $playerID = $lp;
            foreach (['myGroundArena', 'mySpaceArena'] as $lz) {
                foreach (ZoneSearch($lz, AnyUnitFilter) as $lmz) {
                    $lo = GetZoneObject($lmz);
                    if (SWUObjGone($lo)) continue;
                    if (in_array('SWU_LAW074_BOTTOM', $lo->TurnEffects ?? [])) {
                        SWUUnitToBottomOfDeck($lp, $lmz); // bottoms to the unit's owner's deck
                        $law074Found = true;
                        break 3;
                    }
                }
            }
        }
    }
    $playerID = $savedLawPID;

    // SHD_194 Triple Dark Raid — "Return it to its owner's hand at the end of the phase." Bounce every
    // unit still carrying the SWU_SHD194_RETURN marker to its owner's hand. Drain loop: SWUBounceUnit
    // shifts arena indices, so re-scan after each bounce.
    global $playerID;
    $savedShd194PID = $playerID;
    $shd194Found = true;
    while ($shd194Found) {
        $shd194Found = false;
        for ($vp = 1; $vp <= SeatCountForGame(); $vp++) {
            $playerID = $vp;
            foreach (['myGroundArena', 'mySpaceArena'] as $vz) {
                foreach (ZoneSearch($vz, AnyUnitFilter) as $vmz) {
                    $vo = GetZoneObject($vmz);
                    if (SWUObjGone($vo)) continue;
                    if (in_array('SWU_SHD194_RETURN', $vo->TurnEffects ?? [])) {
                        SWUBounceUnit($vp, $vmz); // returns to the unit's owner's hand
                        $shd194Found = true;
                        break 3;
                    }
                    // "a VEHICLE" is a TRAIT, so the card played may be a Vehicle UPGRADE (TWI_236
                    // Grievous's Wheel Bike) — and "return IT to its owner's hand" covers an upgrade just
                    // as much as a unit. An upgrade is a SUBCARD, never visited by the arena scan, so it
                    // stayed attached forever while the unit case worked.
                    foreach (GetUpgradesOnUnit($vo) as $vu) {
                        if (!in_array('SWU_SHD194_RETURN', $vu->TurnEffects ?? [])) continue;
                        SWUReturnUpgradeToHand($vmz, $vu->CardID ?? '', $vp);
                        $shd194Found = true;
                        break 4;
                    }
                }
            }
        }
    }
    $playerID = $savedShd194PID;

    // SHD_015 Doctor Aphra (leader FRONT side, undeployed) — "When the regroup phase starts: Discard a
    // card from your deck." (Once deployed, the deployed side replaces this — so gate on !Deployed.)
    for ($ap = 1; $ap <= SeatCountForGame(); $ap++) {
        foreach (GetLeader($ap) as $lo) {
            if (empty($lo->removed) && ($lo->CardID ?? '') === 'SHD_015' && empty($lo->Deployed)) {
                SWUMillTopCard($ap);
                break;
            }
        }
    }

    // SOR_219 Sneak Attack — "At the start of the regroup phase, defeat it." Defeat every unit still
    // carrying the SWU_SNEAK_DEFEAT marker (set when it was played by Sneak Attack). Drain loop:
    // SWUDefeatUnit shifts arena indices, so re-scan after each defeat.
    global $playerID;
    $savedSneakPID = $playerID;
    $sneakFound = true;
    while ($sneakFound) {
        $sneakFound = false;
        for ($sp = 1; $sp <= SeatCountForGame(); $sp++) {
            $playerID = $sp;
            foreach (['myGroundArena', 'mySpaceArena'] as $szone) {
                foreach (ZoneSearch($szone, AnyUnitFilter) as $smz) {
                    $so = GetZoneObject($smz);
                    if (SWUObjGone($so)) continue;
                    if (!in_array('SWU_SNEAK_DEFEAT', $so->TurnEffects ?? [])) continue;
                    SWUDefeatUnit($sp, $smz);
                    $sneakFound = true;
                    break 3;
                }
            }
        }
    }
    $playerID = $savedSneakPID;

    // JTL_198 Fireball — "When the regroup phase starts: deal 1 damage to this unit." (one pass; any
    // resulting defeat is handled by the SWUDealDamageToUnit/state-based checks below.)
    for ($rp = 1; $rp <= SeatCountForGame(); $rp++) {
        $playerID = $rp;
        foreach (['myGroundArena', 'mySpaceArena'] as $rz) {
            foreach (ZoneSearch($rz, AnyUnitFilter) as $rmz) {
                $ro = GetZoneObject($rmz);
                if (SWUObjGone($ro)) continue;
                if (($ro->CardID ?? '') === 'JTL_198') SWUDealDamageToUnit($rmz, 1, $rp);
            }
        }
    }
    $playerID = $savedSneakPID;

    // JTL_216 Contracted Hunter's regroup self-defeat is evaluated LOWER DOWN, right after phase-duration
    // effects expire (SWUExpireTurnEffects(SWU_DUR_PHASE)) — so a "this phase" ability-nullify (Force
    // Lightning) has already lifted (Hunter defeats) while a round-long one (Kazuda) is still active
    // (Hunter survives). See the block after the phase-expiry pass below.

    // LOF_019 Vergence Temple — "When the regroup phase starts: If you control a unit with 4 or more
    // remaining HP, the Force is with you." Checked for whichever player's base is Vergence Temple.
    for ($vp = 1; $vp <= SeatCountForGame(); $vp++) {
        $vbaseArr = GetBase($vp);
        if (empty($vbaseArr) || ($vbaseArr[0]->CardID ?? '') !== 'LOF_019') continue;
        $playerID = $vp;
        $hasBig = false;
        foreach (['myGroundArena', 'mySpaceArena'] as $vz) {
            foreach (ZoneSearch($vz, AnyUnitFilter) as $vmz) {
                $vo = GetZoneObject($vmz);
                if (SWUObjGone($vo)) continue;
                if (intval(ObjectCurrentHP($vo)) - intval($vo->Damage ?? 0) >= 4) { $hasBig = true; break 2; }
            }
        }
        if ($hasBig) TheForceIsWithYou($vp);
    }
    $playerID = $savedSneakPID;

    // LOF_055 Dume — "When the regroup phase starts: give an Experience token to each OTHER friendly
    // non-Vehicle unit." (Loop per Dume so multiple copies each grant.)
    for ($dp = 1; $dp <= SeatCountForGame(); $dp++) {
        $playerID = $dp;
        $dumeUIDs = [];
        foreach (['myGroundArena', 'mySpaceArena'] as $dz) {
            foreach (ZoneSearch($dz, AnyUnitFilter) as $dmz) {
                $do = GetZoneObject($dmz);
                if ($do !== null && empty($do->removed) && ($do->CardID ?? '') === 'LOF_055') $dumeUIDs[] = intval($do->UniqueID ?? 0);
            }
        }
        foreach ($dumeUIDs as $dumeUID) {
            // "each OTHER friendly non-Vehicle unit" — object-aware exclusion via TraitContains.
            foreach (_SWUCollectTokenTargets($dp, [
                'friendlyOnly' => true, 'notTraits' => ['Vehicle'], 'excludeUID' => $dumeUID,
            ]) as $dmz) {
                DoGiveExperienceToken($dp, $dmz);
            }
        }
    }
    $playerID = $savedSneakPID;

    // JTL_235 Commandeer — return commandeered units to their owners' hands at the start of regroup.
    $j235Found = true;
    while ($j235Found) {
        $j235Found = false;
        for ($jp = 1; $jp <= SeatCountForGame(); $jp++) {
            $playerID = $jp;
            foreach (['myGroundArena', 'mySpaceArena'] as $jz) {
                foreach (ZoneSearch($jz, AnyUnitFilter) as $jmz) {
                    $jo = GetZoneObject($jmz);
                    if (SWUObjGone($jo)) continue;
                    $juid = intval($jo->UniqueID ?? 0);
                    if (GlobalEffectCount(1, 'SWU_JTL235_RETURN_' . $juid) > 0 || GlobalEffectCount(2, 'SWU_JTL235_RETURN_' . $juid) > 0) {
                        SWUClearGlobalEffectsByPrefix(1, 'SWU_JTL235_RETURN_' . $juid);
                        SWUClearGlobalEffectsByPrefix(2, 'SWU_JTL235_RETURN_' . $juid);
                        SWUBounceUnit($jp, $jmz);   // return to owner's hand
                        $j235Found = true;
                        break 3;
                    }
                }
            }
        }
    }
    $playerID = $savedSneakPID;

    // HMW_200 Rish Loo — "At the start of the next regroup phase, its owner takes control of it."
    // CONTROL returns to the owner (contrast JTL_235 directly above, which bounces to hand). Same PERM
    // per-UID global shape; consumed here so a re-steal in a later round gets a fresh marker. A unit
    // already gone (defeated while stolen) simply never matches — the marker dies unconsumed.
    $h200Found = true;
    while ($h200Found) {
        $h200Found = false;
        for ($hp = 1; $hp <= SeatCountForGame(); $hp++) {
            $playerID = $hp;
            foreach (['myGroundArena', 'mySpaceArena'] as $hz) {
                foreach (ZoneSearch($hz, AnyUnitFilter) as $hmz) {
                    $ho = GetZoneObject($hmz);
                    if (SWUObjGone($ho)) continue;
                    $huid = intval($ho->UniqueID ?? 0);
                    $marked = false;
                    for ($hs = 1; $hs <= SeatCountForGame(); $hs++) {
                        if (GlobalEffectCount($hs, 'SWU_HMW200_RETURN_' . $huid) > 0) { $marked = true; break; }
                    }
                    if (!$marked) continue;
                    for ($hs = 1; $hs <= SeatCountForGame(); $hs++) {
                        SWUClearGlobalEffectsByPrefix($hs, 'SWU_HMW200_RETURN_' . $huid);
                    }
                    $howner = intval($ho->Owner ?? $hp);
                    if ($howner !== intval($ho->Controller ?? $hp)) {
                        $playerID = $howner;
                        $hbackMz = SWUFindMzByUID($huid);
                        if ($hbackMz !== null) SWUTakeControlOfUnit($howner, $hbackMz);
                    }
                    $h200Found = true;
                    break 3;
                }
            }
        }
    }
    $playerID = $savedSneakPID;

    // Expire "for this phase" effects. Registry-known tokens (keyword grants, value keywords,
    // stats, lose-abilities / suppress markers) are dropped by SWUExpireTurnEffects via their
    // declared duration. The legacy predicate below still handles the attack/paid tokens that
    // remain in their pre-migration string form; the two cover disjoint token sets, so running
    // both is safe.
    SWUExpireTurnEffects(SWU_DUR_PHASE);

    // JTL_216 Contracted Hunter — "When the regroup phase starts: defeat this unit." Evaluated HERE, after
    // phase-duration effects have expired: a "this phase" ability-nullify (Force Lightning SOR_138) is now
    // gone → the Hunter still self-defeats; a round-long nullify (Kazuda JTL_018 / There Is No Escape) is
    // still active → LostAbilities is true → the self-defeat (its own ability) is suppressed and it survives.
    // (drain loop — a defeat shifts arena indices, so re-scan after each.)
    {
        $savedChPID = $playerID;
        $chFound = true;
        while ($chFound) {
            $chFound = false;
            for ($cp = 1; $cp <= SeatCountForGame(); $cp++) {
                $playerID = $cp;
                foreach (['myGroundArena', 'mySpaceArena'] as $cz) {
                    foreach (ZoneSearch($cz, AnyUnitFilter) as $cmz) {
                        $co = GetZoneObject($cmz);
                        if (SWUObjGone($co)) continue;
                        if (($co->CardID ?? '') === 'JTL_216' && !LostAbilities($co)) { SWUDefeatUnit($cp, $cmz); $chFound = true; break 3; }
                    }
                }
            }
        }
        $playerID = $savedChPID;
    }

    $isPhaseStatEffect = fn($e) => strpos((string)$e, 'SWU_ATK_POWER_') === false // unconsumed attack bonus (fizzled attack)
                               && strpos((string)$e, 'SWU_DEF_DEBUFF_') === false // unconsumed Jyn defender debuff (fizzled attack)
                               && strpos((string)$e, 'SWU_PAID_')      === false; // Task 3.1: resources-paid stamp (per-play; WhenPlayed fires same turn)
    for ($p = 1; $p <= SeatCountForGame(); $p++) {
        $g = &GetGroundArena($p);
        for ($i = 0; $i < count($g); $i++) {
            if (!empty($g[$i]->removed)) continue;
            $g[$i]->TurnEffects = array_values(array_filter($g[$i]->TurnEffects ?? [], $isPhaseStatEffect));
        }
        unset($g);
        $s = &GetSpaceArena($p);
        for ($i = 0; $i < count($s); $i++) {
            if (!empty($s[$i]->removed)) continue;
            $s[$i]->TurnEffects = array_values(array_filter($s[$i]->TurnEffects ?? [], $isPhaseStatEffect));
        }
        unset($s);
    }
    // A "for this phase" +HP buff that kept a damaged unit alive has now expired — defeat any unit
    // whose damage meets/exceeds its (un-buffed) current HP. (Same state-based sweep as shrinks.)
    SWUCheckShrinkDefeats();
    for ($p = 1; $p <= SeatCountForGame(); $p++) {
        // LAW_245 Salvaged Materials — "At the start of the next regroup phase, defeat it." Defeat each
        // upgrade flagged SWU_LAW245_DEFEAT|{hostUID}|{cardID}, then clear the flag (one-shot).
        $geLaw245 = GetGlobalEffects($p);
        foreach ($geLaw245 as $ge) {
            $flag = (string)($ge->CardID ?? '');
            if (!str_starts_with($flag, 'SWU_LAW245_DEFEAT|')) continue;
            $fp = explode('|', $flag);   // [SWU_LAW245_DEFEAT, hostUID, cardID]
            $hostMz = SWUFindMzByUID(intval($fp[1] ?? 0));
            if ($hostMz !== null) {
                $hostObj = GetZoneObject($hostMz);
                $ups = $hostObj ? GetUpgradesOnUnit($hostObj) : [];
                for ($ui = 0; $ui < count($ups); $ui++) {
                    if (($ups[$ui]->CardID ?? '') === ($fp[2] ?? '')) { SWUDefeatUpgrade($p, $hostMz, $ui); break; }
                }
            }
        }
        SWUClearGlobalEffectsByPrefix($p, 'SWU_LAW245_DEFEAT');
        RemoveGlobalEffect($p, 'SWU_ENEMY_DEFEATED');
        SWUClearGlobalEffectsByPrefix($p, 'SWU_ENEMY_LEFT_PLAY');  // clear ALL (multiple leaves stack)
        SWUClearGlobalEffectsByPrefix($p, 'SWU_FRIENDLY_DEFEATED');  // clear ALL (multiple defeats stack)
        SWUClearGlobalEffectsByPrefix($p, 'SWU_FRIENDLY_HEROISM_DEFEATED'); // TWI_017 Palpatine (Heroism face)
        SWUClearGlobalEffectsByPrefix($p, 'SWU_FRIENDLY_ATTACKED');  // TWI_007 Captain Rex "a friendly unit attacked this phase"
        SWUClearGlobalEffectsByPrefix($p, 'SWU_REBEL_DEFEATED');     // LAW_005 Jyn "a friendly Rebel defeated this phase"
        SWUClearGlobalEffectsByPrefix($p, 'SWU_IMPERIAL_DEFEATED');  // ASH_008 Moff Gideon "a friendly Imperial defeated this phase"
        SWUClearGlobalEffectsByPrefix($p, 'SWU_FRIENDLY_UPGRADE_DEFEATED'); // ASH_039 "a friendly upgrade defeated this phase"
        SWUClearGlobalEffectsByPrefix($p, 'SWU_ASH212_USED');               // ASH_212 Peli "first non-unit each phase ignores aspect penalty"
        SWUClearGlobalEffectsByPrefix($p, 'SWU_ASH006_SHIELDED_NEXT');      // ASH_006 Sabine "next unit you play gains Shielded this phase"
        SWUClearGlobalEffectsByPrefix($p, 'SWU_CREATED_TOKEN');      // LAW_016 The Client "if you created a token this phase"
        SWUClearGlobalEffectsByPrefix($p, 'SWU_ASH047_USED');        // ASH_047 Gar Saxon "once each round" create-Mandalorian
        SWUClearGlobalEffectsByPrefix($p, 'SWU_ASH128_USED');        // ASH_128 Bothan-5 "once each round" capture-from-discard
        SWUClearGlobalEffectsByPrefix($p, 'SWU_SHD137_USED');        // SHD_137 Punishing One "ready this unit once each round"
        SWUClearGlobalEffectsByPrefix($p, 'SWU_HMW062_USED');        // HMW_062 Nuvo Vindi "give a Weakness once each round"
        SWUClearGlobalEffectsByPrefix($p, 'SWU_SHD163_USED');        // SHD_163 Migs Mayfeld "deal 2 on any hand-discard once each round"
        SWUClearGlobalEffectsByPrefix($p, 'SWU_SHD217_USED');        // SHD_217 Tobias Beckett "exhaust a ≤cost unit once each round"
        SWUClearGlobalEffectsByPrefix($p, 'SWU_SHD239_USED');        // SHD_239 Toro Calican "deal 1 + ready once each round"
        SWUClearGlobalEffectsByPrefix($p, 'SWU_SHD010_USED');        // SHD_010 Bossk (deployed) "collect a bounty again once each round"
        SWUClearGlobalEffectsByPrefix($p, 'SWU_SHD017_USED');        // SHD_017 Lando (deployed) "smuggle -2 + defeat a resource once each round"
        SWUClearGlobalEffectsByPrefix($p, 'SWU_ASH230_USED');        // ASH_230 Improvised Identity "once each round"
        SWUClearGlobalEffectsByPrefix($p, 'SWU_BASE_ATTACKED');      // ASH_119 Greef Karga "if your base was attacked this phase"
        SWUClearGlobalEffectsByPrefix($p, 'SWU_ATTACKER_DEFEATED');  // SEC_158 "friendly defeated while attacking this phase"
        SWUClearGlobalEffectsByPrefix($p, 'SWU_FRIENDLY_LEFT_PLAY');  // LOF_216 phase flag
        SWUClearGlobalEffectsByPrefix($p, 'SWU_FRIENDLY_LEADER_LEFT_PLAY'); // ASH_211 phase flag
        SWUClearGlobalEffectsByPrefix($p, 'SWU_LOF203');              // LOF_203 "next initiative this phase" flag
        SWUClearGlobalEffectsByPrefix($p, 'SWU_EVENT_LOCK');          // SEC_126 "can't play events this phase"
        SWUClearGlobalEffectsByPrefix($p, 'SWU_FORCE_USED_THIS_PHASE'); // LOF_007 "times you used the Force this phase"
        SWUClearGlobalEffectsByPrefix($p, 'SWU_PLAYED_NONUNIT_FORCE');  // LOF_012 "played a non-unit Force card this phase"
        SWUClearGlobalEffectsByPrefix($p, 'SWU_ATTACKED_JEDI');         // LOF_011 "attacked with a Jedi this phase"
        SWUClearGlobalEffectsByPrefix($p, 'SWU_LOF108_CREATURE_USED');  // LOF_108 "first Creature you play each phase"
        SWUClearGlobalEffectsByPrefix($p, 'SWU_LOF197_REPEAT');         // LOF_197 "repeat the next When-Played ability"
        SWUClearGlobalEffectsByPrefix($p, 'SWU_DEFEATED_CARD_');      // SOR_091 "defeated this phase" multiset
        SWUClearGlobalEffectsByPrefix($p, 'SWU_DMGBASE_');            // SOR_175 "base damaged this phase" set
        SWUClearGlobalEffectsByPrefix($p, 'SWU_BASEDMG_AMT_');        // SOR_013 Cassian "≥3 base damage this phase" amount
        // SOR_115 Kallus / SOR_013 Cassian once-per-round now reset via SWUResetAllNumUses (NumUses).
        SWUClearGlobalEffectsByPrefix($p, 'SWU_EVENT_PLAYED_ROUND');  // SOR_089 Relentless "first event each round"
        SWUClearGlobalEffectsByPrefix($p, 'SWU_CARDS_PLAYED');        // clear ALL (multiple plays stack)
        SWUClearGlobalEffectsByPrefix($p, 'SWU_DISCARDED_HAND');      // LAW_179 "cards discarded from hand this phase"
        SWUClearGlobalEffectsByPrefix($p, 'SWU_DREW_PHASE');          // LAW_051 "cards drawn this phase"
        SWUClearGlobalEffectsByPrefix($p, 'SWU_DISCARDED_PHASE');     // LAW_076 "discarded from hand/deck this phase"
        SWUClearGlobalEffectsByPrefix($p, 'SWU_LAW158_DISCOUNT_NEXT'); // LAW_158 "next Underworld unit -1"
        SWUClearGlobalEffectsByPrefix($p, 'SWU_ASH237_DISCOUNT_NEXT'); // ASH_237 Mouse Droid "next Imperial unit -1"
        SWUClearGlobalEffectsByPrefix($p, 'SWU_LAW058_DISCOUNT_NEXT'); // LAW_058 "next unit -1"
        SWUClearGlobalEffectsByPrefix($p, 'SWU_ASH027_DISCOUNT_NEXT'); // ASH_027 Enoch "next unit -N"
        SWUClearGlobalEffectsByPrefix($p, 'SWU_SHD006_DISCOUNT_NEXT'); // SHD_006 Jabba's bounty "next unit -N"
        SWUClearGlobalEffectsByPrefix($p, 'SWU_LAW053_USED');          // LAW_053 Dengar "once each round"
        SWUClearGlobalEffectsByPrefix($p, 'SWU_LAW094_USED');          // LAW_094 Hondo "once each round"
        SWUClearGlobalEffectsByPrefix($p, 'SWU_LAW176_USED');          // LAW_176 Sebulba's Podracer "once each round"
        SWUClearGlobalEffectsByPrefix($p, 'SWU_NAMEBLOCK_PHASE');     // LAW_243 "named card can't be played this phase"
        RemoveGlobalEffect($p, 'SWU_PLAYED_VILLAINY');
        SWUClearGlobalEffectsByPrefix($p, 'SWU_PLAYED_EVENT'); // TWI_014 Asajj "played an event this phase"
        SWUClearGlobalEffectsByPrefix($p, 'SWU_PLAYED_FO');          // JTL_010 Captain Phasma
        SWUClearGlobalEffectsByPrefix($p, 'SWU_PLAYED_FORCE_CARD');  // LOF_243 Caretaker Matron
        SWUClearGlobalEffectsByPrefix($p, 'SWU_PLAYED_BOUNTYHUNTER'); // JTL_186 Mist Hunter
        SWUClearGlobalEffectsByPrefix($p, 'SWU_PLAYED_PILOT');        // JTL_186 Mist Hunter
        SWUClearGlobalEffectsByPrefix($p, 'SWU_KRENNIC_USED');       // JTL_032 Director Krennic per-round discount
        SWUClearGlobalEffectsByPrefix($p, 'SWU_DEALT_INDIRECT');     // JTL_138 "dealt indirect this phase"
        SWUClearGlobalEffectsByPrefix($p, 'SWU_GIDEON_TAX');         // JTL_188 Moff Gideon opponent-tax
        // JTL_157 Relentless Firespray once-per-round now via per-unit NumUses (SWUResetAllNumUses).
        SWUClearGlobalEffectsByPrefix($p, 'SWU_PILOT_DISCOUNT');     // JTL_008 Wedge (safety; consumed at charge)
        SWUClearGlobalEffectsByPrefix($p, 'SWU_PLAYED_UNIT_');
        SWUClearGlobalEffectsByPrefix($p, 'SWU_ENTERED_PHASE_');   // TS26_02/004 "entered play this phase"
        SWUClearGlobalEffectsByPrefix($p, 'SWU_PLAYED_FROM_HAND_'); // SHD_161/SHD_204 hand-source flag
        SWUClearGlobalEffectsByPrefix($p, 'SWU_UNIT_ATTACKED_');
        SWUClearGlobalEffectsByPrefix($p, 'SWU_DEALT_BASEDMG_');
        SWUClearGlobalEffectsByPrefix($p, 'SWU_UNITDMGBASE_');       // SEC_012 "damaged an enemy base this phase" (any source)
        SWUClearGlobalEffectsByPrefix($p, 'SWU_DMGDBASE_');          // SEC_012 owner-qualified twin (any base)
        SWUClearGlobalEffectsByPrefix($p, 'SWU_ATTACKED_');  // clears SWU_ATTACKED_{uid} + ..._MANDALORIAN_{uid} + ..._VEHICLE
        SWUClearGlobalEffectsByPrefix($p, 'SWU_JTL232_FREE');       // JTL_232 Jump to Lightspeed: free-replay charge is "this phase" only
        SWUClearGlobalEffectsByPrefix($p, 'SWU_NEUTRAL_DISCOUNT');  // SOR_056 Bendu: "this phase" charge
        SWUClearGlobalEffectsByPrefix($p, 'SWU_SNAP_DISCOUNT');     // JTL_098 Snap Wexley: "next Resistance card" charge
        SWUClearGlobalEffectsByPrefix($p, 'SWU_JTL260_USED');       // JTL_260 Death Star Plans: "first unit each round -2" use
        SWUClearGlobalEffectsByPrefix($p, 'SWU_SHD198_USED');       // SHD_198 Clone Trooper: "first Clone unit each round ignores aspect penalty"
        SWUClearGlobalEffectsByPrefix($p, 'SWU_LAW229_USED');       // LAW_229 "first Gambit each round -1" use
        SWUClearGlobalEffectsByPrefix($p, 'SWU_SEC110_DISCOUNT_NEXT'); // SEC_110 GNK "next unit -1" charge
        SWUClearGlobalEffectsByPrefix($p, 'SWU_TWI082_USED');         // TWI_082 MagnaGuard Wing Leader "once each round"
        SWUClearGlobalEffectsByPrefix($p, 'SWU_TWI121_DISCOUNT_NEXT'); // TWI_121 General's Blade "next unit -2" charge
        SWUClearGlobalEffectsByPrefix($p, 'SWU_TWI246_DISCOUNT');      // TWI_246 Tranquility "next 3 Republic cards -1"
        SWUClearGlobalEffectsByPrefix($p, 'SWU_SEC064_USED');       // SEC_064 "first upgrade each phase -1" use
        SWUClearGlobalEffectsByPrefix($p, 'SWU_ASH075_USED');       // ASH_075 Pit Droid "first upgrade each phase -1" use
        SWUClearGlobalEffectsByPrefix($p, 'SWU_SEC261_OFFICIAL_DISCOUNT'); // SEC_261 "next Official unit -1" charge
        SWUClearGlobalEffectsByPrefix($p, 'SWU_SEC001_PLOT_DISCOUNT');     // SEC_001 Palpatine "next Plot play -3" charge
        SWUClearGlobalEffectsByPrefix($p, 'SWU_SEC002_USED');              // SEC_002 Jabba deployed "once each round"
        SWUClearGlobalEffectsByPrefix($p, 'SWU_ASH032_USED');              // ASH_032 Rancor Keeper "once each round"
        SWUClearGlobalEffectsByPrefix($p, 'SWU_ASH160_USED_');             // ASH_160 Kachirho Militia "once each round"
        SWUClearGlobalEffectsByPrefix($p, 'SWU_ASH248_READY');             // ASH_248 Neel "next ≤1-power unit this phase enters ready"
        SWUClearGlobalEffectsByPrefix($p, 'SWU_LEADER_DEFEATED_PHASE');    // ASH_093 Captain Pellaeon "leader defeated this phase → Raid 3"
        SWUClearGlobalEffectsByPrefix($p, 'SWU_SEC067_USED_');      // SEC_067 "first damage each phase prevented" per-unit
        SWUClearGlobalEffectsByPrefix($p, 'SWU_SEC033');            // SEC_033 Sly Moore: enemy units -2/-0 vs bases this phase
        SWUClearGlobalEffectsByPrefix($p, 'SWU_NOHEAL_BASE');       // SOR_160 Wolffe: "bases can't be healed this phase"
        SWUClearGlobalEffectsByPrefix($p, 'SWU_BASE_HEALED_PHASE'); // TS26_38: "if a base was healed this phase"
        SWUClearGlobalEffectsByPrefix($p, 'SWU_TS26035_DISCOUNT_NEXT'); // TS26_35: "next event -2 this phase"
        SWUClearGlobalEffectsByPrefix($p, 'SWU_REX_DISCOUNT_NEXT');     // TS26_06 Rex: "next event -1/-2 this phase"
        SWUClearGlobalEffectsByPrefix($p, 'SWU_TS26063_USED_');         // TS26_63 Rex's DC-17s: "once each round"
        // TS26_12 Sundari Palace — defeat one friendly resource per card resourced this way (at regroup start).
        $sundari = GlobalEffectCount($p, 'SWU_SUNDARI_DEFEAT');
        if ($sundari > 0) {
            $playerID = $p;
            for ($si = 0; $si < $sundari; $si++) {
                $sres = ZoneSearch("myResources", null);
                if (empty($sres)) break;
                SWUDefeatResource($p, $sres[0]);
            }
            SWUClearGlobalEffectsByPrefix($p, 'SWU_SUNDARI_DEFEAT');
        }
        SWUClearGlobalEffectsByPrefix($p, 'SWU_SHIELD_GATE');       // JTL_074 Close the Shield Gate: unused base-damage prevention
        // JTL_013 Poe Dameron once-per-round hop now via leader NumUses (SWUResetAllNumUses).
        SWUClearGlobalEffectsByPrefix($p, 'SWU_THRAWN_REUSE_PENDING'); // safety: clear any dangling offer guard
        SWUClearGlobalEffectsByPrefix($p, 'SWU_BOBA_009_PENDING');     // JTL_009 safety: clear dangling offer guard
        SWUClearGlobalEffectsByPrefix($p, 'SWU_ENFYS_REUSE_PENDING');  // LAW_014 safety: clear dangling offer guard
        SWUClearGlobalEffectsByPrefix($p, 'SWU_JABBA015_PENDING');     // LAW_015 safety: clear if a Jabba play fizzled
        SWUClearGlobalEffectsByPrefix($p, 'SWU_JABBA015_AMBUSH');      // LAW_015 safety
        RemoveGlobalEffect($p, 'SWU_DOOKU_NEXT_SEPARATIST_EXPLOIT');  // TWI_005 Dooku: "this phase" charge
        RemoveGlobalEffect($p, 'SWU_LOF180_NEXT_AMBUSH');            // LOF_180 Deceptive Shade: "this phase" charge
        SWUClearGlobalEffectsByPrefix($p, 'SWU_LOF010_NEXT_HIDDEN');  // LOF_010 deployed "next unit gains Hidden"
        SWUClearGlobalEffectsByPrefix($p, 'SWU_LOF005_DISCOUNT_NEXT');// LOF_005 deployed "next unit costs 1 less"
    }
    SWUResetAllNumUses(); // refresh every card's once-per-round NumUses budget for the new round
    // End of the round: expire "this round" effects (JTL_018 Kazuda / JTL_244 There Is No Escape lose-
    // abilities). They survived the action-phase phase-expiry AND stayed active through every regroup-start
    // self-defeat / trigger above (e.g. JTL_216 Contracted Hunter's regroup self-defeat, which must still
    // see a round-blanked unit as ability-less) — the round is over now, so clear them for the next round.
    //
    // ⚠ ONLY on the round's FINAL regroup. A round is "action phase → regroup phase", but LAW_072 Max Rebo
    // makes it "action phase → regroup → regroup" (and one more per additional Max Rebo), all still ONE
    // round. This runs inside RegroupPhaseStart, so without the guard it fired at the start of regroup 1
    // and a "for this round" blank was already gone by regroup 2 — Contracted Hunter then self-defeated in
    // the additional regroup despite Kazuda having blanked it for the round.
    // Safe ordering: the regroup-start self-defeat/trigger block above runs BEFORE this line, so even on
    // the final regroup those triggers still see the blank; it is cleared only afterwards.
    // Same guard, same reason as the deferred round increment in ReadyPhase — keep the two in step.
    if (!_SWUNeedsExtraRegroup()) {
        SWUExpireTurnEffects(SWU_DUR_ROUND);
    }
    // Return all TEMPORARY_STEAL units to their owners. Drain loop because each
    // SWUTakeControlOfUnit call shifts arena indices.
    global $playerID;
    $savedPID = $playerID;
    $found = true;
    while ($found) {
        $found = false;
        for ($p = 1; $p <= SeatCountForGame(); $p++) {
            $playerID = $p;
            foreach (['myGroundArena', 'mySpaceArena'] as $zone) {
                foreach (ZoneSearch($zone, AnyUnitFilter) as $mzID) {
                    $obj = GetZoneObject($mzID);
                    if ($obj === null || ($obj->removed ?? false)) continue;
                    if (!in_array('TEMPORARY_STEAL', $obj->TurnEffects ?? [])) continue;
                    $owner = intval($obj->Owner ?? $p);
                    if ($owner === $p) continue;
                    SWUTakeControlOfUnit($owner, $mzID);
                    $found = true;
                    break 3;
                }
            }
        }
    }
    $playerID = $savedPID;
}

// SEC_073 The Eye of Aldhani — queue ONE pay-or-exhaust resolution for $target, threading the number of
// copies STILL to resolve after this one so each subsequent copy recomputes its resource cap live (chained
// via SEC_073#0). $count = total resolutions remaining (this one included). Recurses on the can't-pay branch
// so remaining copies still exhaust. No-op once no units remain to affect.
function _SWUQueueEyeOfAldhaniResolution(int $target, int $count): void {
    if ($count <= 0) return;
    global $playerID;
    $playerID = $target;
    $units = array_values(array_merge(ZoneSearch('myGroundArena', AnyUnitFilter), ZoneSearch('mySpaceArena', AnyUnitFilter)));
    if (empty($units)) return;
    $cap = min(count($units), SWUTotalPaymentCapacity($target)); // a Credit/Droid can pay this 1 (CR 3.13)
    if ($cap <= 0) {                                   // can't pay → all exhausted, then resolve the rest
        foreach ($units as $mz) OnExhaustCard($target, $mz);
        _SWUQueueEyeOfAldhaniResolution($target, $count - 1);
        return;
    }
    DecisionQueueController::AddDecision($target, "MZMULTICHOOSE", "0|{$cap}|" . implode('&', $units), 1,
        tooltip:"Pay_1_resource_each_to_keep_units_ready_(unselected_are_exhausted)");
    DecisionQueueController::AddDecision($target, "CUSTOM", "SEC_073#0|{$target}|" . ($count - 1), 1);
    // leave $playerID = $target so MZCountChoices validates the relative mzIDs correctly
}

function ActionPhaseStart() {
    // Twin Suns (CR §12.7): if the phase that just ended contained the first elimination, score now.
    _SWUScoreTwinSunsEndOfPhase();
    if (SWUGetGameWinner() !== 0) return;
    // Determine who holds the initiative going into this round.
    // If initiative was claimed last round (P1_CLAIMED/P2_CLAIMED), that player
    // keeps it; flip to _UNCLAIMED (available but not yet taken this round).
    $ic = GetInitiativeCounter();
    // Twin Suns (Phase 4): parse the holder seat from P{n}_(UN)CLAIMED generically (was P1/P2-hardcoded).
    $holder = intval(GetFirstPlayer());
    if (preg_match('/^P(\d+)_(?:CLAIMED|UNCLAIMED)$/', $ic, $m)) $holder = intval($m[1]);

    SetTurnPlayer($holder);
    SetInitiativeCounter("P{$holder}_UNCLAIMED");
    SetSWUVar('PASS', '0');
    // Twin Suns (Phase 4): return the blast + plan counters to the center each round; clear who has taken
    // a counter. Initiative persists via its own holder logic above. (Harmless no-op in premier.)
    SetBlastCounter("AVAILABLE");
    SetPlanCounter("AVAILABLE");
    SetSWUVar('SWU_COUNTER_TAKEN', '');
    SetSWUVar('SWU_REGROUP_NUM', '0'); // LAW_072: reset the per-round regroup-phase counter

    // SOR_061 Guardian of the Whills: reset each Guardian's per-round upgrade-discount charge.
    for ($p = 1; $p <= SeatCountForGame(); $p++) {
        SWUClearGlobalEffectsByPrefix($p, 'SWU_GUARDIAN_UPG_USED_');
        SWUClearGlobalEffectsByPrefix($p, 'SWU_ACTED_PHASE');   // SEC_145 "first action" gate resets each phase
        // ── "…this phase" ATTACK flags. RegroupPhaseStart clears these too, and for a long time that was
        // the ONLY clear — which is a hole, because an attack can happen DURING the regroup phase (a
        // Bounty replays a unit with Ambush; SHD_226 Unrefusable Offer + JTL_216 Contracted Hunter is the
        // two-card version). Such an attack is recorded AFTER the regroup clear has run, so its flag then
        // survived into the next action phase and every reader mistook it for an attack made THIS phase.
        // A "this phase" flag has to reset when ANY phase starts, not just the regroup one — same shape as
        // the SWU_DUR_ROUND expiry bug (a duration hook living in only one of the phases it spans).
        SWUClearGlobalEffectsByPrefix($p, 'SWU_UNIT_ATTACKED_');   // SEC_177 "didn't attack this phase"
        SWUClearGlobalEffectsByPrefix($p, 'SWU_FRIENDLY_ATTACKED'); // TWI_007 Captain Rex
        SWUClearGlobalEffectsByPrefix($p, 'SWU_ATTACKED_');        // {uid} + _MANDALORIAN_{uid} + _VEHICLE/_FIGHTER/_JEDI/_SEPARATIST/_TOKEN
    }

    // Clear per-round TurnEffects for Leaders and Bases.
    for ($p = 1; $p <= SeatCountForGame(); $p++) {
        $leader = &GetLeader($p);
        for ($i = 0; $i < count($leader); $i++) {
            if (!isset($leader[$i]->removed) || !$leader[$i]->removed) $leader[$i]->TurnEffects = [];
        }
        $base = &GetBase($p);
        for ($i = 0; $i < count($base); $i++) {
            if (!isset($base[$i]->removed) || !$base[$i]->removed) $base[$i]->TurnEffects = [];
        }
    }
    // HMW_147 Beast Lair — base-hosted "When the action phase starts" trigger (per attached copy,
    // per seat). Queued AFTER the per-round resets above so the granted ability sees the fresh phase.
    _SWUHmw147ActionPhaseTriggers();

    AddGameLogEntry('PHASE', '— Action Phase —');

    // SOR_016 Grand Admiral Thrawn — APS passive (leader unit side):
    // "When the action phase starts: Look at the top card of each player's deck."
    global $playerID;
    $savedPID = $playerID;
    for ($p = 1; $p <= SeatCountForGame(); $p++) {
        $playerID = $p;
        $leaderZone = GetLeader($p);
        $thrawnDeployed = false;
        foreach ($leaderZone as $lObj) {
            if (!empty($lObj->removed)) continue;
            if (($lObj->CardID ?? '') === 'SOR_016') {
                $thrawnDeployed = true;
                break;
            }
        }
        if (!$thrawnDeployed) continue;

        for ($deckOwner = 1; $deckOwner <= 2; $deckOwner++) {
            $playerID = $deckOwner;
            $deck = GetDeck($deckOwner);
            $active = array_values(array_filter($deck, fn($c) => empty($c->removed ?? false)));
            if (empty($active)) continue;
            AddGameLogEntry(
                'REVEAL',
                'Thrawn sees top of P' . $deckOwner . '\'s deck: ' . GameLogCardRef($active[0]->CardID),
                'P' . $p
            );
        }
    }
    $playerID = $savedPID; // restore: the peek loop leaves $playerID on the last deck owner,
    // which would otherwise mis-resolve the relative-mzID MZCHOOSE queued in the SOR_017 block
    // below (the documented MZCountChoices/$playerID gotcha) when Thrawn is in play.

    // SOR_017 Han Solo — pending delayed trigger:
    // "At the start of the next action phase, defeat a resource you control."
    // One armed flag per ramp; resolve each as a mandatory choice among the
    // player's resources (auto-PASSes harmlessly if they control none).
    for ($p = 1; $p <= SeatCountForGame(); $p++) {
        $pending = GlobalEffectCount($p, 'SWU_HAN_DEFEAT_RESOURCE');
        for ($k = 0; $k < $pending; $k++) {
            RemoveGlobalEffect($p, 'SWU_HAN_DEFEAT_RESOURCE');
            DecisionQueueController::AddDecision($p, 'MZCHOOSE', 'myResources', 1,
                'Choose_a_resource_to_defeat_(Han_Solo)');
            DecisionQueueController::AddDecision($p, 'CUSTOM', 'HAN_DEFEAT_RESOURCE', 1);
        }
    }

    // SEC_073 The Eye of Aldhani — "At the start of the next action phase, for each enemy unit, its
    // controller must pay 1 resource or exhaust that unit." Each COPY played is a SEPARATE delayed ability
    // (CR: they don't merge), so N copies resolve N times — chained so each copy's resource cap reflects
    // what earlier copies already spent (a unit kept ready by paying for copy 1 must be paid for AGAIN in
    // copy 2, or it's exhausted). _SWUQueueEyeOfAldhaniResolution queues the first and threads the rest.
    for ($armer = 1; $armer <= 2; $armer++) {
        $stacks = GlobalEffectCount($armer, 'SWU_EYE_ALDHANI');
        if ($stacks <= 0) continue;
        SWUClearGlobalEffectsByPrefix($armer, 'SWU_EYE_ALDHANI');   // consume all stacks; the count drives N resolutions
        _SWUQueueEyeOfAldhaniResolution(OtherPlayer($armer), $stacks);
        // leave $playerID = the target so MZCountChoices validates the relative mzIDs correctly
    }

    // JTL_028 Nabat Village — "At the start of the FIRST action phase, put 3 cards from your hand on the
    // bottom of your deck." (The +3 starting hand + no-mulligan halves live in the pregame setup —
    // SWUStartingHandModifier / SWUBaseSuppressesMulligan.) Fires exactly once per game, guarded by the
    // per-player SWU_NABAT_BOTTOM_DONE flag. Interactive: the base's controller chooses which 3 (an
    // MZMULTICHOOSE over their hand → JTL_028#0 moves them to the bottom, mirroring TWI_257).
    for ($p = 1; $p <= SeatCountForGame(); $p++) {
        $nabatBase = GetBase($p);
        $hasNabat  = false;
        foreach ($nabatBase as $bObj) {
            if (empty($bObj->removed) && ($bObj->CardID ?? '') === 'JTL_028') { $hasNabat = true; break; }
        }
        if (!$hasNabat) continue;
        if (GlobalEffectCount($p, 'SWU_NABAT_BOTTOM_DONE') > 0) continue;   // first action phase only
        AddGlobalEffects($p, 'SWU_NABAT_BOTTOM_DONE');
        $playerID = $p;
        $hand = array_values(ZoneSearch("myHand"));
        $n = min(3, count($hand));
        if ($n <= 0) continue;
        DecisionQueueController::AddDecision($p, "MZMULTICHOOSE", "{$n}|{$n}|" . implode('&', $hand), 1,
            tooltip:"Put_3_cards_from_your_hand_on_the_bottom_of_your_deck_(Nabat_Village)");
        DecisionQueueController::AddDecision($p, "CUSTOM", "JTL_028#0", 1);
        // leave $playerID = $p so MZCountChoices validates the myHand-* relative mzIDs
    }

    $playerID = $savedPID;
}

// ── SWU Gameplay Core ──────────────────────────────────────────────────────

// Which arena a unit card enters. arenaData is empty in generated dicts (API
// parsing gap), so fall back to Ground. Extend this list when space units are needed.
function CardTargetArena($cardID) {
    $arena = CardArena($cardID);
    if ($arena === 'Space') return 'SpaceArena';
    return 'GroundArena'; // default Ground
}

// Which arena a LEADER's deployed unit side enters. Almost every leader deploys into the arena
// its leader row implies, but a card may print a deployed side in a DIFFERENT arena — HMW_004
// Grand Moff Tarkin deploys as The Death Star, a Space unit. The override lives in the
// leaderUnitArena dictionary dimension and is absent (null) for every ordinary leader, so they
// keep resolving through CardTargetArena exactly as before.
function LeaderDeployArena($cardID) {
    $override = CardLeaderUnitArena($cardID);
    if ($override === 'Space') return 'SpaceArena';
    if ($override === 'Ground') return 'GroundArena';
    return CardTargetArena($cardID);
}

// Increment and return the next UniqueID counter value.
function NextUniqueID() {
    global $gUniqueIDCounter;
    $gUniqueIDCounter = intval($gUniqueIDCounter) + 1;
    return $gUniqueIDCounter;
}

// Move a unit from its current controller's arena to $newController's arena.
// Preserves Owner, Subcards, Damage, UniqueID, and Status. Strips TEMPORARY_STEAL
// from TurnEffects so returned units don't loop. Returns the new mzID or '' on failure.
// Caller must have $playerID set so that $mzID resolves correctly before the call.
function SWUTakeControlOfUnit(int $newController, string $mzID): string {
    global $playerID;
    $savedPID = $playerID;

    $unit = GetZoneObject($mzID);
    if ($unit === null || ($unit->removed ?? false)) {
        $playerID = $savedPID;
        return '';
    }
    // "Opponents can't take control of this unit" (LAW_149 Rey). Block when someone OTHER than the
    // owner is taking control (an opponent); returning control to the owner is always allowed.
    if (intval($newController) !== intval($unit->Owner ?? $newController) && SWUAvoidsTakeControl($unit)) {
        $playerID = $savedPID;
        return '';
    }
    // CR 3.4.6 — "If an ability would cause a Leader Unit to move to an out-of-play zone or CHANGE CONTROL
    // for any reason, it is defeated instead." A leader unit can only ever be controlled by its leader's
    // controller, so ANY control change defeats it rather than transferring it. Covers both forms:
    //   • a deployed leader in the arena (returns to its leader zone exhausted, CR 3.4.5); and
    //   • a normal unit MADE a leader unit by a leader Pilot upgrade (CR 3.4.7 — the host goes to its
    //     owner's discard, the Leader Upgrade flips back to the leader zone).
    // Reachable both by a take-control effect aimed at a leader unit (Sly Moore TWI_211, Change of Heart,
    // No Glory Only Results) AND by the RETURN half of a temporary steal whose target has become a leader
    // unit in the meantime (LOF_189 Liberated by Darkness + a pilot leader deployed onto the stolen unit) —
    // that second path previously handed the opponent a unit still carrying the other player's leader.
    // ⚠ Only a genuine change of controller qualifies; re-asserting the SAME controller must stay a no-op.
    // The defeat is attributed to the CURRENT controller so it is not treated as an enemy-ability defeat
    // (this is a rules replacement, not a card ability, so "can't be defeated by enemy abilities" is moot).
    // ⚠ $mzID is RELATIVE to the CALLER's frame ($savedPID), but the defeat must be attributed to the
    // current controller — and SWUDefeatUnit re-resolves the mzID under the player it is given. Passing
    // the caller's mzID with the controller as actor resolves to a DIFFERENT unit (it defeated the
    // card that was doing the stealing). Re-find the unit by UID under the controller's own frame.
    $curController = intval($unit->Controller ?? ($unit->Owner ?? $newController));
    if (intval($newController) !== $curController && IsLeaderUnit($unit)) {
        $leaderUid = intval($unit->UniqueID ?? 0);
        $playerID  = $curController;
        $ownerMz   = $leaderUid > 0 ? SWUFindMzByUID($leaderUid) : null;
        if ($ownerMz !== null) SWUDefeatUnit($curController, $ownerMz);
        $playerID = $savedPID;
        return '';
    }

    $cardID      = $unit->CardID ?? '';
    $owner       = intval($unit->Owner ?? $newController);
    $damage      = intval($unit->Damage ?? 0);
    $subcards    = $unit->Subcards ?? [];
    $turnEffects = array_values(array_filter($unit->TurnEffects ?? [],
                    fn($e) => $e !== 'TEMPORARY_STEAL'));
    $uid         = intval($unit->UniqueID ?? 0);
    $status      = intval($unit->Status ?? 1);
    $location    = $unit->Location ?? 'GroundArena';

    $unit->removed = true;
    DecisionQueueController::CleanupRemovedCards();

    $playerID = $newController;
    $newCard  = null;
    if (strpos($location, 'Space') !== false) {
        $newCard = AddSpaceArena($newController, CardID:$cardID, Status:$status,
            Owner:$owner, Damage:$damage, Controller:$newController, UniqueID:$uid);
    } else {
        $newCard = AddGroundArena($newController, CardID:$cardID, Status:$status,
            Owner:$owner, Damage:$damage, Controller:$newController, UniqueID:$uid);
    }

    $newMzID = '';
    if ($newCard !== null) {
        $newCard->Subcards    = $subcards;
        // Taking control of a unit transfers control of its (non-pilot) upgrades too, so "friendly upgrade
        // defeated" (ASH_161 Zeb) fires for the NEW controller when the stolen unit is later defeated (e.g.
        // JTL_043 take-control-then-defeat). EXCLUDE pilot subcards: a Pilot (often a leader) keeps its own
        // controller — its defeat-replacement / return follows the player who played it, not the host's new
        // controller (see the stolen-host pilot case). Captives keep their own owner/controller too.
        if (is_array($newCard->Subcards)) {
            foreach ($newCard->Subcards as $k => $sub) {
                $isCap   = is_array($sub) ? !empty($sub['IsCaptive']) : !empty($sub->IsCaptive);
                $isPilot = is_array($sub) ? !empty($sub['IsPilot'])   : !empty($sub->IsPilot);
                if ($isCap || $isPilot) continue;
                $subCID = is_array($sub) ? ($sub['CardID'] ?? '') : ($sub->CardID ?? '');
                if (is_array($sub)) $newCard->Subcards[$k]['Controller'] = $newController;
                else                $sub->Controller = $newController;
                // CR 6 token ownership: a TOKEN has no printed owner — whoever controls it owns it. So a
                // token upgrade riding a stolen unit changes OWNER too, not just controller. Real (printed)
                // upgrades keep their owner, which is why only tokens are re-owned here. Observable via
                // SEC_046 Galen Erso naming "Shield": a shield stolen from Galen's own side becomes a card
                // Galen's opponent owns and is blanked from that moment on.
                if (strpos(CardType($subCID) ?? '', 'Token') !== false) {
                    if (is_array($sub)) $newCard->Subcards[$k]['Owner'] = $newController;
                    else                $sub->Owner = $newController;
                }
            }
        }
        $newCard->TurnEffects = $turnEffects;
        $newMzID              = $newCard->GetMzID();
    }

    $playerID = $savedPID;
    return $newMzID;
}

// Exhaust $count ready resources for player $player.
// Returns true if successful, false if insufficient ready resources.
// ── Credit tokens (CR §3.13) ─────────────────────────────────────────────────
// A Credit token (LAW_T01, card type "Credit Token") is created in a player's resource zone but is
// NOT a resource: it never counts toward resource totals (so it gives no early leader deploy and no
// extra play affordability) and is never exhausted to pay. Its only function is "While paying
// resources, you may defeat this token. If you do, pay 1 less" — handled by the alt-payment offer
// (SWUOfferAltPayment / CREDIT_PAY). All resource-counting / paying loops skip Credit tokens.
function SWUIsCreditToken(string $cardID): bool {
    return CardType($cardID) === 'Credit Token';
}

// Create $count Credit tokens (LAW_T01) in $player's resource zone.
function SWUCreateCreditToken(int $player, int $count = 1, bool $offerDouble = true): void {
    global $playerID;
    $savedPID = $playerID;
    $playerID = intval($player);
    for ($i = 0; $i < intval($count); $i++) {
        AddResources($player, 'LAW_T01', 1, $player, $player); // Status irrelevant (not a resource)
    }
    if (intval($count) > 0) {
        AddGlobalEffects(intval($player), 'SWU_CREATED_TOKEN'); // LAW_016 "if you created a token this phase"
        AddGameLogEntry('TOKEN', 'P' . intval($player) . ' created ' . intval($count)
            . ' Credit token' . (intval($count) === 1 ? '' : 's'));
        // ASH_094 Moff Jerjerrod — "If you would create a number of tokens, you may defeat this unit to create
        // twice that number instead" (any token type except Force). $offerDouble=false when this call IS the
        // doubled creation (avoids re-offering / infinite recursion).
        if ($offerDouble) _SWUMaybeOfferJerjerrodDouble(intval($player), 'LAW_T01', intval($count), false, '', 'credit');
    }
    $playerID = $savedPID;
}

// Number of Credit tokens $player controls (in their resource zone).
function SWUCountFriendlyCreditTokens(int $player): int {
    $n = 0;
    foreach (GetResources($player) as $r) {
        if (!empty($r->removed)) continue;
        if (SWUIsCreditToken($r->CardID ?? '')) $n++;
    }
    return $n;
}

// True if $player's Credit tokens have lost all abilities (so they can't be defeated to pay 1 less).
// LAW_117 Conveyex Security Captain: "Enemy Credit tokens lose all abilities." — i.e. a Credit token
// is disabled when its controller's OPPONENT controls an active (ability-bearing) LAW_117.
function SWUCreditAbilitiesDisabled(int $player): bool {
    $opp = GetOpponent($player);
    foreach (array_merge(GetGroundArena($opp) ?? [], GetSpaceArena($opp) ?? []) as $u) {
        if (SWUObjGone($u)) continue;
        // "active (ability-bearing)" must consult LostAbilities(), not just HasNoAbilities(): the latter
        // is the GrandArchive-era helper that only sees a literal "NO_ABILITIES" turn effect, while every
        // SWU blanking effect (JTL_018 Kazuda, SOR_138, JTL_244, SHD_072, SEC_054, LAW_132, SEC_046 Galen,
        // TWI_255 Brain Invaders) writes its own marker that only LostAbilities() reads. Checking the
        // wrong one left a BLANKED Conveyex still disabling enemy Credit tokens.
        if (($u->CardID ?? '') === 'LAW_117' && !HasNoAbilities($u) && !LostAbilities($u)) return true;
    }
    // SEC_046 Galen Erso naming "Credit": the player's Credit tokens are non-leader cards an opponent
    // (Galen's controller) owns-from-Galen's-side, so they lose all abilities and can't be defeated to
    // pay 1 less. Checked on the player's actual token CardID (Galen matches by title, robust to reprints).
    foreach (GetResources($player) ?? [] as $r) {
        if (SWUObjGone($r)) continue;
        if (SWUIsCreditToken($r->CardID ?? '') && _SWUGalenSuppressesCard($player, $r->CardID ?? '')) return true;
    }
    return false;
}

// mzIDs ("myResources-N") of $player's Credit tokens that may still be defeated to pay 1 less
// (empty if disabled by an enemy LAW_117). Raw zone indices, matching ZoneSearch/GetZoneObject.
function SWUUsableCreditTokenMzIDs(int $player): array {
    if (SWUCreditAbilitiesDisabled($player)) return [];
    $out = [];
    $resources = GetResources($player);
    for ($i = 0; $i < count($resources); $i++) {
        if (!empty($resources[$i]->removed)) continue;
        if (SWUIsCreditToken($resources[$i]->CardID ?? '')) $out[] = "myResources-{$i}";
    }
    return $out;
}

// How much $player can actually pay right now: ready resources PLUS every alternate payment the real
// payment chain (SWUOfferAltPayment → Credit tokens → SEC_122 Droids) would accept. Use this — never a
// bare ready-resource count — to gate whether a "you may pay N" effect is OFFERED, or the offer is
// hidden from a player who can in fact pay (e.g. 1 ready resource + 1 Credit token for a cost of 2).
function SWUTotalPaymentCapacity(int $player): int {
    $ready = 0;
    foreach (GetResources($player) as $r) {
        if (SWUIsCreditToken($r->CardID ?? '')) continue; // Credit tokens aren't resources (CR 3.13)
        if (empty($r->removed) && intval($r->Status) === 1) $ready++;
    }
    $ready += count(SWUUsableCreditTokenMzIDs($player));
    if (SWUPlayerControlsSEC122($player)) $ready += count(SWUReadyFriendlyDroids($player));
    return $ready;
}

// mzIDs ("theirResources-N", from $player's frame) of the OPPONENT's Credit tokens — for LAW_106
// "defeat an enemy Credit token". Raw zone indices, matching GetZoneObject resolution.
function SWUEnemyCreditTokenMzIDs(int $player): array {
    $opp = GetOpponent($player);
    $out = [];
    $res = GetResources($opp);
    for ($i = 0; $i < count($res); $i++) {
        if (!empty($res[$i]->removed)) continue;
        if (SWUIsCreditToken($res[$i]->CardID ?? '')) $out[] = "theirResources-{$i}";
    }
    return $out;
}

// Keep Credit tokens at the END of $player's resource zone. They're appended on creation, but a card
// resourced afterward would otherwise land behind them. Resource order is free (CR 8.36.4), so a plain
// partition is safe; mzIndex is reindexed to match.
function SWUKeepCreditTokensLast(int $player): void {
    $resources = &GetResources($player);
    $hasCredit = false;
    foreach ($resources as $r) {
        if (SWUIsCreditToken($r->CardID ?? '')) { $hasCredit = true; break; }
    }
    if (!$hasCredit) return;
    usort($resources, function($a, $b) {
        return (SWUIsCreditToken($a->CardID ?? '') ? 1 : 0) <=> (SWUIsCreditToken($b->CardID ?? '') ? 1 : 0);
    });
    for ($i = 0; $i < count($resources); $i++) $resources[$i]->mzIndex = $i;
}

// Defeat a Credit token at $mzID — tokens leave play by being set aside (CR 3.2), NOT to a discard
// pile. Returns true if one was removed.
function SWUDefeatCreditToken(string $mzID): bool {
    $obj = GetZoneObject($mzID);
    if (SWUObjGone($obj)) return false;
    if (!SWUIsCreditToken($obj->CardID ?? '')) return false;
    $obj->removed = true;
    DecisionQueueController::CleanupRemovedCards();
    return true;
}

// Count a player's resources (non-removed, EXCLUDING Credit tokens); $readyOnly restricts to ready ones.
function SWUResourceCount(int $player, bool $readyOnly = false): int {
    $resources = GetResources($player);
    $n = 0;
    foreach ($resources as $r) {
        if (isset($r->removed) && $r->removed) continue;
        if (SWUIsCreditToken($r->CardID ?? '')) continue; // Credit tokens are not resources (CR 3.13)
        if ($readyOnly && intval($r->Status) !== 1) continue;
        $n++;
    }
    return $n;
}

// $partial=true → exhaust min($count, ready) instead of requiring the full $count (all-or-nothing).
// Cost-payment callers must leave $partial false; effects that read "exhaust N enemy resources"
// (e.g. SEC_235 The Wrong Ride) pass true so they exhaust as many as available, capped at N.
function SWUExhaustResources($player, $count, $partial = false) {
    $resources = &GetResources($player);
    $readyCount = 0;
    for ($i = 0; $i < count($resources); $i++) {
        if (isset($resources[$i]->removed) && $resources[$i]->removed) continue;
        if (SWUIsCreditToken($resources[$i]->CardID ?? '')) continue; // never exhaust a Credit token
        if (intval($resources[$i]->Status) === 1) $readyCount++;
    }
    if ($partial) { $count = min($count, $readyCount); if ($count <= 0) return false; }
    if ($readyCount < $count) return false;
    $exhausted = 0;
    for ($i = 0; $i < count($resources) && $exhausted < $count; $i++) {
        if (isset($resources[$i]->removed) && $resources[$i]->removed) continue;
        if (SWUIsCreditToken($resources[$i]->CardID ?? '')) continue; // never exhaust a Credit token
        if (intval($resources[$i]->Status) === 1) {
            $resources[$i]->Status = 0;
            $exhausted++;
        }
    }
    return true;
}

// Single synchronous funnel to pay $cost, where $prepaid of it was already covered by an
// alternate source (e.g. SEC_122 Droids — wired in a later phase). Exhausts max(0,$cost-$prepaid)
// REAL resources. Returns true on success. Records resources actually paid (real resources only)
// in $gLastPlayResourcesPaid. NOTE: synchronous — the interactive Droid choice (later) is queued
// by the call-site and pre-resolved into $prepaid, never inside this function.
// JTL_105 The Starhawk — "While paying costs, you pay half as many resources, rounded up." Applies once
// per controlled Starhawk (each halves, rounded up). Used at the card-play affordability check AND the
// payment funnel so a card can be both PLAYED and PAID at the reduced rate. (Ability/upgrade-cost
// halving via direct SWUExhaustResources is a documented edge — most such costs are 1, where ceil is a
// no-op.)
function SWUApplyCostHalving(int $player, int $resCost): int {
    if ($resCost <= 0) return $resCost;
    $count = 0;
    foreach (array_merge(GetGroundArena($player) ?? [], GetSpaceArena($player) ?? []) as $u) {
        if (!empty($u->removed)) continue;
        if (($u->CardID ?? '') === 'JTL_105' && !LostAbilities($u)) $count++;
    }
    for ($i = 0; $i < $count; $i++) $resCost = intval(ceil($resCost / 2));
    return $resCost;
}

// Spend the MINIMUM number of alternate payments (Credit tokens first, then SEC_122 Droids) to cover a
// $need-resource shortfall, and return how many were covered. Credits are re-resolved on every iteration:
// SWUDefeatCreditToken runs CleanupRemovedCards, which reindexes the zone, so a precomputed mzID list
// goes stale after the first defeat. Callers must confirm the shortfall is coverable BEFORE calling —
// this spends unconditionally and does not roll back.
function _SWUSpendAltPaymentShortfall(int $player, int $need): int {
    $paid = 0;
    while ($paid < $need) {
        $credits = SWUUsableCreditTokenMzIDs($player); // re-resolved: indices shift on each defeat
        if (empty($credits) || !SWUDefeatCreditToken($credits[0])) break;
        $paid++;
    }
    if ($paid < $need && SWUPlayerControlsSEC122($player)) {
        foreach (SWUReadyFriendlyDroids($player) as $mz) { // exhausting does not reindex
            if ($paid >= $need) break;
            $d = GetZoneObject($mz);
            if ($d === null || !empty($d->removed) || intval($d->Status ?? 0) !== 1) continue;
            $d->Status = 0;
            $paid++;
        }
    }
    return $paid;
}

// Pay an ability's inline resource COST (a card's own "pay N" / "[N resources]" component) with the
// same last-resort alt-payment as SWUPayCost, but WITHOUT touching $gLastPlayResourcesPaid or the
// 'resourcesUsed' telemetry — those describe a card PLAY (TWI_210 reads the former), and an activated
// ability's cost is not a play. Returns false and spends nothing if the cost cannot be met.
//
// Use this instead of a bare SWUExhaustResources wherever the ACTING player pays a cost. Keep
// SWUExhaustResources for EFFECTS that exhaust resources (e.g. "exhaust 2 enemy resources"), which are
// not costs and must never consume Credit tokens.
function SWUPayInlineAbilityCost(int $player, int $cost): bool {
    $cost = max(0, $cost);
    if ($cost === 0) return true;
    if (SWUTotalPaymentCapacity($player) < $cost) return false;
    // Pin the frame to the PAYING player for the whole payment. The Credit/Droid shortfall path resolves
    // "myResources-N" mzIDs against the ambient $playerID, so a cost paid by someone other than the
    // current frame's player (an opponent answering a "you may pay 1" prompt — SEC_218 Cikatro Vizago)
    // would otherwise look for Credits in the WRONG resource row and silently fail to pay.
    global $playerID; $savedPID = $playerID; $playerID = $player;
    $ready    = SWUResourceCount($player, readyOnly: true);
    $autoPaid = ($ready < $cost) ? _SWUSpendAltPaymentShortfall($player, $cost - $ready) : 0;
    $fromRes  = max(0, $cost - $autoPaid);
    $ok = ($fromRes === 0) ? true : SWUExhaustResources($player, $fromRes);
    $playerID = $savedPID;
    return $ok;
}

// Pay a resource cost. $prepaid = resources already covered upstream by the INTERACTIVE alt-payment
// funnel (SWUOfferAltPayment), which is used wherever the payment point can reach a continuation.
//
// LAST-RESORT alt-payment: where a cost is paid inline and cannot reach a continuation (the bespoke
// "play a card at −N" effects and per-card "pay N" abilities — ~50 sites, each with its own post-payment
// logic), the player would otherwise be unable to spend Credit tokens / SEC_122 Droids at all, even
// though CR 3.13 and SEC_122 both say they pay COSTS. So if ready resources alone fall short AND total
// capacity covers it, spend the MINIMUM tokens needed and exhaust the rest.
//
// Deliberately last-resort, not first: when resources alone suffice, nothing is auto-spent and this is
// byte-identical to the old behaviour — a player never loses a token they could have kept. The residual
// gap is that with several tokens the player cannot choose to spend MORE of them to preserve a ready
// resource; that choice survives only on the interactive paths above.
function SWUPayCost($player, $cost, $prepaid = 0, bool $applyCostHalving = true, bool $altPayAlreadyOffered = false): bool {
    $cost    = max(0, intval($cost));
    $resCost = max(0, $cost - intval($prepaid));
    if ($applyCostHalving) $resCost = SWUApplyCostHalving(intval($player), $resCost); // JTL_105 The Starhawk
    $autoPaid = 0;
    // $altPayAlreadyOffered: the caller came through SWUOfferAltPayment, so the player was SHOWN the
    // token choice and $prepaid is their answer. Auto-spending here would override an explicit refusal —
    // e.g. the Falcon's "you may pay 1 to keep it ready": declining must let it bounce, not silently
    // exhaust a Droid. Only inline paths that could never ask get the last-resort spend.
    if ($resCost > 0 && !$altPayAlreadyOffered) {
        $ready = SWUResourceCount($player, readyOnly: true);
        if ($ready < $resCost && SWUTotalPaymentCapacity($player) >= $resCost) {
            $autoPaid = _SWUSpendAltPaymentShortfall(intval($player), $resCost - $ready);
        }
    }
    $fromResources = max(0, $resCost - $autoPaid);
    $ok = ($fromResources === 0) ? true : SWUExhaustResources($player, $fromResources);
    // Report RESOURCES exhausted, not total cost — a token-paid point is not a resource paid (TWI_210).
    $GLOBALS['gLastPlayResourcesPaid'] = $ok ? $fromResources : 0;
    if ($ok && $fromResources > 0 && function_exists('SWUTelemetryBumpTurn')) SWUTelemetryBumpTurn($player, 'resourcesUsed', $fromResources);
    return $ok;
}

// Put the card at $mzID (hand or deck) into play as a READY resource (Status:1).
// Normal resources enter exhausted; SOR_017 Han Solo's abilities ready the new one.
// Returns the new resource object or null on failure.
function SWURampResourceReady(int $player, string $mzID): ?object {
    global $playerID;
    $savedPID = $playerID;
    $playerID = intval($player);
    $newResource = MZMove($player, $mzID, "myResources");
    if ($newResource !== null) {
        $newResource->Status     = 1; // enters READY
        $newResource->Owner      = intval($player);
        $newResource->Controller = intval($player);
        AddGameLogEntry('RESOURCE', 'P' . intval($player) . ' put a card into play as a ready resource');
        // Card slides into the RESOURCE ZONE ANCHOR, not a per-card slot: resources collapse to a
        // single DOM element (CollapseGroupBy CardID — GameLayoutShared), so 'myResources-N' for N>0
        // resolves to nothing and the card flew at whatever the fallback picked. 'myResources-0' is
        // the collapsed badge and is always present.
        // Scoped to the resourcing player: the Resources zone is Display: Visibility=Self, so the
        // opponent has no business seeing a card slide into it.
        SWUQueueZoneMoveAnim($mzID, 'myResources-0', intval($player), 420, null, intval($player));
    }
    $playerID = $savedPID;
    return $newResource;
}

// "Put a card into play as a resource" — the DEFAULT: it enters EXHAUSTED (readied at the controller's
// next ReadyPhase), because in SWU cards enter play exhausted unless the text says otherwise. Only the
// explicit "...and ready it / and readies it" wording (SOR_017, SEC_242) uses SWURampResourceReady.
function SWURampResourceExhausted(int $player, string $mzID): ?object {
    global $playerID;
    $savedPID = $playerID;
    $playerID = intval($player);
    $newResource = MZMove($player, $mzID, "myResources");
    if ($newResource !== null) {
        $newResource->Status     = 0; // enters EXHAUSTED
        $newResource->Owner      = intval($player);
        $newResource->Controller = intval($player);
        AddGameLogEntry('RESOURCE', 'P' . intval($player) . ' put a card into play as a resource');
        // Card slides into the RESOURCE ZONE ANCHOR, not a per-card slot: resources collapse to a
        // single DOM element (CollapseGroupBy CardID — GameLayoutShared), so 'myResources-N' for N>0
        // resolves to nothing and the card flew at whatever the fallback picked. 'myResources-0' is
        // the collapsed badge and is always present.
        // Scoped to the resourcing player: the Resources zone is Display: Visibility=Self, so the
        // opponent has no business seeing a card slide into it.
        SWUQueueZoneMoveAnim($mzID, 'myResources-0', intval($player), 420, null, intval($player));
    }
    $playerID = $savedPID;
    return $newResource;
}

// Defeat the resource at $mzID, sending it to its owner's discard (From:RESOURCES).
// Used by SOR_017 Han Solo's "defeat a resource you control" pending trigger.
function SWUDefeatResource(int $player, string $mzID): bool {
    global $playerID;
    $savedPID = $playerID;
    $playerID = intval($player);
    $obj = GetZoneObject($mzID);
    if ($obj === null || (isset($obj->removed) && $obj->removed)) {
        $playerID = $savedPID;
        return false;
    }
    $cardID = $obj->CardID;
    $owner  = intval($obj->Owner ?? 0);
    if ($owner === 0) $owner = intval($player);
    $obj->removed = true;
    SWUAddToDiscard($owner, $cardID, 'RESOURCES');
    AddGameLogEntry('DEFEAT', 'P' . intval($player) . ' defeated a resource');
    DecisionQueueController::CleanupRemovedCards();
    $playerID = $savedPID;
    return true;
}

// True if a unit's printed text makes it enter play ready (e.g. SOR_193 Millennium
// Falcon). Most units enter exhausted; these enter with Status:1.
function SWUUnitEntersReady(string $cardID): bool {
    // Only a SELF-referential "this unit enters play ready" makes the played unit itself enter ready
    // (SOR_193 Millennium Falcon, and the conditional cards SEC_170/LAW_210/LAW_223/ASH_224 which are then
    // re-gated at the call site). Cards whose "…it/that unit/the next unit/each token unit… enters play
    // ready" clause grants readiness to a DIFFERENT unit (SOR_129 Ozzel, SHD_194, TWI_189, TWI_203, LAW_074,
    // ASH_245, ASH_248 Neel) must NOT self-ready — that readiness is applied to the other unit via
    // $gForceEnterReady / the ASH_248 flag / dedicated play paths, never by this text-match.
    $text = CardText($cardID) ?? '';
    return stripos($text, 'this unit enters play ready') !== false;
}

// True if $player's base carries $trait. Base traits are published by AppCore/SWU/CardTraitSupplement.php
// (the API omits them), merged into $traitData at generation, so HasTrait resolves them like any card
// trait. Shared with SWUDeck — see AppCore/SWU/TraitSupplement.php.
// Used by the HMW base-condition cards (HMW_142 Kashyyyk, HMW_234 Tatooine, HMW_177 Endor).
function _SWUControlsBaseWithTrait(int $player, string $trait): bool {
    $zone = GetBase($player);
    $base = $zone[0] ?? null;
    if ($base === null) return false;
    return HasTrait($base->CardID ?? '', $trait);
}

// True if $player's base has a Fortify upgrade with CardID $cardID attached (HMW_206 The Tarkin Doctrine).
function _SWUBaseHasUpgrade(int $player, string $cardID): bool {
    $zone = GetBase($player);
    $base = $zone[0] ?? null;
    if ($base === null) return false;
    return SWUFindUpgradeIndex($base, $cardID) >= 0;
}

// How many copies of $cardID are attached to $player's base. The boolean _SWUBaseHasUpgrade above is
// enough for a UNIQUE Fortify upgrade; a non-unique one (HMW_113 Sinister War Memorial) can be stacked
// and each copy grants its own ability, so those must COUNT.
function _SWUCountBaseUpgrades(int $player, string $cardID): int {
    $zone = GetBase($player);
    $base = $zone[0] ?? null;
    if ($base === null || !is_array($base->Subcards ?? null)) return 0;
    $n = 0;
    foreach ($base->Subcards as $sub) {
        $cid = is_array($sub) ? ($sub['CardID'] ?? '') : ($sub->CardID ?? '');
        $rem = is_array($sub) ? !empty($sub['removed']) : !empty($sub->removed);
        if (!$rem && $cid === $cardID) $n++;
    }
    return $n;
}

// The SWUDefeatUpgrade-style index (non-captive, non-removed order) of the base-attached upgrade carrying
// $uid, or -1 if not found. Used by HMW_060 Rampart's deferred replacement to re-locate the saved upgrade.
function _SWUBaseUpgradeIndexByUID(int $player, string $hostMz, int $uid): int {
    if ($uid <= 0) return -1;
    global $playerID; $sp = $playerID; $playerID = intval($player);
    $host = GetZoneObject($hostMz);
    $playerID = $sp;
    if (SWUObjGone($host) || !is_array($host->Subcards ?? null)) return -1;
    $idx = 0;
    foreach ($host->Subcards as $sub) {
        $isCaptive = is_array($sub) ? !empty($sub['IsCaptive']) : !empty($sub->IsCaptive);
        $isRemoved = is_array($sub) ? !empty($sub['removed'])   : !empty($sub->removed);
        if ($isCaptive || $isRemoved) continue;
        $suid = is_array($sub) ? intval($sub['UniqueID'] ?? 0) : intval($sub->UniqueID ?? 0);
        if ($suid === $uid) return $idx;
        $idx++;
    }
    return -1;
}

// HMW_234 Ritual Dragon — "While you control a Tatooine base, friendly units enter play ready (including
// this one)." A continuous passive: while HMW_234 is in play and its controller has a Tatooine base, that
// player's units enter ready. "Including this one" means HMW_234's OWN entry also readies — it isn't in
// play yet at entry-status time, so its own CardID short-circuits the "controls HMW_234" check.
function _SWURitualDragonEntersReady(int $player, string $cardID): bool {
    if (!_SWUControlsBaseWithTrait($player, 'Tatooine')) return false;
    if ($cardID === 'HMW_234') return true;   // self-inclusion on its own entry
    return _SWUCountActiveUnitsWithCardID($player, 'HMW_234') > 0;
}

// ─── Twin Suns seat helpers (Phase 1) ─────────────────────────────────────────
// SeatOrder / LiveSeats are single-digit seat lists stored as global Value scalars
// (seats are always 1..4, so no separator is needed — "123" = seats 1,2,3). SeatOrder is
// the clockwise turn order; LiveSeats is the non-eliminated subset. Default "12" keeps a
// 2-player game correct with no CreateGame change.
function GetSeatOrderArray(): array {
    $raw = trim((string)GetSeatOrder());
    if ($raw === '') return [1, 2];
    return array_map('intval', str_split($raw));
}
function GetLiveSeatsArray(): array {
    $raw = trim((string)GetLiveSeats());
    if ($raw === '') return GetSeatOrderArray();
    return array_map('intval', str_split($raw));
}
function IsSeatLive(int $seat): bool {
    return in_array($seat, GetLiveSeatsArray(), true);
}
function SeatCountForGame(): int {
    return count(GetSeatOrderArray());
}

// ─── Twin Suns elimination & end-game scoring (Phase 5) ───────────────────────
// Eliminate a seat whose base reached 0 HP (CR §11.3 / §12.6.2). This is the FIRST-EVER
// mutation of LiveSeats. $killer = the seat that dealt the lethal base damage (null for a
// state-based / shrink defeat → no heal). Twin Suns only; the 2-player path still uses the
// instant-win in SWUDeclareGameWinner and never reaches here.
// Tear down one arena's presence for an eliminated seat (no leave-play / when-defeated triggers).
function _SWUCleanupArenaForElim(int $seat, array &$arena): void {
    for ($i = 0; $i < count($arena); $i++) {
        $u = $arena[$i];
        if (!empty($u->removed)) continue;
        $owner      = intval($u->Owner ?? 0);
        $controller = intval($u->Controller ?? $owner);
        if ($owner === $seat) {
            // OWNED by the eliminated seat → rescue any captives it held, then set aside.
            SWURescueCaptivesOf($u);
            $arena[$i]->removed = true;
        } elseif ($controller === $seat && $owner !== $seat && $owner > 0) {
            // Controlled-but-not-owned (mind-control) → owner's discard, trigger-free.
            SWURescueCaptivesOf($u);
            $cid = !empty($u->IsClone) ? 'TWI_116' : ($u->CardID ?? '-');
            AddDiscard($owner, $cid, 'PLAY');
            $arena[$i]->removed = true;
        }
    }
}

// Remove an eliminated seat's board presence WITHOUT firing leave-play / when-defeated triggers
// (CR §11.3.1a: cards removed this way are not "defeated" / "left play").
function _SWUEliminationCleanup(int $seat): void {
    foreach (GetSeatOrderArray() as $p) {
        $g = &GetGroundArena($p); _SWUCleanupArenaForElim($seat, $g); unset($g);
        $s = &GetSpaceArena($p);  _SWUCleanupArenaForElim($seat, $s); unset($s);
    }
    // Mark the seat's own base removed so no stray sweep re-reads it.
    $b = &GetBase($seat);
    if (!empty($b) && empty($b[0]->removed)) $b[0]->removed = true;
}

function SWUEliminateSeat(int $seat, ?int $killer = null): void {
    if (SeatCountForGame() <= 2) return;                 // Twin Suns only
    $live = GetLiveSeatsArray();
    if (!in_array($seat, $live, true)) return;           // idempotent — already eliminated
    // 1. Remove from LiveSeats (SeatOrder is left intact for rotation math).
    $live = array_values(array_filter($live, fn($s) => $s !== $seat));
    SetLiveSeats(implode('', $live));
    _SWUEliminationCleanup($seat);
    // 2. Release any counter this seat held back to center (CR §11.3.4).
    if (GetBlastCounter() === "P{$seat}") SetBlastCounter("AVAILABLE");
    if (GetPlanCounter()  === "P{$seat}") SetPlanCounter("AVAILABLE");
    $ic = GetInitiativeCounter();
    if ($ic === "P{$seat}_CLAIMED" || $ic === "P{$seat}_UNCLAIMED") {
        SetInitiativeCounter("P" . strval($live[0] ?? 1) . "_UNCLAIMED");
    }
    // 3. Optionally heal the eliminator 5 (CR §12.6.2). Self-elimination / no-damager heals no one.
    if ($killer !== null && $killer !== $seat && in_array($killer, $live, true)) {
        OnHealBase($killer, $killer, 5);
    }
    // 4. Flag the game to end at the next phase boundary (deferred scoring below).
    SetSWUVar('SWU_TS_GAME_ENDING', '1');
    AddGameLogEntry('ELIMINATED', "Player {$seat} has been eliminated!", 'ALL');
    // 5. Safety net: a single survivor has nothing left to play — score immediately (CR §12.7).
    if (count(GetLiveSeatsArray()) <= 1) _SWUScoreTwinSunsEndOfPhase();
}

// Deferred Twin Suns end-of-phase scoring (CR §12.7). No-op unless a prior elimination set
// SWU_TS_GAME_ENDING. Highest remaining base HP among live seats wins; ties share the victory.
function _SWUScoreTwinSunsEndOfPhase(): void {
    if (SeatCountForGame() <= 2) return;
    if (GetSWUVar('SWU_TS_GAME_ENDING') !== '1') return;
    if (SWUGetGameWinner() !== 0) return;                 // already scored / ended
    $live = GetLiveSeatsArray();
    if (empty($live)) return;
    // Consume the flag so scoring can't run twice. (This used to have to happen BEFORE the winner
    // was stored, because SetSWUVar and StoreVariable wrote the shared variable slot in different
    // encodings and each wiped the other — an ordering workaround that only ever helped locally,
    // since the next SetSWUVar anywhere still erased the winner. Both encodings are unified now,
    // so the order here is free; see the note above _parseSWUVars.)
    SetSWUVar('SWU_TS_GAME_ENDING', '');
    $best = -PHP_INT_MAX; $remain = [];
    foreach ($live as $p) {
        $b = GetBase($p);
        $hp = (empty($b) || !empty($b[0]->removed)) ? -PHP_INT_MAX
            : intval(CardHp($b[0]->CardID)) - intval($b[0]->Damage ?? 0);
        $remain[$p] = $hp;
        if ($hp > $best) $best = $hp;
    }
    $winners = array_values(array_filter($live, fn($p) => $remain[$p] === $best));
    $label = count($winners) > 1
        ? "GAMEOVER:Players " . implode(', ', $winners) . " share the victory (highest base HP)!"
        : "GAMEOVER:Player {$winners[0]} wins (highest base HP)!";
    SWUDeclareTwinSunsWinners($winners, $label);         // JSON store — MUST be the last DQ-var write
}

// ─── Twin Suns opponent-targeting primitives (Phase 3) ────────────────────────
// These replace the hard 2-player OtherPlayer()/GetOpponent() at N-player-relevant call sites.
// All are byte-identical to the 2-player model when there is exactly one live opponent.

// All LIVE opponents of $player, in seat order. 2-seat game → [the other seat]. Use for
// "each opponent" / iterate-all effects: `foreach (OpponentsOf($p) as $opp) { ... }`.
function OpponentsOf(int $player): array {
    $out = [];
    foreach (GetLiveSeatsArray() as $seat) {
        if ($seat !== $player) $out[] = $seat;
    }
    return $out;
}

// The single opponent to target for a "choose an opponent" effect. Unambiguous whenever there is
// exactly one live opponent (every 2-player game, and any N-player state narrowed to one). Twin Suns
// N-player: the call sites that need a real choice get an interactive prompt in Phase 4 (when a 3–4
// seat game is playable); until then this resolves to the first live opponent so 2-player is identical.
function SWUChooseOpponent(int $player): int {
    $opps = OpponentsOf($player);
    return $opps[0] ?? OtherPlayer($player);
}

// The next LIVE seat clockwise from $player (skips eliminated seats). 2-seat game → the other seat.
// Use for turn-rotation / "the next player" flow (not for targeting an opponent).
function NextLiveSeat(int $player): int {
    $order = GetSeatOrderArray();
    $n = count($order);
    $idx = array_search($player, $order, true);
    if ($idx === false) return OtherPlayer($player);
    for ($step = 1; $step <= $n; $step++) {
        $cand = $order[($idx + $step) % $n];
        if ($cand !== $player && IsSeatLive($cand)) return $cand;
    }
    return OtherPlayer($player);
}

// Twin Suns (Phase 3): the owning seat of a target mzID / decision string, regardless of prefix. The
// ZoneSearch union emits seat-specific p{n}<Zone> mzIDs in N-player games; this decodes ownership from
// any of the three forms. 2-player is byte-identical to the old `strpos('their') ? opp : self` decoders.
//   p{n}<Zone>  → seat n            (union targets)
//   their<Zone> → the one opponent  (2-player; SWUChooseOpponent == OtherPlayer there)
//   my<Zone>/other → $actingPlayer  (self)
function SWUMzOwner(string $mzID, int $actingPlayer): int {
    if (preg_match('/^p(\d+)/', $mzID, $m)) return intval($m[1]);
    if (strpos($mzID, 'their') !== false) return SWUChooseOpponent($actingPlayer);
    return $actingPlayer;
}

// Twin Suns (Group B): "$chooser chooses AN opponent, then $handler runs with the picked seat." The
// picked seat arrives in the continuation's $lastDecision as "P{n}" (parse with SWUPickedOpponent).
//  - exactly ONE live opponent → forced: PASSPARAMETER the lone opponent (no prompt), then $handler.
//  - 2+ live opponents (Twin Suns) → OPTIONCHOOSE of "P{n}" labels, then $handler.
// $handler is a customDQHandler name; carry extra state in its Param ("MY_HANDLER|extra"). Call this ONLY
// on the N-player branch of a site — keep the original 2-player inline effect so 2-player stays identical.
function SWUQueueChooseOpponent(int $chooser, string $handler, string $tooltip = "Choose_an_opponent"): void {
    $opps = OpponentsOf($chooser);
    if (count($opps) <= 1) {
        $lone = $opps[0] ?? OtherPlayer($chooser);
        DecisionQueueController::AddDecision($chooser, "PASSPARAMETER", "P{$lone}", 1);
    } else {
        $labels = array_map(fn($s) => "P{$s}", $opps);
        DecisionQueueController::AddDecision($chooser, "OPTIONCHOOSE", implode("&", $labels), 1, tooltip: $tooltip);
    }
    DecisionQueueController::AddDecision($chooser, "CUSTOM", $handler, 1);
}

// Parse the seat an opponent-picker chose (the "P{n}" carried in $lastDecision). Returns 0 if unparseable
// (a declined/blank pick), so callers can no-op.
function SWUPickedOpponent($lastDecision): int {
    return preg_match('/^P(\d+)$/', (string)$lastDecision, $m) ? intval($m[1]) : 0;
}

// Twin Suns (Group B): the "choose a player" OPTIONCHOOSE label set — "You" + one option per opponent.
// 2-player → the historical "You&Opponent" (byte-identical). N-player → "You&P2&P3...".
function SWUPlayerPickerLabels(int $caster): string {
    if (SeatCountForGame() <= 2) return "You&Opponent";
    $labels = ["You"];
    foreach (OpponentsOf($caster) as $o) $labels[] = "P{$o}";
    return implode("&", $labels);
}
// Decode a "choose a player" pick to a seat: "You"→caster, "Opponent"→lone opp (2-player), "P{n}"→seat n.
function SWUDecodePlayerPick($lastDecision, int $caster): int {
    if ($lastDecision === 'You') return $caster;
    if ($lastDecision === 'Opponent') return OtherPlayer($caster);
    if (preg_match('/^P(\d+)$/', (string)$lastDecision, $m)) return intval($m[1]);
    return $caster;
}

// Same idea for "choose a DECK to look at" pickers. 2-player → the historical two-label set the caller
// passes; N-player → "Your_deck" + one "P{n}_deck" per opponent. The decoder handles both label styles.
function SWUDeckPickerLabels(int $caster, string $twoPlayerLabels = "Your_deck&Opponent's_deck"): string {
    if (SeatCountForGame() <= 2) return $twoPlayerLabels;
    $labels = ["Your_deck"];
    foreach (OpponentsOf($caster) as $o) $labels[] = "P{$o}_deck";
    return implode("&", $labels);
}
function SWUDecodeDeckPick($lastDecision, int $caster): int {
    if ($lastDecision === 'Your_deck' || $lastDecision === 'Yours') return $caster;
    if ($lastDecision === "Opponent's_deck" || $lastDecision === 'Theirs') return OtherPlayer($caster);
    if (preg_match('/^P(\d+)_deck$/', (string)$lastDecision, $m)) return intval($m[1]);
    return $caster;
}

// Swap TurnPlayer (1→2, 2→1), then auto-pass for any player who has claimed
// the initiative this round (they are treated as passing for the rest of APS).
// Whether $seat has taken a counter this round (initiative in premier; + blast/plan in Twin Suns via
// SWU_COUNTER_TAKEN). Such a seat has "passed for the rest of the round" (CR §12.5.3 / initiative).
function _SWUSeatTookCounterThisRound(int $seat): bool {
    if (GetInitiativeCounter() === "P{$seat}_CLAIMED") return true;
    $taken = GetSWUVar('SWU_COUNTER_TAKEN', '');
    return $taken !== '' && strpos($taken, strval($seat)) !== false;
}

function SWUSwapTurnPlayer() {
    global $gTurnPlayer;
    // Twin Suns (Phase 4): advance clockwise via SeatOrder, skipping eliminated seats. 2-player: the other seat.
    $gTurnPlayer = NextLiveSeat(intval($gTurnPlayer));
    // Auto-pass for a seat that already took a counter this round (it's passing for the rest of the round).
    if (_SWUSeatTookCounterThisRound(intval($gTurnPlayer))) {
        SWUPassAction(intval($gTurnPlayer));
    }
    // Goldfish: P2 is a passive bot. Whenever the turn swaps to it, auto-pass immediately — exactly
    // like an initiative-claimant. P1's action → swap to P2 → P2 passes → swap back to P1. Two passes
    // (P1 pass + P2 auto-pass) end the action phase and advance to the next regroup, so P1 plays solo.
    // Goldfish P2, OR the passive opponent of an interrupted replay ("Play from Here" — P1 plays a
    // different line solo), auto-passes whenever the turn swaps to it, exactly like an initiative
    // claimant. The function_exists guard keeps the schema test harness (which may not load MatchReplay)
    // safe; MatchReplayIsInterrupted() is false in every normal/goldfish game.
    if ((SWUGameMode() === 'goldfish'
         || (function_exists('MatchReplayIsInterrupted') && MatchReplayIsInterrupted()))
        && intval($gTurnPlayer) === 2) {
        SWUPassAction(2);
    }
}

// ── SWU game-variable helpers ─────────────────────────────────────────────────
// $gDecisionQueueVariables holds a JSON object of KEY => VALUE.
//
// ⚠ This slot is SHARED with the engine's DecisionQueueController::StoreVariable/GetVariable. These
// helpers used to write it as pipe-delimited "K=V|K=V" text instead, so the two APIs silently
// destroyed each other: StoreVariable json_decode'd a pipe string, got a non-array, and restarted
// from []; this parser found no "|" in JSON and rewrote the slot as pipe. A value written once and
// read later would just vanish — that is how a completed Twin Suns game lost its GAMEOVER_WINNER
// between scoring and the match hook, leaving every seat with "You Lost".
// Both writers now emit JSON. Reads still accept the legacy pipe form (and the oldest bare-integer
// PASS form) so games saved before the unification keep loading — see Core/DecisionQueueController.
// The decode is duplicated rather than shared to keep this file free of a load-order dependency.

function _parseSWUVars(): array {
    global $gDecisionQueueVariables;
    $raw = trim((string)$gDecisionQueueVariables);
    if ($raw === '') return [];
    $json = json_decode($raw, true);
    if (is_array($json)) return $json;
    // ── legacy formats ──
    if (preg_match('/^\d+$/', $raw)) {
        return ['PASS' => $raw];
    }
    $result = [];
    foreach (explode('|', $raw) as $pair) {
        $kv = explode('=', $pair, 2);
        if (count($kv) === 2) $result[$kv[0]] = $kv[1];
    }
    return $result;
}

function GetSWUVar(string $key, string $default = ''): string {
    $value = _parseSWUVars()[$key] ?? $default;
    // StoreVariable() shares this map and may park arrays/objects in it; never return one as a string.
    return is_scalar($value) ? (string)$value : $default;
}

function SetSWUVar(string $key, string $value): void {
    global $gDecisionQueueVariables;
    $vars = _parseSWUVars();
    $vars[$key] = $value;
    $gDecisionQueueVariables = json_encode($vars);
}

function MarkUndoRequiresConsent(): void {
    // O(1): just raise the live per-action flag (called on every draw/scry/search/reveal). The flag is
    // folded into the top snapshot's revealedInfo LATER — at the next PushUndoSnapshot, or read live at
    // undo time — so reveals never rewrite the undo file per draw (that was O(n^2)). See PushUndoSnapshot.
    SetSWUVar('UNDO_REQUIRES_CONSENT', 'true');
}

function ResetUndoDenyCount(int $playerID): void {
    SetSWUVar('UNDO_DENY_COUNT_' . $playerID, '0');
}

// Which seat's pending decision is holding the action-phase exit open (EvaluateTransition returns
// PENDING_DECISION while ANY queue is non-empty)? Returns null when no seat has one.
//
// This is where SWU_RETRY_ENDPHASE has to be queued, and it is NOT always the passing player.
// DecisionQueueController::ExecuteStaticMethods drains one seat's queue in an UNCAPPED while-loop, so a
// static handler that re-queues itself into a queue with nothing interactive ahead of it spins forever
// — the request burns CPU until max_execution_time and the game looks frozen. That is exactly what a
// goldfish "when you take the initiative" trigger did: P1 claims, its YESNO lands in P1's queue, then
// the goldfish auto-pass runs SWUPassAction(2), the exit is blocked by P1's prompt, and the retry went
// onto seat 2 — whose queue held only the retry itself. Queuing on the blocking seat puts the retry
// BEHIND that seat's interactive decision, which is what already made the normal 2-player path safe
// (there the claimant and the blocker are the same seat, so this returns $player unchanged).
//
// Prefer a seat whose FRONT decision is interactive: the static types below are drained inline by
// ExecuteStaticMethods, so a queue of only those will empty on its own and can't hold the retry.
function _SWUEndPhaseBlockingSeat(): ?int {
    static $staticTypes = ['CUSTOM', 'SYSTEM', 'MZMOVE', 'PASSPARAMETER'];
    $seats = GetLiveSeatsArray();
    if (empty($seats)) $seats = [1, 2];
    $anyPending = null;
    foreach ($seats as $s) {
        $queue = [];
        foreach (GetDecisionQueue(intval($s)) as $d) { if (empty($d->removed)) $queue[] = $d; }
        if (empty($queue)) continue;
        if ($anyPending === null) $anyPending = intval($s);
        if (!in_array((string)($queue[0]->Type ?? ''), $staticTypes, true)) return intval($s);
    }
    return $anyPending;
}

// Handle a pass action for $player.
// $gDecisionQueueVariables stores game-state variables as a pipe-delimited KEY=VALUE string.
// The PASS key tracks the consecutive-pass counter: 0 = no prior pass; 1 = opponent just passed.
function SWUPassAction($player) {
    $consecutivePasses = intval(GetSWUVar('PASS', '0'));
    // Twin Suns (Phase 4): the action phase ends when ALL live players pass consecutively. This pass is
    // the Nth; if the prior streak already covers every other live seat, it ends the phase. 2-player:
    // liveCount-1 == 1, so this is byte-identical to the old "two consecutive passes" rule.
    $liveCount = count(GetLiveSeatsArray());
    if ($consecutivePasses >= $liveCount - 1) {
        // Both players have passed → end the action phase (MAIN→RGS). But a "when you take the
        // initiative" trigger (e.g. ASH_155 Grogu's bonus attack) can still be QUEUED when the
        // initiative-claim resolves its pass — and a pending decision makes EvaluateTransition
        // return PENDING_DECISION, so AdvanceAndExecute("PASS") is a no-op. If we cleared PASS
        // first and the exit didn't actually fire, the phase would stay MAIN with PASS=0 — a fresh
        // action sequence, letting BOTH players keep acting (the Grogu bug). So only clear PASS
        // when the exit really fires; otherwise keep PASS=1 and retry once the queue drains
        // (high block so it runs after the triggers; DontSkipOnPass so a PASS answer can't skip it).
        //
        // ⚠ The retry must be queued on the seat that is actually BLOCKING, which is not always
        // $player — see _SWUEndPhaseBlockingSeat.
        if (AdvanceAndExecute("PASS")) {
            SetSWUVar('PASS', '0');
            AutoAdvanceAndExecute();
        } else {
            $blocker = _SWUEndPhaseBlockingSeat();
            if ($blocker !== null) {
                DecisionQueueController::AddDecision($blocker, 'CUSTOM', 'SWU_RETRY_ENDPHASE', 9, '', 1);
            }
        }
    } else {
        // A player who has already claimed the initiative is locked out for the rest of the action
        // phase — the engine resolves their non-turns as passes, but they aren't choosing to pass,
        // so don't log a "passed" entry for them (their claim was already logged as "took the
        // initiative"). Other passes are real player choices and ARE logged.
        if (GetInitiativeCounter() !== 'P' . intval($player) . '_CLAIMED') {
            AddGameLogEntry('PASS', 'P' . intval($player) . ' passed');
        }
        SetSWUVar('PASS', strval($consecutivePasses + 1));   // accumulate the consecutive-pass streak
        SWUSwapTurnPlayer();
    }
}

// Player claims the initiative: mark it CLAIMED, then treat as a pass.
function SWUTakeInitiative($player) {
    $ic = GetInitiativeCounter();
    // Only one player may take initiative per round (Twin Suns Phase 4: any seat, was P1/P2-hardcoded).
    if (str_ends_with($ic, '_CLAIMED')) {
        SetFlashMessage("Initiative has already been taken this round.");
        return;
    }
    SetInitiativeCounter("P{$player}_CLAIMED");
    AddGameLogEntry('INITIATIVE', 'P' . intval($player) . ' took the initiative');
    // LOF_203 Premonition of Doom — "The next time you take the initiative this phase, exhaust all units."
    if (GlobalEffectCount(intval($player), 'SWU_LOF203') > 0) {
        RemoveGlobalEffect(intval($player), 'SWU_LOF203');
        foreach ([1, 2] as $pl) {
            foreach (GetUnitsInPlay($pl) as $u) {
                if (empty($u->removed)) $u->Status = 0;  // exhaust
            }
        }
    }
    // SEC_168 Ziton Moj — "When you take the initiative: deal 2 to a base." One per controlled copy.
    foreach (GetUnitsInPlay(intval($player)) as $zm) {
        if (!empty($zm->removed) || ($zm->CardID ?? '') !== 'SEC_168') continue;
        SWUOfferBaseTarget(intval($player), ['continuation'=>'DEAL_BASE_DAMAGE','amount'=>2,'prompt'=>"Deal_2_to_a_base"]);
    }
    // ASH_014 The Mandalorian (leader) — "When you take the initiative: you may pay 1 resource; if you do,
    // draw a card." This is printed on the UNDEPLOYED leader side; once deployed, only the leader-unit-side
    // abilities are active (the deployed side is Support / On-Attack draw / Epic Action), so gate on !Deployed.
    $hasMando = false;
    foreach (GetLeader(intval($player)) as $l) { if (($l->CardID ?? '') === 'ASH_014' && empty($l->removed) && empty($l->Deployed)) { $hasMando = true; break; } }
    if ($hasMando && SWUTotalPaymentCapacity(intval($player)) >= 1) {
        DecisionQueueController::AddDecision(intval($player), "YESNO", "-", 1, tooltip: "Pay_1_resource_to_draw_a_card?");
        DecisionQueueController::AddDecision(intval($player), "CUSTOM", "ASH_014#0", 1);
    }
    // ASH_155 Grogu — "When you take the initiative: you may attack with a unit." One offer per controlled
    // Grogu. The bonus attack is OUT of the normal action sequence — SWUPassAction below already handles
    // this player's pass — so its terminal after-action must NOT swap the turn again; the ASH_155#0
    // continuation sets SWU_SUPPRESS_AFTERACTION before BeginSWUAttack (consumed in SWUAfterAction).
    foreach (GetUnitsInPlay(intval($player)) as $gz) {
        if (!empty($gz->removed) || ($gz->CardID ?? '') !== 'ASH_155') continue;
        global $playerID; $playerID = intval($player);
        $readyUnits = [];
        foreach (['myGroundArena', 'mySpaceArena'] as $zone) {
            $arr = GetZone($zone);
            for ($i = 0; $i < count($arr); $i++) {
                $u = $arr[$i];
                if (SWUObjGone($u) || intval($u->Status) !== 1) continue;
                $readyUnits[] = "{$zone}-{$i}";
            }
        }
        if (!empty($readyUnits)) {
            SWUQueueMayChooseTarget(intval($player), $readyUnits, "Grogu:_attack_with_a_unit?",
                "Choose_a_unit_to_attack_with", "ASH_155#0");
        }
    }
    // HMW_158 Ezra Bridger — "When you take the initiative: You may deal 3 damage to your base. If you do,
    // create a Beast token." One offer per controlled Ezra; self-damage is the cost, so the Beast (HMW_158#0)
    // is gated on the damage actually landing (skipped if prevented, e.g. Close the Shield Gate).
    foreach (GetUnitsInPlay(intval($player)) as $ez) {
        if (!empty($ez->removed) || ($ez->CardID ?? '') !== 'HMW_158') continue;
        DecisionQueueController::AddDecision(intval($player), "YESNO", "-", 1,
            tooltip: "Deal_3_to_your_base_to_create_a_Beast_token?");
        DecisionQueueController::AddDecision(intval($player), "CUSTOM", "HMW_158#0", 1);
    }
    SWUPassAction($player);
}

// Twin Suns (Phase 4): take an available counter (blast or plan) as the round-ending action (CR §12.5).
// Enforces one-counter-per-player-per-round, fires the counter's effect, records the seat (which drives
// the auto-pass in SWUSwapTurnPlayer), then passes for the rest of the round.
function SWUTakeCounter(int $player, string $which): void {
    if (_SWUSeatTookCounterThisRound($player)) {
        SetFlashMessage("You have already taken a counter this round.");
        return;
    }
    $which = strtolower($which);
    if ($which === 'blast') {
        if (GetBlastCounter() !== 'AVAILABLE') { SetFlashMessage("The blast counter has already been taken."); return; }
        SetBlastCounter("P{$player}");
        AddGameLogEntry('COUNTER', 'P' . $player . ' took the blast counter (1 damage to each enemy base)');
        // Blast: deal 1 damage to each opponent's base.
        foreach (OpponentsOf($player) as $opp) SWUDealDamageToBase(1, $opp);
    } elseif ($which === 'plan') {
        if (GetPlanCounter() !== 'AVAILABLE') { SetFlashMessage("The plan counter has already been taken."); return; }
        SetPlanCounter("P{$player}");
        AddGameLogEntry('COUNTER', 'P' . $player . ' took the plan counter (draw 1, bottom 1)');
        // Plan: draw 1, then place 1 card from hand on the bottom of the deck (may be the drawn card).
        DoDrawCard($player, 1);
        $hand = GetHand($player);
        $handMz = [];
        for ($i = 0; $i < count($hand); $i++) { if (empty($hand[$i]->removed)) $handMz[] = "myHand-{$i}"; }
        if (!empty($handMz)) {
            SWUQueueMayChooseTarget($player, $handMz, "-", "Put_a_card_on_the_bottom_of_your_deck", "SWU_PLAN_BOTTOM");
        }
    } else {
        return;
    }
    // Record the seat as a counter-taker (one-per-round guard + the auto-pass in SWUSwapTurnPlayer).
    SetSWUVar('SWU_COUNTER_TAKEN', GetSWUVar('SWU_COUNTER_TAKEN', '') . strval($player));
    SWUPassAction($player); // taking a counter = pass for the rest of the round
}

// Called after any real (non-pass) action: reset consecutive-pass counter and
// swap TurnPlayer to the opponent.
// SEC_192 Grand Moff Tarkin — "When this unit leaves play, that unit's owner takes control of [the
// stolen unit]." The steal is linked to Tarkin via a GlobalEffects flag SWU_SEC192|{tarkinUID}|{stolenUID}
// on Tarkin's controller. This lazy sweep (run after every action) reverts any steal whose Tarkin is
// no longer in play — covering ALL leave-play paths (defeat / bounce / capture / return-to-hand)
// uniformly, mirroring SWUFlushDeferredReplacements. (UIDs never repeat, so a stale flag can't mis-match.)
function _SWURevertSec192Steals(): void {
    global $playerID;
    foreach ([1, 2] as $p) {
        $ge = &GetGlobalEffects($p);
        for ($i = count($ge) - 1; $i >= 0; $i--) {
            $flag = (string)($ge[$i]->CardID ?? '');
            if (strpos($flag, 'SWU_SEC192|') !== 0) continue;
            $parts     = explode('|', $flag);
            $tarkinUID  = intval($parts[1] ?? 0);
            $stolenUID  = intval($parts[2] ?? 0);
            if (_SWUUnitInPlayWithUID($p, $tarkinUID)) continue; // Tarkin still in play → keep control
            // Tarkin gone → return the stolen unit (if still in play) to its owner; drop the flag.
            $savedPID = $playerID; $playerID = $p;
            $mz = SWUFindMzByUID($stolenUID);
            if ($mz !== null) {
                $o = GetZoneObject($mz);
                if ($o !== null && empty($o->removed)) {
                    $owner = intval($o->Owner ?? 0);
                    if ($owner > 0 && $owner !== intval($o->Controller ?? $owner)) {
                        SWUTakeControlOfUnit($owner, $mz);
                    }
                }
            }
            $playerID = $savedPID;
            array_splice($ge, $i, 1);
        }
    }
}

// Queue the action terminator — the step that ends the current action and passes the turn
// (the SWU_AFTER_ACTION handler → SWUAfterAction). ALWAYS use this instead of queuing
// SWU_AFTER_ACTION inline. It MUST run even when the action's last player decision was a
// declined optional "may" follow-up (Pass button → "PASS") or an auto-pass from an empty
// mandatory choice: the engine's decision queue makes a "PASS" answer sticky and would
// otherwise skip every subsequent CUSTOM (DecisionQueueController skip-on-pass at line ~77),
// swallowing this terminator → the turn never passes → the active player gets a free action.
// dontSkipOnPass marks the terminator exempt from that skip. (Events finalize the same way via
// FINISH_PLAY_CARD, which carries the same flag for the same reason.)
function SWUQueueAfterAction(int $player, int $block = 1): void {
    DecisionQueueController::AddDecision($player, "CUSTOM", "SWU_AFTER_ACTION", $block, dontSkipOnPass: 1);
}

// Record the UNIT that is the source of the ability/effect damage about to be dealt, so the target-side
// damage observer (_SWUOnUnitDamaged) can answer "a friendly unit dealt this" (TWI_016 Jango Fett). Stored
// as "uid,controller" in a persisted SWUVar so it survives the request boundary of an async target-choose
// (the ability queues a MZCHOOSE; the damage resolves in a later request). Set at each unit-ability
// DISPATCH point (When Played / On Attack / etc.); events/bases never set it, so event/base damage is
// correctly NOT "a friendly unit dealing damage". Cleared at the action boundary (SWUAfterAction). Combat
// damage does not use this — there the source controller is definitionally OtherPlayer(target.Controller).
function _SWURecordDamageSource(int $player, ?string $mzID): void {
    if ($mzID === null || $mzID === '') return;
    global $playerID;
    $saved = $playerID; $playerID = intval($player);
    $o = GetZoneObject($mzID);
    $playerID = $saved;
    if ($o === null) return;                 // unresolvable → keep whatever was there
    $ctrl = intval($o->Controller ?? $player);
    $uid  = intval($o->UniqueID ?? 0);
    if ($ctrl > 0) SetSWUVar('SWU_DMG_SRC', $uid . ',' . $ctrl);
}

function SWUAfterAction($player) {
    // Client-visible lobby facts, refreshed every action so a game already in flight when this shipped
    // self-heals rather than rendering the wrong Undo menu forever. Cosmetic only — SWUTakeBookmark /
    // SWULoadBookmark re-check privacy server-side, and a crafted request is refused regardless.
    SetSWUVar('GAME_IS_PRIVATE', SWUGameIsPrivate('SWUSim', strval($GLOBALS['gameName'] ?? '')) ? 'true' : 'false');
    SetSWUVar('GAME_SEAT_COUNT', strval(SeatCountForGame()));
    SetSWUVar('SWU_DMG_SRC', ''); // clear the ability-damage source context at the action boundary (TWI_016)
    // Close the per-attack identity window. SWU_CURRENT_ATTACKER_UID is what lets a mid-attack ABILITY
    // defeat of the attacker count as "defeated while attacking"; leaving it set would make a later,
    // unrelated defeat of that same unit this phase look like one too.
    SetSWUVar('SWU_CURRENT_ATTACKER_UID', '0');
    // JTL_193 I Have You Now — "prevent all damage to the attacker THIS ATTACK." The marker is phase-lived so
    // it survives the mid-combat attack-sweep (covering a survivor-observer redirect that resolves after the
    // attack's damage), then cleared HERE at the action boundary — after all of the attack's queued triggers
    // have drained — so it never lingers to over-prevent a later hit on the same unit this phase.
    for ($jp = 1; $jp <= SeatCountForGame(); $jp++) {
        foreach (array_merge(GetGroundArena($jp) ?? [], GetSpaceArena($jp) ?? []) as $ju) {
            if (!empty($ju->removed) || !is_array($ju->TurnEffects ?? null)) continue;
            $ju->TurnEffects = array_values(array_filter($ju->TurnEffects, fn($te) => SWUParseTurnEffect((string)$te)['base'] !== 'JTL_193'));
        }
    }
    SWUFlushDeferredReplacements(); // resolve any "would be defeated → may instead …" deferrals first
    _SWURevertSec192Steals();       // SEC_192 Tarkin — revert any steal whose source left play
    _SWURevertShd213Steals();       // SHD_213 DJ — stolen resource returns to its owner when DJ leaves play
    _SWUShd001ProcessPending();      // SHD_001 Gar Saxon — return a defeated upgraded unit's upgrade to hand
    // CR 8.19.1.b / 29.3 — uniqueness rule: if the acting player now controls >1 in-play copy of a
    // unique card (e.g. they just played a second copy), they must choose and defeat copies until one
    // remains BEFORE this action ends and the turn passes. Not a triggered ability. SWUEnforceUniqueness
    // queues the choose-and-defeat and returns true; UNIQUENESS_DEFEAT re-enters SWUAfterAction after
    // the defeat (looping for 3+ copy piles), so control only falls through to the turn-swap below once
    // every unique the player controls is a singleton.
    if (SWUEnforceUniqueness(intval($player))) return;
    // CR 8.19.1.b binds EVERY player: an exchange/control-give can hand the NON-acting seat a
    // duplicate unique (Double-Cross). Enforce for the opponent too; their choose parks on THEIR
    // queue and, once resolved, re-enters this action-end as the ACTING player (param above).
    if (SWUEnforceUniqueness(OtherPlayer(intval($player)), intval($player))) return;
    // SEC_194 per-action tracking: finalize the just-completed action. SWU_LAST_ACTION records who acted
    // and whether it attacked a base (and whose), so SEC_194 can ask "did the opponent attack my base in
    // their previous action". The transient SWU_ACTION_BASEATK was set in ExecuteSWUAttack for base hits.
    $_ba = GetSWUVar('SWU_ACTION_BASEATK', '');
    SetSWUVar('SWU_ACTION_BASEATK', '');
    // ⚠ comma-delimited, NOT pipe: '|' is the SWUVar KEY=VALUE delimiter and would truncate the value.
    SetSWUVar('SWU_LAST_ACTION', $_ba !== '' ? (intval($player) . ',BASEATK,' . $_ba) : (intval($player) . ',OTHER'));
    // PER-PLAYER twin. SEC_194 asks "did an opponent attack your base during THEIR previous action" — the
    // opponent's OWN last action, not the most recent action by anybody. The single global above is
    // clobbered by any intervening action of ours (a leader deploy, for instance, which is exactly what
    // happens when SEC_194 is played via Plot during that deploy), which silently turned the card off.
    SetSWUVar('SWU_LAST_ACTION_' . intval($player), $_ba !== '' ? ('BASEATK,' . $_ba) : 'OTHER');
    // SEC_145 — mark that this player has acted this phase (gates "play only as your first action").
    if (GlobalEffectCount(intval($player), 'SWU_ACTED_PHASE') === 0) AddGlobalEffects(intval($player), 'SWU_ACTED_PHASE');
    // ASH_155 Grogu — a bonus attack triggered by taking the initiative must NOT run the action's
    // pass-reset/turn-swap (SWUTakeInitiative's SWUPassAction already passed). Consume the one-shot flag:
    // the deferred-replacement flush + tracking above still run, but leave PASS + TurnPlayer untouched.
    if (GetSWUVar('SWU_SUPPRESS_AFTERACTION', '') === '1') {
        SetSWUVar('SWU_SUPPRESS_AFTERACTION', '');
        DecisionQueueController::CleanupRemovedCards();
        return;
    }
    SetSWUVar('PASS', '0');
    DecisionQueueController::CleanupRemovedCards();
    // Plot window (CR §19): while a leader-deploy Plot window is open, a nested play's terminal
    // After Action must NOT end the deploy action. Redirect to the Plot orchestrator, which
    // replaces the just-played card's resource slot and re-offers the next Plot (or closes the
    // window and runs the real After Action — the turn swap below — once none remain).
    if (GetSWUVar('SWU_PLOT_IN_PROGRESS', '') === '1') {
        _SWUPlotAfterPlay(intval($player));
        return;
    }
    SWUSwapTurnPlayer();
    _SWUCheckForcedAttack(intval(GetTurnPlayer())); // SHD_144 — force the new turn player's next action to be the compelled attack
}

// SHD_144 Give In to Your Anger — "Its controller's next action this phase must be an attack action
// with that unit, if able. It must attack a unit, if able." Armed via SWU_SHD144_FORCE|{uid} on the
// controller (set when the event resolved). Run right after the turn passes to that controller: if the
// compelled unit is able to attack a unit, force that attack (unit targets only, so it can't hit a base);
// if it can only attack a base, force that; if it can't attack at all, the compulsion lapses. One-shot —
// the flag is consumed regardless. (Auto-execute is the only enforcement model available: the engine has
// no "restrict the player's action menu" layer, so we perform the compelled attack directly, mirroring
// ASH_155's programmatic bonus attack. A multi-unit-target case still queues the target choose so the
// controller picks WHICH unit to attack, honoring "it must attack a unit.")
function _SWUCheckForcedAttack(int $player): void {
    global $playerID;
    $ge = &GetGlobalEffects($player);
    $flagIdx = -1; $unitUID = 0;
    for ($i = count($ge) - 1; $i >= 0; $i--) {
        $flag = (string)($ge[$i]->CardID ?? '');
        if (strpos($flag, 'SWU_SHD144_FORCE|') !== 0) continue;
        $unitUID = intval(explode('|', $flag)[1] ?? 0);
        $flagIdx = $i;
        break;
    }
    if ($flagIdx < 0) return;
    array_splice($ge, $flagIdx, 1);           // one-shot: consumed whether or not the attack happens
    if ($unitUID <= 0) return;

    $savedPID = $playerID; $playerID = $player;
    $mz = SWUFindMzByUID($unitUID);
    if ($mz === null) { $playerID = $savedPID; return; }         // unit left play (e.g. died to the 1 damage)
    $unit = GetZoneObject($mz);
    if (SWUObjGone($unit) || intval($unit->Status ?? 0) !== 1) { $playerID = $savedPID; return; }
    $cid = $unit->CardID ?? '';
    if ($cid === 'JTL_059' || $cid === 'LOF_044') { $playerID = $savedPID; return; } // "This unit can't attack."
    $arena = $unit->Location;
    $unitTargets = SWUGetAllValidAttackTargets($player, $unit, $arena, true);   // noBases → units only (union all opponents)
    if (!empty($unitTargets)) {
        BeginSWUAttack($player, $mz, true);                              // must attack a unit
    } elseif (!empty(SWUGetAllValidAttackTargets($player, $unit, $arena, false))) {
        BeginSWUAttack($player, $mz, false);                            // only a base is attackable → attack it
    }
    // else: not able to attack at all → the compulsion lapses ("if able").
    $playerID = $savedPID;
}

// "Take an extra action" (JTL_018 Kazuda Xiono): finish the current action's cleanup but DON'T swap
// the turn player, so the same player immediately takes another action. Resets the consecutive-pass
// counter (this was an action, not a pass).
function SWUAfterActionExtra($player) {
    SetSWUVar('PASS', '0');
    // An extra action is still AN ACTION this player took. SEC_145 Confidence in Victory ("play only as
    // your FIRST action in the action phase") reads this flag, and without it Kazuda's Action did not
    // count — so Confidence stayed playable with the extra action, which is exactly what it must not do.
    if (GlobalEffectCount(intval($player), 'SWU_ACTED_PHASE') === 0) {
        AddGlobalEffects(intval($player), 'SWU_ACTED_PHASE');
    }
    // ⚠ Deliberately NOT updating SWU_LAST_ACTION here. That var is a single global "the most recent
    // action and who took it", read by SEC_194 Fully Armed and Operational as "did the OPPONENT attack my
    // base in THEIR previous action". Recording this player's extra action would clobber the opponent's
    // entry and wrongly turn SEC_194 off. Intended: the condition stays ON when you take an action in
    // between (guarded by FullyArmedAndOperational::PlayerTakesAnActionInBetween_ConditionStillMet).
    DecisionQueueController::CleanupRemovedCards();
}

// ═══════════════════════════════════════════════════════════════════════════
// Trigger Bag — CR-correct triggered-ability collection and resolution
// ═══════════════════════════════════════════════════════════════════════════

// Ability registries — populated by the generator from the card-abilities DB.
// Tests may also inject closures directly for isolated ability testing.
global $whenPlayedAbilities, $whenDefeatedAbilities, $onAttackAbilities, $onDefenseAbilities, $onAttackEndAbilities;
$whenPlayedAbilities    = $whenPlayedAbilities    ?? [];
$whenDefeatedAbilities  = $whenDefeatedAbilities  ?? [];
$onAttackAbilities      = $onAttackAbilities      ?? [];
$onDefenseAbilities     = $onDefenseAbilities     ?? [];
$onAttackEndAbilities   = $onAttackEndAbilities   ?? [];

// Pending triggers collected at the current timing window before any DQ entries are queued.
global $gPendingTriggers, $gTriggerDepth;
$gPendingTriggers = $gPendingTriggers ?? [];
$gTriggerDepth    = $gTriggerDepth    ?? 1;

// Entry TurnEffects to apply when a unit with a specific UniqueID enters play.
// Keyed by UniqueID; consumed immediately inside ActivateCard after placement.
global $gPendingEntryEffects;
$gPendingEntryEffects = $gPendingEntryEffects ?? [];

// Exploit deferred-defeat-trigger bag (Task 1.2 of cost-payment rework, CR 16.d).
// When $gExploitDeferTriggers is true, CollectWhenDefeatedTriggers parks triggers here
// instead of dispatching them immediately.  SWUFlushExploitDeferredTriggers() replays
// them onto the EffectStack alongside the played card's When-Played trigger.
global $gExploitDeferTriggers, $gExploitDeferredBag;
$gExploitDeferTriggers = $gExploitDeferTriggers ?? false;
$gExploitDeferredBag   = $gExploitDeferredBag   ?? [];

// JTL defeat-replacement bag ("if this would be defeated, you may instead …"). A would-be-defeated
// unit with an available replacement is parked here (NOT discarded) and resolved at action end.
// Actions granted to a base by an attached Fortify upgrade, keyed by the UPGRADE's CardID:
//   $baseUpgradeAbilities[$upgradeCardID] = fn(int $player, int $upgradeIndex): void
// Reached through SWUBaseAction (see _SWUBaseActionProviders); the closure pays its own cost and owns
// its After Action, exactly like a $baseAbilities closure.
global $baseUpgradeAbilities;
$baseUpgradeAbilities = $baseUpgradeAbilities ?? [];

global $gDeferredReplacements, $gSec035DefeatSnapshot, $gAsh195DefeatSnapshot, $gCombatDefeatByMz;
// ⚠ $gDeferredReplacements is filled and drained WITHIN one request (park at defeat → flush at the end of
// the action / trigger drain). Nothing may read it after an interactive decision — the replacement's own
// rebuild data rides the CUSTOM decision Param instead (see _SWUEncodeReplacementSnapshot). The former
// `$gReplaceSnapshots` global was removed for exactly that reason.
$gDeferredReplacements = $gDeferredReplacements ?? [];
// SEC_035 Darth Sion — power-at-defeat snapshot (mzID → ['power','owner']). Captured in
// CollectWhenDefeatedTriggers while subcards (Experience) are still intact, read by the
// When Defeated closure after they've been stripped.
$gSec035DefeatSnapshot = $gSec035DefeatSnapshot ?? [];
// ASH_195 Helgait — power-at-defeat snapshot (mzID → power). Captured under the defeating player's frame
// (where the mzID resolves to Helgait) and read by the When Defeated closure, which runs under Helgait's
// controller's frame (where the same frame-relative mzID would resolve to a different unit).
$gAsh195DefeatSnapshot = $gAsh195DefeatSnapshot ?? [];
$gCombatDefeatByMz = $gCombatDefeatByMz ?? [];   // mzID → bool "defeated by combat damage" (ASH_028/191)

// Task 1.3 — play-from-hand orchestrator globals.
// $gPlayGrantedExploit: extra Exploit X granted to the card being played (e.g. by TWI_005).
// Rides across the EXPLOIT_RESOLVE request boundary; restored from the CUSTOM param.
global $gPlayGrantedExploit;
$gPlayGrantedExploit = $gPlayGrantedExploit ?? 0;

// Task 3.1 — resources-paid stamp.
// Records the number of real resources exhausted to pay for the card most recently played.
// Droids (prepaid) are excluded; ignoreCost plays record 0.
// Readable until the next play or the end-of-phase sweep (RegroupPhaseStart clears SWU_PAID_*).
global $gLastPlayResourcesPaid;
$gLastPlayResourcesPaid = $gLastPlayResourcesPaid ?? 0;

function AddTrigger($player, $triggerType, $cardID, $mzID, $extraParams = ''): void {
    global $gPendingTriggers;
    $gPendingTriggers[] = [
        'player'      => intval($player),
        'triggerType' => $triggerType,
        'cardID'      => $cardID,
        'mzID'        => $mzID,
        'extraParams' => $extraParams,
    ];
}

// FlushTriggerBag — original DQ path used by combat/WhenDefeated triggers (single-player, RESOLVE_TRIGGER).
function FlushTriggerBag($activePlayer): bool {
    global $gPendingTriggers, $gTriggerDepth;
    if (empty($gPendingTriggers)) return false;

    $mine   = array_values(array_filter($gPendingTriggers, fn($t) => $t['player'] === intval($activePlayer)));
    $theirs = array_values(array_filter($gPendingTriggers, fn($t) => $t['player'] !== intval($activePlayer)));

    foreach (array_merge($mine, $theirs) as $trigger) {
        DecisionQueueController::AddDecision(
            $trigger['player'],
            "CUSTOM",
            "RESOLVE_TRIGGER|{$trigger['triggerType']}|{$trigger['cardID']}|{$trigger['mzID']}",
            $gTriggerDepth
        );
    }

    $gPendingTriggers = [];
    return true;
}

// _SWUQueueOrchestration — queue a trigger-orchestration / combat-commit CUSTOM decision that must NEVER
// be skipped by a sticky "PASS". When a player DECLINES an optional ("you may") trigger via the Pass
// button (lastDecision = "PASS"), that PASS persists across the rest of the drain and ExecuteStaticMethods
// skips every following CUSTOM that isn't DontSkipOnPass. The trigger's *effect* (DEAL_UNIT_DAMAGE etc.)
// SHOULD be skipped (it self-guards on '-'/'PASS' anyway), but the orchestration that resumes trigger
// resolution / commits combat damage / finalizes the action must still run — else declining an On Attack
// "you may" fizzles the attack's combat damage AND leaves the turn un-swapped (a free extra action).
// dontSkipOnPass=1 is a no-op for any non-PASS lastDecision, so this only changes the broken PASS path.
function _SWUQueueOrchestration($player, string $param, int $block): void {
    // ONE bare resume per action. A BARE "SWU_TRIGGER_RESUME|{p}" finalises the action when the
    // EffectStack empties, so two of them finalise twice and swap the turn twice — with two seats
    // that lands back on the acting player, reading as a free extra action (bug #922). Two arise
    // when an attack NESTED in a play both flush triggers: the play's entry flush queues one
    // (ActivateCard -> CollectEntryTriggers), then the attack's after-attack flush queues another
    // (CollectCombatStep3Triggers -> CollectAfterAttackTriggers) because an attack-end trigger
    // fired. The pending resume already re-drives the stack until it empties, so the second is
    // redundant, not load-bearing — dropping it changes ordering not at all.
    //
    // Deliberately NOT applied to a resume carrying a continuation ("…|COMBAT|…"), which is state,
    // not just a terminal, and must always be queued. And this is a QUEUE-time guard on purpose:
    // suppressing at finalise time instead strands actions that legitimately have only one resume.
    if (preg_match('/^SWU_TRIGGER_RESUME\|\d+$/', $param)) {
        foreach (GetDecisionQueue($player) as $entry) {
            if (($entry->Param ?? '') === $param) return;   // already pending — it will finalise
        }
    }
    DecisionQueueController::AddDecision($player, "CUSTOM", $param, $block, '', 1);
}

// FlushEntryTriggerBag — EffectStack path for entry triggers (WhenPlayed, Shielded, Ambush).
// 0 triggers: returns 0.
// 1 trigger:  auto-dispatches via RESOLVE_NEXT_TRIGGER (no player choice). Returns 1.
// 2+ triggers, same player: populates EffectStack + queues MZCHOOSE for ordering. Returns 2.
// 2+ triggers, cross-player: populates EffectStack + queues YESNO for who resolves first. Returns 2.
function FlushEntryTriggerBag($activePlayer): int {
    global $gPendingTriggers, $gTriggerDepth;
    if (empty($gPendingTriggers)) return 0;

    $count = count($gPendingTriggers);

    // Build Params string (mzID + optional extraParams joined by |).
    $buildParams = fn($t) => $t['mzID'] . (($t['extraParams'] ?? '') !== '' ? '|' . $t['extraParams'] : '');

    if ($count === 1) {
        // Single trigger: add to EffectStack, auto-dispatch via RESOLVE_NEXT_TRIGGER.
        $t = $gPendingTriggers[0];
        $gPendingTriggers = [];
        $stack   = GetEffectStack();
        $stackIdx = count(array_filter($stack, fn($e) => empty($e->removed ?? false)));
        AddEffectStack(CardID:$t['cardID'], Controller:$t['player'], TriggerType:$t['triggerType'], Params:$buildParams($t));
        $mzID = "EffectStack-{$stackIdx}";
        _SWUQueueOrchestration($t['player'], "RESOLVE_NEXT_TRIGGER|{$mzID}", $gTriggerDepth);
        _SWUQueueOrchestration($t['player'], "SWU_TRIGGER_RESUME|{$activePlayer}", 20);
        return 1;
    }

    // 2+ triggers: populate EffectStack for all.
    $mine   = array_values(array_filter($gPendingTriggers, fn($t) => $t['player'] === intval($activePlayer)));
    $theirs = array_values(array_filter($gPendingTriggers, fn($t) => $t['player'] !== intval($activePlayer)));
    $gPendingTriggers = [];

    foreach (array_merge($mine, $theirs) as $t) {
        AddEffectStack(CardID:$t['cardID'], Controller:$t['player'], TriggerType:$t['triggerType'], Params:$buildParams($t));
    }

    _SWUQueueOrchestration(intval($activePlayer), "SWU_TRIGGER_RESUME|{$activePlayer}", 20);

    if (!empty($mine) && !empty($theirs)) {
        // Cross-player: active player picks who resolves first.
        DecisionQueueController::AddDecision(intval($activePlayer), "YESNO", "-", $gTriggerDepth,
            tooltip:"Resolve_Which_Player_First?");
        _SWUQueueOrchestration(intval($activePlayer),
            "SWU_TRIGGER_ORDER_CHOICE|{$activePlayer}", $gTriggerDepth);
    } else {
        // Single player has all triggers: go straight to MZCHOOSE.
        $choosingPlayer = !empty($mine) ? intval($activePlayer) : (intval($activePlayer) === 1 ? 2 : 1);
        $targetStr = _SWUEffectStackTargetsForPlayer($choosingPlayer);
        DecisionQueueController::AddDecision($choosingPlayer, "MZCHOOSE", $targetStr, $gTriggerDepth,
            tooltip:"Choose_trigger_to_resolve");
        _SWUQueueOrchestration($choosingPlayer,
            "RESOLVE_NEXT_TRIGGER|{$choosingPlayer}", $gTriggerDepth);
    }
    return 2;
}

// SWUFlushExploitDeferredTriggers — replays Exploit-deferred WhenDefeated / leave-play
// triggers onto the EffectStack in the same batch as the played card's WhenPlayed trigger.
// Called from ActivateCard's unit branch (Task 1.4) after the card's own entry triggers
// have been staged but before FlushEntryTriggerBag fires, so all triggers order together.
//
// Mechanism: mirrors FlushEntryTriggerBag — each descriptor in $gExploitDeferredBag is
// re-added to $gPendingTriggers via AddTrigger so that FlushEntryTriggerBag sees them
// together with the WhenPlayed trigger and handles ordering (1 trigger = auto-dispatch,
// 2+ = MZCHOOSE / YESNO).  After replay the bag is cleared and the flag reset.
function SWUFlushExploitDeferredTriggers(int $player): void {
    global $gExploitDeferTriggers, $gExploitDeferredBag;
    $gExploitDeferTriggers = false;
    if (empty($gExploitDeferredBag)) return;
    foreach ($gExploitDeferredBag as $entry) {
        $kind = $entry['__kind__'] ?? 'trigger';
        if ($kind === 'trigger') {
            AddTrigger($entry['player'], $entry['triggerType'], $entry['cardID'], $entry['mzID'], $entry['extraParams'] ?? '');
        } elseif ($kind === 'bounty') {
            // Replay bounty decisions at flush time, alongside the When-Played batch.
            DecisionQueueController::AddDecision($entry['activePlayer'], "YESNO", "-", 1, tooltip:"Collect_bounty?");
            DecisionQueueController::AddDecision($entry['activePlayer'], "CUSTOM", "SWUCollectBounty|{$entry['cardID']}", 1);
        }
    }
    $gExploitDeferredBag = [];
}

// ── General multi-clause "then" trigger deferral (CR 8.29.1 + 7.6.14.a / 7.6.8) ───────────────────────
// While an ability with a "then"/"if you do" clause is mid-resolution (e.g. Collateral Damage between its
// two "deal 2" hits), a triggered ability set up by an earlier clause (a first-hit When-Defeated, an
// opponent's disclose reaction, …) must WAIT to RESOLVE until the whole ability finishes — it may not jump
// ahead of the "then" clause, and both players' triggers then resolve active-player-first (CR 7.6.10).
// Unlike the Exploit defer (transient, same-action), a "then" event's clauses are separated by an
// INTERACTIVE choice, so this state is stored in SWUVars — it survives the HTTP request boundary between
// the clauses. CollectWhenDefeatedTriggers parks into SWU_DEFER_WD_BAG while SWU_DEFER_WD is set; the card
// flushes once its final clause resolves.
function SWUBeginDeferWhenDefeated(): void {
    SetSWUVar('SWU_DEFER_WD', 'true');
    if (GetSWUVar('SWU_DEFER_WD_BAG', '') === '') SetSWUVar('SWU_DEFER_WD_BAG', '[]');
}
function SWUFlushDeferredWhenDefeated(int $activePlayer): void {
    if (GetSWUVar('SWU_DEFER_WD', 'false') !== 'true') return;
    SetSWUVar('SWU_DEFER_WD', 'false');
    $bag = json_decode(GetSWUVar('SWU_DEFER_WD_BAG', '[]'), true);
    SetSWUVar('SWU_DEFER_WD_BAG', '[]');
    if (!is_array($bag) || empty($bag)) return;
    global $gPendingTriggers;
    $bounty = [];
    foreach ($bag as $entry) {
        if (($entry['__kind__'] ?? 'trigger') === 'bounty') { $bounty[] = $entry; continue; }
        AddTrigger($entry['player'], $entry['triggerType'], $entry['cardID'], $entry['mzID'], $entry['extraParams'] ?? '');
    }
    FlushTriggerBag($activePlayer);                    // When-Defeated (and friends), active-player-first
    foreach ($bounty as $entry) {                      // bounty is offered AFTER When-Defeated (CR 7.6.3 / 13.f)
        DecisionQueueController::AddDecision($entry['activePlayer'], "YESNO", "-", 1, tooltip:"Collect_bounty?");
        DecisionQueueController::AddDecision($entry['activePlayer'], "CUSTOM", "SWUCollectBounty|{$entry['cardID']}", 1);
    }
}

// FlushCombatTriggerBag — like FlushEntryTriggerBag but for combat Step 1 triggers.
// Instead of finalising via SWUAfterAction when the EffectStack empties, the queued
// SWU_TRIGGER_RESUME carries a COMBAT continuation that queues SWUCombatDamage.
// Returns the flush count (0 = no triggers; caller queues SWUCombatDamage directly).
// $contOverride: an alternative continuation string for callers whose commit step isn't the ordinary
// single-target SWUCombatDamage — TWI_135 Darth Maul's two-defender attack passes
// "MAULCOMBAT|{attacker}|{def1}|{def2}" so both defenders survive the round-trip.
function FlushCombatTriggerBag(int $activePlayer, string $attackerMzID, string $targetMzID, string $contOverride = ''): int {
    global $gPendingTriggers, $gTriggerDepth;
    if (empty($gPendingTriggers)) return 0;

    $count = count($gPendingTriggers);
    $attackerObj = GetZoneObject($attackerMzID);
    $attackerUID = $attackerObj !== null ? intval($attackerObj->UniqueID ?? 0) : 0;
    $cont  = $contOverride !== '' ? $contOverride : "COMBAT|{$attackerMzID}|{$targetMzID}|{$attackerUID}";

    $buildParams = fn($t) => $t['mzID'] . (($t['extraParams'] ?? '') !== '' ? '|' . $t['extraParams'] : '');

    if ($count === 1) {
        $t = $gPendingTriggers[0];
        $gPendingTriggers = [];
        $stack    = GetEffectStack();
        $stackIdx = count(array_filter($stack, fn($e) => empty($e->removed ?? false)));
        AddEffectStack(CardID:$t['cardID'], Controller:$t['player'], TriggerType:$t['triggerType'], Params:$buildParams($t));
        // Orchestration (resolve + resume) rides the ACTIVE player's queue so it drains in the attacker's
        // action — even when the lone trigger is the defender's On Defense ($t['player'] != activePlayer).
        // The effect still dispatches under the EffectStack entry's Controller in RESOLVE_NEXT_TRIGGER.
        _SWUQueueOrchestration(intval($activePlayer), "RESOLVE_NEXT_TRIGGER|EffectStack-{$stackIdx}", $gTriggerDepth);
        _SWUQueueOrchestration(intval($activePlayer), "SWU_TRIGGER_RESUME|{$activePlayer}|{$cont}", 20);
        return 1;
    }

    // 2+ triggers: populate EffectStack for all (active player's first).
    $mine   = array_values(array_filter($gPendingTriggers, fn($t) => $t['player'] === intval($activePlayer)));
    $theirs = array_values(array_filter($gPendingTriggers, fn($t) => $t['player'] !== intval($activePlayer)));
    $gPendingTriggers = [];

    foreach (array_merge($mine, $theirs) as $t) {
        AddEffectStack(CardID:$t['cardID'], Controller:$t['player'], TriggerType:$t['triggerType'], Params:$buildParams($t));
    }

    // The resume must ride the SAME queue as the ordering prompt below, so the prompt (low block) blocks
    // it (block 20). With every trigger belonging to the NON-active player the prompt goes on their queue;
    // leaving the resume on the active player's queue lets it fire before anything is chosen, and it then
    // queues a SECOND, duplicate ordering prompt — after which the chain stalls on the unanswered copy.
    // Unreachable until TWI_135 Darth Maul's two-defender attack made "2+ triggers, all theirs" possible
    // (a normal attack has one defender). Every other shape keeps the active player, exactly as before.
    $resumeOwner = (empty($mine) && !empty($theirs))
        ? (intval($activePlayer) === 1 ? 2 : 1)
        : intval($activePlayer);
    _SWUQueueOrchestration($resumeOwner, "SWU_TRIGGER_RESUME|{$activePlayer}|{$cont}", 20);

    if (!empty($mine) && !empty($theirs)) {
        DecisionQueueController::AddDecision(intval($activePlayer), "YESNO", "-", $gTriggerDepth,
            tooltip:"Resolve_Which_Player_First?");
        _SWUQueueOrchestration(intval($activePlayer),
            "SWU_TRIGGER_ORDER_CHOICE|{$activePlayer}", $gTriggerDepth);
    } else {
        $choosingPlayer = !empty($mine) ? intval($activePlayer) : (intval($activePlayer) === 1 ? 2 : 1);
        $targetStr = _SWUEffectStackTargetsForPlayer($choosingPlayer);
        DecisionQueueController::AddDecision($choosingPlayer, "MZCHOOSE", $targetStr, $gTriggerDepth,
            tooltip:"Choose_trigger_to_resolve");
        _SWUQueueOrchestration($choosingPlayer,
            "RESOLVE_NEXT_TRIGGER|{$choosingPlayer}", $gTriggerDepth);
    }

    return $count;
}

// Returns a &-delimited mzID string of non-removed EffectStack entries for the given player.
function _SWUEffectStackTargetsForPlayer($player): string {
    $stack = GetEffectStack();
    $mzIDs = [];
    foreach ($stack as $i => $e) {
        if (!empty($e->removed)) continue;
        if (intval($e->Controller) === intval($player)) $mzIDs[] = "EffectStack-{$i}";
    }
    return implode('&', $mzIDs);
}

// On* dispatchers — call the registered closure(s) for the given card. A card may register multiple
// When-Played windows under contiguous ":N" tokens (LOF_070 is the first: ":0" Heroism, ":1" Villainy);
// each fires in order as its own separate ability. Single-window cards register only ":0".
function OnWhenPlayed($player, $cardID, $mzID): void {
    global $whenPlayedAbilities;
    _SWURecordDamageSource(intval($player), $mzID); // TWI_016 — the played unit is the damage source for its own When Played
    $fired = false;
    for ($w = 0; isset($whenPlayedAbilities["{$cardID}:{$w}"]); $w++) {
        $whenPlayedAbilities["{$cardID}:{$w}"]($player, $mzID);
        $fired = true;
    }
    if ($fired) {
        // LOF_197 Qui-Gon Jinn's Aethersprite — "The next time you use a When Played ability this phase,
        // you may use that ability again." The flag is armed on its attack; the NEXT When-Played ability
        // consumes it and offers a repeat (re-dispatch the same ability on the same unit).
        if (GlobalEffectCount($player, 'SWU_LOF197_REPEAT') > 0) {
            RemoveGlobalEffect($player, 'SWU_LOF197_REPEAT');
            DecisionQueueController::AddDecision($player, "YESNO", "-", 1,
                tooltip: "Use_that_When_Played_ability_again_(Qui-Gon's_Aethersprite)?");
            DecisionQueueController::AddDecision($player, "CUSTOM", "LOF_197#0|{$cardID}|{$mzID}", 1);
        }
    }
}
$customDQHandlers["LOF_197#0"] = function($player, $parts, $lastDecision) {
    if ($lastDecision !== 'YES') return;
    global $playerID, $whenPlayedAbilities; $playerID = intval($player);
    $cardID = $parts[0] ?? ''; $mzID = $parts[1] ?? '';
    if ($cardID === '' || $mzID === '' || !isset($whenPlayedAbilities["{$cardID}:0"])) return;
    // Repeat ONLY the first When-Played window (":0"), NOT every ":N" window. Per CR each bullet is a separate
    // ability, and Aethersprite repeats the NEXT ability used (the first). A multi-window card (LOF_070 Anakin:
    // heroism-debuff :0 + villainy-debuff :1) must yield 3 resolutions (0,1,repeat-0), not 4.
    $whenPlayedAbilities["{$cardID}:0"](intval($player), $mzID);
    // Multi-ARM case (Aethersprite attacked N times → the arm flag stacked): this repeat is itself a "use" of
    // a When-Played ability, so it consumes ANOTHER arm and offers another repeat of the SAME first ability.
    if (GlobalEffectCount($player, 'SWU_LOF197_REPEAT') > 0) {
        RemoveGlobalEffect($player, 'SWU_LOF197_REPEAT');
        DecisionQueueController::AddDecision($player, "YESNO", "-", 1,
            tooltip: "Use_that_When_Played_ability_again_(Qui-Gon's_Aethersprite)?");
        DecisionQueueController::AddDecision($player, "CUSTOM", "LOF_197#0|{$cardID}|{$mzID}", 1);
    }
};
function OnWhenDefeated($player, $cardID, $mzID): void {
    global $whenDefeatedAbilities;
    _SWURecordDamageSource(intval($player), $mzID); // TWI_016 — the defeated unit is the source for its own When Defeated damage
    $key = $cardID . ':0';
    if (isset($whenDefeatedAbilities[$key])) $whenDefeatedAbilities[$key]($player, $mzID);
}
// OnAttackTrigger($player, $mzID) is defined in CombatLogic.php.

function OnDefenseTrigger($player, $cardID, $mzID): void {
    global $onDefenseAbilities;
    _SWURecordDamageSource(intval($player), $mzID); // TWI_016 — the defending unit is the source for its On Defense damage
    $key = $cardID . ':0';
    if (isset($onDefenseAbilities[$key])) {
        $onDefenseAbilities[$key]($player, $mzID);
        // Mark that THIS attack has an On Defense reaction pending on the defender's queue, so the combat
        // resume gates SWUCombatDamage behind it (combat-pause). Only true On Defense triggers set this —
        // On Attack opponent decisions (indirect damage, Watto) do NOT, so they keep their old timing.
        // Cleared at attack start and when combat commits. (If the closure queued nothing — e.g. no Force
        // for a may-use-Force On Defense — the resume's blocking-decision check is false, so no hop.)
        SetSWUVar('SWU_PENDING_DEF_REACTION', '1');
    }
}
function OnAttackEndTrigger($player, $cardID, $mzID): void {
    global $onAttackEndAbilities;
    _SWURecordDamageSource(intval($player), $mzID); // TWI_016 — the attacker is the source for its On Attack End damage
    $key = $cardID . ':0';
    if (isset($onAttackEndAbilities[$key])) $onAttackEndAbilities[$key]($player, $mzID);
}

// SOR_036 Gideon Hask reaction: give an Experience token to a friendly unit ($player = Gideon's
// controller). Mandatory; 1 friendly auto-resolves.
function GideonExpReaction($player): void {
    GiveTokenUpgrade($player, '', ['token'=>'EXPERIENCE','prompt'=>'Give_an_Experience_token_to_a_friendly_unit']);
}

// SOR_002 Iden Versio (deployed leader unit) reaction: "Heal 1 damage from your base." Mandatory,
// no target — heal the controller's own base.
function IdenHealReaction($player): void {
    OnHealBase(intval($player), intval($player), 1);
}

// SOR_105 General Krell granted reaction: the controller of the defeated unit MAY draw a card.
function KrellDrawReaction($player): void {
    DecisionQueueController::AddDecision(intval($player), 'YESNO', '-', 1, 'Draw_a_card?');
    DecisionQueueController::AddDecision(intval($player), 'CUSTOM', 'KRELL_DRAW', 1);
}

// SOR_015 Boba Fett (undeployed leader) reaction: auto-resolve (always-yes) — exhaust the leader
// to ready a resource, but only when it readies something (collect-time already gated on an
// exhausted resource existing; re-checked here for safety). If nothing readies, the leader is NOT
// exhausted (no benefit → skip the cost).
function BobaLeftPlayReaction($player): void {
    global $playerID;
    $playerID = intval($player);
    if (!_SWULeaderReadyUndeployed(intval($player), 'SOR_015')) return;
    if (SWUReadyResources(intval($player), 1) <= 0) return; // resources full → skip the cost
    foreach (GetLeader(intval($player)) as &$l) {
        if (!empty($l->removed)) continue;
        if (($l->CardID ?? '') === 'SOR_015') { $l->Ready = false; break; }
    }
    unset($l);
}

// ── Combat-hit triggers (Phase 7.2): WhenDealsCombatDamage / WhenDefeats ──────
// SOR_085 Rukh — "deals combat damage to a non-leader unit while attacking: defeat that unit."
// $mzID = the defender. No-op if it was already defeated by the combat.
function RukhDefeatTrigger($player, $mzID): void {
    global $playerID;
    $playerID = intval($player);
    $obj = GetZoneObject($mzID);
    if (SWUObjGone($obj) || IsLeaderUnit($obj)) return;
    SWUDefeatUnit(intval($player), $mzID);
}

// SOR_150 Heroic Sacrifice — granted self-defeat: defeat the attacker ($mzID) after it dealt combat
// damage. Unlike Rukh, this defeats the source unit itself (a deployed leader returns to its zone).
function HeroicSacrificeDefeatTrigger($player, $mzID): void {
    global $playerID;
    $playerID = intval($player);
    $obj = GetZoneObject($mzID);
    if (SWUObjGone($obj)) return;
    $wasLuthenHimself = (($obj->CardID ?? '') === 'SEC_013');
    SWUDefeatUnit(intval($player), $mzID);
    // SEC_013 Luthen Rael — "When a friendly unit is defeated while attacking." This EFFECT-driven
    // self-defeat (SOR_150 Heroic Sacrifice / LAW_205 / LAW_062) happens while the unit is the attacker, so
    // it must fire Luthen too — the combat-counter-death path fires it in ExecuteSWUAttack. If Luthen HIMSELF
    // is the self-defeated attacker he has already returned to the leader zone (undeployed), so force the
    // deployed-self branch.
    if ($wasLuthenHimself) {
        AddTrigger(intval($player), 'SEC_013', 'SEC_013', 'DEPLOYED_SELF');
    } elseif (_SWULeaderReadyUndeployed(intval($player), 'SEC_013') || _SWULeaderDeployed(intval($player), 'SEC_013')) {
        AddTrigger(intval($player), 'SEC_013', 'SEC_013', '');
    }
}

// ASH_102 Ravager — "When you play a unit: you may have it deal damage equal to its power to a unit in
// the same arena." $playedUID = the just-played unit (the dealer). Targets are units in the dealer's arena.
function RavagerReaction($player, int $playedUID): void {
    global $playerID; $playerID = intval($player);
    if ($playedUID <= 0) return;
    $dealerMz = SWUFindMzByUID($playedUID);
    if ($dealerMz === null) return;
    $dealer = GetZoneObject($dealerMz);
    if (SWUObjGone($dealer)) return;
    if (intval(ObjectCurrentPower($dealer)) <= 0) return;   // a 0-power unit would "deal 0" → no valid effect, no prompt
    $arena = strpos($dealerMz, 'SpaceArena') !== false ? 'SpaceArena' : 'GroundArena';
    $targets = [];
    foreach (["my{$arena}", "their{$arena}"] as $z) {
        foreach (ZoneSearch($z, AnyUnitFilter) as $mz) {
            $o = GetZoneObject($mz);
            if ($o !== null && empty($o->removed) && intval($o->UniqueID ?? 0) !== $playedUID) $targets[] = $mz;
        }
    }
    if (empty($targets)) return;
    SWUQueueMayChooseTarget(intval($player), $targets, "Have_the_played_unit_deal_its_power_to_a_unit?", "Choose_a_unit_in_the_same_arena", "ASH_102#0|{$playedUID}");
}

// ASH_060 Cobb Vanth — "When you play another unit: you may deal 2 damage to this unit. If you do, give
// a Shield token to that unit." $spec = "{cobbUID},{playedUID}". Offered via YESNO.
function CobbVanthReaction($player, string $spec): void {
    global $playerID; $playerID = intval($player);
    $parts = explode(',', $spec);
    $cobbUID = intval($parts[0] ?? 0);
    $playedUID = intval($parts[1] ?? 0);
    if ($cobbUID <= 0 || $playedUID <= 0) return;
    if (SWUFindMzByUID($cobbUID) === null) return;   // Cobb left play
    DecisionQueueController::AddDecision(intval($player), "YESNO", "-", 1, tooltip: "Deal_2_to_Cobb_Vanth_to_Shield_the_played_unit?");
    DecisionQueueController::AddDecision(intval($player), "CUSTOM", "ASH_060#0|{$cobbUID}|{$playedUID}", 1);
}

// ASH_184 Follow Me — "After completing the attack, give 3 Advantage tokens to a unit." Dispatched off
// the EffectStack (so $playerID stays set for the relative-mzID choose). Mandatory; any unit is a target.
function Ash184GiveAdvTrigger($player): void {
    SWUOfferUnitTarget($player, '', [
        'continuation' => 'GIVE_ADVANTAGE', 'amount' => 3,
        'prompt' => "Give_3_Advantage_tokens_to_a_unit",
    ]);
}

// SOR_115 Agent Kallus — "When another unique unit is defeated: you may draw a card." The
// once-per-round gate was consumed at collect time, so this just offers the optional draw.
function KallusDrawTrigger($player): void {
    global $playerID;
    $playerID = intval($player);
