// LAW_034 Chewbacca — When Attack Ends (defender defeated): give this unit an Experience token and heal
// 3 damage from him.
function Law034Trigger($player, $mzID): void {
    global $playerID; $playerID = intval($player);
    $o = GetZoneObject($mzID);
    if (SWUObjGone($o)) return;
    DoGiveExperienceToken(intval($player), $mzID);
    OnHealUnit(intval($player), $mzID, 3);
}

// LAW_046 Chirrut Îmwe — When Attack Ends (dealt combat damage to a base): you may heal 4 from another unit.
function Law046Trigger($player, $mzID): void {
    $self = GetZoneObject($mzID);
    $uid  = SWUObjUID($self, 0);
    SWUOfferUnitTarget($player, '', ['continuation'=>'HEAL_TARGET','amount'=>4,'may'=>true,'excludeUID'=>$uid,
        'extraFilter'=>fn($o)=>intval($o->Damage ?? 0) > 0,
        'question'=>"Heal_4_from_another_unit?",'prompt'=>"Choose_a_unit"]);
}

function SEC156DefeatTrigger($player): void {
    global $playerID; $playerID = intval($player);
    $rebels = 0;
    foreach (array_merge(ZoneSearch('myGroundArena', AnyUnitFilter), ZoneSearch('mySpaceArena', AnyUnitFilter)) as $mz) {
        $o = GetZoneObject($mz);
        if ($o !== null && empty($o->removed) && TraitContains($o, 'Rebel')) $rebels++;
    }
    if ($rebels <= 0) return;
    SWUDealDamageToBase($rebels, OtherPlayer(intval($player)));  // 2-player: the one enemy base
}

function JTL073DefeatTrigger($player): void {
    SWUOfferUnitTarget($player, '', ['continuation'=>'EXHAUST_UNIT','may'=>true,
        'question'=>"Exhaust_a_unit",'prompt'=>"Choose_a_unit_to_exhaust"]);
}

function DispatchTrigger($player, $triggerType, $cardID, $mzID, $extra = []): void {
    global $playerID;
    $savedPID = $playerID;
    $playerID = intval($player);
    _SWURecordDamageSource(intval($player), $mzID); // TWI_016 — a reactive trigger's source unit ($mzID, when set) deals its damage
    switch ($triggerType) {
        case 'WhenPlayed':          OnWhenPlayed($player, $cardID, $mzID);          break;
        // HMW_048 — a GAINED When Played: the donor's closure runs with HER mzID ("this unit" = her),
        // through OnWhenPlayed so the LOF_197 repeat-arm sees it as a real When Played use.
        case 'HMW048Gain':          OnWhenPlayed($player, $cardID, $mzID);          break;
        case 'WhenPlayedAsUpgrade': OnWhenPlayedAsUpgrade($player, $cardID, $mzID); break;
        case 'OnAttached':          OnOnAttached($player, $cardID, $mzID);          break;
        case 'WhenDefeated':
            OnWhenDefeated($player, $cardID, $mzID);
            SWUCollectThrawnReuse($player, $cardID, $mzID); // JTL_002 Thrawn "when you use a When Defeated ability"
            break;
        case 'HMW_062':   Hmw062WeakenedDefeatTrigger($player);          break;
        case 'JTL_169':   ShadowCasterReuseTrigger($player, $cardID, $mzID); break;
        // JTL_169 Shadow Caster reuse of a GRANTED When-Defeated: $cardID = the granting card's ID (the
        // granted trigger type), $mzID = the param the original granted dispatch carried. Offer to reuse it.
        case 'JTL_169G':  ShadowCasterReuseTrigger($player, $cardID, $mzID, $cardID); break;
        case 'OnAttack':
            OnAttackTrigger($player, $mzID);
            SWUCollectEnfysReuse($player, $cardID, $mzID); // LAW_014 Enfys Nest "when you use an On Attack ability"
            break;
        case 'JTL_156': JTL156AttackTrigger($player, $mzID);         break;
        case 'LOF_205': LOF205BounceTrigger($player, $mzID);         break; // $mzID = the defender
        // LOF common Force bases — "When a friendly Force unit attacks: The Force is with you."
        case 'LOF_020': case 'LOF_021': case 'LOF_023': case 'LOF_024':
        case 'LOF_026': case 'LOF_027': case 'LOF_029': case 'LOF_030':
            TheForceIsWithYou($player); break;
        case 'LOF_087': EighthBrotherReaction($player); break; // "When you play another unit": may use the Force → +2/+2
        case 'HMW_171': Hmw171TrapFieldReaction($player, intval($mzID), max(1, intval($extra[0] ?? 1))); break; // Trap Field — non-leader ground unit entered: may defeat this upgrade → deal 3
        case 'HMW_206': { // The Tarkin Doctrine base-grant — "When you play a Fortification upgrade: Exhaust an enemy unit."
            global $playerID; $playerID = intval($player);
            $enemies = array_merge(
                ZoneSearch("theirGroundArena", AnyUnitFilter),
                ZoneSearch("theirSpaceArena",  AnyUnitFilter)
            );
            if (!empty($enemies)) SWUQueueChooseTarget(intval($player), $enemies, "Exhaust_an_enemy_unit", "EXHAUST_UNIT");
            break;
        }
        case 'TWI_080': Twi080Reaction($player, intval($extra[0] ?? 0)); break; // may exhaust self → create Battle Droid
        case 'TWI_018':  Twi018Reaction($player, intval($extra[0] ?? 0), true);  break; // front: exhaust leader → deal 1 to =cost
        case 'TWI_018D': Twi018Reaction($player, intval($extra[0] ?? 0), false); break; // deployed: deal 1 to ≤cost
        case 'TWI_101': Twi101Reaction($player, intval($extra[0] ?? 0)); break; // may exhaust self → search top 4 for a unit
        case 'TWI_216': Twi216Reaction($player, intval($extra[0] ?? 0)); break; // may recycle a Clone from discard → draw
        case 'LOF_229': KyloRenUpgradeReaction($player); break; // "When you play an upgrade on this unit": may use the Force → draw
        case 'ASH_047': Ash047UpgradeReaction($player); break;  // "When you play an upgrade on this unit": may create a Mandalorian token (once/round)
        case 'SHD_067': {                                       // Fenn Rau — give an enemy unit -2/-2 this phase
            SWUOfferUnitTarget($player, '', ['continuation'=>'APPLY_PHASE_DEBUFF|2|2|SHD_067', 'side'=>'their', 'prompt'=>"Give_an_enemy_unit_-2/-2_this_phase"]);
            break;
        }
        case 'SHD_133': {  // Dengar — "you may deal 1 damage to that (just-upgraded) unit"; $mzID slot = host UID
            global $playerID; $playerID = intval($player);
            $hostMz = SWUFindMzByUID(intval($mzID));
            if ($hostMz === null) break;
            $o = GetZoneObject($hostMz);
            if (SWUObjGone($o)) break;
            DecisionQueueController::AddDecision($player, 'YESNO', '-', 1, tooltip: "Deal_1_damage_to_that_unit?");
            DecisionQueueController::AddDecision($player, 'CUSTOM', "SHD_133#0|" . intval($mzID), 1);
            break;
        }
        // JTL_002 Thrawn bug fix (test-migration session): these granted-When-Defeated sources were
        // missing the SWUCollectThrawnReuse hook that every other granted-WD case already has (JTL_073,
        // SHD_104, TS26_52/035, SEC_039/156, LAW_141/201) — Thrawn silently could not re-use a WD ability
        // granted by an upgrade/another-unit/event. Added for consistency with the established convention.
        case 'ASH_063': SWUCreateUnitToken($player, 'ASH_T01'); SWUCollectThrawnReuse($player, $cardID, $mzID, $cardID); break; // Bo-Katan's Gauntlet — granted "When Defeated: create a Mandalorian token"
        case 'ASH_134': SWUCreateUnitToken($player, 'ASH_T01'); SWUCollectThrawnReuse($player, $cardID, $mzID, $cardID); break; // Warrior's Legacy (upgrade) — granted "When Defeated: create a Mandalorian token"
        case 'TWI_218': SWUCreateUnitToken($player, 'TWI_T01'); SWUCollectThrawnReuse($player, $cardID, $mzID, $cardID); break; // Droid Cohort (upgrade) — granted "When Defeated: create a Battle Droid token"
        case 'TWI_169': SWUCreateUnitToken($player, 'TWI_T02'); SWUCollectThrawnReuse($player, $cardID, $mzID, $cardID); break; // Clone Cohort (upgrade) — granted "When Defeated: create a Clone Trooper token"
        case 'TWI_129': SWUCreateUnitToken($player, 'TWI_T02'); SWUCollectThrawnReuse($player, $cardID, $mzID, $cardID); break; // In Defense of Kamino — granted "When Defeated: create a Clone Trooper token"
        case 'TWI_103': { // Pyrrhic Assault (phase grant) — "When Defeated: Deal 2 damage to an enemy unit."
            SWUOfferUnitTarget($player, '', ['continuation'=>'DEAL_UNIT_DAMAGE','amount'=>2,'side'=>'their','prompt'=>"Deal_2_damage_to_an_enemy_unit"]);
            break;
        }
        case 'LOF_249': LukeSkywalkerReaction($player, intval($extra[0] ?? 0)); break; // "another unique unit": may use the Force → Exp+Shield
        case 'ASH_060': CobbVanthReaction($player, (string)($extra[0] ?? '')); break;  // play another unit → may deal 2 to self + Shield the played unit
        case 'ASH_102': RavagerReaction($player, intval($extra[0] ?? 0)); break;       // play a unit → may have it deal its power to a unit in the same arena
        case 'LOF_166': LOF166BaseReaction($player, $mzID); break; // deals combat damage to a base → may give Exp to self
        case 'JTL_202': JTL202UpgradeTrigger($player, $mzID);       break;
        case 'JTL_223':  JTL223AttachTrigger($player);              break;
        case 'JTL_191':  JTL191DeployTrigger($player);              break;
        case 'JTL_120':  JTL120DefeatTrigger($player, $mzID);        break;
        // Upgrade-GRANTED When-Defeated abilities — the unit gained them, so JTL_002 Thrawn re-uses
        // them too (SWUCollectThrawnReuse with the granted trigger type).
        case 'JTL_073':  JTL073DefeatTrigger($player); SWUCollectThrawnReuse($player, $cardID, $mzID, $cardID); break;
        case 'SHD_104': {  // Inspiring Mentor (granted When Defeated) — give an Experience token to another friendly unit
            GiveTokenUpgrade($player, '', ['token'=>'EXPERIENCE','prompt'=>"Give_an_Experience_token_to_another_friendly_unit"]);
            SWUCollectThrawnReuse($player, $cardID, $mzID, $cardID);
            break;
        }
        case 'TS26_52': {  // Sith Traditions (granted When Defeated) — give an Experience token to a friendly unit
            GiveTokenUpgrade($player, '', ['token'=>'EXPERIENCE','prompt'=>"Give_an_Experience_token_to_a_friendly_unit"]);
            SWUCollectThrawnReuse($player, $cardID, $mzID, $cardID);
            break;
        }
        case 'TS26_35':  _SWUTs26035Offer($player); SWUCollectThrawnReuse($player, $cardID, $mzID, $cardID); break; // Ahsoka's Lightsabers (granted When Defeated) — may Shield an enemy → next event -2
        case 'HMW_115': { // Leia Organa — "Heal 1 damage from your base." Not optional, no target choice.
            OnHealBase(intval($player), intval($player), 1);
            break;
        }
        // Luminara Unduli — "You may attack with a unit. It gets +2/+0 for this attack."
        case 'HMW_124': LuminaraUnduliAttackOffer(intval($player)); break;
        case 'HMW_014': { // Wicket (leader FRONT) — "you may exhaust this leader. If you do, draw a card."
            global $playerID; $playerID = intval($player);
            DecisionQueueController::AddDecision(intval($player), "YESNO", "-", 1,
                tooltip: "Exhaust_Wicket_to_draw_a_card?");
            DecisionQueueController::AddDecision(intval($player), "CUSTOM", "HMW_014#0", 1);
            break;
        }
        case 'TS26_78': { // Barriss Offee — "When an enemy unit attacks: you may give an Experience token to that unit."
            global $playerID; $playerID = intval($player);
            $atkMz = SWUFindMzByUID(intval($mzID));   // mzID slot carries the attacker's UniqueID
            if ($atkMz !== null) {
                SWUQueueMayChooseTarget(intval($player), [$atkMz], "Give_an_Experience_token_to_the_attacking_unit?", "Choose_the_attacking_unit", "GIVE_EXPERIENCE|1");
                SetSWUVar('SWU_PENDING_DEF_REACTION', '1');   // pause combat so it resolves before damage
            }
            break;
        }
        case 'TS26_73': { // Moralo Eval — "When your base is dealt combat damage: you may deal 1 damage to a unit."
            global $playerID; $playerID = intval($player);
            $tg = array_merge(
                ZoneSearch("myGroundArena", AnyUnitFilter), ZoneSearch("mySpaceArena", AnyUnitFilter),
                ZoneSearch("theirGroundArena", AnyUnitFilter), ZoneSearch("theirSpaceArena", AnyUnitFilter)
            );
            if (!empty($tg)) {
                SWUOfferUnitTarget($player, '', ['continuation'=>'DEAL_UNIT_DAMAGE','amount'=>1,'may'=>true,
                    'question'=>"Deal_1_damage_to_a_unit?",'prompt'=>"Deal_1_damage_to_a_unit"]);
                SetSWUVar('SWU_PENDING_DEF_REACTION', '1');   // pause combat so it drains cross-player
            }
            break;
        }
        case 'SEC_039':  SEC039DefeatTrigger($player); SWUCollectThrawnReuse($player, $cardID, $mzID, $cardID); break;
        case 'SEC_156':  SEC156DefeatTrigger($player); SWUCollectThrawnReuse($player, $cardID, $mzID, $cardID); break;
        case 'OnAttackFromUpgrade':
            OnAttackFromUpgradeTrigger($player, $cardID, $mzID);
            SWUCollectEnfysReuse($player, $cardID, $mzID, true); // LAW_014 — upgrade-granted On Attack counts too
            break;
        case 'OnAttackEndFromUpgrade': OnAttackEndFromUpgradeTrigger($player, $cardID, $mzID); break;
        case 'OnAttackedFromUpgrade': OnAttackedFromUpgradeTrigger($player, $cardID, $mzID); break;
        case 'OnDefenseFromUpgrade': OnDefenseFromUpgradeTrigger($player, $cardID, $mzID); break;
        case 'SEC_101_PREVENT': SEC101PreventTrigger($player, $mzID); break;
        case 'ASH_062_PREVENT': Ash062PreventTrigger($player, $mzID); break;
        case 'OnDefense':    OnDefenseTrigger($player, $cardID, $mzID);   break;
        case 'OnAttackEnd':  OnAttackEndTrigger($player, $cardID, $mzID); break;
        case 'SOR_036':    GideonExpReaction($player);    break;
        case 'SEC_051':    GideonExpReaction($player);    break;   // Bo-Katan — same "Exp to a friendly" reaction
        case 'SOR_002':     IdenHealReaction($player);     break;
        case 'SOR_105':    KrellDrawReaction($player);    SWUCollectThrawnReuse($player, $cardID, $mzID, $cardID);    break; // General Krell — granted "When Defeated: you may draw a card" (JTL_002 Thrawn reuse fix, see comment above)
        case 'SOR_015': BobaLeftPlayReaction($player); break;
        case 'SOR_085':        RukhDefeatTrigger($player, $mzID);              break;
        case 'ASH_101':        RukhDefeatTrigger($player, $mzID);              break;   // The Great Mothers — defeat the combat-damaged non-leader defender
        case 'SOR_150': HeroicSacrificeDefeatTrigger($player, $mzID); break;
        case 'LAW_205': HeroicSacrificeDefeatTrigger($player, $mzID); break;   // Flash the Vents self-defeat
        case 'ASH_184': Ash184GiveAdvTrigger($player); break;   // Follow Me — give 3 Advantage tokens to a unit
        case 'LAW_033': Law033Trigger($player, $mzID); break;   // Hound's Tooth — may defeat a lower-power unit
        case 'LAW_034': Law034Trigger($player, $mzID); break;   // Chewbacca — Exp + heal 3 self
        case 'LAW_054': Law054Trigger($player, $mzID); break;   // Maul — may take control of a non-leader unit
        case 'LAW_088': Law088Trigger($player, $mzID); break;   // Anakin — may return the attacker + heal 2
        case 'LAW_119': Law119Trigger($player); break;          // Rogue One — scry top 2
        case 'LAW_176': Law176Trigger($player, $mzID); break;   // Sebulba's Podracer — may ready on deck-discard
        case 'LAW_141': Law141Trigger($player, $mzID); SWUCollectThrawnReuse($player, $cardID, $mzID, $cardID); break;   // Targeted For Removal — opp creates Credits = host cost (granted WD; Thrawn-reusable)
        case 'LAW_201': Law201Trigger($player, $mzID); SWUCollectThrawnReuse($player, $cardID, $mzID, $cardID); break;   // Thermal Detonator — if host was ready, 2 to each enemy ground unit (granted WD; Thrawn-reusable)
        case 'LAW_007': Law007Trigger($player); break;          // Boba Fett (leader form) — may exhaust → Credit
        case 'IC27_146': Ic27146ReadyResourcesTrigger($player); break;   // Boba Fett — may ready 2 resources
        case 'LAW_046': Law046Trigger($player, $mzID); break;   // Chirrut — may heal 4 from another unit
        case 'ASH_005': Ash005Trigger($player, $mzID); break;   // Luke (undeployed) — may exhaust → heal 1 from the attacker
        case 'ASH_005#1': Ash005DeployedTrigger($player, $mzID); break;   // Luke (deployed) — heal 2 from the attacker or your base
        case 'ASH_128': { $pp128 = explode(',', $mzID, 2); Ash128Trigger($player, intval($pp128[0] ?? 0), strval($pp128[1] ?? '')); break; }   // Bothan-5 — may capture defeated friendly from discard
        case 'ASH_013': Ash013Trigger($player, $mzID); break;   // Ezra — may exhaust → Advantage to a different unit
        case 'ASH_013#1': Ash013DeployedTrigger($player, $mzID); break;   // Ezra (deployed) — may give Advantage to a different unit (no exhaust)
        case 'ASH_016': Ash016Trigger($player, $mzID, intval($extra[0] ?? 0)); break;   // Shin — may exhaust → exhaust a cheaper unit
        case 'ASH_016#1': Ash016DeployedTrigger($player, $mzID, intval($extra[0] ?? 0)); break;   // Shin (deployed) — may exhaust a cheaper unit, once/round (no self-exhaust)
        case 'ASH_017': Ash017Trigger($player, intval($extra[0] ?? 0)); break;          // Greef — may exhaust → Advantage to the played/created unit
        case 'ASH_017#1': Ash017DeployedTrigger($player, intval($extra[0] ?? 0)); break; // Greef (deployed) — auto Advantage to the played/created unit
        case 'ASH_018': Ash018Trigger($player); break;                                  // Grogu — may deploy on a uq-4+ play
        case 'SHD_008': Shd008FrontReaction($player); break;                            // Boba Fett (front) — may exhaust → give a friendly unit +1/+0
        case 'SHD_014': Shd014FrontReaction($player); break;                            // Cad Bane (front) — may exhaust → opponent's own unit takes 1
        case 'SHD_005': Shd005FrontReaction($player); break;                            // Hondo (front) — may exhaust → give a unit an Experience token
        case 'SHD_018':  Shd018Reaction($player, intval($extra[0] ?? 4), true);  break; // Mandalorian (front) — may exhaust leader → exhaust enemy ≤4HP
        case 'SHD_018D': Shd018Reaction($player, intval($extra[0] ?? 6), false); break; // Mandalorian (deployed) — may exhaust enemy ≤6HP
        case 'SOR_149':         MaceReadyTrigger($player, $mzID);              break;
        case 'SEC_209':         SEC209CaptureTrigger($player, $mzID);          break;
        case 'SEC_088':         SEC088MayDrawTrigger($player, $mzID);          break;
        case 'SEC_147':         SEC147EachDiscardTrigger($player, $mzID);      break;
        case 'SEC_150':         SEC150SacTrigger($player, $mzID);              break;
        case 'SEC_205':         SEC205MillTrigger($player, $mzID);            break;
        case 'SEC_013':         SEC013AttackerDefeatedTrigger($player, $mzID);  break;
        case 'SEC_017':         SEC017DeployBaseHitTrigger($player);           break;
        case 'SEC_017#1':       SEC017LeaderBaseHitTrigger($player);           break;
        case 'LOF_017':         RevanExpTrigger($player, $mzID);               break;
        case 'LOF_017D':        RevanExpTriggerDeployed($player, $mzID);       break;
        case 'SOR_133': SeventhSisterBaseTrigger($player);            break;
        case 'SOR_088':    BlizzardExcessTrigger($player, intval($extra[0] ?? 0)); break;
        case 'SHD_138':    DoDrawCard($player, 1); break;   // Jango Fett — attacks and defeats a unit: draw a card
        case 'SHD_122':    Shd122ResourceStealTrigger($player, $mzID); break;   // Arquitens — defeated unit becomes your resource
        case 'SHD_147':    // Ketsu Onyo — deals combat damage to a base: may defeat an upgrade costing 2 or less
            SWUQueueDefeatUpgrade(intval($player), "Defeat_an_upgrade_costing_2_or_less", may: true, max: 1, filter: 'cost<=2', min: 0);
            break;
        case 'ASH_137':    Ash137ExcessTrigger($player, $mzID, intval($extra[0] ?? 0)); break;   // Wipe Them Out — excess to another unit in the arena
        case 'SOR_115':        KallusDrawTrigger($player);                   break;
        case 'SOR_013':       CassianDrawTrigger($player);                  break;
        case 'TWI_210': CunningOpponentPlayedReaction($player); break;
        case 'TWI_064': KiAdiMundiDrawReaction($player); break;   // Ki-Adi-Mundi — opponent's 2nd card → may draw 2
        case 'TWI_184': DecisionQueueController::AddDecision($player, 'CUSTOM', 'TWI_184#0|' . (string)$mzID, 1); break; // played-unit cost rides in $mzID
        case 'SHD_172': Shd172Reaction($player, (string)$mzID); break;   // Krayt Dragon — $mzID carries "cost~count"
        case 'SHD_239': {  // Toro Calican — "may deal 1 to the played BH unit; if you do, ready Toro"; $mzID = "playedUID,toroUID"
            global $playerID; $playerID = intval($player);
            $pp = explode(',', (string)$mzID, 2);
            $playedMz = SWUFindMzByUID(intval($pp[0] ?? 0));
            $toroUID  = intval($pp[1] ?? 0);
            if ($playedMz === null) break;
            $o = GetZoneObject($playedMz);
            if (SWUObjGone($o)) break;
            DecisionQueueController::AddDecision($player, 'YESNO', '-', 1, tooltip: "Deal_1_damage_to_it_to_ready_Toro_Calican?");
            DecisionQueueController::AddDecision($player, 'CUSTOM', "SHD_239#0|" . intval($pp[0] ?? 0) . "|" . $toroUID, 1);
            break;
        }
        case 'SHD_255': {  // Lady Proxima — "may deal 1 damage to a base"
            global $playerID; $playerID = intval($player);
            SWUQueueMayChooseTarget($player, ['myBase-0', 'theirBase-0'], "Deal_1_damage_to_a_base?", "Choose_a_base", "DEAL_TARGET|1");
            break;
        }
        case 'SHD_163': {  // Migs Mayfeld — "may deal 2 to a unit or base" (once/round; consumed on use)
            global $playerID; $playerID = intval($player);
            if (GlobalEffectCount($player, 'SWU_SHD163_USED') > 0) break;  // multi-card discard: only the first reacts
            $targets = _SWUAllUnitsAndBases(intval($player));
            if (empty($targets)) break;
            SWUQueueMayChooseTarget($player, $targets, "Deal_2_damage_to_a_unit_or_base?", "Choose_a_target", "SHD_163#0");
            break;
        }
        case 'SHD_217': {  // Tobias Beckett — "may exhaust a unit costing ≤ the non-unit card you played"; $mzID = cost
            global $playerID; $playerID = intval($player);
            $cost = intval($mzID);
            $targets = [];
            foreach (['myGroundArena', 'mySpaceArena', 'theirGroundArena', 'theirSpaceArena'] as $z) {
                foreach (ZoneSearch($z, AnyUnitFilter) as $mz) {
                    $o = GetZoneObject($mz);
                    if ($o !== null && empty($o->removed) && intval($o->Status ?? 0) === 1
                        && intval(CardCost($o->CardID ?? '')) <= $cost) $targets[] = $mz;
                }
            }
            if (empty($targets)) break;   // no valid target → don't consume the once/round
            SWUQueueMayChooseTarget($player, $targets, "Exhaust_a_unit_costing_{$cost}_or_less?", "Choose_a_unit", "SHD_217#0");
            break;
        }
        case 'SOR_182':        BosskPlayEventReaction($player);        break;
        case 'SOR_143':     FFFPlayAggressionReaction($player);     break;
        case 'SOR_109':           YularenHealReaction($player);           break;
        case 'Shielded':
            DoGiveShieldToken($player, $mzID);
            break;
        case 'Ambush':
            // Re-compute valid targets at dispatch time (units may have died between collect and dispatch).
            $ambushObj = GetZoneObject($mzID);
            // The Ambush unit may have changed arenas since collect — e.g. JTL_096 Blue Leader whose
            // When-Played ("pay 2 → move to the ground arena") was ordered to resolve FIRST. That move
            // gives the unit a new mzID and marks the cached (space) slot removed, so GetZoneObject($mzID)
            // returns null and Ambush would silently fizzle. Re-resolve by the unit's UID (carried in
            // $extra[0]), mirroring FlushCombatTriggerBag's attacker-UID re-resolution.
            if (SWUObjGone($ambushObj)) {
                $ambushUID = intval($extra[0] ?? 0);
                if ($ambushUID > 0) {
                    $reMz = SWUFindMzByUID($ambushUID);
                    if ($reMz !== null) { $mzID = $reMz; $ambushObj = GetZoneObject($mzID); }
                }
            }
            if (SWUObjGone($ambushObj)) break;
            $ambushArena    = $ambushObj->Location ?? 'GroundArena';
            $validTargets   = SWUGetAllValidAmbushTargets($player, $ambushObj, $ambushArena); // union all opponents
            if (empty($validTargets)) break;
            $targetStr = implode('&', $validTargets);
            DecisionQueueController::AddDecision($player, "YESNO", "-", 1, tooltip:"Ambush_attack?");
            DecisionQueueController::AddDecision($player, "CUSTOM", "SWUAmbushAnswer|{$mzID}|{$targetStr}", 1);
            break;
        case 'Support':
            // Re-compute eligible attackers at dispatch time (board may have changed since collect).
            // One combined "may choose" popup (pick an attacker OR decline) — mirrors IBH_064's
            // "may attack with another unit" so the interactive choice resolves cleanly inside the
            // entry-trigger resume (a YESNO + separate MZCHOOSE chain misorders here).
            $supObj = GetZoneObject($mzID);
            if (SWUObjGone($supObj)) break;
            $supAttackers = SWUGetValidSupportAttackers($player, $supObj);
            if (empty($supAttackers)) break;
            SWUQueueMayChooseTarget($player, $supAttackers, "Support__attack_with_another_unit?",
                "Choose_a_unit_to_attack_with", "SWUSupportChooseAttacker|{$mzID}");
            break;
        // Support-granted abilities fire the supporting unit's (S's) closure against the attacker's (A's)
        // mzID, so "this unit" resolves to A. Reuse the innate/upgrade dispatch helpers.
        case 'SupportOnAttack':    OnAttackFromUpgradeTrigger($player, $cardID, $mzID); break;
        case 'SupportOnAttackEnd': OnAttackEndTrigger($player, $cardID, $mzID);         break;
        case 'SupportWhenDefeated': OnWhenDefeated($player, $cardID, $mzID);            break;
        case 'AdvantageShed':      _SWUResolveAdvantageShed($player, $mzID);            break;
    }
    $playerID = $savedPID;
}

function SWUApplyPassiveEntryGrants(int $player, string $cardID, string $mzID): void {
    // ASH_006 Sabine Wren (leader) — "the next unit you play this phase gains Shielded." Consume the flag at
    // the first unit entry and give it a Shield token (Shielded's "give a Shield token" clarification).
    if (stripos(CardType($cardID) ?? '', 'Unit') !== false
        && GlobalEffectCount($player, 'SWU_ASH006_SHIELDED_NEXT') > 0) {
        RemoveGlobalEffect($player, 'SWU_ASH006_SHIELDED_NEXT');
        DoGiveShieldToken($player, $mzID);
    }
    if (HasTrait($cardID, 'Vehicle')) {
        $ground = GetGroundArena($player);
        foreach ($ground as $u) {
            if (isset($u->removed) && $u->removed) continue;
            if ($u->CardID === 'SOR_100') {
                AddTurnEffect($mzID, 'SOR_100');   // CardID token (registry: Ambush, perm) — provenance for Active Effects
                break;
            }
        }
    }
}

// CollectEntryTriggers — collect WhenPlayed, Shielded, and Ambush triggers when a unit enters play.
// Uses FlushEntryTriggerBag (EffectStack path). Returns the flush count (0, 1, or 2+).
// $isPlay distinguishes a genuine card play (the default) from a non-play entry such as a leader
// deploy: "when you play a card" observer reactions (FFF/Bossk/Cunning) only fire on a real play.
function CollectEntryTriggers($activePlayer, $cardID, $mzID, $targetArena, bool $isPlay = true): int {
    // TS26_02/004 (Anakin/Padmé) — mark every unit that ENTERS play this phase (incl. tokens/leaders via
    // their own entry points). Keyed by UniqueID on the controller; cleared at RegroupPhaseStart.
    $entO = GetZoneObject($mzID);
    if ($entO !== null) AddGlobalEffects(intval($entO->Controller ?? $activePlayer), 'SWU_ENTERED_PHASE_' . intval($entO->UniqueID ?? 0));
    // SEC_046 Galen Erso — a named card the enemy Galen targets has lost its abilities, so its When
    // Played does not fire (the $cardID/hand-source path can't rely on the object's Owner being set).
    if (HasWhenPlayedAbility($cardID) && !_SWUGalenSuppressesCard($activePlayer, $cardID)) {
        AddTrigger($activePlayer, 'WhenPlayed', $cardID, $mzID);
    }

    // HMW_048 Vernestra Rwoh — the additional cost recorded donor CardIDs (SWUVar: the pick can be
    // separated from this collection by a payment decision, so a global would not survive the request
    // boundary). One trigger PER DONOR rides the bag — multiple gains order through the normal prompt —
    // and each dispatches through OnWhenPlayed, so a gained ability counts as "using a When Played
    // ability" (LOF_197). Donors without a registered closure (vanilla / keyword-only per the
    // Shielded-and-Ambush-are-not-When-Played ruling) grant nothing. The stamp records the gain on her
    // object; its standard phase-duration sweep IS the "for this phase" expiry.
    if ($cardID === 'HMW_048') {
        $g048 = GetSWUVar('SWU_HMW048_GAINS', '');
        if ($g048 !== '') {
            SetSWUVar('SWU_HMW048_GAINS', '');
            global $whenPlayedAbilities;
            foreach (array_values(array_filter(explode(',', $g048))) as $gcid) {
                AddTurnEffect($mzID, 'SWU_HMW048_GAIN_' . $gcid);
                if (isset($whenPlayedAbilities[$gcid . ':0'])) {
                    AddTrigger($activePlayer, 'HMW048Gain', $gcid, $mzID);
                }
            }
        }
    }

    $obj = GetZoneObject($mzID);
    if ($obj !== null && HasKeyword_Shielded($obj)) {
        AddTrigger($activePlayer, 'Shielded', $cardID, $mzID);
    }

    if ($obj !== null && HasKeyword_Ambush($obj)) {
        // Ambush CR 5.9.a: "attack that enemy unit" — units only, not the base.
        $ambushTargets = SWUGetAllValidAmbushTargets($activePlayer, $obj, $targetArena); // union all opponents
        if (!empty($ambushTargets)) {
            // Carry the unit's UID (not the target list — dispatch recomputes valid targets fresh) so a
            // preceding trigger that moves the unit between arenas (JTL_096) can be re-resolved at dispatch.
            $ambushUID = intval($obj->UniqueID ?? 0);
            AddTrigger($activePlayer, 'Ambush', $cardID, $mzID, (string)$ambushUID);
        }
    }

    // Support (ASH) — "When you play/deploy this unit, you may attack with another unit." Fires on
    // both unit plays and leader deploys (this collector runs for both). Only offer if there's a ready
    // OTHER friendly unit to attack with; the chosen attacker gains S's other abilities for that attack.
    if ($obj !== null && HasKeyword_Support($obj)) {
        $supportAttackers = SWUGetValidSupportAttackers($activePlayer, $obj);
        if (!empty($supportAttackers)) {
            AddTrigger($activePlayer, 'Support', $cardID, $mzID, implode('&', $supportAttackers));
        }
    }

    // ASH_041 Outcast — "When a friendly unit enters play (including this one): it gets +1/+0 for this
    // phase." Buff the entering unit once per ASH_041 the active player controls (self-buffs on its own
    // entry, since it's already in the arena by now).
    if ($obj !== null) {
        $a041 = 0;
        foreach (GetUnitsInPlay($activePlayer) as $u) {
            if (empty($u->removed) && ($u->CardID ?? '') === 'ASH_041') $a041++;
        }
        for ($i = 0; $i < $a041; $i++) SWUApplyPhaseBuff($mzID, 1, 0, 'ASH_041');
    }

    // Task 5.1 — observer triggers: "when an opponent plays a card / unit / event / upgrade".
    // TWI_210 Cunning fires once per copy in play when the opponent paid less than printed cost.
    // AddTrigger here so the reactions batch with the played card's own WhenPlayed via
    // FlushEntryTriggerBag (cross-player → YESNO ordering choice, single → auto-dispatch).
    // Skipped for non-play entries (e.g. leader deploy): deploying a leader is not "playing a card".
    if ($isPlay) {
        SWUCollectOpponentPlayReactions($activePlayer, $cardID, intval($GLOBALS['gLastPlayResourcesPaid']));
        // Batch E.1 — own-play reactions (Bossk/FFF). Pass the played unit's UID so an Aggression unit
        // doesn't trigger its own copy ("another …").
        SWUCollectOwnPlayReactions($activePlayer, $cardID, ($obj !== null ? intval($obj->UniqueID ?? 0) : 0));
    }
    // HMW_171 Trap Field — a base-hosted reactive fires when a non-leader ground unit enters play.
    SWUCollectTrapFieldReactions($mzID);
    return FlushEntryTriggerBag($activePlayer);
}

// HMW_171 Trap Field (Fortify) — "When a non-leader ground unit enters play (including token units):
// You may defeat this upgrade. If you do, deal 3 damage to that unit." A base-hosted REACTIVE entry
// observer — the first of its kind. Unrestricted: fires for BOTH players' bases and for friendly OR
// enemy ground units, played OR created (see _SWUCreateOneToken). The reaction is owned by the base
// owner, who may be the NON-ACTIVE player (cross-player, drains like SHD_172). The entering unit is
// carried by UniqueID (frame-independent) because the trigger owner may differ from the frame the
// entering mzID was captured in. Returns the number of triggers added (so the token path knows to flush).
function SWUCollectTrapFieldReactions(string $enteredMzID): int {
    if (strpos($enteredMzID, 'GroundArena') === false) return 0;   // ground units only
    $obj = GetZoneObject($enteredMzID);
    if (SWUObjGone($obj)) return 0;
    if (IsLeaderUnit($obj)) return 0;                              // "non-leader" excludes deployed leaders
    $enteredUID = intval($obj->UniqueID ?? 0);
    if ($enteredUID <= 0) return 0;
    $added = 0;
    foreach ([1, 2] as $bp) {
        $zone = GetBase($bp);
        $base = $zone[0] ?? null;
        if ($base === null) continue;
        $n = 0;
        foreach (GetUpgradesOnUnit($base) as $sub) {
            $cid = is_array($sub) ? ($sub['CardID'] ?? '') : ($sub->CardID ?? '');
            if ($cid === 'HMW_171') $n++;
        }
        if ($n > 0) {
            // ONE trigger carrying the count (not N identical triggers — two identical reactive triggers
            // hang the EffectStack flush, per SHD_172). The handler loops up to $n sequential may-defeats.
            AddTrigger($bp, 'HMW_171', 'HMW_171', (string)$enteredUID, (string)$n);
            $added++;
        }
    }
    return $added;
}

// Queue the base owner's "you may defeat Trap Field → deal 3" decision. Guarded so it only prompts while
// a Trap Field is still on their base and the entering unit is still in play.
function Hmw171TrapFieldReaction(int $player, int $enteredUID, int $count): void {
    global $playerID; $playerID = $player;
    if (SWUFindMzByUID($enteredUID) === null) return;             // entering unit already gone
    $zone = GetBase($player); $base = $zone[0] ?? null;
    if ($base === null || SWUFindUpgradeIndex($base, 'HMW_171') < 0) return;
    DecisionQueueController::AddDecision($player, 'YESNO', '-', 1,
        tooltip: "Defeat_Trap_Field_to_deal_3_damage_to_that_unit?");
    DecisionQueueController::AddDecision($player, 'CUSTOM', "HMW_171#0|{$enteredUID}|{$count}", 1);
}

// CollectWhenPlayedAsUpgradeTriggers — parallel to CollectEntryTriggers for upgrades.
// If the card has a WhenPlayedAsUpgrade ability, that fires; otherwise falls back to
// WhenPlayed if the card also has that. Returns FlushEntryTriggerBag count (0/1/2+).
function CollectWhenPlayedAsUpgradeTriggers(int $player, string $cardID, string $targetMzID): int {
    // SEC_046 Galen Erso — a named upgrade/pilot that lost its abilities fires no When-Played(-as-Upgrade).
    if (_SWUGalenSuppressesCard($player, $cardID)) { /* suppressed: no entry trigger */ }
    elseif (HasWhenPlayedAsUpgradeAbility($cardID)) {
        AddTrigger($player, 'WhenPlayedAsUpgrade', $cardID, $targetMzID);
    } elseif (HasWhenPlayedAbility($cardID)) {
        AddTrigger($player, 'WhenPlayed', $cardID, $targetMzID);
    }
    // Task 5.1 — TWI_210 Cunning observer: fires on upgrade plays too.
    SWUCollectOpponentPlayReactions($player, $cardID, intval($GLOBALS['gLastPlayResourcesPaid']));
    // Batch E.1 — own-play reactions (an Aggression upgrade triggers FFF; an upgrade is never a unit, so no self-UID).
    // $playedAsUpgrade = true: a Piloting card reaching here was played as a PILOT, and its CardType is
    // still "Unit" — the flag stops it reading as a unit play (CR 17.c).
    SWUCollectOwnPlayReactions($player, $cardID, 0, true);
    // LOF_229 Kylo Ren — "When you play an upgrade on this unit: may use the Force → draw a card." The
    // host is known here; the reaction is owned by the active (playing) player, so no cross-player race.
    $lof229Host = GetZoneObject($targetMzID);
    // ⚠ All THREE of the "When YOU play an upgrade on THIS unit" cards below (LOF_229 Kylo Ren,
    // ASH_047 Gar Saxon, SHD_067 Fenn Rau) must also require that the player who PLAYED the upgrade
    // CONTROLS the host. $player is whoever played it, and per the upgrade-ownership ruling an
    // OPPONENT may legally attach an upgrade to your unit — at which point these fired for the WRONG
    // player. Fenn Rau's is the visible one: its "-2/-2 to an enemy unit" pool is relative to the
    // trigger's player, so an opponent attaching an upgrade to Fenn Rau made him debuff HIMSELF.
    // (SHD_133 Dengar below is deliberately NOT gated: it reads "on A unit", not "this unit".)
    $upgHostIsMine = $lof229Host !== null && intval($lof229Host->Controller ?? -1) === intval($player);
    if ($upgHostIsMine && ($lof229Host->CardID ?? '') === 'LOF_229') {
        AddTrigger($player, 'LOF_229', 'LOF_229', '');
    }
    // ASH_047 Gar Saxon — "When you play an upgrade on this unit: you may create a Mandalorian token
    // (once each round)." Host known here; reaction owned by the active player. The once-per-round gate
    // is enforced in the reaction (so the trigger always collects; it no-ops if already used).
    if ($upgHostIsMine && ($lof229Host->CardID ?? '') === 'ASH_047'
        && GlobalEffectCount($player, 'SWU_ASH047_USED') <= 0) {
        AddTrigger($player, 'ASH_047', 'ASH_047', '');
    }
    // SHD_067 Fenn Rau — "When you play an upgrade on this unit: Give an enemy unit -2/-2 for this phase."
    if ($upgHostIsMine && ($lof229Host->CardID ?? '') === 'SHD_067') {
        AddTrigger($player, 'SHD_067', 'SHD_067', '');
    }
    // SHD_133 Dengar (field observer) — "When you play an upgrade on a unit: you may deal 1 damage to that
    // unit." Fires once per active Dengar the player controls; carries the HOST's UID (mzIDs shift).
    if ($lof229Host !== null && empty($lof229Host->removed)) {
        $hostUID133 = intval($lof229Host->UniqueID ?? 0);
        $dengars = _SWUCountActiveUnitsWithCardID($player, 'SHD_133');
        for ($i = 0; $i < $dengars && $hostUID133 > 0; $i++) {
            AddTrigger($player, 'SHD_133', 'SHD_133', strval($hostUID133));
        }
    }
    // HMW_206 The Tarkin Doctrine — "Attached base gains: 'When you play a Fortification upgrade: Exhaust an
    // enemy unit.'" Fires when a Fortification-TRAIT upgrade is played while HMW_206 is attached to the
    // player's base. HMW_206 is itself trait 'Law' (not Fortification), so playing it never self-triggers.
    if (HasTrait($cardID, 'Fortification') && _SWUBaseHasUpgrade(intval($player), 'HMW_206')) {
        AddTrigger($player, 'HMW_206', 'HMW_206', '');
    }
    return FlushEntryTriggerBag($player);
}

// CollectOnAttachedTriggers — fires when a card BECOMES ATTACHED (any source: normal upgrade
// play, Piloting, leader flip-attach, ship hop), distinct from WhenPlayedAsUpgrade (play trigger).
// Gated by HasOnAttachedAbility (manual dictionary). Returns FlushEntryTriggerBag count (0/1/2+).
function CollectOnAttachedTriggers(int $player, string $cardID, string $targetMzID): int {
    if (!HasOnAttachedAbility($cardID)) return 0;
    AddTrigger($player, 'OnAttached', $cardID, $targetMzID);
    return FlushEntryTriggerBag($player);
}

// OnWhenPlayedAsUpgrade — dispatches the WhenPlayedAsUpgrade closure if registered,
// otherwise delegates to OnWhenPlayed for cards that share that window.
function OnWhenPlayedAsUpgrade(int $player, string $cardID, string $mzID): void {
    global $whenPlayedAsUpgradeAbilities;
    $key = $cardID . ':0';
    if (isset($whenPlayedAsUpgradeAbilities[$key])) {
        $whenPlayedAsUpgradeAbilities[$key]($player, $mzID);
        // LOF_197 Qui-Gon Jinn's Aethersprite — a "When Played as an upgrade" ability also counts as a
        // "When Played" ability, so it consumes the armed repeat and offers to use it again (re-dispatch
        // the same upgrade ability on the same host). Mirrors the OnWhenPlayed repeat.
        if (GlobalEffectCount($player, 'SWU_LOF197_REPEAT') > 0) {
            RemoveGlobalEffect($player, 'SWU_LOF197_REPEAT');
            DecisionQueueController::AddDecision($player, "YESNO", "-", 1,
                tooltip: "Use_that_When_Played_ability_again_(Qui-Gon's_Aethersprite)?");
            DecisionQueueController::AddDecision($player, "CUSTOM", "LOF_197#2|{$cardID}|{$mzID}", 1);
        }
        return;
    }
    OnWhenPlayed($player, $cardID, $mzID);
}
$customDQHandlers["LOF_197#2"] = function($player, $parts, $lastDecision) {
    if ($lastDecision !== 'YES') return;
    global $playerID; $playerID = intval($player);
    $cardID = $parts[0] ?? ''; $mzID = $parts[1] ?? '';
    if ($cardID === '' || $mzID === '') return;
    OnWhenPlayedAsUpgrade(intval($player), $cardID, $mzID); // flag already consumed → re-checks for a 2nd charge
};

// OnOnAttached — dispatches the OnAttached closure for the given card.
function OnOnAttached(int $player, string $cardID, string $mzID): void {
    global $onAttachedAbilities;
    $key = $cardID . ':0';
    if (isset($onAttachedAbilities[$key])) {
        $onAttachedAbilities[$key]($player, $mzID);
    }
}

// ── Reactive "an enemy unit is defeated / leaves play" dispatch (Phase 7.1) ───
// Distinct from the SWU_ENEMY_DEFEATED phase flag: these fire a real reaction (queue a decision)
// at the moment a unit leaves play, observed by units/leaders in play.

// Count non-removed units with $cardID controlled by $player (across both arenas).
function _SWUCountUnitsWithCardID(int $player, string $cardID): int {
    $n = 0;
    foreach (GetUnitsInPlay($player) as $u) {
        if (!empty($u->removed)) continue;
        if (($u->CardID ?? '') === $cardID) $n++;
    }
    return $n;
}

// Like _SWUCountUnitsWithCardID but excludes copies that have lost their abilities (SEC_046 Galen Erso) —
// for REACTIVE-OBSERVER triggers, where a suppressed copy must not react. (Plain control/"you control N"
// counts still use _SWUCountUnitsWithCardID — a suppressed unit is still controlled.)
function _SWUCountActiveUnitsWithCardID(int $player, string $cardID): int {
    $n = 0;
    foreach (GetUnitsInPlay($player) as $u) {
        if (!empty($u->removed) || ($u->CardID ?? '') !== $cardID) continue;
        if (LostAbilities($u)) continue;
        $n++;
    }
    return $n;
}

// True if $player's leader is $cardID, undeployed, and ready (so it can pay an "exhaust this
// leader" cost). Leader-side reactive abilities are active only while the leader is undeployed.
function _SWULeaderReadyUndeployed(int $player, string $cardID): bool {
    foreach (GetLeader($player) as $l) {
        if (!empty($l->removed)) continue;
        if (($l->CardID ?? '') === $cardID && empty($l->Deployed) && !empty($l->Ready)) return true;
    }
    return false;
}

// Ready up to $count exhausted resources for $player (resources are fungible, so no choice needed).
// Returns how many were readied.
function SWUReadyResources(int $player, int $count): int {
    $resources = &GetResources($player);
    $readied = 0;
    for ($i = 0; $i < count($resources) && $readied < $count; $i++) {
        if (!empty($resources[$i]->removed)) continue;
        if (intval($resources[$i]->Status) === 0) {
            $resources[$i]->Status = 1;
            $readied++;
        }
    }
    return $readied;
}

// For each unit that just left play ($leftCards entries: ['player'=>controller, 'cardID'=>…]),
// add the reactive triggers observed by the OTHER player and (for defeats) the granted
// When-Defeated abilities on the leaving unit. Also sets the SWU_ENEMY_LEFT_PLAY phase flag on the
// opponent (for "if an enemy unit left play this phase" checks — Boba's deployed OnAttackEnd).
// Caller flushes the trigger bag. $defeated distinguishes a defeat from a bounce/other leave.

// Simultaneous-defeat window. A card whose text defeats several units AT ONCE ("Defeat all units")
// still walks them one at a time through SWUDefeatUnit, so any observer that reads the board would
// see it shrink mid-effect. Wrapping the loop in Begin/End tells the leave-play collector to judge
// every defeat in the batch against the board as it stood when the effect started. Always pair them
// (End in a finally-style position) — a window left open would freeze the next effect's counts too.
function SWUSimulDefeatBegin(): void {
    $GLOBALS['gSimulDefeatWindow'] = true;
    unset($GLOBALS['gSimulDefeatSidious']);
    // Snapshot, PER SEAT, how many copies of each CardID are in play right now — i.e. before any of the
    // batch has been removed. "When an enemy unit is defeated" observers must fire for every copy that
    // was in play when the defeat happened, and inside a wipe the only trustworthy answer is this
    // pre-effect picture. See _SWUSimulObserverCount below for why the live count + $leftCards
    // supplement is not enough.
    $snap = [];
    foreach ([1, 2] as $seat) {
        foreach (GetUnitsInPlay($seat) as $u) {
            if (!empty($u->removed) || LostAbilities($u)) continue;
            $cid = (string)($u->CardID ?? '');
            if ($cid === '') continue;
            $snap[$seat][$cid] = ($snap[$seat][$cid] ?? 0) + 1;
        }
    }
    $GLOBALS['gSimulDefeatUnits'] = $snap;
}

// How many copies of $cardID controlled by $seat should observe a defeat in THIS batch.
//
// Normally: the copies still active, PLUS any copy that left play in this same $leftCards batch (it was
// in play when the co-defeated unit died, so its reaction still fires — CR simultaneous-removal).
//
// ⚠ That is only correct when the whole simultaneous defeat arrives as ONE batch, which is how COMBAT
// and "deal N damage to each unit" effects behave. A mass-defeat card like SOR_043 Superlaser Blast
// ("Defeat all units") instead walks the board one unit at a time, so every defeat is its own
// single-element batch: an observer defeated EARLY in the loop is neither still active nor present in
// the LATER batches, and its reaction was silently dropped. Inside a SWUSimulDefeatBegin/End window we
// therefore answer from the pre-effect snapshot instead, which is the board the whole batch is judged
// against.
function _SWUSimulObserverCount(int $seat, string $cardID, array $leftCards): int {
    if (!empty($GLOBALS['gSimulDefeatWindow']) && isset($GLOBALS['gSimulDefeatUnits'])) {
        return intval($GLOBALS['gSimulDefeatUnits'][$seat][$cardID] ?? 0);
    }
    $n = _SWUCountActiveUnitsWithCardID($seat, $cardID);
    foreach ($leftCards as $lc) {
        if (($lc['cardID'] ?? '') === $cardID && intval($lc['player'] ?? 0) === $seat) $n++;
    }
    return $n;
}
function SWUSimulDefeatEnd(): void {
    $GLOBALS['gSimulDefeatWindow'] = false;
    unset($GLOBALS['gSimulDefeatSidious']);
    unset($GLOBALS['gSimulDefeatUnits']);
}
function SWUCollectLeavePlayReactions(array $leftCards, bool $defeated): void {
    // TS26_13 Darth Sidious — snapshot how many Sidious units were in play WHEN these cards left, per
    // seat, before walking the batch. This collection runs after every card in $leftCards is already
    // marked removed, so a live count would miss a Sidious who died in the same batch — yet he was in
    // play when those units were defeated and still sees each of them (his own defeat included). Add
    // any Sidious in $leftCards back to the snapshot; a bounce/other leave does not count, hence the
    // $defeated gate.
    $sidiousPerSeat = [];
    $sidiousLiveMz  = [];
    global $playerID; $savedSidPID = $playerID;
    foreach ([1, 2] as $sp) {
        $playerID = $sp;
        $n = 0;
        foreach (['myGroundArena', 'mySpaceArena'] as $z) {
            foreach (ZoneSearch($z, AnyUnitFilter) as $mz) {
                $o = GetZoneObject($mz);
                if ($o === null || !empty($o->removed) || ($o->CardID ?? '') !== 'TS26_13') continue;
                $n++;
                $sidiousLiveMz[$mz] = true;
            }
        }
        $sidiousPerSeat[$sp] = $n;
    }
    $playerID = $savedSidPID;
    if ($defeated) {
        foreach ($leftCards as $d0) {
            if (($d0['cardID'] ?? '') !== 'TS26_13') continue;
            // Only add back a Sidious the live scan MISSED. Different callers reach this collector at
            // different points — combat marks its dead removed first (scan finds nothing, add back), while
            // the effect-defeat path collects before the mark lands (scan already found him). Adding back
            // unconditionally double-counted him and doubled every droid.
            if (!empty($d0['mzID']) && isset($sidiousLiveMz[$d0['mzID']])) continue;
            $sp0 = intval($d0['player'] ?? 0);
            if (isset($sidiousPerSeat[$sp0])) $sidiousPerSeat[$sp0]++;
        }
        // A card that defeats several units AT ONCE ("Defeat all units") still reaches this collector one
        // unit at a time, so a Sidious killed by the wipe would stop counting partway through the very
        // batch he was alive for. SWUSimulDefeatBegin/End open a window that freezes the seat counts for
        // the whole effect; outside such a window nothing is cached and each defeat is judged on its own.
        if (!empty($GLOBALS['gSimulDefeatWindow'])) {
            if (!isset($GLOBALS['gSimulDefeatSidious'])) $GLOBALS['gSimulDefeatSidious'] = $sidiousPerSeat;
            $sidiousPerSeat = $GLOBALS['gSimulDefeatSidious'];
        }
    }
    foreach ($leftCards as $d) {
        $controller = intval($d['player'] ?? 0);
        if ($controller <= 0) continue;
        // Twin Suns: EVERY opponent of the controller observes this enemy leaving play (2-player → the one
        // opponent; OpponentsOf is length-1 so each loop below runs exactly once and is byte-identical).
        $opps = OpponentsOf($controller);
        foreach ($opps as $opp) AddGlobalEffects($opp, 'SWU_ENEMY_LEFT_PLAY');
        AddGlobalEffects($controller, 'SWU_FRIENDLY_LEFT_PLAY'); // "if a friendly unit left play this phase" (LOF_216)
        // ASH_211 Fateful Goodbye — "if a friendly LEADER unit left play this phase" (any leave, not just defeat).
        if (strpos(CardType($d['cardID'] ?? '') ?? '', 'Leader') !== false) {
            AddGlobalEffects($controller, 'SWU_FRIENDLY_LEADER_LEFT_PLAY');
        }

        // SOR_015 Boba Fett (undeployed leader of an opponent): "When an enemy unit leaves play: you may
        // exhaust this leader; if you do, ready a resource." Treated as an always-yes auto-resolve
        // (like SLT SOR_083): only fires when there is a benefit — the leader is ready+undeployed
        // AND there is an exhausted resource to ready (total > ready). If resources are full, skip.
        foreach ($opps as $opp) {
            if (_SWULeaderReadyUndeployed($opp, 'SOR_015')
                && SWUResourceCount($opp) > SWUResourceCount($opp, true)) {
                AddTrigger($opp, 'SOR_015', 'SOR_015', '');
            }
        }

        if ($defeated) {
            // TS26_13 Darth Sidious — "When a non-token unit is defeated: create a Battle Droid token."
            // Fires for each in-play Sidious's controller, for ANY non-token unit defeat (friendly or enemy).
            $dTypeSid = CardType($d['cardID'] ?? '') ?? '';
            if (strpos($dTypeSid, 'Unit') !== false && strpos(strtolower($dTypeSid), 'token') === false) {
                foreach ([1, 2] as $sp) {
                    $nSid = intval($sidiousPerSeat[$sp] ?? 0);   // batch-aware: see the snapshot above
                    for ($i = 0; $i < $nSid; $i++) SWUCreateUnitToken($sp, 'TS26_T01');
                }
            }
            // LAW_005 Jyn Erso — track "a friendly Rebel unit was defeated this phase" on the controller.
            // Read the LIVE traits of the defeated unit (incl. GRANTED Rebel from Nemik's Manifesto SEC_156 /
            // Fulcrum LAW_150), not just its printed CardID — the object is still reachable (removed but
            // intact) here. Fall back to the printed trait for entries built without an mzID.
            $law005Rebel = (!empty($d['mzID']) && TraitContains(GetZoneObject($d['mzID']), 'Rebel'))
                        || HasTrait($d['cardID'] ?? '', 'Rebel');
            if ($law005Rebel) AddGlobalEffects($controller, 'SWU_REBEL_DEFEATED');
            // ASH_008 Moff Gideon — "a friendly Imperial unit was defeated this phase" on the controller.
            if (HasTrait($d['cardID'] ?? '', 'Imperial')) AddGlobalEffects($controller, 'SWU_IMPERIAL_DEFEATED');
            // ASH_093 Captain Pellaeon — "While a leader unit has been defeated this phase, gains Raid 3."
            // Flag BOTH players (any leader, friendly or enemy). Cleared at RegroupPhaseStart. Read the LIVE
            // leader-unit status of the defeated object (still intact here, before its upgrades are stripped)
            // so a unit made a leader unit by The Darksaber (ASH_135) or a deployed Pilot leader counts —
            // its PRINTED type is "Unit". Fall back to the printed type for entries built without an mzID.
            if ((!empty($d['mzID']) && IsLeaderUnit(GetZoneObject($d['mzID'])))
                || strpos(CardType($d['cardID'] ?? '') ?? '', 'Leader') !== false) {
                foreach (GetLiveSeatsArray() as $lp) AddGlobalEffects($lp, 'SWU_LEADER_DEFEATED_PHASE');
            }
            // TWI_001 Nala Se (deployed) — "Each friendly Clone unit gains: When Defeated: Heal 2 damage
            // from your base." Field-presence grant while the controller's TWI_001 leader is deployed.
            if (HasTrait($d['cardID'] ?? '', 'Clone') && _SWULeaderDeployed($controller, 'TWI_001')) {
                OnHealBase($controller, $controller, 2);
            }
            // TWI_033 Calculating MagnaGuard — "When a friendly unit is defeated: this unit gains Sentinel
            // for this phase." Grant to each in-play TWI_033 the controller has (mandatory, inline).
            foreach (GetUnitsInPlay($controller) as $mg) {
                if (empty($mg->removed) && ($mg->CardID ?? '') === 'TWI_033') AddTurnEffect($mg->GetMzID(), 'SENTINEL');
            }
            // ASH_127 The Twins (controlled by $controller): "When another friendly unit is defeated: heal 1
            // from your base." The just-defeated unit is removed, so an in-play Twins is always "another".
            // ⚠ Deferred: a Twins CO-DEFEATED in a simultaneous board-wipe (SOR_043 "defeat all units") should
            // still heal once per other co-defeated friendly (last-known information), but SOR_043 defeats
            // units sequentially (not one $leftCards batch), so a co-defeated Twins misses some/all of them.
            // A proper fix = route board-wipes through a true simultaneous-defeat batch (broad, risky).
            $twins = _SWUCountActiveUnitsWithCardID($controller, 'ASH_127');
            for ($i = 0; $i < $twins; $i++) {
                OnHealBase($controller, $controller, 1);
            }
            // ASH_128 Bothan-5 (controlled by $controller): "When another friendly non-Vehicle unit is
            // defeated: you may have this unit capture that unit from your discard pile. Once each round."
            $dCardID128 = $d['cardID'] ?? '';
            if ($dCardID128 !== '' && strpos(CardType($dCardID128) ?? '', 'Unit') !== false
                && strpos(strtolower(CardType($dCardID128) ?? ''), 'token') === false
                && !HasTrait($dCardID128, 'Vehicle')
                && GlobalEffectCount($controller, 'SWU_ASH128_USED') <= 0) {
                foreach (GetUnitsInPlay($controller) as $bothan) {
                    if (!empty($bothan->removed) || ($bothan->CardID ?? '') !== 'ASH_128') continue;
                    // Encode captor UID + defeated CardID in mzID: the flat FlushTriggerBag path (used by
                    // leave-play reactions) drops extraParams, so both must ride the mzID field (comma-sep).
                    AddTrigger($controller, 'ASH_128', 'ASH_128', strval(intval($bothan->UniqueID ?? 0)) . ',' . $dCardID128);
                    break;   // one Bothan-5 reaction per defeat
                }
            }
            // Twin Suns: the "when an ENEMY unit is defeated" observers below fire for EVERY opponent of the
            // defeated unit's controller (2-player → the one opponent; loop runs once, byte-identical).
            foreach ($opps as $opp) {
            // SOR_036 Gideon Hask (controlled by $opp): "When an enemy unit is defeated: give an
            // Experience token to a friendly unit." Fires once per Gideon in play — INCLUDING a Gideon
            // defeated in this same simultaneous batch (CR: the condition reads the pre-defeat state;
            // he traded with the enemy he killed). Same supplement as HK-47 below.
            $gideons = _SWUSimulObserverCount($opp, 'SOR_036', $leftCards);
            for ($i = 0; $i < $gideons; $i++) {
                AddTrigger($opp, 'SOR_036', 'SOR_036', '');
            }
            // SEC_051 Bo-Katan Kryze (controlled by $opp): "When an enemy unit is defeated: give an
            // Experience token to a friendly unit." Same shape as Gideon, same batch supplement.
            $bokatans = _SWUSimulObserverCount($opp, 'SEC_051', $leftCards);
            for ($i = 0; $i < $bokatans; $i++) {
                AddTrigger($opp, 'SEC_051', 'SEC_051', '');
            }
            // LOF_130 HK-47 (controlled by $opp): "When an enemy unit is defeated: deal 1 damage to its
            // controller's base." $controller is the defeated unit's controller (the enemy from HK-47's view).
            // Also count HK-47s that were defeated in THIS SAME simultaneous batch (already removed, so
            // absent from the active count): they were in play when the enemy was defeated, so their
            // reaction still fires (CR: simultaneous defeats use the pre-defeat state; the damage lands
            // even when HK-47 itself was defeated in the batch).
            $hk47s = _SWUSimulObserverCount($opp, 'LOF_130', $leftCards);
            for ($i = 0; $i < $hk47s; $i++) {
                SWUDealDamageToBase(1, $controller);
            }
            // SOR_002 Iden Versio (deployed leader unit of $opp): "When an enemy unit is defeated:
            // Heal 1 damage from your base." Fires once per defeated enemy unit.
            // ⚠ Counted through the batch-aware helper, NOT _SWULeaderDeployed: a deployed leader IS a
            // real arena unit that gets DEFEATED in combat and only then returns to its leader zone
            // (user ruling 2026-08-17), so on a trade the live `Deployed` flag is already false by the
            // time this collection runs. Same simultaneous-defeat family as Chimaera/Gideon/HK-47 above.
            $idens = _SWUSimulObserverCount($opp, 'SOR_002', $leftCards);
            for ($i = 0; $i < $idens; $i++) {
                AddTrigger($opp, 'SOR_002', 'SOR_002', '');
            }
            // SHD_137 Punishing One (controlled by $opp): "When an UPGRADED enemy unit is defeated: you may
            // ready this unit. Use this ability only once each round." Readying is pure benefit, so this is
            // an always-yes auto-resolve that only fires (and consumes the once/round) when there IS a
            // benefit — i.e. an EXHAUSTED Punishing One (mirrors SOR_015's benefit-only auto-resolve).
            if (!empty($d['upgraded']) && GlobalEffectCount($opp, 'SWU_SHD137_USED') <= 0) {
                foreach (GetUnitsInPlay($opp) as $pu) {
                    if (!empty($pu->removed) || ($pu->CardID ?? '') !== 'SHD_137' || LostAbilities($pu)) continue;
                    if (intval($pu->Status ?? 0) === 1) continue;   // already ready → no benefit, don't consume
                    $pu->Status = 1;                                // ready it
                    AddGlobalEffects($opp, 'SWU_SHD137_USED');       // once each round
                    break;
                }
            }
            // HMW_062 Nuvo Vindi (controlled by $opp): "When an enemy unit with a Weakness token on it is
            // defeated: You may give a Weakness token to a unit. Use this ability only once each round."
            // $d['weakened'] is captured at the defeat sites while the subcards are still intact — by the
            // time this collection runs the dying unit's upgrades are already stripped, so the token
            // cannot be read off the unit here.
            // The once/round flag is consumed HERE, at collect time, so a DECLINED offer still spends the
            // round (the ability triggered) — same convention as SHD_137 above.
            // ⚠ Counted through the batch-aware helper for the same reason as Chimaera/Iden above: a Vindi
            // that TRADED with the weakened enemy was in play when it was defeated, so he still observes it.
            if (!empty($d['weakened']) && GlobalEffectCount($opp, 'SWU_HMW062_USED') <= 0
                && _SWUSimulObserverCount($opp, 'HMW_062', $leftCards) > 0) {
                AddGlobalEffects($opp, 'SWU_HMW062_USED');
                AddTrigger($opp, 'HMW_062', 'HMW_062', '');
            }
            // ASH_052 Chimaera (controlled by $opp): "When an enemy unit is defeated: heal 2 damage from
            // your base." Fires once per Chimaera in play; non-interactive. Same batch supplement as
            // Gideon/Bo-Katan/HK-47 above: a Chimaera defeated in THIS batch was in play when the enemy
            // was defeated, so it still heals — the live-report case is a straight combat TRADE.
            $chimaeras = _SWUSimulObserverCount($opp, 'ASH_052', $leftCards);
            for ($i = 0; $i < $chimaeras; $i++) {
                OnHealBase($opp, $opp, 2);
            }
            // LAW_053 Dengar (controlled by $opp): "When a unit with the highest cost among enemy units
            // is defeated: create a Credit token. Use only once each round." The defeated unit
            // (controlled by $controller, i.e. an enemy of $opp) was the highest-cost enemy iff its cost
            // is >= every other still-in-play unit of $controller. Per-round flag cleared at RGS.
            $law053Active = _SWUCountActiveUnitsWithCardID($opp, 'LAW_053') > 0;
            if (!$law053Active) {
                // CR simultaneous-removal: the trigger condition is evaluated as of the state that caused
                // it (before the batch's removals), so a Dengar defeated in the SAME batch still triggers.
                foreach ($leftCards as $lc053) {
                    if (($lc053['cardID'] ?? '') === 'LAW_053' && intval($lc053['player'] ?? 0) === $opp) { $law053Active = true; break; }
                }
            }
            if ($law053Active && GlobalEffectCount($opp, 'SWU_LAW053_USED') <= 0) {
                $defCost  = intval(CardCost($d['cardID'] ?? ''));
                $maxOther = 0;
                foreach (GetUnitsInPlay($controller) as $u) {
                    if (empty($u->removed)) $maxOther = max($maxOther, intval(CardCost($u->CardID ?? '')));
                }
                if ($defCost >= $maxOther) {
                    SWUCreateCreditToken($opp, 1);
                    AddGlobalEffects($opp, 'SWU_LAW053_USED');
                }
            }
            } // end foreach opponent (enemy-defeated observers)
            // LAW_119 Rogue One (controlled by $controller): "When a friendly unit is defeated: look at
            // the top 2 cards, put any number on the bottom, rest on top." Fires once per Rogue One.
            // Count via the shared observer helper. Outside a wipe this is the old "active copies +
            // copies that left play in THIS batch" (CR simultaneous-removal: a Rogue One that dies in the
            // same batch was in play when the friendly died, so its reaction still fires — the card says
            // "a friendly unit", no "another", so its OWN defeat qualifies).
            // ⚠ Inside a SWUSimulDefeatBegin/End window the helper answers from the pre-effect snapshot
            // INSTEAD of active+batch, which is load-bearing here in BOTH directions: a per-unit wipe
            // loop otherwise (a) misses friendlies defeated after this Rogue One, and (b) DOUBLE-FIRES
            // for Rogue One's own defeat, because that defeat reaches the collection by two routes and
            // active+batch counts it twice. Measured: a solo Rogue One caught in Superlaser Blast raised
            // TWO scries for ONE friendly defeat.
            $rogueones = _SWUSimulObserverCount($controller, 'LAW_119', $leftCards);
            for ($i = 0; $i < $rogueones; $i++) AddTrigger($controller, 'LAW_119', 'LAW_119', '');
            // HMW_113 Sinister War Memorial (Fortify upgrade on $controller's base) — the base gains
            // "When a friendly unit is defeated: Heal 1 damage from this base." $controller is the
            // DEFEATED unit's controller, which is exactly "friendly" from that base's point of view.
            // Non-interactive, so it resolves inline rather than through a trigger. NOT unique: each
            // attached copy grants its own ability, hence the count.
            $memorials = _SWUCountBaseUpgrades($controller, 'HMW_113');
            for ($i = 0; $i < $memorials; $i++) OnHealBase($controller, $controller, 1);
            // SOR_105 General Krell (controlled by $controller): grants "When Defeated: you may draw
            // a card" to each OTHER friendly unit. The leaving unit qualifies if it isn't Krell.
            if (($d['cardID'] ?? '') !== 'SOR_105' && _SWUCountUnitsWithCardID($controller, 'SOR_105') > 0) {
                AddTrigger($controller, 'SOR_105', 'SOR_105', '');
                _SWUAddShadowCasterGrantedReuse($controller, 'SOR_105', ''); // JTL_169 Shadow Caster reuse of this granted WD
            }
            // SOR_115 Agent Kallus: "When another UNIQUE unit is defeated: you may draw a card. Use
            // only once each round." Any unique unit (friendly OR enemy) other than Kallus himself —
            // a defeated Kallus is already removed, so an in-play Kallus never sees its own defeat.
            // Fires for each Kallus controller (both seats) whose once-per-round flag is unused.
            if (CardUnique($d['cardID'] ?? '')) {
                foreach (GetLiveSeatsArray() as $kp) {
                    // Per-instance once-per-round via each Kallus unit's NumUses budget.
                    foreach (array_merge(GetGroundArena($kp) ?? [], GetSpaceArena($kp) ?? []) as $ku) {
                        if (empty($ku->removed) && ($ku->CardID ?? '') === 'SOR_115' && SWUHasUseAvailable($ku)) {
                            AddTrigger($kp, 'SOR_115', 'SOR_115', '');
                            SWUConsumeUse($ku);
                        }
                    }
                }
            }
        }
    }
}

// Task 5.1 — TWI_210 Cunning: "When an opponent plays a card: If that opponent paid less than
// the card's cost to play it, ready or exhaust a unit."
// Called immediately after $gLastPlayResourcesPaid is finalised for the play. For each TWI_210
// controlled by the OPPONENT of $playingPlayer that is in play (ground or space), if
// resourcesPaid < printed cost, queue a trigger for that TWI_210's controller.
// Uses AddTrigger + FlushEntryTriggerBag (batches with the played card's own entry triggers).
// $resourcesPaid is passed explicitly so this never re-reads the global (race-safety).
function SWUCollectOpponentPlayReactions(int $playingPlayer, string $playedCardID, int $resourcesPaid): void {
    $opp = GetOpponent($playingPlayer);
    if ($opp === null) return;
    $printedCost = intval(CardCost($playedCardID));
    // TWI_210 Cunning — fires ONLY when the opponent paid LESS than the printed cost (a discount).
    if ($resourcesPaid < $printedCost) {
        $count = _SWUCountActiveUnitsWithCardID($opp, 'TWI_210');   // SEC_046 Galen — named observer doesn't react
        for ($i = 0; $i < $count; $i++) {
            AddTrigger($opp, 'TWI_210', 'TWI_210', '');
        }
    }
    // SHD_172 Krayt Dragon — "When an opponent plays a card: You may deal damage equal to that card's cost
    // to their base or a ground unit they control." Damage = the PRINTED cost (project ruling); gated > 0 so
    // a 0-cost play raises no useless prompt. The reactor is $opp (non-active); it targets the PLAYING
    // player's board. Mirrors TWI_210's drain path (proven interactive non-active-player reaction).
    if ($printedCost > 0) {
        $krayts = _SWUCountActiveUnitsWithCardID($opp, 'SHD_172');   // Galen-suppression + multi-copy aware
        // ⚠ Add ONE trigger carrying the COUNT (payload "cost~count"), NOT N identical triggers: two
        // identical reactive triggers hang the EffectStack flush (a pre-existing engine limitation, never
        // hit before because every prior reactive card was unique — Krayt is the first non-unique one).
        // The reaction loops the may-deal $count times, which is CR-equivalent for identical triggers.
        if ($krayts > 0) {
            AddTrigger($opp, 'SHD_172', 'SHD_172', $printedCost . '~' . $krayts);   // "cost~count" in the mzID slot
        }
    }
    // TWI_064 Ki-Adi-Mundi — "Coordinate - When an opponent plays their SECOND card each phase: You may
    // draw 2 cards." Fires only on the opponent's exactly-2nd card of the phase (SWU_CARDS_PLAYED was
    // incremented at the start of ActivateCard, so == 2 here means this is that 2nd card) and only while
    // the reactor's Coordinate is active.
    if (GlobalEffectCount($playingPlayer, 'SWU_CARDS_PLAYED') === 2 && IsCoordinateActive($opp)) {
        $kiadi = _SWUCountActiveUnitsWithCardID($opp, 'TWI_064');
        for ($i = 0; $i < $kiadi; $i++) {
            AddTrigger($opp, 'TWI_064', 'TWI_064', '');
        }
    }
}

// Batch E.1 — reactive "when YOU (the controller) play a card" observers. Mirror of
// SWUCollectOpponentPlayReactions but for the PLAYING player's own units. Called from the same
// three play sites (unit entry, upgrade attach, event play). $playedUID = the just-played unit's
// UniqueID (0 for events/upgrades) so an observer can exclude the card it was triggered by
// ("another …" — a played Aggression unit must not trigger its own copy).
// $playedAsUpgrade = the card was played AS AN UPGRADE (the Piloting path). A Piloting card's CardType
// is "Unit", so without this flag playing one as a pilot reads as "you played a unit" to every observer
// below — CR 17.c says the opposite ("A card with Piloting is considered an upgrade for the purpose of
// abilities that instruct a player to 'play an upgrade'"). Family-swept 2026-08-14 (candidate #7):
// every "when you play a unit" observer reads $isUnitPlay, every "an upgrade" observer $isUpgradePlay,
// and "a non-unit card" (SHD_217) counts a pilot-as-upgrade as non-unit.
function SWUCollectOwnPlayReactions(int $playingPlayer, string $playedCardID, int $playedUID = 0, bool $playedAsUpgrade = false, ?array $allowedUIDs = null): void {
    $isEvent       = strpos(CardType($playedCardID) ?? '', 'Event') !== false;
    $isUpgrade     = strpos(CardType($playedCardID) ?? '', 'Upgrade') !== false;
    $isAggression  = strpos(CardAspect($playedCardID) ?? '', 'Aggression') !== false;
    // Token Units have CardType "Token Unit", which contains "Unit" — so token plays count as units here.
    $isUnit        = strpos(CardType($playedCardID) ?? '', 'Unit') !== false;
    $isUnitPlay    = $isUnit && !$playedAsUpgrade;   // a Piloting card played as a pilot is NOT a unit play
    $isUpgradePlay = $isUpgrade || $playedAsUpgrade; // ...and IS an upgrade play (CR 17.c)
    $isCommandUnit = $isUnitPlay
                  && (strpos(CardAspect($playedCardID) ?? '', 'Command') !== false);
    foreach (GetUnitsInPlay($playingPlayer) as $u) {
        if (!empty($u->removed) || LostAbilities($u)) continue;   // SEC_046 Galen — a named observer doesn't react
        $cid = $u->CardID ?? '';
        $uid = intval($u->UniqueID ?? 0);
        // Event-play observer snapshot (the Bossk verdict): with an allowlist supplied, a unit that
        // was NOT in play when the event was played is no observer of it.
        if ($allowedUIDs !== null && !in_array($uid, $allowedUIDs, true)) continue;
        // HMW_115 Leia Organa, These Are My Friends: "When you play ANOTHER unit that costs 3 or less:
        // Heal 1 damage from your base." COST is always the PRINTED cost (never a discounted or
        // aspect-inflated one). Self-exclusion is by UniqueID, so her own arrival — she is cost 1 —
        // does not heal, while a SECOND copy of her would trigger the first.
        if ($cid === 'HMW_115' && $isUnitPlay && $uid !== $playedUID && intval(CardCost($playedCardID)) <= 3) {
            AddTrigger($playingPlayer, 'HMW_115', 'HMW_115', '');
        }
        // HMW_124 Luminara Unduli, Besieged General: "When you play a unit (including this one): You may
        // attack with a unit. It gets +2/+0 for this attack." "(including this one)" = NO self-exclusion,
        // so her own arrival triggers her (contrast HMW_115 just above, which is "another unit").
        if ($cid === 'HMW_124' && $isUnitPlay) {
            AddTrigger($playingPlayer, 'HMW_124', 'HMW_124', '');
        }
        // SOR_182 Bossk: "When you play an event: you may deal 2 damage to a unit."
        if ($cid === 'SOR_182' && $isEvent) {
            AddTrigger($playingPlayer, 'SOR_182', 'SOR_182', '');
        }
        // TWI_184 Tactical Droid Commander: "When you play another Separatist unit: you may exhaust a
        // unit that costs the same as or less than the played unit." Carries the played unit's cost.
        if ($cid === 'TWI_184' && $isUnitPlay
            && HasTrait($playedCardID, 'Separatist') && $uid !== $playedUID) {
            AddTrigger($playingPlayer, 'TWI_184', 'TWI_184', strval(intval(CardCost($playedCardID))));
        }
        // SOR_143 Fighters for Freedom: "When you play another [Aggression] card: you may deal 1 to a base."
        if ($cid === 'SOR_143' && $isAggression && $uid !== $playedUID) {
            AddTrigger($playingPlayer, 'SOR_143', 'SOR_143', '');
        }
        // SOR_109 Colonel Yularen: "When you play a [Command] unit (including this one): Heal 1 from
        // your base." No self-exclusion — "including this one" means Yularen's own play counts too.
        if ($cid === 'SOR_109' && $isCommandUnit) {
            AddTrigger($playingPlayer, 'SOR_109', 'SOR_109', '');
        }
        // LAW_003 Agent Kallus (deployed) — "When you play a Heroism card: heal 2 from your base."
        // Mandatory, no decision → heal immediately.
        if ($cid === 'LAW_003' && strpos(CardAspect($playedCardID) ?? '', 'Heroism') !== false) {
            OnHealBase($playingPlayer, $playingPlayer, 2);
        }
        // LOF_087 Eighth Brother: "When you play another unit: you may use the Force → give a unit +2/+2."
        if ($cid === 'LOF_087' && $isUnitPlay && $uid !== $playedUID) {
            AddTrigger($playingPlayer, 'LOF_087', 'LOF_087', '');
        }
        // TWI_080 Poggle the Lesser: "When you play another unit: you may exhaust this unit → create a Battle Droid."
        if ($cid === 'TWI_080' && $isUnitPlay && $uid !== $playedUID) {
            AddTrigger($playingPlayer, 'TWI_080', 'TWI_080', '', strval($uid));
        }
        // TWI_101 Mas Amedda: "When you play another unit: you may exhaust this unit → search top 4 for a unit, draw."
        if ($cid === 'TWI_101' && $isUnitPlay && $uid !== $playedUID) {
            AddTrigger($playingPlayer, 'TWI_101', 'TWI_101', '', strval($uid));
        }
        // TWI_216 Fives: "When you play an event: you may put a Clone unit from discard on the bottom → draw."
        if ($cid === 'TWI_216' && $isEvent) {
            AddTrigger($playingPlayer, 'TWI_216', 'TWI_216', '', strval($uid));
        }
        // TWI_018 Quinlan Vos (deployed) — "When you play a unit: you may deal 1 damage to an enemy unit
        // that costs the same as or less than the played unit." (Carry the played unit's cost.)
        if ($cid === 'TWI_018' && $isUnitPlay && $uid !== $playedUID) {
            AddTrigger($playingPlayer, 'TWI_018D', 'TWI_018', '', strval(intval(CardCost($playedCardID))));
        }
        // LOF_249 Luke Skywalker: "When you play another <uq> unit: may use the Force → give an Experience
        // and a Shield token to this unit." Carries Luke's UID so the reaction can target him.
        if ($cid === 'LOF_249' && $isUnitPlay
            && CardUnique($playedCardID) && $uid !== $playedUID) {
            AddTrigger($playingPlayer, 'LOF_249', 'LOF_249', '', strval($uid));
        }
        // ASH_060 Cobb Vanth: "When you play another unit: you may deal 2 damage to THIS unit. If you do,
        // give a Shield token to THAT (the played) unit." Carries Cobb's UID + the played unit's UID.
        if ($cid === 'ASH_060' && $isUnitPlay && $uid !== $playedUID && $playedUID > 0) {
            AddTrigger($playingPlayer, 'ASH_060', 'ASH_060', '', $uid . ',' . $playedUID);
        }
        // ASH_102 Ravager: "When you play a unit: you may have it deal damage equal to its power to a unit
        // in the same arena." Carries the played unit's UID (the dealer). Not "another" — Ravager's own
        // play counts; but the played unit must still be in play (a unit-type entry).
        if ($cid === 'ASH_102' && $isUnitPlay && $playedUID > 0) {
            AddTrigger($playingPlayer, 'ASH_102', 'ASH_102', '', strval($playedUID));
        }
        // SHD_096 Maz Kanata: "When you play ANOTHER unit: give an Experience token to this unit."
        // Mandatory, targets self → resolve immediately.
        if ($cid === 'SHD_096' && $isUnitPlay && $uid !== $playedUID) {
            DoGiveExperienceToken($playingPlayer, $u->GetMzID());
        }
        // SHD_239 Toro Calican: "When you play ANOTHER Bounty Hunter unit: you may deal 1 damage to it. If
        // you do, ready this unit. Once each round." Carries the played unit's UID + Toro's UID.
        if ($cid === 'SHD_239' && $isUnitPlay
            && HasTrait($playedCardID, 'Bounty Hunter') && $uid !== $playedUID && $playedUID > 0
            && GlobalEffectCount($playingPlayer, 'SWU_SHD239_USED') <= 0) {
            AddTrigger($playingPlayer, 'SHD_239', 'SHD_239', $playedUID . ',' . $uid);
        }
        // SHD_255 Lady Proxima: "When you play ANOTHER Underworld card: you may deal 1 damage to a base."
        if ($cid === 'SHD_255' && _SWUCardHasTrait($playingPlayer, $playedCardID, 'Underworld') && $uid !== $playedUID) { // LAW_212 Malakili: owned Creatures count as Underworld when played
            AddTrigger($playingPlayer, 'SHD_255', 'SHD_255', '');
        }
        // SHD_018 The Mandalorian (deployed) — "When you play an upgrade: you may exhaust an enemy unit
        // with 6 or less remaining HP." (No leader-exhaust cost on the deployed side.)
        if ($cid === 'SHD_018' && $isUpgradePlay) {
            AddTrigger($playingPlayer, 'SHD_018D', 'SHD_018', '', '6');
        }
        // SHD_217 Tobias Beckett: "When you play a NON-UNIT card: you may exhaust a unit that costs the
        // same as or less than the card you played. Use this ability only once each round." The once/round
        // marker is consumed when the exhaust actually resolves (SHD_217#0), not on trigger.
        if ($cid === 'SHD_217' && !$isUnitPlay
            && GlobalEffectCount($playingPlayer, 'SWU_SHD217_USED') <= 0) {
            AddTrigger($playingPlayer, 'SHD_217', 'SHD_217', strval(intval(CardCost($playedCardID))));
        }
        // LOF_096 Obi-Wan Kenobi: "When you play a Force unit (including this one): this unit gains
        // Sentinel for this phase." No self-exclusion; grant immediately (no decision).
        if ($cid === 'LOF_096'
            && $isUnitPlay && HasTrait($playedCardID, 'Force')) {
            $obiMz = SWUFindMzByUID($uid);
            // CardID-based token (not bare 'SENTINEL') so the Active Effects popup shows Obi-Wan's
            // art as the source — registry row 'LOF_096' => GRANT_KEYWORD SENTINEL.
            if ($obiMz !== null) AddTurnEffect($obiMz, 'LOF_096');
        }
    }
    // ── Leader observers (undeployed leaders are NOT in GetUnitsInPlay) ──
    $isUnit = $isUnitPlay;   // leader observers below are all "when you play a unit" — pilot-as-upgrade excluded (CR 17.c)
    // ASH_017 Greef Karga — "When you play OR create a unit: you may exhaust this leader; if you do, give an
    // Advantage token to that unit." (The create half is hooked in SWUCreateUnitToken.)
    if ($isUnit && $playedUID > 0 && _SWULeaderReadyUndeployed($playingPlayer, 'ASH_017')) {
        AddTrigger($playingPlayer, 'ASH_017', 'ASH_017', '', strval($playedUID));
    } elseif ($isUnit && $playedUID > 0 && _SWULeaderDeployed($playingPlayer, 'ASH_017')) {
        AddTrigger($playingPlayer, 'ASH_017#1', 'ASH_017#1', '', strval($playedUID));   // deployed side: auto-give
    }
    // ASH_018 Grogu — "When you play a <uq> unit that costs 4 or more: if this leader is ready, you may
    // deploy him." (Grogu has no Epic Action; this trigger is his only deploy path.)
    if ($isUnit && CardUnique($playedCardID) && intval(CardCost($playedCardID)) >= 4
        && _SWULeaderReadyUndeployed($playingPlayer, 'ASH_018')) {
        AddTrigger($playingPlayer, 'ASH_018', 'ASH_018', '');
    }
    // TWI_018 Quinlan Vos (front) — "When you play a unit: you may exhaust this leader; if you do, deal 1
    // damage to an enemy unit that costs the same as the played unit." (Carry the played unit's cost.)
    if ($isUnit && _SWULeaderReadyUndeployed($playingPlayer, 'TWI_018')) {
        AddTrigger($playingPlayer, 'TWI_018', 'TWI_018', '', strval(intval(CardCost($playedCardID))));
    }
    // SHD_008 Boba Fett (front) — "When you play a unit that has 1 or more keywords: you may exhaust this
    // leader; if you do, give a friendly unit +1/+0 for this phase." Keyword count read off the played
    // unit's in-play object (includes granted keywords).
    if ($isUnit && $playedUID > 0 && _SWULeaderReadyUndeployed($playingPlayer, 'SHD_008')) {
        $pObj = GetZoneObject(SWUFindMzByUID($playedUID));
        if ($pObj !== null && !empty($pObj) && _SWUCountDistinctKeywords($pObj) >= 1) {
            AddTrigger($playingPlayer, 'SHD_008', 'SHD_008', '');
        }
    }
    // SHD_014 Cad Bane (front) — "When you play an Underworld card: you may exhaust this leader; if you
    // do, an opponent chooses a unit they control. Deal 1 damage to it." (Any card type with the trait.)
    if (_SWUCardHasTrait($playingPlayer, $playedCardID, 'Underworld') && _SWULeaderReadyUndeployed($playingPlayer, 'SHD_014')) { // LAW_212 Malakili: owned Creatures count as Underworld when played
        AddTrigger($playingPlayer, 'SHD_014', 'SHD_014', '');
    }
    // SHD_018 The Mandalorian (front) — "When you play an upgrade: you may exhaust this leader; if you
    // do, exhaust an enemy unit with 4 or less remaining HP."
    if ($isUpgradePlay && _SWULeaderReadyUndeployed($playingPlayer, 'SHD_018')) {
        AddTrigger($playingPlayer, 'SHD_018', 'SHD_018', '', '4');
    }
}

// SOR_182 Bossk reaction: "you may deal 2 damage to a unit." (Any unit — Bossk always self-qualifies.)
function BosskPlayEventReaction(int $player): void {
    global $playerID;
    $playerID = intval($player);
    $targets = _SWUCollectUnits(-1, fn($o) => true);
    if (empty($targets)) return;
    SWUQueueMayChooseTarget(intval($player), $targets,
        "Bossk:_deal_2_to_a_unit?", "Deal_2_damage_to_a_unit", "DEAL_UNIT_DAMAGE|2");
}

// SOR_143 Fighters for Freedom reaction: "you may deal 1 damage to a base." (Either base.)
function FFFPlayAggressionReaction(int $player): void {
    global $playerID;
    $playerID = intval($player);
    SWUQueueMayChooseTarget(intval($player), ["myBase-0", "theirBase-0"],
        "Deal_1_to_a_base?", "Deal_1_damage_to_a_base", "DEAL_BASE_DAMAGE|1");
}

// SOR_109 Colonel Yularen reaction: mandatory heal 1 from the controller's own base (no decision).
function YularenHealReaction(int $player): void {
    OnHealBase(intval($player), intval($player), 1);
}

// TWI_210 Cunning reaction dispatcher: queue the ready-or-exhaust choice for the TWI_210 controller.
// TWI_064 Ki-Adi-Mundi — reactive "may draw 2 cards" when the opponent plays their 2nd card each phase.
// $player = the reactor (Ki-Adi's controller). Optional → YESNO; the continuation draws 2 on YES.
function KiAdiMundiDrawReaction(int $player): void {
    DecisionQueueController::AddDecision(intval($player), "YESNO", "-", 1, tooltip: "Draw_2_cards?");
    DecisionQueueController::AddDecision(intval($player), "CUSTOM", "TWI_064#0", 1);
}

function CunningOpponentPlayedReaction(int $player): void {
    global $playerID;
    $playerID = intval($player);
    // Collect ALL units (any arena, any player) — "a unit" has no restriction.
    $allUnits = _SWUCollectUnits(-1, fn($o) => true);
    if (empty($allUnits)) return; // no units in play — effect is a no-op
    // Present the mode choice first; the unit-choose handler reads $lastDecision to know the mode.
    DecisionQueueController::AddDecision(intval($player), "OPTIONCHOOSE", "Ready&Exhaust", 1, "Ready_or_exhaust_a_unit?");
    DecisionQueueController::AddDecision(intval($player), "CUSTOM", "TWI_210#1|" . implode('&', $allUnits), 1);
}

// SHD_172 Krayt Dragon — reactive "when an opponent plays a card." $reactor = Krayt's controller (non-
// active); $payload = "cost~count" (printed cost + how many Krayts the reactor controls). Queue an
// intermediate CUSTOM so the target MZMAYCHOOSE is built under $playerID = $reactor (DispatchTrigger
// restores $playerID after this fn, so we must NOT queue the relative-mzID choose here directly — same
// discipline as SHD_246 / TWI_210's continuation). SHD_172#0/#1 loop the may-deal once per Krayt.
function Shd172Reaction(int $reactor, string $payload): void {
    $pp     = explode('~', $payload);
    $amount = intval($pp[0] ?? 0);
    $count  = intval($pp[1] ?? 0);
    if ($amount <= 0 || $count <= 0) return;
    DecisionQueueController::AddDecision(intval($reactor), "CUSTOM", "SHD_172#0|{$amount}|{$count}", 1);
}

// ─── Granted "When Defeated" registry — SINGLE SOURCE OF TRUTH ───────────────────────────────
// A unit can GAIN a "When Defeated" ability from three places. Each grant dispatches under its OWN
// per-card trigger type (not the generic 'WhenDefeated' window), so every consumer must agree on the
// same list:
//   • CollectWhenDefeatedTriggers  — fires them on a REAL defeat.
//   • JTL_039 Chimaera             — activates one on demand on a LIVING unit.
//   • JTL_002 Thrawn / JTL_169 Shadow Caster — re-use one via SWUUseWhenDefeatedAbility($grantedType).
// Keeping the list in one place is load-bearing: a hand-maintained second copy is exactly how Thrawn
// silently lost six granted-WD cases (fixed session 82) and how Chimaera lost ALL of them (fixed here).
//
// Grant mechanisms:
//   1. ATTACHED UPGRADE  — an upgrade subcard on the unit grants the ability.
//   2. PHASE/TURN EFFECT — an event stamped a marker into the unit's TurnEffects.
//   3. FIELD PRESENCE    — the controller controls a unit that grants to its fellow units.

// Upgrade CardID => param-builder name (or null). The builder supplies the value passed in the
// trigger's mzID/extraParams slot for grants whose effect depends on the HOST, snapshotted while the
// host is still intact (the host is gone by dispatch time on a real defeat).
function _SWUGrantedWDUpgradeRegistry(): array {
    return [
        'JTL_073' => null,  // Grim Valor          — "you may exhaust a unit"
        'SHD_104' => null,  // Inspiring Mentor    — "give an Experience token to another friendly unit"
        'TS26_52' => null,  // Sith Traditions     — "give an Experience token to a friendly unit"
        'TS26_35' => null,  // Ahsoka's Lightsabers— "may Shield an enemy → next event -2"
        'SEC_039' => null,  // Creditor's Claim    — "you may defeat a unit with 3 or less remaining HP"
        'SEC_156' => null,
        'ASH_134' => null,  // Warrior's Legacy    — "create a Mandalorian token"
        'TWI_218' => null,  // Droid Cohort        — "create a Battle Droid token"
        'TWI_169' => null,  // Clone Cohort        — "create a Clone Trooper token"
        'LAW_141' => '_SWUGrantedWDParamHostCost',  // Targeted For Removal — Credits = host's printed cost
        'LAW_201' => '_SWUGrantedWDParamHostReady', // Thermal Detonator    — only if host was ready
    ];
}
function _SWUGrantedWDParamHostCost($hostObj, string $hostCardID): string {
    return (string)intval(CardCost($hostCardID));
}
function _SWUGrantedWDParamHostReady($hostObj, string $hostCardID): string {
    return (intval($hostObj->Status ?? 0) === 1) ? '1' : '0';
}

// TurnEffects markers stamped by an event that grants a When Defeated for the phase.
function _SWUGrantedWDTurnEffectRegistry(): array {
    return [
        'TWI_103',  // Pyrrhic Assault      — "deal 2 damage to an enemy unit"
        'TWI_129',  // In Defense of Kamino — "create a Clone Trooper token" (friendly Republic units)
    ];
}

// Field-presence grants: $controller controls a unit that grants a When Defeated to its fellows.
// $hostCardID is the unit that would be using the ability (a granter never grants to itself).
function _SWUFieldPresenceGrantedWDTypes(int $controller, string $hostCardID): array {
    $types = [];
    if ($controller <= 0) return $types;
    // ASH_063 Bo-Katan's Gauntlet — "Each OTHER friendly NON-TOKEN unit gains: create a Mandalorian token."
    if ($hostCardID !== 'ASH_063'
        && strpos(CardType($hostCardID) ?? '', 'Token') === false
        && _SWUCountUnitsWithCardID($controller, 'ASH_063') > 0) {
        $types[] = 'ASH_063';
    }
    // SOR_105 General Krell — "Each OTHER friendly unit gains: you may draw a card."
    if ($hostCardID !== 'SOR_105' && _SWUCountUnitsWithCardID($controller, 'SOR_105') > 0) {
        $types[] = 'SOR_105';
    }
    return $types;
}

// All GRANTED When-Defeated trigger types currently available on a LIVING unit, in a stable order
// (upgrades → phase effects → field presence). Does NOT include the unit's own innate When Defeated —
// callers test that separately with HasWhenDefeatedAbility($cardID).
function _SWUGrantedWhenDefeatedTypes(int $controller, string $mzID): array {
    $obj = GetZoneObject($mzID);
    if (SWUObjGone($obj)) return [];
    $hostCardID = $obj->CardID ?? '';
    $types = [];
    $upgReg = _SWUGrantedWDUpgradeRegistry();
    if (is_array($obj->Subcards ?? null)) {
        foreach ($obj->Subcards as $sub) {
            $scid = is_array($sub) ? ($sub['CardID'] ?? '')   : ($sub->CardID ?? '');
            $srem = is_array($sub) ? !empty($sub['removed'])  : !empty($sub->removed);
            if (!$srem && array_key_exists($scid, $upgReg)) $types[] = $scid;
        }
    }
    if (is_array($obj->TurnEffects ?? null)) {
        foreach (_SWUGrantedWDTurnEffectRegistry() as $te) {
            if (in_array($te, $obj->TurnEffects, true)) $types[] = $te;
        }
    }
    foreach (_SWUFieldPresenceGrantedWDTypes($controller, $hostCardID) as $t) $types[] = $t;
    return array_values(array_unique($types));
}

function CollectWhenDefeatedTriggers($activePlayer, array $defeatedCards): void {
    global $gPendingTriggers, $gExploitDeferTriggers, $gExploitDeferredBag;

    global $playerID;
    foreach ($defeatedCards as $d) {
        // ASH_063 Bo-Katan's Gauntlet — "Each OTHER friendly non-token unit gains: When Defeated:
        // create a Mandalorian token." Field-presence grant: a friendly non-token unit's defeat creates
        // a Mandalorian for its controller while they control an ASH_063 unit.
        $dctrl63 = intval($d['player'] ?? 0);
        if ($dctrl63 > 0 && in_array('ASH_063', _SWUFieldPresenceGrantedWDTypes($dctrl63, $d['cardID'] ?? ''), true)) {
            AddTrigger($dctrl63, 'ASH_063', 'ASH_063', '');
            _SWUAddShadowCasterGrantedReuse($dctrl63, 'ASH_063', ''); // JTL_169 Shadow Caster reuse of this granted WD
        }
        // SEC_046 Galen Erso — a named card that lost its abilities fires no When Defeated.
        if (HasWhenDefeatedAbility($d['cardID']) && !_SWUGalenSuppressesCard(intval($d['player'] ?? 0), $d['cardID'])) {
            AddTrigger($d['player'], 'WhenDefeated', $d['cardID'], $d['mzID']);
            // Snapshot the defeated unit's power WHILE its upgrades are still attached (they are at this
            // collection point), so a "deal damage equal to this unit's power" When-Defeated (JTL_104 Raddus)
            // reads the buffed value — by resolution time CleanupRemovedCards has stripped the subcards and
            // ObjectCurrentPower would return only the printed base.
            if (($d['cardID'] ?? '') === 'JTL_104' && !empty($d['mzID'])) {
                global $gWDPowerSnapshot;
                if (!isset($gWDPowerSnapshot) || !is_array($gWDPowerSnapshot)) $gWDPowerSnapshot = [];
                $rdSelf = GetZoneObject($d['mzID']);
                if ($rdSelf !== null) $gWDPowerSnapshot[$d['mzID']] = intval(ObjectCurrentPower($rdSelf));
            }
            // JTL_169 Shadow Caster — "When a friendly unit is defeated: you may use all of its
            // When Defeated abilities again." One reuse offer per controlled copy. Collected at
            // defeat time (defeat-event hook), distinct from Thrawn's use-time hook.
            foreach (array_merge(GetGroundArena($d['player']) ?? [], GetSpaceArena($d['player']) ?? []) as $u) {
                if (!empty($u->removed)) continue;
                if (($u->CardID ?? '') === 'JTL_169') {
                    AddTrigger($d['player'], 'JTL_169', $d['cardID'], $d['mzID']);
                }
            }
        }
        // Upgrade-granted When Defeated (JTL_073 Grim Valor: "Attached unit gains When Defeated: you may
        // exhaust a unit"). The defeated unit is still in the array (removed=true) with its subcards
        // intact at this collection point — resolve it under the active player's frame.
        if (!empty($d['mzID'])) {
            $savedDPID = $playerID;
            $playerID = intval($activePlayer);
            $defObj = GetZoneObject($d['mzID']);
            // Snapshot "was this defeated BY COMBAT DAMAGE" per mzID (marker set at the combat-defeat
            // sites in SWUCombatDamage), and consume the flag — read by ASH_028/ASH_191 whenDefeated.
            $GLOBALS['gCombatDefeatByMz'][$d['mzID']] = ($defObj !== null
                && GlobalEffectCount(intval($d['player'] ?? 0), 'SWU_COMBATDEF_' . intval($defObj->UniqueID ?? 0)) > 0);
            if ($defObj !== null) RemoveGlobalEffect(intval($d['player'] ?? 0), 'SWU_COMBATDEF_' . intval($defObj->UniqueID ?? 0));
            // A BLANKED unit has no When Defeated to fire — including ones it GAINED from an upgrade or a
            // phase effect. SEC_038 Condemn ("loses all other abilities" while attacking) is the sharp case:
            // an attacker wearing Condemn that dies during its own attack must not fire an upgrade-granted
            // When Defeated (SEC_039 Creditor's Claim). Same for SEC_046 Galen / LOF_202 Mind Trick /
            // SEC_054 Exiled from the Force. The unit's OWN When Defeated is already gated elsewhere; these
            // two GRANTED blocks were not.
            $defBlanked = ($defObj !== null && LostAbilities($defObj));
            // Phase-granted When Defeated abilities (event-stamped TurnEffects markers) — see
            // _SWUGrantedWDTurnEffectRegistry(). Detected on the (removed, still-intact) defeated object.
            if (!$defBlanked && $defObj !== null && is_array($defObj->TurnEffects ?? null)) {
                foreach (_SWUGrantedWDTurnEffectRegistry() as $teType) {
                    if (in_array($teType, $defObj->TurnEffects, true)) {
                        AddTrigger($d['player'], $teType, $teType, '');
                        _SWUAddShadowCasterGrantedReuse(intval($d['player']), $teType, ''); // JTL_169 Shadow Caster reuse
                    }
                }
            }
            if (!$defBlanked && $defObj !== null && is_array($defObj->Subcards ?? null)) {
                // Upgrade-granted When Defeated abilities — see _SWUGrantedWDUpgradeRegistry().
                // Each dispatches under its own per-card trigger type. Grants whose effect depends on
                // the HOST carry a param built here (the host is gone by dispatch time, and the
                // FlushTriggerBag path drops extraParams, so it rides in the mzID slot).
                $upgReg = _SWUGrantedWDUpgradeRegistry();
                foreach ($defObj->Subcards as $sub) {
                    $scid = is_array($sub) ? ($sub['CardID'] ?? '') : ($sub->CardID ?? '');
                    $srem = is_array($sub) ? !empty($sub['removed']) : !empty($sub->removed);
                    if ($srem || !array_key_exists($scid, $upgReg)) continue;
                    $builder = $upgReg[$scid];
                    $param   = ($builder === null) ? '' : $builder($defObj, $d['cardID'] ?? '');
                    AddTrigger($d['player'], $scid, $scid, $param);
                    _SWUAddShadowCasterGrantedReuse(intval($d['player']), $scid, $param); // JTL_169 Shadow Caster reuse
                }
                // SHD_001 Gar Saxon (deployed grant) — "Each friendly upgraded unit gains: When Defeated:
                // you may return an upgrade that was attached to this unit to its owner's hand." Field-
                // presence grant (fires while the unit's controller's leader is SHD_001). Snapshot the real
                // upgrade CardIDs now (subcards still intact). Resolved as a benefit-only auto-return in
                // SWUAfterAction's lazy sweep rather than a When-Defeated trigger: an ENEMY defeat queues
                // the controller's trigger on their (non-active) queue, which doesn't drain mid-attack
                // (subsystem gap #1). Returning an upgrade is always beneficial, so auto-resolve one.
                $dctrl1 = intval($d['player'] ?? 0);
                $ld1    = $dctrl1 > 0 ? SWUGetLeader($dctrl1) : null;
                if ($ld1 !== null && ($ld1->CardID ?? '') === 'SHD_001') {
                    $upgSnap = [];
                    foreach ($defObj->Subcards as $sub) {
                        $scid = is_array($sub) ? ($sub['CardID'] ?? '') : ($sub->CardID ?? '');
                        $srem = is_array($sub) ? !empty($sub['removed']) : !empty($sub->removed);
                        if (!$srem && $scid !== '' && strpos(CardType($scid) ?? '', 'Upgrade') !== false) $upgSnap[] = $scid;
                    }
                    if (!empty($upgSnap)) $GLOBALS['gShd001Pending'][] = ['owner' => $dctrl1, 'upgs' => $upgSnap];
                }
            }
            // Support (ASH) — A was defeated during a supported attack while bearing the grant. Fire the
            // supporting unit's "When Defeated" ability against A's mzID (so "this unit" = A). The marker
            // is still on the (removed) object at this collection point.
            if ($defObj !== null) {
                $sgDef = _SWUSupportGrant($defObj);
                if ($sgDef !== null && $sgDef['cardID'] !== '' && HasWhenDefeatedAbility($sgDef['cardID'])) {
                    AddTrigger($d['player'], 'SupportWhenDefeated', $sgDef['cardID'], $d['mzID']);
                }
            }
            // SEC_035 Darth Sion — "When Defeated: if this unit had 7+ power, return him to hand."
            // Snapshot his power NOW (Experience subcards still attached); the When Defeated closure
            // runs after they're stripped, so it reads base power without this. Keyed by mzID (the
            // same string the closure receives).
            if ($defObj !== null && ($d['cardID'] ?? '') === 'SEC_035') {
                global $gSec035DefeatSnapshot, $gSec035AttackPower;
                // "had 7 or more power" reads his power AT THE MOMENT OF DEFEAT. If he was defeated while
                // ATTACKING, that includes any "for this attack" bonus (e.g. Surprise Strike +3), which was
                // stashed at combat-power time (the SWU_ATK_POWER bonus is consumed before this point).
                $power = intval(ObjectCurrentPower($defObj));
                $uid035 = intval($defObj->UniqueID ?? 0);
                if (is_array($gSec035AttackPower ?? null) && isset($gSec035AttackPower[$uid035])) {
                    $power = max($power, intval($gSec035AttackPower[$uid035]));
                    unset($gSec035AttackPower[$uid035]);
                }
                $gSec035DefeatSnapshot[$d['mzID']] = [
                    'power' => $power,
                    'owner' => intval($defObj->Owner ?? $d['player']),
                ];
            }
            // ASH_195 Helgait — "When Defeated: distribute Advantage equal to THIS unit's power." Snapshot
            // its power NOW, resolved here under the active (defeating) player's frame where $d['mzID']
            // correctly points at Helgait; the closure runs under Helgait's controller's frame, where that
            // frame-relative mzID would resolve to a different unit (see the closure in CardDQHandlers.php).
            if ($defObj !== null && ($d['cardID'] ?? '') === 'ASH_195') {
                global $gAsh195DefeatSnapshot;
                $gAsh195DefeatSnapshot[$d['mzID']] = intval(ObjectCurrentPower($defObj));
            }
            // Granted custom Bounty (SHD_006 phase grant / SHD_123 upgrade grant) — snapshot the
            // reward(s) NOW while the (removed) object still carries its turn-effects + subcards, so the
            // bounty can be offered after cleanup. Each granted Bounty is an independent ability
            // (CR 13.b); the innate $Bounty_Cards bounty is offered separately. A reward = the source
            // CardID + a param (SHD_006: the discount 1/2; SHD_123: 1 if the host was unique → top 10).
            if ($defObj !== null) {
                global $gGrantedBountySnapshot;
                // Same builder the CAPTURE path uses (_SWUGrantedBountyRewards) — a Bounty fires on
                // "defeated OR captured", so both paths must produce an identical reward list.
                // (Exploit-sacrifice stays the accepted no-cover edge for the SHD_006/SHD_123 grants.)
                $rewards = _SWUGrantedBountyRewards($defObj, $d['cardID'] ?? '', intval($d['player'] ?? 0));
                // SHD_161 Stolen Landspeeder — its bounty is gated on "if YOU (the collector) own this
                // unit"; snapshot the owner now (the object is gone by the offer loop below).
                if (($d['cardID'] ?? '') === 'SHD_161') {
                    $GLOBALS['gShd161DefeatOwner'][$d['mzID']] = intval($defObj->Owner ?? $d['player']);
                }
                if (!empty($rewards)) { $GLOBALS['gGrantedBountySnapshot'][$d['mzID']] = $rewards; }
            }
            $playerID = $savedDPID;
        }
    }
    SWUCollectLeavePlayReactions($defeatedCards, true);

    // Exploit deferred-defeat-trigger bag (CR 16.d / Task 1.2):
    // When a unit is sacrificed for Exploit mid-payment, its WhenDefeated triggers,
    // leave-play reactions, AND bounty rewards must not fire immediately — they are
    // collected here (as typed entries) and parked in $gExploitDeferredBag so
    // SWUFlushExploitDeferredTriggers() can replay them alongside the played card's
    // WhenPlayed trigger.  The deferral activates whenever the flag is set, regardless
    // of whether $gPendingTriggers is non-empty — this ensures a unit with Bounty but
    // no WhenDefeated is also deferred (Bug B fix), and a unit with both does not lose
    // its bounty via an early return (Bug A fix).
    // General multi-clause "then" deferral (CR 8.29.1 + 7.6.14.a): while an event is between its clauses
    // (Collateral Damage's two "deal 2" hits), a first-clause defeat's When-Defeated / bounty must WAIT
    // until the whole event resolves. Serialized (SWU_DEFER_WD/_BAG SWUVars) so it survives the request
    // boundary between the clauses; SWUFlushDeferredWhenDefeated() replays it after the final clause.
    // Distinct from the transient, same-action Exploit park below.
    if (GetSWUVar('SWU_DEFER_WD', 'false') === 'true') {
        $bag = json_decode(GetSWUVar('SWU_DEFER_WD_BAG', '[]'), true);
        if (!is_array($bag)) $bag = [];
        foreach ($gPendingTriggers as $t) { $bag[] = ['__kind__' => 'trigger'] + $t; }
        global $Bounty_Cards;
        foreach ($defeatedCards as $d) {
            if (isset($Bounty_Cards[$d['cardID']]) && !_SWUGalenSuppressesCard(intval($d['player'] ?? 0), $d['cardID'])) {
                $bag[] = ['__kind__' => 'bounty', 'activePlayer' => OtherPlayer(intval($d['player'] ?? $activePlayer)), 'cardID' => $d['cardID']];
            }
        }
        SetSWUVar('SWU_DEFER_WD_BAG', json_encode($bag));
        $gPendingTriggers = [];
        return;
    }

    if (!empty($gExploitDeferTriggers)) {
        // Park trigger descriptors (tagged with __kind__ = 'trigger').
        foreach ($gPendingTriggers as $t) {
            $gExploitDeferredBag[] = ['__kind__' => 'trigger'] + $t;
        }
        $gPendingTriggers = [];

        // Park bounty descriptors (tagged with __kind__ = 'bounty'). SEC_046 Galen — a named unit has no
        // Bounty. Collector = the opponent of the sacrificed unit's controller (CR 13.f) — Exploit fodder
        // is always the exploiter's own unit, so the OPPONENT collects at flush time.
        global $Bounty_Cards;
        foreach ($defeatedCards as $d) {
            if (isset($Bounty_Cards[$d['cardID']]) && !_SWUGalenSuppressesCard(intval($d['player'] ?? 0), $d['cardID'])) {
                $gExploitDeferredBag[] = [
                    '__kind__'    => 'bounty',
                    'activePlayer' => OtherPlayer(intval($d['player'] ?? $activePlayer)),
                    'cardID'      => $d['cardID'],
                ];
            }
        }
        return;
    }

    FlushTriggerBag($activePlayer);

    // Bounty (CR 7.6.3 / 13.f): after WhenDefeated triggers, offer the bounty reward to the OPPONENT of
    // the defeated unit's controller — usually the defeating $activePlayer, but when a player's OWN unit
    // dies during their action (attacker counter-death, sacrifice), the opponent still collects.
    // SEC_046 Galen Erso — a named defeated unit has lost its Bounty (no reward offered).
    global $Bounty_Cards;
    foreach ($defeatedCards as $d) {
        if (isset($Bounty_Cards[$d['cardID']]) && !_SWUGalenSuppressesCard(intval($d['player'] ?? 0), $d['cardID'])) {
            $collector = OtherPlayer(intval($d['player'] ?? $activePlayer));
            // SHD_161 Stolen Landspeeder — thread "collector owns the defeated unit" (param 1/0) from
            // the pre-cleanup owner snapshot; its reward only fires when the collector owns it.
            $param = '';
            if ($d['cardID'] === 'SHD_161') {
                $own = $GLOBALS['gShd161DefeatOwner'][$d['mzID'] ?? ''] ?? 0;
                $param = '|' . (intval($own) === $collector ? 1 : 0);
                unset($GLOBALS['gShd161DefeatOwner'][$d['mzID'] ?? '']);
            }
            DecisionQueueController::AddDecision($collector, "YESNO", "-", 1, tooltip:"Collect_bounty?");
            DecisionQueueController::AddDecision($collector, "CUSTOM", "SWUCollectBounty|{$d['cardID']}{$param}", 1);
        }
    }

    // Granted custom bounties (SHD_006 phase grant / SHD_123 upgrade grant) + conditional innate
    // (SHD_033/SHD_165), snapshotted above while the object still had its turn-effects/subcards/status.
    // Each is an independent ability (CR 13.b) offered to the opponent of the bountied unit's
    // controller (CR 13.f — see the innate loop above for the self-death nuance).
    global $gGrantedBountySnapshot;
    foreach ($defeatedCards as $d) {
        $mz = $d['mzID'] ?? '';
        if ($mz === '' || empty($gGrantedBountySnapshot[$mz])) continue;
        if (!_SWUGalenSuppressesCard(intval($d['player'] ?? 0), $d['cardID'] ?? '')) {
            $collector = OtherPlayer(intval($d['player'] ?? $activePlayer));
            foreach ($gGrantedBountySnapshot[$mz] as $rw) {
                DecisionQueueController::AddDecision($collector, "YESNO", "-", 1, tooltip:"Collect_bounty?");
                DecisionQueueController::AddDecision($collector, "CUSTOM", "SWUCollectBounty|{$rw['reward']}|{$rw['param']}", 1);
            }
        }
        unset($gGrantedBountySnapshot[$mz]);
    }
}

// ─── JTL Phase 23 — reuse a "When Defeated" ability ───────────────────────────
// Re-invoke primitive: fire a card's registered When-Defeated ability on demand,
// decoupled from an actual defeat. Routed through the trigger system so the dispatch
// path also re-collects the Thrawn "when you use a When Defeated ability" reaction
// (JTL_002), letting uses chain (Thrawn + Shadow Caster can use one ability up to
// three times). On a Thrawn/Shadow-Caster replay the source unit is already in discard;
// $mzID is passed as-is — the JTL When-Defeated pool targets other units/players/bases,
// so it doesn't need the dead unit's live state (self-referential reads degrade). Used
// by JTL_039 Chimaera (a living unit), JTL_002, and JTL_169.
// $grantedType (non-null) = the When-Defeated was GRANTED by an attached upgrade and dispatches via a
// per-card trigger type (e.g. 'JTL_073'), not the generic 'WhenDefeated' window. Re-arm that same type
// + snapshot mzID (the granted handlers don't depend on the now-defeated host being present).
function SWUUseWhenDefeatedAbility(int $owner, string $cardID, string $mzID, ?string $grantedType = null): void {
    if ($grantedType !== null) {
        AddTrigger($owner, $grantedType, $grantedType, $mzID);
        FlushTriggerBag($owner);
        return;
    }
    if (!HasWhenDefeatedAbility($cardID)) return;
    AddTrigger($owner, 'WhenDefeated', $cardID, $mzID);
    FlushTriggerBag($owner);
}

// A unit holding MORE than one "When Defeated" (its innate one plus any it gained) must let the
// controller pick which to use when an ability activates one on demand (JTL_039 Chimaera). Options are
// labelled by the CardID that SUPPLIES the ability — the host's own CardID for the innate one, the
// granting card's CardID for each granted one — which is stable, unambiguous, and directly assertable.
function SWUQueueChooseWhenDefeatedAbility(int $owner, string $hostCardID, string $mzID, array $options): void {
    $labels = [];
    foreach ($options as $o) $labels[] = ($o === null) ? $hostCardID : $o;
    DecisionQueueController::AddDecision($owner, "OPTIONCHOOSE", implode('&', $labels), 1,
        tooltip:"Choose_a_When_Defeated_ability_to_use");
    DecisionQueueController::AddDecision($owner, "CUSTOM", "JTL_039#1|{$owner}|{$hostCardID}|{$mzID}", 1);
}

// JTL_002 Grand Admiral Thrawn — usability of the "use that ability again" reaction.
// Undeployed: may exhaust the (ready) leader. Deployed leader unit: no cost, once each round.
function _SWUThrawnReuseMode(int $owner): ?string {
    if (_SWULeaderDeployed($owner, 'JTL_002')) {
        return SWUHasUseAvailable(SWUGetLeader($owner)) ? 'deployed' : null; // once/round via leader NumUses
    }
    if (_SWULeaderReadyUndeployed($owner, 'JTL_002')) return 'undeployed';
    return null;
}

// ── Per-card once-per-round budget via the NumUses field (Leader / GroundArena / SpaceArena / Base) ──
// NumUses = remaining uses this round (default 1). The parser writes -1 for an absent field (old
// gamestate) — normalize that to the default. Reset to 1 for every card at RegroupPhaseStart so the
// budget refreshes each round. Replaces the ad-hoc SWU_*_USED GlobalEffect flags.
function SWUNumUses($obj): int {
    $n = intval($obj->NumUses ?? 1);
    return $n < 0 ? 1 : $n; // -1 = parser's "absent" sentinel → treat as the default
}
function SWUHasUseAvailable($obj): bool {
    return $obj !== null && SWUNumUses($obj) > 0;
}
function SWUConsumeUse($obj): void {
    if ($obj !== null) $obj->NumUses = max(0, SWUNumUses($obj) - 1);
}
// Refresh every card's once-per-round budget (called from RegroupPhaseStart). Repeatable base Actions
// with a per-GAME budget ($baseActionNumUses, e.g. LOF_022) are EXEMPT — their NumUses must persist
// across rounds, so they are not refilled here.
function SWUResetAllNumUses(): void {
    global $baseActionNumUses;
    for ($p = 1; $p <= SeatCountForGame(); $p++) {
        foreach ([GetLeader($p) ?? [], GetGroundArena($p) ?? [], GetSpaceArena($p) ?? [], GetBase($p) ?? []] as $zone) {
            for ($i = 0; $i < count($zone); $i++) {
                if (empty($zone[$i]->removed) && !isset($baseActionNumUses[$zone[$i]->CardID ?? ''])) {
                    $zone[$i]->NumUses = 1;
                }
            }
        }
    }
}

function _SWUExhaustUndeployedLeader(int $player, string $cardID): void {
    $leaderArr = &GetLeader($player);
    for ($i = 0; $i < count($leaderArr); $i++) {
        if (!empty($leaderArr[$i]->removed)) continue;
        if (($leaderArr[$i]->CardID ?? '') === $cardID) { $leaderArr[$i]->Ready = false; break; }
    }
}

// JTL_009 Boba Fett (undeployed leader) — "When you deal NON-COMBAT damage: you may exhaust this leader;
// if you do, deal 1 indirect damage to a player." Called by the non-combat damage funnels after the
// damage is applied, for the dealing player. The SWU_BOBA_009_PENDING guard keeps at most one offer
// outstanding; the leader exhausts on accept, so the reaction's own indirect (a base hit) can't re-fire
// it. Combat damage is excluded by the $gInCombatDamage flag at the call site.
function _SWUCollectBobaNonCombatReaction(int $dealer): void {
    if ($dealer <= 0) return;
    if (!_SWULeaderReadyUndeployed($dealer, 'JTL_009')) return;
    if (GlobalEffectCount($dealer, 'SWU_BOBA_009_PENDING') > 0) return;
    AddGlobalEffects($dealer, 'SWU_BOBA_009_PENDING');
    DecisionQueueController::AddDecision($dealer, "YESNO", "-", 1,
        tooltip:"Exhaust_Boba_Fett_to_deal_1_indirect_damage?");
    DecisionQueueController::AddDecision($dealer, "CUSTOM", "JTL_009#0|{$dealer}", 1);
}

// Use-time hook (JTL_002 Thrawn): after any When-Defeated ability resolves under $owner, offer the
// reuse. The SWU_THRAWN_REUSE_PENDING guard keeps at most one outstanding offer, so a chained replay
// (which also dispatches WhenDefeated) can't stack duplicate prompts before the first is answered.
// Mode is re-checked at resolve time (Thrawn may have exhausted meanwhile). Called from DispatchTrigger.
// $grantedType (non-null) = an upgrade-granted When-Defeated ability that dispatched via its per-card
// trigger type — the unit gained it, so Thrawn re-uses it the same as an innate one.
function SWUCollectThrawnReuse(int $owner, string $cardID, string $mzID, ?string $grantedType = null): void {
    if ($grantedType === null && !HasWhenDefeatedAbility($cardID)) return;
    $guardKey = 'SWU_THRAWN_REUSE_PENDING|' . $cardID . '|' . $mzID . '|' . ($grantedType ?? '');
    if (GlobalEffectCount($owner, $guardKey) > 0) return;
    if (_SWUThrawnReuseMode($owner) === null) return;
    AddGlobalEffects($owner, $guardKey);
    DecisionQueueController::AddDecision($owner, "YESNO", "-", 1,
        tooltip:"Use_that_When_Defeated_ability_again_(Thrawn)?");
    DecisionQueueController::AddDecision($owner, "CUSTOM", "THRAWN_REUSE|{$owner}|{$cardID}|{$mzID}|" . ($grantedType ?? ''), 1);
}

// ── LAW_014 Enfys Nest — "When you use an 'On Attack' ability: use that ability again." ──
// Direct mirror of JTL_002 Thrawn's When-Defeated reuse, on the On-Attack window instead.
// Re-invoke an On-Attack ability by re-dispatching it on the same attacker mzID. The mode gate +
// PENDING guard bound this to exactly one replay (the cost makes a second offer return mode null).
// $fromUpgrade = the ability was GRANTED by an attached upgrade ("attached unit gains: On Attack: …")
// — re-dispatch via the OnAttackFromUpgrade seam ($cardID is the upgrade's, $mzID the host unit).
function SWUUseOnAttackAbility(int $owner, string $cardID, string $mzID, bool $fromUpgrade = false): void {
    global $onAttackAbilities;
    if (!isset($onAttackAbilities["{$cardID}:0"])) return;
    AddTrigger($owner, $fromUpgrade ? 'OnAttackFromUpgrade' : 'OnAttack', $cardID, $mzID);
    FlushTriggerBag($owner);
}

// Usability of Enfys's reaction. Undeployed (front): pay 2 resources AND exhaust the (ready) leader.
// Deployed leader unit: no cost, once each round (leader NumUses budget).
function _SWUEnfysReuseMode(int $owner): ?string {
    if (_SWULeaderDeployed($owner, 'LAW_014')) {
        return SWUHasUseAvailable(SWUGetLeader($owner)) ? 'deployed' : null;
    }
    if (_SWULeaderReadyUndeployed($owner, 'LAW_014') && SWUTotalPaymentCapacity($owner) >= 2) return 'undeployed';
    return null;
}

// Use-time hook (called from DispatchTrigger after an On-Attack ability resolves under $owner). The
// PENDING guard keeps at most one outstanding offer; mode is re-checked at resolve time. Only the
// attacker-controller's own On-Attack abilities reach here ($owner = the attacking player). Covers
// both innate On-Attack and upgrade-GRANTED On-Attack ("attached unit gains: On Attack: …", $fromUpgrade).
function SWUCollectEnfysReuse(int $owner, string $cardID, string $mzID, bool $fromUpgrade = false): void {
    global $onAttackAbilities;
    if (!isset($onAttackAbilities["{$cardID}:0"])) return;
    if (GlobalEffectCount($owner, 'SWU_ENFYS_REUSE_PENDING') > 0) return;
    if (_SWUEnfysReuseMode($owner) === null) return;
    AddGlobalEffects($owner, 'SWU_ENFYS_REUSE_PENDING');
    DecisionQueueController::AddDecision($owner, "YESNO", "-", 1,
        tooltip:"Use_that_On_Attack_ability_again_(Enfys_Nest)?");
    DecisionQueueController::AddDecision($owner, "CUSTOM", "ENFYS_REUSE|{$owner}|{$cardID}|{$mzID}|" . ($fromUpgrade ? '1' : '0'), 1);
}

// Dispatch target for the Shadow Caster (JTL_169) reuse trigger collected at defeat time.
// $grantedType (non-null) = the reuse is of a GRANTED When-Defeated ability (dispatched via its per-card
// trigger type, e.g. 'TWI_129'), so skip the innate-WD gate — the unit GAINED that ability. This is the
// Shadow-Caster analog of the Thrawn (JTL_002) / Chimaera (JTL_039) granted-WD support; without it
// Shadow Caster silently ignored event-/upgrade-/field-granted When Defeateds (only innate ones were
// offered). For a granted type $cardID carries the granting card's ID and $mzID carries the param the
// original dispatch used (empty for token-creation grants).
function ShadowCasterReuseTrigger(int $owner, string $cardID, string $mzID, ?string $grantedType = null): void {
    if ($grantedType === null && !HasWhenDefeatedAbility($cardID)) return;
    DecisionQueueController::AddDecision($owner, "YESNO", "-", 1,
        tooltip:"Use_its_When_Defeated_ability_again_(Shadow_Caster)?");
    DecisionQueueController::AddDecision($owner, "CUSTOM",
        "SHADOW_CASTER_REUSE|{$owner}|{$cardID}|{$mzID}|" . ($grantedType ?? ''), 1);
}

// True if $player controls at least one non-removed Shadow Caster (JTL_169) in an arena.
function _SWUControlsShadowCaster(int $player): bool {
    if ($player <= 0) return false;
    foreach (array_merge(GetGroundArena($player) ?? [], GetSpaceArena($player) ?? []) as $u) {
        if (empty($u->removed) && ($u->CardID ?? '') === 'JTL_169') return true;
    }
    return false;
}

// Queue a Shadow Caster (JTL_169) reuse offer for a GRANTED When-Defeated ability on a defeated unit,
// but only if that unit's controller ($owner) controls a Shadow Caster. $param is the value the original
// granted dispatch carried in its mzID slot (host cost / ready flag / '' for token-creation grants) —
// threaded through so the reuse resolves identically. Called from CollectWhenDefeatedTriggers alongside
// each granted-When-Defeated trigger add, mirroring the SWUCollectThrawnReuse calls in DispatchTrigger.
function _SWUAddShadowCasterGrantedReuse(int $owner, string $grantedType, string $param): void {
    if (!_SWUControlsShadowCaster($owner)) return;
    AddTrigger($owner, 'JTL_169G', $grantedType, $param);
}

// Drain all static DQ entries for both players after each action.
// Called by EngineActionRunner after every mode if the function exists.
// Processes RESOLVE_TRIGGER and other CUSTOM/SYSTEM entries until a
// non-static decision (MZCHOOSE, YESNO, etc.) blocks further progress.
function ProcessGoldfishAutomation(): bool {
    $madeProgress = false;
    $dqController = new DecisionQueueController();
    // Drain EVERY live seat's static queue after each action, not just seats 1/2 — otherwise a
    // non-active seat's reaction to another player's action (e.g. P3's Gideon Hask SOR_036 "when an
    // enemy unit is defeated" firing off a P1↔P2 trade) sits pending until that seat next acts.
    // 2-player games have no SeatOrder → fall back to [1,2] (byte-identical drain).
    $seats = GetLiveSeatsArray();
    if (empty($seats)) $seats = [1, 2];
    for ($cycle = 0; $cycle < 64; ++$cycle) {
        $before = [];
        foreach ($seats as $s) $before[$s] = count(GetDecisionQueue($s));
        foreach ($seats as $s) $dqController->ExecuteStaticMethods($s);
        // A defeat resolved INSIDE this drain (e.g. a non-active player's When Defeated that defeats a
        // unit) parks any "if this would be defeated, you may instead …" replacement. SWUAfterAction
        // already flushed before this drain began, and it is the only other flush point — so without
        // this the bag is never drained and the would-be-defeated unit is stranded in play forever,
        // neither defeated nor replaced. Flushing here queues the offer, which changes the queue counts
        // and therefore costs one more (terminating) cycle: the offer is interactive, so the following
        // cycle drains nothing new and the loop goes stable.
        SWUFlushDeferredReplacements();
        $stable = true;
        foreach ($seats as $s) { if (count(GetDecisionQueue($s)) !== $before[$s]) { $stable = false; break; } }
        if ($stable) break;
        $madeProgress = true;
    }
    return $madeProgress;
}

// DQ handler: resolve a single trigger from the bag.
global $customDQHandlers;
// TRAITOROUS_REVERT|<hostOwner>|<hostUID> — the queued "becomes unattached → owner takes control back"
// half of SOR_122 / JTL_083 (see the SWUDefeatUpgrade chokepoint for why it is queued at block 2).
// No-ops if the host has left play or control already reverted by the time it fires.
// XPLAYER_ATTACK_END_RELAY|<attackerPlayer>|<cardID>|<attackerUID> — a survival-gated "When Attack
// Ends" trigger deferred behind the DEFENDER-controller's parked When-Defeateds (see the collection
// gate in CollectAfterAttackTriggers). Fires on the defender-controller's queue AFTER their triggers
// resolve: re-evaluates survival by UID and only then hands the trigger back to the attacker's queue.
// A dead attacker here = the roster card's "if this unit survived" is FALSE → the trigger is dropped.
$customDQHandlers["XPLAYER_ATTACK_END_RELAY"] = function($player, $parts, $lastDecision) {
    global $playerID;
    $savedPID   = $playerID;
    $atkPlayer  = intval($parts[0] ?? 0);
    $cardID     = (string)($parts[1] ?? '');
    $atkUID     = intval($parts[2] ?? 0);
    if ($atkPlayer <= 0 || $cardID === '' || $atkUID <= 0) return;
    $trigType   = ($parts[3] ?? '') !== '' ? (string)$parts[3] : 'OnAttackEnd';
    $playerID = $atkPlayer;                     // resolve the attacker in ITS controller's frame
    $mz = SWUFindMzByUID($atkUID);
    $o  = ($mz !== null) ? GetZoneObject($mz) : null;
    if ($o !== null && empty($o->removed) && intval($o->UniqueID ?? 0) === $atkUID) {
        DecisionQueueController::AddDecision($atkPlayer, "CUSTOM",
            "RESOLVE_TRIGGER|{$trigType}|{$cardID}|{$mz}", 1);
    }
    $playerID = $savedPID;
};

// ATTACK_END_ORDER_PICK|<attackerPlayer>|<cardID>|<attackerUID>|<triggerType> — resolves the
// cross-player order choice raised by _SWUAttackEndCrossPlayerOrderSeam. "You" delivers the
// attack-end trigger to the active player now (their triggers resolve first; the opponent's
// parked When-Defeateds drain after). Anything else ("Opponent") parks an
// XPLAYER_ATTACK_END_RELAY behind the opponent's When-Defeateds so survival is re-checked
// after they resolve; if their queue already drained, the survival re-check runs inline.
$customDQHandlers["ATTACK_END_ORDER_PICK"] = function($player, $parts, $lastDecision) {
    global $playerID;
    $savedPID  = $playerID;
    $atkPlayer = intval($parts[0] ?? 0);
    $cardID    = (string)($parts[1] ?? '');
    $aeUID     = intval($parts[2] ?? 0);
    $trigType  = ($parts[3] ?? '') !== '' ? (string)$parts[3] : 'OnAttackEnd';
    if ($atkPlayer <= 0 || $cardID === '' || $aeUID <= 0) return;
    if ($lastDecision === 'You') {
        $playerID = $atkPlayer;
        $mz = SWUFindMzByUID($aeUID);
        $o  = ($mz !== null) ? GetZoneObject($mz) : null;
        if ($o !== null && empty($o->removed) && intval($o->UniqueID ?? 0) === $aeUID) {
            DecisionQueueController::AddDecision($atkPlayer, "CUSTOM",
                "RESOLVE_TRIGGER|{$trigType}|{$cardID}|{$mz}", 1);
        }
        $playerID = $savedPID;
        return;
    }
    $relayed = false;
    for ($seat = 1; $seat <= SeatCountForGame() && !$relayed; $seat++) {
        if ($seat === $atkPlayer) continue;
        foreach (GetDecisionQueue($seat) as $entry) {
            if (!empty($entry->removed)) continue;
            if (($entry->Type ?? '') !== 'CUSTOM') continue;
            if (strpos((string)($entry->Param ?? ''), 'RESOLVE_TRIGGER|WhenDefeated|') !== 0) continue;
            // One block AFTER the When-Defeated entry: its targeted-damage continuations queue at
            // ITS block and must fully resolve before survival is re-checked (Raddus-shaped WDs).
            DecisionQueueController::AddDecision($seat, "CUSTOM",
                "XPLAYER_ATTACK_END_RELAY|{$atkPlayer}|{$cardID}|{$aeUID}|{$trigType}",
                intval($entry->Block ?? 1) + 1);
            $relayed = true;
            break;
        }
    }
    if (!$relayed) {
        $playerID = $atkPlayer;
        $mz = SWUFindMzByUID($aeUID);
        $o  = ($mz !== null) ? GetZoneObject($mz) : null;
        if ($o !== null && empty($o->removed) && intval($o->UniqueID ?? 0) === $aeUID) {
            DecisionQueueController::AddDecision($atkPlayer, "CUSTOM",
                "RESOLVE_TRIGGER|{$trigType}|{$cardID}|{$mz}", 1);
        }
        $playerID = $savedPID;
    }
    $playerID = $savedPID;
};

$customDQHandlers["TRAITOROUS_REVERT"] = function($player, $parts, $lastDecision) {
    global $playerID;
    $savedPID  = $playerID;
    $hostOwner = intval($parts[0] ?? 0);
    $hostUID   = intval($parts[1] ?? 0);
    if ($hostOwner <= 0 || $hostUID <= 0) return;
    $playerID = $hostOwner;                       // resolve + take control in the OWNER's frame
    $mz = SWUFindMzByUID($hostUID);
    if ($mz !== null) {
        $o = GetZoneObject($mz);
        if ($o !== null && empty($o->removed) && intval($o->Controller ?? $hostOwner) !== $hostOwner) {
            SWUTakeControlOfUnit($hostOwner, $mz);
        }
    }
    $playerID = $savedPID;
};

$customDQHandlers["RESOLVE_TRIGGER"] = function($player, $parts, $lastDecision) {
    global $gTriggerDepth, $playerID;
    $savedPID    = $playerID;
    $playerID    = intval($player);
    $triggerType = $parts[0] ?? '';
    $cardID      = $parts[1] ?? '';
    $mzID        = $parts[2] ?? '';

    $gTriggerDepth++;
    DispatchTrigger($player, $triggerType, $cardID, $mzID);
    // Flush any nested triggers the ability closure just collected (e.g. Vader defeating a
    // unit whose When Defeated also triggers). They queue at higher depth, resolving first.
    FlushTriggerBag($player);
    $gTriggerDepth--;
    $playerID = $savedPID;
};

// JTL_002 Thrawn — resolve the "use that When Defeated ability again" offer. Always clears the
// pending guard; on YES pays the cost (undeployed: exhaust leader / deployed: once-per-round flag)
// and re-invokes. Re-checks usability (a prior link in the chain may have consumed Thrawn).
$customDQHandlers["THRAWN_REUSE"] = function($player, $parts, $lastDecision) {
    $owner       = intval($parts[0] ?? $player);
    $cardID      = $parts[1] ?? '';
    $mzID        = $parts[2] ?? '';
    $grantedType = ($parts[3] ?? '') !== '' ? $parts[3] : null;
    RemoveGlobalEffect($owner, 'SWU_THRAWN_REUSE_PENDING|' . $cardID . '|' . $mzID . '|' . ($grantedType ?? ''));
    if ($lastDecision !== "YES") return;
    $mode = _SWUThrawnReuseMode($owner);
    if ($mode === null) return;
    if ($mode === 'undeployed') _SWUExhaustUndeployedLeader($owner, 'JTL_002');
    else SWUConsumeUse(SWUGetLeader($owner)); // deployed: spend the once/round NumUses budget
    SWUUseWhenDefeatedAbility($owner, $cardID, $mzID, $grantedType);
};

// LAW_014 Enfys Nest — resolve the "use that On Attack ability again" offer. Clears the pending guard;
// on YES pays the cost (undeployed: 2 resources + exhaust the leader / deployed: once-per-round) and
// re-invokes. Mode re-checked at resolve time.
$customDQHandlers["ENFYS_REUSE"] = function($player, $parts, $lastDecision) {
    $owner       = intval($parts[0] ?? $player);
    $cardID      = $parts[1] ?? '';
    $mzID        = $parts[2] ?? '';
    $fromUpgrade = ($parts[3] ?? '0') === '1';
    RemoveGlobalEffect($owner, 'SWU_ENFYS_REUSE_PENDING');
    if ($lastDecision !== "YES") return;
    $mode = _SWUEnfysReuseMode($owner);
    if ($mode === null) return;
    if ($mode === 'undeployed') { SWUPayInlineAbilityCost($owner, 2); _SWUExhaustUndeployedLeader($owner, 'LAW_014'); }
    else SWUConsumeUse(SWUGetLeader($owner)); // deployed: spend the once/round NumUses budget
    SWUUseOnAttackAbility($owner, $cardID, $mzID, $fromUpgrade);
};

// JTL_169 Shadow Caster — resolve the "use its When Defeated ability again" offer. $parts[3] (when
// non-empty) = the GRANTED trigger type; the reuse then re-arms that per-card type instead of the
// generic innate 'WhenDefeated' window (see SWUUseWhenDefeatedAbility).
$customDQHandlers["SHADOW_CASTER_REUSE"] = function($player, $parts, $lastDecision) {
    if ($lastDecision !== "YES") return;
    $owner       = intval($parts[0] ?? $player);
    $cardID      = $parts[1] ?? '';
    $mzID        = $parts[2] ?? '';
    $grantedType = ($parts[3] ?? '') !== '' ? $parts[3] : null;
    SWUUseWhenDefeatedAbility($owner, $cardID, $mzID, $grantedType);
};

// DQ handler: cleanup + swap turn player after all When Played triggers fully resolve.
$customDQHandlers["FINISH_PLAY_CARD"] = function($player, $parts, $lastDecision) {
    DecisionQueueController::CleanupRemovedCards();
    // An "Attack with a unit" event / Support-unit play whose combat already owns the after-action
    // (SWUCombatDamage at the end of the attack calls SWUAfterAction). Skip the duplicate turn pass.
    // The flag is a PERSISTED SWUVar so it survives the request boundary an interactive mid-attack
    // decision creates (see BeginSWUAttack) — a transient global would be lost on the fresh process,
    // letting this handler double-swap the turn = a free extra action. Consume it here.
    if (GetSWUVar('SWU_COMBAT_OWNS_AFTERACTION', '') === '1') {
        SetSWUVar('SWU_COMBAT_OWNS_AFTERACTION', '');
        return;
    }
    SWUAfterAction($player);
};

// Task 5.1 — TWI_210 Cunning event-play observer. Queued at block 5 during the event branch
// of ActivateCard so it fires after the event's own effects (block 1) but before FINISH_PLAY_CARD
// (block 10). $parts[0]=playingPlayer, $parts[1]=playedCardID, $parts[2]=resourcesPaid.
// Calls SWUCollectOpponentPlayReactions and immediately FlushTriggerBag for the playing player.
$customDQHandlers["TWI_210#0"] = function($player, $parts, $lastDecision) {
    $playingPlayer = intval($parts[0] ?? $player);
    $playedCardID  = $parts[1] ?? '';
    $resourcesPaid = intval($parts[2] ?? 0);
    if ($playedCardID === '') return;
    // Observer snapshot taken at event-play time (the Bossk verdict): units the event itself seated
    // are excluded from own-play reactions. '' = nothing was in play; an ABSENT 4th part (legacy
    // callers) = no filtering. (The opponent-side collectors are count-based, not per-unit, and an
    // event seating a unit under the OPPONENT's control is not a real scenario today — unfiltered.)
    $allowedUIDs = array_key_exists(3, $parts)
        ? array_map('intval', array_values(array_filter(explode(',', $parts[3]), 'strlen')))
        : null;
    SWUCollectOpponentPlayReactions($playingPlayer, $playedCardID, $resourcesPaid);
    // Batch E.1 — own-play reactions on event plays (Bossk's "when you play an event"; FFF on an Aggression event).
    SWUCollectOwnPlayReactions($playingPlayer, $playedCardID, 0, false, $allowedUIDs);
    FlushTriggerBag($playingPlayer);
};

// DQ handler: pop the chosen EffectStack entry and dispatch it.
// $parts[0] = EffectStack mzID of the chosen trigger (from MZCHOOSE result or auto-dispatch).
$customDQHandlers["RESOLVE_NEXT_TRIGGER"] = function($player, $parts, $lastDecision) {
    global $gTriggerDepth, $playerID;
    $savedPID = $playerID;
    $playerID = intval($player);

    // Auto-dispatch: RESOLVE_NEXT_TRIGGER|EffectStack-N → $parts[0] = "EffectStack-N" (contains '-').
    // After MZCHOOSE: RESOLVE_NEXT_TRIGGER|{player} → $parts[0] = player number; mzID is $lastDecision.
    $p0   = $parts[0] ?? '';
    $mzID = str_contains($p0, '-')
        ? $p0
        : (($lastDecision && $lastDecision !== '-' && $lastDecision !== '') ? $lastDecision : '');

    $entry = GetZoneObject($mzID);
    if (SWUObjGone($entry)) { $playerID = $savedPID; return; }

    $triggerType = $entry->TriggerType ?? '';
    $cardID      = $entry->CardID ?? '';
    $params      = $entry->Params ?? '';
    $controller  = intval($entry->Controller ?? $player);

    $entry->Remove();

    $paramParts = $params !== '' ? explode('|', $params) : [];
    $unitMzID   = $paramParts[0] ?? '';
    $extra      = array_slice($paramParts, 1);

    $gTriggerDepth++;
    DispatchTrigger($controller, $triggerType, $cardID, $unitMzID, $extra);
    $gTriggerDepth--;

    $playerID = $savedPID;
};

// DQ handler: called at block 20 after all interactive decisions from the current trigger resolve.
// Checks the EffectStack and either queues the next trigger or finalises the action.
// True if $player has a pending BLOCKING decision (one that requires input: MZCHOOSE/YESNO/etc.) on
// their queue. Static decisions (CUSTOM/SYSTEM/MZMOVE/PASSPARAMETER) drain without input and are NOT
// blocking — so a hopped SWU_TRIGGER_RESUME (a CUSTOM) doesn't count itself. Used by the combat resume
// to gate SWUCombatDamage behind a defender's On Defense reaction (LOF_047/067/252 combat-pause).
function _SWUPlayerHasBlockingDecision(int $player): bool {
    $q = GetDecisionQueue($player);
    if (empty($q)) return false;
    static $staticTypes = ['CUSTOM', 'SYSTEM', 'MZMOVE', 'PASSPARAMETER'];
    foreach ($q as $d) {
        if (!in_array($d->Type ?? '', $staticTypes, true)) return true;
    }
    return false;
}

// True if $player has ANY pending decision still owed — including the static/auto-resolving kinds
// (PASSPARAMETER, CUSTOM) that _SWUPlayerHasBlockingDecision deliberately ignores — other than an
// orchestration resume, which must never count itself. Used ONLY by the combat resume's hop-back:
// once the resume has moved to the other player's queue it can no longer drain the active player's,
// so anything still sitting there is pre-damage work that combat must wait for. (HMW_188 Giant Gorax:
// when the opponent's chosen mode leaves the caster a single legal target, the caster's pick is a
// PASSPARAMETER — not "blocking", but it still has to resolve before combat damage.)
function _SWUPlayerHasPendingWork(int $player): bool {
    $q = GetDecisionQueue($player);
    if (empty($q)) return false;
    foreach ($q as $d) {
        if (strpos((string)($d->Param ?? ''), 'SWU_TRIGGER_RESUME') === 0) continue;
        return true;
    }
    return false;
}

// Uniqueness rule (CR 29.3): defeat the copy the player chose, then continue the paused action.
// SWUDefeatUnit collects the defeated copy's WhenDefeated triggers (CR 29.3: those still resolve);
// FlushEntryTriggerBag dispatches them — if they need interactive resolution it queues
// SWU_TRIGGER_RESUME (which re-enters SWUAfterAction when done), otherwise we re-enter inline.
// Either way SWUAfterAction re-checks uniqueness, so a 3+ copy pile keeps prompting until singleton.
$customDQHandlers["UNIQUENESS_DEFEAT"] = function($player, $parts, $lastDecision) {
    if (SWUDecisionDeclined($lastDecision)) return; // mandatory — no decline
    global $playerID; $playerID = intval($player);
    $actingPlayer = intval($parts[0] ?? $player) ?: intval($player);  // cross-seat enforcement resumes the ACTOR
    SWUDefeatUnit(intval($player), $lastDecision);
    $flushed = FlushEntryTriggerBag(intval($player));
    DecisionQueueController::CleanupRemovedCards();
    if ($flushed === 0) SWUAfterAction($actingPlayer);
    // $flushed > 0: SWU_TRIGGER_RESUME (already queued) re-enters SWUAfterAction after the triggers resolve.
};

$customDQHandlers["SWU_TRIGGER_RESUME"] = function($player, $parts, $lastDecision) {
    global $playerID;
    $savedPID    = $playerID;
    $activePlayer = intval($parts[0] ?? $player);
    $playerID     = $activePlayer;

    // Continuation: "COMBAT|{attackerMzID}|{targetMzID}" when this resume drives a
    // combat attack. When the EffectStack empties, queue SWUCombatDamage instead of
    // finalising via SWUAfterAction. Forwarded verbatim on each re-queue.
    $continuation = $parts[1] ?? '';
    $contStr      = ($continuation !== '')
        ? "|{$continuation}|" . ($parts[2] ?? '') . "|" . ($parts[3] ?? '') . "|" . ($parts[4] ?? '')
        : '';

    $stack = GetEffectStack();
    $remaining = array_values(array_filter($stack, fn($e) => empty($e->removed ?? false)));

    if (empty($remaining)) {
        DecisionQueueController::CleanupRemovedCards();
        if ($continuation === 'COMBAT' || $continuation === 'MAULCOMBAT') {
            // A defender's On Defense reaction (Captain Typho's disclose, LOF_047/067/252, …) is a
            // NON-active-player decision that must resolve BEFORE combat damage. When it was resolved in
            // the active drain (the single/other branches below), its decision sits on the defender's
            // queue. If the other player still has a pending BLOCKING decision, hop this resume onto
            // their queue and wait — the re-fired resume commits combat once they're done. (Supersedes
            // the old SWU_PENDING_DEF_REACTION-gated hop; scoped to COMBAT so non-combat plays that queue
            // an opponent decision, e.g. a forced discard, still finalize normally.)
            $other = OtherPlayer($activePlayer);
            if (_SWUPlayerHasBlockingDecision($other)) {
                _SWUQueueOrchestration($other, "SWU_TRIGGER_RESUME|{$activePlayer}{$contStr}", 20);
                $playerID = $savedPID;
                return;
            }
            // …and a cross-player chain can bounce the pre-damage decision BACK to the active player:
            // HMW_188 Giant Gorax's On Attack has the OPPONENT choose a mode, and one of those modes then
            // has the CASTER choose a damage target. Once the resume has hopped onto the other player's
            // queue, the check above can no longer see that pending caster decision, so combat committed
            // ahead of it (the target then resolved against a board combat had already changed). Hop back.
            // Guarded on having already hopped away ($player !== $activePlayer) — a resume sitting behind
            // the active player's OWN block is ordered by its block number and must not re-queue itself.
            if ($player !== $activePlayer && _SWUPlayerHasPendingWork($activePlayer)) {
                _SWUQueueOrchestration($activePlayer, "SWU_TRIGGER_RESUME|{$activePlayer}{$contStr}", 20);
                $playerID = $savedPID;
                return;
            }
            SetSWUVar('SWU_PENDING_DEF_REACTION', '');
            $aMz = $parts[2] ?? '';
            $tMz = $parts[3] ?? '';
            $uid = $parts[4] ?? '0';
            if ($aMz !== '' && $tMz !== '') {
                // Queue combat damage onto the CURRENT drain's queue ($player — the active player normally,
                // or the defender when a hop resumed here) so it runs in the same drain rather than
                // stranding on the other player's queue. The trailing |{$activePlayer} carries the
                // attacker frame so SWUCombatDamage resolves "my…" mzIDs correctly regardless of $player.
                // MAULCOMBAT (TWI_135's two-defender attack) commits through its own handler; there
                // parts[3]/parts[4] are the two DEFENDER mzIDs, not a target + attacker UID.
                _SWUQueueOrchestration($player, $continuation === 'MAULCOMBAT'
                    ? "SWUMaulCombatDamage|{$aMz}|{$tMz}|{$uid}|{$activePlayer}"
                    : "SWUCombatDamage|{$aMz}|{$tMz}|{$uid}|{$activePlayer}", 1);
            }
        } else {
            // A BARE resume must not finalise while a COMBAT continuation is still queued: that resume
            // carries the pending SWUCombatDamage, whose own terminal runs the After Action once damage
            // resolves. Finalising here swaps the turn, then combat swaps it again — with two seats that
            // lands back on the acting player, i.e. a free extra action (bug #926).
            //
            // It happens when an On-Attack ability opens its own decision chain, which defers combat
            // damage past this resume: e.g. Cinta Kaz's When Played attack made with a unit piloted by
            // JTL_142 Darth Vader ("On Attack: deal 1 to a unit; if one is defeated, deal 1 to a unit or
            // base"). Observed order: JTL_142#0, JTL_142#1, bare resume (finalises), COMBAT resume,
            // SWUCombatDamage (finalises again).
            //
            // Deliberately narrow, on BOTH axes:
            //   • only a pending COMBAT continuation counts (a bare one may never reach a terminal), and
            //   • only when that combat will actually finalise. A SUPPORT bonus attack sets
            //     SWU_COMBAT_SKIP_AFTERACTION, so its combat terminal stands down and the outer action
            //     owns the After Action — deferring to it there strands the turn instead of double-
            //     swapping it. That is exactly what broke DoctorPershing and TheMandalorian's Support
            //     cases when this guard was first tried without the skip check.
            if (GetSWUVar('SWU_COMBAT_SKIP_AFTERACTION', '') !== '1') {
            foreach ([1, 2] as $_p) {
                foreach (GetDecisionQueue($_p) as $_e) {
                    $_param = (string)($_e->Param ?? '');
                    if (str_starts_with($_param, 'SWU_TRIGGER_RESUME') && strpos($_param, '|COMBAT') !== false) {
                        $playerID = $savedPID;
                        return;
                    }
                }
            }
            }
            // Chained "then (may) attack with another unit" (SOR_009 / SOR_103): an attack just
            // completed its full trigger resolution (the stack emptied). If one is armed, fire it
            // NOW — after the just-finished attack and any nested OnAttackEnd chain — and re-queue a
            // resume so SWUAfterAction fires once THIS chained attack also resolves. Else finalise.
            $chainSpec = GetSWUVar('SWU_CHAINED_ATTACK', '');
            if ($chainSpec !== '') {
                SetSWUVar('SWU_CHAINED_ATTACK', '');
                _SWUQueueOrchestration($activePlayer, "SWU_TRIGGER_RESUME|{$activePlayer}", 20);
                ChainedAttackTrigger($activePlayer, $chainSpec);
            } elseif (GetSWUVar('SWU_MONMOTHMA_LOOP', '') !== '') {
                // SEC_103 Mon Mothma — a looped attack just resolved; re-offer the next "attack with
                // another unit". Don't re-queue a resume here (each accepted attack's CollectAfterAttack-
                // Triggers queues the next one while the loop var is set); a decline clears the var so the
                // play's FINISH_PLAY_CARD finalizes the action.
                _SWUMonMothmaOffer($activePlayer);
            } elseif (GetSWUVar("SWU_SHD145_LOOP", "") !== "") {
                // SHD_145 Headhunting — same count-capped loop; re-offer the next of up to 3 attacks.
                _SWUShd145Offer($activePlayer);
            } elseif (GetSWUVar("SWU_TS26059_LOOP", "") !== "") {
                // TS26_59 Brothers — count-capped loop; re-offer the next of up to 2 unique-unit attacks.
                _SWUTs26059Offer($activePlayer);
            } else {
                SWUAfterAction($activePlayer);
            }
        }
        $playerID = $savedPID;
        return;
    }

    // Check if remaining triggers all belong to one player.
    $myRemaining    = array_filter($remaining, fn($e) => intval($e->Controller) === $activePlayer);
    $theirRemaining = array_filter($remaining, fn($e) => intval($e->Controller) !== $activePlayer);

    // Re-queue SWU_TRIGGER_RESUME for the next round at block 20, forwarding the continuation.
    // It must ride the queue that will actually DRAIN next, or it spins: when 2+ remaining triggers are
    // all the OPPONENT's, the ordering MZCHOOSE and its RESOLVE_NEXT_TRIGGER go on THEIR queue (below),
    // so a resume left on the active player's queue re-fires immediately, re-queues itself, and loops
    // forever — the active drain never blocks on the opponent's pending choice.
    // Previously unreachable: a normal attack has ONE defender, so "2+ triggers, all theirs" could not
    // arise. TWI_135 Darth Maul's two-defender attack (each defender with an On Defense) reaches it.
    // Every other shape keeps the active player as the resume owner, exactly as before.
    $resumeOwner = intval($activePlayer);
    if (count($remaining) > 1 && empty($myRemaining) && !empty($theirRemaining)) {
        $resumeOwner = intval($activePlayer) === 1 ? 2 : 1;
    }
    _SWUQueueOrchestration($resumeOwner, "SWU_TRIGGER_RESUME|{$activePlayer}{$contStr}", 20);

    if (count($remaining) === 1) {
        // Single trigger left: auto-dispatch via RESOLVE_NEXT_TRIGGER, onto the CURRENT drain's queue
        // ($player — the player whose ExecuteStaticMethods is running this resume), NOT the trigger's
        // controller. Queuing on the controller would strand a lone opponent trigger on their queue and
        // loop this resume; $player is always being drained now, so it runs. RESOLVE_NEXT_TRIGGER
        // dispatches under the entry's own Controller regardless, so the trigger still resolves under
        // the right player; if it queues a reaction for the OTHER player, the empty-stack hop above
        // waits for it next round.
        $e = $remaining[0];
        $stackIdx = array_search($e, $stack);
        _SWUQueueOrchestration($player,
            "RESOLVE_NEXT_TRIGGER|EffectStack-{$stackIdx}", 1);
    } elseif (!empty($myRemaining) && empty($theirRemaining)) {
        // Active player still has multiple triggers: MZCHOOSE.
        $targetStr = _SWUEffectStackTargetsForPlayer($activePlayer);
        DecisionQueueController::AddDecision($activePlayer, "MZCHOOSE", $targetStr, 1,
            tooltip:"Choose_trigger_to_resolve");
        _SWUQueueOrchestration($activePlayer, "RESOLVE_NEXT_TRIGGER|{$activePlayer}", 1);
    } elseif (empty($myRemaining) && !empty($theirRemaining)) {
        // Switch to other player's triggers.
        $other = intval($activePlayer) === 1 ? 2 : 1;
        $targetStr = _SWUEffectStackTargetsForPlayer($other);
        DecisionQueueController::AddDecision($other, "MZCHOOSE", $targetStr, 1,
            tooltip:"Choose_trigger_to_resolve");
        _SWUQueueOrchestration($other, "RESOLVE_NEXT_TRIGGER|{$other}", 1);
    } else {
        // Mixed: ask active player who goes first (shouldn't normally happen mid-resolution, but handle it).
        DecisionQueueController::AddDecision($activePlayer, "YESNO", "-", 1,
            tooltip:"Resolve_Which_Player_First?");
        _SWUQueueOrchestration($activePlayer,
            "SWU_TRIGGER_ORDER_CHOICE|{$activePlayer}", 1);
    }

    $playerID = $savedPID;
};

// DQ handler: active player chose YES (mine first) or NO (theirs first) for cross-player ordering.
$customDQHandlers["SWU_TRIGGER_ORDER_CHOICE"] = function($player, $parts, $lastDecision) {
    global $playerID;
    $savedPID     = $playerID;
    $activePlayer = intval($parts[0] ?? $player);
    $playerID     = $activePlayer;

    $mineFirst = ($lastDecision === 'YES' || $lastDecision === '1');
    $first  = $mineFirst ? $activePlayer : (intval($activePlayer) === 1 ? 2 : 1);
    $ids = array_values(array_filter(explode('&', _SWUEffectStackTargetsForPlayer($first))));

    if (count($ids) === 1) {
        // The chosen side has exactly ONE trigger — no order to pick, so skip the single-option
        // "Choose_trigger_to_resolve" MZCHOOSE (it just hangs the effect stack with one clickable card)
        // and auto-dispatch it. Queue onto the current drain ($player); RESOLVE_NEXT_TRIGGER dispatches
        // under the entry's own Controller, so a lone opponent trigger still resolves right.
        _SWUQueueOrchestration($player, "RESOLVE_NEXT_TRIGGER|{$ids[0]}", 1);
    } else {
        DecisionQueueController::AddDecision($first, "MZCHOOSE", implode('&', $ids), 1,
            tooltip:"Choose_trigger_to_resolve");
        _SWUQueueOrchestration($first, "RESOLVE_NEXT_TRIGGER|{$first}", 1);
    }

    $playerID = $savedPID;
};

// Ambush: player answered the "Ambush attack?" YESNO.
// $parts[0] = attackerMzID; $parts[1..] = target mzIDs (joined as &-separated parts).
global $customDQHandlers;
$customDQHandlers["SWUAmbushAnswer"] = function($player, $parts, $lastDecision) {
    global $playerID;
    $savedPID     = $playerID;
    $playerID     = intval($player);
    $attackerMzID = $parts[0] ?? '';
    $targetStr    = implode('&', array_slice($parts, 1));
    if ($lastDecision === "YES" || $lastDecision === "1") {
        AddTurnEffect($attackerMzID, 'SWU_AMBUSH_ATTACK'); // ASH_207 — "while attacking using Ambush, +2/+0"
        $targets = array_values(array_filter(explode('&', $targetStr), fn($t) => $t !== ''));
        if (count($targets) === 1) {
            // Only one valid target — auto-fire, no player choice needed.
            ExecuteSWUAttack($player, $attackerMzID, $targets[0]);
        } else {
            DecisionQueueController::AddDecision($player, "MZCHOOSE", $targetStr, 1, tooltip:"Choose_Ambush_target");
            DecisionQueueController::AddDecision($player, "CUSTOM", "SWUAmbushAttack|{$attackerMzID}", 1);
        }
    } else {
        // Declined — SWU_TRIGGER_RESUME (block 20) handles SWUAfterAction; just cleanup here.
        DecisionQueueController::CleanupRemovedCards();
    }
    $playerID = $savedPID;
};

// Ambush: player chose an attack target.
global $customDQHandlers;
$customDQHandlers["SWUAmbushAttack"] = function($player, $parts, $lastDecision) {
    global $playerID;
    $savedPID     = $playerID;
    $playerID     = intval($player);
    $attackerMzID = $parts[0] ?? '';
    if ($lastDecision === "PASS" || $lastDecision === "" || $lastDecision === "-") {
        // Passed on target — SWU_TRIGGER_RESUME handles SWUAfterAction.
        DecisionQueueController::CleanupRemovedCards();
    } else {
        ExecuteSWUAttack($player, $attackerMzID, $lastDecision);
    }
    $playerID = $savedPID;
};

// Support (ASH): player chose which friendly unit makes the supported attack (or declined via the
// MZMAYCHOOSE Pass button → '-'). On accept, lend S's other abilities to the chosen attacker and attack.
global $customDQHandlers;
$customDQHandlers["SWUSupportChooseAttacker"] = function($player, $parts, $lastDecision) {
    global $playerID;
    $savedPID  = $playerID;
    $playerID  = intval($player);
    $supportMz = $parts[0] ?? '';
    if ($lastDecision === "PASS" || $lastDecision === "" || $lastDecision === "-") {
        // Declined — the SWU_TRIGGER_RESUME (block 20) handles SWUAfterAction; just clean up.
        DecisionQueueController::CleanupRemovedCards();
    } else {
        _SWUSupportGrantAbilities(intval($player), $supportMz, $lastDecision);   // grants + BeginSWUAttack
    }
    $playerID = $savedPID;
};

// Advantage shed (ASH_T02) — resolves the attacker's "When attack ends: defeat this upgrade" as one bag
// slot. If other triggers are still pending AND 2+ tokens remain, offer "defeat 1" (to interleave with
// the other triggers) vs "defeat all". If nothing else is pending (or only 1 token), auto-defeat all.
// The current EffectStack entry was already Remove()'d in RESOLVE_NEXT_TRIGGER before this dispatch.
function _SWUResolveAdvantageShed(int $player, string $mzID): void {
    global $playerID; $playerID = $player;
    $unit = GetZoneObject($mzID);
    if (SWUObjGone($unit)) return;
    // ASH_149 Eviscerator — the controller's units don't shed Advantage after combat (skip the picker too).
    if (_SWUControlsCardInPlay(intval($unit->Controller ?? $player), 'ASH_149')) return;
    $count = _SWUCountAdvantageSubcards($unit);
    if ($count <= 0) return;
    $otherPending = 0;
    foreach (GetEffectStack() as $e) { if (empty($e->removed ?? false)) $otherPending++; }
    if ($count === 1 || $otherPending === 0) { _SWUDefeatAllAdvantageTokens($mzID); return; }
    DecisionQueueController::AddDecision($player, "OPTIONCHOOSE",
        "Defeat_1_Advantage_token&Defeat_all_Advantage_tokens", 1, "Advantage_tokens:_defeat_one_or_all?");
    DecisionQueueController::AddDecision($player, "CUSTOM", "AdvantageShed#0|{$mzID}", 1);
}
global $customDQHandlers;
$customDQHandlers["AdvantageShed#0"] = function($player, $parts, $lastDecision) {
    global $playerID; $playerID = intval($player);
    $mzID = $parts[0] ?? '';
    if ($lastDecision === 'Defeat_all_Advantage_tokens') {
        _SWUDefeatAllAdvantageTokens($mzID);
        return;
    }
    // "Defeat 1" (default) — defeat one, then re-enter the bag so any remaining tokens re-order with the
    // still-pending triggers (the block-20 SWU_TRIGGER_RESUME re-offers ordering each round).
    _SWUDefeatOneAdvantageToken($mzID);
    $unit = GetZoneObject($mzID);
    if ($unit !== null && empty($unit->removed) && _SWUCountAdvantageSubcards($unit) > 0) {
        AddEffectStack('ASH_T02', intval($player), 'AdvantageShed', $mzID);
    }
};

// Bounty: player answered the "Collect bounty?" YESNO.
global $customDQHandlers;
$customDQHandlers["SWUCollectBounty"] = function($player, $parts, $lastDecision) {
    global $playerID;
    $savedPID = $playerID;
    $playerID = intval($player);
    if ($lastDecision === "YES" || $lastDecision === "1") {
        $cardID = $parts[0] ?? '';
        switch ($cardID) {
            case 'TS26_27': { // Fortune and Glory's bounty — a friendly unit captures a non-leader unit
                $captors = array_merge(ZoneSearch("myGroundArena", AnyUnitFilter), ZoneSearch("mySpaceArena", AnyUnitFilter));
                if (!empty($captors)) {
                    SWUQueueChooseTarget(intval($player), $captors, "Choose_a_friendly_unit_to_capture_with", "TS26_27#1");
                    $savedPID = intval($player); // leave the collector frame for the queued MZCHOOSE validation
                }
                break;
            }
            case 'SHD_027': // Hylobon Enforcer — draw 1 card
            case 'SHD_095': // Clone Deserter — draw 1 card
            case 'SHD_134': // Guavian Antagonizer — draw 1 card
            case 'SHD_195': // Cartel Turncoat — draw 1 card
                DoDrawCard($player, 1);
                break;
            case 'SHD_185': // Doctor Evazan — ready up to 12 resources (fungible → auto-ready)
                SWUReadyResources(intval($player), 12);
                break;
            case 'SHD_221': // Wanted's granted bounty — ready 2 friendly resources
                SWUReadyResources(intval($player), 2);
                break;
            case 'SHD_211': // Fugitive Wookiee — exhaust a unit
                $targets = _SWUCollectUnits(0, fn($o) => true);
                SWUQueueChooseTarget(intval($player), $targets, 'Exhaust_a_unit', 'EXHAUST_UNIT');
                $savedPID = intval($player); // leave the collector frame for the queued MZCHOOSE validation
                break;
            case 'SHD_222': // Enticing Reward's granted bounty — search the top 10 for 2 non-unit cards,
                            // reveal + draw; THEN, if the host was NOT unique (param 0), discard a card
                            // from your hand (queued after the search finalize; SHD_222#0).
                DoTopDeckSearch(intval($player), 10,
                    fn($c) => stripos(CardType($c) ?? '', 'Unit') === false, 2);
                if (intval($parts[1] ?? 0) !== 1) {
                    DecisionQueueController::AddDecision(intval($player), "CUSTOM", "SHD_222#0", 1);
                }
                $savedPID = intval($player); // leave the collector frame for the queued search decisions
                break;
            case 'SHD_261': // Rich Reward's granted bounty — give an Experience token to each of up to 2 units
                $targets = _SWUCollectUnits(0, fn($o) => true);
                if (!empty($targets)) {
                    DecisionQueueController::AddDecision(intval($player), "MZMULTICHOOSE",
                        "0|" . min(2, count($targets)) . "|" . implode("&", $targets), 1,
                        tooltip:"Give_an_Experience_token_to_each_of_up_to_2_units");
                    DecisionQueueController::AddDecision(intval($player), "CUSTOM", "GIVE_EXP_EACH", 1);
                    $savedPID = intval($player); // leave the collector frame for the queued MZMULTICHOOSE
                }
                break;
            case 'SHD_068': // Public Enemy's granted bounty — give a Shield token to a unit
                $targets = _SWUCollectUnits(0, fn($o) => true);
                SWUQueueChooseTarget(intval($player), $targets,
                    'Give_a_Shield_token_to_a_unit', 'GIVE_SHIELD');
                $savedPID = intval($player); // leave the collector frame for the queued MZCHOOSE validation
                break;
            case 'SHD_071': { // Top Target's granted bounty — heal 4 (6 if the host was unique) from a unit or base
                $n = (intval($parts[1] ?? 0) === 1) ? 6 : 4;
                $targets = array_merge(_SWUCollectUnits(0, fn($o) => true), ['myBase-0', 'theirBase-0']);
                SWUQueueChooseTarget(intval($player), $targets,
                    "Heal_{$n}_damage_from_a_unit_or_base", "HEAL_TARGET|{$n}");
                $savedPID = intval($player); // leave the collector frame for the queued MZCHOOSE validation
                break;
            }
            case 'SHD_116': // Outlaw Corona — put the top card of your deck into play as a resource
            case 'SHD_125': // Price on Your Head's granted bounty — same effect
                            // (enters EXHAUSTED — no "and ready it" wording)
                // Compact first: a previous collection in this SAME decision pass (Bossk SHD_010's
                // re-collect) moved the old top card out and left its slot marked `removed`, and cleanup
                // has not run yet. Without this, $deck[0] is still that dead slot, the guard below skips,
                // and the second collection silently does nothing.
                DecisionQueueController::CleanupRemovedCards();
                $deck = GetDeck($player);
                if (!empty($deck) && !empty($deck[0]) && empty($deck[0]->removed)) {
                    SWURampResourceExhausted(intval($player), 'myDeck-0');
                }
                break;
            case 'SHD_161': // Stolen Landspeeder — if the collector OWNS the defeated unit (param 1,
                            // threaded from the defeat-time owner snapshot), play it from their discard
                            // for free and give it an Experience token. The replay is from DISCARD, so
                            // its own "played from your hand" When Played does NOT flip control. A
                            // CAPTURED copy never lands in discard (capture path passes no param → 0).
                if (intval($parts[1] ?? 0) === 1) {
                    $mz = _SWUFindDiscardMzID(intval($player), 'SHD_161');
                    if ($mz !== null) {
                        global $gTurnPlayer, $gPlayGrantExp;
                        $savedTP = $gTurnPlayer; $savedPass = GetSWUVar('PASS', '0');
                        $gPlayGrantExp = 1;
                        ActivateCard($player, $mz, true);   // free play; entry grants the Experience
                        $gPlayGrantExp = null;
                        $gTurnPlayer = $savedTP; SetSWUVar('PASS', $savedPass);
                        $savedPID = intval($player); // leave the collector frame after the nested play
                    }
                }
                break;
            case 'SHD_226': { // Unrefusable Offer — "Play this unit for free (under YOUR control). It enters
                              // play ready. At the start of the regroup phase, defeat it." $parts[1] =
                              // "<defeatedCardID>~<owner>". Plays the just-defeated unit from its OWNER's
                              // discard into the collector's arena, ready, tagged SWU_SNEAK_DEFEAT.
                $pp        = explode('~', strval($parts[1] ?? ''));
                $defCardID = $pp[0] ?? '';
                $owner     = intval($pp[1] ?? 0);
                if ($defCardID === '' || $owner <= 0) break;
                $disc = &GetDiscard($owner);
                $idx = -1;
                for ($i = count($disc) - 1; $i >= 0; $i--) {
                    if (!empty($disc[$i]->removed)) continue;
                    if (($disc[$i]->CardID ?? '') === $defCardID) { $idx = $i; break; }
                }
                if ($idx >= 0) {
                    $disc[$idx]->removed = true;
                    DecisionQueueController::CleanupRemovedCards();
                } elseif (!_SWUTakeCaptiveByCardID($owner, $defCardID)) {
                    break;   // neither in the owner's discard nor held as a captive → nothing to play
                }
                // (else: the unit left play by CAPTURE — taken out of captivity by the call above.)
                $collector = intval($player);
                $uid   = NextUniqueID();
                $arena = CardTargetArena($defCardID);
                $newCard = ($arena === 'SpaceArena')
                    ? AddSpaceArena($collector, CardID: $defCardID, Status: 1, Owner: $owner, Damage: 0, Controller: $collector, UniqueID: $uid)
                    : AddGroundArena($collector, CardID: $defCardID, Status: 1, Owner: $owner, Damage: 0, Controller: $collector, UniqueID: $uid);
                if ($newCard !== null) {
                    $newMz = $newCard->GetMzID();
                    AddTurnEffect($newMz, 'SWU_SNEAK_DEFEAT');            // defeated at the next regroup start
                    CollectEntryTriggers($collector, $defCardID, $newMz, $arena);   // "Play this unit" → its When Played fires
                    // CR 8.19.1.b — this seats a unit OUTSIDE the normal play path, and the uniqueness
                    // rule is only enforced from SWUAfterAction, which has already run by the time this
                    // bounty reward resolves. Without this the collector simply keeps two copies of a
                    // unique unit. Enforce for the collector here (the choose parks on their queue).
                    if (CardUnique($defCardID)) SWUEnforceUniqueness($collector);
                }
                $savedPID = $collector;   // leave the collector frame for any queued entry triggers
                break;
            }
            case 'SHD_006': // Jabba's granted bounty — "the next unit you play this phase costs N less"
                            // (N = the discount carried in parts[1]: 1 from the front Action, 2 deployed).
                $amt = max(1, intval($parts[1] ?? 1));
                for ($i = 0; $i < $amt; $i++) AddGlobalEffects($player, 'SWU_SHD006_DISCOUNT_NEXT');
                break;
            case 'SHD_123': // Bounty Hunter's Quarry — search the top 5 (10 if the bountied unit was
                            // unique) of YOUR deck for a unit costing 3 or less and play it for free.
                $n = (intval($parts[1] ?? 0) === 1) ? 10 : 5;
                if (count(GetDeck($player)) > 0) {
                    DoTopDeckPlay($player, $n,
                        fn($c) => stripos(CardType($c) ?? '', 'Unit') !== false && intval(CardCost($c)) <= 3,
                        3, 1);
                }
                break;
            case 'SHD_031': // The Client's granted bounty — heal 5 damage from a base
                SWUQueueChooseTarget(intval($player), ['myBase-0', 'theirBase-0'],
                    'Heal_5_damage_from_which_base?', 'HEAL_TARGET|5');
                $savedPID = intval($player); // leave the collector frame for the queued MZCHOOSE validation
                break;
            case 'SHD_033': // Synara San — deal 5 damage to a base (exhausted-only bounty)
                SWUQueueChooseTarget(intval($player), ['myBase-0', 'theirBase-0'],
                    'Deal_5_damage_to_which_base?', 'DEAL_BASE_DAMAGE|5');
                $savedPID = intval($player); // leave the collector frame for the queued MZCHOOSE validation
                break;
            case 'SHD_058': // Val — deal 3 damage to a unit (any unit; fizzles with none in play)
                $targets = _SWUCollectUnits(0, fn($o) => true);
                SWUQueueChooseTarget(intval($player), $targets,
                    'Deal_3_damage_to_a_unit', 'DEAL_UNIT_DAMAGE|3');
                $savedPID = intval($player); // leave the collector frame for the queued MZCHOOSE validation
                break;
            case 'SHD_167': // Wanted Insurgents — deal 2 damage to a unit
                $targets = _SWUCollectUnits(0, fn($o) => true);
                SWUQueueChooseTarget(intval($player), $targets,
                    'Deal_2_damage_to_a_unit', 'DEAL_UNIT_DAMAGE|2');
                $savedPID = intval($player); // leave the collector frame for the queued MZCHOOSE validation
                break;
            case 'SHD_165': // Unlicensed Headhunter (exhausted-only bounty) — heal 5 from YOUR base
                            // ("your" = the collector's; no target choice)
                OnHealBase(intval($player), intval($player), 5);
                break;
            case 'SHD_173': { // Guild Target's granted bounty — deal 2 (3 if the host was unique) to a base
                $n = (intval($parts[1] ?? 0) === 1) ? 3 : 2;
                SWUQueueChooseTarget(intval($player), ['myBase-0', 'theirBase-0'],
                    "Deal_{$n}_damage_to_which_base?", "DEAL_BASE_DAMAGE|{$n}");
                $savedPID = intval($player); // leave the collector frame for the queued MZCHOOSE validation
                break;
            }
            case 'SHD_176': // Death Mark's granted bounty — draw 2 cards
                DoDrawCard($player, 2);
                break;
        }
        // SHD_010 Bossk (deployed) — "When you collect a bounty: you may collect that bounty again. Use
        // this ability only once each round." After the reward above resolves, if the collector controls a
        // deployed Bossk, hasn't used it this round, and this isn't itself the re-collection (the global
        // re-entrancy guard), offer to run the SAME reward once more. Consumed on USE (the YES).
        if (empty($GLOBALS['gShd010Recollecting'])
            && GlobalEffectCount(intval($player), 'SWU_SHD010_USED') <= 0
            && _SWUCountUnitsWithCardID(intval($player), 'SHD_010') > 0) {
            DecisionQueueController::AddDecision(intval($player), "YESNO", "-", 1, tooltip:"Bossk:_collect_that_bounty_again?");
            DecisionQueueController::AddDecision(intval($player), "CUSTOM", "SHD_010#recollect|" . implode("|", $parts), 1);
            $savedPID = intval($player);   // leave the collector frame for the queued re-collect decisions
        }
    }
    $playerID = $savedPID;
};
// SHD_010 Bossk (deployed) re-collect — re-run the just-collected bounty reward once more (marked via the
// gShd010Recollecting guard so the re-run doesn't offer a third collection). Consumes the once/round flag.
$customDQHandlers["SHD_010#recollect"] = function($player, $parts, $lastDecision) {
    if (($lastDecision ?? '') !== 'YES') return;
    global $playerID, $customDQHandlers; $playerID = intval($player);
    // Re-check the once-each-round flag at RESOLVE time, not only at queue time. When one unit carries
    // TWO bounties (CR 13.b — each is an independent ability) both SWUCollectBounty handlers run, and so
    // queue their re-offers, before either re-offer is answered; at queue time the flag was still clear
    // for both. Without this the ability fires twice in a round — the second bounty also got doubled.
    // ⚠ Known remaining wart: the second re-offer is still PRESENTED (it was queued before the first was
    // answered) and simply does nothing when accepted. Suppressing that prompt needs the re-offers to be
    // drained one at a time with the pending list carried on the decision Param (the split-damage
    // _SWUSplitOfferStep pattern), since a transient global would not survive the request boundary.
    if (GlobalEffectCount(intval($player), 'SWU_SHD010_USED') > 0) return;
    AddGlobalEffects(intval($player), 'SWU_SHD010_USED');   // once each round — consumed on actual re-collect
    $GLOBALS['gShd010Recollecting'] = true;
    $customDQHandlers["SWUCollectBounty"](intval($player), $parts, 'YES');   // re-resolve the same reward
    $GLOBALS['gShd010Recollecting'] = false;
};

// Deal $amount non-combat damage to the unit at $unitMzID (perspective of $player).
// Handles defeat + When Defeated triggers. Shared by DEAL_UNIT_DAMAGE and
// ability closures (e.g. SOR_137) that need to damage a unit directly.
// Find the current relative mzID of the unit with $uid across all four arenas, or
// null if it's gone. Caller must have $playerID set (uses relative zone names).
// Use after a step that may have shifted indices (defeat/cleanup) to re-resolve a
// unit captured earlier by UniqueID.
function SWUFindMzByUID(int $uid): ?string {
    foreach (["myGroundArena", "mySpaceArena", "theirGroundArena", "theirSpaceArena"] as $zone) {
        foreach (ZoneSearch($zone, AnyUnitFilter) as $mz) {
            $o = GetZoneObject($mz);
            if ($o !== null && empty($o->removed) && intval($o->UniqueID ?? -1) === $uid) return $mz;
        }
    }
    return null;
}

// The NON-INTERACTIVE damage-prevention chain, shared by the single-target ability funnel
// (SWUDealDamageToUnit) and the divided-damage funnel (_SWUApplySplitHits) so the two cannot drift.
// Divided damage is still card-ability damage (CR 34/35.5), so every "can't be damaged" / reduction /
// Shield effect applies to each assigned share exactly as it would to a single-target hit; before this
// was factored out, the split funnel consulted ONLY the Shield and a Lurking TIE Phantom (SHD_187) took
// its full share of an Overwhelming Barrage.
// Returns the amount that actually lands. Sets $prevented when the WHOLE instance was prevented (the
// caller must apply nothing at all), and $shielded when a Shield token was what absorbed it (the caller
// queues its own prevented/shield-break animations, which differ per funnel).
// INTERACTIVE replacements (SEC_101 Amidala, ASH_062 The Mandalorian) are deliberately NOT here — each
// funnel offers those to the controller before reaching this point.
// ⚠ ORDER is load-bearing: reductions run BEFORE the Shield. A Shield absorbs an INSTANCE of damage, so
// if prevention has already reduced the instance to zero there is nothing left to absorb and the Shield
// must NOT be spent (SEC_042 Cassian Andor's prevent-2 vs a 2-damage ability).
function _SWUNonInteractiveDamagePrevention($obj, int $amount, int $player, ?string $sourceMzID,
                                            bool &$prevented, bool &$shielded): int {
    $prevented = false;
    $shielded  = false;
    if ($obj === null) return $amount;
    $isEnemyAbility = intval($player) !== intval($obj->Controller ?? $player);
    // "Can't be damaged by enemy card abilities" (SHD_187 Lurking TIE Phantom) — the whole instance.
    if ($isEnemyAbility && SWUAvoidsAbilityDamage($obj)) { $prevented = true; return 0; }
    // LOF_108 Malakili — "if a friendly Creature unit would deal damage to a friendly unit, prevent it".
    // Source-aware, so it only applies on a funnel that threads a source (divided damage is source-less).
    if ($sourceMzID !== null && _SWULof108PreventsCreatureDamage($sourceMzID, $obj)) { $prevented = true; return 0; }
    // SEC_042 Cassian Andor — "if an enemy card ability would deal damage to this unit, prevent 2".
    if (($obj->CardID ?? '') === 'SEC_042' && $isEnemyAbility) $amount = max(0, $amount - 2);
    $amount = _SWUApplyDamagePrevention($obj, $amount, false, $sourceMzID); // LOF_220 / SEC_050 / ASH_150
    // Shield (CR 8.31): absorbs the ENTIRE remaining instance from any source.
    if ($amount > 0 && SWUConsumeShieldToken($obj)) { $prevented = true; $shielded = true; return 0; }
    return $amount;
}

function SWUDealDamageToUnit(string $unitMzID, int $amount, int $player, ?string $sourceMzID = null, bool $skipPrevent = false): void {
    global $playerID;
    $saved    = $playerID;
    $playerID = intval($player);
    $unit     = GetZoneObject($unitMzID);
    if ($unit !== null && !($unit->removed ?? false)) {
        // ASH_196 Gorian Shard's Corsair — damage dealt by a friendly Underworld card (the threaded
        // source) is unpreventable: skip every prevention/reduction below and apply the full amount.
        if (!$skipPrevent && $amount > 0 && $sourceMzID !== null
            && _SWUDamageUnpreventable(GetZoneObject($sourceMzID))) {
            $unit->Damage = intval($unit->Damage) + $amount;
            SWUQueueDamageAnim($unitMzID, intval($amount), intval($player));
            $hp = ObjectCurrentHP($unit);
            if ($hp > 0 && intval($unit->Damage) >= $hp && !SWUImmuneToHpDefeat($unit)) {
                SWUDefeatUnit(intval($player), $unitMzID, false, true);
            }
            $playerID = $saved;
            return;
        }
        // SEC_101 Queen Amidala — interactive prevention of effect/ability damage. Offer her controller a
        // chance to defeat a trait-sharing friendly to prevent; defer this damage to AMIDALA_PREVENT_ABILITY
        // (which re-applies with $skipPrevent on decline). Indirect damage never reaches here (it writes
        // Damage directly), so it's unpreventable as required.
        if (!$skipPrevent && $amount > 0 && ($unit->CardID ?? '') === 'SEC_101') {
            $targets = _SWUAmidalaPreventTargets($unit);
            if (!empty($targets)) {
                $ctrl = intval($unit->Controller ?? $player);
                $uid  = intval($unit->UniqueID ?? 0);
                // Queue the prevent for Amidala's controller; the MZMAYCHOOSE waits on THEIR queue (so it
                // validates under their context when drained). Restore $playerID so the caller — e.g. an
                // opponent's event handler that does more after this damage — continues in its own frame.
                $targets = _SWUAmidalaPreventTargets($unit);   // re-collect under the controller's frame
                $tstr = $targets ? implode('&', $targets) : '';
                DecisionQueueController::AddDecision($ctrl, 'MZMAYCHOOSE', $tstr, 1,
                    tooltip: 'Defeat_a_trait-sharing_friendly_to_prevent_damage_to_Queen_Amidala?');
                // dontSkipOnPass: the continuation MUST run even when the MZMAYCHOOSE is PASSED (declined) —
                // otherwise the deferred damage is silently dropped instead of applied in full.
                DecisionQueueController::AddDecision($ctrl, 'CUSTOM', "AMIDALA_PREVENT_ABILITY|{$uid}|{$amount}|{$player}", 1, dontSkipOnPass: 1);
                $playerID = $saved;
                return;   // damage deferred to the handler
            }
        }
        // ASH_062 The Mandalorian — interactive prevention of effect/ability damage to ANOTHER friendly
        // unit. Offer the controller a chance to defeat a Shield on a friendly ASH_062; defer to
        // ASH062_PREVENT_ABILITY (which re-applies with $skipPrevent on decline / no shield). Skip when the
        // target IS an ASH_062 (its own Shielded keyword covers it — "another friendly unit" doesn't apply).
        if (!$skipPrevent && $amount > 0 && ($unit->CardID ?? '') !== 'ASH_062'
            && _SWUAsh062Provider($unit) !== null) {
            $ctrl = intval($unit->Controller ?? $player);
            $uid  = intval($unit->UniqueID ?? 0);
            DecisionQueueController::AddDecision($ctrl, 'YESNO', '-', 1,
                tooltip: 'Defeat_a_Shield_on_The_Mandalorian_to_prevent_damage_to_this_unit?');
            DecisionQueueController::AddDecision($ctrl, 'CUSTOM', "ASH062_PREVENT_ABILITY|{$uid}|{$amount}|{$player}", 1);
            $playerID = $saved;
            return;   // damage deferred to the handler
        }
        // Non-interactive prevention chain (SHD_187 immunity -> LOF_108 -> SEC_042 -> reductions ->
        // Shield), shared with the divided-damage funnel. This funnel is effect/ability damage only:
        // combat damage is applied inline in SWUCombatDamage, ASH_196 unpreventable already returned
        // above, and indirect damage never reaches here (it writes Damage directly), so indirect
        // correctly ignores Shields.
        $prevented = false; $shielded = false;
        $amount = _SWUNonInteractiveDamagePrevention($unit, $amount, intval($player), $sourceMzID, $prevented, $shielded);
        if ($shielded) {
            SWUQueuePreventedAnim($unitMzID, intval($player));
            SWUQueueShieldBreakAnim($unitMzID, intval($player));
        }
        if ($prevented) {
            $playerID = $saved;
            return;
        }
        $unit->Damage = intval($unit->Damage) + $amount;
        SWUQueueDamageAnim($unitMzID, intval($amount), intval($player));
        $hp = ObjectCurrentHP($unit);
        if ($hp > 0 && intval($unit->Damage) >= $hp && !SWUImmuneToHpDefeat($unit)) {
            // SWUDefeatUnit now collects WhenDefeated + leave-play reactions itself (single point).
            SWUDefeatUnit(intval($player), $unitMzID, false, true); // SBA "no remaining HP" (not an ability-defeat)
        }
        // JTL_009 Boba Fett — effect damage to a unit is always non-combat (combat damage to units never
        // routes through this funnel; it modifies Damage directly in SWUCombatDamage).
        if ($amount > 0) _SWUCollectBobaNonCombatReaction(intval($player));
        // "When damage is dealt to this unit" reactions. Call even when this damage defeated the unit —
        // SEC_143 fires regardless (no "survives" clause); the $survived flag gates the survival-only ones.
        if ($amount > 0) _SWUOnUnitDamaged($unit, intval($amount), false, empty($unit->removed));
    }
    $playerID = $saved;
}

// Deal a divided-damage assignment SIMULTANEOUSLY. $assignmentStr is the MZSPLITASSIGN result —
// comma-separated "mzID:amount" pairs. All assigned damage is applied first (so a unit killed by
// its share can't stale a co-target's mzID), then defeats resolve in a single sweep. Targets are
// snapshotted by UniqueID and re-resolved with SWUFindMzByUID during the sweep (SWUDefeatUnit
// cleans up and shifts indices per defeat). Source-less: damage is unattributed (matches "deal N
// damage divided among units" cards — SOR_135). Caller need not set $playerID; saved/restored here.
function SWUDealSplitDamage(int $player, string $assignmentStr): void {
    if ($assignmentStr === '' || $assignmentStr === '-' || $assignmentStr === 'PASS') return;
    global $playerID;
    $saved    = $playerID;
    $playerID = intval($player);

    // Phase 0: resolve each "mzID:amount" to a (UniqueID, amount) hit. Nothing is mutated yet,
    // so the submitted mzIDs are still valid; capture UID so the sweep survives reindexing.
    $hits = [];
    foreach (explode(',', $assignmentStr) as $pair) {
        $p = explode(':', $pair);
        if (count($p) < 2) continue;
        $amt = intval($p[1]);
        if ($amt <= 0) continue;
        $obj = GetZoneObject(trim($p[0]));
        if (SWUObjGone($obj)) continue;
        $hits[] = ['uid' => intval($obj->UniqueID ?? 0), 'amount' => $amt];
    }

    // Split hits into those whose target has an INTERACTIVE damage-replacement (SEC_101 Queen Amidala —
    // "if damage would be dealt to this unit, you may defeat a trait-sharing friendly to prevent it") and
    // the rest. Divided damage is simultaneous (CR 34/35.5): offer each replacement FIRST — its cost may
    // defeat a co-target, which is then simply skipped — then apply all surviving damage together and sweep.
    // (Non-interactive prevention in split damage — Shields, LOF_220 reduction — is a separate deferred gap.)
    $offer = []; $apply = [];
    foreach ($hits as $h) {
        $mz  = SWUFindMzByUID($h['uid']);
        $obj = $mz !== null ? GetZoneObject($mz) : null;
        if (SWUObjGone($obj)) continue;
        if (($obj->CardID ?? '') === 'SEC_101' && !empty(_SWUAmidalaPreventTargets($obj))) $offer[] = $h;
        else $apply[] = $h;
    }

    if (empty($offer)) { _SWUApplySplitHits(intval($player), $apply); $playerID = $saved; return; }

    // Interactive: carry the plain hits + remaining offers through the decision, offering each replacement
    // one at a time; the final step applies everything that survived.
    _SWUSplitOfferStep(intval($player), $offer, $apply);
    $playerID = $saved;
}

// Apply a resolved hit list SIMULTANEOUSLY: add ALL damage first (indices stay put), then sweep defeats
// by UID (re-resolve each time, since SWUDefeatUnit cleans up and shifts indices).
function _SWUApplySplitHits(int $player, array $hits): void {
    global $playerID; $saved = $playerID; $playerID = intval($player);
    $dealtAny = false;
    foreach ($hits as $h) {
        $mz  = SWUFindMzByUID($h['uid']);
        if ($mz === null) continue;
        $obj = GetZoneObject($mz);
        if (SWUObjGone($obj)) continue;
        $amount = intval($h['amount']);
        if ($amount <= 0) continue;
        // Each assigned share is still card-ability damage, so it runs the SAME non-interactive
        // prevention chain as the single-target funnel: "can't be damaged" immunity (SHD_187), SEC_042's
        // prevent-2, LOF_220/SEC_050/ASH_150 reductions, then the Shield. Source-less (divided damage is
        // unattributed), so the source-aware LOF_108 leg does not apply here.
        $prevented = false; $shielded = false;
        $amount = _SWUNonInteractiveDamagePrevention($obj, $amount, intval($player), null, $prevented, $shielded);
        if ($shielded) {
            SWUQueuePreventedAnim($mz, intval($player));
            SWUQueueShieldBreakAnim($mz, intval($player));
        }
        if ($prevented || $amount <= 0) continue;
        $obj->Damage = intval($obj->Damage) + $amount;
        SWUQueueDamageAnim($mz, $amount, intval($player));
        $dealtAny = true;
    }
    foreach ($hits as $h) {
        $mz  = SWUFindMzByUID($h['uid']);
        if ($mz === null) continue;
        $obj = GetZoneObject($mz);
        if (SWUObjGone($obj)) continue;
        $hp = ObjectCurrentHP($obj);
        if ($hp > 0 && intval($obj->Damage) >= $hp && !SWUImmuneToHpDefeat($obj)) {
            // SWUDefeatUnit now collects WhenDefeated + leave-play reactions itself (single point).
            SWUDefeatUnit(intval($player), $mz, false, true); // SBA "no remaining HP" (not an ability-defeat)
        }
    }
    // Divided damage is non-combat: a source that dealt any of it to a unit triggers the "when you deal
    // non-combat damage" reaction ONCE for the whole simultaneous event (JTL_009 Boba Fett). The
    // SWU_BOBA_009_PENDING guard inside the collector dedupes multi-target hits to a single offer.
    if ($dealtAny) _SWUCollectBobaNonCombatReaction(intval($player));
    $playerID = $saved;
}

function _SWUEncodeHits(array $hits): string {
    $out = [];
    foreach ($hits as $h) $out[] = intval($h['uid']) . ':' . intval($h['amount']);
    return implode(',', $out);
}
function _SWUDecodeHits(?string $s): array {
    $out = [];
    foreach (explode(',', (string)$s) as $pair) {
        if ($pair === '') continue;
        $p = explode(':', $pair);
        if (count($p) < 2) continue;
        $out[] = ['uid' => intval($p[0]), 'amount' => intval($p[1])];
    }
    return $out;
}

// Offer the next SEC_101 damage-replacement in a split. $offer = remaining hits still to offer; $apply =
// the plain + already-declined hits to apply at the end. State is carried through the decision PARAM (DQ
// variables don't survive the request boundary — the split spans P1's assign and the target-controller's
// answer). Skips a target already gone (a prior prevent's cost) and one that can no longer pay (no trait-
// sharing friendly → its hit just applies). When offers run out, apply everything simultaneously. $player =
// the caster (damage dealer / attribution).
function _SWUSplitOfferStep(int $player, array $offer, array $apply): void {
    global $playerID; $playerID = intval($player);
    while (!empty($offer)) {
        $cur = array_shift($offer);
        $mz  = SWUFindMzByUID(intval($cur['uid']));
        $obj = $mz !== null ? GetZoneObject($mz) : null;
        if (SWUObjGone($obj)) continue;   // target gone (a prior prevent's cost) → nothing to do
        $targets = _SWUAmidalaPreventTargets($obj);
        if (empty($targets)) { $apply[] = $cur; continue; }     // can't pay now → this hit applies with the rest
        $decider = intval($obj->Controller ?? $player);
        $playerID = $decider;   // leave set = the decision's player, so MZCountChoices validates its frame
        DecisionQueueController::AddDecision($decider, 'MZMAYCHOOSE', implode('&', $targets), 1,
            tooltip: 'Defeat_a_trait-sharing_friendly_to_prevent_damage_to_Queen_Amidala?');
        DecisionQueueController::AddDecision($decider, 'CUSTOM',
            "SPLIT_PREVENT_RESOLVE|{$player}|" . intval($cur['uid']) . "|" . intval($cur['amount']) . "|{$decider}|"
            . _SWUEncodeHits($apply) . "|" . _SWUEncodeHits($offer), 1);
        return;   // wait on the decision; SPLIT_PREVENT_RESOLVE continues the loop
    }
    // No more offers → apply the plain + declined hits simultaneously, then sweep.
    _SWUApplySplitHits($player, $apply);
}

// "Distribute N Advantage tokens among units (divided as you choose)" — the SPLIT_DAMAGE analogue for
// the Advantage-token cards (ASH_195/211/224). $assignmentStr = "mzID:count,mzID:count" (MZSPLITASSIGN).
// No defeats occur, so apply directly by mzID; DoGiveAdvantageToken gives one token per count.
function SWUGiveSplitAdvantage(int $player, string $assignmentStr): void {
    if ($assignmentStr === '' || $assignmentStr === '-' || $assignmentStr === 'PASS') return;
    global $playerID;
    $saved    = $playerID;
    $playerID = intval($player);
    foreach (explode(',', $assignmentStr) as $pair) {
        $p = explode(':', $pair);
        if (count($p) < 2) continue;
        $mz  = trim($p[0]);
        $cnt = intval($p[1]);
        if ($cnt <= 0) continue;
        $obj = GetZoneObject($mz);
        if (SWUObjGone($obj)) continue;
        for ($k = 0; $k < $cnt; $k++) DoGiveAdvantageToken(intval($player), $mz);
    }
    $playerID = $saved;
}

// Queue a "distribute $total Advantage tokens among $targets" decision (MZSPLITASSIGN → SPLIT_ADVANTAGE).
// $upto=true allows assigning fewer than $total (the "may / up to" wording); false requires all $total.
function SWUQueueDistributeAdvantage(int $player, int $total, array $targets, bool $upto, string $tooltip): void {
    if ($total <= 0 || empty($targets)) return;
    $spec = "{$total}|" . implode("&", $targets) . ($upto ? "|UPTO" : "");
    DecisionQueueController::AddDecision($player, "MZSPLITASSIGN", $spec, 1, tooltip: $tooltip);
    DecisionQueueController::AddDecision($player, "CUSTOM", "SPLIT_ADVANTAGE", 1);
}

// ── Indirect damage (CR §35) ────────────────────────────────────────────────
// "Deal N indirect damage to a player": that player (the assigner) assigns N unpreventable damage,
// divided as they choose, among their units + base — capped per unit at remaining HP (shields are
// ignored but NOT consumed, CR 35.2.a). All damage simultaneous (CR 35.5); attributed to the
// controller (CR 35.4). Built on MZSPLITASSIGN (per-target caps, base targets, forced-full pool).

// CardIDs whose presence makes the CONTROLLER assign indirect damage to opponents (override of
// CR 35.1's "the chosen player assigns"). JTL_143 Devastator; JTL_171's per-unit grant slots in later.
function SWUIndirectAssignToOpponentSources(): array {
    return ["JTL_143"];
}

// Resolve an indirect-damage SOURCE unit's UniqueID from its (current-frame) mzID — 0 if it's gone/null.
// Used to thread the dealing unit through SWUDealIndirectDamage so JTL_171 Targeting Computer's per-source
// override can be evaluated against the actual dealer (not any controlled host).
function _SWUSrcUID(string $mzID): int {
    $o = GetZoneObject($mzID);
    return ($o !== null && empty($o->removed)) ? intval($o->UniqueID ?? 0) : 0;
}

// Resolve who assigns the indirect damage. Default: the damaged player. Override → the controller, when the
// damaged player is an opponent AND either (a) the controller controls a "you assign all indirect you deal"
// source (JTL_143 Devastator — per-controller, any source), or (b) the SOURCE unit that dealt this indirect
// bears JTL_171 Targeting Computer ("you assign all indirect dealt by THIS unit" — per-source). $sourceUID is
// the UniqueID of the unit dealing the damage (0 when the source is an event/player-effect, which can't bear
// Targeting Computer). Threaded through the funnel + the INDIRECT_APPLY/INDIRECT_CHOOSE_PLAYER params so the
// re-resolution across the request boundary agrees with the first pass.
function SWUControllerAssignsIndirect(int $controller, int $damagedPlayer, int $sourceUID = 0): int {
    if ($damagedPlayer === $controller) return $damagedPlayer; // self-target never overrides
    global $playerID;
    $saved = $playerID; $playerID = $controller;
    $controls = false;
    // (a) JTL_143 Devastator — controller assigns ALL indirect they deal, regardless of source unit.
    foreach (SWUIndirectAssignToOpponentSources() as $srcCard) {
        foreach (["myGroundArena", "mySpaceArena"] as $z) {
            foreach (ZoneSearch($z, AnyUnitFilter) as $mz) {
                $o = GetZoneObject($mz);
                if (SWUObjGone($o)) continue;
                if (($o->CardID ?? '') === $srcCard) { $controls = true; break 3; }
            }
        }
    }
    // (b) JTL_171 Targeting Computer — per-SOURCE: only the unit that actually dealt this indirect (if it
    // still bears Targeting Computer) makes the controller the assigner. A different friendly unit's indirect
    // is unaffected (reference: "should not affect indirect damage dealt by another friendly unit").
    if (!$controls && $sourceUID > 0) {
        $srcMz = SWUFindMzByUID($sourceUID);
        if ($srcMz !== null) {
            $srcObj = GetZoneObject($srcMz);
            if ($srcObj !== null && empty($srcObj->removed) && _SWUUnitHasUpgrade($srcObj, 'JTL_171')) {
                $controls = true;
            }
        }
    }
    $playerID = $saved;
    return $controls ? $controller : $damagedPlayer;
}

// Apply an indirect assignment string ("mz:amt,mz:amt") SIMULTANEOUSLY: raw damage to units
// (bypasses + preserves shields), base via SWUDealDamageToBase attributed to the controller,
// then one UID-snapshot defeat sweep. Shared by the DQ handler and the auto-resolve path.
// $thenHandler (optional) is a "Name~arg1~arg2" continuation dispatched AFTER the assignment is applied,
// with the results exposed in $gLastIndirectBaseDmg (total base damage dealt this way) and
// $gLastIndirectUnitUIDs (UniqueIDs of units damaged this way). Threaded through the decision param so it
// survives the request boundary on the interactive MZSPLITASSIGN path. (JTL_152/218/222 reactive seams.)
function SWUApplyIndirectAssignment(int $controller, int $damagedPlayer, string $assignmentStr, string $thenHandler = '', int $sourceUID = 0): void {
    global $playerID, $gLastIndirectBaseDmg, $gLastIndirectUnitUIDs;
    $gLastIndirectBaseDmg = 0; $gLastIndirectUnitUIDs = [];
    if ($assignmentStr === '' || $assignmentStr === '-' || $assignmentStr === 'PASS') {
        if ($thenHandler !== '') SWUDispatchIndirectThen($controller, $thenHandler);
        return;
    }
    $saved    = $playerID;
    $assigner = SWUControllerAssignsIndirect($controller, $damagedPlayer, $sourceUID);

    // Phase 0: parse the submitted assignment under the ASSIGNER's frame (the queued mzIDs are
    // assigner-relative). Capture units by UniqueID so later phases are frame-independent.
    $playerID = $assigner;
    $hits = []; $baseDmg = 0;
    foreach (explode(',', $assignmentStr) as $pair) {
        $p = explode(':', $pair);
        if (count($p) < 2) continue;
        $mz = trim($p[0]); $amt = intval($p[1]);
        if ($amt <= 0) continue;
        if (strpos($mz, 'Base') !== false) { $baseDmg += $amt; continue; }
        $o = GetZoneObject($mz);
        if (SWUObjGone($o)) continue;
        $hits[] = ['uid' => intval($o->UniqueID ?? 0), 'amount' => $amt, 'obj' => $o];
    }
    // Expose the results for an optional reactive continuation (JTL_152/218/222).
    $gLastIndirectBaseDmg  = $baseDmg;
    $gLastIndirectUnitUIDs = array_map(fn($h) => $h['uid'], $hits);

    // Phases 1-2 run under the CONTROLLER's frame so SWUFindMzByUID / SWUQueueDamageAnim /
    // SWUDefeatUnit stay consistent and the defeat is attributed to the controller (CR 35.4).
    $playerID = $controller;

    // Phase 1: apply all unit damage (no defeats — indices/UIDs stay valid through the loop).
    foreach ($hits as $h) {
        $mz = SWUFindMzByUID($h['uid']); if ($mz === null) continue;
        $o  = GetZoneObject($mz); if (SWUObjGone($o)) continue;
        $amt = $h['amount'];
        // SEC_050 Vigil — "If damage would be dealt to THIS unit by another card, deal that much +1 instead."
        // Indirect damage is unpreventable, so the "prevent 1 to another friendly" half never applies here —
        // but Vigil's INCREASE still does for the portion assigned to Vigil, added at the damage step (indirect
        // is dealt all together). "Deal N indirect" is card-ability damage, so it qualifies as "by another card."
        if (($o->CardID ?? '') === 'SEC_050') $amt += 1;
        $o->Damage = intval($o->Damage) + $amt;
        SWUQueueDamageAnim($mz, $amt, $controller);
    }

    // Base damage — attributed to the controller (self-target suppresses the enemy-base flags). Flagged
    // indirect so an unpreventable base-prevention one-shot (JTL_074) is consumed but does NOT prevent it.
    if ($baseDmg > 0) {
        SWUDealDamageToBase($baseDmg, $damagedPlayer, $controller, true);
        // SEC_012 Cassian — indirect base damage counts as the source unit "damaging an opponent's base"
        // (CR 35.4 attributes indirect damage to the controller). Arm the per-unit marker directly with the
        // threaded $sourceUID: SWU_DMG_SRC is already cleared by the action boundary before the opponent
        // answers the assignment, so the central read in SWUDealDamageToBase can't see it here. Enemy base only.
        if ($sourceUID > 0) {
            AddGlobalEffects(intval($controller),
                'SWU_DMGDBASE_' . intval($sourceUID) . '_' . intval($damagedPlayer));
        }
        if ($sourceUID > 0 && intval($damagedPlayer) !== intval($controller)) {
            AddGlobalEffects(intval($controller), 'SWU_UNITDMGBASE_' . intval($sourceUID));
            // JTL_177 Stay on Target — the granted trigger reads "When this unit deals DAMAGE to a base",
            // not "combat damage", so indirect damage the attacker deals to a base fires it too. The
            // combat-end check in CombatLogic only sees $combatCtx['dealtToBase'] (direct hit + Overwhelm
            // spill), so without this an attacker that damages the base by BOTH paths in one attack — e.g.
            // JTL_149 Red Squadron Y-Wing's On Attack indirect, then its combat damage — drew only once.
            // We are in the controller's frame here, so SWUFindMzByUID resolves correctly.
            $jtl177Src = SWUFindMzByUID(intval($sourceUID));
            if ($jtl177Src !== null) {
                $jtl177Obj = GetZoneObject($jtl177Src);
                if ($jtl177Obj !== null && empty($jtl177Obj->removed)
                        && is_array($jtl177Obj->TurnEffects ?? null)
                        && in_array('JTL_177', $jtl177Obj->TurnEffects, true)) {
                    DoDrawCard(intval($controller), 1);
                }
            }
        }
    }

    // Phase 2: simultaneous defeat sweep (re-resolve by UID — SWUDefeatUnit shifts indices).
    foreach ($hits as $h) {
        $mz = SWUFindMzByUID($h['uid']); if ($mz === null) continue;
        $o  = GetZoneObject($mz); if (SWUObjGone($o)) continue;
        $hp = ObjectCurrentHP($o);
        if ($hp > 0 && intval($o->Damage) >= $hp && !SWUImmuneToHpDefeat($o)) SWUDefeatUnit($controller, $mz, false, true); // SBA
    }

    // "When damage is dealt to this unit" observers. Indirect damage writes ->Damage directly (it is
    // unpreventable and bypasses the SWUDealDamageToUnit funnel), so these have to be fired explicitly
    // here or a whole damage kind is invisible to them — SEC_143 The Elite Squad's reaction, the
    // damaged-this-phase marker, and the rest. Run AFTER the defeat sweep so $survived is accurate.
    foreach ($hits as $h) {
        if (intval($h['amount']) <= 0) continue;
        $obs = null;
        $obsMz = SWUFindMzByUID($h['uid']);
        if ($obsMz !== null) $obs = GetZoneObject($obsMz);
        if ($obs === null) $obs = $h['obj'] ?? null;   // defeated: still observe, with $survived = false
        if ($obs === null) continue;
        _SWUOnUnitDamaged($obs, intval($h['amount']), false, $obsMz !== null && !SWUObjGone($obs));
    }

    // JTL_133 Allegiant General Pryde — "When indirect damage is dealt to a unit: you may defeat a
    // non-unique upgrade on it." For each surviving unit damaged this way, if $controller controls Pryde,
    // offer to defeat one of that unit's non-unique upgrades. (Single damaged unit is the common case;
    // multi-unit would clobber the shared DefeatUpg StoreVariables — a documented edge.)
    $prydeControls = false;
    foreach (array_merge(GetGroundArena($controller) ?? [], GetSpaceArena($controller) ?? []) as $pu) {
        if (empty($pu->removed) && ($pu->CardID ?? '') === 'JTL_133') { $prydeControls = true; break; }
    }
    if ($prydeControls) {
        foreach ($gLastIndirectUnitUIDs as $uid) {
            if (SWUFindMzByUID(intval($uid)) === null) continue;
            SWUQueueDefeatUpgrade($controller, "You_may_defeat_a_non-unique_upgrade_on_the_damaged_unit",
                may: true, max: 1, filter: "unique=0", min: 0, onlyHostUID: intval($uid));
        }
    }

    $playerID = $saved;
    if ($thenHandler !== '') SWUDispatchIndirectThen($controller, $thenHandler);
}

// Dispatch an indirect "then" continuation: "Name~arg1~arg2" → $customDQHandlers[Name]($controller,[args]).
function SWUDispatchIndirectThen(int $controller, string $thenHandler): void {
    global $customDQHandlers;
    $parts = explode('~', $thenHandler);
    $name  = array_shift($parts);
    if ($name !== '' && isset($customDQHandlers[$name]) && is_callable($customDQHandlers[$name])) {
        $customDQHandlers[$name]($controller, $parts, '');
    }
}

// Core funnel: deal $amount indirect damage to $damagedPlayer, dealt by $controller. $thenHandler is an
// optional "Name~args" continuation (see SWUApplyIndirectAssignment). $sourceUID is the UniqueID of the unit
// dealing the damage (0 for event/player sources); it gates the per-source JTL_171 Targeting Computer override.
function SWUDealIndirectDamage(int $controller, int $amount, int $damagedPlayer, string $thenHandler = '', int $sourceUID = 0): void {
    if ($amount <= 0) { if ($thenHandler !== '') SWUDispatchIndirectThen($controller, $thenHandler); return; }
    // JTL_165 Hunting Aggressor: indirect damage you deal to opponents is increased by 1.
    if ($damagedPlayer !== $controller) {
        // Each COPY increases it — this is a per-object constant ability, not a once-per-player one, so
        // two Hunting Aggressors turn 8 indirect into 10. The `break` made every copy after the first
        // a no-op. It stayed hidden because MZSPLITASSIGN totals were unvalidated: the assign step
        // offered a 9-point pool, the test assigned the correct 10, and the appliers applied all 10.
        foreach (GetUnitsInPlay($controller) as $u) { if (($u->CardID ?? '') === 'JTL_165' && empty($u->removed)) $amount += 1; }
    }
    AddGlobalEffects($controller, 'SWU_DEALT_INDIRECT'); // JTL_138 "if you dealt indirect damage this phase"
    global $playerID;
    $assigner = SWUControllerAssignsIndirect($controller, $damagedPlayer, $sourceUID);
    $saved = $playerID; $playerID = $assigner;
    $persp = ($assigner === $damagedPlayer) ? 'my' : 'their'; // 'their' only in the override case

    $specs = [];
    foreach ([$persp . "GroundArena", $persp . "SpaceArena"] as $z) {
        foreach (ZoneSearch($z, AnyUnitFilter) as $mz) {
            $o = GetZoneObject($mz);
            if (SWUObjGone($o)) continue;
            $cap = ObjectCurrentHP($o) - intval($o->Damage); // shields don't reduce the cap (CR 35.3)
            if ($cap > 0) $specs[] = "{$mz}:{$cap}";
        }
    }
    // The base is an UNLIMITED sink for indirect damage — unlike units (capped at remaining HP
    // per the CR), the base can be assigned damage past its remaining HP and goes over capacity.
    // Cap the spec at $amount (the most that could ever be assigned to one target) so the player
    // may dump the whole pool onto the base and overkill is dealt/displayed in full.
    $base = GetBase($damagedPlayer);
    if (count($base) > 0 && empty($base[0]->removed)) {
        $specs[] = "{$persp}Base-0:{$amount}";
    }
    if (empty($specs)) { $playerID = $saved; if ($thenHandler !== '') SWUDispatchIndirectThen($controller, $thenHandler); return; }

    $cap = 0; foreach ($specs as $s) { $cap += intval(explode(':', $s)[1]); }
    $pool = min($amount, $cap);                 // assign as much as possible (CR 35.3)
    if ($pool <= 0) { $playerID = $saved; if ($thenHandler !== '') SWUDispatchIndirectThen($controller, $thenHandler); return; }

    if (count($specs) === 1) {                  // no meaningful choice — auto-resolve, no popup
        $mz = explode(':', $specs[0])[0];
        SWUApplyIndirectAssignment($controller, $damagedPlayer, "{$mz}:{$pool}", $thenHandler, $sourceUID);
        $playerID = $saved;
        return;
    }

    // Always emit the thenHandler slot (possibly empty) so $sourceUID keeps a fixed positional index.
    $applyParam = "INDIRECT_APPLY|{$controller}|{$damagedPlayer}|{$thenHandler}|{$sourceUID}";
    DecisionQueueController::AddDecision($assigner, "MZSPLITASSIGN", "{$pool}|" . implode("&", $specs), 1, tooltip:"Assign_{$pool}_indirect_damage");
    DecisionQueueController::AddDecision($assigner, "CUSTOM", $applyParam, 1);
    // Leave $playerID = $assigner: MZCountChoices validates the relative-mzID split next, under it.
}

// "Deal N indirect damage to a player" — controller picks You or Opponent (2-player; Twin Suns later).
// $thenHandler optional (see SWUApplyIndirectAssignment).
function SWUDealIndirectToChosenPlayer(int $controller, int $amount, string $thenHandler = '', int $sourceUID = 0): void {
    global $playerID; $playerID = $controller;
    // Always emit the thenHandler slot (possibly empty) so $sourceUID keeps a fixed positional index.
    $param = "INDIRECT_CHOOSE_PLAYER|{$controller}|{$amount}|{$thenHandler}|{$sourceUID}";
    DecisionQueueController::AddDecision($controller, "OPTIONCHOOSE", "You&Opponent", 1, "Choose_a_player_to_deal_indirect_damage");
    DecisionQueueController::AddDecision($controller, "CUSTOM", $param, 1);
}

// "Deal N indirect damage to each opponent" (2-player: the one opponent). Twin Suns (Phase 3): all opponents.
function SWUDealIndirectToEachOpponent(int $controller, int $amount): void {
    foreach (OpponentsOf($controller) as $opp) {
        SWUDealIndirectDamage($controller, $amount, intval($opp));
    }
}

// Apply an indirect assignment ($lastDecision = "mz:amt,..."); param = controller|damagedPlayer|thenHandler|sourceUID.
$customDQHandlers["INDIRECT_APPLY"] = function($player, $parts, $lastDecision) {
    $controller = intval($parts[0] ?? $player);
    $damaged    = intval($parts[1] ?? $player);
    $thenHandler = (string)($parts[2] ?? '');
    $sourceUID  = intval($parts[3] ?? 0);
    SWUApplyIndirectAssignment($controller, $damaged, (string)$lastDecision, $thenHandler, $sourceUID);
};

// Resolve the You/Opponent choice for "deal N indirect to a player"; param = controller|amount|thenHandler|sourceUID.
$customDQHandlers["INDIRECT_CHOOSE_PLAYER"] = function($player, $parts, $lastDecision) {
    $controller = intval($parts[0] ?? $player);
    $amount     = intval($parts[1] ?? 0);
    $thenHandler = (string)($parts[2] ?? '');
    $sourceUID  = intval($parts[3] ?? 0);
    $target     = ((string)$lastDecision === 'Opponent') ? GetOpponent($controller) : $controller;
    SWUDealIndirectDamage($controller, $amount, intval($target), $thenHandler, $sourceUID);
};

// DQ handler: deal N damage to the unit at the mzID stored in $lastDecision.
// Queued by WhenPlayed abilities that target a unit chosen via MZCHOOSE.
$customDQHandlers["DEAL_UNIT_DAMAGE"] = function($player, $parts, $lastDecision) {
    if ($lastDecision === null || $lastDecision === '-' || $lastDecision === '') return;
    // Resolve the frame-relative target mzID under the DECIDER's frame (the player who built/answered the
    // choice) — matches the sibling APPLY_PHASE_BUFF/DEBUFF/BOUNCE handlers. Needed when the decider isn't
    // the active turn player (e.g. TS26_15 C-3P0's opponent-controlled activated ability); a no-op when
    // they are, so existing active-player callers are unaffected.
    global $playerID;
    $playerID = intval($player);
    SWUDealDamageToUnit($lastDecision, intval($parts[0] ?? 1), intval($player));
};

// Universal handler: give the unit at $lastDecision a "for this phase" shrink of
// –{$parts[0]}/–{$parts[1]}. Callers queue PASSPARAMETER/MZCHOOSE + CUSTOM APPLY_PHASE_DEBUFF|power|hp.
$customDQHandlers["APPLY_PHASE_DEBUFF"] = function($player, $parts, $lastDecision) {
    if ($lastDecision === null || $lastDecision === '-' || $lastDecision === '' || $lastDecision === 'PASS') return;
    global $playerID;
    $playerID = intval($player);
    SWUApplyPhaseDebuff($lastDecision, intval($parts[0] ?? 0), intval($parts[1] ?? 0), (string)($parts[2] ?? ''));
};

// Universal handler: give the unit at $lastDecision a "for this phase" buff of
// +{$parts[0]}/+{$parts[1]}. Optional $parts[2] = source CardID (shown in the Active
// Effects popup). Callers queue PASSPARAMETER/MZCHOOSE + CUSTOM APPLY_PHASE_BUFF|power|hp|source.
$customDQHandlers["APPLY_PHASE_BUFF"] = function($player, $parts, $lastDecision) {
    if ($lastDecision === null || $lastDecision === '-' || $lastDecision === '' || $lastDecision === 'PASS') return;
    global $playerID;
    $playerID = intval($player);
    SWUApplyPhaseBuff($lastDecision, intval($parts[0] ?? 0), intval($parts[1] ?? 0), (string)($parts[2] ?? ''));
};

$customDQHandlers["BOUNCE_UNIT"] = function($player, $parts, $lastDecision) {
    if ($lastDecision === null || $lastDecision === '-' || $lastDecision === '' || $lastDecision === 'PASS') return;
    global $playerID;
    $playerID = intval($player);
    SWUBounceUnit($player, $lastDecision);
};

// Universal handler: heal $parts[0] from the chosen target ($lastDecision), which
// may be a unit mzID or a base mzID (myBase-0 / theirBase-0). Queued by
// PASSPARAMETER/MZCHOOSE + CUSTOM HEAL_TARGET|N. (SOR_074 Repair.)
$customDQHandlers["HEAL_TARGET"] = function($player, $parts, $lastDecision) {
    if ($lastDecision === null || $lastDecision === '-' || $lastDecision === '' || $lastDecision === 'PASS') return;
    global $playerID;
    $playerID = intval($player);
    $amount = intval($parts[0] ?? 0);
    if (strpos($lastDecision, 'Base') !== false) {
        $targetPlayer = (strpos($lastDecision, 'my') === 0) ? intval($player) : GetOpponent(intval($player));
        OnHealBase(intval($player), $targetPlayer, $amount);
    } else {
        OnHealUnit(intval($player), $lastDecision, $amount);
    }
};

// Universal handler: deal N damage to a chosen UNIT or BASE (mzID may be a unit mzID or
// myBase-0/theirBase-0). Param DEAL_TARGET|N. No-ops on a '-' decline. Mirror of HEAL_TARGET.
$customDQHandlers["DEAL_TARGET"] = function($player, $parts, $lastDecision) {
    if ($lastDecision === null || $lastDecision === '-' || $lastDecision === '' || $lastDecision === 'PASS') return;
    global $playerID;
    $playerID = intval($player);
    $amount = intval($parts[0] ?? 0);
    if (strpos($lastDecision, 'Base') !== false) {
        $targetPlayer = (strpos($lastDecision, 'my') === 0) ? intval($player) : GetOpponent(intval($player));
        SWUDealDamageToBase($amount, $targetPlayer);
    } else {
        SWUDealDamageToUnit($lastDecision, $amount, intval($player));
    }
};

// Universal handler: close the current action. Lets base/leader epic abilities reuse
// the universal effect handlers (DEAL_UNIT_DAMAGE, APPLY_PHASE_DEBUFF, HEAL_TARGET, …
// which deliberately do NOT call SWUAfterAction so events can use them too) and then
// end the action by queuing CUSTOM SWU_AFTER_ACTION last.
$customDQHandlers["SWU_AFTER_ACTION"] = function($player, $parts, $lastDecision) {
    SWUAfterAction(intval($player));
};

// Resolves the "which base ability?" OPTIONCHOOSE SWUBaseAction raises when a base has both its own
// Action and one or more Fortify-upgrade Actions. Labels are re-derived from the current board (nothing
// can have changed in between), so no state rides the decision. An unrecognised answer keeps the action.
$customDQHandlers["BASE_ACTION_PICK"] = function($player, $parts, $lastDecision) {
    global $playerID;
    $playerID = intval($player);
    foreach (_SWUBaseActionProviders(intval($player)) as $prov) {
        if ($prov['label'] === (string)$lastDecision) {
            _SWUDispatchBaseAction(intval($player), $prov);
            return;
        }
    }
};

// Like SWU_AFTER_ACTION but DON'T swap the turn player — JTL_018 Kazuda's "take an extra action".
$customDQHandlers["SWU_AFTER_ACTION_EXTRA"] = function($player, $parts, $lastDecision) {
    SWUAfterActionExtra(intval($player));
};

// Universal handler: ready the resource at the mzID passed via $lastDecision.
// Callers queue PASSPARAMETER($mzID) + CUSTOM READY_RESOURCE.
$customDQHandlers["READY_RESOURCE"] = function($player, $parts, $lastDecision) {
    if ($lastDecision === null || $lastDecision === '-' || $lastDecision === '' || $lastDecision === 'PASS') return;
    OnReadyCard($player, $lastDecision);
};

// Universal handler: exhaust the unit at the mzID passed via $lastDecision.
// Callers queue PASSPARAMETER($mzID) or MZCHOOSE + CUSTOM EXHAUST_UNIT.
$customDQHandlers["EXHAUST_UNIT"] = function($player, $parts, $lastDecision) {
    if ($lastDecision === null || $lastDecision === '-' || $lastDecision === '' || $lastDecision === 'PASS') return;
    OnExhaustCard($player, $lastDecision);
};

// Universal handler: ready the unit at the mzID passed via $lastDecision.
// Callers queue PASSPARAMETER($mzID) or MZCHOOSE + CUSTOM READY_UNIT.
$customDQHandlers["READY_UNIT"] = function($player, $parts, $lastDecision) {
    if ($lastDecision === null || $lastDecision === '-' || $lastDecision === '' || $lastDecision === 'PASS') return;
    OnReadyCard($player, $lastDecision);
};

// ── Scry infrastructure ───────────────────────────────────────────────────────
// DoScry($player, $n): peek top $n cards, let player place each to top or bottom.
// Queues a single SCRY decision (frontend panel) followed by SCRY_FINALIZE.
// Result format: "topID1,topID2|bottomID1,bottomID2" (topmost-first | order-added).
// ⚠ NOTHING is held across the SCRY decision. The peeked cards stay exactly where they are — the FRONT
// $n of the deck — and only the finalize handler (running once the player has answered) mutates the
// deck. This mirrors REVEALARRANGE_FINALIZE below and is not a style choice: SCRY raises an INTERACTIVE
// decision, so production answers it in a LATER request in a FRESH process. The old shape spliced the
// cards out of the deck into a `$gScryState` global and rebuilt from it at finalize; across the real
// request boundary that global was empty, so the finalize dereferenced null and every peeked card was
// destroyed — the deck simply lost 2 cards on each Inferno Four (SOR_031) and 1 on each R2-D2
// (SOR_236). Guard: InfernoFour_Unforgetting::WhenPlayed_ScryAnsweredAcrossRequestBoundary.
// (The JTL_094 family: any value written before an AddDecision and read behind it must be serialized.)
function DoScry($player, $n) {
    $deck = &GetDeck($player);
    $n = min($n, count($deck));
    if ($n === 0) return;
    $cardIDs = implode(',', array_map(fn($c) => $c->CardID, array_slice($deck, 0, $n)));
    DecisionQueueController::AddDecision($player, "SCRY", $cardIDs, 1, tooltip:"Look_at_top_cards");
    DecisionQueueController::AddDecision($player, "CUSTOM", "SCRY_FINALIZE|{$n}", 1);
    MarkUndoRequiresConsent();
}

// $parts[0] = N (how many were peeked). $lastDecision = "topID1,topID2|bottomID1,bottomID2" —
// top listed topmost-first, bottom in the order added. Any peeked card the answer fails to account for
// goes back on top rather than vanishing.
$customDQHandlers["SCRY_FINALIZE"] = function($player, $parts, $lastDecision) {
    $n = max(0, intval($parts[0] ?? 0));
    if ($n === 0) return;
    $deck = &GetDeck($player);
    $peeked = array_splice($deck, 0, $n);
    $byID = [];
    foreach ($peeked as $c) { $byID[$c->CardID][] = $c; }   // lists, so duplicate CardIDs survive
    $sections  = explode('|', (string) $lastDecision);
    $topIDs    = ($sections[0] ?? '') !== '' ? explode(',', $sections[0]) : [];
    $bottomIDs = ($sections[1] ?? '') !== '' ? explode(',', $sections[1]) : [];
    foreach ($bottomIDs as $id) {
        if (!empty($byID[$id])) { array_push($deck, array_shift($byID[$id])); }
    }
    foreach (array_reverse($topIDs) as $id) {               // reversed so the first listed ends up on top
        if (!empty($byID[$id])) { array_unshift($deck, array_shift($byID[$id])); }
    }
    foreach ($byID as $list) { foreach ($list as $c) { array_unshift($deck, $c); } }
    foreach ($deck as $i => $c) { $c->mzIndex = $i; }
};

// ── Reveal-top-N → discard-any + reorder-rest ─────────────────────────────────
// Generic finalize for "reveal the top N cards … you may discard any of the revealed cards and
// put the rest back on top in any order" (SOR_152 For a Cause I Believe In). The revealed cards
// are still the FRONT N of the deck (no global state held across the request boundary — the
// caller only reveals/peeks; this handler does the actual deck mutation when the player answers).
// $parts[0] = N (count revealed). $lastDecision = "keptID1,keptID2|discardID1,discardID2":
//   kept go back on top in the listed order (first = top); discarded go to discard (From DECK).
$customDQHandlers["REVEALARRANGE_FINALIZE"] = function($player, $parts, $lastDecision) {
    global $playerID;
    $playerID = intval($player);
    $n = max(0, intval($parts[0] ?? 0));
    if ($n === 0) return;
    $deck = &GetDeck($player);
    $revealed = array_splice($deck, 0, $n);          // pull the revealed cards off the top
    foreach ($deck as $i => $c) { $c->mzIndex = $i; }

    $byID = [];
    foreach ($revealed as $c) { $byID[$c->CardID][] = $c; }  // lists handle duplicate CardIDs

    $sections   = explode('|', (string)$lastDecision);
    $keptIDs    = ($sections[0] ?? '') !== '' ? explode(',', $sections[0]) : [];
    $discardIDs = ($sections[1] ?? '') !== '' ? explode(',', $sections[1]) : [];

    foreach ($discardIDs as $id) {
        if (!empty($byID[$id])) { $c = array_shift($byID[$id]); SWUAddToDiscard($player, $c->CardID, 'DECK'); }
    }
    // Put kept back on top in the listed order (first listed ends up on top).
    foreach (array_reverse($keptIDs) as $id) {
        if (!empty($byID[$id])) { $c = array_shift($byID[$id]); array_unshift($deck, $c); }
    }
    // Safety: any revealed card the answer didn't account for goes back on top.
    foreach ($byID as $list) { foreach ($list as $c) { array_unshift($deck, $c); } }
    foreach ($deck as $i => $c) { $c->mzIndex = $i; }
};

// ── Look-at-top-of-deck helpers ───────────────────────────────────────────────
// "Top of deck" for the look-at-top family (R2-D2, Inferno Four, Reinforcement Walker,
// Ezra Bridger) is the FRONT of the deck array (index 0) — the same end DoScry peeks and
// the test harness' topCardID reads. These operate on that front card.

// First non-removed deck index (the top), or -1 if the deck is empty.
function _SWUTopDeckFrontIdx(int $player): int {
    $deck = GetDeck($player);
    for ($i = 0; $i < count($deck); $i++) {
        if (empty($deck[$i]->removed)) return $i;
    }
    return -1;
}

// Draw the top (front) card to $player's hand. Returns its CardID, or null if deck empty.
function SWUDrawTopCardFront(int $player): ?string {
    global $playerID;
    $saved = $playerID; $playerID = intval($player);
    $idx = _SWUTopDeckFrontIdx($player);
    if ($idx === -1) { $playerID = $saved; return null; }
    $obj = MZMove($player, "myDeck-$idx", "myHand");
    $playerID = $saved;
    if ($obj !== null) MarkUndoRequiresConsent();   // top card revealed to the player (undo redesign)
    return $obj ? $obj->CardID : null;
}

// Play the top (front) card of $player's deck, paying its cost minus $discount (floored at 0), or
// free when $ignoreCost. Used by effects that let you "play the top card" as part of ANOTHER action
// (SOR_192 Ezra's On Attack End, SOR_246 You're My Only Hope's event) — it does NOT advance the
// turn: the parent action (combat / the event's FINISH_PLAY_CARD) owns SWUAfterAction, so the inner
// ActivateCard's own turn advance is neutralised by capturing/restoring the turn state around it.
// Returns true if a card was played (false on empty deck). Unaffordable → ActivateCard no-ops.
// $asUnitOnly: play a Piloting card AS A UNIT, skipping the Unit-vs-Pilot choice. Required by every
// "search your deck for a UNIT and play it" ability (SOR_104, LAW_063, LOF_100, LAW_074): the ability
// named what it was looking for and plays THAT, so the pilot-upgrade mode is not on offer even when a
// legal Vehicle host is on the board.
function SWUPlayTopDeckCard(int $player, bool $ignoreCost = false, int $discount = 0, bool $asUnitOnly = false): bool {
    $idx = _SWUTopDeckFrontIdx($player);
    if ($idx === -1) return false;
    global $gTurnPlayer;
    $savedTP   = $gTurnPlayer;
    $savedPass = GetSWUVar('PASS', '0');
    // A Piloting card played from the deck must offer the Unit-vs-Pilot choice (so it can be played as an
    // upgrade), which lives in SWUBeginPlayCard's Piloting branch — ActivateCard alone would only play it
    // as a unit. Route pilots there, threading the discount (applies to the unit cost AND, via
    // SWU_PILOT_DISCOUNT, the pilot cost). Non-pilots keep the direct ActivateCard path.
    $topObj = ($ignoreCost || $asUnitOnly) ? null : GetZoneObject("myDeck-$idx");
    if ($topObj !== null && HasKeyword_Piloting($topObj)
            && !_SWUGalenSuppressesCard($player, $topObj->CardID ?? '')
            && !empty(SWUGetPilotValidTargets($player, $topObj->CardID ?? '', false, intval($discount)))) {
        SWUBeginPlayCard($player, "myDeck-$idx", $discount);
        $gTurnPlayer = $savedTP; SetSWUVar('PASS', $savedPass);
        return true;
    }
    ActivateCard($player, "myDeck-$idx", $ignoreCost, $discount);
    $gTurnPlayer = $savedTP;
    SetSWUVar('PASS', $savedPass);
    return true;
}

// Mill (discard) the top (front) card to $player's discard with From='DECK'.
// Returns its CardID, or null if deck empty.
function SWUMillTopCard(int $player): ?string {
    global $playerID;
    $saved = $playerID; $playerID = intval($player);
    $deck = &GetDeck($player);
    $idx  = _SWUTopDeckFrontIdx($player);
    if ($idx === -1) { $playerID = $saved; return null; }
    $cardID = $deck[$idx]->CardID;
    // Deck top slides to the discard pile. Queued BEFORE the move so the source mzID still resolves.
    SWUQueueZoneMoveAnim('myDeck-' . $idx, 'myDiscard-0', intval($player));
    SWUAddToDiscard($player, $cardID, 'DECK');
    $deck[$idx]->removed = true;
    DecisionQueueController::CleanupRemovedCards();
    AddGlobalEffects(intval($player), 'SWU_DISCARDED_PHASE');   // "discarded from your deck this phase" (LAW_076)
    // LAW_176 Sebulba's Podracer — "When you discard a card from your deck: you may ready this unit"
    // (once each round). Collect the reactive may-ready trigger for the milling player; it flushes at
    // the enclosing action's completion (combat / play-card). Gated to an EXHAUSTED Podracer so the
    // offer only appears when it's meaningful, and to once-per-round via SWU_LAW176_USED.
    if (GlobalEffectCount(intval($player), 'SWU_LAW176_USED') <= 0) {
        foreach (GetUnitsInPlay(intval($player)) as $pu) {
            if (empty($pu->removed) && ($pu->CardID ?? '') === 'LAW_176' && intval($pu->Status ?? 1) === 0) {
                AddTrigger(intval($player), 'LAW_176', 'LAW_176', $pu->GetMzID());
                break;
            }
        }
    }
    $playerID = $saved;
    return $cardID;
}

// ── Top-deck search infrastructure ───────────────────────────────────────────
// DoTopDeckSearch($player, $n, $filter, $maxPicks):
//   Peek top $n cards, player picks up to $maxPicks matching cards to draw.
//   Constraint encoded as "count:N" in the TOPDECKSEARCH decision param.
//
// DoTopDeckPlay($player, $n, $filter, $costBudget):
//   Peek top $n cards, player picks any number of matching units whose combined
//   cost ≤ $costBudget, each is played for free (no WhenPlayed triggers).
//   Constraint encoded as "cost:N" in the TOPDECKSEARCH decision param.
//
// The peeked card IDs are embedded in the CUSTOM finalize handler param so they
// survive PHP's stateless HTTP request boundary. Format: HANDLER|ID1,ID2,...
// Decision param format: "allIDs|matchingIDs|constraint|costMap"
// Finalize answer format: comma-separated chosen CardIDs (empty = choose none).

// True if $player controls a unit with CardID $cardID in play (any arena, incl. deployed leaders).
function _SWUControlsCardInPlay(int $player, string $cardID): bool {
    foreach (GetUnitsInPlay($player) as $u) {
        if (empty($u->removed) && ($u->CardID ?? '') === $cardID) return true;
    }
    return false;
}

// True if $player controls a unit carrying the upgrade $upgradeCardID.
function _SWUControlsUnitWithUpgrade(int $player, string $upgradeCardID): bool {
    foreach (GetUnitsInPlay($player) as $u) {
        if (!empty($u->removed)) continue;
        foreach (GetUpgradesOnUnit($u) as $up) {
            $ucid = is_array($up) ? ($up['CardID'] ?? '') : ($up->CardID ?? '');
            if ($ucid === $upgradeCardID) return true;
        }
    }
    return false;
}

function _topDeckSearchBegin(int $player, int $n, callable $filter, string $constraint, string $finalizeHandler): void {
    // ASH_084 Arcana Star Map — "If you would search a number of cards from your deck, search twice that
    // number of cards instead." Applies to every deck-search/play-from-deck routed through this funnel.
    if ($n > 0 && _SWUControlsUnitWithUpgrade($player, 'ASH_084')) $n *= 2;
    $deck = &GetDeck($player);
    $n = min($n, count($deck));
    if ($n === 0) return;
    $peeked = array_splice($deck, 0, $n);
    foreach ($deck as $i => $card) { $card->mzIndex = $i; }

    $allIDs   = implode(',', array_map(fn($c) => $c->CardID, $peeked));
    $matchIDs = implode(',', array_map(
        fn($c) => $c->CardID,
        array_filter($peeked, fn($c) => $filter($c->CardID))
    ));
    // cost map for all peeked cards: "CardID:cost,..." so frontend can enforce budget.
    $costMap  = implode(',', array_map(fn($c) => $c->CardID . ':' . intval(CardCost($c->CardID)), $peeked));

    // ⚠ THE FILTER MUST OUTLIVE THE DECISION. $matchIDs above is only a HINT for the client; the answer
    // comes back as a list of CardIDs and _topDeckResolveFromIDs matches it against $allIDs — i.e. every
    // peeked card, filtered or not. Anything that answers with an unfiltered CardID therefore gets it.
    // On HMW_043 ("up to 2 units that each cost 4 or less") that meant a cost-5 unit could be played and
    // a cost-3 EVENT was placed into the ground arena as a unit. The filter is the load-bearing half of
    // most of these cards, so it has to be enforced server-side on the way back too.
    // Stored rather than threaded through the finalize param because all 20 finalize handlers share
    // _topDeckResolveFromIDs — one store fixes every one of them without touching 20 signatures. Set
    // fresh on every search, and searches are strictly sequential (one pending decision at a time).
    // The '~' sentinel distinguishes "a filter is in force and NOTHING matched" from "no filter stored".
    // Without it an empty match list reads as "unrestricted", which is the exact inversion of what it
    // means — and it is the common case (a search whose top N contains no legal card at all).
    DecisionQueueController::StoreVariable("TopDeckLegalIDs", '~' . $matchIDs);
    // The CONSTRAINT ("count:N" / "cost:N" / "cost:N:M") was client-enforced only, exactly like the
    // filter. SOR_087 Darth Vader's "any number of Villainy units with combined cost 3 or LESS" happily
    // played two cost-2 units for a combined 4.
    DecisionQueueController::StoreVariable("TopDeckConstraint", $constraint);
    $param = $allIDs . '|' . $matchIDs . '|' . $constraint . '|' . $costMap;
    DecisionQueueController::AddDecision($player, "TOPDECKSEARCH", $param, 1, tooltip: "Search_top_cards");
    // Embed allIDs in the finalize param — survives the HTTP request boundary. dontSkipOnPass: when the search
    // has NO valid pick it auto-skips (a PASS), which would otherwise skip this finalize too — leaving the
    // peeked cards (already array_spliced off the deck) milled instead of returned to the bottom (ASH_224).
    DecisionQueueController::AddDecision($player, "CUSTOM", $finalizeHandler . '|' . $allIDs, 1, dontSkipOnPass: 1);
    MarkUndoRequiresConsent();
}

function DoTopDeckSearch(int $player, int $n, callable $filter, int $maxPicks): void {
    _topDeckSearchBegin($player, $n, $filter, "count:$maxPicks", "TOPDECKSEARCH_FINALIZE");
}

function DoTopDeckPlay(int $player, int $n, callable $filter, int $costBudget, int $maxCount = 0): void {
    // Constraint "cost:N" (any number within budget) or "cost:N:M" (≤M picks AND within budget,
    // e.g. SOR_104 U-Wing Reinforcement: up to 3 units, combined cost ≤7). Frontend-enforced.
    $constraint = $maxCount > 0 ? "cost:$costBudget:$maxCount" : "cost:$costBudget";
    _topDeckSearchBegin($player, $n, $filter, $constraint, "SOR_087#0");
}

// Resolve chosen CardIDs from $lastDecision against the flat list of all peeked IDs.
// Index-based dedup handles duplicate IDs (e.g. three copies of the same card).
// Returns ['drawn' => [cardID,...], 'remaining' => [cardID,...]].
function _topDeckResolveFromIDs(array $allIDs, string $lastDecision): array {
    $chosenIDs   = ($lastDecision !== '' && $lastDecision !== 'PASS')
        ? array_values(array_filter(explode(',', $lastDecision))) : [];
    // Server-side re-check of the search filter (stored by _topDeckSearchBegin — see the note there).
    // An illegal pick is not "drawn"; it falls through to `remaining`, which is the disposition the
    // callers already give an unpicked card (bottom of the deck), so no handler needs to change.
    // Membership is by CardID because every filter is a pure function of the CardID.
    // Absent/empty variable = no restriction, which keeps any future caller that stores nothing working.
    $legalRaw = (string) DecisionQueueController::GetVariable("TopDeckLegalIDs");
    if (strncmp($legalRaw, '~', 1) === 0) {                    // '~' = a filter is in force
        $legalIDs  = array_values(array_filter(explode(',', substr($legalRaw, 1))));
        $chosenIDs = array_values(array_filter($chosenIDs, fn($cid) => in_array($cid, $legalIDs, true)));
        // Consumed — a later resolve with no search of its own must not inherit this restriction.
        DecisionQueueController::StoreVariable("TopDeckLegalIDs", '');
        // Then the COUNT / COMBINED-COST constraint, applied to the picks in the order they were chosen:
        // accept while the budget holds and drop the overflow (it joins `remaining` → bottom of deck).
        $con = (string) DecisionQueueController::GetVariable("TopDeckConstraint");
        DecisionQueueController::StoreVariable("TopDeckConstraint", '');
        $maxPicks = PHP_INT_MAX; $maxCost = PHP_INT_MAX;
        if (preg_match('/^count:(\d+)$/', $con, $m))            { $maxPicks = intval($m[1]); }
        elseif (preg_match('/^cost:(\d+)(?::(\d+))?$/', $con, $m)) {
            $maxCost  = intval($m[1]);
            if (($m[2] ?? '') !== '') $maxPicks = intval($m[2]);
        }
        if ($maxPicks !== PHP_INT_MAX || $maxCost !== PHP_INT_MAX) {
            $kept = []; $spent = 0;
            foreach ($chosenIDs as $cid) {
                if (count($kept) >= $maxPicks) break;
                $c = intval(CardCost($cid));
                if ($spent + $c > $maxCost) continue;   // skip this one, a cheaper later pick may still fit
                $kept[] = $cid; $spent += $c;
            }
            $chosenIDs = $kept;
        }
    }
    $usedIndices = [];
    $drawnIDs    = [];
    foreach ($chosenIDs as $cid) {
        foreach ($allIDs as $idx => $aid) {
            if (!in_array($idx, $usedIndices, true) && $aid === $cid) {
                $drawnIDs[]    = $cid;
                $usedIndices[] = $idx;
                break;
            }
        }
    }
    $remainingIDs = [];
    foreach ($allIDs as $idx => $aid) {
        if (!in_array($idx, $usedIndices, true)) $remainingIDs[] = $aid;
    }
    return ['drawn' => $drawnIDs, 'remaining' => $remainingIDs];
}

// Shuffle remaining card IDs and push new Deck objects to the bottom of the deck.
function _topDeckPutRemainingToBottom(int $player, array $remainingIDs): void {
    shuffle($remainingIDs);
    $deck = &GetDeck($player);
    foreach ($remainingIDs as $cardID) {
        $obj          = new Deck($cardID, 'Deck', $player);
        $obj->mzIndex = count($deck);
        array_push($deck, $obj);
    }
    foreach ($deck as $i => $card) { $card->mzIndex = $i; }
}

// TOPDECKSEARCH_FINALIZE: draw chosen cards to hand; shuffle rest to bottom of deck.
$customDQHandlers["TOPDECKSEARCH_FINALIZE"] = function($player, $parts, $lastDecision) {
    global $playerID;
    $savedPID = $playerID; $playerID = intval($player);
    $allIDs  = array_values(array_filter(explode(',', $parts[0] ?? '')));
    $resolved = _topDeckResolveFromIDs($allIDs, $lastDecision ?? '');
    // These cards are DRAWN ("search … reveal it, and DRAW it"), so the when-you-draw observers must
    // fire exactly as they do for DoDrawCard — this path used to AddHand() silently, so LOF_148 Rey's
    // "when you draw this card during the action phase" never triggered off a search-and-draw
    // (SOR_123 Recruit, SOR_084, …). Capture the new hand slots to hand the observers real mzIDs.
    $handBefore = count(GetHand(intval($player)));
    foreach ($resolved['drawn'] as $cardID) {
        AddHand(intval($player), CardID: $cardID);
    }
    $drawnMz = [];
    for ($i = $handBefore; $i < count(GetHand(intval($player))); $i++) $drawnMz[] = "myHand-{$i}";
    _topDeckPutRemainingToBottom(intval($player), $resolved['remaining']);
    if (!empty($drawnMz)) {
        if (function_exists('_SWUOnPlayerDrew')) _SWUOnPlayerDrew(intval($player), count($drawnMz));
        _SWUOnDrawLof148(intval($player), $drawnMz);
    }
    $playerID = $savedPID;
};

// TWI_201 Aid from the Innocent — like TOPDECKSEARCH_FINALIZE, but the chosen cards are DISCARDED (not
// drawn); the rest go to the bottom of the deck in random order.
$customDQHandlers["TWI_201#0"] = function($player, $parts, $lastDecision) {
    $allIDs   = array_values(array_filter(explode(',', $parts[0] ?? '')));
    $resolved = _topDeckResolveFromIDs($allIDs, $lastDecision ?? '');
    foreach ($resolved['drawn'] as $cardID) {
        SWUAddToDiscard(intval($player), $cardID, 'DECK');
        // "For this phase, you may play the discarded cards, and they each cost 2 resources less."
        // This second sentence had no implementation at all — the cards were discarded and then simply
        // sat there. Stamp the newly added entry (the last non-removed one) with the at-cost-minus-2
        // discard modifier; SWUClearDiscardModifiers wipes it at regroup, giving the "this phase" bound.
        $d = &GetDiscard(intval($player));
        for ($i = count($d) - 1; $i >= 0; $i--) {
            if (!empty($d[$i]->removed)) continue;
            if (($d[$i]->CardID ?? '') === $cardID) { $d[$i]->Modifier = 'TPP2'; break; }
        }
        unset($d);
    }
    _topDeckPutRemainingToBottom(intval($player), $resolved['remaining']);
};

// LOF_103 Following the Path: chosen Force units go on TOP of the deck (chosen order; first chosen ends
// up on top); the non-chosen peeked cards go to the bottom in random order.
$customDQHandlers["LOF_103#0"] = function($player, $parts, $lastDecision) {
    $allIDs   = array_values(array_filter(explode(',', $parts[0] ?? '')));
    $resolved = _topDeckResolveFromIDs($allIDs, $lastDecision ?? '');
    _topDeckPutRemainingToBottom(intval($player), $resolved['remaining']);
    $deck = &GetDeck(intval($player));
    $chosen = $resolved['drawn'];
    for ($i = count($chosen) - 1; $i >= 0; $i--) {
        $obj = new Deck($chosen[$i], 'Deck', intval($player));
        array_unshift($deck, $obj);
    }
    foreach ($deck as $i => $card) { $card->mzIndex = $i; }
};

// SOR_087#0 — the shared finalize for every "search the deck and play them for FREE" card
// (SOR_087 Vader, SOR_104 U-Wing Reinforcement, LAW_063 L3-37, ASH_110 Admiral Ackbar, SHD_123
// Bounty Hunter's Quarry via DoTopDeckPlay).
//
// ⚠ "PLAY them" is a REAL PLAY, not a put-into-play. This used to place the picks with a bare
// AddGroundArena/AddSpaceArena, so the fetched unit's own When Played never fired, no entry ceremony
// ran, and nothing was nested — directly observable (a fetched Salacious Crumb healed nothing).
// Now each pick is played SEQUENTIALLY through the real pipeline via TOPDECK_PLAY_NEXT below: play one,
// let its triggers drain, then the next — the queue is the ordering authority, so a When Played that
// raises decisions cannot be jumped by the next play (the SEC_018 ordering family).
$customDQHandlers["SOR_087#0"] = function($player, $parts, $lastDecision) {
    global $playerID;
    $savedPID = $playerID;
    $playerID = intval($player);
    $allIDs   = array_values(array_filter(explode(',', $parts[0] ?? '')));
    $resolved = _topDeckResolveFromIDs($allIDs, $lastDecision ?? '');
    _topDeckPutRemainingToBottom(intval($player), $resolved['remaining']);
    if (!empty($resolved['drawn'])) {
        DecisionQueueController::AddDecision(intval($player), "CUSTOM",
            "TOPDECK_PLAY_NEXT|" . implode(',', $resolved['drawn']), 1);
    }
    $playerID = $savedPID;
};

// TOPDECK_PLAY_NEXT — pop one CardID off the list, real-play it for FREE from the top of the deck, then
// re-queue itself with the rest. Queued AFTER the play call so the played card's own trigger decisions
// (already appended by ActivateCard) resolve BEFORE the next play.
// Free play ⇒ ActivateCard(ignoreCost) ⇒ no cost, aspect penalty included, and the Piloting Unit-vs-
// Pilot branch is skipped — matching the rule that a play-from-search plays the UNIT it searched for.
// SWU_CARDS_PLAYED is NOT bumped here: ActivateCard does it on the real path (it was manual before).
$customDQHandlers["TOPDECK_PLAY_NEXT"] = function($player, $parts, $lastDecision) {
    global $playerID;
    $playerID = intval($player);
    $queue  = array_values(array_filter(explode(',', $parts[0] ?? '')));
    if (empty($queue)) return;
    $cardID = array_shift($queue);
    // SOR_062 Regional Governor: a named card can't be played, even from the deck. Not placed;
    // it goes to the bottom with the rest.
    if (SWUCardPlayBlocked(intval($player), $cardID)) {
        _topDeckPutRemainingToBottom(intval($player), [$cardID]);
    } else {
        $deck = &GetDeck(intval($player));
        $obj  = new Deck($cardID, 'Deck', intval($player));
        array_unshift($deck, $obj);
        foreach ($deck as $i => $c) { $c->mzIndex = $i; }
        SWUPlayTopDeckCard(intval($player), true);
    }
    if (!empty($queue)) {
        DecisionQueueController::AddDecision(intval($player), "CUSTOM",
            "TOPDECK_PLAY_NEXT|" . implode(',', $queue), 1);
    }
};

// SOR_199 Bamboozle: handles the alternate-cost YESNO answer.
// YES → discard the first Cunning card found in player's hand (Bamboozle is already in discard).
// NO  → exhaust resources equal to the normal cost encoded in $parts[0].
$customDQHandlers["SOR_199#0"] = function($player, $parts, $lastDecision) {
    if ($lastDecision === "YES" || $lastDecision === "1") {
        global $playerID;
        $playerID = intval($player);
        $hand = GetHand($player);
        for ($i = 0; $i < count($hand); $i++) {
            if (!empty($hand[$i]->removed)) continue;
            if (strpos(CardAspect($hand[$i]->CardID) ?? '', 'Cunning') !== false) {
                $hand[$i]->removed = true;
                SWUAddToDiscard($player, $hand[$i]->CardID, 'HAND');
                DecisionQueueController::CleanupRemovedCards();
                return;
            }
        }
    } else {
        // The alternate-cost card's normal resource cost — a payable cost, so Credits/Droids apply.
        SWUPayInlineAbilityCost($player, intval($parts[0] ?? 0));
    }
};

// SOR_199 Bamboozle: exhausts the chosen unit and bounces all upgrades to their owners' hands.
// Token upgrades are set aside (SWUDefeatUpgrade bounce:true handles this).
$customDQHandlers["SOR_199#1"] = function($player, $parts, $lastDecision) {
    if ($lastDecision === null || $lastDecision === '-' || $lastDecision === '' || $lastDecision === 'PASS') return;
    global $playerID;
    $playerID = intval($player);
    $obj = GetZoneObject($lastDecision);
    if ($obj === null || ($obj->removed ?? false)) return;
    $obj->Status = 0;
    // "EACH upgrade" — an upgrade that CAN'T be returned (SEC_061 Willrow Hood's protected lone friendly
    // upgrade, JTL_012's pilot immunity) must be SKIPPED, not treated as the end of the list. Walking a
    // fixed index 0 would stop dead on the first protected upgrade and strand every later one, so advance
    // the index only when a return is refused; on success the list shifts down into the same slot.
    $idx = 0;
    $pinnedUID = SWUPinWillrowUpgradeCount($obj);
    for ($guard = 0; $guard < 64; $guard++) {
        $host = GetZoneObject($lastDecision);
        if ($host === null || ($host->removed ?? false)) break;
        $live = 0;
        foreach (($host->Subcards ?? []) as $sub) {
            $isCaptive = is_array($sub) ? !empty($sub['IsCaptive']) : !empty($sub->IsCaptive);
            $isRemoved = is_array($sub) ? !empty($sub['removed'])   : !empty($sub->removed);
            if (!$isCaptive && !$isRemoved) $live++;
        }
        if ($idx >= $live) break;
        if (!SWUDefeatUpgrade($player, $lastDecision, $idx, bounce: true)) $idx++;
    }
    SWUUnpinWillrowUpgradeCount($pinnedUID);
    DecisionQueueController::CleanupRemovedCards();
};

// Returns an array of valid arena mzIDs that the given upgrade can target.
// Defaults to all friendly units (ground + space). Card-specific restrictions
// are handled in the switch statement below.
//
// $upgradeObj (optional): when provided, the returned list is further filtered to
// only hosts the player can actually afford at the host-specific cost — i.e.,
// SWUComputePlayCost($player, $upgradeObj, $candidateObj) ≤ ready resources.
// This closes the "attach to non-Guardian even though you can only afford Guardian" edge.
// $discount: subtracted from that host-specific cost before the comparison. ⚠ REQUIRED whenever the
// caller is playing the upgrade at a reduction, or the gate prices the card at FULL cost and returns an
// empty host list — the play then dies as "No valid targets for upgrade" and the card is stranded in
// hand. SHD_194 Triple Dark Raid ("play it… it costs 5 resources less") hit exactly that: a Vehicle
// UPGRADE was correctly offered by its search and could never actually be played.
function SWUGetUpgradeValidTargets(int $player, string $cardID, $upgradeObj = null, int $discount = 0): array {
    global $playerID;
    $savedPID = $playerID;
    // FORTIFY (HMW) — "Attach this to your base, not a unit." The ONLY legal host is the player's own
    // base, so returning it here gives BOTH guards from one branch: a Fortify upgrade is never offered
    // a unit, and no other upgrade is ever offered the base. ActivateCard's single-target path then
    // auto-passes it into ATTACH_UPGRADE → _SWUFinalizeUpgradeAttach, which hosts on any zone object —
    // so payment, the aspect surcharge, Tarkin's HMW_004 penalty waiver ($discount), uniqueness, and
    // the WhenPlayedAsUpgrade / OnAttached triggers all come along unchanged.
    if (HasKeyword_Fortify((object) ['CardID' => $cardID, 'TurnEffects' => []])) {
        $playerID = $savedPID;
        return ['myBase-0'];
    }
    // DEFAULT = EVERY unit in play, both sides, both arenas. Per CR 2.e an upgrade with no printed
    // controller restriction may be played onto an ENEMY unit (and that unit's controller then resolves
    // anything it grants), so "any unit" is the RULE and every narrowing below is the exception.
    // ⚠ This was inverted until 2026-08-17: the default used to be friendly-arenas-only and the switch
    // carried a 32-case fall-through group whose only job was to restore the rules-default for cards
    // somebody had reported. That made the switch an ALLOWLIST — an upgrade nobody had thought about was
    // silently friendly-only, which inverted whole cards (LAW_127 Kill Switch, LAW_141 Targeted For
    // Removal, TWI_070 Perilous Position: pure drawbacks playable only on your own units). Those 32 cases
    // were deleted when the default flipped; they are the default now.
    // ⛔ Cases below that carry their OWN body must come AFTER a completed body — never between the bare
    // labels of a fall-through group, which would silently re-point every label above them.
    $playerID = $player;
    $all = array_merge(
        ZoneSearch("myGroundArena",    AnyUnitFilter),
        ZoneSearch("mySpaceArena",     AnyUnitFilter),
        ZoneSearch("theirGroundArena", AnyUnitFilter),
        ZoneSearch("theirSpaceArena",  AnyUnitFilter)
    );
    $playerID = $savedPID;
    switch ($cardID) {
        // "Attach to a FRIENDLY unit." — the printed word narrows the rules default back to your own
        // arenas. These four relied on the OLD friendly-only default and so had no case of their own;
        // with the default inverted they need one.
        case 'SHD_251': // The Mandalorian's Rifle — "attach to a friendly non-Vehicle unit" (Vehicle filter below)
        case 'SHD_124': // Legal Authority
        case 'LOF_091': // Craving Power
        case 'SEC_069': // Nimble Prowess
            $playerID = $player;
            $all = array_merge(
                ZoneSearch("myGroundArena", AnyUnitFilter),
                ZoneSearch("mySpaceArena",  AnyUnitFilter)
            );
            if ($cardID === 'SHD_251') {
                $all = array_values(array_filter($all, function($mz) {
                    $o = GetZoneObject($mz);
                    return !SWUObjGone($o) && !HasTrait($o->CardID ?? '', 'Vehicle');
                }));
            }
            $playerID = $savedPID;
            break;
        // "Attach to a friendly ground unit." (ASH_230 Improvised Identity — attach condition is a
        // GroundArena unit; a space unit is not a legal host.)
        case 'ASH_230':
            $playerID = $player;
            $all = ZoneSearch("myGroundArena", AnyUnitFilter);
            $playerID = $savedPID;
            break;
        // "Attach to a non-Vehicle unit."
        case 'SOR_053': // Luke's Lightsaber
        case 'SOR_054': // Jedi Lightsaber
        case 'SHD_126': // The Darksaber
        case 'SHD_074': // Vambrace Grappleshot
        // ⚠ SET-WIDE AUDIT (2026-08-15): these ten all print the plain, unqualified "Attach to a
        // non-Vehicle unit." and were absent from the switch ENTIRELY, so they fell through to the
        // DEFAULT pool — which is friendly-arenas-only AND has no Vehicle filter. Two defects each:
        // a Vehicle was offered despite the printed restriction, and an ENEMY non-Vehicle was not
        // offered despite CR 2.e (no controller named => either side). Found by generalising two
        // single-card reports (SHD_074, SHD_104); every one was text-checked for a "friendly" or
        // trait qualifier before being added here.
        case 'SHD_073': // Mandalorian Armor
        case 'SHD_104': // Inspiring Mentor
        case 'SHD_177': // Vambrace Flamethrower
        case 'SHD_224': // Boba Fett's Armor
        case 'LOF_090': // Inquisitor's Lightsaber
        case 'LAW_150': // Fulcrum
        case 'LAW_186': // Enfys Nest's Helmet
        case 'LAW_187': // "Staccato Lightning" Repeater
        case 'LAW_201': // Thermal Detonator
        case 'ASH_055': // Blade of Talzin
        case 'LOF_215': // Ascension Cable
        case 'SOR_137': // Fallen Lightsaber
        case 'SOR_136': // Vader's Lightsaber
        case 'SOR_071': // Electrostaff
        case 'LOF_040': // Kylo Ren's Lightsaber
        case 'LOF_053': // Heirloom Lightsaber
        case 'LOF_102': // Yoda's Lightsaber
        case 'LOF_122': // Pillio Star Compass
        case 'LOF_171': // Heavy Blaster Cannon
        case 'LOF_187': // Corrupted Saber
        case 'LOF_140': // Maul's Lightsaber
        case 'LOF_201': // Qui-Gon Jinn's Lightsaber
        case 'LOF_238': // Darth Revan's Lightsabers
        case 'SEC_156': // Nemik's Manifesto
        case 'LAW_200': // Salvaged Blaster
        case 'LAW_111': // Leia's Disguise
        case 'LAW_126': // Adventurer Sniper Rifle
        case 'ASH_180': // Bokken Saber
        case 'ASH_066': // Luke's Jedi Lightsaber
        case 'ASH_114': // Sabine's Lightsaber
        case 'ASH_183': // Whistling Birds
        case 'ASH_210': // DDC Defender
        case 'SHD_174': // Hotshot DL-44 Blaster
        case 'SHD_225': // Jetpack
        case 'TWI_236': // Grievous's Wheel Bike
        case 'TWI_256': // Hold-Out Blaster
        case 'TWI_152': // Mace Windu's Lightsaber
        case 'TWI_121': // General's Blade
        case 'TWI_248': // Ahsoka's Padawan Lightsaber
        case 'TS26_22': // The Darksaber
        case 'TS26_35': // Ahsoka's Lightsabers
        case 'TS26_52': // Sith Traditions
        case 'TS26_63': // Rex's DC-17s
        case 'HMW_127': // Chewbacca's Bowcaster
            // "Attach to a non-Vehicle unit." No "friendly" qualifier → any non-Vehicle unit, friendly OR
            // enemy, is a legal host (CR 2.e — a player may play an upgrade onto an enemy unit; if it grants
            // abilities, the attached unit's controller resolves them). Rebuild from all four arenas, then
            // filter out Vehicles (mirrors the "Vehicle unit" group below).
            $playerID = $player;
            $all = array_values(array_filter(array_merge(
                ZoneSearch("myGroundArena",    AnyUnitFilter),
                ZoneSearch("mySpaceArena",     AnyUnitFilter),
                ZoneSearch("theirGroundArena", AnyUnitFilter),
                ZoneSearch("theirSpaceArena",  AnyUnitFilter)
            ), fn($mz) => !HasTrait(GetZoneObject($mz)->CardID ?? '', 'Vehicle')));
            $playerID = $savedPID;
            break;
        // "Attach to a unit that costs 4 or less."
        case 'TS26_79': // Underestimated
            $all = array_values(array_filter($all, fn($mz) => intval(CardCost(GetZoneObject($mz)->CardID ?? '')) <= 4));
            break;
        // "Attach to a token unit."
        case 'TWI_119': // Nameless Valor
            $all = array_values(array_filter($all, fn($mz) => strpos(CardType(GetZoneObject($mz)->CardID ?? '') ?? '', 'Token') !== false));
            break;
        // "Attach to a damaged unit." (Mark My Words gives Overwhelm — a friendly damaged unit.)
        case 'ASH_181':
            $all = array_values(array_filter($all, fn($mz) => intval(GetZoneObject($mz)->Damage ?? 0) > 0));
            break;
        // "Attach to a friendly unique unit."
        case 'SEC_256': // Moral Authority
            $all = array_values(array_filter($all, fn($mz) =>
                CardUnique(GetZoneObject($mz)->CardID ?? '')));
            break;
        // "Attach to a <uq> non-Vehicle unit."
        case 'ASH_135': // The Darksaber
            $all = array_values(array_filter($all, function($mz) {
                $cid = GetZoneObject($mz)->CardID ?? '';
                return CardUnique($cid) && !HasTrait($cid, 'Vehicle');
            }));
            break;
        // "Attach to a Jedi non-Vehicle unit."
        case 'LOF_151': // Knight's Saber
            $all = array_values(array_filter($all, function($mz) {
                $cid = GetZoneObject($mz)->CardID ?? '';
                return HasTrait($cid, 'Jedi') && !HasTrait($cid, 'Vehicle');
            }));
            break;
        // "Attach to a Force unit."
        case 'LOF_051': // Jedi Holocron
        case 'LOF_052': // Jedi Trials
        case 'LOF_074': // Bolstered Endurance
        case 'LOF_138': // Sith Holocron
        case 'LOF_261': // Constructed Lightsaber
            $all = array_values(array_filter($all, fn($mz) =>
                TraitContains(GetZoneObject($mz), 'Force')));
            break;
        // "Attach to a Vehicle unit." No "friendly" qualifier → any Vehicle, friendly OR enemy, is a legal
        // host (rebuild from all four arenas, then filter by the Vehicle trait). The granted combat "defeat
        // that unit" trigger is already controller-agnostic, so an enemy-hosted turret works.
        case 'JTL_120': // Dorsal Turret
        case 'JTL_172': // Twin Laser Turret
        case 'SOR_121': // Hardpoint Heavy Blaster
        case 'SOR_214': // Smuggling Compartment — was absent from this group (default friendly-any pool
                        // offered Troopers); the granted "On Attack: Ready a resource" resolves for the
                        // HOST's controller on an enemy host, CR 2.e.
        case 'SEC_227': // Special Modifications — was a friendly-only filter (group reconciliation
                        // 2026-08-13); same unqualified "Attach to a Vehicle unit" as the rest.
            $playerID = $player;
            $all = array_values(array_filter(array_merge(
                ZoneSearch("myGroundArena",    AnyUnitFilter),
                ZoneSearch("mySpaceArena",     AnyUnitFilter),
                ZoneSearch("theirGroundArena", AnyUnitFilter),
                ZoneSearch("theirSpaceArena",  AnyUnitFilter)
            ), fn($mz) => HasTrait(GetZoneObject($mz)->CardID ?? '', 'Vehicle')));
            $playerID = $savedPID;
            break;
        // "Attach to a Capital Ship or Transport unit." (JTL_227 Superheavy Ion Cannon)
        case 'JTL_227':
            // TraitContains, not bare-CardID HasTrait: the host is IN PLAY, so a deployed leader's
            // deployed-side trait line (HMW_004 → The Death Star, a Capital Ship) must count.
            $all = array_values(array_filter($all, function($mz) {
                $o = GetZoneObject($mz);
                return TraitContains($o, 'Capital Ship') || TraitContains($o, 'Transport');
            }));
            break;
        // "Attach to a UNIQUE unit." No controller word → either side (CR 2.e), but the host must be
        // unique. SEC_104 was absent from the switch entirely, so it had NEITHER guard: it fell through to
        // the friendly-only default AND offered non-unique friendly hosts.
        // ⚠ This case carries its OWN body, so it MUST sit after a completed body — never inside the
        // fall-through chain above, which would silently re-point every case listed before it into here.
        // Guarded by SEC_104's AttachPool_UNIQUEUnitsOnly_EitherSide.
        case 'SEC_104': // Figure of Unity
            $playerID = $player;
            $all = array_values(array_filter(array_merge(
                ZoneSearch("myGroundArena",    AnyUnitFilter),
                ZoneSearch("mySpaceArena",     AnyUnitFilter),
                ZoneSearch("theirGroundArena", AnyUnitFilter),
                ZoneSearch("theirSpaceArena",  AnyUnitFilter)
            ), function($mz) {
                $o = GetZoneObject($mz);
                return !SWUObjGone($o) && !empty(CardUnique($o->CardID ?? ''));
            }));
            $playerID = $savedPID;
            break;
        // "Attach to a NON-LEADER unit" (no "friendly") — both sides, both arenas, leader units
        // excluded (a deployed leader / Darksaber host is not a legal host; the exclusion is the
        // printed restriction, unlike the SHD bounty group's tolerated over-permissiveness).
        // ── "Attach to a NON-LEADER unit." — the WHOLE printed-text family ────────────────────────
        // No controller word, so per CR 2.e the pool spans BOTH sides; "non-leader" then removes only
        // deployed leaders. Three of these are pure downside (Imprisoned, Frozen in Carbonite, Shadow
        // of Stygeon Prime) and are unplayable as designed if they cannot reach an enemy unit.
        // Consolidated 2026-08-16 after LAW_077 was found missing: the switch is keyed by CardID, so a
        // card absent from it silently falls through to the friendly-only default `$all` — which is
        // BOTH defects at once (no enemy hosts, deployed leaders offered). TWI_122 was worse than
        // absent: it had its own case that filtered leaders out of the friendly-only default, so it
        // looked handled while still missing every enemy host.
        // Auto-resolution is what hid all of it — with one friendly unit on the board the attach never
        // prompts, so no assertion ever saw the pool.
        case 'LAW_128': // Veiled Strength — was friendly-only AND offered the deployed leader
        case 'SHD_072': // Imprisoned — printed "Attach to a non-leader unit"; it was in the
                        // no-filter group above, so it offered DEPLOYED LEADERS as hosts.
        case 'TWI_122': // Squad Support — had a friendly-only case of its own
        case 'SHD_053': // Second Chance — absent from the switch
        case 'SHD_193': // Frozen in Carbonite — absent from the switch
        case 'LAW_077': // Shadow of Stygeon Prime — absent from the switch
            $playerID = $player;
            $all = array_values(array_filter(array_merge(
                ZoneSearch("myGroundArena",    AnyUnitFilter),
                ZoneSearch("mySpaceArena",     AnyUnitFilter),
                ZoneSearch("theirGroundArena", AnyUnitFilter),
                ZoneSearch("theirSpaceArena",  AnyUnitFilter)
            ), function($mz) {
                $o = GetZoneObject($mz);
                return !SWUObjGone($o) && !IsLeaderUnit($o);
            }));
            $playerID = $savedPID;
            break;
    }

    // Affordability filter: when the upgrade object is provided, only keep hosts whose
    // host-specific cost is ≤ the player's current ready-resource count.
    if ($upgradeObj !== null) {
        $ready = 0;
        foreach (GetResources($player) as $r) {
            if (SWUIsCreditToken($r->CardID ?? '')) continue; // Credit tokens aren't resources
            if (empty($r->removed) && intval($r->Status) === 1) $ready++;
        }
        // Alt-payment capacity (mirrors the actual payment chain SWUOfferAltPayment → Credits then SEC_122
        // Droids): a host is affordable if ready resources PLUS defeatable Credit tokens PLUS — with Vuutun
        // Palaa in play — exhaustible friendly Droids cover its cost. Without this, an upgrade payable only
        // via Droids/Credits was filtered out entirely, so the play silently fizzled ("No valid targets").
        $ready += count(SWUUsableCreditTokenMzIDs($player));
        if (SWUPlayerControlsSEC122($player)) $ready += count(SWUReadyFriendlyDroids($player));
        $all = array_values(array_filter($all, function($mz) use ($player, $upgradeObj, $ready, $discount) {
            $candidateObj = GetZoneObject($mz);
            if (SWUObjGone($candidateObj)) return false;
            $hostCost = max(0, SWUComputePlayCost($player, $upgradeObj, $candidateObj) - max(0, $discount));
            $hostCost = SWUApplyCostHalving($player, $hostCost); // JTL_105 The Starhawk — halved targets must glow too
            return $ready >= $hostCost;
        }));
    }

    return $all;
}

// Whether $destObj is a legal host for an upgrade printed $upgradeCardID, honoring the upgrade's printed
// "Attach to a [X] unit" restriction — controller-agnostic (works for an enemy destination). Reuses
// SWUGetUpgradeValidTargets (the single source of truth for attach restrictions) queried from the
// DESTINATION's own controller frame; passes no $upgradeObj so the affordability filter is skipped (a
// MOVE has no cost). A token / unrestricted upgrade falls through to "any unit of that controller" → true.
function _SWUUpgradeCanAttachTo($destObj, string $upgradeCardID): bool {
    if (SWUObjGone($destObj) || $upgradeCardID === '') return false;
    $dctrl = intval($destObj->Controller ?? $destObj->Owner ?? 0);
    if ($dctrl <= 0) return false;
    $duid = intval($destObj->UniqueID ?? -1);
    // ⚠ FRAME: SWUGetUpgradeValidTargets returns mzIDs built in $dctrl's perspective (it sets
    // $playerID = $dctrl internally and restores it before returning). Resolving them under whatever
    // frame the CALLER happens to be in reads the wrong seat's arenas, every UID comparison misses, and
    // the function answers "no legal host" for every enemy-controlled destination — which silently
    // emptied MOVE_UPGRADE's destination list whenever the host was an opponent's unit (SHD_064
    // Survivors' Gauntlet moving an upgrade between two ENEMY units). Resolve in the same frame that
    // minted the mzIDs. (Cross-seat frame family — see the deferred-damage frame-mismatch note.)
    global $playerID;
    $savedPID = $playerID;
    $playerID = $dctrl;
    $found = false;
    foreach (SWUGetUpgradeValidTargets($dctrl, $upgradeCardID) as $mz) {
        $o = GetZoneObject($mz);
        if ($o !== null && intval($o->UniqueID ?? -2) === $duid) { $found = true; break; }
    }
    $playerID = $savedPID;
    return $found;
}

// Number of Pilot upgrades currently on a host (Subcards flagged IsPilot).
function SWUVehiclePilotCount($host): int {
    if ($host === null || !is_array($host->Subcards ?? null)) return 0;
    $n = 0;
    foreach ($host->Subcards as $sub) {
        $isPilot = is_array($sub) ? ($sub['IsPilot'] ?? false) : ($sub->IsPilot ?? false);
        if ($isPilot) $n++;
    }
    return $n;
}

// Max pilots a host may carry: 1 by default, +1 per "additional Pilot" grant
// (the host's own innate, e.g. Millennium Falcon, plus any attached pilot that
// grants it, e.g. R2-D2). CR 8.346.c — these grants override the base restriction.
function SWUVehiclePilotCapacity($host): int {
    if ($host === null) return 0;
    $cap = 1;
    if (CardPilotAddsCapacity($host->CardID ?? '')) $cap++;
    foreach (GetUpgradesOnUnit($host) as $u) {
        if (CardPilotAddsCapacity($u->CardID ?? '')) $cap++;
    }
    return $cap;
}

// Whether $pilotCardID may attach as a Pilot to $host right now.
// Default: host is a friendly Vehicle AND current pilots < capacity.
// Per-card overrides mirror SWUGetUpgradeValidTargets.
//
// $context controls which rule set applies:
//   'piloting'   (default) — normal Piloting hand-play / leader-deploy path;
//                uses the generic count < capacity rule for all pilots including JTL_100.
//   'freeattach' — JTL_100's own "when played as a unit" free-attach ability
//                (Task 10); applies the strict "0 pilots on host" rule.
//
// R2-D2's CardPilotIgnoresOccupied override applies in BOTH contexts.
function SWUPilotCanAttach(string $pilotCardID, $host, string $context = 'piloting'): bool {
    if (SWUObjGone($host)) return false;
    $hostID = $host->CardID ?? '';
    if (!HasTrait($hostID, 'Vehicle')) return false;

    // R2-D2 (JTL_245): may attach to a Vehicle WITH a Pilot already on it.
    // This override applies regardless of context.
    if (CardPilotIgnoresOccupied($pilotCardID)) return true;

    // Poe Dameron unit (JTL_100) free-attach clause: strict "without a Pilot"
    // (capacity grants do NOT loosen this specific ability — CR card text).
    // Only applies in the 'freeattach' context (Task 10).
    // In 'piloting' context JTL_100 uses the generic capacity rule below.
    if ($pilotCardID === 'JTL_100' && $context === 'freeattach') {
        return SWUVehiclePilotCount($host) === 0;
    }

    return SWUVehiclePilotCount($host) < SWUVehiclePilotCapacity($host);
}

// Friendly Vehicles a pilot may attach to right now, affordability-filtered
// against the piloting cost. Mirrors the affordability filter in
// SWUGetUpgradeValidTargets.
function SWUGetPilotValidTargets(int $player, string $pilotCardID, bool $ignoreCost = false, int $discount = 0): array {
    global $playerID;
    $savedPID = $playerID;
    $playerID = $player;
    $all = array_merge(
        ZoneSearch("myGroundArena", AnyUnitFilter),
        ZoneSearch("mySpaceArena",  AnyUnitFilter)
    );
    $playerID = $savedPID;

    // A FREE pilot-play (e.g. LAW_215 Vermillion's revealed-card free play) has no cost, so the
    // affordability gate must be skipped — otherwise a broke player is wrongly offered no hosts.
    if (!$ignoreCost) {
        $pilotObj = (object)['CardID' => $pilotCardID];
        $cost = SWUComputePilotCost($player, $pilotObj);
        $cost = SWUApplyCostHalving($player, $cost); // JTL_105 The Starhawk — halved targets must glow too
        $cost = max(0, $cost - max(0, $discount));   // discounted plays (You're My Only Hope -5) gate on the REAL price
        $ready = 0;
        foreach (GetResources($player) as $r) {
            if (SWUIsCreditToken($r->CardID ?? '')) continue; // Credit tokens aren't resources
            if (empty($r->removed) && intval($r->Status) === 1) $ready++;
        }
        if ($ready < $cost) return [];
    }

    return array_values(array_filter($all, function($mz) use ($pilotCardID) {
        $hostObj = GetZoneObject($mz);
        return SWUPilotCanAttach($pilotCardID, $hostObj);
    }));
}

// Friendly Vehicles a leader may deploy onto as a Pilot (capacity-only; deploy is free).
// No affordability check — the deploy threshold is the only gate. Mirrors the
// $playerID save/restore idiom used throughout this file.
function SWUGetLeaderPilotVehicles(int $player): array {
    global $playerID;
    $savedPID = $playerID;
    $playerID = $player;
    $all = array_merge(
        ZoneSearch("myGroundArena", AnyUnitFilter),
        ZoneSearch("mySpaceArena",  AnyUnitFilter)
    );
    $playerID = $savedPID;
    return array_values(array_filter($all, function($mz) {
        $hostObj = GetZoneObject($mz);
        if (SWUObjGone($hostObj)) return false;
        if (!HasTrait($hostObj->CardID ?? '', 'Vehicle')) return false;
        return SWUVehiclePilotCount($hostObj) < SWUVehiclePilotCapacity($hostObj);
    }));
}

// JTL_013 Poe Dameron leader Action: returns mzIDs of friendly Vehicles with exactly 0 pilots.
// Used both as the affordability guard and as the attach target list.
// "Without a Pilot on it" = strict 0-pilot check (SWUVehiclePilotCount === 0), not the
// capacity-based check used by normal Piloting; Poe's action text requires no pilot at all.
function SWUGetPoe013AttachVehicles(int $player): array {
    global $playerID;
    $savedPID = $playerID;
    $playerID = $player;
    $all = array_merge(
        ZoneSearch("myGroundArena", AnyUnitFilter),
        ZoneSearch("mySpaceArena",  AnyUnitFilter)
    );
    $playerID = $savedPID;
    return array_values(array_filter($all, function($mz) {
        $hostObj = GetZoneObject($mz);
        if (SWUObjGone($hostObj)) return false;
        if (!HasTrait($hostObj->CardID ?? '', 'Vehicle')) return false;
        return SWUVehiclePilotCount($hostObj) === 0;
    }));
}

// Returns true when $cardID's alternate cost path is available for $player right now.
// For SOR_199: hand must have ≥2 Cunning cards — Bamboozle itself is Cunning, so
// ≥2 means there is at least one other Cunning card available to discard.
function SWUCheckAlternateCost(int $player, string $cardID): bool {
    switch ($cardID) {
        case 'SOR_199': {
            $count = 0;
            foreach (GetHand($player) as $h) {
                if (!empty($h->removed)) continue;
                if (strpos(CardAspect($h->CardID) ?? '', 'Cunning') !== false) $count++;
            }
            return $count >= 2;
        }
        default:
            return false;
    }
}

// Returns mzIDs of all arena units (both players, both arenas) that have at
// least one non-captive upgrade. Caller must have $playerID set correctly.
// A host counts only if it carries >=1 upgrade matching $filter (empty filter =
// every upgrade matches, so this is backward-compatible for all existing callers).
// NOTE the name is historical: since Fortify (base-attached upgrades) this returns every upgrade
// HOST — arena units AND bases — which is required so "defeat an upgrade" cards can reach a base
// upgrade at all. Only 2 callers, both in the defeat-upgrade flow, both intending to include bases.
function SWUGetUnitsWithUpgrades(string $filter = ''): array {
    $result = [];
    foreach (['myGroundArena', 'mySpaceArena', 'theirGroundArena', 'theirSpaceArena'] as $zone) {
        foreach (ZoneSearch($zone, ['Unit', 'Leader Unit', 'Token Unit']) as $mzID) {
            $obj = GetZoneObject($mzID);
            if ($obj === null || ($obj->removed ?? false)) continue;
            foreach (GetUpgradesOnUnit($obj) as $up) {
                if (SWUUpgradeMatchesFilter($up->CardID ?? '', $filter)) {
                    $result[] = $mzID;
                    break;
                }
            }
        }
    }
    // Bases: FORTIFY upgrades live in Base.Subcards. GetUpgradesOnUnit expects a unit, so read the
    // subcards directly (a base holds only Fortify upgrades — no pilots, no captives). Without this,
    // a base upgrade is invisible to EVERY "defeat an upgrade" card in the game (Confiscate SOR_251).
    foreach (['myBase-0', 'theirBase-0'] as $baseMz) {
        $base = GetZoneObject($baseMz);
        if ($base === null) continue;
        // GetUpgradesOnUnit normalizes round-tripped array subcards to objects (see BaseUpgradeCount).
        foreach (GetUpgradesOnUnit($base) as $up) {
            if (SWUUpgradeMatchesFilter($up->CardID ?? '', $filter)) {
                $result[] = $baseMz;
                break;
            }
        }
    }
    return $result;
}

// Every matching upgrade in play, addressed as a SUBCARD mzID ("<hostMz>.u<subIdx>" — see
// MZParseSubcardID). The upgrade-level counterpart of SWUGetUnitsWithUpgrades: same zones, same
// filter, same base handling (Fortify upgrades live in Base.Subcards), but it names the UPGRADES
// rather than the units carrying them — so "defeat an upgrade" can be a single decision that
// highlights the upgrades on the board, instead of a host pick followed by a context-free popup.
//
// The sub index is the RAW Subcards key. Eligibility mirrors GetUpgradesOnUnit exactly (skip captives
// and removed entries); SWUDefeatUpgrade indexes by a *different* space — the live-upgrade ordinal —
// so convert with SWUUpgradeOrdinalFromSubIndex, never pass a raw key straight through.
function SWUGetUpgradeSubcardMzIDs(string $filter = '', int $onlyHostUID = 0): array {
    $result = [];
    $scan = function(string $hostMz) use (&$result, $filter, $onlyHostUID) {
        $obj = GetZoneObject($hostMz);
        if ($obj === null || ($obj->removed ?? false)) return;
        if ($onlyHostUID > 0 && intval($obj->UniqueID ?? 0) !== $onlyHostUID) return;
        if (!is_array($obj->Subcards ?? null)) return;
        foreach ($obj->Subcards as $key => $sub) {
            $isCaptive = is_array($sub) ? !empty($sub['IsCaptive']) : !empty($sub->IsCaptive);
            $isRemoved = is_array($sub) ? !empty($sub['removed'])   : !empty($sub->removed);
            if ($isCaptive || $isRemoved) continue;
            $cardID = is_array($sub) ? ($sub['CardID'] ?? '') : ($sub->CardID ?? '');
            if ($cardID === '' || $cardID === '-') continue;
            if (!SWUUpgradeMatchesFilter($cardID, $filter)) continue;
            $result[] = $hostMz . '.u' . $key;
        }
    };
    foreach (['myGroundArena', 'mySpaceArena', 'theirGroundArena', 'theirSpaceArena'] as $zone) {
        foreach (ZoneSearch($zone, ['Unit', 'Leader Unit', 'Token Unit']) as $mzID) $scan($mzID);
    }
    // Bases carry Fortify upgrades; without this they are invisible to every "defeat an upgrade" card.
    foreach (['myBase-0', 'theirBase-0'] as $baseMz) $scan($baseMz);
    return $result;
}

// Predicate over a candidate upgrade's CardID. $filter is a comma-separated list of
// AND-ed clauses "field op value"; fields unique/leader/cost, ops = != < <= > >=.
// Empty filter => always true. Used by SWUGetUnitsWithUpgrades + the defeat-upgrade
// host resolver (future Piloting cards LOF_155 unique=1, JTL_175 leader!=1, …).
function SWUUpgradeMatchesFilter(string $cardID, string $filter): bool {
    if ($filter === '') return true;
    foreach (explode(',', $filter) as $clause) {
        $clause = trim($clause);
        if ($clause === '') continue;
        if (!preg_match('/^(\w+)\s*(<=|>=|!=|=|<|>)\s*(.+)$/', $clause, $m)) continue;
        $field = $m[1];
        $op    = $m[2];
        $target = intval(trim($m[3]));
        switch ($field) {
            case 'unique': $actual = CardUnique($cardID) ? 1 : 0; break;
            case 'leader': $actual = (strpos(CardType($cardID) ?? '', 'Leader') !== false) ? 1 : 0; break;
            case 'cost':   $actual = intval(CardCost($cardID)); break;
            default: continue 2; // unknown field → ignore the clause
        }
        $ok = match ($op) {
            '='  => $actual === $target,
            '!=' => $actual !== $target,
            '<'  => $actual <  $target,
            '<=' => $actual <= $target,
            '>'  => $actual >  $target,
            '>=' => $actual >= $target,
            default => true,
        };
        if (!$ok) return false;
    }
    return true;
}

// Generic "defeat an upgrade" entry point shared by SOR_162/SHD_166 (may, single),
// SOR_251/SHD_262 (mandatory, single), SOR_170 (any number, min 0). Stages the chosen
// host's matching upgrades into TempZone and lets the player pick which to defeat.
//   $may    — host selection is pick-or-pass (MZMAYCHOOSE) vs mandatory.
//   $max    — max upgrades to defeat (1 = single pick; >1 = MZMULTICHOOSE).
//   $filter — SWUUpgradeMatchesFilter predicate string (default '' = any upgrade).
//   $min    — min upgrades to defeat (0 = optional / soft-pass).
// Leaves $playerID set so MZCountChoices resolves the relative arena names.
// $thenHandler — optional CUSTOM handler name fired AFTER this defeat fully resolves (a successful
// pick, not a decline). Used to chain "defeat up to N upgrades, possibly on DIFFERENT units" as N
// sequential "may defeat 1" flows (SOR_155): each flow re-reads the board, so the picks can span units.
function SWUQueueDefeatUpgrade(int $player, string $tooltip, bool $may = false,
                              int $max = 1, string $filter = '', int $min = 1, string $thenHandler = '',
                              int $onlyHostUID = 0): void {
    global $playerID;
    $playerID = intval($player);
    // SINGLE-pick ($max <= 1) offers the UPGRADES themselves as subcard mzIDs — one decision, the
    // candidates highlighted in place on their hosts. The old flow asked for a HOST unit first and only
    // then showed that host's upgrades in a TempZone popup, so the player had to commit to a unit before
    // they could see what was on it (and two upgrades on one unit were indistinguishable in the popup).
    // MULTI-pick ($max > 1) still uses the host-first flow: its MZMULTICHOOSE picks several upgrades on
    // ONE host, which the host step scopes. Converting that is separate work.
    if ($max <= 1) {
        SWUQueueDefeatUpgradeDirect($player, $tooltip, $may, $filter, $min, $thenHandler, $onlyHostUID);
        return;
    }
    $targets = SWUGetUnitsWithUpgrades($filter);
    // Scope to a single host (e.g. "defeat an upgrade on IT" — JTL_133 Pryde on the indirect-damaged unit).
    if ($onlyHostUID > 0) {
        $targets = array_values(array_filter($targets, function($mz) use ($onlyHostUID) {
            $o = GetZoneObject($mz);
            return $o !== null && intval($o->UniqueID ?? 0) === $onlyHostUID;
        }));
    }
    if (empty($targets)) {
        // No legal host → fizzle. Still honour the continuation so a chain doesn't dead-end early
        // (e.g. all upgrades already defeated by an earlier link).
        if ($thenHandler !== '') {
            global $customDQHandlers;
            DecisionQueueController::StoreVariable("DefeatUpgThen", "");
            if (isset($customDQHandlers[$thenHandler])) $customDQHandlers[$thenHandler]($player, [], '');
        }
        return;
    }
    DecisionQueueController::StoreVariable("DefeatUpgParams", $min . '|' . $max . '|' . $filter);
    DecisionQueueController::StoreVariable("DefeatUpgThen", $thenHandler);
    if ($may) {
        DecisionQueueController::AddDecision($player, "MZMAYCHOOSE", implode("&", $targets), 1, tooltip: $tooltip);
    } else if (count($targets) === 1) {
        DecisionQueueController::AddDecision($player, "PASSPARAMETER", $targets[0], 1);
    } else {
        DecisionQueueController::AddDecision($player, "MZCHOOSE", implode("&", $targets), 1, tooltip: $tooltip);
    }
    DecisionQueueController::AddDecision($player, "CUSTOM", "DEFEAT_UPGRADE", 1);
}

// "Defeat ONE upgrade" as a single board-addressed decision: every matching upgrade is offered as a
// subcard mzID and highlighted on its host. DEFEAT_UPGRADE recognises a subcard answer and defeats it
// directly, so there is no host step and no TempZone staging.
// $min == 0 (or $may) makes it declinable; a mandatory offer with exactly one legal upgrade
// auto-resolves as usual, which is itself the proof the filter narrowed correctly.
function SWUQueueDefeatUpgradeDirect(int $player, string $tooltip, bool $may, string $filter,
                                     int $min, string $thenHandler, int $onlyHostUID): void {
    global $playerID;
    $playerID = intval($player);
    $targets = SWUGetUpgradeSubcardMzIDs($filter, $onlyHostUID);
    if (empty($targets)) {
        // No legal upgrade → fizzle. Still honour the continuation so a chain doesn't dead-end early
        // (e.g. every upgrade already defeated by an earlier link).
        if ($thenHandler !== '') {
            global $customDQHandlers;
            DecisionQueueController::StoreVariable("DefeatUpgThen", "");
            if (isset($customDQHandlers[$thenHandler])) $customDQHandlers[$thenHandler]($player, [], '');
        }
        return;
    }
    DecisionQueueController::StoreVariable("DefeatUpgParams", $min . '|1|' . $filter);
    DecisionQueueController::StoreVariable("DefeatUpgThen", $thenHandler);
    $declinable = $may || $min === 0;
    if (!$declinable && count($targets) === 1) {
        // MANDATORY with a single legal upgrade → resolve it with no prompt, exactly as the host-first
        // flow did (PASSPARAMETER for a lone host, then its own single-match auto-defeat). Emitting a
        // one-candidate MZCHOOSE instead would leave a decision pending that nothing ever answers, and
        // the upgrade would silently survive.
        DecisionQueueController::AddDecision($player, "PASSPARAMETER", $targets[0], 1);
    } else {
        DecisionQueueController::AddDecision($player, $declinable ? "MZMAYCHOOSE" : "MZCHOOSE",
            implode("&", $targets), 1, tooltip: $tooltip);
    }
    DecisionQueueController::AddDecision($player, "CUSTOM", "DEFEAT_UPGRADE", 1);
    // Leave $playerID set: MZCountChoices validates the relative-frame specs next, under it.
}

// Returns a non-leader unit to its owner's hand (bounce mechanic).
// Defeats all upgrades on the unit first per CR 9.3:
//   tokens are set aside (no discard entry); non-tokens go to owner's discard.
// The unit itself is removed from the arena; a fresh copy (no damage/counters)
// is added to the owner's hand.
// Remove a TOKEN unit from play by a NON-defeat route (bounce target, capture target). JUDGE RULING
// 2026-08-13 (CR 5.8/§369): the token is set aside — NOT defeated (no When-Defeated observers, no
// defeat flags) — but it HAS left play, so leave-play reactions fire as non-defeat and its non-token
// upgrades are defeated per CR 9.3 (host left play), with the friendly-upgrade-defeated observers.
function _SWUCeaseTokenUnit(int $player, string $mzID): bool {
    global $playerID;
    $saved = $playerID;
    $playerID = intval($player);
    $obj = &GetZoneObject($mzID);
    if ($obj === null || ($obj->removed ?? false)) { $playerID = $saved; return false; }
    $cardID     = $obj->CardID;
    $owner      = intval($obj->Owner ?? $player);
    $controller = intval($obj->Controller ?? $owner);
    SWURescueCaptivesOf($obj);
    if (!empty($obj->Subcards) && is_array($obj->Subcards)) {
        foreach ($obj->Subcards as $sub) {
            $isCaptive = is_array($sub) ? !empty($sub['IsCaptive']) : !empty($sub->IsCaptive);
            $isRemoved = is_array($sub) ? !empty($sub['removed'])   : !empty($sub->removed);
            if ($isCaptive || $isRemoved) continue;
            $subCardID = is_array($sub) ? ($sub['CardID'] ?? '') : ($sub->CardID ?? '');
            $subOwner  = is_array($sub) ? intval($sub['Owner'] ?? $owner) : intval($sub->Owner ?? $owner);
            if ($subCardID === '' || strpos(strtolower(CardType($subCardID) ?? ''), 'token') !== false) continue;
            SWUAddToDiscard($subOwner, $subCardID, 'PLAY');
            $subCtrl = is_array($sub) ? intval($sub['Controller'] ?? $subOwner) : intval($sub->Controller ?? $subOwner);
            _SWUOnUpgradeDefeated($subCtrl > 0 ? $subCtrl : $controller, $subCardID, $obj, $subOwner);
        }
    }
    $obj->removed = true;
    SWUCollectLeavePlayReactions([['player' => $controller, 'cardID' => $cardID]], false); // NOT a defeat
    FlushTriggerBag($controller);
    DecisionQueueController::CleanupRemovedCards();
    $playerID = $saved;
    return true;
}

function SWUBounceUnit(int $player, string $mzID): bool {
    global $playerID;
    $savedPID = $playerID;
    $playerID = intval($player);

    $obj = &GetZoneObject($mzID);
    if ($obj === null || ($obj->removed ?? false)) {
        $playerID = $savedPID;
        return false;
    }
    // "Can't be returned to hand by enemy card abilities" (JTL_103 / TWI_220 / LOF_073). Bounce is
    // always ability-driven; only block when an opponent is doing it.
    if (intval($player) !== intval($obj->Controller ?? $player) && SWUAvoidsBounce($obj)) {
        $playerID = $savedPID;
        return false;
    }
    // A deployed LEADER UNIT (the leader itself IS the arena unit, own CardID is a leader) can't be
    // returned to hand. A vehicle merely CARRYING a leader-pilot upgrade is NOT a leader unit for this
    // purpose — it bounces normally, and its leader pilot is returned to the leader zone below. (The
    // old `IsLeaderUnit` guard conflated the two and blocked bouncing any leader-piloted vehicle.)
    if (strpos(CardType($obj->CardID ?? '') ?? '', 'Leader') !== false) {
        $playerID = $savedPID;
        return false;
    }

    // TWI_116 Clone — a bounced Clone copy returns to hand as the REAL card (TWI_116); the printed copy
    // only exists while in play.
    $cardID = !empty($obj->IsClone) ? 'TWI_116' : $obj->CardID;
    $owner  = intval($obj->Owner);

    // Return any leader-pilot subcards to the leader zone (exhausted) FIRST — a leader pilot can't go to
    // hand or discard; losing its host defeats it as a STATE-BASED consequence (CR), not a direct
    // enemy-ability defeat, so the leader's "can't be defeated/returned by enemy abilities" immunity does
    // NOT apply here. Must run before the upgrade-discard loop so a leader pilot is never discarded.
    // Unit slides back to its OWNER's hand — which is the OPPONENT's hand when you control a unit they
    // own, so the animation is queued from the owner's perspective, not the actor's. Queued before the
    // unit is removed so the source still resolves.
    SWUQueueZoneMoveAnim($mzID, 'myHand-0', intval($owner), 420, intval($obj->UniqueID ?? 0) ?: null);

    SWUReturnLeaderPilotSubcards($obj, $owner);
    // A pilot UPGRADE with a "would be defeated → may move to ground" replacement (JTL_094 Luke) is
    // still "would be defeated" when its host is RETURNED TO HAND (the upgrade doesn't bounce with the
    // host; CR 9.3 defeats it). Snapshot it so the controller is offered the move at action end, exactly
    // as on a host DEFEAT — the discard loop below then skips it (SWU_SELF_HANDLED_DEFEAT_SUBCARDS).
    _SWUDeferPilotDefeatReplacements($obj);

    // Defeat all attached upgrades (CR 9.3)
    if (!empty($obj->Subcards) && is_array($obj->Subcards)) {
        foreach ($obj->Subcards as $sub) {
            $isCaptive = is_array($sub) ? !empty($sub['IsCaptive']) : !empty($sub->IsCaptive);
            $isRemoved = is_array($sub) ? !empty($sub['removed'])   : !empty($sub->removed);
            if ($isCaptive || $isRemoved) continue;
            $subCardID  = is_array($sub) ? ($sub['CardID'] ?? '') : ($sub->CardID ?? '');
            $subOwner   = is_array($sub) ? intval($sub['Owner'] ?? $owner) : intval($sub->Owner ?? $owner);
            if ($subCardID === '') continue;
            if (in_array($subCardID, SWU_SELF_HANDLED_DEFEAT_SUBCARDS, true)) continue; // own defeat disposition (deferred above)
            if (strpos(strtolower(CardType($subCardID) ?? ''), 'token') === false) {
                SWUAddToDiscard($subOwner, $subCardID, 'PLAY');
                // CR 9.3: a host returned to hand DEFEATS its attached upgrades — fire the "a friendly upgrade
                // was defeated" observers (ASH_039 flag / ASH_055 return / ASH_161 Zeb deal-1), which the
                // bounce path previously skipped (only the defeat/host-leaves-via-defeat paths fired them).
                $subCtrlB = is_array($sub) ? intval($sub['Controller'] ?? $subOwner) : intval($sub->Controller ?? $subOwner);
                _SWUOnUpgradeDefeated($subCtrlB > 0 ? $subCtrlB : intval($obj->Controller ?? $owner), $subCardID, $obj, $subOwner);
            }
        }
    }

    $controller = intval($obj->Controller ?? $owner);
    $isToken    = strpos(strtolower(CardType($obj->CardID) ?? ''), 'token') !== false;
    // CR 8.34.4: rescue any captives guarded by this unit before it leaves play (bounce).
    SWURescueCaptivesOf($obj);

    if ($isToken) {
        // JUDGE RULING (2026-08-13, confirmed against CR 5.8/§369): a bounced token is NOT defeated —
        // it is removed from the game (set aside), fires NO When-Defeated observers and NO defeat
        // flags, but still counts as having been returned to hand / left play for the abilities that
        // care about THAT (leave-play reactions fire as non-defeat, same as a real unit's bounce).
        $obj = &GetZoneObject($mzID);
        if ($obj !== null && empty($obj->removed)) $obj->removed = true;
        SWUCollectLeavePlayReactions([['player' => $controller, 'cardID' => $cardID]], false); // NOT a defeat
    } else {
        $obj->removed = true;
        AddHand($owner, CardID:$cardID);
        // "Leaves play" reactions (not a defeat): Boba Fett's leader trigger + the phase flag.
        SWUCollectLeavePlayReactions([['player' => $controller, 'cardID' => $cardID]], false);
    }
    FlushTriggerBag($controller);

    DecisionQueueController::CleanupRemovedCards();
    $playerID = $savedPID;
    return true;
}

// Move a non-leader unit from the arena to the BOTTOM of its OWNER's deck (SOR_187 "put the other on
// the bottom of its owner's deck"). Mirrors SWUBounceUnit (defeat non-token upgrades, rescue captives,
// fire leave-play reactions) but the body goes to deck-bottom instead of hand. Token units are set
// aside (never enter a deck), same as bounce.
function SWUUnitToBottomOfDeck(int $player, string $mzID, bool $toTop = false): bool {
    global $playerID;
    $savedPID = $playerID;
    $playerID = intval($player);

    $obj = &GetZoneObject($mzID);
    if ($obj === null || ($obj->removed ?? false) || IsLeaderUnit($obj)) {
        $playerID = $savedPID;
        return false;
    }
    $cardID = $obj->CardID;
    $owner  = intval($obj->Owner);

    // Defeat all attached non-token upgrades (CR 9.3)
    if (!empty($obj->Subcards) && is_array($obj->Subcards)) {
        foreach ($obj->Subcards as $sub) {
            $isCaptive = is_array($sub) ? !empty($sub['IsCaptive']) : !empty($sub->IsCaptive);
            $isRemoved = is_array($sub) ? !empty($sub['removed'])   : !empty($sub->removed);
            if ($isCaptive || $isRemoved) continue;
            $subCardID = is_array($sub) ? ($sub['CardID'] ?? '') : ($sub->CardID ?? '');
            $subOwner  = is_array($sub) ? intval($sub['Owner'] ?? $owner) : intval($sub->Owner ?? $owner);
            if ($subCardID === '') continue;
            if (strpos(strtolower(CardType($subCardID) ?? ''), 'token') === false) {
                SWUAddToDiscard($subOwner, $subCardID, 'PLAY');
            }
        }
    }

    $controller = intval($obj->Controller ?? $owner);
    SWURescueCaptivesOf($obj);
    $obj->removed = true;
    if (strpos(strtolower(CardType($cardID) ?? ''), 'token') === false) {
        $deck = &GetDeck($owner);
        $d = new Deck($cardID, 'Deck', $owner);
        if ($toTop) array_unshift($deck, $d); else array_push($deck, $d); // LOF_200: owner chooses top/bottom
        foreach ($deck as $i => $c) { $c->mzIndex = $i; }
    }

    SWUCollectLeavePlayReactions([['player' => $controller, 'cardID' => $cardID]], false);
    FlushTriggerBag($controller);

    DecisionQueueController::CleanupRemovedCards();
    $playerID = $savedPID;
    return true;
}

// Play a card from the player's hand (mzID like "myHand-2").
// Pays cost in resources, moves the card to its arena (unit) or discard (event).
// This is the SWUSim equivalent of GA's ActivateCard.
// $altPayOffered: true only when reached from the PLAY_CARD funnel continuation, i.e. the player was
// already shown the Credit/Droid choice and $prepaid is their answer — so SWUPayCost must not
// auto-spend on top of it. Direct callers (the "play a card at -N" effects) leave it false.
function ActivateCard($player, $mzID, $ignoreCost, $discount = 0, $prepaid = 0, $owner = null, bool $altPayOffered = false) {
    // Snapshot the play-source's TurnEffect grant ONCE, at entry. The unit-placement branch below
    // consumes and nulls the global; the upgrade branch runs later in the same call and needs the same
    // value to thread onto ATTACH_UPGRADE (upgrade placement is async, so it cannot read the global at
    // attach time). Reading the global again down there is not safe — hence the snapshot.
    $gEntryPlayGrantTE = (string) ($GLOBALS['gPlayGrantTurnEffect'] ?? '');
    global $playerID;
    $savedPID = $playerID;
    $playerID = intval($player);
    // $owner defaults to the caster; a foreign-owned play (from an opponent's discard/resources —
    // SEC_205 Obi-Wan, LAW_066) passes the opponent so the unit enters Owner=opponent/Controller=caster
    // and an event lands in the OWNER's discard. Every normal caller omits it → byte-identical.
    $owner = ($owner === null) ? intval($player) : intval($owner);


    // Result channel (idiom shared with $gLastPlayResourcesPaid): the mzID of the newly
    // placed unit for a successful unit play, or '' if nothing was placed (failed/blocked
    // play, or a non-unit whose placement is deferred). Callers that need the played
    // card read $GLOBALS['gLastPlayedMzID'] immediately after ActivateCard returns.
    $GLOBALS['gLastPlayedMzID'] = '';

    $obj = GetZoneObject($mzID);
    if ($obj === null || (isset($obj->removed) && $obj->removed)) {
        $playerID = $savedPID;
        return;
    }

    $cardID        = $obj->CardID;
    // SEC_053 One in a Million etc.: "This card can't be played from your hand." Block ONLY the
    // hand-source play (myHand-N); the Plot/resource path (myResources-N) is unaffected.
    if (strpos($mzID, 'Hand') !== false && _SWUCantPlayFromHand($cardID)) {
        SetFlashMessage("That card can't be played from your hand.");
        $playerID = $savedPID;
        return;
    }
    // SOR_062 Regional Governor: an opponent's named card can't be played (no cost, no state change).
    if (SWUCardPlayBlocked(intval($player), $cardID)) {
        SetFlashMessage("That card can't be played (named by an opponent).");
        $playerID = $savedPID;
        return;
    }
    AddGameLogEntry('PLAY', 'P' . intval($player) . ' played ' . GameLogCardRef($cardID));
    if (function_exists('SWUTelemetryBumpCard')) { SWUTelemetryBumpCard($player, $cardID, 'played'); SWUTelemetryBumpTurn($player, 'cardsUsed'); }
    $rawType       = CardType($cardID);
    // Cost (base + aspect penalty + all play-cost modifiers) — single source of
    // truth shared with the UI affordability check. See $playCostModifiers.
    // $discount (e.g. SOR_093 "It costs 1 resource less") is subtracted, floored at 0.
    $cost          = max(0, SWUComputePlayCost($player, $obj) - intval($discount));
    // cards-played-this-phase counter (any type). Bumped AFTER the cost is computed, so a modifier that
    // reads "for each OTHER card you played this phase" (TS26_36 Tribunal) sees the cards that came
    // before this one — the same view the UI affordability check gets, since that runs before the play.
    // Bumping first made Tribunal count ITSELF and cost 2 less than it should. Everything downstream
    // (e.g. the Coordinate "exactly the 2nd card" check) still sees a count that includes this card.
    AddGlobalEffects(intval($player), 'SWU_CARDS_PLAYED');
    // Consume every one-shot "next X costs N less" charge this play triggered — table-driven, so the set
    // spent always matches the set _SWUPlayCostModifierDelta applied at cost time (SOR_056 Bendu / JTL_098
    // Snap / JTL_008 Wedge-as-unit / LOF_005 Morgan / SEC_110 / TWI_121 / TS26_35 / TS26_06 Rex / TWI_246 /
    // SEC_261 / LAW_058 / ASH_027 / SHD_006 / LAW_158 / ASH_237). Shared with the Smuggle commit.
    _SWUConsumeOneShotCharges($player, $obj);
    // JTL_232 Jump to Lightspeed: consume the one-shot "next copy of that unit is free" charge (keyed on
    // the exact CardID — a per-CardID free-override, not part of the shared one-shot table).
    if (GlobalEffectCount(intval($player), 'SWU_JTL232_FREE|' . $cardID) > 0) {
        RemoveGlobalEffect(intval($player), 'SWU_JTL232_FREE|' . $cardID);
    }
    // ASH_212 Peli Motto: "Ignore the aspect penalties of the first non-unit card you play each phase." The
    // used-flag means "this player has played a non-unit this phase" — set on ANY non-unit play, NOT only
    // while controlling Peli (mirrors the JTL_260 pattern below). That way a non-unit played BEFORE Peli
    // entered still counts, so a later non-unit is correctly not the phase's first and keeps its penalty.
    // The waiver itself (in the cost pipeline) additionally requires controlling Peli. Cleared at RegroupPhaseStart.
    // Upgrades are EXCLUDED here: they charge their cost later, in _SWUFinalizeUpgradeAttach (after a host is
    // chosen), which sets the flag AFTER its charge — otherwise the flag would be set before the attach-time
    // cost recompute and the waiver would be lost (the cost would recompute with the flag already used).
    if (stripos(CardType($cardID) ?? '', 'Unit') === false
            && stripos(CardType($cardID) ?? '', 'Upgrade') === false
            && GlobalEffectCount(intval($player), 'SWU_ASH212_USED') <= 0) {
        AddGlobalEffects(intval($player), 'SWU_ASH212_USED');
    }
    // JTL_260 Death Star Plans: "The first unit you play each round costs 2 less." The used-flag means
    // "this player has played a unit this round" — set on ANY unit play, NOT only while controlling a DSP
    // bearer. That way a unit played BEFORE the player gains DSP still counts, so a later unit correctly
    // is not the round's first and gets no discount. The discount itself (the peek in the cost pipeline)
    // additionally requires controlling a DSP bearer. Cleared at RegroupPhaseStart.
    if (strpos(CardType($cardID) ?? '', 'Unit') !== false
            && GlobalEffectCount(intval($player), 'SWU_JTL260_USED') <= 0) {
        AddGlobalEffects(intval($player), 'SWU_JTL260_USED');
    }
    // SHD_198 Clone Trooper: mark the once-per-round "first Clone unit ignores aspect penalty" charge used
    // once this Clone unit's (already-waived) cost is locked in. Cleared at RegroupPhaseStart.
    if (strpos(CardType($cardID) ?? '', 'Unit') !== false && HasTrait($cardID, 'Clone')
            && GlobalEffectCount(intval($player), 'SWU_SHD198_USED') <= 0
            && _SWUControlsCardInPlay(intval($player), 'SHD_198')) {
        AddGlobalEffects(intval($player), 'SWU_SHD198_USED');
    }
    // LAW_229 The Master Codebreaker: mark the once-per-round "first Gambit -1" discount used when the
    // player plays a Gambit card while controlling LAW_229. Cleared at RegroupPhaseStart.
    if (HasTrait($cardID, 'Gambit')
            && GlobalEffectCount(intval($player), 'SWU_LAW229_USED') <= 0
            && _SWUCountUnitsWithCardID(intval($player), 'LAW_229') > 0) {
        AddGlobalEffects(intval($player), 'SWU_LAW229_USED');
    }
    // (The LAW_058 / ASH_027 / SHD_006 / LAW_158 / ASH_237 / SEC_110 / TWI_121 / TS26_35 / TS26_06 Rex /
    // TWI_246 / SEC_261 one-shot consumes are now handled by _SWUConsumeOneShotCharges above.)
    // SEC_001 Chancellor Palpatine: consume the "next Plot play −3" charge when a Plot card is actually
    // played from resources (a Resources object). Mirrors the SWUComputePlayCost gate above.
    global $Plot_Cards;
    if (isset($Plot_Cards[$cardID]) && is_object($obj) && ($obj instanceof Resources)
            && GlobalEffectCount(intval($player), 'SWU_SEC001_PLOT_DISCOUNT') > 0) {
        RemoveGlobalEffect(intval($player), 'SWU_SEC001_PLOT_DISCOUNT');
    }
    $cardTypeLower = strtolower($rawType ?? '');
    $isEvent       = strpos($cardTypeLower, 'unit') === false && strpos($cardTypeLower, 'upgrade') === false;

    global $hasAlternateCostCards;
    $hasAltCost = $isEvent
                  && isset($hasAlternateCostCards[$cardID])
                  && SWUCheckAlternateCost($player, $cardID);

    // Upgrades check valid targets BEFORE paying cost (unlike units/events).
    // Alt-cost events defer payment to the event branch (YESNO choice).
    // The early resource exhaust is skipped for both; upgrades pay after target
    // confirmation, alt-cost events pay via the SOR_199 handler.
    if (!$ignoreCost && !$hasAltCost && strpos($cardTypeLower, 'upgrade') === false) {
        $ok = SWUPayCost($player, $cost, $prepaid, true, $altPayOffered);
        if (!$ok) {
            SetFlashMessage("Not enough ready resources (need $cost).");
            $playerID = $savedPID;
            return;
        }
    }

    // LOF_012 Rey: "played a non-unit Force card this phase" — a Force EVENT commits here (cost paid).
    // Force UPGRADES set the same flag in the upgrade branch once a valid host is confirmed.
    if ($isEvent && HasTrait($cardID, 'Force')) {
        AddGlobalEffects($player, 'SWU_PLAYED_NONUNIT_FORCE');
    }

    // Task 3.1 / Task 6.1: stamp how many real resources were paid for this play (unit + event paths).
    // Upgrades defer payment to ATTACH_UPGRADE (post-host selection), so $gLastPlayResourcesPaid is
    // written there. Alt-cost events defer to SOR_199. This block covers the early paths only.
    // SWUPayCost is the single owner of $gLastPlayResourcesPaid for normal (non-ignoreCost, non-altCost,
    // non-upgrade) plays. ignoreCost explicitly records 0; altCost reads what SOR_199 sets.
    if ($ignoreCost) {
        // Normally 0; a pre-charged foreign play (SWUPlayFromOpponentDiscard OTPP/OTPN) passes the
        // amount it already charged as $prepaid so TWI_210 sees the real resources paid. Default 0.
        $resourcesPaid = intval($prepaid);
        $GLOBALS['gLastPlayResourcesPaid'] = intval($prepaid);
    } elseif (!$hasAltCost && strpos($cardTypeLower, 'upgrade') === false) {
        // SWUPayCost already wrote $gLastPlayResourcesPaid; just read it back.
        $resourcesPaid = intval($GLOBALS['gLastPlayResourcesPaid']);
    } elseif ($hasAltCost) {
        // Alt-cost events: old computation; SOR_199 will overwrite $gLastPlayResourcesPaid.
        $resourcesPaid = max(0, $cost - intval($prepaid));
        $GLOBALS['gLastPlayResourcesPaid'] = $resourcesPaid;
    } else {
        // Upgrades: payment deferred to ATTACH_UPGRADE. Do NOT write $gLastPlayResourcesPaid here;
        // ATTACH_UPGRADE calls SWUPayCost which will set it to the exact host-specific cost.
        $resourcesPaid = 0; // unused by the upgrade branch; ATTACH_UPGRADE owns it.
    }

    if (strpos($cardTypeLower, 'unit') !== false) {
        // Remove from hand first.
        $obj->Remove();

        // TWI_116 Clone — "enter play as a copy." $gCloneCopyCardID (set at play time in CLONE_COPY_CHOICE)
        // holds the chosen card's printed CardID; the unit then enters play AS that card (arena, stats,
        // traits, abilities, keywords all resolve from the copied CardID) with an IsClone flag. $cardID
        // stays TWI_116 for the cost/played-card bookkeeping above; only the ENTERING unit becomes the copy.
        global $gCloneCopyCardID;
        $cloneCopyID = null;
        if ($cardID === 'TWI_116' && !empty($gCloneCopyCardID)) {
            $cloneCopyID = $gCloneCopyCardID;
        }
        $gCloneCopyCardID = null;   // consume once
        $effectiveCardID = $cloneCopyID ?? $cardID;

        // Add directly to the arena with correct Owner/Controller so that
        // BuildIndex() runs with the right player — otherwise GetMzID() returns
        // "theirGroundArena-N" for the unit we just played.
        $targetArena = CardTargetArena($effectiveCardID);
        $uid = NextUniqueID();
        // CR 8.22.f: units enter play exhausted — unless the card says otherwise
        // (SOR_193 Millennium Falcon: "This unit enters play ready."), or the play source forces it
        // (SOR_129 Admiral Ozzel: "Play an Imperial unit … It enters play ready." sets $gForceEnterReady).
        global $gForceEnterReady;
        // The card's own enters-ready replacement (incl. the conditional variants) — shared with every
        // other arena-entry path via _SWUCardEntersReadyFor. NOTE it is keyed on $cardID for the
        // conditionals but on $effectiveCardID for the plain text-match, matching a TWI_116 Clone copy.
        $entersReady = SWUUnitEntersReady($effectiveCardID) || _SWUCardEntersReadyFor(intval($player), $cardID);
        if (in_array($cardID, ['SEC_170', 'LAW_210', 'LAW_223', 'ASH_224'], true)) {
            $entersReady = _SWUCardEntersReadyFor(intval($player), $cardID);   // conditional → exact, not best-case
        }
        // ASH_248 Neel — "The next unit you play this phase with 1 or less power enters play ready."
        // Armed flag consumed by the next ≤1-power unit the controller plays.
        // ASH_248 Neel — the flag he arms is consumed by the next ≤1-power unit you play (never by Neel
        // himself; SWUUnitEntersReady now only self-readies "this unit"-phrased cards).
        if (GlobalEffectCount(intval($player), 'SWU_ASH248_READY') > 0 && intval(CardPower($cardID)) <= 1) {
            $entersReady = true;
            RemoveGlobalEffect(intval($player), 'SWU_ASH248_READY');
        }
        $entryStatus = (!empty($gForceEnterReady) || $entersReady) ? 1 : 0;
        if ($targetArena === 'SpaceArena') {
            $newCard = AddSpaceArena($player, CardID:$effectiveCardID, Status:$entryStatus,
                Owner:$owner, Damage:0, Controller:$player, UniqueID:$uid);
        } else {
            $newCard = AddGroundArena($player, CardID:$effectiveCardID, Status:$entryStatus,
                Owner:$owner, Damage:0, Controller:$player, UniqueID:$uid);
        }
        // TWI_116 Clone — durably mark the entering unit as a Clone copy (drives its granted Clone trait,
        // its non-unique treatment, and the CardID→TWI_116 revert when it leaves play).
        if ($cloneCopyID !== null) $newCard->IsClone = true;

        $newCardMzID = $newCard->GetMzID();
        $GLOBALS['gLastPlayedMzID'] = $newCardMzID; // result channel — see top of ActivateCard

        // Hand slides into the arena. $mzID is ActivateCard's own SOURCE parameter (the card's hand
        // slot), never reassigned; $newCardMzID is where it landed. The source card is already flagged
        // removed by now, which is fine — the client clones from the PRE-render DOM, so the old hand
        // slot still resolves.
        SWUQueueZoneMoveAnim($mzID, $newCardMzID, intval($player));

        // Task 3.1: durable paid-resources stamp on the arena object so a deferred WhenPlayed
        // (resolved in a later request via the EffectStack) can still read it.
        // Cleared at RegroupPhaseStart alongside other per-phase TurnEffects.
        AddTurnEffect($newCardMzID, "SWU_PAID_{$resourcesPaid}");

        // A play SOURCE may grant a TurnEffect token to the entering unit (consume-once, like
        // $gForceEnterReady): SOR_003 Chewbacca tags it 'SOR_003' (Sentinel this phase), SOR_219
        // Sneak Attack tags it 'SWU_SNEAK_DEFEAT' (defeated at the next regroup).
        global $gPlayGrantTurnEffect;
        if (!empty($gPlayGrantTurnEffect)) {
            AddTurnEffect($newCardMzID, $gPlayGrantTurnEffect);
            $gPlayGrantTurnEffect = null;
        }
        // A play SOURCE may also give Shield token(s) to the entering unit (consume-once):
        // LOF_076 Soresu Stance plays a Force unit and gives it a Shield.
        global $gPlayGrantShield;
        if (!empty($gPlayGrantShield)) {
            for ($gs = 0; $gs < intval($gPlayGrantShield); $gs++) DoGiveShieldToken($player, $newCardMzID);
            $gPlayGrantShield = null;
        }
        // …or Experience token(s): LOF_125 The Burden of Masters plays a unit and gives it 2 Experience.
        global $gPlayGrantExp;
        if (!empty($gPlayGrantExp)) {
            for ($ge = 0; $ge < intval($gPlayGrantExp); $ge++) DoGiveExperienceToken($player, $newCardMzID);
            $gPlayGrantExp = null;
        }
        // …or the LOF_220 "prevent 2 of next damage" one-shot marker (applied BEFORE entry triggers so a
        // granted-Ambush attack's counter-damage is the instance that gets prevented).
        global $gPlayGrantPrevent2;
        if (!empty($gPlayGrantPrevent2)) {
            AddTurnEffect($newCardMzID, 'PREVENT_DMG_2');
            $gPlayGrantPrevent2 = null;
        }
        // LOF_180 Deceptive Shade — "the next unit you play this phase gains Ambush." Lingering flag,
        // consumed at this (the next) unit's entry — before entry triggers collect, so Ambush can fire.
        if (GlobalEffectCount(intval($player), 'SWU_LOF180_NEXT_AMBUSH') > 0) {
            AddTurnEffect($newCardMzID, 'AMBUSH^LOF_180');
            RemoveGlobalEffect(intval($player), 'SWU_LOF180_NEXT_AMBUSH');
        }
        // LOF_010 Third Sister (deployed) — "the next unit you play this phase gains Hidden."
        if (GlobalEffectCount(intval($player), 'SWU_LOF010_NEXT_HIDDEN') > 0) {
            AddTurnEffect($newCardMzID, 'HIDDEN^LOF_010');
            RemoveGlobalEffect(intval($player), 'SWU_LOF010_NEXT_HIDDEN');
        }
        // LAW_015 Jabba (deployed) — the Underworld unit played by Jabba's action gains Ambush this phase
        // IF a Credit was defeated paying its cost (CREDIT_PAY armed SWU_JABBA015_AMBUSH). Consume both
        // flags here, before entry triggers collect, so the granted Ambush can fire its entry attack.
        if (GlobalEffectCount(intval($player), 'SWU_JABBA015_PENDING') > 0) {
            RemoveGlobalEffect(intval($player), 'SWU_JABBA015_PENDING');
            if (GlobalEffectCount(intval($player), 'SWU_JABBA015_AMBUSH') > 0) {
                AddTurnEffect($newCardMzID, 'AMBUSH^LAW_015');
                RemoveGlobalEffect(intval($player), 'SWU_JABBA015_AMBUSH');
            }
        }
        // (LOF_005 Morgan's "next unit you play" charge is spent by _SWUConsumeOneShotCharges at the top of
        // ActivateCard — its consumeApplies gate spends it on any unit play, discount or not.)

        AddGlobalEffects($player, 'SWU_PLAYED_UNIT_' . $uid);
        // SHD_161 Stolen Landspeeder / SHD_204 Millennium Falcon — "if you played this unit from your
        // hand": per-UID flag set ONLY for hand-sourced plays (discard/deck/smuggle-resource plays
        // don't set it). Cleared with the other per-phase flags at RegroupPhaseStart.
        if (strpos($mzID, 'Hand') !== false) AddGlobalEffects($player, 'SWU_PLAYED_FROM_HAND_' . $uid);
        // JTL_032 Director Krennic + LOF_108 Malakili: consume the "first When-Defeated unit / first
        // Creature" per-round/phase discount slots on ANY qualifying play (shared with the smuggled-unit
        // commit in SWUSmuggleResource).
        _SWUMarkUnitPlayUsedFlags($player, $cardID);
        if (strpos(CardAspect($cardID) ?? '', 'Villainy') !== false) {
            AddGlobalEffects($player, 'SWU_PLAYED_VILLAINY');
        }
        if (HasTrait($cardID, 'First Order')) {
            AddGlobalEffects($player, 'SWU_PLAYED_FO');  // JTL_010 Captain Phasma "played a First Order card"
        }
        if (HasTrait($cardID, 'Force')) {
            AddGlobalEffects($player, 'SWU_PLAYED_FORCE_CARD');  // LOF_243 Caretaker Matron "played a Force card"
        }
        if (HasTrait($cardID, 'Bounty Hunter')) {
            AddGlobalEffects($player, 'SWU_PLAYED_BOUNTYHUNTER');  // JTL_186 Mist Hunter
        }
        if (HasTrait($cardID, 'Pilot')) {
            AddGlobalEffects($player, 'SWU_PLAYED_PILOT');         // JTL_186 Mist Hunter
        }

        // Apply pending entry TurnEffects keyed by UniqueID (e.g. AMBUSH granted by Energy Conversion Lab).
        global $gPendingEntryEffects;
        if (isset($gPendingEntryEffects[$uid])) {
            foreach ($gPendingEntryEffects[$uid] as $effect) {
                AddTurnEffect($newCardMzID, $effect);
            }
            unset($gPendingEntryEffects[$uid]);
        }

        // Collect all entry triggers: WhenPlayed, Shielded, Ambush.
        // FlushEntryTriggerBag populates EffectStack (2+ triggers) or auto-dispatches (1 trigger).
        // SWU_TRIGGER_RESUME (block 20) handles SWUAfterAction when all triggers are resolved.
        SWUApplyPassiveEntryGrants($player, $effectiveCardID, $newCardMzID);

        // A unit entering play can change the board's continuous shrinks: e.g. SHD_037
        // Snoke shrinks every enemy non-leader unit (defeating any reduced to 0 HP), and
        // a small unit entering under an enemy Snoke is itself immediately defeated.
        SWUCheckShrinkDefeats();

        // CR 16.d / Task 1.4: Exploit-defeated units' WhenDefeated triggers were parked while
        // $gExploitDeferTriggers was true.  Replay them into $gPendingTriggers NOW — before
        // FlushEntryTriggerBag runs — so they batch with the played card's WhenPlayed trigger.
        // We do this BEFORE the "defeated on entry" check so the deferred triggers always fire
        // even if the played unit was immediately defeated on entry (e.g. by a Snoke shrink).
        SWUFlushExploitDeferredTriggers($player);

        // If the unit was itself defeated on entry (entered under an enemy Snoke), don't
        // run entry triggers on a now-stale mzID — just finish the action.
        // Any Exploit-deferred triggers that were just replayed into $gPendingTriggers still
        // need to be flushed here; FlushEntryTriggerBag handles that and takes over cleanup
        // when it returns > 0 (SWU_TRIGGER_RESUME queued).
        $enteredStill = false;
        foreach (GetZone($targetArena === 'SpaceArena' ? 'mySpaceArena' : 'myGroundArena') as $u) {
            if (empty($u->removed) && intval($u->UniqueID ?? 0) === $uid) { $enteredStill = true; break; }
        }
        if (!$enteredStill) {
            $deferredTriggered = FlushEntryTriggerBag($player);
            DecisionQueueController::CleanupRemovedCards();
            if ($deferredTriggered === 0) {
                SWUAfterAction($player);
            }
            // deferredTriggered >= 1: SWU_TRIGGER_RESUME (already queued) handles cleanup.
            $playerID = $savedPID;
            return;
        }

        $triggered = CollectEntryTriggers($player, $effectiveCardID, $newCardMzID, $targetArena);

        if ($triggered === 0) {
            // No entry triggers — end action immediately.
            DecisionQueueController::CleanupRemovedCards();
            SWUAfterAction($player);
        }
        // triggered >= 1: SWU_TRIGGER_RESUME (already queued at block 20) handles cleanup.
    } elseif (strpos($cardTypeLower, 'upgrade') !== false) {
        // Upgrades: validate affordable targets (host-specific cost), then queue host selection
        // and ATTACH_UPGRADE. Cost is paid AFTER the host is chosen (inside ATTACH_UPGRADE) so
        // that host-dependent discounts (SOR_061) are exact with no claw-back.
        // The upgrade stays in hand until ATTACH_UPGRADE succeeds, giving natural rollback on
        // payment failure (the card remains playable on a future action).
        // LOF_018 Anakin — "ignoring aspect penalties": the aspect surcharge ($discount) must be waived in
        // the AFFORDABILITY check too, else a host that's only affordable post-waiver is filtered out and the
        // play silently fizzles. The discount equals the aspect penalty, so ignore it here; the actual
        // (async, host-specific) payment is discounted via the ATTACH_UPGRADE param → _SWUFinalizeUpgradeAttach.
        $twi040Saved = $GLOBALS['gTwi040IgnoreAspect'] ?? false;
        if ($discount > 0) $GLOBALS['gTwi040IgnoreAspect'] = true;
        $validTargets = SWUGetUpgradeValidTargets($player, $cardID, $ignoreCost ? null : $obj, $discount);
        $GLOBALS['gTwi040IgnoreAspect'] = $twi040Saved;
        if (empty($validTargets)) {
            SetFlashMessage("No valid targets for upgrade.");
            $playerID = $savedPID;
            return;
        }
        // LOF_012 Rey: a Force upgrade with a valid host is a "non-unit Force card" played this phase.
        if (HasTrait($cardID, 'Force')) {
            AddGlobalEffects($player, 'SWU_PLAYED_NONUNIT_FORCE');
        }
        // Do NOT pay here and do NOT $obj->Remove() yet — ATTACH_UPGRADE handles both.
        // Pass the upgrade's current hand mzID so ATTACH_UPGRADE can remove it on success.
        $upgradeMz = $mzID;
        if (count($validTargets) === 1) {
            DecisionQueueController::AddDecision($player, "PASSPARAMETER", $validTargets[0], 0);
        } else {
            DecisionQueueController::AddDecision($player, "MZCHOOSE", implode('&', $validTargets), 0, tooltip:"Choose_upgrade_target");
        }
        $igc = $ignoreCost ? 1 : 0;
        // Thread $discount (5th field; 4th=isPilot, 0 for a normal upgrade) so the deferred upgrade payment
        // honors an aspect-penalty waiver (LOF_018 Anakin plays a Villainy upgrade "ignoring aspect penalties").
        // 7th field: $gPlayGrantTurnEffect — the marker the PLAYING effect wants stamped on what it played.
        // ⚠ It MUST ride the param. Upgrade placement is ASYNC (this queues ATTACH_UPGRADE and returns),
        // and callers null the global on the line right after ActivateCard, so by the time the attach runs
        // the global is already NULL. The unit branch below gets away with reading the global only because
        // its placement is synchronous. SHD_194 Triple Dark Raid lost its return-to-hand marker exactly here.
        DecisionQueueController::AddDecision($player, "CUSTOM",
            "ATTACH_UPGRADE|{$cardID}|{$upgradeMz}|{$igc}|0|" . intval($discount) . "||" . $gEntryPlayGrantTE, 0);
    } else {
        // Events: move to discard, resolve immediate effect, then cleanup.
        // Mark that this discard is the event's OWN play (From='HAND' but NOT a "discarded from hand"
        // event) so "when discarded from hand or deck" triggers (LAW_206) don't fire on normal play.
        $GLOBALS['gPlayingEventCardID'] = $cardID;
        $obj->Remove();
        // A foreign-owned event goes to the OWNER's discard as a PLAY (not the caster's HAND).
        SWUAddToDiscard($owner, $cardID, ($owner !== intval($player)) ? 'PLAY' : 'HAND');
        unset($GLOBALS['gPlayingEventCardID']);
        // SOR_153 Saw Gerrera (enemy in play): "As an additional cost for each opponent to play an
        // event, they must deal 2 damage to their base." Applied at play time (always payable).
        if (_SWUCountUnitsWithCardID(OtherPlayer(intval($player)), 'SOR_153') > 0) {
            SWUDealDamageToBase(2, intval($player));
        }
        // LOF_142 Adi Gallia (enemy in play): "When an opponent plays an event: deal 1 to that player's base."
        $adiCount = _SWUCountUnitsWithCardID(OtherPlayer(intval($player)), 'LOF_142');
        for ($ai = 0; $ai < $adiCount; $ai++) SWUDealDamageToBase(1, intval($player));
        // SOR_089 Relentless (enemy in play): "The first event played by each opponent each round loses
        // all abilities." If this is $player's first event this round AND an opponent controls Relentless,
        // skip the event's effect (it still goes to discard). The per-round flag clears at RegroupPhaseStart.
        $eventBlanked = false;
        if (GlobalEffectCount(intval($player), 'SWU_EVENT_PLAYED_ROUND') <= 0
            && _SWUCountUnitsWithCardID(OtherPlayer(intval($player)), 'SOR_089') > 0) {
            $eventBlanked = true;
            AddGameLogEntry('ABILITY', GameLogCardRef($cardID) . " loses all abilities (Relentless)");
        }
        AddGlobalEffects(intval($player), 'SWU_EVENT_PLAYED_ROUND');
        if ($hasAltCost && !$eventBlanked) {
            // Queue YESNO before the event's When-Played dispatch so the cost choice resolves first.
            DecisionQueueController::AddDecision($player, "YESNO", "-", 1, tooltip:"Use_alternate_cost?");
            DecisionQueueController::AddDecision($player, "CUSTOM", "SOR_199#0|{$cost}", 1);
        }
        // ── Event When-Played resolution (inlined from the former OnPlayEvent in CardEffects.php). ──
        // Preamble — fires on EVERY event play, even a Relentless-blanked (SOR_089) or Galen-suppressed
        // (SEC_046) one: playing a blanked event is still "playing an event"; only the event's OWN ability
        // is lost, not the fact that you played it.
        AddGlobalEffects(intval($player), 'SWU_PLAYED_EVENT'); // TWI_014 Asajj "if you played an event this phase" (cleared at RGS)
        // TS26_08 Ahsoka Tano (front, undeployed) — "When you play an event: you may exhaust this leader →
        // look at the top card of your deck (play/discard/leave)." Reacts to the act of playing the event.
        if (_SWULeaderReadyUndeployed(intval($player), 'TS26_08')) {
            DecisionQueueController::AddDecision(intval($player), "YESNO", "-", 1, tooltip: "Exhaust_Ahsoka_to_look_at_the_top_card?");
            DecisionQueueController::AddDecision(intval($player), "CUSTOM", "TS26_08#0", 1);
        }
        // SNAPSHOT the event-play observer set BEFORE the event's own effects run (the Bossk verdict,
        // candidate #1 fix 2026-08-14): "when you play an event" reactions belong to units in play at
        // the moment the event is PLAYED — a unit the event itself seats (Sneak Attack × Bossk) must
        // not observe its own arrival. The block-5 collector below re-scans the post-effect board, so
        // it filters against this UID snapshot.
        $evtObserverUIDs = [];
        foreach ([1, 2] as $sp) {
            foreach (GetUnitsInPlay($sp) as $u0) {
                if (empty($u0->removed) && intval($u0->UniqueID ?? 0) > 0) $evtObserverUIDs[] = intval($u0->UniqueID);
            }
        }
        // The event's OWN When-Played effect — suppressed when the event has lost all abilities (Relentless
        // blanking / SEC_046 Galen). Dispatched via $whenPlayedAbilities (per-card files under cards/<set>/),
        // the same array unit When-Played handlers use; an event has no board object so $mzID is ''.
        if (!$eventBlanked && !_SWUGalenSuppressesCard(intval($player), $cardID)) {
            global $whenPlayedAbilities;
            if (isset($whenPlayedAbilities["{$cardID}:0"])) $whenPlayedAbilities["{$cardID}:0"]($player, '');
        }
        // Task 5.1 — TWI_210 Cunning observer: fire after event effects (block 1) but before
        // FINISH_PLAY_CARD (block 10). resourcesPaid is already finalised at $gLastPlayResourcesPaid.
        // Skip when hasAltCost: SOR_199 may later change what was paid; documented as a known
        // limitation (the alt-cost branch resolves asynchronously via SOR_199 handler).
        if (!$hasAltCost) {
            DecisionQueueController::AddDecision($player, "CUSTOM",
                "TWI_210#0|{$player}|{$cardID}|{$resourcesPaid}|" . implode(',', $evtObserverUIDs), 5);
        }
        DecisionQueueController::AddDecision($player, "CUSTOM", "FINISH_PLAY_CARD", 10, dontSkipOnPass: 1);
        // Do NOT restore $playerID here — ExecuteStaticMethods calls MZCountChoices
        // immediately after this returns, and it needs $playerID = $player to resolve
        // relative zone names like "theirGroundArena" correctly.
        return;
    }

    $playerID = $savedPID;
}

// Task 3.1: reader helper — resources paid for the play that put $obj into play.
// Reads the SWU_PAID_n TurnEffect stamped by ActivateCard; returns 0 if absent.
// Only meaningful for units (events have no arena object; use $gLastPlayResourcesPaid instead).
function SWUUnitResourcesPaid($obj): int {
    if (!empty($obj->TurnEffects)) {
        foreach ($obj->TurnEffects as $te) {
            if (preg_match('/^SWU_PAID_(\d+)$/', $te, $m)) return intval($m[1]);
        }
    }
    return 0;
}

// ── Task 1.3: Play-from-hand orchestrator (Exploit pre-step) ────────────────

// Effective Exploit X for a card being PLAYED: printed registry + granted-this-play + EXPLOIT_n
// TurnEffects. Hand cards carry no TurnEffects, so the grant rides in $gPlayGrantedExploit
// (set by e.g. TWI_005). Returns 0 if the card has no Exploit at all.
function SWUEffectivePlayExploit($obj): int {
    global $gPlayGrantedExploit;
    if ($obj === null || !isset($obj->CardID)) return 0;
    $base = GetKeyword_Exploit_Value($obj);   // additive; may return null when 0
    return intval($base) + intval($gPlayGrantedExploit ?? 0);
}

// Display flag for the hand "Exploit available" icon (schema Virtual: ExploitAvailable).
// 1 when a card in hand could be played with Exploit: it HAS Exploit (printed or granted
// on the card itself), OR it is a Separatist card while TWI_005 Count Dooku's "next
// Separatist card you play this phase gains Exploit" charge is active for the hand's owner
// (SWU_DOOKU_NEXT_SEPARATIST_EXPLOIT). Returns 1/0 for the Image counter (ShowZero hides 0).
function HandCardExploitAvailable($obj): int {
    if ($obj === null || !isset($obj->CardID)) return 0;
    if (HasKeyword_Exploit($obj)) return 1;
    $player = intval($obj->PlayerID ?? 0);
    if ($player > 0
            && HasTrait($obj->CardID, 'Separatist')
            && GlobalEffectCount($player, 'SWU_DOOKU_NEXT_SEPARATIST_EXPLOIT') > 0) {
        return 1;
    }
    return 0;
}

// Friendly units the player may defeat for Exploit (CR 16): ANY friendly unit — non-leader
// Units, Token Units (Battle Droids, etc.), AND a deployed Leader Unit. Single source of truth
// shared by SWUBeginPlayCard (offer + max) and EXPLOIT_RESOLVE (validate the answer), so a unit
// type can never be offered-but-not-defeatable or vice versa.
function SWUExploitFodder($player): array {
    global $playerID;
    $savedPID = $playerID;
    $playerID = intval($player);
    $fodder = array_merge(
        ZoneSearch("myGroundArena", AnyUnitFilter),
        ZoneSearch("mySpaceArena",  AnyUnitFilter)
    );
    $playerID = $savedPID;
    return $fodder;
}

// SEC_122 Vuutun Palaa: "Each friendly Droid unit may be exhausted to pay costs as if it were a resource."
// Returns mzIDs of the player's friendly units that (a) have trait Droid and (b) are READY (Status===1).
// Uses the same ready predicate as SWUUnitAction's exhaust cost-kind: intval($obj->Status) === 1.
// Uses ZoneSearch (like SWUExploitFodder) with $playerID save/restore so relative zone names resolve.
// GetField objects' trait-filtering uses HasTrait (not ZoneSearch cardSubtypes, which is a dead stub).
function SWUReadyFriendlyDroids($player): array {
    global $playerID;
    $savedPID = $playerID;
    $playerID = intval($player);
    $candidates = array_merge(
        ZoneSearch("myGroundArena", AnyUnitFilter),
        ZoneSearch("mySpaceArena",  AnyUnitFilter)
    );
    $playerID = $savedPID;
    $droids = [];
    foreach ($candidates as $mz) {
        $o = GetZoneObject($mz);
        if (SWUObjGone($o)) continue;
        if (intval($o->Status) !== 1) continue;              // not ready — cannot be exhausted
        if (!HasTrait($o->CardID ?? '', 'Droid')) continue;  // not a Droid
        $droids[] = $mz;
    }
    return $droids;
}

// Returns true if the player controls SEC_122 (Vuutun Palaa) in play (either arena).
function SWUPlayerControlsSEC122(int $player): bool {
    foreach (GetField($player) as $u) {
        if (SWUObjGone($u)) continue;
        if (($u->CardID ?? '') === 'SEC_122') return true;
    }
    return false;
}

// Play-from-hand entry point. Chains optional interactive cost steps (Exploit, then later the
// Droid alt-pay step) before the actual play. If neither applies, plays immediately via
// ActivateCard. Routing here must be fully transparent to non-Exploit plays.
function SWUBeginPlayCard($player, $mzID, $discount = 0) {
    global $playerID, $gPlayGrantedExploit;
    $savedPID = $playerID;
    $playerID = intval($player);
    $discount = max(0, intval($discount));

    $obj = GetZoneObject($mzID);
    if ($obj === null || (isset($obj->removed) && $obj->removed)) {
        $playerID = $savedPID;
        return;
    }

    // TWI_005 Count Dooku (deployed) On Attack: "the next Separatist card you play this phase
    // gains Exploit 3." Consume the flag NOW (before SWUEffectivePlayExploit reads
    // $gPlayGrantedExploit) whenever a Separatist card is being played, regardless of how many
    // units the player ultimately chooses to defeat. A non-Separatist play does NOT consume.
    $cardID = $obj->CardID ?? '';
    if (GlobalEffectCount(intval($player), 'SWU_DOOKU_NEXT_SEPARATIST_EXPLOIT') > 0
            && HasTrait($cardID, 'Separatist')) {
        $gPlayGrantedExploit = intval($gPlayGrantedExploit ?? 0) + 3;
        RemoveGlobalEffect(intval($player), 'SWU_DOOKU_NEXT_SEPARATIST_EXPLOIT');
    }

    // TWI_116 Clone — "You may have this unit enter play as a copy of a non-leader, non-Vehicle unit in
    // play." Offer the (optional) copy choice at PLAY time, before placement, so the copy replacement
    // happens as it enters play (Clone is a 0/0 that would otherwise be defeated on entry). The chosen
    // card ID is stashed in $gCloneCopyCardID; ActivateCard reads it and places Clone as that card with
    // an IsClone flag. Declining (or no eligible target) enters a plain 0/0 Clone that the HP sweep
    // defeats. The cost paid is Clone's own (SWUComputePlayCost still reads TWI_116).
    if ($cardID === 'TWI_116') {
        $copyTargets = _SWUCloneCopyTargets(intval($player));
        if (!empty($copyTargets)) {
            SWUQueueMayChooseTarget(intval($player), $copyTargets,
                "Copy_a_unit_in_play?", "Choose_a_unit_to_copy", "CLONE_COPY_CHOICE|{$mzID}");
            $playerID = $savedPID;
            return;
        }
        // No eligible unit to copy — fall through to normal play (enters as a 0/0 Clone, then defeated).
    }

    // Piloting: a unit with the Piloting keyword may be played as an upgrade on a
    // friendly Vehicle. Decide Unit vs Pilot BEFORE the Exploit step (Exploit only
    // applies on the unit-play branch, which re-enters after this block).
    // SEC_046 Galen Erso — a named card has lost Piloting; it can only be played as a unit (the hand
    // object's Owner isn't reliably set, so gate on $player explicitly rather than HasKeyword_Piloting).
    if (HasKeyword_Piloting($obj) && !_SWUGalenSuppressesCard(intval($player), $obj->CardID ?? '')) {
        // Pre-apply any play discount to the pilot cost (SWUComputePilotCost / the affordability-gated
        // SWUGetPilotValidTargets read SWU_PILOT_DISCOUNT). Removed again on any non-pilot exit below so it
        // never leaks to a later play. Used by top-deck plays that grant a discount (LOF_188 As I Have
        // Foreseen: play the top card, incl. a pilot as an upgrade, for 4 less).
        for ($k = 0; $k < $discount; $k++) AddGlobalEffects(intval($player), 'SWU_PILOT_DISCOUNT');
        $ready = 0;
        foreach (GetResources($player) as $r) {
            if (SWUIsCreditToken($r->CardID ?? '')) continue; // Credit tokens aren't resources
            if (empty($r->removed) && intval($r->Status) === 1) $ready++;
        }
        $unitCost  = max(0, SWUComputePlayCost($player, $obj) - $discount);
        $vehicles  = SWUGetPilotValidTargets(intval($player), $cardID);
        $canUnit   = $ready >= $unitCost;
        $canPilot  = !empty($vehicles); // SWUGetPilotValidTargets is affordability-gated (now discount-aware)

        if ($canUnit && $canPilot) {
            // Both options available — ask the player. Thread the discount so the Unit branch can drop the
            // pilot-discount and apply it to the unit cost instead.
            DecisionQueueController::AddDecision($player, "OPTIONCHOOSE",
                "Unit&Pilot", 1, tooltip:"Play_as_Unit_or_Pilot?");
            DecisionQueueController::AddDecision($player, "CUSTOM",
                "PILOT_PLAY_CHOICE|{$mzID}|{$cardID}|{$discount}", 1);
            $playerID = $savedPID;
            return;
        }
        if (!$canUnit && $canPilot) {
            // Pilot-only (cannot afford the unit cost) — go straight to Vehicle pick (discount consumed at charge).
            SWUQueuePilotVehiclePick(intval($player), $mzID, $cardID, $vehicles);
            $playerID = $savedPID;
            return;
        }
        // Unit-only or neither — the pilot discount doesn't apply; remove it (the unit discount is passed below).
        for ($k = 0; $k < $discount; $k++) RemoveGlobalEffect(intval($player), 'SWU_PILOT_DISCOUNT');
    }

    _SWUBeginPlayCardUnitPath(intval($player), $mzID, $discount);
    $playerID = $savedPID;
}

// TWI_116 Clone — eligible copy targets: every non-leader, non-Vehicle unit in play (either player's
// arenas). "Only printed attributes are copied," so the target is the CARD; damage/upgrades/tokens on it
// are irrelevant to eligibility.
function _SWUCloneCopyTargets(int $player): array {
    $targets = [];
    foreach (['myGroundArena', 'mySpaceArena', 'theirGroundArena', 'theirSpaceArena'] as $zone) {
        foreach (ZoneSearch($zone, AnyUnitFilter) as $mz) {
            $o = GetZoneObject($mz);
            if (SWUObjGone($o)) continue;
            if (IsLeaderUnit($o)) continue;                 // non-leader
            if (TraitContains($o, 'Vehicle')) continue;  // non-Vehicle
            $targets[] = $mz;
        }
    }
    return $targets;
}

// TWI_116 Clone — resolve the copy choice: stash the chosen card's printed CardID in $gCloneCopyCardID
// (null if declined / target gone), then continue the normal unit-play path. ActivateCard reads the
// global at placement time. $playerID is intentionally left = $player (the unit-path convention).
$customDQHandlers["CLONE_COPY_CHOICE"] = function($player, $parts, $lastDecision) {
    global $playerID, $gCloneCopyCardID;
    $playerID = intval($player);
    $mzID = $parts[0] ?? '';
    $gCloneCopyCardID = null;
    if ($lastDecision !== '' && $lastDecision !== '-' && $lastDecision !== 'PASS') {
        $chosen = GetZoneObject($lastDecision);
        if ($chosen !== null && empty($chosen->removed)) {
            $gCloneCopyCardID = $chosen->CardID ?? null;   // the printed card to copy
        }
    }
    _SWUBeginPlayCardUnitPath(intval($player), $mzID);
    // $playerID intentionally left = $player (mirrors _SWUBeginPlayCardUnitPath callers)
};

// ── _SWUBeginPlayCardUnitPath — the Exploit + play funnel for the unit-play branch ──
// Shared by the SWUBeginPlayCard fall-through AND the PILOT_PLAY_CHOICE "Unit" answer,
// so choosing "Unit" from the pilot prompt runs the IDENTICAL path as playing a
// non-pilot unit (Exploit included).
// $playerID must be set correctly by the caller before invoking this.
// CRITICAL: does NOT restore $playerID on return — callers (SWUBeginPlayCard,
// PILOT_PLAY_CHOICE) own the restore so that the event branch of ActivateCard can
// leave $playerID = $player for MZCountChoices (see the SWUContinuePlayAfterExploit
// note and the general engine gotcha in the instructions).
function _SWUBeginPlayCardUnitPath(int $player, string $mzID, int $discount = 0): void {
    global $gPlayGrantedExploit, $gLastExploitedPowers;
    // Reset the per-play record of exploited units' powers (TWI_138 Count Dooku reads it in When Played).
    // Cleared here so a play that doesn't Exploit leaves it empty (no stale leak from a prior play).
    $gLastExploitedPowers = [];

    $obj = GetZoneObject($mzID);
    if ($obj === null || (isset($obj->removed) && $obj->removed)) return;

    $exploitX = SWUEffectivePlayExploit($obj);
    $grant    = intval($gPlayGrantedExploit ?? 0); // capture before reset
    $gPlayGrantedExploit = 0; // prevent the grant from leaking to any subsequent unrelated play
    $friendly = SWUExploitFodder($player);

    if ($exploitX > 0 && !empty($friendly)) {
        $max   = min($exploitX, count($friendly));
        DecisionQueueController::AddDecision($player, "MZMULTICHOOSE",
            "0|{$max}|" . implode("&", $friendly), 1,
            tooltip:"Defeat_up_to_{$max}_units_(Exploit)");
        DecisionQueueController::AddDecision($player, "CUSTOM",
            "EXPLOIT_RESOLVE|{$mzID}|{$grant}|{$exploitX}", 1);
        return;
    }

    // HMW_048 Vernestra Rwoh — "As an additional cost to play this unit, put up to 2 units that each
    // cost 5 or less from your discard pile on the bottom of your deck." Exploit's shape and EXPLOIT'S
    // SCOPE: this lives on the SWUBeginPlayCard path, so a direct-ActivateCard nested play (SOR_219
    // Sneak Attack, play-from-deck effects) skips it — exactly as those paths already skip Exploit.
    // That is a documented engine-family gap (see hmw-implement.md), not a per-card choice; when the
    // family is fixed, fix it at ONE seam for both. The play-grant globals are snapshotted into the
    // param: the caller nulls them before the queued cost resolves (e.g. LOF_076's shield grant).
    if (($obj->CardID ?? '') === 'HMW_048') {
        $picks048 = _SWUHmw048LegalPicks($player);
        if (!empty($picks048)) {
            $max048  = min(2, count($picks048));
            $snap048 = (!empty($GLOBALS['gForceEnterReady']) ? '1' : '0')
                     . '~' . (string)($GLOBALS['gPlayGrantTurnEffect'] ?? '')
                     . '~' . intval($GLOBALS['gPlayGrantShield'] ?? 0);
            DecisionQueueController::AddDecision($player, "MZMULTICHOOSE",
                "0|{$max048}|" . implode("&", $picks048), 1,
                tooltip:"Bottom_up_to_{$max048}_units_(additional_cost)", dontSkipOnPass: 1);
            DecisionQueueController::AddDecision($player, "CUSTOM",
                "HMW_048#0|{$mzID}|" . intval($discount) . "|{$snap048}", 1, dontSkipOnPass: 1);
            return;
        }
    }


    // No Exploit — delegate directly. The event branch of ActivateCard deliberately does
    // NOT restore $playerID before returning (so ExecuteStaticMethods / MZCountChoices
    // can resolve relative zone names). Caller restores $playerID after this returns.
    SWUContinuePlayAfterExploit($player, $mzID, $discount);
}

// ── SWUOfferAltPayment — alternate-payment funnel (Credit tokens, then Droids) ──
// The single site for offering non-resource payment when paying $cost to play a card / attach an
// upgrade / keep the Falcon. Offers Credit-token defeat first (CR 3.13: "While paying resources, you
// may defeat this token. If you do, pay 1 less"); if the player has none usable, falls through to the
// SEC_122 Droid offer (SWUOfferDroidPayment), which itself falls through to the bare continuation.
//   Credit branch: queue MZMULTICHOOSE (defeat 0..min(credits,cost) tokens) + CUSTOM CREDIT_PAY, and
//   leave $playerID = $player (mirrors the Droid offer — MZCountChoices resolves the relative mzIDs
//   right after this returns). CREDIT_PAY then dispatches the continuation with prepaid = tokens
//   defeated (it does NOT chain into the Droid offer — a single payment uses one alt-pay source,
//   which is sufficient for all current cards; SEC_122 + Credits in one deck would not stack).
function SWUOfferAltPayment(int $player, int $cost, string $continuation, string $args, int $block = 1): void {
    if ($cost > 0) {
        $credits = SWUUsableCreditTokenMzIDs($player);
        if (!empty($credits)) {
            $max = min(count($credits), $cost); // can't pay below 0
            global $playerID;
            $playerID = $player; // leave set: MZCountChoices resolves the relative mzIDs after return
            DecisionQueueController::AddDecision($player, "MZMULTICHOOSE",
                "0|{$max}|" . implode("&", $credits), $block,
                tooltip:"Defeat_any_number_of_Credit_tokens_to_pay_1_resource_less_each");
            // The cap rides in the decision param: the MZMULTICHOOSE "0|max|..." bound is enforced by the
            // CLIENT only (the queue controller validates that at least one choice exists, never how many
            // were submitted), so the handler needs its own copy to enforce CR 1.7.2 — "exhaust ready
            // resources EQUAL TO the cost". Without it an over-long answer defeats extra Credits for free.
            DecisionQueueController::AddDecision($player, "CUSTOM",
                "CREDIT_PAY|{$max}|{$continuation}|{$args}", $block);
            return; // $playerID intentionally left = $player
        }
    }
    // No usable Credit tokens — fall through to the Droid offer (then the bare continuation).
    SWUOfferDroidPayment($player, $cost, $continuation, $args, $block);
}

// ── SWUOfferDroidPayment — central SEC_122 alt-pay offer ─────────────────────
// Single entry point for the "exhaust a Droid to pay costs" mechanic (SEC_122).
// If $cost > 0 AND the player controls SEC_122 AND has ready Droids:
//   - Queues MZMULTICHOOSE (pick Droids to exhaust, capped at $cost) at $block.
//   - Queues CUSTOM "DROID_PAY|{$max}|{$continuation}|{$args}" at $block ($max = the CR 1.7.2 cap).
//   - Leaves $playerID = $player on return (CRITICAL: MZCountChoices resolves the
//     relative mzIDs in the MZMULTICHOOSE param under $playerID immediately after
//     this function returns; if $playerID is restored to a different player, the
//     count is 0 and the choice auto-resolves to "-", silently skipping the pick).
//   - Returns without calling the continuation.
// If no Droid offer applies (cost 0 / no SEC_122 / no ready Droids):
//   - Dispatches the continuation immediately with $prepaid = 0.
//   - Leaves $playerID unchanged (caller is responsible for save/restore).
//
// Param encoding: $parts[0] = the exhaust cap, $parts[1] = continuation (a single pipe-free token),
// implode("|", array_slice($parts, 2)) = args (may contain "|").
//
// $block: 1 for card-play / Falcon (matches existing queuing), 0 for upgrades.
function SWUOfferDroidPayment(int $player, int $cost, string $continuation, string $args, int $block = 1): void {
    if ($cost > 0 && SWUPlayerControlsSEC122($player)) {
        $droids = SWUReadyFriendlyDroids($player);
        if (!empty($droids)) {
            $max = min(count($droids), $cost); // CR 8.16: cannot exceed the remaining cost
            // Set $playerID = $player and leave it set — MZCountChoices validates the
            // relative mzIDs in the MZMULTICHOOSE param right after this returns.
            global $playerID;
            $playerID = $player;
            DecisionQueueController::AddDecision($player, "MZMULTICHOOSE",
                "0|{$max}|" . implode("&", $droids), $block,
                tooltip:"Pick_any_number_of_Droids_to_exhaust_for_this_card");
            DecisionQueueController::AddDecision($player, "CUSTOM",
                "DROID_PAY|{$max}|{$continuation}|{$args}", $block);
            return; // $playerID intentionally left = $player
        }
    }
    // No Droid offer — invoke the continuation immediately with prepaid = 0.
    SWUDispatchDroidContinuation($player, $continuation, $args, 0);
}

// ── SWUDispatchDroidContinuation — continuation registry ─────────────────────
// Dispatches to the named continuation after Droid exhaustion (or immediately on
// the no-droid path). $prepaid = number of Droids already exhausted.
// Continuations:
//   PLAY_CARD    args = "{mzID}|{discount}"   → ActivateCard (pays remainder + records resourcesPaid)
//   ATTACH_UPGRADE args = "{cardID}|{upgradeMz}|{hostMz}" → _SWUFinalizeUpgradeAttach (pays remainder)
//   FALCON_KEEP  args = "{falconMz}"          → SWUPayCost(1, prepaid) → keep/bounce Falcon
// Note: PLAY_CARD and ATTACH_UPGRADE do NOT call SWUPayCost here — their downstream
// functions (ActivateCard / _SWUFinalizeUpgradeAttach) already handle payment.
function SWUDispatchDroidContinuation(int $player, string $continuation, string $args, int $prepaid): void {
    switch ($continuation) {
        case 'PLAY_CARD': {
            $argParts = explode('|', $args, 2);
            $mzID     = $argParts[0] ?? '';
            $discount = intval($argParts[1] ?? 0);
            ActivateCard($player, $mzID, false, $discount, $prepaid, null, true);
            break;
        }
        case 'ATTACH_UPGRADE': {
            $argParts  = explode('|', $args, 7);
            $cardID    = $argParts[0] ?? '';
            $upgradeMz = $argParts[1] ?? '';
            $hostMz    = $argParts[2] ?? '';
            $isPilot   = !empty($argParts[3]); // 4th field set to '1' on the pilot path
            $discount  = intval($argParts[4] ?? 0); // 5th field = LOF_018 Anakin aspect-penalty waiver
            // 6th field = OWNER for a foreign play (SEC_205's milled Pilot); empty/absent → the caster.
            $ownerFld  = $argParts[5] ?? '';
            $ownerArg  = ($ownerFld === '') ? null : intval($ownerFld);
            // 7th field = the play-source TurnEffect grant (SHD_194 return-to-hand). ⚠ The explode limit
            // above must cover it: at limit 6 this field was glommed into $ownerFld/truncated and the
            // marker never reached the subcard even though every upstream hop carried it.
            $grantTE   = (string) ($argParts[6] ?? '');
            _SWUFinalizeUpgradeAttach($player, $cardID, $upgradeMz, $hostMz, $prepaid, false, $isPilot, false, $discount, true, $ownerArg, $grantTE);
            break;
        }
        case 'FALCON_KEEP': {
            $falconMz = $args;
            $paidOk   = SWUPayCost($player, 1, $prepaid, false, true); // effect cost ("pay 1 to keep it ready"), not halved by JTL_105
            _SWUFalconKeepOrBounce($player, $falconMz, $paidOk);
            break;
        }
        case 'PLOT_PAY': {
            // Play the chosen Plot card from resources, crediting any Credit/Droid alt-payment. args =
            // the resource mzID. ActivateCard pays the remainder and its terminal After Action stays
            // intercepted, so the Plot window remains open (SWU_PLOT_IN_PROGRESS).
            ActivateCard($player, $args, false, 0, $prepaid);
            _SWUSec008HealOnResourcePlay($player); // SEC_008 Bail — "play a card from your resources"
            break;
        }
        case 'SMUGGLE_PAY': {
            // Re-enter SWUSmuggleResource with the alt-payment settled. args =
            // "{resourceIdx}|{discount}|{deferHandler}" — all scalars, so this survives the request
            // boundary on the decision's own Param (nothing is parked in an in-memory global).
            $argParts = explode('|', $args, 3);
            $idx      = intval($argParts[0] ?? 0);
            $disc     = intval($argParts[1] ?? 0);
            $defer    = ($argParts[2] ?? '') === '' ? null : $argParts[2];
            SWUSmuggleResource($player, $idx, $disc, $defer, $prepaid);
            break;
        }
        case 'UNIT_ACTION_PAY': {
            // A unit's "Action [N resources, …]" cost, after the Credit/Droid offer. args =
            // "{providerCardID}|{cost}|{unitMzID}"; $cost arrives ALREADY halved by SWUUnitAction.
            // The unit's own base cost (exhaust / defeat) was paid before the offer, so only the
            // resource remainder is settled here — then the ability runs exactly as before.
            global $unitAbilities, $playerID;
            $argParts = explode('|', $args, 3);
            $provider = $argParts[0] ?? '';
            $cost     = intval($argParts[1] ?? 0);
            $mzID     = $argParts[2] ?? '';
            $playerID = $player; // $mzID is a relative mzID in this player's frame
            if (!SWUPayCost($player, $cost, $prepaid, false, true)) { SWUAfterAction($player); break; }
            if (isset($unitAbilities[$provider]) && is_callable($unitAbilities[$provider])) {
                ($unitAbilities[$provider])($player, $mzID); // handler owns its SWUAfterAction
            } else {
                SWUAfterAction($player);
            }
            break;
        }
        case 'BASE_EPIC_PAY': {
            // A base Epic Action's "[N resource]" cost, after the Credit/Droid offer. args =
            // "{baseCardID}|{cost}". EpicActionUsed was already set by SWUBaseAction (the gate ahead of
            // it guarantees the cost is payable, so the Epic cannot be consumed for nothing here).
            global $baseAbilities, $playerID;
            $argParts = explode('|', $args, 2);
            $cardID   = $argParts[0] ?? '';
            $cost     = intval($argParts[1] ?? 0);
            $playerID = $player;
            if (!SWUPayCost($player, $cost, $prepaid, false, true)) { SWUAfterAction($player); break; }
            if (isset($baseAbilities[$cardID]) && is_callable($baseAbilities[$cardID])) {
                ($baseAbilities[$cardID])($player);
            } else {
                SWUAfterAction($player);
            }
            break;
        }
        case 'LEADER_ACTION_PAY': {
            // A leader's "Action [N resources, …]" cost, after the Credit/Droid offer. args =
            // "{leaderCardID}|{cost}"; $cost arrives ALREADY halved by SWULeaderAction (so pass
            // applyCostHalving=false — halving it twice would undercharge under JTL_105).
            global $leaderAbilities, $playerID;
            $argParts = explode('|', $args, 2);
            $cardID   = $argParts[0] ?? '';
            $cost     = intval($argParts[1] ?? 0);
            $playerID = $player; // handlers below resolve relative mzIDs
            if (!SWUPayCost($player, $cost, $prepaid, false, true)) { SWUAfterAction($player); break; }
            if (isset($leaderAbilities[$cardID]) && is_callable($leaderAbilities[$cardID])) {
                ($leaderAbilities[$cardID])($player); // handler owns its SWUAfterAction
            } else {
                SWUAfterAction($player);
            }
            break;
        }
        case 'IC27_158_PAY': {
            // Millennium Falcon "you may pay 1 → return a friendly unit costing 3 or less to its
            // owner's hand", after the Credit/Droid alt-pay offer. $prepaid = alt-payments already
            // made; pay the remainder, then offer the (mandatory) return.
            $paidOk = SWUPayCost($player, 1, $prepaid, false, true); // effect cost, not halved by JTL_105
            if (!$paidOk) break;
            $targets = Ic27158EligibleReturns(intval($player));
            if (empty($targets)) break;
            SWUQueueChooseTarget(intval($player), $targets,
                "Return_a_friendly_unit_(cost_3_or_less)_to_its_owner's_hand", "IC27_158#1");
            break;
        }
        case 'JTL_096_MOVE_PAY': {
            // Blue Leader "you may pay 2 resources → move to the ground arena + 2 Experience", after the
            // Credit/Droid alt-pay offer. $args = the moving unit's UniqueID; $prepaid = alt-payments made.
            $paidOk = SWUPayCost($player, 2, $prepaid, false, true); // effect cost, not halved by JTL_105
            if (!$paidOk) break;
            $mz = SWUFindMzByUID(intval($args));
            if ($mz === null) break;
            $newMz = SWUMoveUnitBetweenArenas($mz, 'GroundArena');
            if ($newMz === '') break;
            for ($i = 0; $i < 2; $i++) DoGiveExperienceToken($player, $newMz);
            break;
        }
    }
}

// Stage 2 of the play ceremony: discount from Exploit is known. Routes through the
// central SWUOfferDroidPayment to offer the Droid alt-pay step if SEC_122 is in play.
// NOTE: the event branch of ActivateCard does NOT restore $playerID before returning, so we must
// not restore $playerID here either — callers (SWUBeginPlayCard, EXPLOIT_RESOLVE) handle that.
function SWUContinuePlayAfterExploit($player, $mzID, $discount) {
    $obj  = GetZoneObject($mzID);
    // Upgrades pay their cost HOST-SIDE in ATTACH_UPGRADE (which runs its own Credit/Droid alt-pay offer),
    // so the PLAY_CARD-level alt-pay offer here is spurious for them: with SEC_122 it would exhaust Droids
    // that ActivateCard's upgrade branch never spends, then ATTACH_UPGRADE would ask a second time (the
    // upgrade ends up stuck in hand, Droids wasted). Route upgrades straight to ActivateCard (prepaid 0).
    if ($obj !== null && empty($obj->removed)
            && strpos(strtolower(CardType($obj->CardID ?? '') ?? ''), 'upgrade') !== false) {
        SWUDispatchDroidContinuation(intval($player), 'PLAY_CARD', "{$mzID}|{$discount}", 0);
        return;
    }
    $cost = ($obj !== null && empty($obj->removed))
          ? max(0, SWUComputePlayCost($player, $obj) - intval($discount))
          : 0;
    SWUOfferAltPayment(intval($player), $cost, 'PLAY_CARD', "{$mzID}|{$discount}", 1);
}

// ── Leader: get the non-removed leader card object for a player ────────────
function SWUGetLeader(int $player): ?object {
    $arr = &GetLeader($player);
    for ($i = 0; $i < count($arr); $i++) {
        if (!isset($arr[$i]->removed) || !$arr[$i]->removed) return $arr[$i];
    }
    return null;
}

// Twin Suns (Phase 2): a seat may hold two leaders. The $leaderIndex-th LIVE leader (0-based over
// live entries). Index 0 preserves the historical "first live" behavior for single-leader games.
function SWUGetLeaderByIndex(int $player, int $leaderIndex): ?object {
    $arr  = &GetLeader($player);
    $live = 0;
    for ($i = 0; $i < count($arr); $i++) {
        if (isset($arr[$i]->removed) && $arr[$i]->removed) continue;
        if ($live === $leaderIndex) return $arr[$i];
        $live++;
    }
    return null;
}

// The live leader whose deployed arena-unit carries $uid (DeployedUniqueID). Used on defeat/return to
// reset the CORRECT leader when a seat has two deployed. $uid must be > 0 (0 = not deployed).
function SWUFindLeaderByDeployedUID(int $player, int $uid): ?object {
    if ($uid <= 0) return null;
    $arr = &GetLeader($player);
    for ($i = 0; $i < count($arr); $i++) {
        if (isset($arr[$i]->removed) && $arr[$i]->removed) continue;
        if (intval($arr[$i]->DeployedUniqueID ?? 0) === $uid) return $arr[$i];
    }
    return null;
}

// The live leader with a given CardID. Leader CardIDs are unique per seat (CR §12.3 forbids copies),
// so this identifies a specific leader instance — used for pilot-return (DeployedUniqueID is 0 for a
// pilot subcard) and for a leader ability that mutates "this leader" (matches its own CardID).
function SWUFindLeaderByCardID(int $player, string $cardID): ?object {
    $arr = &GetLeader($player);
    for ($i = 0; $i < count($arr); $i++) {
        if (isset($arr[$i]->removed) && $arr[$i]->removed) continue;
        if (($arr[$i]->CardID ?? '') === $cardID) return $arr[$i];
    }
    return null;
}

// ── Deploy a leader unit to the Ground Arena (or as a Pilot onto a Vehicle) ───
// $mode = 'Unit'  → standard deploy to Ground Arena (existing behaviour).
// $mode = 'Pilot' → attach the leader as a Pilot upgrade onto $hostMz (Asajj JTL_001 etc.).
//                   $hostMz must be a friendly Vehicle mzID (capacity already verified by caller).
// When called with mode='Unit' for a CardLeaderCanDeployAsUpgrade leader AND eligible Vehicles
// exist, queues OPTIONCHOOSE Unit/Pilot before committing — the LEADER_DEPLOY_CHOICE handler
// then calls back with the chosen mode.
// Marks EpicActionUsed/Deployed/Ready=false in all branches. Leaders deploy for free
// (the threshold is a condition, not a cost).
// $isAction=false for a deploy that is a TRIGGERED REACTION rather than the player's action for the turn
// (ASH_018 Grogu — "when you play a unique unit costing 4+ … you may deploy him"). Such a deploy must not
// run its own After Action: the thing that triggered it (the card play) already runs one, and two
// After Actions swap the turn TWICE, handing the same player a second action (live bug report #963).
// ⚠ The Plot arming below still happens either way — CR 19.761.a keys Plot on the DEPLOY EVENT ("When you
// deploy a leader"), not on a deploy action — and the triggering play's own After Action picks up
// SWU_PLOT_IN_PROGRESS and opens the window, so the Plot flow is unchanged.
// ⚠ The flag is NOT threaded through the Unit/Pilot re-offer below (LEADER_DEPLOY_CHOICE re-enters with
// the default true). That is safe only because the one reaction-deploy leader, ASH_018, is not
// CardLeaderCanDeployAsUpgrade, so it can never reach that branch. A future pilot-capable leader with a
// reaction deploy must carry $isAction through LEADER_DEPLOY_CHOICE or it will regress this bug.
function SWUDeployLeader(int $player, string $mode = 'Unit', string $hostMz = '', int $leaderIndex = 0, bool $isAction = true): void {
    global $playerID;
    $savedPID = $playerID;
    $playerID = $player;

    // Twin Suns: deploy the clicked leader instance. Index 0 == the historical first-live leader.
    $leader = SWUGetLeaderByIndex($player, $leaderIndex);
    if ($leader === null) { $playerID = $savedPID; return; }

    $cardID = $leader->CardID;

    // Deploy gate. Standard leaders use the once-per-game Epic Action (free; threshold = printed cost,
    // ready or exhausted). JTL_014 Admiral Trench instead deploys via a NON-epic, repeatable
    // Action [3 resources, Exhaust]: requires the leader ready, controlling 6+ resources, and 3 ready
    // resources to pay — and does NOT consume the epic action, so he can redeploy after returning to
    // leader form.
    if ($leader->Deployed ?? false) { $playerID = $savedPID; return; }
    if ($cardID === 'JTL_014') {
        if (empty($leader->Ready)
            || SWUResourceCount($player) < 6
            || SWUTotalPaymentCapacity($player) < 3) {
            $playerID = $savedPID;
            return;
        }
        SWUPayInlineAbilityCost($player, 3); // [3 resources] — Credits/Droids may pay it (CR 3.13)
    } elseif ($cardID === 'SEC_008') {
        // Bail Organa Action [Exhaust, discard 2 cards from your hand]: deploy if you control 4+ resources.
        // Non-epic, repeatable. The discard-2 is an interactive cost paid BEFORE the deploy commits: on the
        // first call queue a 2-card hand pick + a continuation (SEC_008_DEPLOY) that discards them and
        // re-enters here; the flagged re-entry falls through to the commit below. The leader is exhausted
        // by the shared commit ($leader->Ready = false).
        if (empty($leader->Ready) || SWUResourceCount($player) < 4) { $playerID = $savedPID; return; }
        if (GlobalEffectCount($player, 'SWU_SEC008_DEPLOY_PAID') <= 0) {
            $bailHand = array_values(ZoneSearch("myHand"));
            if (count($bailHand) < 2) { $playerID = $savedPID; return; }
            DecisionQueueController::AddDecision($player, "MZMULTICHOOSE",
                "2|2|" . implode('&', $bailHand), 1, tooltip: "Discard_2_cards_from_your_hand_to_deploy_Bail_Organa");
            DecisionQueueController::AddDecision($player, "CUSTOM", "SEC_008#1|{$leaderIndex}", 1);
            $playerID = $savedPID;
            return;
        }
        RemoveGlobalEffect($player, 'SWU_SEC008_DEPLOY_PAID');
    } elseif ($cardID === 'LAW_013') {
        // Chewbacca, Hero of Kessel — "Epic Action [4 resources]: Deploy this leader." The bracket makes
        // this a real COST, not the usual "if you control N or more resources" THRESHOLD that every other
        // leader carries (he is the only leader in the game printed this way). It is still the
        // once-per-game Epic. Capacity, not ready resources: a Credit token / SEC_122 Droid pays it
        // (CR 3.13). Pay before committing so an unpayable Epic can't spend the slot.
        if (($leader->EpicActionUsed ?? false)
            || SWUTotalPaymentCapacity($player) < intval(CardCost($cardID))) {
            $playerID = $savedPID;
            return;
        }
        SWUPayInlineAbilityCost($player, intval(CardCost($cardID)));
    } elseif ($cardID === 'LOF_007') {
        // Avar Kriss Epic Action: deploy if (resources you control) + (times you used the Force this
        // phase) ≥ 9 (her printed deploy threshold).
        $forceUses = GlobalEffectCount($player, 'SWU_FORCE_USED_THIS_PHASE');
        if (($leader->EpicActionUsed ?? false)
            || (SWUResourceCount($player) + $forceUses) < intval(CardCost($cardID))) {
            $playerID = $savedPID;
            return;
        }
    } elseif ($cardID === 'ASH_018') {
        // Grogu has no Epic Action; he deploys ONLY via his "play a uq unit costing 4+" trigger, which
        // just requires he is ready (no resource threshold).
        if (empty($leader->Ready)) { $playerID = $savedPID; return; }
    } elseif ($cardID === 'ASH_010') {
        // Bo-Katan Kryze, Reclaiming Mandalore — Epic Action: deploy when (resources you control) +
        // (friendly Mandalorian units) ≥ her printed deploy threshold (10). Mirrors LOF_007 Avar Kriss.
        $mandoUnits = 0;
        foreach (GetUnitsInPlay($player) as $u) {
            if (empty($u->removed) && TraitContains($u, 'Mandalorian')) $mandoUnits++;
        }
        if (($leader->EpicActionUsed ?? false)
            || (SWUResourceCount($player) + $mandoUnits) < intval(CardCost($cardID))) {
            $playerID = $savedPID;
            return;
        }
    } else {
        if (($leader->EpicActionUsed ?? false)
            || SWUResourceCount($player) < intval(CardCost($cardID))) {
            $playerID = $savedPID;
            return;
        }
    }

    // For CardLeaderCanDeployAsUpgrade leaders deploying as 'Unit' (not 'UnitDirect'):
    // if eligible Vehicles exist, offer Unit/Pilot choice BEFORE committing state changes.
    // 'UnitDirect' is the internal mode used by LEADER_DEPLOY_CHOICE after the player
    // already chose "Unit" — it skips the re-offer gate.
    if ($mode === 'Unit' && CardLeaderCanDeployAsUpgrade($cardID)) {
        $vehicles = SWUGetLeaderPilotVehicles($player);
        if (!empty($vehicles)) {
            DecisionQueueController::AddDecision($player, "OPTIONCHOOSE",
                "Unit&Pilot", 1, tooltip:"Deploy_as_Unit_or_Pilot?");
            DecisionQueueController::AddDecision($player, "CUSTOM",
                "LEADER_DEPLOY_CHOICE|{$cardID}", 1);
            $playerID = $savedPID;
            return;
        }
    }

    AddGameLogEntry('PLAY', 'P' . intval($player) . ' deployed ' . GameLogCardRef($cardID));

    // Mark the leader side: epic action consumed (NOT for JTL_014's non-epic repeatable deploy),
    // leader flipped to deployed state.
    $leader->EpicActionUsed = ($cardID !== 'JTL_014' && $cardID !== 'SEC_008');
    $leader->Deployed       = true;
    $leader->Ready          = false; // leader side exhausted after the deploy action

    // JTL_191 Invincible — "When you deploy a leader: ...". Add its reaction to the pending-trigger
    // bag NOW (before the mode branches) so it rides whichever flush runs: the Unit branch's
    // CollectEntryTriggers or the Pilot branch's CollectWhenPlayedAsUpgradeTriggers.
    foreach (GetUnitsInPlay($player) as $u) {
        if (empty($u->removed) && ($u->CardID ?? '') === 'JTL_191') {
            AddTrigger($player, 'JTL_191', 'JTL_191', '');
        }
    }
    // TWI_022 Droid Manufactory / TWI_025 Shadow Collective Camp (bases) — "When you deploy a leader:
    // Create 2 Battle Droid tokens / Draw a card." (Mandatory, non-interactive → resolve inline.)
    $dlBase = GetBase($player);
    if (!empty($dlBase) && isset($dlBase[0])) {
        if (($dlBase[0]->CardID ?? '') === 'TWI_022') SWUCreateUnitTokens($player, 'TWI_T01', 2);
        if (($dlBase[0]->CardID ?? '') === 'TWI_025') DoDrawCard($player, 1);
    }

    // CR §19 Plot: a leader deploy opens a Plot window for the deploying player. Arm it now if any
    // affordable Plot card sits in their resources; the window actually opens when this deploy's After
    // Action runs (intercepted in SWUAfterAction), i.e. after the leader's own When Deployed resolves.
    // SWU_PLOT_K snapshots the resource count so replacements appended during the window are excluded
    // from re-offering (CR 19.d). Both deploy branches (Unit / Pilot) funnel through SWUAfterAction.
    if (PlayerHasPlotsToPlay($player)) {
        SetSWUVar('SWU_PLOT_IN_PROGRESS', '1');
        SetSWUVar('SWU_PLOT_K', strval(SWUResourceCount($player)));
        SetSWUVar('SWU_PLOT_P', '0');
        SetSWUVar('SWU_PLOT_PENDING_REPLACE', '');
    }

    if ($mode === 'Pilot') {
        // ── Pilot branch: attach leader as a Pilot upgrade onto the chosen Vehicle ──
        // $hostMz must be a valid Vehicle mzID (verified by caller / LEADER_DEPLOY_PILOT).
        // DeployedUniqueID is 0: the leader exists as a Subcard on the host, not a
        // standalone arena unit, so there is no arena UniqueID to track back.
        $leader->DeployedUniqueID = 0;

        // Attach as a Pilot subcard (ignoreCost=true — deploy is free; isPilot=true).
        // _SWUFinalizeUpgradeAttach expects $playerID = $player (already set above)
        // and handles the Subcard append, WhenPlayedAsUpgrade / OnAttached triggers,
        // and SWUAfterAction.
        _SWUFinalizeUpgradeAttach($player, $cardID, '', $hostMz, 0, true, true);

        $playerID = $savedPID;
        return;
    }

    // ── Unit branch (default): create the arena unit entry ──────────────────
    // The deployed side may print a different arena than the leader side (HMW_004 → The Death
    // Star, a Space unit), so the destination comes from LeaderDeployArena, not a hardcoded
    // ground zone. Every leader without a leaderUnitArena override still lands in GroundArena.
    $uid = NextUniqueID();
    $deployArena = LeaderDeployArena($cardID);
    if ($deployArena === 'SpaceArena') {
        $newCard = AddSpaceArena($player, CardID:$cardID, Status:1,
            Owner:$player, Damage:0, Controller:$player, UniqueID:$uid);
    } else {
        $newCard = AddGroundArena($player, CardID:$cardID, Status:1,
            Owner:$player, Damage:0, Controller:$player, UniqueID:$uid);
    }
    $leader->DeployedUniqueID = $uid;

    $newCardMzID = $newCard->GetMzID();
    // A leader deploy is not "playing a card": its When Deployed (WhenPlayed) entry trigger still
    // fires, but reactive "when you play a card" observers (FFF/Bossk/Cunning) must not. ($isPlay=false)
    $triggered = CollectEntryTriggers($player, $cardID, $newCardMzID, $deployArena, false);

    if ($triggered === 0) {
        DecisionQueueController::CleanupRemovedCards();
        if ($isAction) SWUAfterAction($player);   // see $isAction on the signature (bug report #963)
    }

    $playerID = $savedPID;
}

// Returns true if every cost of the leader's action ability can be paid:
// the resource component (from $leaderActionResourceCosts) and any printed
// additional cost. Checked before the leader exhausts — an unaffordable
// action must be a no-op, not a soft pass that spends the leader.
function SWULeaderActionAffordable(int $player, string $cardID): bool {
    global $leaderActionResourceCosts, $playerID, $leaderAbilities;

    // No registered activated ability → nothing to activate. Leaders whose front side is
    // purely reactive/triggered (e.g. ASH_005 "When a friendly unit's attack ends...") have
    // no $leaderAbilities entry; without this guard a zero-cost such leader would glow green
    // and clicking it would exhaust (tap) the leader for free. Activation dispatches only via
    // $leaderAbilities (see SWULeaderAction), so membership IS "has an activated action".
    if (!isset($leaderAbilities[$cardID])) return false;

    // TWI_255 Brain Invaders — "Each leader loses all abilities except for epic actions." The front
    // (undeployed) leader's activated Action is lost while a Brain Invaders is in play (the Epic deploy
    // is an epic action, dispatched separately, so it still works).
    if (_SWUBrainInvadersInPlay()) return false;

    $cost = $leaderActionResourceCosts[$cardID] ?? 0;
    $cost = SWUApplyCostHalving($player, $cost); // JTL_105 The Starhawk — halves activation costs too
    // Gate on TOTAL payment capacity, never bare ready resources: a Credit token may be defeated while
    // paying resources to pay 1 less (CR 3.13) and a SEC_122 Droid may be exhausted "to pay costs as if
    // it were a resource" — both say COSTS, not "cards", so they cover an activated ability's cost.
    // SWULeaderAction pays through SWUOfferAltPayment, so the offer and the payment agree.
    if ($cost > 0 && SWUTotalPaymentCapacity($player) < $cost) return false;

    // SHD_017 Lando (front) — "Play a card using Smuggle" (effect target) is NOT gated (CR 6.4.587.c): the
    // [Exhaust, defeat a resource] cost changes game state, so usable even with no smugglable card.

    // TWI_002 Nute Gunray: only if 2 or more friendly units were defeated this phase.
    if ($cardID === 'TWI_002' && GlobalEffectCount($player, 'SWU_FRIENDLY_DEFEATED') < 2) return false;
    // SHD_011 Kylo Ren — Action [Exhaust, discard a card from your hand]. Same mandatory discard cost as
    // HMW_010/LAW_011: an empty hand makes the action unavailable, never a soft pass.
    if ($cardID === 'SHD_011') {
        $savedPidK = $playerID;
        $playerID  = $player;
        $handK     = ZoneSearch("myHand");
        $playerID  = $savedPidK;
        if (empty($handK)) return false;
    }
    // ASH_002 Fennec Shand — Action [1 resource, Exhaust, exhaust a friendly unit]. Only a READY unit can
    // pay an "exhaust a friendly unit" cost, so the action needs at least one.
    // ⚠ Gates the COST only. "Play a unit from your hand" is the EFFECT and is deliberately NOT gated
    // (CR 6.4.587.c, as already applied to SHD_017 Lando): exhausting a friendly unit changes game state,
    // so the action remains legal with an empty hand.
    if ($cardID === 'ASH_002') {
        $savedPidF = $playerID;
        $playerID  = $player;
        $readyF    = false;
        foreach (['myGroundArena', 'mySpaceArena'] as $zF) {
            foreach (ZoneSearch($zF, AnyUnitFilter) as $mzF) {
                $oF = GetZoneObject($mzF);
                if ($oF !== null && empty($oF->removed) && intval($oF->Status ?? 0) === 1) { $readyF = true; break 2; }
            }
        }
        $playerID = $savedPidF;
        if (!$readyF) return false;
    }
    // HMW_010 Tarfful — Action [2 resources, Exhaust, discard a card from your hand]. The discard is a
    // mandatory COST, so with an empty hand the action is unavailable and the leader must NOT exhaust.
    if ($cardID === 'HMW_010') {
        $savedPidT = $playerID;
        $playerID  = $player;
        $handT     = ZoneSearch("myHand");
        $playerID  = $savedPidT;
        if (empty($handT)) return false;
    }
    // ASH_012 Vane — Action [Exhaust, defeat a friendly upgrade]: the upgrade-defeat is a mandatory COST, so
    // the action is unavailable (leader not exhausted) when there is no friendly upgrade to defeat.
    if ($cardID === 'ASH_012') {
        $hasUpg = false;
        foreach (['myGroundArena', 'mySpaceArena'] as $z) {
            foreach (ZoneSearch($z, AnyUnitFilter) as $mz) {
                $o = GetZoneObject($mz);
                if ($o !== null && empty($o->removed) && count(GetUpgradesOnUnit($o)) > 0) { $hasUpg = true; break 2; }
            }
        }
        if (!$hasUpg) return false;
    }
    // TS26_02 Anakin / TS26_04 Padmé (front) are deliberately NOT gated here.
    // RULING (2026-08-09): their Action costs nothing but [Exhaust], so it may always be taken as a "soft
    // pass" — exhausting a leader is itself a change to the gamestate, which satisfies CR 8.1.4. The
    // "if 2 or more friendly units entered play this phase" clause is part of the ABILITY's resolution,
    // not part of its cost, so it belongs in the closure (which already no-ops) — never in affordability.
    // ⚠ The old gate here also counted units CURRENTLY IN PLAY carrying the entry flag, which made the
    // whole action silently unavailable the moment one of the two entrants died or was stolen — the
    // leader stayed ready, the closure never ran, and nothing reported why.
    // TS26_06 Rex (front): the ready-an-exhausted-enemy cost needs an exhausted enemy unit in play.
    if ($cardID === 'TS26_06') {
        $hasExh = false;
        foreach (GetUnitsInPlay(OtherPlayer($player)) as $u) {
            if (empty($u->removed) && intval($u->Status ?? 1) === 0) { $hasExh = true; break; }
        }
        if (!$hasExh) return false;
    }
    // TS26_07 Asajj Ventress (front): "Attack with a token unit" — effect target only. NOT gated
    // (CR 6.4.587.c): the [Exhaust] cost changes game state, so usable even with no ready token unit.
    // TWI_006 Wat Tambor: only if a friendly unit was defeated this phase.
    if ($cardID === 'TWI_006' && GlobalEffectCount($player, 'SWU_FRIENDLY_DEFEATED') <= 0) return false;
    // TWI_007 Captain Rex: only if a friendly unit attacked this phase.
    if ($cardID === 'TWI_007' && GlobalEffectCount($player, 'SWU_FRIENDLY_ATTACKED') <= 0) return false;
    // TWI_008 Padmé Amidala: Coordinate — only while you control 3 or more units.
    if ($cardID === 'TWI_008' && !IsCoordinateActive($player)) return false;
    // TWI_011 Ahsoka Tano: Coordinate — only while you control 3 or more units.
    if ($cardID === 'TWI_011' && !IsCoordinateActive($player)) return false;
    // TWI_009 / TWI_011 / TWI_012 / TWI_014 (attack with a unit), TWI_013 Mace (damaged enemy), TWI_015
    // Grievous (a Droid to give Sentinel), TWI_003 Obi-Wan (damaged unit to heal) — effect targets only.
    // NOT gated (CR 6.4.587.c): their [Exhaust]/[cost] changes game state, usable even with no valid target.
    // (TWI_011's Coordinate activation-condition is a SEPARATE gate above and stays enforced.)
    // TWI_010 Pre Vizsla: only if you've drawn a card this phase (its damage = cards drawn; a genuine
    // activation condition, not just an effect target) — kept.
    if ($cardID === 'TWI_010' && GlobalEffectCount($player, 'SWU_DREW_PHASE') <= 0) return false;
    // TWI_004 Yoda: only if a unit left play this phase (activation condition) — kept.
    if ($cardID === 'TWI_004'
        && GlobalEffectCount($player, 'SWU_FRIENDLY_LEFT_PLAY') <= 0
        && GlobalEffectCount($player, 'SWU_ENEMY_LEFT_PLAY') <= 0) return false;

    // IC27_001 Darth Vader (No One to Stop Us) — same shape as SOR_006 below: the front side's
    // "defeat a friendly unit" sits INSIDE the bracketed cost, so it is a cost REQUIREMENT (kept by the
    // CR 6.4.587.c sweep, which only dropped effect-TARGET gates). With no friendly unit the Action is
    // unavailable and the leader must not exhaust. The DEPLOYED side is the opposite — there the defeat
    // is an effect behind "you may … If you do", so it is never gated.
    if ($cardID === 'SOR_006' || $cardID === 'IC27_001') {
        $savedPID = $playerID;
        $playerID = $player;
        $friendlies = array_merge(
            ZoneSearch("myGroundArena", AnyUnitFilter),
            ZoneSearch("mySpaceArena",  AnyUnitFilter)
        );
        $playerID = $savedPID;
        if (empty($friendlies)) return false;
    }

    // SOR_017 Han Solo ("put a card from hand into play as a resource"), SHD_006 Jabba ("choose a unit" to
    // give a Bounty) — effect targets only. NOT gated (CR 6.4.587.c): their [Exhaust] cost changes game
    // state, so each Action is usable even with an empty hand / no unit in play (it just does nothing).

    // JTL_013 Poe Dameron: "attach to a friendly Vehicle without a Pilot" — requires ≥1
    // such Vehicle in play, else the action has no valid target (leader stays ready).
    if ($cardID === 'JTL_013') {
        $savedPID = $playerID;
        $vehicles = SWUGetPoe013AttachVehicles($player);
        $playerID = $savedPID;
        if (empty($vehicles)) return false;
    }

    // TWI_005 Count Dooku: "Play a Separatist card from your hand" (effect target) is NOT gated
    // (CR 6.4.587.c): the [Exhaust] cost changes game state, so usable even with no affordable Separatist.

    // SEC_002 Jabba the Hutt ("a friendly damaged unit deals damage to an enemy unit") — effect targets only.
    // NOT gated (CR 6.4.587.c): the [1 resource, Exhaust] cost changes game state, so the Action is usable
    // even with no friendly damaged unit / no enemy unit (it just does nothing).

    // SEC_003 Lama Su: "play an upgrade from your hand on a friendly non-Vehicle unit" — needs ≥1 hand
    // upgrade with a valid non-Vehicle host, affordable at the −1 discount.
    if ($cardID === 'SEC_003') {
        $savedPID = $playerID;
        $playable = _SWUSec003PlayableHandUpgrades($player);
        $playerID = $savedPID;
        if (empty($playable)) return false;
    }

    // SEC_004 Leia Organa (Disclose), SEC_005 Satine Kryze (heal a unit) — effect targets only. NOT gated
    // (CR 6.4.587.c): their [1 resource, Exhaust] / [Exhaust] cost changes game state, so the Action is usable
    // even with no disclosable card / no damaged unit (it just does nothing).

    // SEC_006 Colonel Yularen: "Attack with a unit" — the effect's target. NOT gated (CR 6.4.587.c): the
    // [Exhaust] cost changes game state, so the Action is usable even with no ready unit (it just does nothing).

    // SEC_007 Dryden Vos: cost "[Exhaust, discard a card costing 6+]" + effect "play a unit costing ≤5".
    // The 6+ discard is part of the COST → keep it gated. The "≤5 playable unit" is the effect's target →
    // NOT gated (CR 6.4.587.c): usable with a 6+ card to discard even if no ≤5 unit is playable.
    if ($cardID === 'SEC_007') {
        $savedPID = $playerID; $playerID = $player;
        $has6 = false;
        foreach (ZoneSearch('myHand') as $mz) {
            $o = GetZoneObject($mz);
            if (SWUObjGone($o)) continue;
            if (intval(CardCost($o->CardID)) >= 6) { $has6 = true; break; }
        }
        $playerID = $savedPID;
        if (!$has6) return false;
    }

    // SEC_010 Dedra Meero (choose an enemy unit), SEC_011 Governor Pryce (ready a token unit), SEC_018 DJ
    // (choose a friendly + play a unit) — effect targets only. NOT gated (CR 6.4.587.c): their
    // [1 resource, Exhaust] / [Exhaust] cost changes game state, so each Action is usable even with no valid
    // target (it just does nothing).

    // LOF leaders whose Action cost includes "use the Force (lose your Force token)" — the player must
    // control their Force token to pay, else the Action isn't available.
    global $leaderActionForceCost;
    if (!empty($leaderActionForceCost[$cardID]) && !PlayerHasTheForce($player)) return false;

    // LAW_001 Saw Gerrera (attack with a unit), LAW_002 Tobias Beckett (a friendly non-leader to give away),
    // LAW_003 Agent Kallus (a playable hand card), LAW_004 Aurra Sing (a non-leader unit with ≤1 HP to
    // defeat) — effect targets only. NOT gated (CR 6.4.587.c): their [Exhaust]/[1 resource, Exhaust] cost
    // changes game state, so each Action is usable even with no valid target (it just does nothing).
    // LAW_005 Jyn Erso (front) — "If a friendly Rebel was defeated this phase, search…" is a conditional
    // EFFECT, not an activation gate: the [1 resource, Exhaust] cost changes game state, so the Action is
    // usable anyway (CR 6.4.587.c — "Use it anyway": pay + exhaust, no draw). The handler no-ops the search
    // when the condition isn't met. NOT gated (matches LAW_001-004/006).
    // LAW_006 Vel Sartha (front) — "Give an Experience token to a unit" (effect target) is NOT gated
    // (CR 6.4.587.c): the [Exhaust] cost changes game state, so usable even with no unit in play.
    // LAW_008 Director Krennic (front) — needs a friendly unit to defeat (the cost).
    if ($cardID === 'LAW_008') {
        $savedPID = $playerID; $playerID = $player;
        $ok = !empty(ZoneSearch('myGroundArena', AnyUnitFilter)) || !empty(ZoneSearch('mySpaceArena', AnyUnitFilter));
        $playerID = $savedPID;
        if (!$ok) return false;
    }
    // LAW_009 Hera Syndulla — passive only, no front Action.
    if ($cardID === 'LAW_009') return false;
    // LAW_010 Leia Organa (front) — "give a unit +1/+1 per aspect" (effect target) is NOT gated
    // (CR 6.4.587.c): the [2 resources, Exhaust] cost changes game state, so usable even with no unit.
    // LAW_011 Darth Vader (front) — needs a card in hand to discard (the cost).
    if ($cardID === 'LAW_011') {
        $savedPID = $playerID; $playerID = $player;
        $ok = !empty(ZoneSearch('myHand'));
        $playerID = $savedPID;
        if (!$ok) return false;
    }
    // LAW_012 Sebulba (front) — "A friendly unit gains Raid 1" (effect target) is NOT gated (CR 6.4.587.c):
    // the [Exhaust, discard a card from your deck] cost changes game state, so usable even with no unit.
    // BUT the [discard a card from your deck] cost requires a non-empty deck — gate on that.
    if ($cardID === 'LAW_012' && _SWUTopDeckFrontIdx($player) === -1) return false;
    // LAW_014 Enfys Nest — front is a reaction (no Action).
    if ($cardID === 'LAW_014') return false;
    // LAW_013 Chewbacca (front) — Action [1 resource, Exhaust, defeat a friendly resource]. TWO separate
    // resource costs: a Credit token may pay the "[1 resource]" (CR 3.13) but CANNOT satisfy "defeat a
    // friendly resource", because a Credit is created in the resource zone and is explicitly NOT a
    // resource (CR 3.13). SWUResourceCount already excludes Credits, so this is the real-resource gate.
    // (Previously implicit: the ready-resource cost check happened to also prove a resource existed.)
    if ($cardID === 'LAW_013' && SWUResourceCount($player) < 1) return false;
    // LAW_015 Jabba (front) — needs a friendly Underworld unit to return (the additional cost); the
    // 1-resource cost is already gated above via $leaderActionResourceCosts.
    if ($cardID === 'LAW_015') {
        if (empty(_SWULaw015FriendlyUnderworldUnits($player))) return false;
    }
    // LAW_017 Han Solo (front) — needs a friendly token to defeat (the cost). "Friendly token" = the Force
    // token, a Credit, an Experience/Shield token, or a Token unit (all enumerated by _SWULaw017TokenOptions).
    if ($cardID === 'LAW_017') {
        if (empty(_SWULaw017TokenOptions($player))) return false;
    }
    // LAW_016 The Client (front) — "Action [Exhaust]: If you created a token this phase, exhaust an enemy
    // unit." The "if you created a token" is a conditional EFFECT, not an activation gate: the [Exhaust]
    // cost changes game state, so the Action is usable anyway (CR 6.4.587.c — exhaust the leader, no
    // effect). NOT gated. The handler no-ops the exhaust-an-enemy when the condition isn't met.

    return true;
}

// ── Exhaust leader and trigger its action ability ──────────────────────────
// Dispatches to the per-card handler in $leaderAbilities. If no handler is
// registered for the card, the leader is exhausted but nothing else happens.
function SWULeaderAction(int $player, string $cardID, int $leaderIndex = 0): void {
    global $playerID, $leaderAbilities;
    $savedPID = $playerID;
    $playerID = $player;

    // A leader's "Action: …" ability is a player action — legal ONLY during the action phase.
    // The UI gates on this, but guard the engine entry too: once both players have passed (e.g.
    // a player takes the initiative after the opponent passed) the action phase ends, and a
    // stray/bypassed call must not still exhaust the leader and fire the ability.
    if (GetCurrentPhase() !== 'MAIN') { $playerID = $savedPID; return; }

    // Twin Suns: act on the clicked leader instance. Index 0 == the historical first-live leader.
    $leader = SWUGetLeaderByIndex($player, $leaderIndex);

    // A deployed leader's front Action is normally unavailable (its unit side takes over) — EXCEPT
    // TWI_017 "Flipatine", whose "Deployed" state is just its flipped Villainy face (no unit side); its
    // Action is available on BOTH faces (the $leaderAbilities closure branches on the face).
    if ($leader === null || !$leader->Ready || ($leader->Deployed && ($leader->CardID ?? '') !== 'TWI_017')) {
        $playerID = $savedPID;
        return;
    }

    // Costs must be payable before anything happens — leader stays ready and
    // the player keeps their action if not.
    if (!SWULeaderActionAffordable($player, $cardID)) {
        $playerID = $savedPID;
        return;
    }

    $leader->Ready = false; // exhaust

    // Pay the resource component CENTRALLY, through the alt-payment funnel, so Credit tokens (CR 3.13)
    // and SEC_122 Droids can pay a leader Action exactly as they pay a card. Handlers no longer call
    // SWUExhaustResources themselves — they are dispatched by LEADER_ACTION_PAY once the cost is paid.
    // When the player has no usable Credit/Droid the funnel dispatches SYNCHRONOUSLY with prepaid 0,
    // so this is behaviour-identical to the old inline payment for every player without tokens.
    global $leaderActionResourceCosts;
    $cost = SWUApplyCostHalving($player, $leaderActionResourceCosts[$cardID] ?? 0);
    if ($cost > 0) {
        SWUOfferAltPayment($player, $cost, 'LEADER_ACTION_PAY', "{$cardID}|{$cost}", 1);
        return; // $playerID intentionally left = $player when the funnel queued a decision
    }

    if (isset($leaderAbilities[$cardID]) && is_callable($leaderAbilities[$cardID])) {
        ($leaderAbilities[$cardID])($player);
        // Ability handlers are responsible for calling SWUAfterAction
    } else {
        SWUAfterAction($player);
    }

    $playerID = $savedPID;
}

// Remaining uses of a repeatable base Action this game. The NumUses field is lazily seeded: an
// absent/sentinel (<0) value means "untouched" → the full per-game budget. Returns 0 for a base
// that is not a registered repeatable-action base.
function _SWUBaseActionUsesLeft($base, string $cardID): int {
    global $baseActionNumUses;
    if ($base === null || !isset($baseActionNumUses[$cardID])) return 0;
    $n = isset($base->NumUses) ? intval($base->NumUses) : -1;
    return ($n < 0) ? intval($baseActionNumUses[$cardID]) : $n;
}

// ── Base Actions: the base's own Action, plus Actions hosted on Fortify upgrades ─────────────────────
// A base can now carry upgrades (Fortify), and such an upgrade may itself grant an activated Action
// (HMW_095 Carbonite Chamber) — registered in $baseUpgradeAbilities, keyed by the UPGRADE's CardID, and
// called as fn($player, $upgradeIndex). Clicking the base is a single undifferentiated input, so when
// more than one Action is available the player is asked which to use rather than one silently shadowing
// the other (the deliberate difference from the single-provider unit model in SWUGetUnitActionProvider).
//
// Returns every AVAILABLE base Action as
//   ['kind' => 'own'|'upgrade', 'cardID' => …, 'index' => <upgrade index, or -1 for 'own'>, 'label' => …]
// Labels are single-token (DecisionQueue params split on spaces) and are re-derived, not stored — the
// board cannot change between the OPTIONCHOOSE and the CUSTOM that reads its answer.
function _SWUBaseActionProviders(int $player): array {
    global $baseAbilities, $baseActionNumUses, $baseActionRepeatable, $baseUpgradeAbilities;
    $baseArr = GetBase($player);
    $base = null;
    foreach ($baseArr as $b) { if (empty($b->removed)) { $base = $b; break; } }
    if ($base === null) return [];
    $cardID = $base->CardID ?? '';
    $out = [];

    // The base's own Action — only when it actually has one registered, so clicking a vanilla base can
    // no longer burn its (nonexistent) Epic slot. SEC_046 Galen Erso suppresses it by name.
    if (isset($baseAbilities[$cardID]) && !_SWUGalenSuppressesCard($player, $cardID)) {
        $available = true;
        if (isset($baseActionRepeatable[$cardID])) {
            // Repeatable card-cost Action (LOF_028 Tomb of Eilram): available iff the cost can be paid,
            // i.e. the player has a ready friendly unit to exhaust.
            $available = false;
            foreach (array_merge(GetGroundArena($player), GetSpaceArena($player)) as $ru) {
                if (SWUObjGone($ru)) continue;
                if (intval($ru->Status ?? 0) === 1) { $available = true; break; }
            }
        } elseif (isset($baseActionNumUses[$cardID])) {
            $available = _SWUBaseActionUsesLeft($base, $cardID) > 0; // per-GAME budget
        } else {
            $available = empty($base->EpicActionUsed);
            // LAW_023 Great Pit of Carkoon — its Epic cost is "[discard a unit from your hand]"; with no
            // unit in hand the cost can't be paid, so the Action isn't offered at all (and can't burn the
            // Epic slot). Mirrors the resource-cost affordability gate in _SWUBaseOwnAction.
            if ($available && $cardID === 'LAW_023') $available = _SWULaw023CanPayCost($player);
            // LAW_019 Alliance Outpost — same rule for its "[defeat a friendly token]" cost: with no
            // friendly token the cost is unpayable, so don't offer the Action at all.
            if ($available && $cardID === 'LAW_019') $available = _SWULaw019CanPayCost($player);
        }
        if ($available) $out[] = ['kind' => 'own', 'cardID' => $cardID, 'index' => -1, 'label' => 'EpicAction'];
    }

    // Actions granted by upgrades attached to the base. Index is the position among non-captive,
    // non-removed subcards — what SWUDefeatUpgrade's $upgradeIndex means.
    $idx = 0;
    foreach (GetUpgradesOnUnit($base) as $sub) {
        $ucid = is_array($sub) ? ($sub['CardID'] ?? '') : ($sub->CardID ?? '');
        if ($ucid !== '' && isset($baseUpgradeAbilities[$ucid])) {
            $label = preg_replace('/[^A-Za-z0-9]/', '', (string)CardTitle($ucid));
            if ($label === '') $label = str_replace('_', '', $ucid);
            foreach ($out as $o) { if ($o['label'] === $label) { $label .= ($idx + 1); break; } }
            $out[] = ['kind' => 'upgrade', 'cardID' => $ucid, 'index' => $idx, 'label' => $label];
        }
        $idx++;
    }
    return $out;
}

// Run one resolved base Action.
function _SWUDispatchBaseAction(int $player, array $prov): void {
    global $playerID, $baseUpgradeAbilities;
    if ($prov['kind'] === 'own') { _SWUBaseOwnAction($player); return; }
    $playerID = $player;
    $fn = $baseUpgradeAbilities[$prov['cardID']] ?? null;
    if (is_callable($fn)) $fn($player, intval($prov['index']));
    else SWUAfterAction($player);
}

function SWUBaseAction(int $player): void {
    global $playerID;
    $savedPID = $playerID;
    $playerID = $player;

    $providers = _SWUBaseActionProviders($player);
    if (empty($providers)) { $playerID = $savedPID; return; }   // nothing available — keep the action
    if (count($providers) === 1) {
        _SWUDispatchBaseAction($player, $providers[0]);
        $playerID = $savedPID;
        return;
    }
    // More than one Action on the base — let the player pick. The leading "@CardID" segment renders the
    // base's art above the buttons (OptionChooseUI strips it from the options).
    $labels = array_column($providers, 'label');
    $baseArr = GetBase($player);
    $bcid = '';
    foreach ($baseArr as $b) { if (empty($b->removed)) { $bcid = $b->CardID ?? ''; break; } }
    DecisionQueueController::AddDecision($player, 'OPTIONCHOOSE',
        ($bcid !== '' ? '@' . $bcid . '&' : '') . implode('&', $labels), 1,
        tooltip: 'Which_base_ability_do_you_want_to_use?');
    DecisionQueueController::AddDecision($player, 'CUSTOM', 'BASE_ACTION_PICK', 1);
    $playerID = $savedPID;
}

function _SWUBaseOwnAction(int $player): void {
    global $playerID, $baseAbilities, $baseActionNumUses, $baseActionRepeatable;
    $savedPID = $playerID;
    $playerID = $player;

    $baseArr = &GetBase($player);
    $base    = null;
    for ($i = 0; $i < count($baseArr); $i++) {
        if (!isset($baseArr[$i]->removed) || !$baseArr[$i]->removed) {
            $base = &$baseArr[$i];
            break;
        }
    }

    if ($base === null) {
        $playerID = $savedPID;
        return;
    }
    $cardID = $base->CardID;

    // SEC_046 Galen Erso — if the enemy Galen named this base, it has lost its abilities → no base action.
    if (_SWUGalenSuppressesCard($player, $cardID)) { $playerID = $savedPID; return; }

    // Repeatable base Action with a card-cost (e.g. LOF_028 Tomb of Eilram): runs every time, the
    // ability closure pays its own cost. Does NOT consume EpicActionUsed or a NumUses budget.
    if (isset($baseActionRepeatable[$cardID])) {
        if (isset($baseAbilities[$cardID]) && is_callable($baseAbilities[$cardID])) {
            ($baseAbilities[$cardID])($player);
        } else {
            SWUAfterAction($player);
        }
        $playerID = $savedPID;
        return;
    }

    // Repeatable base Action (e.g. LOF_022 Mystic Monastery): gated per GAME by the NumUses field,
    // NOT the once-per-game EpicActionUsed flag (so it doesn't consume the epic slot). The budget is
    // exempted from the per-round NumUses refill (SWUResetAllNumUses), making it whole-game.
    if (isset($baseActionNumUses[$cardID])) {
        $left = _SWUBaseActionUsesLeft($base, $cardID);
        if ($left <= 0) {
            $playerID = $savedPID;
            return;
        }
        $base->NumUses = $left - 1; // lazily seed + consume in one step
        if (isset($baseAbilities[$cardID]) && is_callable($baseAbilities[$cardID])) {
            ($baseAbilities[$cardID])($player);
        } else {
            SWUAfterAction($player);
        }
        $playerID = $savedPID;
        return;
    }

    // Standard once-per-game Epic Action base.
    if ($base->EpicActionUsed) {
        $playerID = $savedPID;
        return;
    }
    // Affordability gate for an Epic Action with a printed [N resource] cost (LAW_029 Citadel Research
    // Center). If the player can't pay, the Epic is "not selectable" — a no-op that must NOT consume the
    // once-per-game Epic slot (so a forced/illegal activation doesn't waste it).
    global $baseEpicResourceCosts;
    $epicCost = $baseEpicResourceCosts[$cardID] ?? 0;
    // Capacity, not ready resources: a Credit token / SEC_122 Droid pays an Epic Action's cost too.
    if ($epicCost > 0 && SWUTotalPaymentCapacity($player) < $epicCost) {
        $playerID = $savedPID;
        return;
    }
    // LAW_029 Citadel Research Center — "[1 resource]: Return a friendly RESOURCE …". The two
    // resource-shaped costs are independent: a Credit may pay the bracket cost but is never itself a
    // resource to return (CR 3.13), so the Epic also needs a real resource to exist or it is a no-op
    // that must PRESERVE the once-per-game Epic. Same shape as the LAW_013 Chewbacca gate.
    if ($cardID === 'LAW_029' && SWUResourceCount($player) < 1) {
        $playerID = $savedPID;
        return;
    }
    // LAW_023 Great Pit of Carkoon — same rule for a CARD cost: its Epic is "[discard a unit from your
    // hand]", so with no unit in hand the cost is unpayable, the Action is a no-op, and the once-per-game
    // Epic slot must survive. (The ability closure already bailed out here, but only after the flag below
    // had been set — the Epic was silently spent for nothing.)
    if ($cardID === 'LAW_023' && !_SWULaw023CanPayCost($player)) {
        $playerID = $savedPID;
        return;
    }
    // LAW_019 Alliance Outpost — same shape. Its closure already bailed out on an unpayable cost, but
    // only AFTER the flag below was set, so the once-per-game Epic was silently spent for nothing.
    if ($cardID === 'LAW_019' && !_SWULaw019CanPayCost($player)) {
        $playerID = $savedPID;
        return;
    }
    $base->EpicActionUsed = true;

    // Pay the Epic's resource cost centrally, through the alt-pay funnel, then dispatch the ability.
    if ($epicCost > 0) {
        SWUOfferAltPayment($player, $epicCost, 'BASE_EPIC_PAY', "{$cardID}|{$epicCost}", 1);
        return; // $playerID intentionally left = $player when the funnel queued a decision
    }

    if (isset($baseAbilities[$cardID]) && is_callable($baseAbilities[$cardID])) {
        ($baseAbilities[$cardID])($player);
    } else {
        SWUAfterAction($player);
    }

    $playerID = $savedPID;
}

// ── Unit activated abilities ("Action [Exhaust]: …") ────────────────────────
// Parallel to SWULeaderAction. A unit's action can be provided by the unit itself
// ($unitAbilities[unitCardID]) OR by an attached upgrade ($unitAbilities[upgradeCardID]),
// mirroring OnAttackFromUpgrade. Returns the providing CardID, or '' if none.
// TWI_047 Satine Kryze — true while ANY player controls a Satine (TWI_047) in play. Her constant ability
// grants an Action to every unit on the board, so the grant is checked field-wide (either player's).
function _SWUSatineInPlay(): bool {
    foreach ([1, 2] as $p) {
        foreach (array_merge(GetGroundArena($p), GetSpaceArena($p)) as $u) {
            if ($u !== null && empty($u->removed) && ($u->CardID ?? '') === 'TWI_047') return true;
        }
    }
    return false;
}

function SWUGetUnitActionProvider($obj): string {
    global $unitAbilities;
    if (SWUObjGone($obj)) return '';
    if (isset($unitAbilities[$obj->CardID])) return $obj->CardID;
    foreach (GetUpgradesOnUnit($obj) as $u) {
        $uid = is_array($u) ? ($u['CardID'] ?? '') : ($u->CardID ?? '');
        if ($uid !== '' && isset($unitAbilities[$uid])) return $uid;
    }
    // TWI_047 Satine Kryze — "Each unit (including enemy units) gains: Action [Exhaust]: …" A field-wide
    // granted Action: any unit without its own provider gets Satine's while a Satine is in play. (A unit
    // with its own Action keeps it — the single-provider model surfaces only one, a documented edge.)
    if (_SWUSatineInPlay()) return 'TWI_047';
    return '';
}

// Affordability for a unit action: resource cost (rare) + per-card additional costs.
// The Exhaust cost is checked separately by SWUUnitAction (the unit must be ready).
function SWUUnitActionAffordable(int $player, string $mzID, string $providerCardID): bool {
    global $playerID, $unitActionResourceCosts;
    $cost = $unitActionResourceCosts[$providerCardID] ?? 0;
    $cost = SWUApplyCostHalving($player, $cost); // JTL_105 The Starhawk — halves activation costs too
    // Total payment capacity, not bare ready resources — Credit tokens (CR 3.13) and SEC_122 Droids pay
    // an activated ability's cost exactly as they pay a card's. SWUUnitAction pays through the same
    // funnel, so the offer and the payment agree.
    if ($cost > 0 && SWUTotalPaymentCapacity($player) < $cost) return false;

    $savedPID = $playerID;
    $playerID = $player;
    $ok = true;
    // A unit that has lost its abilities can't use its activated ("Action [Exhaust]:") ability.
    $actor = GetZoneObject($mzID);
    if ($actor !== null && LostAbilities($actor)) { $playerID = $savedPID; return false; }
    switch ($providerCardID) {
        case 'TS26_15': { // C-3P0 — "Only opponents may use this ability." Block the OWNER (even if control
                           // reverts to them); any non-owner may. Also needs another ground unit to target.
            if ($actor !== null && intval($player) === intval($actor->Owner ?? $player)) { $ok = false; break; }
            $selfUID = SWUObjUID($actor);
            $found = false;
            foreach (['myGroundArena', 'theirGroundArena'] as $z) {
                foreach (ZoneSearch($z, AnyUnitFilter) as $mz) {
                    $o = GetZoneObject($mz);
                    if ($o !== null && empty($o->removed) && intval($o->UniqueID ?? -1) !== $selfUID) { $found = true; break 2; }
                }
            }
            if (!$found) $ok = false;
            break;
        }
        case 'HMW_009': { // Chewbacca (deployed): "Use this ability only once each round" — and, since the
                          // ability has NO cost at all (no exhaust, no resources), it must not be offerable
                          // when it could do nothing: it needs a friendly unit with a valid NON-BASE target.
                          // (The FRONT side deliberately is NOT target-gated — its [2 resources, Exhaust]
                          // cost changes game state, so per CR 6.4.587.c it stays available and fizzles.)
            if (!SWUHasUseAvailable($actor)) { $ok = false; break; }
            if (empty(_SWUHmw009Attackers($player))) $ok = false;
            break;
        }
        case 'ASH_119': // Greef Karga: only useful if your base was attacked this phase.
            if (GlobalEffectCount($player, 'SWU_BASE_ATTACKED') <= 0) $ok = false;
            break;
        case 'TWI_082': { // MagnaGuard Wing Leader: once each round, and needs a ready Droid unit.
            if (GlobalEffectCount($player, 'SWU_TWI082_USED') > 0) { $ok = false; break; }
            $found = false;
            foreach (['myGroundArena', 'mySpaceArena'] as $z) {
                foreach (ZoneSearch($z, AnyUnitFilter) as $mz) {
                    $o = GetZoneObject($mz);
                    if ($o !== null && empty($o->removed) && intval($o->Status ?? 0) === 1 && HasTrait($o->CardID ?? '', 'Droid')) { $found = true; break 2; }
                }
            }
            if (!$found) $ok = false;
            break;
        }
        case 'TWI_206': { // Independent Senator: needs a ready unit with 4 or less power to exhaust.
            $found = false;
            foreach (['myGroundArena', 'mySpaceArena', 'theirGroundArena', 'theirSpaceArena'] as $z) {
                foreach (ZoneSearch($z, AnyUnitFilter) as $mz) {
                    $o = GetZoneObject($mz);
                    if ($o !== null && empty($o->removed) && intval($o->Status ?? 0) === 1 && intval(ObjectCurrentPower($o)) <= 4) { $found = true; break 2; }
                }
            }
            if (!$found) $ok = false;
            break;
        }
        // SHD_155 Heroic Resolve — NO readiness gate (USER RULING 2026-08-15). The costs (2 resources +
        // defeating a Heroic Resolve on this unit) are payable regardless of whether the attack can
        // actually happen, and paying them for no attack is a legitimate SOFT PASS: the game state really
        // did change. A readiness gate would deny the player that line, which is the opposite of the CR
        // position that a cost may be paid even when the effect does nothing.
        case 'SHD_087': // Crosshair — available if EITHER sub-action is affordable: 2 ready resources
                        // (the +1/+0 action) OR the unit is ready (the Exhaust deal-power action).
            if (!(($actor !== null && intval($actor->Status ?? 0) === 1)
                    || SWUTotalPaymentCapacity($player) >= 2)) $ok = false;
            break;
        case 'ASH_230': // Improvised Identity (granted): once each round.
            if (GlobalEffectCount($player, 'SWU_ASH230_USED') > 0) $ok = false;
            break;
        case 'SHD_017': // Lando (deployed): once each round, and needs a smugglable unit affordable at -2.
            if (GlobalEffectCount($player, 'SWU_SHD017_USED') > 0) $ok = false;
            elseif (!_SWUShd017HasTarget($player)) $ok = false;
            break;
        case 'ASH_109': // T-6 Shuttle: needs ANOTHER unit to buff.
        case 'ASH_118': { // 8D8: needs ANOTHER friendly unit to damage.
            $selfUid = SWUObjUID($actor, 0);
            $zones = $providerCardID === 'ASH_109'
                ? ['myGroundArena', 'mySpaceArena', 'theirGroundArena', 'theirSpaceArena']
                : ['myGroundArena', 'mySpaceArena'];
            $found = false;
            foreach ($zones as $z) { foreach (ZoneSearch($z, AnyUnitFilter) as $mz) { $o = GetZoneObject($mz); if ($o !== null && empty($o->removed) && intval($o->UniqueID ?? 0) !== $selfUid) { $found = true; break 2; } } }
            if (!$found) $ok = false;
            break;
        }
        case 'LAW_084': // Krrsantan: needs 2+ cards in hand to pay the discard cost.
            if (count(array_filter(GetHand($player), fn($c) => empty($c->removed))) < 2) $ok = false;
            break;
        case 'ASH_217': // Mayor's Majordomo: needs 1+ card in hand to pay the discard cost.
            if (count(array_filter(GetHand($player), fn($c) => empty($c->removed))) < 1) $ok = false;
            break;
        case 'LAW_015': // Jabba (deployed): needs a playable Underworld unit in hand (ready resources + Credits).
            if (empty(_SWULaw015PlayableUnderworldUnits($player))) $ok = false;
            break;
        case 'LAW_156': // Hunter For Hire: cost is defeating a friendly Credit token (the acting player's).
            if (empty(SWUUsableCreditTokenMzIDs($player))) $ok = false;
            break;
        // LAW_003 Agent Kallus (deployed): "play a card ignoring aspect penalties" is the EFFECT target. The
        // cost is [1 resource, Exhaust] — both paid by SWUUnitAction before the handler runs (a game-state
        // change), so per CR 6.4.587.c the Action is usable even with no playable hand card. NOT gated here.
        case 'ASH_002': { // Fennec Shand (deployed): needs 1 ready resource, a hand unit, and a ready friendly unit (the cost).
            if (SWUTotalPaymentCapacity($player) < 1) { $ok = false; break; }
            if (empty(ZoneSearch('myHand', ['Unit', 'Token Unit']))) { $ok = false; break; }
            $hasReady = false;
            foreach (['myGroundArena', 'mySpaceArena'] as $z) {
                foreach (ZoneSearch($z, AnyUnitFilter) as $mz) {
                    $o = GetZoneObject($mz);
                    if ($o !== null && empty($o->removed) && intval($o->Status) === 1) { $hasReady = true; break 2; }
                }
            }
            if (!$hasReady) $ok = false;
            break;
        }
        case 'LOF_013': // Barriss Offee (deployed): the cost is [use the Force] → keep the Force gate. The
            // playable event is the effect target → NOT gated (CR 6.4.587.c). The handler spends the Force
            // (UseTheForce) BEFORE checking for an event, so the cost is paid even when nothing is played.
            if (!PlayerHasTheForce($player)) $ok = false;
            break;
        case 'LOF_018': // Anakin (deployed): the cost is [use the Force] → keep the Force gate. The playable
            // Villainy card is the effect target → NOT gated (CR 6.4.587.c). The handler spends the Force
            // (UseTheForce) BEFORE checking for a target, so the cost is paid even when nothing is played.
            if (!PlayerHasTheForce($player)) $ok = false;
            break;
        case 'SEC_007': // Dryden Vos (deployed): the cost is [discard a card] → keep the "card in hand" gate.
            // "Play a unit" is the effect target → NOT gated (CR 6.4.587.c): usable with a card to discard
            // even with no playable unit. The handler (SEC_007D) discards the chosen card BEFORE checking for
            // a playable unit, so the cost is paid even when nothing is played.
            if (empty(ZoneSearch('myHand'))) $ok = false;
            break;
        case 'LAW_126': { // Adventurer Sniper Rifle: needs an undamaged non-leader ground unit to target.
            $has = false;
            foreach (["myGroundArena", "theirGroundArena"] as $z) {
                foreach (ZoneSearch($z, NonLeaderUnitFilter) as $mz) {
                    $o = GetZoneObject($mz);
                    if ($o !== null && empty($o->removed) && intval($o->Damage ?? 0) === 0) { $has = true; break 2; }
                }
            }
            if (!$has) $ok = false;
            break;
        }
        case 'LAW_094': // Hondo Ohnaka: deck non-empty, not used this round, top card actually playable.
            $topIdx094 = _SWUTopDeckFrontIdx($player);
            if ($topIdx094 === -1 || GlobalEffectCount($player, 'SWU_LAW094_USED') > 0) { $ok = false; break; }
            // "Play the top card of your deck" respects play-restrictions: can't use it on a card an
            // opponent named (SOR_062 Regional Governor) — the top card must be playable.
            $deck094 = GetDeck($player);
            $topCid094 = $deck094[$topIdx094]->CardID ?? '';
            if ($topCid094 !== '' && SWUCardPlayBlocked($player, $topCid094)) $ok = false;
            break;
        case 'SOR_094': // Bail Organa: "Give Experience to ANOTHER friendly unit" — needs one.
            $others = SWUOtherFriendlyUnits($player, $mzID);
            if (empty($others)) $ok = false;
            break;
        case 'SOR_093': // Alliance Dispatcher / Strategic Acumen: play a UNIT from hand at −1.
        case 'TWI_120': // Needs ≥1 hand unit affordable after the discount.
            if (empty(SWUHandPlayablesAtDiscount($player, ['Unit'], 1))) $ok = false;
            break;
        case 'LOF_094': // Jedi Consular — Action [Exhaust, use the Force]: play a unit at −2.
            if (!PlayerHasTheForce($player) || empty(SWUHandPlayablesAtDiscount($player, ['Unit'], 2))) $ok = false;
            break;
        case 'LOF_178': // Adept of Anger — Action [Exhaust, use the Force]: exhaust a unit.
            if (!PlayerHasTheForce($player)) $ok = false;
            break;
        case 'LOF_098': // Action [use the Force]: only while in the SPACE arena + you hold the Force.
            if (!PlayerHasTheForce($player) || strpos((string)$mzID, 'SpaceArena') === false) $ok = false;
            break;
        case 'SOR_177': // Bib Fortuna: play an EVENT from hand at −1.
            if (empty(SWUHandPlayablesAtDiscount($player, ['Event'], 1))) $ok = false;
            break;
        case 'JTL_050': { // Phantom II: "attach it as an upgrade to The Ghost" — needs ANY unit titled
            // "The Ghost" in play, on EITHER player's side (JTL_053 Heart of the Family, SOR_050 Spectre
            // Home Base, …). The card targets by title, not a specific CardID, and an opponent's Ghost is
            // a legal host too (CR — an ability that says "The Ghost" refers to any card with that title).
            $hasGhost = false;
            foreach ([1, 2] as $pl) {
                foreach (array_merge(GetGroundArena($pl) ?? [], GetSpaceArena($pl) ?? []) as $u) {
                    if (empty($u->removed) && SWUObjectTitle($u) === 'The Ghost') { $hasGhost = true; break 2; }
                }
            }
            if (!$hasGhost) $ok = false;
            break;
        }
        case 'SOR_110': // Frontline Shuttle: defeat self, then ANOTHER friendly unit attacks
            // a non-base target — needs ≥1 such attacker (excluding the Shuttle itself).
            $self = GetZoneObject($mzID);
            $selfUID = SWUObjUID($self);
            if (empty(SWUUnitsWithNonBaseAttackTarget($player, $selfUID))) $ok = false;
            break;
        case 'SOR_184': // Fett's Firespray: "Exhaust a non-unique unit" — needs ≥1 in play.
            if (empty(_SWUNonUniqueUnitTargets($player))) $ok = false;
            break;
        case 'JTL_013': // Poe Dameron hop: once-per-round (activation condition → keep). The empty-Vehicle to
            // hop to is the effect target → NOT gated (CR 6.4.587.c): the [1 resource] cost is a game-state
            // change, so the hop is usable even with no other ship to hop to — spend 1 and don't hop (a soft
            // pass); Poe stays on his current Vehicle. The dispatcher pays the resource; the handler no-ops on
            // no target (and does NOT consume the once-per-round, since no hop occurred).
            if (!SWUHasUseAvailable(SWUGetLeader($player))) $ok = false;
            break;
    }
    $playerID = $savedPID;
    return $ok;
}

// True if $player controls a card with one of the given titles, as a LEADER (deployed or not),
// a UNIT in an arena, or an UPGRADE attached to a friendly unit (SOR_184 "control Boba Fett or
// Jango Fett (as a leader, unit, or upgrade)"). Title match is exact (CardTitle).
function _SWUControlsTitle(int $player, array $titles): bool {
    foreach (GetLeader($player) as $l) {
        if (empty($l->removed) && in_array(SWUObjectTitle($l), $titles, true)) return true;
    }
    foreach (GetUnitsInPlay($player) as $u) {
        if (!empty($u->removed)) continue;
        if (in_array(SWUObjectTitle($u), $titles, true)) return true;
        if (is_array($u->Subcards ?? null)) {
            foreach ($u->Subcards as $sub) {
                $scid = is_array($sub) ? ($sub['CardID'] ?? '') : ($sub->CardID ?? '');
                $srem = is_array($sub) ? !empty($sub['removed']) : !empty($sub->removed);
                if (!$srem && in_array(CardTitle($scid), $titles, true)) return true;
            }
        }
    }
    return false;
}

// All NON-unique units in play (both players, both arenas) as mzIDs — SOR_184 "exhaust a non-unique
// unit". Deployed leaders are unique, so they're excluded. Caller sets $playerID.
function _SWUNonUniqueUnitTargets(int $player): array {
    $out = [];
    foreach (['myGroundArena', 'mySpaceArena', 'theirGroundArena', 'theirSpaceArena'] as $z) {
        foreach (ZoneSearch($z, AnyUnitFilter) as $mz) {
            $o = GetZoneObject($mz);
            if (SWUObjGone($o)) continue;
            if (CardUnique($o->CardID ?? '')) continue;
            $out[] = $mz;
        }
    }
    return $out;
}

// Hand card mzIDs of the given $types whose play cost — after $discount (floored at 0) —
// the player can pay with ready resources. Single source of truth for "play a card from
// hand at −N" actions (SOR_093/TWI_120 units, SOR_177 events): used both by the
// affordability gate and by the ability closures. Caller sets $playerID.
function SWUHandPlayablesAtDiscount(int $player, array $types, int $discount): array {
    $ready = SWUTotalPaymentCapacity($player); // Credits/Droids can pay a play cost (CR 3.13)
    $out = [];
    foreach (ZoneSearch("myHand", $types) as $mz) {
        $o = GetZoneObject($mz);
        if (SWUObjGone($o)) continue;
        $cost = max(0, SWUComputePlayCost($player, $o) - $discount);
        if ($cost <= $ready) $out[] = $mz;
    }
    return $out;
}

// Hand cards (any type) with the Separatist trait whose play cost the player can afford
// with their current ready resources (no discount). Shared by TWI_005 Count Dooku's
// affordability gate and its ability closures (leader side + deployed-unit side).
// Caller must set $playerID before calling.
function _SWUSeparatistHandPlayables(int $player): array {
    $ready = SWUTotalPaymentCapacity($player); // Credits/Droids can pay a play cost (CR 3.13)
    $out = [];
    foreach (ZoneSearch("myHand") as $mz) {
        $o = GetZoneObject($mz);
        if (SWUObjGone($o)) continue;
        if (!HasTrait($o->CardID ?? '', 'Separatist')) continue;
        $cost = SWUComputePlayCost($player, $o);
        if ($cost <= $ready) $out[] = $mz;
    }
    return $out;
}

// Friendly units that could make a non-base attack: those in an arena where the opponent
// has ≥1 unit (attacks are same-arena; "can't attack bases" leaves only enemy units).
// Optionally exclude one unit by UniqueID (the SOR_110 Shuttle, defeated as its cost).
// Caller sets $playerID. Shared by SOR_110's affordability gate and its ability closure.
function SWUUnitsWithNonBaseAttackTarget(int $player, int $excludeUID = -1): array {
    $out = [];
    foreach (['GroundArena', 'SpaceArena'] as $arena) {
        $oppArr = GetZone("their{$arena}");
        $hasEnemyUnit = false;
        foreach ($oppArr as $u) { if ($u !== null && empty($u->removed)) { $hasEnemyUnit = true; break; } }
        if (!$hasEnemyUnit) continue;
        $myArr = GetZone("my{$arena}");
        for ($i = 0; $i < count($myArr); $i++) {
            $u = $myArr[$i];
            if (SWUObjGone($u)) continue;
            if (intval($u->UniqueID ?? -2) === $excludeUID) continue;
            $out[] = "my{$arena}-{$i}";
        }
    }
    return $out;
}

// All friendly units except the one at $mzID (by UniqueID). Caller sets $playerID.
function SWUOtherFriendlyUnits(int $player, string $mzID): array {
    $self    = GetZoneObject($mzID);
    $selfUID = SWUObjUID($self);
    $out = [];
    foreach (array_merge(
        ZoneSearch("myGroundArena", AnyUnitFilter),
        ZoneSearch("mySpaceArena",  AnyUnitFilter)
    ) as $mz) {
        $o = GetZoneObject($mz);
        if (SWUObjGone($o)) continue;
        if (intval($o->UniqueID ?? -2) === $selfUID) continue;
        $out[] = $mz;
    }
    return $out;
}

// Pay the base action cost and dispatch the unit's action ability. Full no-op if the cost
// is unaffordable — the player keeps their action. Base cost is 'exhaust' (requires ready,
// exhausts the unit) by default, or 'defeat' (no ready requirement; the unit is defeated to
// pay — SOR_110). The Exhaust cost-kind requires Status===1; 'defeat' may act while exhausted.
function SWUUnitAction(int $player, string $mzID): void {
    global $playerID, $unitAbilities, $unitActionResourceCosts, $unitActionCostKind;
    $savedPID = $playerID;
    $playerID = $player;

    $obj = GetZoneObject($mzID);
    if (SWUObjGone($obj)) {
        $playerID = $savedPID;
        return;
    }
    $provider = SWUGetUnitActionProvider($obj);
    if ($provider === '') {
        $playerID = $savedPID;
        return;
    }
    _SWURecordDamageSource(intval($player), $mzID); // TWI_016 — the acting unit is the source of its activated-ability damage
    $costKind = $unitActionCostKind[$provider] ?? 'exhaust';
    if ($costKind === 'exhaust' && intval($obj->Status) !== 1) {
        $playerID = $savedPID;
        return; // not ready → can't pay the Exhaust cost
    }
    if (!SWUUnitActionAffordable($player, $mzID, $provider)) {
        $playerID = $savedPID;
        return;
    }

    // Pay the base cost.
    if ($costKind === 'defeat') {
        SWUDefeatUnit($player, $mzID); // the unit leaves play; closure attacks with another unit
    } elseif ($costKind === 'exhaust') {
        $obj->Status = 0; // exhaust (the default action cost)
    }
    // 'none': no base cost — a pure "Action [N resources]:" ability (no exhaust, no ready needed,
    // repeatable while resources last, e.g. SOR_184 Fett's Firespray). The resource cost is paid below,
    // through the alt-payment funnel so Credit tokens / SEC_122 Droids can pay it (CR 3.13). With no
    // usable token the funnel dispatches synchronously with prepaid 0 — identical to the old inline pay.
    $rc = $unitActionResourceCosts[$provider] ?? 0;
    $rc = SWUApplyCostHalving($player, $rc); // JTL_105 The Starhawk — halves activation costs too
    if ($rc > 0) {
        SWUOfferAltPayment($player, $rc, 'UNIT_ACTION_PAY', "{$provider}|{$rc}|{$mzID}", 1);
        return; // $playerID intentionally left = $player when the funnel queued a decision
    }

    if (isset($unitAbilities[$provider]) && is_callable($unitAbilities[$provider])) {
        ($unitAbilities[$provider])($player, $mzID);
        // Ability handlers are responsible for calling SWUAfterAction.
    } else {
        SWUAfterAction($player);
    }

    $playerID = $savedPID;
}

// ── Plot (CR §19) ────────────────────────────────────────────────────────────
// "When you deploy a leader, you may play this card from your resource zone by paying its cost,
// replacing it with the top card of your deck." Detection is generated ($Plot_Cards / HasKeyword_Plot);
// only execution lives here. The window is orchestrated through SWUAfterAction (see SWU_PLOT_IN_PROGRESS):
// the deploy arms it, each play re-offers until the player declines or no affordable Plot remains.

// True if the player has at least one Plot card in their resources they can afford right now.
// Affordability uses TOTAL payment capacity — ready resources (the Plot card itself may pay for it, it
// counts toward ready when ready) plus Credit tokens / SEC_122 Droids, since Plot pays a card's cost and
// CR 3.13 applies — including aspect penalties (folded into SWUComputePlayCost).
function PlayerHasPlotsToPlay(int $player): bool {
    global $playerID, $Plot_Cards;
    $saved = $playerID; $playerID = $player;
    $ready = SWUTotalPaymentCapacity($player);
    $resources = &GetResources($player);
    $found = false;
    for ($i = 0; $i < count($resources); $i++) {
        if (isset($resources[$i]->removed) && $resources[$i]->removed) continue;
        $cardID = $resources[$i]->CardID ?? '';
        if (!isset($Plot_Cards[$cardID])) continue;
        if (_SWUGalenSuppressesCard($player, $cardID)) continue;   // SEC_046 Galen Erso — named → lost Plot
        if (SWUCardPlayBlocked($player, $cardID)) continue;      // SOR_062 named-card lock
        if (SWUComputePlayCost($player, $resources[$i]) <= $ready) { $found = true; break; }
    }
    $playerID = $saved;
    return $found;
}

// Resource mzIDs (myResources-N) eligible to be played as a Plot this deploy: a Plot card,
// affordable, and inside the original-resources window [0, K-P) so top-of-deck replacements
// appended during this window are not re-offered (CR 19.d).
function _SWUEligiblePlotResources(int $player): array {
    global $playerID, $Plot_Cards;
    $saved = $playerID; $playerID = $player;
    $window = intval(GetSWUVar('SWU_PLOT_K', '0')) - intval(GetSWUVar('SWU_PLOT_P', '0'));
    $ready  = SWUTotalPaymentCapacity($player); // Credits/Droids can pay a Plot's cost (CR 3.13)
    $resources = &GetResources($player);
    $out = [];
    $pos = 0;
    for ($i = 0; $i < count($resources); $i++) {
        if (isset($resources[$i]->removed) && $resources[$i]->removed) continue;
        $here = $pos; $pos++;
        if ($here >= $window) continue;                          // a replacement (CR 19.d) — skip
        $cardID = $resources[$i]->CardID ?? '';
        if (!isset($Plot_Cards[$cardID])) continue;
        if (_SWUGalenSuppressesCard($player, $cardID)) continue;   // SEC_046 Galen Erso — named → lost Plot
        if (SWUCardPlayBlocked($player, $cardID)) continue;
        if (SWUComputePlayCost($player, $resources[$i]) > $ready) continue;
        $out[] = "myResources-{$here}";
    }
    $playerID = $saved;
    return $out;
}

// Replace the just-played Plot card's slot with the top of the deck (enters exhausted, CR 19.c).
// If the deck is empty there is no replacement (and no base damage — CR 19 has no mill).
function _SWUPlotReplaceSlot(int $player): void {
    global $playerID;
    $saved = $playerID; $playerID = $player;
    $deck = &GetDeck($player);
    for ($i = 0; $i < count($deck); $i++) {
        if (isset($deck[$i]->removed) && $deck[$i]->removed) continue;
        $topCardID = $deck[$i]->CardID;
        $deck[$i]->Remove();
        AddResources($player, $topCardID, 0, $player, $player);   // Status 0 = exhausted
        break;
    }
    DecisionQueueController::CleanupRemovedCards();
    $playerID = $saved;
}

// Called from SWUAfterAction while a Plot window is open. If a Plot card was just played, replace its
// slot and count it; then re-offer the next eligible Plot (or close the window).
function _SWUPlotAfterPlay(int $player): void {
    if (GetSWUVar('SWU_PLOT_PENDING_REPLACE', '') === '1') {
        SetSWUVar('SWU_PLOT_PENDING_REPLACE', '');
        _SWUPlotReplaceSlot($player);
        SetSWUVar('SWU_PLOT_P', strval(intval(GetSWUVar('SWU_PLOT_P', '0')) + 1));
    }
    _SWUPlotReoffer($player);
}

// Offer the next Plot (MZMAYCHOOSE over eligible resources). When none remain, close the window and
// run the real After Action (swap the turn — ending the deploy action).
function _SWUPlotReoffer(int $player): void {
    $eligible = _SWUEligiblePlotResources($player);
    if (empty($eligible)) {
        SetSWUVar('SWU_PLOT_IN_PROGRESS', '');
        SetSWUVar('SWU_PLOT_K', '0');
        SetSWUVar('SWU_PLOT_P', '0');
        SetSWUVar('SWU_PLOT_PENDING_REPLACE', '');
        SWUSwapTurnPlayer();
        return;
    }
    global $playerID; $playerID = $player;   // for relative mzID resolution in MZCountChoices
    DecisionQueueController::AddDecision($player, "MZMAYCHOOSE", implode('&', $eligible), 1,
        tooltip: "Play_a_Plot_card_from_your_resources");
    // dontSkipOnPass: PLOT_PLAY is the RESOLVER, and declining is a real outcome it has to handle —
    // it clears SWU_PLOT_IN_PROGRESS and runs the deploy's real After Action. DecisionQueueController
    // skips the decision following a PASS unless it opts out, and the UI's PASS button submits
    // cardID=PASS, so without this the resolver never runs on a decline: the window stays open (the
    // next card played is redirected back into the Plot orchestrator and re-offers) and the deploy
    // never finalises (the turn never passes = a free extra action). Bug #923.
    // Answering '-' took the non-PASS path and resolved correctly, which is why this hid from the
    // schema tests until one drove the PASS button's actual value.
    DecisionQueueController::AddDecision($player, "CUSTOM", "PLOT_PLAY", 1, dontSkipOnPass: 1);
}

// MZMAYCHOOSE resolver: $lastDecision is the chosen resource mzID, or '-'/'' to decline.
$customDQHandlers["PLOT_PLAY"] = function($player, $parts, $lastDecision) {
    global $playerID;
    $savedPID = $playerID; $playerID = intval($player);
    $ans = $lastDecision ?? '';
    if ($ans === '' || $ans === '-' || $ans === 'PASS') {
        // Declined → close the window and end the deploy action (flag cleared → real swap).
        SetSWUVar('SWU_PLOT_IN_PROGRESS', '');
        SetSWUVar('SWU_PLOT_K', '0');
        SetSWUVar('SWU_PLOT_P', '0');
        SetSWUVar('SWU_PLOT_PENDING_REPLACE', '');
        SWUAfterAction(intval($player));
        $playerID = $savedPID;
        return;
    }
    $resObj = GetZoneObject($ans);
    if (SWUObjGone($resObj)) { _SWUPlotReoffer(intval($player)); $playerID = $savedPID; return; }
    // A Plot is being played: mark for slot-replacement at the next After Action (CR 19.c).
    SetSWUVar('SWU_PLOT_PENDING_REPLACE', '1');
    AddGameLogEntry('PLAY', 'P' . intval($player) . ' plays ' . GameLogCardRef($resObj->CardID) . ' using Plot');
    // Spend the Plot card toward its OWN cost, from ANY position in the zone.
    //
    // A Plot card is still a RESOURCE when it is played, so it may be exhausted toward its own cost, and
    // the engine already depends on that: ChancellorPalpatine_HowLibertyDies pins a cost-2 Plot play at
    // "7 ready -> 5", i.e. two resources consumed INCLUDING the card itself. But SWUExhaustResources
    // sweeps from index 0, so that only ever happened when the Plot card happened to sit FIRST. A card
    // further down was never the one spent: the player paid the full cost out of OTHER resources and
    // still lost the slot to the top-of-deck replacement. Bug #925 (Cad Bane at index 6).
    //
    // Moving the chosen card to the front makes the existing sweep spend it first from any position —
    // the same behaviour the index-0 tests already assert, now deliberate rather than positional luck.
    // Resource ORDER carries no game meaning (the zone is a pool, and _SWUPlotReplaceSlot appends the
    // replacement rather than filling the vacated slot), and this card leaves the zone immediately, so
    // the reorder is unobservable. Preferred over threading a prepayment: the deferred upgrade path
    // re-encodes its call through DROID_PAY, whose arg parser drops any extra field.
    //
    // An EXHAUSTED Plot card is left where it is — it cannot be exhausted again, so it pays nothing and
    // the full cost correctly comes from elsewhere. $ans is index-based and must be remapped.
    $plotRes = &GetResources(intval($player));
    $plotIdx = intval(explode('-', $ans)[1] ?? -1);
    if ($plotIdx > 0 && isset($plotRes[$plotIdx]) && intval($plotRes[$plotIdx]->Status ?? 0) === 1) {
        $plotMoved = $plotRes[$plotIdx];
        array_splice($plotRes, $plotIdx, 1);
        array_unshift($plotRes, $plotMoved);
        $ans = 'myResources-0';
    }
    // Play from resources at full cost (the Plot card exhausts itself toward its cost — see above).
    // ActivateCard removes it and routes unit/upgrade/event; its terminal After Action is intercepted
    // (the window stays open).
    // Route the cost through the alt-payment funnel, so a Credit token / SEC_122 Droid can pay part of it
    // (CR 3.13) exactly as on the normal play path. $ans is a scalar mzID, so it rides the CUSTOM
    // decision's own Param across the request boundary. No usable token → dispatches synchronously.
    //
    // UPGRADES ARE EXCLUDED, mirroring SWUContinuePlayAfterExploit: an upgrade pays its cost HOST-SIDE in
    // ATTACH_UPGRADE, which runs its own Credit/Droid offer. Offering here too would spend tokens the
    // upgrade branch never credits and then ask a second time. (Every Plot card printed so far IS an
    // upgrade, so today this is the only live branch — the funnel path is for a future non-upgrade Plot.)
    $plotObj  = GetZoneObject($ans);
    $plotType = ($plotObj !== null && empty($plotObj->removed)) ? (CardType($plotObj->CardID ?? '') ?? '') : '';
    if (strpos(strtolower($plotType), 'upgrade') !== false) {
        SWUDispatchDroidContinuation(intval($player), 'PLOT_PAY', $ans, 0);
    } else {
        $plotCost = ($plotObj !== null && empty($plotObj->removed))
                  ? max(0, SWUComputePlayCost(intval($player), $plotObj)) : 0;
        SWUOfferAltPayment(intval($player), $plotCost, 'PLOT_PAY', $ans, 1);
    }
    // Do NOT restore $playerID — the upgrade/event paths return without restoring and rely on $playerID
    // staying = $player for MZCountChoices on any decision they queued.
};

// ── Disclose (CR §38) ────────────────────────────────────────────────────────
// "Disclose" reveals any number of hand cards; if their aspect icons collectively cover the required
// icons, the rest of the ability resolves (CR 38.1-2). Otherwise nothing is revealed and the effect
// does not happen (CR 38.3). Optional ("you may disclose") effects simply aren't offered when the
// requirement cannot be met.

// The aspect icons a card shows, as a multiset list (e.g. SEC_054 → ['Vigilance','Vigilance']).
function SWUCardAspectIcons(string $cardID): array {
    $a = CardAspect($cardID);
    if ($a === null || $a === '') return [];
    return array_values(array_filter(array_map('trim', explode(',', $a))));
}

// True if the multiset $have covers the multiset $required (icon counts).
function _SWUAspectsCover(array $have, array $required): bool {
    $pool = [];
    foreach ($have as $x) { $pool[$x] = ($pool[$x] ?? 0) + 1; }
    foreach ($required as $r) {
        if (($pool[$r] ?? 0) <= 0) return false;
        $pool[$r]--;
    }
    return true;
}

// Can the player's hand collectively disclose the required aspect icons?
function PlayerCanDisclose(int $player, array $required): bool {
    if (empty($required)) return true;
    // Resolve the hand mzIDs UNDER $player — keep $playerID = $player across the whole loop, since
    // GetZoneObject("myHand-N") resolves "my" against the ambient $playerID. Restoring before the loop
    // (the old bug) read the caller's hand when $player != the ambient $playerID — e.g. SEC_038 Condemn,
    // whose disclose belongs to the DEFENDER but fires under the ATTACKER's $playerID.
    global $playerID; $saved = $playerID; $playerID = $player;
    $hand = ZoneSearch("myHand");
    $have = [];
    foreach ($hand as $mz) {
        $o = GetZoneObject($mz);
        if (SWUObjGone($o)) continue;
        $have = array_merge($have, SWUCardAspectIcons($o->CardID ?? ''));
    }
    $playerID = $saved;
    return _SWUAspectsCover($have, $required);
}

// Queue an optional disclose over the player's hand. If the requirement can't be met it's not offered
// (CR 38.3). On a covering selection the chosen cards are revealed (logged; they stay in hand) and
// $thenHandler (a CUSTOM handler string, e.g. "DRAW_CARD|1") is dispatched. The server re-validates
// coverage on the answer, so a client can't bypass the requirement.
// $elseHandler (optional): a CUSTOM handler queued when the player CAN'T meet the requirement or
// DECLINES it — for "you may disclose X; if you DON'T, <penalty>" cards (SEC_164). It is encoded into
// the resolver token after a "@@ELSE@@" sentinel (neither handler may contain that literal).
function SWUQueueDisclose(int $player, array $required, string $thenHandler, string $tooltip, string $elseHandler = ''): void {
    if (!PlayerCanDisclose($player, $required)) {
        if ($elseHandler !== '') DecisionQueueController::AddDecision($player, "CUSTOM", $elseHandler, 1);
        return;
    }
    // Compact any removed-but-not-cleaned cards (e.g. the event/unit that triggered this disclose was
    // just removed from hand) so the offered hand mzIDs match what they resolve to at answer time.
    DecisionQueueController::CleanupRemovedCards();
    global $playerID; $saved = $playerID; $playerID = $player;
    $hand = ZoneSearch("myHand");
    $playerID = $saved;
    if (empty($hand)) {
        if ($elseHandler !== '') DecisionQueueController::AddDecision($player, "CUSTOM", $elseHandler, 1);
        return;
    }
    if ($elseHandler !== '') $thenHandler = $thenHandler . '@@ELSE@@' . $elseHandler;
    $reqCSV = implode(',', $required);
    // The "~REQ~aspects" tooltip suffix carries the required icons to the client so the popup can gate
    // its Confirm on aspect coverage (window.aspectData supplies each candidate's icons). The popup
    // strips it for display; the server never parses the tooltip semantically. The server re-validates
    // coverage in DISCLOSE_RESOLVE regardless, so this is purely a client-UX side channel.
    $discloseTooltip = $tooltip . "~REQ~" . implode('-', $required);
    DecisionQueueController::AddDecision($player, "MZMULTICHOOSE", "0|" . count($hand) . "|" . implode('&', $hand),
        1, tooltip: $discloseTooltip);
    DecisionQueueController::AddDecision($player, "CUSTOM", "DISCLOSE_RESOLVE|{$reqCSV}|{$thenHandler}", 1);
}

// Validates the disclosed selection and dispatches the "if you do" effect.
$customDQHandlers["DISCLOSE_RESOLVE"] = function($player, $parts, $lastDecision) {
    global $playerID; $playerID = intval($player);
    $required    = array_values(array_filter(explode(',', $parts[0] ?? '')));
    $combined    = implode('|', array_slice($parts, 1));   // handler may carry '|'-delimited args
    $hb          = explode('@@ELSE@@', $combined);          // optional "if you don't" handler
    $thenHandler = $hb[0];
    $elseHandler = $hb[1] ?? '';
    $selected = ($lastDecision !== null && $lastDecision !== '-' && $lastDecision !== '' && $lastDecision !== 'PASS')
        ? array_values(array_filter(explode('&', $lastDecision)))
        : [];
    $have = [];
    foreach ($selected as $mz) {
        $o = GetZoneObject($mz);
        if (SWUObjGone($o)) continue;
        $have = array_merge($have, SWUCardAspectIcons($o->CardID ?? ''));
    }
    if (empty($selected) || !_SWUAspectsCover($have, $required)) {   // declined / insufficient (CR 38.3)
        if ($elseHandler !== '') DecisionQueueController::AddDecision(intval($player), "CUSTOM", $elseHandler, 1);
        return;
    }
    foreach ($selected as $mz) {
        $o = GetZoneObject($mz);
        if ($o !== null) AddGameLogEntry('DISCLOSE', 'P' . intval($player) . ' discloses ' . GameLogCardRef($o->CardID ?? ''));
    }
    // SEC_016 Padmé Amidala — disclosing reveals cards from hand ("reveal 1 or more cards from your hand").
    if (function_exists('_SWUSec016React')) _SWUSec016React(intval($player));
    if ($thenHandler !== '') DecisionQueueController::AddDecision(intval($player), "CUSTOM", $thenHandler, 1);
};

// Play a card from the player's resource zone using Smuggle (CR 8.22).
// $resourceIdx is the 0-based index into the player's non-removed Resources entries.
// $prepaid: resources already covered by an alternate payment (Credit tokens / SEC_122 Droids). The
// SENTINEL -1 means "the alt-payment offer has not been made yet" — on that first entry, once the cost
// is known, this queues the offer and re-enters through SMUGGLE_PAY with the real prepaid amount.
// Everything before the first mutation is pure cost computation, so re-entering recomputes identically.
function SWUSmuggleResource(int $player, int $resourceIdx, int $discount = 0, ?string $deferHandler = null, int $prepaid = -1): void {
    global $playerID;
    $savedPID = $playerID;
    $playerID = $player;

    // Locate the resource at the given logical index.
    $resources = &GetResources($player);
    $actualIdx = -1;
    $count = 0;
    for ($i = 0; $i < count($resources); $i++) {
        if (isset($resources[$i]->removed) && $resources[$i]->removed) continue;
        if (SWUIsCreditToken($resources[$i]->CardID ?? '')) continue; // Credit tokens aren't smugglable resources
        if ($count === $resourceIdx) { $actualIdx = $i; break; }
        $count++;
    }

    if ($actualIdx === -1) {
        SetFlashMessage("Invalid resource index.");
        $playerID = $savedPID;
        return;
    }

    $resourceObj = $resources[$actualIdx];
    $cardID      = $resourceObj->CardID;

    // SOR_062 Regional Governor: an opponent's named card can't be played, including via Smuggle.
    if (SWUCardPlayBlocked(intval($player), $cardID)) {
        SetFlashMessage("That card can't be played (named by an opponent).");
        $playerID = $savedPID;
        return;
    }

    // SEC_046 Galen Erso — if the enemy Galen named this card, it has lost Smuggle (and all abilities).
    if (_SWUGalenSuppressesCard($player, $cardID)) {
        SetFlashMessage("That card doesn't have Smuggle.");
        $playerID = $savedPID;
        return;
    }
    // Determine effective cost: min(native Smuggle path, Tech path), factoring in aspect penalties.
    $totalCost = GetEffectiveSmuggleCost($player, $cardID);
    if ($totalCost < 0) {
        SetFlashMessage("That card doesn't have Smuggle.");
        $playerID = $savedPID;
        return;
    }
    // SHD_017 Lando — "It costs 2 resources less." Applied after the aspect-adjusted Smuggle cost, floored at 0.
    $totalCost = max(0, $totalCost - $discount);
    // Shared, base-cost-independent play-cost modifiers — the SAME delta the normal-play path uses, so
    // Smuggle correctly applies the Qi'ra surcharge, passive field/subject taxes, and every "next X costs N
    // less" discount instead of dodging them. Signed (a surcharge raises the cost). The used-flag bucket is
    // OFF until Phase 3 wires its Smuggle consume (no double-dip). Host unknown here (a smuggled upgrade
    // picks its host AFTER payment), so pass null → best-case host-conditional discount, as on the
    // normal-play affordability path. Charges consumed AFTER the play commits, below.
    $totalCost = max(0, $totalCost + _SWUPlayCostModifierDelta($player, $resourceObj, null, true));
    // JTL_105 The Starhawk — "While paying costs, you pay half as many resources, rounded up." Smuggle is a
    // cost paid to play a card, so it halves too — applied AFTER all reductions (aspect penalty, Lando -2,
    // shared delta).
    $totalCost = SWUApplyCostHalving($player, $totalCost);

    // A smuggled UPGRADE (SHD_174 / SHD_175) needs a valid host BEFORE anything is paid — an
    // upgrade with nowhere to attach can't be played at all.
    $isUpgrade = stripos(CardType($cardID) ?? '', 'Upgrade') !== false;
    if ($isUpgrade && empty(SWUGetUpgradeValidTargets($player, $cardID))) {
        SetFlashMessage("No valid unit to attach that upgrade to.");
        $playerID = $savedPID;
        return;
    }

    // Smuggle ADDITIONAL cost — SHD_036 First Light: "deal 4 damage to a friendly unit". This is a COST,
    // not an effect: it must be PAYABLE for the play to be legal at all, so with no friendly unit to
    // damage the card simply cannot be smuggled. Gated BEFORE anything is spent, exactly like the
    // upgrade-host gate above. The targets are snapshotted HERE, before the smuggled card enters play,
    // because the card paying the cost is not yet a friendly unit and so cannot pay with itself.
    global $smuggleAdditionalDamageCost;
    $addCostDmg     = intval($smuggleAdditionalDamageCost[$cardID] ?? 0);
    $addCostTargets = [];
    if ($addCostDmg > 0) {
        $addCostTargets = array_merge(ZoneSearch("myGroundArena", AnyUnitFilter),
                                      ZoneSearch("mySpaceArena",  AnyUnitFilter));
        if (empty($addCostTargets)) {
            SetFlashMessage("You must be able to deal {$addCostDmg} damage to a friendly unit to play that card.");
            $playerID = $savedPID;
            return;
        }
    }

    // CR 8.22.e: the card can exhaust itself toward payment while still in resources.
    //
    // This used to lean on "SWUExhaustResources exhausts ready resources in order, so it naturally
    // includes the card" — which only holds when the smuggled card is among the LOWEST-INDEX ready
    // resources. Every existing Smuggle case places it at index 0, so the gap stayed hidden: a card
    // further down the zone was never the one spent, and the player paid its full cost out of OTHER
    // resources AND still lost the card. Same defect as Plot (bug #925), same root cause.
    //
    // Spend it explicitly and ask the sweep for the REMAINDER. Done here rather than by reordering the
    // zone (the fix Plot uses) because Smuggle pays INLINE and $actualIdx is still needed afterwards for
    // removal and slot replacement — reordering would invalidate it. An already-exhausted resource pays
    // nothing, so the full cost then correctly comes from elsewhere.
    $smuggleSelfPaid = 0;
    if (intval($resourceObj->Status ?? 0) === 1) { $resourceObj->Status = 0; $smuggleSelfPaid = 1; }

    // Smuggle is a cost paid to PLAY a card, so a Credit token may be defeated to pay 1 less (CR 3.13)
    // and a SEC_122 Droid may be exhausted for it. The offer is made BEFORE this commit point (the code
    // below depends on $actualIdx / $resourceObj, which cannot survive a decision boundary), then this
    // function re-enters with the chosen $prepaid. Only the scalar (index, discount) crosses the
    // boundary — it rides the CUSTOM decision's own Param, so it survives the request boundary.
    $remaining = max(0, $totalCost - $smuggleSelfPaid);
    if ($prepaid < 0) {
        $prepaid = 0;
        if ($remaining > 0 && (!empty(SWUUsableCreditTokenMzIDs($player)) || SWUPlayerControlsSEC122($player))) {
            $resourceObj->Status = 1; // undo the self-payment; the re-entry redoes it
            SWUOfferAltPayment($player, $remaining, 'SMUGGLE_PAY',
                "{$resourceIdx}|{$discount}|" . ($deferHandler ?? ''), 1);
            return; // $playerID intentionally left = $player when the funnel queued a decision
        }
    }
    $exhaustOk = SWUExhaustResources($player, max(0, $remaining - $prepaid));
    if (!$exhaustOk) {
        // Roll the self-payment back: nothing is spent on a failed play (the card stays playable).
        if ($smuggleSelfPaid) $resourceObj->Status = 1;
        SetFlashMessage("Not enough ready resources (need {$totalCost}).");
        $playerID = $savedPID;
        return;
    }

    // Play committed: spend the one-shot "next X costs N less" charges the shared delta applied (Smuggle
    // bypasses ActivateCard, where a normal play would consume them). Same table-driven consume the normal
    // path uses, so the two can never diverge. No-op when no discount was armed.
    _SWUConsumeOneShotCharges($player, $resourceObj, null);
    // JTL_260 Death Star Plans: mark the once-per-round "first unit costs 2 less" discount used (it is in
    // the always-included peek bucket but not the one-shot table — its consume is a _USED flag). Mirrors
    // ActivateCard's JTL_260 block so a smuggled first unit spends the charge (preserved from the prior
    // _SWUSmugglePlayDiscount behavior).
    if (_SWUObjIsUnit($resourceObj)
            && GlobalEffectCount(intval($player), 'SWU_JTL260_USED') <= 0) {
        AddGlobalEffects(intval($player), 'SWU_JTL260_USED');
    }
    // Phase 3: a smuggled unit spends the JTL_032 Krennic / LOF_108 Malakili "first slot" just like a
    // normal unit play (mirrors ActivateCard's unit branch), so the used-flag-bucket discounts the shared
    // delta now applies to Smuggle are consumed and can't be double-dipped by a later normal play.
    _SWUMarkUnitPlayUsedFlags($player, $cardID);

    AddGlobalEffects(intval($player), 'SWU_CARDS_PLAYED');  // playing via Smuggle counts

    // UPGRADE smuggle branch (SHD_174 / SHD_175): attach to a chosen host instead of entering an
    // arena. Cost is already paid; the SMUGGLE_ATTACH continuation removes the resource entry,
    // attaches (ignoreCost), replaces the spent slot from the deck (CR 8.22.g), and fires the
    // "When played using Smuggle" closure with the HOST mz. $playerID stays = $player for the
    // queued host-choice validation (deliberately no restore on this path).
    if ($isUpgrade) {
        $hosts = SWUGetUpgradeValidTargets($player, $cardID);
        SWUQueueChooseTarget(intval($player), $hosts,
            "Choose_a_unit_to_attach_" . str_replace(' ', '_', CardTitle($cardID) ?? 'the_upgrade') . "_to",
            "SMUGGLE_ATTACH|{$cardID}|{$actualIdx}");
        return;
    }

    // EVENT smuggle branch. An event has no arena to enter: it must go to the discard and run the full
    // event ceremony (Saw Gerrera / Adi Gallia taxes, alt-cost, the When-Played dispatch, the played-event
    // observers). That ceremony lives in ActivateCard, so DELEGATE rather than re-implement it — exactly
    // as the $isUpgrade branch above delegates, and as Plot does via PLOT_PAY.
    // Without this the event fell through to the unit path below and was ADDED TO AN ARENA as a bogus
    // unit: its effect never resolved and it never reached the discard.
    // Cost is already fully paid here, hence ignoreCost=true.
    // ⚠ CR 8.22.g — the slot replacement runs BEFORE the event's ability, not after. "As it enters play,
    // a card played using Smuggle is replaced in the resource zone by the top card of a player's deck.
    // The two cards are considered to enter play SIMULTANEOUSLY." The ability resolves after the card is
    // played, so it must not be able to change which card refills the slot. Running the replacement
    // afterwards made a deck-manipulating smuggled event refill from the WRONG card (Commission peeks the
    // top 10, so a 12-card deck refilled from card 11) — and with a deck shorter than the peek the whole
    // deck was gone by then, so the slot was NEVER refilled and the player permanently lost a resource.
    // The new resource appends to the END of the zone, so $actualIdx still addresses the smuggled card
    // for the ActivateCard call below. Deck empty => no replacement and no base damage (CR 8.22.h).
    if (stripos(CardType($cardID) ?? '', 'Event') !== false) {
        $deckE = &GetDeck($player);
        for ($i = 0; $i < count($deckE); $i++) {
            if (isset($deckE[$i]->removed) && $deckE[$i]->removed) continue;
            $topE = $deckE[$i]->CardID;
            $deckE[$i]->Remove();
            AddResources($player, $topE, 0, $player, $player); // Status 0 = exhausted
            break;
        }
        // Thread the resource's OWNER. A spent event goes to its OWNER's discard, and ActivateCard's
        // discard line is already owner-correct — but its $owner parameter DEFAULTS to the acting
        // player, so a foreign-owned smuggled event (a resource you control but an opponent owns) was
        // filed under the caster. The from-hand play and the smuggled UNIT path both got this right,
        // which is why only this branch was wrong.
        $evOwner = intval($resourceObj->Owner ?? $player);
        if ($evOwner <= 0) $evOwner = intval($player);
        ActivateCard($player, "myResources-{$actualIdx}", true, 0, 0, $evOwner);
        return; // $playerID intentionally left = $player for any decision ActivateCard queued
    }

    // Remove card from resources zone (it has now been exhausted above).
    $resources[$actualIdx]->Remove();

    // CR 8.22.g: replace the slot with the top card of the deck (enters exhausted).
    // If deck is empty, no replacement and no base damage (CR 8.22.h).
    $deck = &GetDeck($player);
    for ($i = 0; $i < count($deck); $i++) {
        if (isset($deck[$i]->removed) && $deck[$i]->removed) continue;
        $topCardID = $deck[$i]->CardID;
        $deck[$i]->Remove();
        AddResources($player, $topCardID, 0, $player, $player); // Status 0 = exhausted
        break;
    }

    // CR 8.22.f: unit enters play exhausted.
    $targetArena = CardTargetArena($cardID);
    $uid = NextUniqueID();
    if ($targetArena === 'SpaceArena') {
        $newCard = AddSpaceArena($player, CardID:$cardID, Status:0,
            Owner:$player, Damage:0, Controller:$player, UniqueID:$uid);
    } else {
        $newCard = AddGroundArena($player, CardID:$cardID, Status:0,
            Owner:$player, Damage:0, Controller:$player, UniqueID:$uid);
    }

    // CR 8.22.f: WhenPlayed and other entry triggers fire just as for normal play.
    $newCardMzID = $newCard->GetMzID();

    // SHD_017 Lando — defer the entry triggers so the "defeat a resource you own and control" cost resolves
    // AFTER the Smuggled card's slot is replaced (above) but BEFORE its When Played abilities (CR ordering:
    // a leader ability's effects resolve in sequence). The deferHandler owns firing the entry triggers.
    if ($deferHandler !== null) {
        // ⚠ The payload rides the decision PARAM, not a transient global. It used to be parked in
        // $GLOBALS['gSmuggleDeferred'] and read back after the deferHandler's own INTERACTIVE decision
        // (Lando's "defeat a resource you own and control"). The harness runs one process so it survived
        // there, but PRODUCTION starts a fresh process on every answer — so the global was gone and the
        // smuggled card's WHEN PLAYED NEVER FIRED in a real game. Identical shape to the JTL_094
        // pilot-replacement disappearance. Only scalars cross, and the unit is carried by UniqueID
        // because an arena mzID can reindex before the continuation runs.
        DecisionQueueController::AddDecision($player, 'CUSTOM',
            $deferHandler . '|' . intval($player) . '|' . $cardID . '|' . intval($uid) . '|' . $targetArena, 1);
        $playerID = $savedPID;
        return;
    }

    // Pay the Smuggle ADDITIONAL cost (SHD_036: "deal 4 damage to a friendly unit"). Queued against the
    // pre-placement snapshot, so the card that just arrived cannot be chosen to pay its own cost. The
    // damage runs through the normal funnel, so a Shield absorbs it — and the cost still counts as PAID,
    // because paying a cost is not the same as the damage landing.
    if ($addCostDmg > 0 && !empty($addCostTargets)) {
        SWUQueueChooseTarget($player, $addCostTargets,
            "Deal_{$addCostDmg}_damage_to_a_friendly_unit_(Smuggle_cost)", "DEAL_UNIT_DAMAGE|{$addCostDmg}");
    }

    _SWUSmuggleFireEntry($player, $cardID, $newCardMzID, $targetArena);
    $playerID = $savedPID;
}

// Fire a Smuggled unit's entry triggers — the "When played using Smuggle" closure (SHD_113/148/174/213),
// the SHD_005 Hondo observer, and the generic WhenPlayed/Ambush/Shielded entry bag. Extracted so SHD_017
// Lando can DEFER it until after its resource-defeat cost resolves. Owns the after-action.
function _SWUSmuggleFireEntry(int $player, string $cardID, string $newCardMzID, string $targetArena): void {
    global $playerID, $whenPlayedUsingSmuggleAbilities;
    $playerID = intval($player);
    _SWUSec008HealOnResourcePlay($player);   // SEC_008 Bail Organa — "play a card from your resources"
    if (isset($whenPlayedUsingSmuggleAbilities["{$cardID}:0"])) {
        $whenPlayedUsingSmuggleAbilities["{$cardID}:0"]($player, $newCardMzID);
    }
    // SHD_005 Hondo fires on BOTH sides. Front: "you may EXHAUST this leader; if you do, give an
    // Experience token" (needs him ready+undeployed to pay). Deployed: "you may give an Experience
    // token" — NO cost, so readiness is irrelevant and the undeployed gate must not apply.
    // The deployed arm was missing entirely, so a deployed Hondo never reacted to Smuggle at all.
    if (_SWULeaderReadyUndeployed($player, 'SHD_005') || _SWULeaderDeployed($player, 'SHD_005')) {
        AddTrigger($player, 'SHD_005', 'SHD_005', '');
    }
    // Stamp "this unit entered play via Smuggle" on the entering object, keyed by UniqueID. The generic
    // entry bag below only BAGS its triggers — they resolve later, possibly across a request boundary —
    // so a transient variable would be gone by the time a When Played closure runs. TS26_34 Fives needs
    // this: he can copy a "When played using Smuggle" ability, which may only fire if HE too was smuggled.
    $_smUnit = GetZoneObject($newCardMzID);
    $_smUID  = ($_smUnit !== null) ? intval($_smUnit->UniqueID ?? 0) : 0;
    if ($_smUID > 0) AddGlobalEffects($player, 'SWU_SMUGGLED_' . $_smUID);
    $triggered = CollectEntryTriggers($player, $cardID, $newCardMzID, $targetArena);
    // LOF_197 Qui-Gon Jinn's Aethersprite — a SMUGGLED card's When-Played ability also counts as "a When
    // Played ability you use this phase"; this path fires $whenPlayedUsingSmuggleAbilities directly (never
    // OnWhenPlayed), so the repeat arm was previously never consumed here. Consume it and offer to re-use
    // the smuggle When-Played ability. If there are no other entry triggers, the repeat owns the After Action.
    $repeatQueued = false;
    if (isset($whenPlayedUsingSmuggleAbilities["{$cardID}:0"])
            && GlobalEffectCount($player, 'SWU_LOF197_REPEAT') > 0) {
        RemoveGlobalEffect($player, 'SWU_LOF197_REPEAT');
        $ownsAA = ($triggered === 0) ? 1 : 0;
        DecisionQueueController::AddDecision($player, "YESNO", "-", 1,
            tooltip: "Use_that_When_Played_ability_again_(Qui-Gon's_Aethersprite)?");
        DecisionQueueController::AddDecision($player, "CUSTOM",
            "LOF_197#1|{$cardID}|{$newCardMzID}|{$ownsAA}", 1);
        $repeatQueued = true;
    }
    if ($triggered === 0 && !$repeatQueued) {
        DecisionQueueController::CleanupRemovedCards();
        SWUAfterAction($player);
    }
}
// LOF_197 repeat of a smuggled card's When-Played ability (re-dispatch the same smuggle ability on the same
// unit). $parts[2]=1 → this repeat owns the After Action (no separate entry trigger did).
$customDQHandlers["LOF_197#1"] = function($player, $parts, $lastDecision) {
    global $playerID, $whenPlayedUsingSmuggleAbilities; $playerID = intval($player);
    $cardID = $parts[0] ?? ''; $mzID = $parts[1] ?? ''; $ownsAA = !empty($parts[2] ?? 0);
    if ($lastDecision === 'YES' && $cardID !== '' && $mzID !== ''
            && isset($whenPlayedUsingSmuggleAbilities["{$cardID}:0"])) {
        $whenPlayedUsingSmuggleAbilities["{$cardID}:0"](intval($player), $mzID);
    }
    if ($ownsAA) { DecisionQueueController::CleanupRemovedCards(); SWUAfterAction(intval($player)); }
};

// SHD_038 Brutal Traditions — an Upgrade whose "Action: If an enemy unit was defeated this phase, play
// this upgrade from your discard pile (paying its cost)." Unlike LAW_200/SHD_135 (which stamp TPP at
// discard time via cardDiscardedHandlers), SHD_038's condition can become true AFTER it's already in the
// discard pile, so its effective play-from-discard modifier is computed LIVE: TPP whenever an enemy unit
// was defeated this phase (the SWU_ENEMY_DEFEATED flag, cleared at RegroupPhaseStart).
function _SWUEffectiveDiscardModifier(int $player, object $entry): string {
    $mod = $entry->Modifier ?? '';
    if ($mod === '' && ($entry->CardID ?? '') === 'SHD_038'
        && GlobalEffectCount($player, 'SWU_ENEMY_DEFEATED') > 0) {
        return 'TPP';
    }
    return $mod;
}

function SWUPlayFromDiscard(int $player, int $discardIdx): void {
    global $playerID;
    $savedPID = $playerID;
    $playerID = $player;

    $discard  = &GetDiscard($player);
    $actualIdx = -1;
    $count = 0;
    for ($i = 0; $i < count($discard); $i++) {
        if (isset($discard[$i]->removed) && $discard[$i]->removed) continue;
        if ($count === $discardIdx) { $actualIdx = $i; break; }
        $count++;
    }
    if ($actualIdx === -1) {
        SetFlashMessage("Invalid discard index.");
        $playerID = $savedPID;
        return;
    }

    $entry    = $discard[$actualIdx];
    $cardID   = $entry->CardID;
    $modifier = _SWUEffectiveDiscardModifier($player, $entry);

    // 'TPP2' = "this phase you may play this from your discard, and it costs 2 resources less"
    // (TWI_201 Aid from the Innocent). Decode it into the plain at-cost modifier plus a discount so the
    // gate, the cost charge and the upgrade path all deal with one shape.
    $playDiscount = 0;
    if ($modifier === 'TPP2') { $modifier = 'TPP'; $playDiscount = 2; }

    if ($modifier !== 'TPF' && $modifier !== 'TPP') {
        SetFlashMessage("That card cannot be played from discard this phase.");
        $playerID = $savedPID;
        return;
    }

    // SOR_062 Regional Governor: an opponent's named card can't be played, including from discard.
    if (SWUCardPlayBlocked(intval($player), $cardID)) {
        SetFlashMessage("That card can't be played (named by an opponent).");
        $playerID = $savedPID;
        return;
    }

    // Upgrades (LAW_200 Salvaged Blaster) attach to a host — route through ActivateCard, which offers the
    // host choice and pays/removes the upgrade via ATTACH_UPGRADE. TPF → free (ignoreCost); TPP → at cost.
    // On a failed attach (no valid host / unaffordable) the upgrade stays in discard with its modifier.
    // Upgrades (LAW_200 Salvaged Blaster) and EVENTS (TWI_201 Aid from the Innocent discards Heroism
    // NON-UNIT cards, i.e. events and upgrades) both route through ActivateCard, which charges the cost,
    // resolves the card and returns an event to the discard. Only a UNIT may use the inline arena
    // placement below — sending an event down it drops the event card into an arena as a bogus 0/0 unit
    // and its ability never resolves.
    $isEvent = strpos(CardType($cardID), 'Event') !== false;
    if ($isEvent || strpos(CardType($cardID), 'Upgrade') !== false) {
        ActivateCard($player, "myDiscard-{$actualIdx}", $modifier === 'TPF', $playDiscount);
        // Events: this input path does not auto-drain, so flush the queued block-1 effect decisions and
        // the FINISH_PLAY_CARD terminator inline (mirrors SWUPlayFromOpponentDiscard).
        if ($isEvent) (new DecisionQueueController())->ExecuteStaticMethods(intval($player), "-");
        $playerID = $savedPID;
        return;
    }

    // Piloting (official ruling, 2025-03-06): the permission is to "play THAT CARD", not "play that
    // unit", so a Piloting unit in your own discard may also be played as a Pilot UPGRADE on a friendly
    // Vehicle. The hand path gets this fork from SWUBeginPlayCard and the FOREIGN-discard path has its
    // own mirror; this path placed units inline and so never offered the choice at all.
    // TPF is "play for FREE", which ignores ALL resource costs including the aspect penalty (ruling
    // 2024-07-16) — and that applies to the PILOT cost too, so a free pilot play costs 0 no matter what
    // its Piloting cost is. Expressed as SWU_PILOT_DISCOUNT stacks because SWUComputePilotCost is the
    // single chokepoint used by BOTH the affordability gate (SWUGetPilotValidTargets) and the charge
    // (_SWUFinalizeUpgradeAttach), so the offer and the payment can't disagree.
    $entryObjForPilot = (object) ['CardID' => $cardID, 'TurnEffects' => []];
    if (HasKeyword_Piloting($entryObjForPilot) && !_SWUGalenSuppressesCard(intval($player), $cardID)) {
        $freeWaiver = ($modifier === 'TPF')
            ? max(0, intval(CardPilotingCost($cardID))) + SWUAspectPenalty($player, $cardID) : 0;
        for ($k = 0; $k < $freeWaiver; $k++) AddGlobalEffects(intval($player), 'SWU_PILOT_DISCOUNT');
        $vehicles = SWUGetPilotValidTargets(intval($player), $cardID);
        if (!empty($vehicles)) {
            $ready = 0;
            foreach (GetResources($player) as $r) {
                if (SWUIsCreditToken($r->CardID ?? '')) continue;
                if (empty($r->removed) && intval($r->Status) === 1) $ready++;
            }
            $unitCost = ($modifier === 'TPF') ? 0
                : max(0, intval(CardCost($cardID)) + SWUAspectPenalty($player, $cardID) - $playDiscount);
            if ($modifier === 'TPF' || $ready >= $unitCost) {
                DecisionQueueController::AddDecision($player, "OPTIONCHOOSE",
                    "Unit&Pilot", 1, tooltip:"Play_as_Unit_or_Pilot?");
                DecisionQueueController::AddDecision($player, "CUSTOM",
                    "OWN_DISCARD_PILOT_CHOICE|{$actualIdx}|{$cardID}|{$modifier}|{$playDiscount}", 1);
                $playerID = $savedPID;
                return;
            }
            // Can't afford the unit cost — the Pilot route is the only one left.
            AddGlobalEffects(intval($player), 'SWU_CARDS_PLAYED');
            SWUQueuePilotVehiclePick(intval($player), "myDiscard-{$actualIdx}", $cardID, $vehicles);
            $playerID = $savedPID;
            return;
        }
        // No legal Vehicle host — the pilot waiver must not leak into the unit play below.
        for ($k = 0; $k < $freeWaiver; $k++) RemoveGlobalEffect(intval($player), 'SWU_PILOT_DISCOUNT');
    }

    _SWUOwnDiscardPlayAsUnit($player, $actualIdx, $cardID, $modifier, $playDiscount);
    $playerID = $savedPID;
}

// The UNIT half of an own-discard play (cost, arena placement, entry triggers), split out so the
// Unit-vs-Pilot fork's "Unit" branch can re-enter it without re-running the fork.
// $actualIdx is the RAW discard index — the same one the "myDiscard-N" mzIDs use, not the visible one.
function _SWUOwnDiscardPlayAsUnit(int $player, int $actualIdx, string $cardID, string $modifier,
                                  int $playDiscount = 0): void {
    global $playerID;
    $savedPID = $playerID;
    $playerID = $player;
    $discard  = &GetDiscard($player);
    $entry    = $discard[$actualIdx] ?? null;
    if ($entry === null || !empty($entry->removed)) { $playerID = $savedPID; return; }

    if ($modifier === 'TPP') {
        $cost = max(0, intval(CardCost($cardID)) + SWUAspectPenalty($player, $cardID) - $playDiscount);
        if (!SWUPayInlineAbilityCost($player, $cost)) {
            SetFlashMessage("Not enough ready resources.");
            $playerID = $savedPID;
            return;
        }
        // Task 5.1: stamp resources paid for TWI_210 observer (at-cost play = full cost paid).
        $GLOBALS['gLastPlayResourcesPaid'] = $cost;
    } else {
        // TPF = free play from discard (e.g. The Power of the Force) → 0 resources paid.
        $GLOBALS['gLastPlayResourcesPaid'] = 0;
    }

    AddGlobalEffects(intval($player), 'SWU_CARDS_PLAYED');  // playing from discard counts
    $entry->removed = true;
    $targetArena = CardTargetArena($cardID);
    $uid = NextUniqueID();
    if ($targetArena === 'SpaceArena') {
        $newCard = AddSpaceArena($player, CardID:$cardID, Status:0,
            Owner:$player, Damage:0, Controller:$player, UniqueID:$uid);
    } else {
        $newCard = AddGroundArena($player, CardID:$cardID, Status:0,
            Owner:$player, Damage:0, Controller:$player, UniqueID:$uid);
    }
    $newCardMzID = $newCard->GetMzID();

    global $gPendingEntryEffects;
    if (isset($gPendingEntryEffects[$uid])) {
        foreach ($gPendingEntryEffects[$uid] as $effect) {
            AddTurnEffect($newCardMzID, $effect);
        }
        unset($gPendingEntryEffects[$uid]);
    }

    SWUApplyPassiveEntryGrants($player, $cardID, $newCardMzID);
    $triggered = CollectEntryTriggers($player, $cardID, $newCardMzID, $targetArena);
    if ($triggered === 0) {
        DecisionQueueController::CleanupRemovedCards();
        SWUAfterAction($player);
    }

    $playerID = $savedPID;
}

// SWUPlayDiscardUnitDiscounted was retired — all discard discount-plays now route
// through the canonical ActivateCard($player, $discardMzID, false, $discount), which
// runs the full cost pipeline and reports the placed unit via $GLOBALS['gLastPlayedMzID'].

function SWUPlayFromOpponentDiscard(int $player, int $discardIdx): void {
    global $playerID;
    $savedPID = $playerID;
    $playerID = $player;

    $opponent  = OtherPlayer($player);
    $discard   = &GetDiscard($opponent);
    $actualIdx = -1;
    $count = 0;
    for ($i = 0; $i < count($discard); $i++) {
        if (isset($discard[$i]->removed) && $discard[$i]->removed) continue;
        if ($count === $discardIdx) { $actualIdx = $i; break; }
        $count++;
    }
    if ($actualIdx === -1) {
        SetFlashMessage("Invalid discard index.");
        $playerID = $savedPID;
        return;
    }

    $entry    = $discard[$actualIdx];
    $cardID   = $entry->CardID;
    $modifier = $entry->Modifier ?? '';

    if ($modifier !== 'OTPF' && $modifier !== 'OTPP' && $modifier !== 'OTPN') {
        SetFlashMessage("That card cannot be played from opponent's discard this phase.");
        $playerID = $savedPID;
        return;
    }

    // SOR_062 Regional Governor: an opponent's named card can't be played, including from a discard.
    if (SWUCardPlayBlocked(intval($player), $cardID)) {
        SetFlashMessage("That card can't be played (named by an opponent).");
        $playerID = $savedPID;
        return;
    }

    // Piloting: the permission is to "play THAT CARD", not "play that unit" — so a milled card with the
    // Piloting keyword may also be played as an upgrade on a friendly Vehicle, at its Piloting cost. The
    // hand path gets this from SWUBeginPlayCard; this path calls ActivateCard directly, so mirror the
    // Unit-vs-Pilot fork here. OTPN's "ignoring aspect penalties" is expressed by pre-loading the penalty
    // as SWU_PILOT_DISCOUNT stacks — SWUComputePilotCost is the single chokepoint used by BOTH the
    // affordability gate (SWUGetPilotValidTargets) and the charge, so the two stay consistent.
    $entryObjForPilot = (object) ['CardID' => $cardID, 'TurnEffects' => []];
    if (HasKeyword_Piloting($entryObjForPilot) && !_SWUGalenSuppressesCard(intval($player), $cardID)) {
        $penaltyWaiver = ($modifier === 'OTPN') ? SWUAspectPenalty($player, $cardID) : 0;
        for ($k = 0; $k < $penaltyWaiver; $k++) AddGlobalEffects(intval($player), 'SWU_PILOT_DISCOUNT');
        $vehicles = SWUGetPilotValidTargets(intval($player), $cardID);
        if (!empty($vehicles)) {
            $ready = 0;
            foreach (GetResources($player) as $r) {
                if (SWUIsCreditToken($r->CardID ?? '')) continue;
                if (empty($r->removed) && intval($r->Status) === 1) $ready++;
            }
            $unitCost = intval(CardCost($cardID))
                        + ($modifier === 'OTPN' ? 0 : SWUAspectPenalty($player, $cardID));
            $canUnit  = ($modifier === 'OTPF') || $ready >= $unitCost;
            if ($canUnit) {
                DecisionQueueController::AddDecision($player, "OPTIONCHOOSE",
                    "Unit&Pilot", 1, tooltip:"Play_as_Unit_or_Pilot?");
                DecisionQueueController::AddDecision($player, "CUSTOM",
                    "FOREIGN_PILOT_PLAY_CHOICE|{$actualIdx}|{$cardID}|{$modifier}|{$opponent}", 1);
                $playerID = $savedPID;
                return;
            }
            // Can't afford the unit cost — the Pilot route is the only one left.
            AddGlobalEffects(intval($player), 'SWU_CARDS_PLAYED');
            SWUQueuePilotVehiclePick(intval($player), "theirDiscard-{$actualIdx}", $cardID,
                $vehicles, $opponent);
            $playerID = $savedPID;
            return;
        }
        // No legal Vehicle host — the pilot discount must not leak into the unit play below.
        for ($k = 0; $k < $penaltyWaiver; $k++) RemoveGlobalEffect(intval($player), 'SWU_PILOT_DISCOUNT');
    }

    AddGlobalEffects(intval($player), 'SWU_CARDS_PLAYED');  // playing from opponent's discard counts
    _SWUForeignDiscardPlayAsUnit(intval($player), $actualIdx, $cardID, $modifier, $opponent);
    $playerID = $savedPID;
}

// The UNIT/event route of a play from an opponent's discard: charge the OTPF/OTPP/OTPN cost and hand the
// card to ActivateCard. Split out of SWUPlayFromOpponentDiscard so the Unit answer to the Unit-vs-Pilot
// fork (FOREIGN_PILOT_PLAY_CHOICE) can re-enter exactly the same path.
function _SWUForeignDiscardPlayAsUnit(int $player, int $actualIdx, string $cardID, string $modifier,
                                      int $opponent): void {
    global $playerID;
    $savedPID = $playerID;
    $playerID = $player;
    $cost = 0;
    if ($modifier === 'OTPP' || $modifier === 'OTPN') {
        // OTPP = at cost (with aspect penalty); OTPN = at cost, IGNORING aspect penalties (SEC_205).
        $cost = intval(CardCost($cardID)) + ($modifier === 'OTPN' ? 0 : SWUAspectPenalty($player, $cardID));
        if (!SWUPayInlineAbilityCost($player, $cost)) {
            SetFlashMessage("Not enough ready resources.");
            $playerID = $savedPID;
            return;
        }
        // Task 5.1: stamp resources paid for TWI_210 observer (at-cost play = full cost paid).
        $GLOBALS['gLastPlayResourcesPaid'] = $cost;
    } else {
        // OTPF = free play from opponent's discard → 0 resources paid.
        $GLOBALS['gLastPlayResourcesPaid'] = 0;
    }

    // Delegate to the single play path (ActivateCard). It removes the source discard entry itself, routes
    // an event to the OWNER's (opponent's) discard and a unit to Owner=opponent/Controller=caster, and
    // applies every play-time effect (Saw Gerrera SOR_153 / Adi Gallia LOF_142 / Relentless SOR_089 /
    // TWI_210 / telemetry) — which the old hand-rolled branches skipped. The special OTPF/OTPP/OTPN cost
    // was already charged above; pass it as prepaid (ignoreCost for a free OTPF play) so ActivateCard does
    // not recompute or double-charge. Do NOT pre-remove $entry — ActivateCard reads it via GetZoneObject.
    // The caller ALREADY settled cost (OTPP/OTPN charged $cost above with the correct aspect-penalty rule;
    // OTPF is free), so ActivateCard must NOT recompute it — always ignoreCost, and pass the charged amount
    // as prepaid so $gLastPlayResourcesPaid (TWI_210) reflects it. Recomputing would re-apply the aspect
    // penalty OTPN is meant to ignore and wrongly fail the play.
    $foreignPrepaid = ($modifier === 'OTPF') ? 0 : $cost;
    ActivateCard(intval($player), "theirDiscard-{$actualIdx}", 1, 0, $foreignPrepaid, $opponent);
    // EVENTS only: this input path does not auto-drain, so flush the queued block-1 effect decisions +
    // the FINISH_PLAY_CARD terminator inline (as the old event branch did). A UNIT's When Played decisions
    // (e.g. JTL_047 Yularen's keyword choice) surface via the harness's normal post-input decision pickup,
    // so draining them here would prematurely consume the play-confirmation step and desync answers.
    if (strpos(CardType($cardID) ?? '', 'Event') !== false) {
        (new DecisionQueueController())->ExecuteStaticMethods(intval($player), "-");
    }
    $playerID = $savedPID;
}

function SWUComputeActionsData(int $player): array {
    global $baseAbilities, $baseActionNumUses, $baseActionRepeatable;

    $isMain   = (GetCurrentPhase() === 'MAIN');
    $isMyTurn = (intval(GetTurnPlayer()) === $player);
    $dq       = new DecisionQueueController();
    $dqEmpty  = $dq->AllQueuesEmpty();
    $active   = $isMain && $isMyTurn && $dqEmpty;

    $data = [
        'leaderAbility'       => false,
        'leaderDeploy'        => false,
        'baseEpic'            => false,
        'unitActions'         => [],
        'attackers'           => [],
        'smugglableResources' => [],
        'readyResources'      => 0,
        // Twin Suns (Phase 4 counters). Inert in premier (SeatCountForGame() <= 2): all false/[].
        'blastAvailable'      => false,
        'planAvailable'       => false,
        'counterTaken'        => false,
        'roundState'          => [],
    ];

    // Twin Suns counter availability — computed regardless of $active so both HUDs can render the state.
    if (SeatCountForGame() > 2) {
        $tookCounter = _SWUSeatTookCounterThisRound($player);
        $data['counterTaken']   = $tookCounter;
        $data['blastAvailable'] = !$tookCounter && (GetBlastCounter() === 'AVAILABLE');
        $data['planAvailable']  = !$tookCounter && (GetPlanCounter() === 'AVAILABLE');
        $turnSeat = intval(GetTurnPlayer());
        foreach (GetLiveSeatsArray() as $seat) {
            if (_SWUSeatTookCounterThisRound($seat)) $data['roundState'][$seat] = 'took-counter';
            elseif ($seat === $turnSeat)             $data['roundState'][$seat] = 'active';
            else                                     $data['roundState'][$seat] = 'waiting';
        }
    }

    if (!$active) return $data;

    // Leader
    // Twin Suns: a seat can hold two leaders, each with its own glow state. Compute per live-leader
    // index; the back-compat scalar keys mirror index 0 so the current single-leader client is unchanged.
    $leaderArr    = &GetLeader($player);
    $abilityByIdx = [];
    $deployByIdx  = [];
    $liveIdx      = 0;
    for ($li = 0; $li < count($leaderArr); $li++) {
        $leaderObj = $leaderArr[$li];
        if (isset($leaderObj->removed) && $leaderObj->removed) continue;
        $ready    = (bool)($leaderObj->Ready ?? false);
        $deployed = (bool)($leaderObj->Deployed ?? false);
        $epicUsed = (bool)($leaderObj->EpicActionUsed ?? false);
        $cid      = $leaderObj->CardID ?? '';
        // TWI_017 "Flipatine" has an activated Action on BOTH faces (its "Deployed" state is the flipped
        // Villainy face, not a unit deploy), so its glow isn't gated on !deployed.
        $abilityByIdx[$liveIdx] = $ready && (!$deployed || $cid === 'TWI_017')
            && SWULeaderActionAffordable($player, $cid);
        if ($cid === 'JTL_014') {
            // Trench: non-epic repeatable deploy — ready, control 6+ resources, 3 ready resources.
            $deployByIdx[$liveIdx] = $ready && !$deployed
                && SWUResourceCount($player) >= 6
                && SWUTotalPaymentCapacity($player) >= 3;
        } elseif ($cid === 'SEC_008') {
            // Bail Organa: non-epic repeatable Action [Exhaust, discard 2 cards from hand]: deploy if you
            // control 4+ resources. Needs the leader ready + 2 cards in hand to discard as the cost.
            $bailHand = 0; foreach (GetHand($player) as $bh) if (empty($bh->removed)) $bailHand++;
            $deployByIdx[$liveIdx] = $ready && !$deployed
                && SWUResourceCount($player) >= 4 && $bailHand >= 2;
        } elseif ($cid === 'TWI_017') {
            // TWI_017 "Flipatine" has NO deploy — both faces are flip Actions (its empty printed cost
            // would otherwise make the generic ">= CardCost" check pass and offer a bogus Deploy option).
            $deployByIdx[$liveIdx] = false;
        } else {
            $deployByIdx[$liveIdx] = !$epicUsed && !$deployed
                && SWUResourceCount($player) >= intval(CardCost($cid));
        }
        $liveIdx++;
    }
    $data['leaderAbilityByIndex'] = $abilityByIdx;
    $data['leaderDeployByIndex']  = $deployByIdx;
    $data['leaderAbility'] = $abilityByIdx[0] ?? false;
    $data['leaderDeploy']  = $deployByIdx[0] ?? false;

    // Base — has an available action if registered in $baseAbilities. Repeatable-action bases
    // (LOF_022) are gated by remaining NumUses; standard epic bases by EpicActionUsed.
    $baseArr = GetBase($player);
    foreach ($baseArr as $b) {
        if (isset($b->removed) && $b->removed) continue;
        $bCardID = $b->CardID ?? '';
        // Any available base Action lights the base — its own Epic and/or a Fortify-upgrade Action
        // (HMW_095). _SWUBaseActionProviders is the same list SWUBaseAction dispatches from, so the glow
        // and the click can't drift.
        $data['baseEpic'] = !empty(_SWUBaseActionProviders($player));
        break; // only one live base per player
    }

    // Unit activated abilities — ready arena units (own or upgrade-granted) with an
    // affordable action. mzIDs are player-relative ("myGroundArena-N").
    global $unitActionCostKind;
    foreach (['GroundArena' => GetGroundArena($player), 'SpaceArena' => GetSpaceArena($player)] as $arenaName => $arr) {
        for ($i = 0; $i < count($arr); $i++) {
            $u = $arr[$i];
            if (SWUObjGone($u)) continue;
            $provider = SWUGetUnitActionProvider($u);
            if ($provider === '') continue;
            // Exhaust-cost actions need a ready unit; 'defeat'-cost actions (SOR_110) may act
            // while exhausted, so don't gate those on Status.
            $costKind = $unitActionCostKind[$provider] ?? 'exhaust';
            if ($costKind === 'exhaust' && intval($u->Status) !== 1) continue;
            $mz = "my{$arenaName}-{$i}";
            if (SWUUnitActionAffordable($player, $mz, $provider)) $data['unitActions'][] = $mz;
        }
    }

    // Attacker glow — friendly units that could declare an attack right now (ready + ≥1 valid target).
    // Purely the green "can attack" highlight; the attack itself is the framework unit-click. Set
    // $playerID = $player so SWUGetValidAttackTargets resolves the "their{arena}" frame correctly.
    global $playerID; $savedAtkPID = $playerID; $playerID = $player;
    foreach (['GroundArena' => GetGroundArena($player), 'SpaceArena' => GetSpaceArena($player)] as $arenaName => $arr) {
        for ($i = 0; $i < count($arr); $i++) {
            if (_SWUUnitCanAttackNow($player, $arr[$i], $arenaName)) $data['attackers'][] = "my{$arenaName}-{$i}";
        }
    }
    $playerID = $savedAtkPID;

    // Any-player-usable unit actions (LAW_156 Hunter For Hire) — also surface them on the OPPONENT's
    // units, as "their{Arena}-N" (SWUUnitAction has no controller gate, so the live click resolves).
    global $anyPlayerUnitActions;
    $oppAP = OtherPlayer($player);
    foreach (['GroundArena' => GetGroundArena($oppAP), 'SpaceArena' => GetSpaceArena($oppAP)] as $arenaName => $arr) {
        for ($i = 0; $i < count($arr); $i++) {
            $u = $arr[$i];
            if (SWUObjGone($u)) continue;
            $provider = SWUGetUnitActionProvider($u);
            if ($provider === '' || empty($anyPlayerUnitActions[$provider])) continue;
            $mz = "their{$arenaName}-{$i}";
            if (SWUUnitActionAffordable($player, $mz, $provider)) $data['unitActions'][] = $mz;
        }
    }

    // Resources — two passes: count ready first, then check affordability
    $resources  = GetResources($player);
    $readyCount = 0;
    $allCards   = [];
    $logical    = 0;
    foreach ($resources as $r) {
        if (isset($r->removed) && $r->removed) continue;
        if (SWUIsCreditToken($r->CardID ?? '')) continue; // Credit tokens aren't resources / not smugglable
        if (intval($r->Status) === 1) $readyCount++;
        $allCards[] = ['idx' => $logical, 'cardID' => $r->CardID, 'obj' => $r];
        $logical++;
    }
    $data['readyResources'] = $readyCount;
    foreach ($allCards as $c) {
        $cost = GetEffectiveSmuggleCost($player, $c['cardID']);
        // The gate MUST use the same shared modifier delta as the payment path (SWUSmuggleResource) so the
        // resource is offered iff it is actually affordable — surcharges (Qi'ra) raise the requirement,
        // discounts lower it. Signed; used-flag bucket OFF until Phase 3, matching the payment path.
        if ($cost >= 0) $cost = max(0, $cost + _SWUPlayCostModifierDelta($player, $c['obj'], null, true));
        // JTL_105 The Starhawk halves the paid cost — the affordability gate must use the halved amount so
        // the resource is offered when the player can actually afford the (reduced) Smuggle cost.
        if ($cost >= 0 && $readyCount >= SWUApplyCostHalving($player, $cost)) { // -1 = no Smuggle path for this card
            $data['smugglableResources'][] = $c['idx'];
        }
    }

    $playableDiscards = [];
    $myDiscard = GetDiscard($player);
    $di = 0;
    for ($i = 0; $i < count($myDiscard); $i++) {
        if (isset($myDiscard[$i]->removed) && $myDiscard[$i]->removed) continue;
        $mod = _SWUEffectiveDiscardModifier($player, $myDiscard[$i]);
        $dDisc = 0;
        if ($mod === 'TPP2') { $mod = 'TPP'; $dDisc = 2; }   // TWI_201 — at cost, 2 less
        if ($mod === 'TPF') {
            $playableDiscards[] = ['idx' => $di, 'free' => true];
        } elseif ($mod === 'TPP') {
            $dCost = max(0, intval(CardCost($myDiscard[$i]->CardID))
                            + SWUAspectPenalty($player, $myDiscard[$i]->CardID) - $dDisc);
            if ($readyCount >= $dCost) $playableDiscards[] = ['idx' => $di, 'free' => false];
        }
        $di++;
    }
    $data['playableDiscards'] = $playableDiscards;

    $opponentPlayableDiscards = [];
    $oppPlayer = OtherPlayer($player);
    $oppDiscard = GetDiscard($oppPlayer);
    $odi = 0;
    for ($i = 0; $i < count($oppDiscard); $i++) {
        if (isset($oppDiscard[$i]->removed) && $oppDiscard[$i]->removed) continue;
        $mod = $oppDiscard[$i]->Modifier ?? '';
        if ($mod === 'OTPF') {
            $opponentPlayableDiscards[] = ['idx' => $odi, 'free' => true];
        } elseif ($mod === 'OTPP' || $mod === 'OTPN') {
            // OTPN (SEC_205 Obi-Wan, TS26 Mother Talzin) is "at cost, IGNORING aspect penalties". It was
            // missing from this list, so the card the ability milled was never offered as clickable in the
            // client even though the input handler accepted it — the whole permission was invisible in-game.
            $dCost = intval(CardCost($oppDiscard[$i]->CardID))
                     + ($mod === 'OTPN' ? 0 : SWUAspectPenalty($player, $oppDiscard[$i]->CardID));
            if ($readyCount >= $dCost) $opponentPlayableDiscards[] = ['idx' => $odi, 'free' => false];
        }
        $odi++;
    }
    $data['opponentPlayableDiscards'] = $opponentPlayableDiscards;

    // Hand cards playable via alternate cost (glow even when readyResources < normal cost).
    global $hasAlternateCostCards;
    $alternateCostHand = [];
    $myHand = GetHand($player);
    $hIdx   = 0;
    foreach ($myHand as $h) {
        if (!empty($h->removed)) continue;
        $hID = $h->CardID ?? '';
        if (isset($hasAlternateCostCards[$hID]) && SWUCheckAlternateCost($player, $hID)) {
            $alternateCostHand[] = $hIdx;
        }
        $hIdx++;
    }
    $data['alternateCostHand'] = $alternateCostHand;
    $data['pilotPlayableHand'] = SWUComputePilotPlayableHand($player);

    return $data;
}

// Returns the array of hand indices (0-based, RAW array indices including removed
// tombstones) for cards in $player's hand that are playable via the Piloting upgrade
// path: they have the Piloting keyword AND SWUGetPilotValidTargets returns at least
// one eligible Vehicle.
//
// Index convention: indices match the raw hand array position — the same space used by
// GetZoneObject("myHand-N") and ActionMap/PlayHand. Removed tombstone slots are counted
// (pIdx is incremented on removed entries) so that index N here maps to the same physical
// hand slot as PlayHand:N. Note: the sibling alternateCostHand list in SWUComputeActionsData
// uses a live-only (non-removed) index space — that is a pre-existing discrepancy; do NOT
// change this function to match it.
//
// Unlike SWUComputeActionsData this function has no $active guard — it is safe to call
// outside the normal action window (e.g. from the test assertion layer).
function SWUComputePilotPlayableHand(int $player): array {
    global $playerID;
    $savedPID = $playerID;
    $playerID = $player;      // Prophylactic pin: SWUComputePilotCost and SWUPilotCanAttach
                               // may do their own relative ("my*") zone lookups via $playerID.
                               // Pinning here ensures they resolve under the correct player
                               // when this function is called outside a normal action window.
    $pilotPlayableHand = [];
    $pIdx = 0;
    foreach (GetHand($player) as $h) {
        if (!empty($h->removed)) { $pIdx++; continue; }
        $hID = $h->CardID ?? '';
        if ($hID !== '' && HasKeyword_Piloting($h) && !empty(SWUGetPilotValidTargets($player, $hID))) {
            $pilotPlayableHand[] = $pIdx;
        }
        $pIdx++;
    }
    $playerID = $savedPID;
    return $pilotPlayableHand;
}

// ═══════════════════════════════════════════════════════════════════════════
// End SWU Core Game Logic
// ═══════════════════════════════════════════════════════════════════════════

// --- Additional Activation Costs Registry ---
// Cards that offer an optional extra reserve cost at activation time (Grand Archive rule 1.3).
// Each entry maps a cardID to:
//   'prompt'       => string shown in the YesNo dialog
//   'extraReserve' => int, number of extra handâ†’memory payments
//   'condition'    => callable($player) that returns true if the option should be offered
$additionalActivationCosts = [];

// Append a full-state snapshot to the whole-game, multi-step undo stack (player 1's Versions zone) with
// metadata (acting seat, phase, boundary, revealed-info). The stack IS serialized in the gamestate (the
// Versions zones ride in Gamestate.txt), so the undo history is captured by any bug report and restored
// by loading the gamestate — while GetSerializedZones (the snapshot payload) excludes the Versions zone,
// so snapshots never recursively nest. $boundary: 'action' (default) | 'resource' | 'pregame-step'.
function PushUndoSnapshot($actingSeat, $boundary = 'action', $name = '') {
    global $playerID, $gRandomCounter, $gCurrentPhase;
    $savedPlayerID = $playerID;
    $seat = intval($actingSeat);
    $playerID = $seat;

    // Fold the just-finished action's live reveal flag into ITS snapshot (the current top) before we
    // move on — one file rewrite per revealing action instead of one per draw. (At undo time, the last
    // action's reveal is read live from UNDO_REQUIRES_CONSENT since it isn't stamped yet — see the scan.)
    if (GetSWUVar('UNDO_REQUIRES_CONSENT', 'false') === 'true' && UndoCursor() >= 0) {
        UndoStackSetRevealed(UndoCursor());
    }

    // Reset per-action undo state so every snapshot is born with clean flags.
    // UNDO_BLOCKED flags are intentionally NOT reset here — they're permanent.
    SetSWUVar('UNDO_REQUIRES_CONSENT', 'false');
    SetSWUVar('PENDING_UNDO_FROM', '');
    SetSWUVar('PENDING_UNDO_TARGET', '');
    SetSWUVar('PENDING_BLOCK_PROMPT_FOR', '');
    SetSWUVar('UNDO_DENY_COUNT_' . $seat, '0');
    SetSWUVar('PASS', GetSWUVar('PASS', '0')); // ensure format is key=value

    $payload = Versions::GetSerializedZones() . '<v0>' . $gRandomCounter;
    $record  = UndoRecordBuild($seat, (string)($gCurrentPhase ?? ''), (string)$boundary, 0, (string)$name, $payload);
    UndoStackAppend($record);          // ordinal is implicit (the array index)
    UndoCursorSet(UndoStackCount() - 1);   // the new entry is what the next Undo restores

    $playerID = $savedPlayerID;
}

// Backward-compatible alias — the ~15 existing 'action' call sites keep working unchanged.
function SaveUndoVersion($targetPlayerID, $name = "") {
    PushUndoSnapshot($targetPlayerID, 'action', $name);
}

// The ordinal Undo will restore next. NOT the same as the physical top: the log is append-only, so
// after an undo the entries above the cursor are still present (they are the abandoned branch, and
// stepping back through them is exactly how Undo rewinds a bookmark load).
// Stored in the bookmark sidecar (player 2's Versions zone), NOT in a SWUVar — LoadVersion restores the
// snapshot's $gDecisionQueueVariables, which would clobber a SWUVar cursor. That is the same hazard
// _SWUReapplyUndoBlocks exists to work around; keeping the cursor out of the payload makes it immune
// by construction rather than by re-stamping.
function UndoCursor() {
    return UndoCursorGet();
}

// Restore the exact state stored in a raw payload blob, WITHOUT touching the undo cursor. The stack
// lives in player 1's Versions zone; to restore, append the payload as a TEMPORARY slot at the end,
// LoadVersion from it (reusing the untouched generated 700-line restore body), then drop just that temp
// slot. LoadVersion never touches the Versions zones (the payload excludes them), so both the undo log
// and the bookmark sidecar survive the restore untouched.
function _SWURestoreSerializedPayload(string $payload): void {
    $z = &GetVersions(1);
    $tmpIdx = count($z);
    $z[] = new Versions('0:' . $payload, 'Versions', 1, $tmpIdx);   // payload = raw GetSerializedZones blob
    LoadVersion(1, $tmpIdx);
    $z = &GetVersions(1);                    // re-grab post-restore (defensive; LoadVersion leaves Versions alone)
    array_splice($z, $tmpIdx, 1);            // drop ONLY the temp slot — the log is append-only
}

// Restore the game to undo-stack entry $restoreOrdinal and park the cursor BELOW it, so the next Undo
// targets the entry below. Entries at/above $restoreOrdinal are DELIBERATELY retained: they are the
// branch being abandoned, and Undo must be able to walk back into them.
// Returns false if $restoreOrdinal is out of range.
function LoadUndoSnapshot($restoreOrdinal) {
    $restoreOrdinal = intval($restoreOrdinal);
    $line = UndoStackRead($restoreOrdinal);
    if ($line === null) return false;
    $rec = UndoRecordParse($line);
    _SWURestoreSerializedPayload($rec['payload']);
    UndoCursorSet($restoreOrdinal - 1);
    return true;
}

// ── Undo actions (shared by EngineActionRunner cases 10004/10008/10009 AND the test harness) ─────────
// Kept here (not inline in the Core switch) so the logic is reusable + directly testable. Tasks 8-11
// flesh these out (multi-step target, Undo Phase, the private/public consent scan). Interim behavior
// below = single-step free undo gated on the legacy UNDO_REQUIRES_CONSENT flag.

// Capture / re-apply the permanent per-player undo-block flags across a restore. LoadVersion restores a
// pre-block snapshot's $gDecisionQueueVariables, so the CURRENT blocks must be re-stamped afterwards.
// Seat-count driven, not a 1..2 pair — Twin Suns runs four seats.
function _SWUCaptureUndoBlocks(): array {
    $out = [];
    for ($p = 1; $p <= SeatCountForGame(); $p++) {
        if (GetSWUVar('UNDO_BLOCKED_' . $p, 'false') === 'true') $out[] = $p;
    }
    return $out;
}

function _SWUReapplyUndoBlocks(array $blockedSeats): void {
    foreach ($blockedSeats as $p) SetSWUVar('UNDO_BLOCKED_' . intval($p), 'true');
}

// The snapshot ordinal an undo of the given kind should restore.
//   'step'  — restore the current top (one action / one boundary back; LoadUndoSnapshot then pops).
//   'phase' — jump to the FIRST action of the current phase: the lowest run of contiguous 'action'
//             entries above the most recent non-action boundary ('resource'/'pregame-step'). Restoring
//             it lands at the action-phase start; the pop then leaves the top at that boundary, so a
//             following 'step' Undo crosses into it (the regroup RES step).
function SWUComputeUndoTarget(string $kind): int {
    global $gRandomCounter;
    $top = UndoCursor();
    // Skip "no-op" snapshots at the top of the stack: a snapshot whose stored payload equals the CURRENT
    // serialized state (nothing has changed since it was taken — e.g. the pregame pre-resource
    // PushPregameSnapshot captured right before the resource pick, which matches the live pre-pick state).
    // Undoing to such a snapshot appears to do nothing, so one Undo should step PAST it to the first state
    // that actually differs. Payload format mirrors PushUndoSnapshot exactly so the comparison is byte-exact
    // (production canonicalizes zones across the request boundary, so the compare holds there too).
    $cur = Versions::GetSerializedZones() . '<v0>' . $gRandomCounter;
    while ($top > 0) {
        $line = UndoStackRead($top);
        if ($line === null) break;
        if (UndoRecordParse($line)['payload'] !== $cur) break;
        $top--;
    }
    if ($kind !== 'phase') return $top;
    // Walk down through contiguous 'action' entries, stopping at any other boundary. 'load' is one of
    // them: it marks the pre-state of a bookmark load, so Undo Phase lands at the start of the CURRENT
    // line instead of wandering into the branch that was abandoned by that load.
    $target = $top;
    for ($i = $top; $i >= 0; $i--) {
        $line = UndoStackRead($i);
        if ($line === null) break;
        if (UndoRecordParse($line)['boundary'] !== 'action') break;   // hit a boundary → stop
        $target = $i;                                                  // lowest 'action' seen so far
    }
    return $target;
}

// Does an undo TO $targetOrdinal by $requesterSeat need opponent consent (a public-queue request)?
//   • PRIVATE games: never — undo is always free (requirement #7).
//   • Undo Phase ('phase'): always a request in public (requirement #4), regardless of what it crosses.
//   • Otherwise scan every entry being reverted — ordinals [targetOrdinal .. UndoCursor()] — plus the LIVE
//     (unsnapshotted, top+1) action whose reveal is still in UNDO_REQUIRES_CONSENT. Consent is needed if
//     any reverted action (a) revealed new info, (b) belongs to the opponent, or (c) is a phase boundary
//     ('resource'/'pregame-step' — the undo crosses out of the current phase; requirement #3).
// Record ord_i stores the PRE-state of action i+1 and that action's metadata (seat/revealed/boundary), so
// reverting to $targetOrdinal undoes actions whose records are exactly [targetOrdinal .. top].
// Is this a ONE-PLAYER mode? Goldfish's seat 2 is a passive bot; Hotseat is one person playing both
// seats. Either way there is no second decision-maker to coordinate with.
// Matched explicitly rather than "mode is non-empty" so a future non-solo mode cannot silently inherit
// solo privileges.
function SWUIsSoloMode(): bool {
    $m = SWUGameMode();
    return $m === 'goldfish' || $m === 'hotseat';
}

// SWUSim's privacy check — use this, NOT SimGameIsPrivateGame, anywhere in SWUSim that asks "is this
// game private?".
//
// A one-player mode IS a private game: goldfish and hotseat lobbies are created with isPrivate=true
// (APIs/Lobbies/JoinQueue.php) and there is no opponent to expose anything to. They are re-derived here
// rather than trusted to the flag because that flag lives ONLY in APCu with a one-hour TTL
// (SIM_GAME_RECORD_CACHE_TTL) and has no disk fallback: once it expires — or PHP restarts —
// SimGameReadAuthKeys falls back to SimGameDefaultAuthKeys() (isPrivate = false) and the game silently
// reads as PUBLIC. The game MODE is a GlobalEffect inside the gamestate, so it is durable and is
// restored along with it.
//
// ⚠ That APCu expiry also affects ordinary 2-player private lobbies, which have no durable signal to
// fall back on — a private match running longer than an hour starts demanding undo consent. Fixing
// that needs the auth record persisted outside APCu; it is NOT addressed here.
function SWUGameIsPrivate(string $rootName = '', string $gameName = ''): bool {
    return SWUIsSoloMode() || SimGameIsPrivateGame($rootName, $gameName);
}

function SWUUndoNeedsConsent(int $requesterSeat, int $targetOrdinal, string $kind = 'step', string $rootName = '', string $gameName = ''): bool {
    // Checked FIRST — above the reveal-flag check as well as the phase check. Undo Phase ALWAYS
    // requests when not private, and MarkUndoRequiresConsent fires on every draw; in a solo mode a
    // request can never be answered, so either path would hang the undo forever.
    if (SWUGameIsPrivate($rootName, $gameName)) return false;
    if ($kind === 'phase') return true;
    // The live action's reveal flag hasn't been folded into a record yet — read it directly.
    if (GetSWUVar('UNDO_REQUIRES_CONSENT', 'false') === 'true') return true;
    $top = UndoCursor();
    for ($i = $targetOrdinal; $i <= $top; $i++) {
        $line = UndoStackRead($i);
        if ($line === null) continue;
        $r = UndoRecordParse($line);
        if ($r['revealed']) return true;                          // (a) new info revealed
        if (intval($r['seat']) !== $requesterSeat) return true;   // (b) opponent's action
        if ($r['boundary'] !== 'action') return true;             // (c) crosses a phase boundary
    }
    return false;
}

function SWUDoUndo(int $playerID, string $kind = 'step', string $rootName = '', string $gameName = ''): void {
    $target = SWUComputeUndoTarget($kind);
    if (!SWUUndoNeedsConsent($playerID, $target, $kind, $rootName, $gameName)) {
        $blocked = _SWUCaptureUndoBlocks();
        LoadUndoSnapshot($target);
        _SWUReapplyUndoBlocks($blocked);
        SetFlashMessage('Undo applied.');
    } else {
        $blocked = GetSWUVar('UNDO_BLOCKED_' . $playerID, 'false') === 'true';
        if ($blocked) {
            SetFlashMessage('Your opponent has blocked your undo requests.');
        } else {
            // Remember the exact multi-step/phase target so the approval reverts to the SAME point the
            // requester saw — not merely the single top action (SWUApproveUndo consumes PENDING_UNDO_TARGET).
            SetSWUVar('PENDING_UNDO_FROM', (string)$playerID);
            SetSWUVar('PENDING_UNDO_TARGET', (string)$target);
            SetFlashMessage('Undo requested. Waiting for opponent.');
        }
    }
}

function SWUApproveUndo(): void {
    $requestingPlayer = intval(GetSWUVar('PENDING_UNDO_FROM', '0'));
    if ($requestingPlayer < 1 || $requestingPlayer > 2) return;
    $blocked = _SWUCaptureUndoBlocks();
    // Revert to the SAME target the requester chose (multi-step / Undo Phase), not just the top action.
    $target = intval(GetSWUVar('PENDING_UNDO_TARGET', (string)UndoCursor()));
    LoadUndoSnapshot($target);
    _SWUReapplyUndoBlocks($blocked);
    SetSWUVar('PENDING_UNDO_FROM', '');
    SetSWUVar('PENDING_UNDO_TARGET', '');
    SetFlashMessage('Undo approved.');
}

function SWUDenyUndo(): void {
    $requestingPlayer = intval(GetSWUVar('PENDING_UNDO_FROM', '0'));
    SetSWUVar('PENDING_UNDO_FROM', '');
    SetSWUVar('PENDING_UNDO_TARGET', '');
    SetSWUVar('UNDO_REQUIRES_CONSENT', 'false');
    if ($requestingPlayer >= 1 && $requestingPlayer <= 2) {
        $denyKey = 'UNDO_DENY_COUNT_' . $requestingPlayer;
        $newCount = intval(GetSWUVar($denyKey, '0')) + 1;
        SetSWUVar($denyKey, (string)$newCount);
        if ($newCount >= 2) SetSWUVar('PENDING_BLOCK_PROMPT_FOR', (string)$requestingPlayer);
    }
    SetFlashMessage('Undo denied.');
}

// ── Gamestate bookmarks (private lobbies only) ───────────────────────────────
// A bookmark is a durable, named snapshot that owns its own payload — deliberately NOT a pointer into
// the undo log. That decouples bookmark durability from log retention: the log's retention policy can
// change without invalidating a bookmark, and a bookmark outlives any branch it was taken on.
//
// Private-only is enforced HERE, on the server. The client hides the menu items, but that is cosmetic.

function SWUTakeBookmark(int $seat, string $label = '', string $rootName = '', string $gameName = ''): bool {
    // Solo modes count: goldfish/hotseat ARE private lobbies by construction, but isPrivate is
    // APCu-backed with a 1h TTL, so a longer session would silently lose bookmarks. See
    // SWUGameIsPrivate.
    if (!SWUGameIsPrivate($rootName, $gameName)) {
        SetFlashMessage('Gamestate bookmarks are only available in private lobbies.');
        return false;
    }
    if (BookmarkCount() >= SWU_BOOKMARK_MAX) {
        SetFlashMessage('Bookmark limit reached (' . SWU_BOOKMARK_MAX . '). Load or ignore an existing one.');
        return false;
    }
    global $gRandomCounter, $gCurrentPhase, $gTurnNumber;
    // Same payload format as an undo snapshot, so $gRandomCounter rides along and a load inherits
    // undo's determinism guarantee (the property that makes mulligan undo reproducible).
    $payload = Versions::GetSerializedZones() . '<v0>' . $gRandomCounter;
    $round   = intval($gTurnNumber);
    $id = BookmarkAppend($seat, $round, (string)($gCurrentPhase ?? ''), UndoCursor(), $label, $payload);
    if ($id < 1) { SetFlashMessage('Could not save the bookmark.'); return false; }
    SetFlashMessage('Bookmark saved — Round ' . $round . '.');
    return true;
}

function SWULoadBookmark(int $seat, int $bookmarkId, string $rootName = '', string $gameName = ''): bool {
    if (!SWUGameIsPrivate($rootName, $gameName)) {
        SetFlashMessage('Gamestate bookmarks are only available in private lobbies.');
        return false;
    }
    $bm = BookmarkRead($bookmarkId);
    if ($bm === null) { SetFlashMessage('That bookmark no longer exists.'); return false; }

    $blocked = _SWUCaptureUndoBlocks();
    // Snapshot the CURRENT (pre-load) state first, so a following Undo rewinds the load itself and
    // walks back up the line being abandoned. The 'load' boundary stops Undo Phase from walking past
    // this point into that abandoned branch.
    PushUndoSnapshot($seat, 'load');
    $loadOrdinal = UndoCursor();

    _SWURestoreSerializedPayload($bm['payload']);
    _SWUReapplyUndoBlocks($blocked);
    UndoCursorSet($loadOrdinal);   // explicit: the restore must not move the cursor

    // A game that had already ended is playable again. GAMEOVER_WINNER / GAMEOVER_WINNERS live in the
    // gamestate, so the restore cleared them; the only external step is undoing the RemoveActiveGame
    // that the match-end path ran. The match RESULT stays recorded and sealed (see MatchGameIsSealed).
    if ($rootName !== '' && $gameName !== '' && function_exists('RegisterActiveGame')) {
        RegisterActiveGame($rootName, $gameName, true);
    }
    SetFlashMessage('Loaded bookmark — Round ' . intval($bm['round']) . '.');
    return true;
}

function GetStartingChampionChoices($player) {
    $material = GetMaterial($player);
    $levelZeroChampions = [];
    $fallbackChampions = [];
    for($i = 0; $i < count($material); ++$i) {
        $obj = $material[$i];
        if($obj->removed || !PropertyContains(CardType($obj->CardID), "CHAMPION")) continue;
        $mzID = "myMaterial-" . $i;
        $fallbackChampions[] = $mzID;
        if(intval(CardLevel($obj->CardID)) === 0) {
            $levelZeroChampions[] = $mzID;
        }
    }
    return !empty($levelZeroChampions) ? $levelZeroChampions : $fallbackChampions;
}

function QueuePregameStartingChampionChoice($player, $nextPlayer = null) {
    $choices = GetStartingChampionChoices($player);
    if(empty($choices)) return false;
    DecisionQueueController::AddDecision($player, "MZCHOOSE", implode("&", $choices), 1, "Reveal_your_starting_Lv_0_champion");
    $handlerParam = "PREGAME_CHOOSE_STARTING_CHAMPION";
    if($nextPlayer !== null) $handlerParam .= "|" . $nextPlayer;
    DecisionQueueController::AddDecision($player, "CUSTOM", $handlerParam, 1);
    return true;
}

function QueuePregameStartingChampionSetup() {
    $firstPlayer = intval(GetFirstPlayer());
    $secondPlayer = $firstPlayer == 1 ? 2 : 1;
    if(FindChampionMZ($firstPlayer) !== null && FindChampionMZ($secondPlayer) !== null) return false;
    return QueuePregameStartingChampionChoice($firstPlayer, $secondPlayer);
}

function GetPregameStartingFieldMaterialChoices($player) {
    $material = GetMaterial($player);
    $choices = [];
    for($i = 0; $i < count($material); ++$i) {
        if($material[$i]->removed) continue;
        switch($material[$i]->CardID) {
            case "fln04uv297": // The Looking Glass
                $choices[] = "myMaterial-" . $i;
                break;
        }
    }
    return $choices;
}

function PlacePregameStartingFieldMaterial($player, $mzID) {
    global $playerID;
    $savedPlayerID = $playerID;
    $playerID = $player;

    $obj = GetZoneObject($mzID);
    if($obj === null || $obj->removed) {
        $playerID = $savedPlayerID;
        return null;
    }

    switch($obj->CardID) {
        case "fln04uv297": // The Looking Glass
            break;
        default:
            $playerID = $savedPlayerID;
            return null;
    }

    DecisionQueueController::StoreVariable("SuppressNextEnter", "YES");
    $newObj = MZMove($player, $mzID, "myField");
    if($newObj === null) {
        DecisionQueueController::ClearVariable("SuppressNextEnter");
        $playerID = $savedPlayerID;
        return null;
    }

    $newObj->TurnEffects = array_values(array_filter(
        $newObj->TurnEffects ?? [],
        fn($effect) => $effect !== "ENTERED_THIS_TURN"
    ));
    $playerID = $savedPlayerID;
    return $newObj->GetMzID();
}

function ResolvePregameStartingFieldMaterials($player) {
    $choices = GetPregameStartingFieldMaterialChoices($player);
    foreach($choices as $mzID) {
        PlacePregameStartingFieldMaterial($player, $mzID);
    }
}

function PlacePregameStartingChampion($player, $mzID) {
    $obj = GetZoneObject($mzID);
    if($obj === null || $obj->removed || !PropertyContains(CardType($obj->CardID), "CHAMPION")) return null;

    DecisionQueueController::StoreVariable("SuppressNextEnter", "YES");
    $newObj = MZMove($player, $mzID, "myField");
    if($newObj === null) {
        DecisionQueueController::ClearVariable("SuppressNextEnter");
        return null;
    }

    $newObj->TurnEffects = array_values(array_filter(
        $newObj->TurnEffects ?? [],
        fn($effect) => $effect !== "ENTERED_THIS_TURN"
    ));
    return $newObj->GetMzID();
}

$customDQHandlers["PREGAME_CHOOSE_STARTING_CHAMPION"] = function($player, $parts, $lastDecision) {
    if($lastDecision === "-" || $lastDecision === "" || $lastDecision === "PASS") return;

    $startingChampionMZ = PlacePregameStartingChampion($player, $lastDecision);
    if($startingChampionMZ === null) return;
    DecisionQueueController::StoreVariable("PregameStartingChampion" . $player, $startingChampionMZ);

    $nextPlayer = isset($parts[0]) ? intval($parts[0]) : 0;
    if($nextPlayer > 0) {
        if(!QueuePregameStartingChampionChoice($nextPlayer)) {
            $firstPlayer = intval(GetFirstPlayer());
            $secondPlayer = $firstPlayer == 1 ? 2 : 1;
            DecisionQueueController::AddDecision($firstPlayer, "CUSTOM", "PREGAME_RESOLVE_STARTING_CHAMPION_ENTER|" . $secondPlayer, 250);
            $firstMzID = DecisionQueueController::GetVariable("PregameStartingChampion" . $firstPlayer);
            if($firstMzID !== null && $firstMzID !== "") {
                global $playerID;
                $savedPlayerID = $playerID;
                $playerID = $firstPlayer;
                Enter($firstPlayer, $firstMzID);
                $playerID = $savedPlayerID;
            }
        }
        return;
    }

    $firstPlayer = intval(GetFirstPlayer());
    $secondPlayer = $firstPlayer == 1 ? 2 : 1;
    DecisionQueueController::AddDecision($firstPlayer, "CUSTOM", "PREGAME_RESOLVE_STARTING_CHAMPION_ENTER|" . $secondPlayer, 250);
    $firstMzID = DecisionQueueController::GetVariable("PregameStartingChampion" . $firstPlayer);
    if($firstMzID !== null && $firstMzID !== "") {
        global $playerID;
        $savedPlayerID = $playerID;
        $playerID = $firstPlayer;
        Enter($firstPlayer, $firstMzID);
        $playerID = $savedPlayerID;
    }
};

$customDQHandlers["PREGAME_RESOLVE_STARTING_CHAMPION_ENTER"] = function($player, $parts, $lastDecision) {
    $resolvePlayer = isset($parts[0]) ? intval($parts[0]) : ($player == 1 ? 2 : 1);
    $storedMzID = DecisionQueueController::GetVariable("PregameStartingChampion" . $resolvePlayer);
    if($storedMzID === null || $storedMzID === "") {
        $firstPlayer = intval(GetFirstPlayer());
        $secondPlayer = $firstPlayer == 1 ? 2 : 1;
        ResolvePregameStartingFieldMaterials($firstPlayer);
        ResolvePregameStartingFieldMaterials($secondPlayer);
        DecisionQueueController::AddDecision($player, "CUSTOM", "PREGAME_FINISH_STARTING_CHAMPIONS", 250);
        return;
    }

    global $playerID;
    $savedPlayerID = $playerID;
    $playerID = $resolvePlayer;
    Enter($resolvePlayer, $storedMzID);
    $playerID = $savedPlayerID;

    $firstPlayer = intval(GetFirstPlayer());
    $secondPlayer = $firstPlayer == 1 ? 2 : 1;
    ResolvePregameStartingFieldMaterials($firstPlayer);
    ResolvePregameStartingFieldMaterials($secondPlayer);
    // Queue cleanup on the currently executing queue. If we enqueue this on the
    // other player, it can strand a static-only decision with no input path.
    DecisionQueueController::AddDecision($player, "CUSTOM", "PREGAME_FINISH_STARTING_CHAMPIONS", 250);
};

$customDQHandlers["PREGAME_FINISH_STARTING_CHAMPIONS"] = function($player, $parts, $lastDecision) {
    DecisionQueueController::ClearVariable("PregameStartingChampion1");
    DecisionQueueController::ClearVariable("PregameStartingChampion2");
    SetMacroTurnIndex('{}');
};

function IsFirstTurnAttackLocked($player) {
    $currentTurn = intval(GetTurnNumber());
    $firstPlayer = intval(GetFirstPlayer());
    return $currentTurn === 1 && intval($player) === $firstPlayer;
}

function CanActivateAttackCardNow($player, $cardID, $setFlash = true) {
    if(!PropertyContains(CardType($cardID), "ATTACK")) return true;
    if(!IsFirstTurnAttackLocked($player)) return true;
    if($setFlash) SetFlashMessage("Cannot attack on the first turn.");
    return false;
}

//TODO: Add this to a schema
function ActionMap($actionCard, $allowDuringDecisionQueue = false)
{
    global $playerID;
    $turnPlayer = &GetTurnPlayer();
    $currentPhase = GetCurrentPhase();
    $cardArr = explode("-", $actionCard);
    $cardZone = $cardArr[0];
    $cardIndex = $cardArr[1];

    // Block all FSM actions while any player has pending DQ decisions
    // (Opportunity windows, ability choices, combat decisions, etc.)
    $dqController = new DecisionQueueController();
    if(!$allowDuringDecisionQueue && !$dqController->AllQueuesEmpty()) return "";

    switch ($cardZone) {
        case "myHand":
            if(function_exists("HasOpportunity") && HasOpportunity($playerID)
                && function_exists("GetPlayableOpportunityChoices")
                && function_exists("ResolveOpportunitySelection")) {
                $opportunityChoices = GetPlayableOpportunityChoices($playerID);
                if(in_array($actionCard, $opportunityChoices, true)) {
                    ResolveOpportunitySelection($playerID, $actionCard);
                    return "PLAY";
                }
            }
            if($currentPhase == "MAIN" && $playerID == $turnPlayer) {
                // Turn player can play any card during their main phase
                $handObj = GetZoneObject($actionCard);
                if($handObj !== null && !CanActivateAttackCardNow($playerID, $handObj->CardID, true)) break;
                if(function_exists("CanActivateCard") && !CanActivateCard($playerID, $actionCard, false)) break;
                SaveUndoVersion($playerID);
                SWUBeginPlayCard($playerID, $actionCard);
                return "PLAY";
            }
            break;
        case "myGroundArena":
        case "mySpaceArena":
            if ($currentPhase !== "MAIN" || $playerID != $turnPlayer) break;
            if (!$dqController->AllQueuesEmpty()) break;
            $obj = GetZoneObject($actionCard);
            if ($obj === null || (isset($obj->removed) && $obj->removed)) break;
            if (intval($obj->Status) !== 1) {
                SetFlashMessage("That unit is exhausted.");
                break;
            }
            SaveUndoVersion($playerID);
            BeginSWUAttack($playerID, $actionCard);
            return "ATTACK";
    }
    return "";
}

// ── GA Template Code ────────────────────────────────────────────────────────
// Everything below this line is copied from the Grand Archive engine template.
// Do NOT add SWU-specific logic here. SWU overrides live above.
// Some functions here (e.g. OnLeaveField, TriggerGameOver) are called from the
// guarded GA template section at the bottom of this file.
// ────────────────────────────────────────────────────────────────────────────

// (Former ActionMap GA cases for myField, myGraveyard, myBanish, myMaterial, myDeck
//  were removed — SWU does not use those zones.)

function DoActivateCard($player, $mzCard, $ignoreCost = false) {
    // Check if opponent has Corhazi Outlook lockdown effect
    $opponent = ($player == 1) ? 2 : 1;
    if(GlobalEffectCount($opponent, "rw8qq1uwq8-lockdown") > 0) {
        // Activation is blocked
        return;
    }

    $sourceObject = &GetZoneObject($mzCard);

    if($sourceObject === null || (isset($sourceObject->removed) && $sourceObject->removed)) {
        return;
    }

    if(IsFacetLockedName($player, $sourceObject->CardID)) {
        return;
    }
    if(IsDreamFairyLockedCardID($player, $sourceObject->CardID)) {
        SetFlashMessage("Dream Fairy is preventing that card from being played.");
        return;
    }

    // Attack cards cannot be activated by the opening player on turn 1.
    if(!CanActivateAttackCardNow($player, $sourceObject->CardID, true)) {
        return;
    }

    // Blessed Clergy (a3pmmloejo): restrict to 2 card plays during next turn
    if(GlobalEffectCount($player, "a3pmmloejo-restrict") > 0) {
        if(CardActivatedCallCount($player) >= 2) {
            return; // Already played 2 cards this turn
        }
    }

    // Invoke Dominance (PLljzdiMmq): can't activate non-ally cards this turn
    if(GlobalEffectCount($player, "PLljzdiMmq_NO_NONALLY") > 0) {
        $cardType = CardType($sourceObject->CardID);
        if(!PropertyContains($cardType, "ALLY")) {
            return;
        }
    }

    // 1.5 Ally Link pre-check: if the card has Ally Link, there must be at least
    // one ally on the field to link to. If not, the activation is illegal.
    global $AllyLink_Cards;
    $hasAllyLink = isset($AllyLink_Cards[$sourceObject->CardID]);
    if($hasAllyLink) {
        $allyTargets = ZoneSearch("myField", ["ALLY"]);
        if(empty($allyTargets)) return; // No valid Link target â€” block activation
    }

    // Nightmare Coil (3fe3c97s71): only while your champion is distant, and only during recollection.
    if($sourceObject->CardID === "3fe3c97s71") {
        if(GetCurrentPhase() !== "RECOLLECTION") return;
        $champMZ = FindChampionMZ($player);
        if($champMZ === null) return;
        $champObj = GetZoneObject($champMZ);
        if($champObj === null || !IsDistant($champObj)) return;
    }

    // Weapon Link pre-check: Sheath of Faceted Lapis (0cnn1eh85y) requires a Warrior weapon on field
    // Fang of Dragon's Breath (iebo5fu381) requires a Polearm weapon on field
    $hasWeaponLink = ($sourceObject->CardID === "0cnn1eh85y" || $sourceObject->CardID === "iebo5fu381" || $sourceObject->CardID === "swy2NJ4q6O");
    if($hasWeaponLink) {
        if($sourceObject->CardID === "iebo5fu381") {
            $weaponTargets = ZoneSearch("myField", ["WEAPON"], cardSubtypes: ["POLEARM"]);
        } else if($sourceObject->CardID === "swy2NJ4q6O") {
            $weaponTargets = ZoneSearch("myField", ["REGALIA"]);
        } else {
            $weaponTargets = ZoneSearch("myField", ["WEAPON"], cardSubtypes: ["WARRIOR"]);
        }
        if(empty($weaponTargets)) return; // No valid weapon â€” block activation
    }

    // Command pre-check: COMMAND subtype attack needs a matching ally on field
    if(PropertyContains(CardSubtypes($sourceObject->CardID), "COMMAND")) {
        if(PropertyContains(CardSubtypes($sourceObject->CardID), "CHESSMAN")) {
            $commandAllies = ZoneSearch("myField", ["ALLY"], cardSubtypes: ["CHESSMAN"]);
        } else if(PropertyContains(CardSubtypes($sourceObject->CardID), "AUTOMATON")) {
            $commandAllies = ZoneSearch("myField", ["ALLY"], cardSubtypes: ["AUTOMATON"]);
        } else {
            $commandAllies = [];
        }
        if(empty($commandAllies)) return; // No ally to command â€” block activation
    }

    $ignoreElementRequirement = (
        $sourceObject->CardID === "pn9gQjV3Rb" &&
        GetCounterCount($sourceObject, "_seiryuuBanished") > 0
    );
    if(!$ignoreElementRequirement && !CanPlayerUseCardElement($player, $sourceObject->CardID, true, true)) {
        return;
    }

    // Three Visits (w7o3agvvnc): mandatory additional cost â€” rest your champion.
    if($sourceObject->CardID === "w7o3agvvnc" && !$ignoreCost && !CanPayRestChampionCost($player)) {
        return;
    }
    if($sourceObject->CardID === "iohZMWh5v5" && !$ignoreCost) {
        $blazingThrowWeapons = ZoneSearch("myField", ["WEAPON"]);
        if(empty($blazingThrowWeapons)) {
            SetFlashMessage("Blazing Throw requires a weapon to sacrifice.");
            return;
        }
    }

    //1.1 Announcing Activation: First, the player announces the card they are activating and places it onto the effects stack.
    // Track the source zone so "whenever you activate from memory" triggers can check it in OnCardActivated.
    $activationSourceOverride = DecisionQueueController::GetVariable("activationSourceZoneOverride");
    if($activationSourceOverride !== null && $activationSourceOverride !== "") {
        DecisionQueueController::StoreVariable("activationSourceZone", $activationSourceOverride);
        DecisionQueueController::ClearVariable("activationSourceZoneOverride");
    } else {
        DecisionQueueController::StoreVariable("activationSourceZone", strtok($mzCard, "-"));
    }
    $obj = MZMove($player, $mzCard, "EffectStack");
    $obj->_sourceZone = DecisionQueueController::GetVariable("activationSourceZone");
    $obj->Controller = $player;
    $threeVisitsSource = DecisionQueueController::GetVariable("threeVisitsActivationSource");
    if($obj->CardID === "w7o3agvvnc") {
        if(!isset($obj->TurnEffects) || !is_array($obj->TurnEffects)) $obj->TurnEffects = [];
        if($threeVisitsSource === "GY" && !in_array("THREE_VISITS_FROM_GY", $obj->TurnEffects)) {
            $obj->TurnEffects[] = "THREE_VISITS_FROM_GY";
        } else if($threeVisitsSource === "BANISH" && !in_array("THREE_VISITS_FROM_BANISH", $obj->TurnEffects)) {
            $obj->TurnEffects[] = "THREE_VISITS_FROM_BANISH";
        }
    }
    DecisionQueueController::ClearVariable("threeVisitsActivationSource");
    if($obj->CardID === "3fe3c97s71" && IsClassBonusActive($player, ["RANGER"])) {
        $obj->TurnEffects[] = "CANT_BE_NEGATED";
    }
    // Spellward Scepter (f6lxizyuml): next card you activate this turn can't be negated.
    if(GlobalEffectCount($player, "f6lxizyuml_NEXT_CANT_BE_NEGATED") > 0) {
        $obj->TurnEffects[] = "CANT_BE_NEGATED";
        RemoveGlobalEffect($player, "f6lxizyuml_NEXT_CANT_BE_NEGATED");
    }
    TrackEffectStackSourceZone("EffectStack-" . $obj->mzIndex, DecisionQueueController::GetVariable("activationSourceZone"));
    if($obj->CardID === "w7o3agvvnc") {
        if($threeVisitsSource === "GY") {
            TrackEffectStackSourceZone("EffectStack-" . $obj->mzIndex, "myGraveyard");
        } else if($threeVisitsSource === "BANISH") {
            TrackEffectStackSourceZone("EffectStack-" . $obj->mzIndex, "myBanish");
        }
    }
    // Empower: the next spell activated this turn gets the full pending empower amount.
    // Tag this activation on the effect stack and consume pending empower immediately.
    if(PropertyContains(CardSubtypes($obj->CardID), "SPELL")) {
        $pendingEmpowerForActivation = PendingEmpowerAmount($player);
        if($pendingEmpowerForActivation > 0) {
            AddTurnEffect("EffectStack-" . $obj->mzIndex, "EMPOWERED");
            AddTurnEffect("EffectStack-" . $obj->mzIndex, "EMPOWER_PLUS_" . $pendingEmpowerForActivation);
            ConsumePendingEmpower($player);
        }
    }

    // Three Visits (w7o3agvvnc): pay mandatory additional cost by resting champion.
    if($obj->CardID === "w7o3agvvnc" && !$ignoreCost) {
        $champMZ = FindChampionMZ($player);
        if($champMZ !== null) {
            ExhaustCard($player, $champMZ);
        }
    }

    //TODO: 1.3 Declaring Costs: Next, the player declares the intended cost parameters for the card.

    //TODO: 1.4 Selecting Modes

    //TODO: 1.5 Declaring Targets

    //TODO: 1.6 Checking Legality

    // Right of Realm (ptrz1bqry4): "Whenever you activate a domain card, you may sacrifice
    // Right of Realm. If you do, that domain enters the field without any of its upkeep abilities."
    $cardType = CardType($obj->CardID);
    if(PropertyContains($cardType, "DOMAIN")) {
        $field = GetZone("myField");
        for($ri = 0; $ri < count($field); ++$ri) {
            if(!$field[$ri]->removed && $field[$ri]->CardID === "ptrz1bqry4") {
                DecisionQueueController::AddDecision($player, "YESNO", "-", 100,
                    tooltip:"Sacrifice_Right_of_Realm_so_domain_enters_without_upkeep?");
                DecisionQueueController::AddDecision($player, "CUSTOM", "RightOfRealmChoice|$ri", 100);
                break; // Only one Right of Realm can trigger
            }
        }
    }

    //1.7 Calculating Reserve Cost

    $reserveCost = CalculateActivationReserveCost($player, $obj, false);



    // Expeditious Opening (w1wgpeifd0): consume fast-activation effect when any ally is activated.

    // (Not a cost modifier â€” kept outside the helper.)

    if(GlobalEffectCount($player, "w1wgpeifd0") > 0 && PropertyContains(CardType($obj->CardID), "ALLY")) {

        RemoveGlobalEffect($player, "w1wgpeifd0");

    }

    // Bombastic Sprint (t4owmcva0f): consume fast-activation effect on the next Ranger action.

    if(GlobalEffectCount($player, "t4owmcva0f") > 0

        && PropertyContains(CardType($obj->CardID), "ACTION")

        && PropertyContains(CardClasses($obj->CardID), "RANGER")) {

        RemoveGlobalEffect($player, "t4owmcva0f");

    }

    // Accelerate (6yW2zOwWmU): consume fast-activation effect when any card is activated.

    if(GlobalEffectCount($player, "6yW2zOwWmU") > 0) {

        RemoveGlobalEffect($player, "6yW2zOwWmU");

    }



    // Break Apart (4ns2jbt4hq): interactive cost choice for mixed regalia/non-regalia targets.

    // Simple cases (all regalias â†’ $reserveCost already includes +2, no regalias â†’ no change) are

    // handled by CalculateActivationReserveCost above.

    $hasBreakApartCost = false;

    if($obj->CardID === "4ns2jbt4hq") {

        $allBPTargets = array_merge(

            ZoneSearch("myField", ["ITEM"]), ZoneSearch("myField", ["WEAPON"]),

            ZoneSearch("theirField", ["ITEM"]), ZoneSearch("theirField", ["WEAPON"])

        );

        $bpRegaliaCount = 0;

        $bpNonRegaliaCount = 0;

        foreach($allBPTargets as $bpMZ) {

            $bpObj = GetZoneObject($bpMZ);

            if(PropertyContains(CardType($bpObj->CardID), "REGALIA")) {

                $bpRegaliaCount++;

            } else {

                $bpNonRegaliaCount++;

            }

        }

        if($bpRegaliaCount > 0 && $bpNonRegaliaCount == 0) {

            DecisionQueueController::StoreVariable("breakApartTargetRegalia", "YES");

        } else if($bpRegaliaCount > 0 && $bpNonRegaliaCount > 0) {

            $hasBreakApartCost = true;

            DecisionQueueController::AddDecision($player, "YESNO", "-", 100, tooltip:"Target_a_regalia?_(costs_2_more)");

            DecisionQueueController::AddDecision($player, "CUSTOM", "BreakApartCostChoice|$reserveCost", 100);

        } else {

            DecisionQueueController::StoreVariable("breakApartTargetRegalia", "NO");

        }

    }



    // Coronation Ceremony (y4PZCiE26a): interactive cost choice for mixed unique/non-unique targets.

    // Simple cases (all unique â†’ $reserveCost already includes -2, no unique â†’ no change) are

    // handled by CalculateActivationReserveCost above.

    $hasCoronationCost = false;

    if($obj->CardID === "y4PZCiE26a") {

        $allUnits = array_merge(

            ZoneSearch("myField", ["ALLY", "CHAMPION"]),

            ZoneSearch("theirField", ["ALLY", "CHAMPION"])

        );

        $allUnits = FilterSpellshroudTargets($allUnits);

        $uniqueAllyCount = 0;

        $nonUniqueCount = 0;

        foreach($allUnits as $uMZ) {

            $uObj = GetZoneObject($uMZ);

            if(PropertyContains(EffectiveCardType($uObj), "ALLY") && PropertyContains(EffectiveCardType($uObj), "UNIQUE")) {

                $uniqueAllyCount++;

            } else {

                $nonUniqueCount++;

            }

        }

        if($uniqueAllyCount > 0 && $nonUniqueCount == 0) {

            DecisionQueueController::StoreVariable("coronationTargetUnique", "YES");

        } else if($uniqueAllyCount > 0 && $nonUniqueCount > 0) {

            $hasCoronationCost = true;

            DecisionQueueController::AddDecision($player, "YESNO", "-", 100, tooltip:"Target_a_unique_ally?_(costs_2_less)");

            DecisionQueueController::AddDecision($player, "CUSTOM", "CoronationCeremonyChoice|$reserveCost", 100);

        } else {

            DecisionQueueController::StoreVariable("coronationTargetUnique", "NO");

        }

    }
    //1.3 Declaring Costs â€” check for optional additional costs
    $hasSongOfFrostAltCost       = false;
    $hasScryAltCost              = false;
    $hasDominatingStrikeAltCost  = false;
    $hasRavishingFinaleCost      = false;
    $hasInterventionCost         = false;
    $hasSlimeKingCost            = false;
    $hasInnervateAgilityCost     = false;
    $hasGoldenGambitCost         = false;
    $hasArgusReserveAltCost      = false;
    global $additionalActivationCosts;
    $hasAdditionalCost = false;
    if(isset($additionalActivationCosts[$obj->CardID])) {
        $costEntry = $additionalActivationCosts[$obj->CardID];
        $extraReserve = $costEntry['extraReserve'];
        $hand = GetZone("myHand");
        $conditionMet = !isset($costEntry['condition']) || $costEntry['condition']($player);
        if($conditionMet && count($hand) >= $reserveCost + $extraReserve) {
            $hasAdditionalCost = true;
            $prompt = $costEntry['prompt'];
            DecisionQueueController::AddDecision($player, "YESNO", "-", 100, tooltip:$prompt);
            DecisionQueueController::AddDecision($player, "CUSTOM",
                "DeclareAdditionalCost|" . $obj->CardID . "|" . $reserveCost . "|" . $extraReserve, 100);
        }
    }

    //1.3 Declaring Costs — Innervate Agility (v43ehjdu50): mandatory delevel + recover 5
    if($obj->CardID === "v43ehjdu50" && !$ignoreCost) {
        $canDelevel = false;
        $field = GetField($player);
        foreach($field as $fieldObj) {
            if($fieldObj->removed) continue;
            if(!PropertyContains(EffectiveCardType($fieldObj), "CHAMPION")) continue;
            if(($fieldObj->Controller ?? 0) != $player) continue;
            $subcards = is_array($fieldObj->Subcards) ? $fieldObj->Subcards : [];
            if(!empty($subcards)) $canDelevel = true;
            break;
        }
        if($canDelevel) {
            $hasInnervateAgilityCost = true;
            DecisionQueueController::AddDecision($player, "CUSTOM", "InnervateAgilityActivationCost|" . $reserveCost, 100);
        }
