            DecisionQueueController::AddDecision($player, "MZCHOOSE", $targetStr, 100, "Rest_first_Fatestone");
            DecisionQueueController::AddDecision($player, "CUSTOM", "WindsOfDestinyRestStep|1", 100);
        }
    } else {
        for($i = 0; $i < $baseReserve; ++$i) {
