    if($card === null) return;
    switch($card->CardID) {

        default: break;
    }
}

/**
 * Pay the non-reserve costs for an activated ability (e.g., banish self, REST).
 * Called before AbilityActivated so the card is already gone before the opponent
 * receives priority via AbilityOpportunity.
 *
 * @param int    $player  The activating player
 * @param string $mzCard  The mzID of the card paying the cost
 * @param string $cardID  The card's dictionary ID
 */
function ActivatedAbilityCost($player, $mzCard, $cardID, $abilityIndex = 0) {
    global $Cardistry_Cards;
    if(isset($Cardistry_Cards[$cardID])) {
        $baseCost = intval($Cardistry_Cards[$cardID]);
        $reserveCost = max(0, $baseCost - GetCardistryDiscount($player));
        for($ri = 0; $ri < $reserveCost; ++$ri) {
            DecisionQueueController::AddDecision($player, "CUSTOM", "ReserveCard", 101);
        }
    }
    switch($cardID) {
        case "2sn7hlyrkw": // Fatestone of Progress - [Guo Jia Bonus] (4): Transform
            if(intval($abilityIndex) === 0) {
                for($ri = 0; $ri < 4; ++$ri) {
                    DecisionQueueController::AddDecision($player, "CUSTOM", "ReserveCard", 100);
                }
            }
            break;
        case "0w5xyjuczy": // Lavaplume Fatestone - [Guo Jia Bonus] (4): Transform
            if(intval($abilityIndex) === 0) {
                for($ri = 0; $ri < 4; ++$ri) {
                    DecisionQueueController::AddDecision($player, "CUSTOM", "ReserveCard", 100);
                }
            }
            break;
        case "l6410a85dn": // Cyclonic Fatestone - [Guo Jia Bonus] (3), [REST]: Transform
            if(intval($abilityIndex) === 0) {
                $sourceObj = &GetZoneObject($mzCard);
                if($sourceObj !== null) $sourceObj->Status = 1;
                for($ri = 0; $ri < 3; ++$ri) {
                    DecisionQueueController::AddDecision($player, "CUSTOM", "ReserveCard", 100);
                }
            }
            break;
        case "x7t0vki9gy": // Beseeched Fatestone - [Guo Jia Bonus] (6), [REST]: Transform, costs 2 less per materialize
            if(intval($abilityIndex) === 0) {
                $sourceObj = &GetZoneObject($mzCard);
                if($sourceObj !== null) $sourceObj->Status = 1;
                $reserveCost = max(0, 6 - (MaterializeCallCount($player) * 2));
                for($ri = 0; $ri < $reserveCost; ++$ri) {
                    DecisionQueueController::AddDecision($player, "CUSTOM", "ReserveCard", 100);
                }
            }
            break;
        case "qiv63tpshe": // Idle Fatestone - [Guo Jia Bonus] [REST], (2): reveal top card and check parity
            if(intval($abilityIndex) === 0) {
                $sourceObj = &GetZoneObject($mzCard);
                if($sourceObj !== null) $sourceObj->Status = 1;
                DecisionQueueController::AddDecision($player, "CUSTOM", "ReserveCard", 100);
                DecisionQueueController::AddDecision($player, "CUSTOM", "ReserveCard", 100);
            }
            break;
        case "3h93tgm72l": // Fluvial Fatestone - [Guo Jia Bonus] (4), [REST]: mill 2 and transform
            if(intval($abilityIndex) === 0) {
                $sourceObj = &GetZoneObject($mzCard);
                if($sourceObj !== null) $sourceObj->Status = 1;
                for($ri = 0; $ri < 4; ++$ri) {
                    DecisionQueueController::AddDecision($player, "CUSTOM", "ReserveCard", 100);
                }
            }
            break;
        case "ulh4lplwqe": // Coiled Fatestone - [Guo Jia Bonus] [REST], (1): deal/champions + age
            if(intval($abilityIndex) === 0) {
                $sourceObj = &GetZoneObject($mzCard);
                if($sourceObj !== null) $sourceObj->Status = 1;
                DecisionQueueController::AddDecision($player, "CUSTOM", "ReserveCard", 100);
            }
            break;
        case "o37qtuvlxa": // Fatestone of Unrelenting - [Guo Jia Bonus] [REST], banish two fire from GY
            if(intval($abilityIndex) === 0) {
                $sourceObj = &GetZoneObject($mzCard);
                if($sourceObj !== null) $sourceObj->Status = 1;
            }
            break;
        case "xd4kv0akqr": // Fatestone of Revelations - [Guo Jia Bonus] (6), costs (LV) less
            if(intval($abilityIndex) === 0) {
                $reserveCost = max(0, 6 - PlayerLevel($player));
                for($ri = 0; $ri < $reserveCost; ++$ri) {
                    DecisionQueueController::AddDecision($player, "CUSTOM", "ReserveCard", 100);
                }
            }
            break;
        case "vZH2xr4yq2": // Auspicious Manifestation - (2), Discard this card from your hand
            if(intval($abilityIndex) === 0) {
                DecisionQueueController::AddDecision($player, "CUSTOM", "ReserveCard", 100);
                DecisionQueueController::AddDecision($player, "CUSTOM", "ReserveCard", 100);
                MZMove($player, $mzCard, "myGraveyard");
                DecisionQueueController::CleanupRemovedCards();
            }
            break;
        case "G8pN8Hackq": // Aella, Zephyr's Hand â€” (3), first activation each turn costs (3) less
            if(intval($abilityIndex) === 0) {
                $reserveCost = 3;
                if(ActivateAbilityTurnCount($player, $cardID) <= 1) {
                    $reserveCost = max(0, $reserveCost - 3);
                }
                for($ri = 0; $ri < $reserveCost; ++$ri) {
