$customDQHandlers["HeirloomOfLibraChoice"] = function($player, $parts, $lastDecision) {
    if(intval($lastDecision) === 1) {
        $opponent = ($player == 1) ? 2 : 1;
        $champ = FindChampionMZ($opponent);
        if($champ !== null) AddTurnEffect($champ, "MRiM1fnOWC-level");
