function ApplyCrystallizedDestinyPrevention($championMZ, $amount) {
    $champion = GetZoneObject($championMZ);
    if($champion === null || !in_array("CRYSTALLIZED_DESTINY", $champion->TurnEffects ?? [])) {
        return $amount;
    }
    $champion->TurnEffects = array_values(array_filter($champion->TurnEffects, fn($e) => $e !== "CRYSTALLIZED_DESTINY"));
    if($amount >= 7) {
        $opponent = ($champion->Controller == 1) ? 2 : 1;
        AddGlobalEffects($opponent, "CRYSTALLIZED_DESTINY_COST");
    }
    return 0;
}

function ApplyFatedKeepsakePrevention($player, $amount) {
    if($amount < 7) return $amount;
    if(!IsGuoJiaBonus($player)) return $amount;
    if(CountFatestoneOrFateboundObjects($player) < 3) return $amount;
    $field = &GetField($player);
    foreach($field as $fObj) {
        if(!$fObj->removed && $fObj->CardID === "vi1uyifw6s" && !HasNoAbilities($fObj)) {
            return min($amount, 6);
        }
    }
    return $amount;
}

function DealChampionDamage($player, $amount=1, $sourceController = null) {
    $targetMZ = FindChampionMZ($player);
    if($targetMZ === null) return null;

    if($sourceController === null) {
        $effectStack = GetEffectStack();
        for($i = count($effectStack) - 1; $i >= 0; --$i) {
            if($effectStack[$i] !== null && !$effectStack[$i]->removed) {
                $sourceController = intval($effectStack[$i]->Controller ?? $player);
                break;
            }
        }
    }

    $sourceMZ = DecisionQueueController::GetVariable("mzID");
    if($sourceMZ !== null && $sourceMZ !== "" && $sourceMZ !== "-") {
        $sourceObj = GetZoneObject($sourceMZ);
        if($sourceObj !== null && $sourceController === null) {
            $sourceController = intval($sourceObj->Controller ?? $player);
        }
    }
    if($sourceMZ === null || $sourceMZ === "" || $sourceMZ === "-" || GetZoneObject($sourceMZ) === null) {
        $sourceMZ = null;
    }

    if($sourceMZ === null && $sourceController !== null) {
        $sourceMZ = FindChampionMZ(intval($sourceController));
    }

    return DealDamage($player, $sourceMZ, $targetMZ, $amount);
}

function DealChampionDamageAmount($player, $amount=1) {
    $champMZ = FindChampionMZ($player);
    if($champMZ === null) return 0;
    $champObj = GetZoneObject($champMZ);
    if($champObj === null) return 0;
    $beforeDamage = intval($champObj->Damage);
    DealChampionDamage($player, $amount);
    $champObj = GetZoneObject($champMZ);
    if($champObj === null) return 0;
    return max(0, intval($champObj->Damage) - $beforeDamage);
}

function ChillToTheBoneResolve($player) {
    global $playerID;
    $attackerMZ = DecisionQueueController::GetVariable("CombatAttacker");
    if($attackerMZ === null || $attackerMZ === "-" || $attackerMZ === "") return;
    $attackerObj = GetZoneObject($attackerMZ);
    if($attackerObj === null || $attackerObj->removed || !PropertyContains(EffectiveCardType($attackerObj), "ALLY")) return;
    $targets = FilterSpellshroudTargets([$attackerMZ]);
    if(empty($targets)) return;
    $fieldZone = $player == $playerID ? "myField" : "theirField";
    $phantasiaCount = count(ZoneSearch($fieldZone, ["PHANTASIA"]));
    AddTurnEffect($attackerMZ, $phantasiaCount >= 2 ? "p00ghqhcpb-4" : "p00ghqhcpb-2");
}

function PossessedReapingOnKill($player) {
    global $playerID;
    $killedCardID = DecisionQueueController::GetVariable("CombatKilledCardID");
    if($killedCardID === null || $killedCardID === "-" || $killedCardID === "") return;
    if(!PropertyContains(CardType($killedCardID), "ALLY")) return;

    $opponentGraveyard = $player == $playerID ? "theirGraveyard" : "myGraveyard";
    $ownGraveyard = $player == $playerID ? "myGraveyard" : "theirGraveyard";
    $graveyardCandidates = [];
    $combatTarget = DecisionQueueController::GetVariable("CombatTarget");
    $targetObj = $combatTarget !== null ? GetZoneObject($combatTarget) : null;
    if($targetObj !== null && !$targetObj->removed) {
        $graveyardCandidates[] = $targetObj->Owner == $playerID ? "myGraveyard" : "theirGraveyard";
    }
    $graveyardCandidates[] = $opponentGraveyard;
    $graveyardCandidates[] = $ownGraveyard;
    $graveyardCandidates = array_values(array_unique($graveyardCandidates));

    $graveyardMZ = null;
    foreach($graveyardCandidates as $graveyardZone) {
        $graveyard = GetZone($graveyardZone);
        for($i = count($graveyard) - 1; $i >= 0; --$i) {
            if(!$graveyard[$i]->removed && $graveyard[$i]->CardID === $killedCardID) {
                $graveyardMZ = $graveyardZone . "-" . $i;
                break 2;
            }
        }
    }
    if($graveyardMZ === null) return;

    $newObj = MZMove($player, $graveyardMZ, "myField");
    if($newObj === null) return;
    $newObj->Controller = $player;
    $newObj->Status = 1;
    $subtypes = EffectiveCardSubtypes($newObj);
    if(!PropertyContains($subtypes, "SPIRIT")) {
        ApplyPersistentOverride($newObj->GetMzID(), ["subtypes" => $subtypes . ",SPIRIT"]);
    }
}

function AnnihilationResolve($player, $amount) {
    $amount = max(0, min(7, intval($amount)));
    $damageDealt = DealChampionDamageAmount($player, $amount);

    $targets = array_merge(ZoneSearch("myField"), ZoneSearch("theirField"));
    foreach($targets as $mzID) {
        $obj = GetZoneObject($mzID);
        if($obj === null || $obj->removed || PropertyContains(EffectiveCardType($obj), "CHAMPION")) continue;
        if(intval(CardCost_reserve($obj->CardID)) === $damageDealt) {
            DoAllyDestroyed($player, $mzID);
        }
    }
    DecisionQueueController::CleanupRemovedCards();
}

function RecoverChampion($player, $amount=1) {
    global $playerID;

    // Fiery Interference (gt2zqtgs42): controller can't recover until end of turn
    if(GlobalEffectCount($player, "CANT_RECOVER") > 0) {
        return null;
    }

    // Morgan, Soul Guide (ka5av43ehj): [Level 2+] opponents can't recover
    $opponent = ($player == 1) ? 2 : 1;
    $oppField = &GetField($opponent);
    foreach($oppField as $oppObj) {
        if(!$oppObj->removed && $oppObj->CardID === "ka5av43ehj" && !HasNoAbilities($oppObj)) {
            if(PlayerLevel($oppObj->Controller) >= 2) {
                return null; // Recovery blocked by Morgan
            }
        }
        if(!$oppObj->removed && $oppObj->CardID === "koyegh1snb" && !HasNoAbilities($oppObj)) {
            return null; // Recovery blocked by Serpentine Judicator
        }
    }

    $zone = $player == $playerID ? "myField" : "theirField";
    $zoneArr = &GetZone($zone);

    // Infernal Vessel (vgWgu1DUYv): if any player controls it, reduce recover amount by 3
    $allField = array_merge(GetZone("myField"), GetZone("theirField"));
    foreach($allField as $ivObj) {
        if(!$ivObj->removed && $ivObj->CardID === "vgWgu1DUYv" && !HasNoAbilities($ivObj)) {
            $amount = max(0, $amount - 3);
            break;
        }
    }
    if($amount <= 0) return null;

    // Transfusive Aura (7qWYuRNoYI): [Damage 20+] recover 2+X instead of X.
    // Stacking is additive per active copy (+2 each).
    $champMZ = FindChampionMZ($player);
    if($champMZ !== null) {
        $champObj = GetZoneObject($champMZ);
        if($champObj !== null && intval($champObj->Damage ?? 0) >= 20) {
            $bonusCopies = 0;
            $field = &GetField($player);
            for($i = 0; $i < count($field); ++$i) {
                if(!$field[$i]->removed && $field[$i]->CardID === "7qWYuRNoYI" && !HasNoAbilities($field[$i])) {
                    $bonusCopies++;
                }
            }
            if($bonusCopies > 0) $amount += 2 * $bonusCopies;
        }
    }

    for($i = 0; $i < count($zoneArr); ++$i) {
        $obj = &$zoneArr[$i];
        if(PropertyContains(EffectiveCardType($obj), "CHAMPION")) {
            $actualRecovered = $obj->Damage - max(0, $obj->Damage - $amount);
            $obj->Damage = max(0, $obj->Damage - $amount);

            // Queue restore animation for the champion
            if($actualRecovered > 0) {
                $absoluteTarget = ConvertMzIDToAbsolute($zone . "-" . $i, $player);
                QueueRestoreAnimation($absoluteTarget, $actualRecovered, 500, true);
            }

            $field = GetField($player);
            $fieldZone = $player == $playerID ? "myField" : "theirField";
            for($fi = 0; $fi < count($field); ++$fi) {
                if($field[$fi]->removed || HasNoAbilities($field[$fi])) continue;
                if($field[$fi]->CardID === "2jgiM0p4dt") {
                    if(!IsClassBonusActive($player, ["ASSASSIN"])) continue;
                    AddTurnEffect($fieldZone . "-" . $fi, "2jgiM0p4dt_RECOVER_" . intval($amount));
                    if(intval($amount) >= 4) AddTurnEffect($fieldZone . "-" . $fi, "UNBLOCKABLE");
                }
                // Photic Blade (NRBO0nVMdl): [Class Bonus] whenever you recover, put a refinement counter on it
                if($field[$fi]->CardID === "NRBO0nVMdl") {
                    if(!IsClassBonusActive($player, ["ASSASSIN"])) continue;
                    AddCounters($player, $fieldZone . "-" . $fi, "refinement", 1);
                }
                // Lightveil Agent (jcaLgesx0e): whenever you recover, put a buff counter on it
                if($field[$fi]->CardID === "jcaLgesx0e") {
                    AddCounters($player, $fieldZone . "-" . $fi, "buff", 1);
                }
            }

            return $obj;
        }
    }
    return null;
}

function Empower($player, $amount, $sourceID) {
    if(intval($amount) <= 0) return;
    global $playerID;
    $zone = $player == $playerID ? "myField" : "theirField";
    $field = GetZone($zone);
    foreach($field as $i => $obj) {
        if(PropertyContains(EffectiveCardType($obj), "CHAMPION")) {
            AddTurnEffect($zone . "-" . $i, "EMPOWERED");
            AddTurnEffect($zone . "-" . $i, "EMPOWER_PLUS_" . intval($amount));
            break;
        }
    }
    foreach($field as $i => $obj) {
        if($obj->removed || $obj->CardID !== "l94wp7qjwb" || HasNoAbilities($obj)) continue;
        if($amount > GetCounterCount($obj, "root")) {
            AddCounters($player, $zone . "-" . $i, "root", 1);
        }
    }
    foreach($field as $i => $obj) {
        if($obj->removed || $obj->CardID !== "AxHzxEHBHZ" || HasNoAbilities($obj)) continue;
        AddTurnEffect($zone . "-" . $i, "AxHzxEHBHZ_EMPOWER_" . intval($amount));
    }
    // Radiant Origin of Mage (dOPqsWYMCQ): whenever you empower, put a training counter on it
    foreach($field as $i => $obj) {
        if($obj->removed || $obj->CardID !== "dOPqsWYMCQ" || HasNoAbilities($obj)) continue;
        AddCounters($player, $zone . "-" . $i, "training", 1);
    }
}

function ConsumePendingEmpower($player) {
    global $playerID;
    $zone = $player == $playerID ? "myField" : "theirField";
    $field = &GetZone($zone);
    foreach($field as &$obj) {
        if(!PropertyContains(EffectiveCardType($obj), "CHAMPION")) continue;
        $newEffects = [];
        $pending = 0;
        foreach($obj->TurnEffects ?? [] as $effectID) {
            if($effectID === "EMPOWERED") continue;
            if(strpos($effectID, "EMPOWER_PLUS_") === 0) {
                $pending += intval(substr($effectID, strlen("EMPOWER_PLUS_")));
                continue;
            }
            $newEffects[] = $effectID;
        }
        $obj->TurnEffects = $newEffects;
        return $pending;
    }
    return 0;
}

function IsEmpowered($player) {
    $contextMZ = DecisionQueueController::GetVariable("mzID");
    if(is_string($contextMZ) && strpos($contextMZ, "EffectStack-") === 0) {
        $stackObj = GetZoneObject($contextMZ);
        if($stackObj !== null && !$stackObj->removed) {
            if(in_array("EMPOWERED", $stackObj->TurnEffects ?? [])) return true;
            foreach($stackObj->TurnEffects ?? [] as $effectID) {
                if(strpos($effectID, "EMPOWER_PLUS_") === 0
                    && intval(substr($effectID, strlen("EMPOWER_PLUS_"))) > 0) {
                    return true;
                }
            }
        }
    }
    global $playerID;
    $zone = $player == $playerID ? "myField" : "theirField";
    $field = GetZone($zone);
    foreach($field as $obj) {
        if(PropertyContains(EffectiveCardType($obj), "CHAMPION")) {
            return in_array("EMPOWERED", $obj->TurnEffects ?? []);
        }
    }
    return false;
}

function PendingEmpowerAmount($player) {
    $contextMZ = DecisionQueueController::GetVariable("mzID");
    if(is_string($contextMZ) && strpos($contextMZ, "EffectStack-") === 0) {
        $stackObj = GetZoneObject($contextMZ);
        if($stackObj !== null && !$stackObj->removed) {
            $pendingFromStack = 0;
            foreach($stackObj->TurnEffects ?? [] as $effectID) {
                if(strpos($effectID, "EMPOWER_PLUS_") !== 0) continue;
                $pendingFromStack += intval(substr($effectID, strlen("EMPOWER_PLUS_")));
            }
            if($pendingFromStack > 0) return $pendingFromStack;
        }
    }
    global $playerID;
    $zone = $player == $playerID ? "myField" : "theirField";
    $field = GetZone($zone);
    foreach($field as $obj) {
        if(!PropertyContains(EffectiveCardType($obj), "CHAMPION")) continue;
        $pending = 0;
        foreach($obj->TurnEffects ?? [] as $effectID) {
            if(strpos($effectID, "EMPOWER_PLUS_") !== 0) continue;
            $pending += intval(substr($effectID, strlen("EMPOWER_PLUS_")));
        }
        return $pending;
    }
    return 0;
}

function HandleZoneMoveTriggers($player, $fromZone, $toZone) {
    if(strpos($fromZone, "Memory") !== false && strpos($toZone, "Hand") !== false) {
        if(GetTurnPlayer() == $player && GlobalEffectCount($player, "yrzexkW5Ej") > 0) {
            $deck = &GetDeck($player);
            foreach($deck as $deckObj) {
                if(!$deckObj->removed) {
                    MZMove($player, "myDeck-0", "myGraveyard");
                    break;
                }
            }
        }
    }
}

function GetOpponent($player) {
    if($player == 1) return 2;
    if($player == 2) return 1;
    return null;
}

/**
 * Get the full lineage of a player's champion (current champion CardID + all subcards).
 * Returns an array of CardIDs representing the lineage from newest to oldest.
 * @param int $player  The player number
 * @return array  Array of CardIDs, empty if no champion on field
 */
function GetChampionLineage($player) {
    $field = &GetField($player);
    foreach($field as $obj) {
        if($obj === null) continue;
        if(!$obj->removed && PropertyContains(EffectiveCardType($obj), "CHAMPION") && $obj->Controller == $player) {
            $subcards = is_array($obj->Subcards) ? $obj->Subcards : [];
            return array_merge([$obj->CardID], $subcards);
        }
    }
    return [];
}

/**
 * Check if a specific card is part of a player's champion lineage.
 * This includes the current champion itself and all subcards beneath it.
 * Used for "Inherited Effect" abilities that persist while a card is in the lineage.
 * @param int    $player  The player number
 * @param string $cardID  The card ID to check for
 * @return bool  True if the card is in the lineage
 */
function ChampionHasInLineage($player, $cardID) {
    $lineage = GetChampionLineage($player);
    return in_array($cardID, $lineage);
}

function IsBasicElementName($element) {
    return in_array($element, ["WATER", "FIRE", "WIND"]);
}

function IsAdvancedElementName($element) {
    return in_array($element, ["CRUX", "EXALTED", "ASTRA", "LUXEM", "UMBRA", "TERA", "EXIA", "NEOS"]);
}

function GetCardElements($cardID) {
    $elementProperty = CardElement($cardID);
    if($elementProperty === null || $elementProperty === "") return [];
    $elements = array_values(array_filter(array_map('trim', explode(',', $elementProperty)), fn($part) => $part !== ""));
    return empty($elements) ? ["NORM"] : $elements;
}

function IsNormOnlyElementProperty($elementProperty) {
    if($elementProperty === null || $elementProperty === "") return true;
    $elements = array_values(array_filter(array_map('trim', explode(',', $elementProperty)), fn($part) => $part !== ""));
    if(empty($elements)) return true;
    foreach($elements as $element) {
        if($element !== "NORM") return false;
    }
    return true;
}

function GetPlayerEnabledElements($player) {
    $enabled = ["NORM" => true];
    foreach(GetChampionLineage($player) as $lineageCardID) {
        foreach(GetCardElements($lineageCardID) as $lineageElement) {
            if($lineageElement === "NORM") continue;
            $enabled[$lineageElement] = true;
        }
    }

    $hasOtherAdvanced = false;
    foreach(array_keys($enabled) as $enabledElement) {
        if($enabledElement !== "EXALTED" && IsAdvancedElementName($enabledElement)) {
            $hasOtherAdvanced = true;
            break;
        }
    }
    if($hasOtherAdvanced) {
        $enabled["EXALTED"] = true;
    }

    // Imperial Seal (by8145w2u2): banish ability enables all basic elements until end of turn
    if(GlobalEffectCount($player, "by8145w2u2_FIRE") > 0) $enabled["FIRE"] = true;
    if(GlobalEffectCount($player, "by8145w2u2_WATER") > 0) $enabled["WATER"] = true;
    if(GlobalEffectCount($player, "by8145w2u2_WIND") > 0) $enabled["WIND"] = true;

    return array_keys($enabled);
}

//Deprecated: use CanPlayerMeetCardElementRequirements instead for checking if a player can use a card with the given element property
function IsPlayerElementEnabled($player, $element) {
    if(IsNormOnlyElementProperty($element)) return true;
    $enabledElements = GetPlayerEnabledElements($player);
    foreach(array_values(array_filter(array_map('trim', explode(',', $element)), fn($part) => $part !== "")) as $elementPart) {
        if(in_array($elementPart, $enabledElements)) return true;
    }
    return false;
}

function CanPlayerMeetCardElementRequirements($player, $elementProperty) {
    if(IsNormOnlyElementProperty($elementProperty)) return true;

    $requiredElements = array_values(array_filter(array_map('trim', explode(',', $elementProperty)), fn($part) => $part !== ""));
    if(empty($requiredElements)) return true;

    $enabledLookup = array_fill_keys(GetPlayerEnabledElements($player), true);

    // Exalted must always be enabled when a card has the Exalted element.
    if(in_array("EXALTED", $requiredElements, true) && !isset($enabledLookup["EXALTED"])) {
        return false;
    }

    // Preserve existing behavior for non-Exalted requirements: any non-NORM listed element is sufficient.
    $otherRequirements = [];
    foreach($requiredElements as $requiredElement) {
        if($requiredElement === "NORM" || $requiredElement === "EXALTED") continue;
        $otherRequirements[] = $requiredElement;
    }

    if(empty($otherRequirements)) return true;

    foreach($otherRequirements as $requiredElement) {
        if(isset($enabledLookup[$requiredElement])) return true;
    }

    return false;
}

function GetElementRestrictionMessage($element) {
    if(IsNormOnlyElementProperty($element)) return "";
    return "Element not enabled: " . $element;
}

function ChampionNameRoot($cardID) {
    $name = CardName($cardID);
    if($name === null || $name === "") return "";
    $commaPos = strpos($name, ",");
    if($commaPos === false) return strtolower(trim($name));
    return strtolower(trim(substr($name, 0, $commaPos)));
}

function ChampionCanSameLevelUp($player) {
    return ChampionHasInLineage($player, "KqBosnU7pU")
        || ChampionHasInLineage($player, "4upufooz13");
}

function CanChampionLevelUpIntoCard($player, $cardID, $higherLevelOnly = false) {
    if(!PropertyContains(CardType($cardID), "CHAMPION")) return false;

    $targetLevel = intval(CardLevel($cardID));
    if($targetLevel <= 0) return false;

    $champObj = GetPlayerChampion($player);
    if($champObj === null || $champObj->removed) return false;

    $currentLevel = intval(CardLevel($champObj->CardID));
    if($targetLevel === ($currentLevel + 1)) return true;
    if($higherLevelOnly) return false;
    if($targetLevel !== $currentLevel) return false;
    return ChampionCanSameLevelUp($player);
}

function GetLevelUpMaterialIndices($player, $higherLevelOnly = false) {
    $material = GetMaterial($player);
    $choices = [];
    for($i = 0; $i < count($material); ++$i) {
        if($material[$i]->removed) continue;
        if(!CanChampionLevelUpIntoCard($player, $material[$i]->CardID, $higherLevelOnly)) continue;
        $choices[] = "myMaterial-" . $i;
    }
    return $choices;
}

function CanMaterializeChampion($player, $cardID) {
    return CanChampionLevelUpIntoCard($player, $cardID);
}

function IsDistortionCard($cardID) {
    if(PropertyContains(CardSubtypes($cardID), "DISTORTION")) return true;
    if(PropertyContains(CardType($cardID), "DISTORTION")) return true;
    if(PropertyContains(CardClasses($cardID), "DISTORTION")) return true;
    return false;
}

function CanLookingGlassIgnoreElementRequirement($player, $cardID) {
    if(!IsDistortionCard($cardID)) return false;

    $field = &GetField($player);
    for($i = 0; $i < count($field); ++$i) {
        if($field[$i]->removed) continue;
        if($field[$i]->CardID !== "fln04uv297") continue;
        if(HasNoAbilities($field[$i])) continue;
        return true;
    }

    return false;
}

function CanPlayerUseCardElement($player, $cardID, $consumeBypass = false, $setFlash = true) {
    $cardElement = CardElement($cardID);
    if($cardElement === null || $cardElement === "" || $cardElement === "NORM") return true;

    if(CanLookingGlassIgnoreElementRequirement($player, $cardID)) {
        return true;
    }

    if(CanPlayerMeetCardElementRequirements($player, $cardElement)) {
        return true;
    }

    if(CanMaterializeChampion($player, $cardID)) {
        return true;
    }

    if(GlobalEffectCount($player, "PRISMATIC_CODEX_IGNORE_ELEMENT") > 0) {
        if($consumeBypass) {
            RemoveGlobalEffect($player, "PRISMATIC_CODEX_IGNORE_ELEMENT");
        }
        return true;
    }

    // Silvie, Slime Sovereign (mdwbkuhtjm): ignore element requirements for advanced element Slime ally cards
    if(IsAdvancedElementCard($cardID)
       && PropertyContains(CardSubtypes($cardID), "SLIME")
       && PropertyContains(CardType($cardID), "ALLY")
       && ChampionHasInLineage($player, "mdwbkuhtjm")) {
        return true;
    }

    // Legendary Saddle (AXE6sCzjZU): ignore element req for non-advanced element Horse ally cards
    if(GlobalEffectCount($player, "AXE6sCzjZU_IGNORE_HORSE_ELEMENT") > 0
       && PropertyContains(CardSubtypes($cardID), "HORSE")
       && PropertyContains(CardType($cardID), "ALLY")
       && !IsAdvancedElementCard($cardID)) {
        return true;
    }

    // Spirit of Chess (AYe0neu31W): inherited effect â€” ignore element req for non-advanced element Chessman cards
    if(PropertyContains(CardSubtypes($cardID), "CHESSMAN")
       && !IsAdvancedElementCard($cardID)
       && ChampionHasInLineage($player, "AYe0neu31W")) {
        return true;
    }

    // Spirit of Slime (0xp4xq07vv): inherited effect - ignore element req for basic element Slime cards
    if(PropertyContains(CardSubtypes($cardID), "SLIME")
       && !IsAdvancedElementCard($cardID)
       && ChampionHasInLineage($player, "0xp4xq07vv")) {
        return true;
    }

    // Harbinger of Lightning (1i5z6r7s9k): while you control an arcane Shenju ally, ignore this card's element requirements.
    if($cardID === "1i5z6r7s9k") {
        $field = &GetField($player);
        for($i = 0; $i < count($field); ++$i) {
            if($field[$i]->removed) continue;
            if(!PropertyContains(EffectiveCardType($field[$i]), "ALLY")) continue;
            if(!PropertyContains(EffectiveCardSubtypes($field[$i]), "SHENJU")) continue;
            if(!PropertyContains(EffectiveCardElement($field[$i]), "ARCANE")) continue;
            return true;
        }
    }

    if($setFlash) {
        SetFlashMessage(GetElementRestrictionMessage($cardElement));
    }
    return false;
}

/**
 * Diana, Haunt Reminiscence (qp2r93Bgpj): [CB] Curse cards in your champion's lineage lose all abilities.
 * Returns true if curse lineage abilities should be suppressed for this player.
 */
function AreCurseLineageAbilitiesSuppressed($player) {
    global $playerID;
    $zone = $player == $playerID ? "myField" : "theirField";
    $field = GetZone($zone);
    foreach($field as $fObj) {
        if($fObj === null) continue;
        if(!$fObj->removed && $fObj->CardID === "qp2r93Bgpj" && !HasNoAbilities($fObj)
            && IsClassBonusActive($player, ["RANGER"])) {
            return true;
        }
    }
    return false;
}

/**
 * Get the champion object reference for a player.
 * @param int $player The player number
 * @return object|null The champion field object, or null if not found.
 */
function GetPlayerChampion($player) {
    $field = &GetField($player);
    foreach($field as &$obj) {
        if(!$obj->removed && PropertyContains(EffectiveCardType($obj), "CHAMPION") && $obj->Controller == $player) {
            return $obj;
        }
    }
    return null;
}

function CanPayRestChampionCost($player) {
    $champMZ = FindChampionMZ($player);
    if($champMZ === null) return false;
    $champObj = GetZoneObject($champMZ);
    if($champObj === null || $champObj->removed) return false;
    return isset($champObj->Status) && intval($champObj->Status) === 2;
}

/**
 * Attempt a Diao Chan glimmer cast from memory. Called when a player selects a
 * myMemory card during an opportunity window. Returns true if handled, false otherwise.
 *
 * Flow: REST champion â†’ remove glimmer counters â†’ move spell to hand â†’ ActivateCard(ignoreCost=true)
 *
 * @param int    $player  The player attempting the glimmer cast
 * @param string $memoryMZ The mzID of the memory card (e.g. "myMemory-2")
 * @return bool  True if glimmer cast was performed
 */
function TryGlimmerCast($player, $memoryMZ) {
    $parts = explode("-", $memoryMZ);
    if($parts[0] !== "myMemory") return false;

    // Verify Diao Chan inherited ability is available
    if(!ChampionHasInLineage($player, "00xbh8oc00")) return false;

    $champMZ = FindChampionMZ($player);
    if($champMZ === null) return false;
    $champObj = &GetZoneObject($champMZ);
    if($champObj->Status != 2 || HasNoAbilities($champObj)) return false;

    $memObj = GetZoneObject($memoryMZ);
    if($memObj === null || $memObj->removed) return false;

    $spellCost = CalculateActivationReserveCost($player, $memObj, true);
    $glimmerCount = GetCounterCount($champObj, "glimmer");
    if($spellCost > $glimmerCount) return false;

    // REST the champion
    $champObj->Status = 1;

    // Remove glimmer counters to pay the cost
    RemoveCounters($player, $champMZ, "glimmer", $spellCost);

    // Force ActivateCard to keep memory as the logical activation source even after moving to hand.
    DecisionQueueController::StoreVariable("activationSourceZoneOverride", "myMemory");

    // Move spell from memory to hand, then activate with ignoreCost=true
    MZMove($player, $memoryMZ, "myHand");
    $hand = &GetHand($player);
    $handIdx = count($hand) - 1;
    ActivateCard($player, "myHand-" . $handIdx, true);

    return true;
}

