$customDQHandlers["AshfletchedBowmanRecollection"] = function($player, $parts, $lastDecision) {
    if($lastDecision === "-" || $lastDecision === "" || $lastDecision === "PASS") return;
    $mzID = $parts[0] ?? "";
    $pickNumber = intval($parts[1] ?? "1");
    $obj = GetZoneObject($mzID);
    if($obj === null || $obj->removed || $obj->CardID !== "vUq1XBaQtU") return;

    MZMove($player, $lastDecision, "myBanish");
    AddTurnEffect($mzID, "RANGED_3");

    if($pickNumber >= 3) return;
    $fireGY = ZoneSearch("myGraveyard", cardElements: ["FIRE"]);
    if(empty($fireGY)) return;
    $nextPick = $pickNumber + 1;
    DecisionQueueController::AddDecision($player, "MZMAYCHOOSE", implode("&", $fireGY), 1,
        tooltip:"Banish_another_fire_card_for_Ranged_3?_(" . $nextPick . "_of_3)");
    DecisionQueueController::AddDecision($player, "CUSTOM", "AshfletchedBowmanRecollection|" . $mzID . "|" . $nextPick, 1);
};

$customDQHandlers["GlacierRemnantsUpkeep"] = function($player, $parts, $lastDecision) {
    $mzID = $parts[0] ?? "";
    $toRemove = intval($lastDecision ?? 0);
    if($toRemove <= 0) return;
    $obj = GetZoneObject($mzID);
    if($obj === null || $obj->removed || $obj->CardID !== "vftUL7ZjFM") return;
    $actual = min(2, $toRemove, GetCounterCount($obj, "durability"));
    if($actual <= 0) return;
    RemoveCounters($player, $mzID, "durability", $actual);
    RecoverChampion($player, $actual);
};

// ============================================================================
// Domain Card Type â€” Recollection Upkeep, Passive Effects, and Helpers
// ============================================================================

/**
 * Process domain upkeep checks that trigger "At the beginning of your recollection phase".
 * Called from RecollectionPhase() BEFORE memory is returned to hand.
 *
 * Dawn of Ashes (4coy34bro8): reveal random memory; if not norm element, sacrifice.
 * Prismatic Sanctuary (9w0ejcyuvu): reveal random memory; if not fire/water/wind, sacrifice.
 */
function DomainRecollectionUpkeep($player) {
    $field = &GetField($player);
    for($i = count($field) - 1; $i >= 0; --$i) {
        if($field[$i]->removed) continue;
        // Right of Realm exemption: domains tagged NO_UPKEEP skip recollection upkeep
        if(in_array("NO_UPKEEP", $field[$i]->TurnEffects)) continue;
        // Reciprocity, Dorumegia's Call (mSOHJGjrIu): negate one upkeep trigger via counter
        if(GetCounterCount($field[$i], "reciprocity_negate") > 0) {
            RemoveCounters($player, "myField-" . $i, "reciprocity_negate", 1);
            continue;
        }
        switch($field[$i]->CardID) {
            case "4coy34bro8": // Dawn of Ashes
                DomainRevealMemoryUpkeep($player, $i, ["NORM"], "4coy34bro8");
                break;
            case "9w0ejcyuvu": // Prismatic Sanctuary
                DomainRevealMemoryUpkeep($player, $i, ["FIRE", "WATER", "WIND"], "9w0ejcyuvu");
                break;
            case "n1voy5ttkk": // Shatterfall Keep: sacrifice if < 3 water in graveyard
                {
                    global $playerID;
                    $gravZone = $player == $playerID ? "myGraveyard" : "theirGraveyard";
                    $waterGY = ZoneSearch($gravZone, cardElements: ["WATER"]);
                    if(count($waterGY) < 3) {
                        DoSacrificeFighter($player, "myField-" . $i);
                        DecisionQueueController::CleanupRemovedCards();
                    }
                }
                break;
            case "waf8urrqtj": // Gloamspire, Black Market: sacrifice if influence >= 8
                {
                    global $playerID;
                    $memZone = $player == $playerID ? "myMemory" : "theirMemory";
                    $influence = count(GetZone($memZone));
                    if($influence >= 8) {
                        DoSacrificeFighter($player, "myField-" . $i);
                        DecisionQueueController::CleanupRemovedCards();
                    }
                }
                break;
            case "p4lpnvx7mn": // Exalted Dorumegian Throne: sacrifice if <= 4 other domains
                {
                    global $playerID;
                    $zone = $player == $playerID ? "myField" : "theirField";
                    $otherDomains = 0;
                    $fieldArr = GetZone($zone);
                    foreach($fieldArr as $fi => $fObj) {
                        if(!$fObj->removed && $fObj->CardID !== "p4lpnvx7mn" && PropertyContains(CardType($fObj->CardID), "DOMAIN")) {
                            $otherDomains++;
                        }
                    }
                    if($otherDomains <= 4) {
                        DoSacrificeFighter($player, "myField-" . $i);
                        DecisionQueueController::CleanupRemovedCards();
                    }
                }
                break;
            case "snke7lneo4": // Hulao Gate, Sun's Ascent: may banish fire from GY or sacrifice
                {
                    global $playerID;
                    $gravZone = $player == $playerID ? "myGraveyard" : "theirGraveyard";
                    $fireGY = ZoneSearch($gravZone, cardElements: ["FIRE"]);
                    if(!empty($fireGY)) {
                        $fireStr = implode("&", $fireGY);
                        DecisionQueueController::AddDecision($player, "MZMAYCHOOSE", $fireStr, 1, "Banish_fire_card_or_sacrifice_Hulao_Gate");
                        DecisionQueueController::AddDecision($player, "CUSTOM", "HulaoGateUpkeep|" . $i, 1);
                    } else {
                        DoSacrificeFighter($player, "myField-" . $i);
                        DecisionQueueController::CleanupRemovedCards();
                    }
                }
                break;
            case "95ynk6lmnf": // Guandu, Theater of War: remove 2 battle counters or sacrifice
                {
                    $battleCount = GetCounterCount($field[$i], "battle");
                    if($battleCount >= 2) {
                        RemoveCounters($player, "myField-" . $i, "battle", 2);
                    } else {
                        DoSacrificeFighter($player, "myField-" . $i);
                        DecisionQueueController::CleanupRemovedCards();
                    }
                }
                break;
            case "vftUL7ZjFM": // Glacier Remnants: remove up to two durability counters, then recover that much
                {
                    $maxRemove = min(2, GetCounterCount($field[$i], "durability"));
                    if($maxRemove > 0) {
                        DecisionQueueController::AddDecision($player, "NUMBERCHOOSE", "0|" . $maxRemove, 1,
                            tooltip:"Choose_durability_counters_to_remove_(Glacier_Remnants)");
                        DecisionQueueController::AddDecision($player, "CUSTOM", "GlacierRemnantsUpkeep|myField-" . $i, 1);
                    }
                }
                break;
            case "gjhv2etytr": // Keep of the Golden Sashes: banish 2 from GY or sacrifice
                {
                    global $playerID;
                    $gravZone = $player == $playerID ? "myGraveyard" : "theirGraveyard";
                    $gyCards = GetZone($gravZone);
                    $gyMZs = [];
                    for($gi = 0; $gi < count($gyCards); ++$gi) {
                        if(!$gyCards[$gi]->removed) $gyMZs[] = $gravZone . "-" . $gi;
                    }
                    if(count($gyMZs) >= 2) {
                        DecisionQueueController::AddDecision($player, "YESNO", "-", 1, tooltip:"Banish_2_cards_from_graveyard?_(Keep_of_the_Golden_Sashes)");
                        DecisionQueueController::AddDecision($player, "CUSTOM", "KeepGoldenSashesUpkeep|" . $i, 1);
                    } else {
                        DoSacrificeFighter($player, "myField-" . $i);
                        DecisionQueueController::CleanupRemovedCards();
                    }
                }
                break;
            case "kmuuqzfvg8": // Changban, Heroic Impasse: sacrifice if no unique ally on field
                {
                    global $playerID;
                    $zone = $player == $playerID ? "myField" : "theirField";
                    $hasUniqueAlly = false;
                    $fieldArr = GetZone($zone);
                    foreach($fieldArr as $fObj) {
                        if(!$fObj->removed && PropertyContains(EffectiveCardType($fObj), "ALLY") && PropertyContains(EffectiveCardType($fObj), "UNIQUE")) {
                            $hasUniqueAlly = true;
                            break;
                        }
                    }
                    if(!$hasUniqueAlly) {
                        DoSacrificeFighter($player, "myField-" . $i);
                        DecisionQueueController::CleanupRemovedCards();
                    }
                }
                break;
            case "lxnq80yu75": // Gearstride Academy: pay (1) or sacrifice
                {
                    $hand = GetHand($player);
                    if(count($hand) > 0) {
                        DecisionQueueController::AddDecision($player, "YESNO", "-", 1, tooltip:"Pay_(1)_for_Gearstride_Academy?");
                        DecisionQueueController::AddDecision($player, "CUSTOM", "GearstrideAcademyUpkeep|myField-" . $i, 1);
                    } else {
                        DoSacrificeFighter($player, "myField-" . $i);
                        DecisionQueueController::CleanupRemovedCards();
                    }
                }
                break;
            case "ShQkyQMBCT": // Starlit Apothecary: [Arisanna Bonus] copy a Potion or Herb unless opponent pays (4)
                if(!HasNoAbilities($field[$i]) && IsArisannaBonusActive($player)) {
                    StarlitApothecaryRecollection($player);
                }
                break;
        }
    }

}

/**
 * Domain upkeep helper: reveal a random memory card. If its element is NOT in the
 * allowed list, sacrifice the domain at fieldIndex.
 *
 * @param int    $player          The controlling player
 * @param int    $fieldIndex      Index of the domain in the field
 * @param array  $allowedElements Array of allowed element strings (e.g. ["NORM"])
 * @param string $domainCardID    CardID of the domain (for logging/identification)
 */
function DomainRevealMemoryUpkeep($player, $fieldIndex, $allowedElements, $domainCardID) {
    $memory = &GetMemory($player);
    if(count($memory) == 0) {
        // No memory cards â€” sacrifice (can't meet element condition)
        DoSacrificeFighter($player, "myField-" . $fieldIndex);
        DecisionQueueController::CleanupRemovedCards();
        return;
    }
    // Pick a random memory card and reveal it
    $randomIdx = array_rand($memory);
    $memObj = $memory[$randomIdx];
    $memMZ = "myMemory-" . $randomIdx;
    DoRevealCard($player, $memMZ);

    $element = CardElement($memObj->CardID);
    if(!in_array($element, $allowedElements)) {
        // Element doesn't match â€” sacrifice the domain
        // Re-fetch field index since CleanupRemovedCards may have shifted indices
        $field = &GetField($player);
        for($si = 0; $si < count($field); ++$si) {
            if(!$field[$si]->removed && $field[$si]->CardID === $domainCardID) {
                DoSacrificeFighter($player, "myField-" . $si);
                break;
            }
        }
        DecisionQueueController::CleanupRemovedCards();
    }
}

/**
 * Mill N cards from a player's deck (move top N cards from deck to graveyard).
 * @param int    $player   The acting player (perspective for zone names)
 * @param string $deckRef  "myDeck" or "theirDeck"
 * @param string $gyRef    "myGraveyard" or "theirGraveyard"
 * @param int    $amount   Number of cards to mill
 */
function MillCards($player, $deckRef, $gyRef, $amount) {
    $deck = GetZone($deckRef);
    $n = min($amount, count($deck));
    // Always mill in reverse order because cards stick around in their zone until cleaned up for last known information
    for($i = $n-1; $i >= 0; --$i) {
        // Purging Tempest (yuo7dbge3b): redirect GY destination to banish
        $effectiveDest = $gyRef;
        if(strpos($gyRef, "Graveyard") !== false) {
            $gyOwner = (strpos($gyRef, "my") === 0) ? $player : (($player == 1) ? 2 : 1);
            if(GlobalEffectCount($gyOwner, "yuo7dbge3b") > 0) {
                $effectiveDest = (strpos($gyRef, "my") === 0) ? "myBanish" : "theirBanish";
            }

            // Sasha, Purifying Acolyte (GRlUlcYRmV): while fostered, cards entering that
            // player's graveyard are banished instead.
            if($effectiveDest === $gyRef) {
                $gyOwnerField = GetField($gyOwner);
                foreach($gyOwnerField as $fObj) {
                    if(!$fObj->removed && $fObj->CardID === "GRlUlcYRmV" && !HasNoAbilities($fObj) && IsFostered($fObj)) {
                        $effectiveDest = (strpos($gyRef, "my") === 0) ? "myBanish" : "theirBanish";
                        break;
                    }
                }
            }
        }
        MZMove($player, "$deckRef-" . $i, $effectiveDest);
    }
}

// ============================================================================
// Split Damage â€” shared helper for processing MZSplitAssign results
// ============================================================================

/**
 * Process the comma-separated mzID:amount result from an MZSplitAssign decision.
 * Calls DealDamage for each non-zero assignment.
 * @param int    $player        The acting player
 * @param string $source        The mzID of the damage source (e.g. the card dealing damage)
 * @param string $assignmentStr The MZSplitAssign result, e.g. "myField-0:3,theirField-1:2"
 */
function ProcessSplitDamage($player, $source, $assignmentStr) {
    if(empty($assignmentStr) || $assignmentStr === "-") return;
    $pairs = explode(",", $assignmentStr);
    foreach($pairs as $pair) {
        $parts = explode(":", $pair);
        if(count($parts) < 2) continue;
        $targetMZ = $parts[0];
        $amount = intval($parts[1]);
        if($amount > 0) {
            DealDamage($player, $source, $targetMZ, $amount);
        }
    }
}

// ============================================================================
// LevelUpChampion â€” materialize the top champion card from the material deck for free
// ============================================================================

/**
 * Level up the player's champion by materializing the first legal level-up target
 * in their material deck without paying a cost. Used by effects that say
 * "level up your champion."
 * @param int $player The acting player
 * @return bool True if successful, false if no champion found in material deck
 */
function LevelUpChampion($player) {
    $choices = GetLevelUpMaterialIndices($player);
    if(empty($choices)) return false;
    DoMaterialize($player, $choices[0]);
    return true;
}

// ============================================================================
// Delevel â€” return the top card of the champion's lineage to material deck
// ============================================================================

/**
 * Delevel a player's champion: the current champion card is returned to the
 * owner's material deck, and the top subcard becomes the new champion.
 * @param int $player The acting player
 * @return bool True if deleveled successfully, false if champion has no lineage
 */
function Delevel($player) {
    $field = &GetField($player);
    foreach($field as &$obj) {
        if(!$obj->removed && PropertyContains(EffectiveCardType($obj), "CHAMPION") && $obj->Controller == $player) {
            $subcards = is_array($obj->Subcards) ? $obj->Subcards : [];
            if(empty($subcards)) return false; // Level 1 champion, can't delevel
            // Current champion goes to material deck
            $demotedCardID = $obj->CardID;
            MZAddZone($player, "myMaterial", $demotedCardID);
            // Previous champion (top subcard) becomes current
            $obj->CardID = array_shift($obj->Subcards);
            return true;
        }
    }
    return false;
}

// ============================================================================
// Transform â€” flip a card on the field to its other orientation
// ============================================================================

/**
 * Transform a card on the field to its reverse side using CardOtherOrientation.
 * The card keeps its zone position, counters, status, subcards, and all other state.
 * @param int    $player The acting player.
 * @param string $mzCard The mzID of the card to transform (e.g. "myField-3").
 * @return bool True if transformed, false if card has no other orientation.
 */
function TransformCard($player, $mzCard) {
    $obj = &GetZoneObject($mzCard);
    $otherSide = CardOtherOrientation($obj->CardID);
    if($otherSide === null) return false;
    $obj->CardID = $otherSide;
    return true;
}

/**
 * Display CardID for an arena entry. A deployed leader keeps its leader-side
 * CardID in state (stats/text/abilities live on it), but in the arena it must
 * SHOW its unit side — image file "{CardID}_back.webp". Regular units render
 * unchanged. Used only by GroundArena/SpaceArena rendering in GetNextTurn.php.
 */
/**
 * The payload a MASKED (face-down, opponent-owned) resource still sends to the client.
 *
 * Resources is a Visibility=Self zone, so the transport hides the opponent's cards behind a CardBack.
 * It used to send NO cardJSON with them, which hid one thing that is not secret: whether the resource
 * is EXHAUSTED. In SWU that is public — the physical card is visibly rotated, and this zone's schema
 * already declares `Rotation: Status=0:9` and `Overlay: Status=0:exhausted` for it.
 *
 * Consequence of withholding it: parseResCountFromData (Custom/GameLayoutShared.php) counts every entry
 * toward the total but can only count an exhausted one when the entry carries {"Status":0}. With no
 * JSON the opponent's badge read N/N for the whole game — "my opponent's resources do not go down as
 * they play cards", while their own client, which sees its own resources in full, looked correct.
 *
 * Only Status travels. The CardID stays hidden (that IS the secret), and so does every other property.
 * Guarded by DevTools/tests/opponent_resource_status_test.php.
 */
function SWUMaskedResourceJSON($obj): string {
    return json_encode(['Status' => intval($obj->Status ?? 1)]);
}

function SWUArenaDisplayCardID($obj): string {
    $cardID = isset($obj->CardID) ? $obj->CardID : "-";
    if($cardID === "-") return "-";
    if(strpos(CardType($cardID), 'Leader') !== false) return $cardID . "_back";
    return $cardID;
}

/**
 * Display CardID for the LEADER-ZONE slot. Normally the leader keeps its front image in its slot even
 * when deployed (its unit side renders separately in the arena). EXCEPTION: TWI_017 "Flipatine" is a
 * double-leader-face FLIP card with no unit side — its "Deployed" flag is the flipped Villainy face, so
 * the leader slot itself must show the back image ("{CardID}_back") while flipped. Used only by the
 * Leader-zone rendering in GetNextTurn.php.
 */
function SWULeaderDisplayCardID($obj): string {
    $cardID = isset($obj->CardID) ? $obj->CardID : "-";
    if($cardID === 'TWI_017' && !empty($obj->Deployed)) return $cardID . "_back";
    return $cardID;
}

// ============================================================================
// Guo Jia Bonus â€” check if champion name starts with "Guo Jia"
// ============================================================================

/**
 * Check if the given player's champion is a Guo Jia champion (name starts with "Guo Jia").
 * @param int $player The player to check.
 * @return bool True if the player's champion is Guo Jia.
 */
function IsGuoJiaBonus($player) {
    $champMZ = FindChampionMZ($player);
    if($champMZ === null) return false;
    $champObj = GetZoneObject($champMZ);
    return strpos(CardName($champObj->CardID), "Guo Jia") === 0;
}

/**
 * Check if the given player's champion is a Jin champion (name starts with "Jin").
 * @param int $player The player to check.
 * @return bool True if the player's champion is Jin.
 */
function IsJinBonus($player) {
    $champMZ = FindChampionMZ($player);
    if($champMZ === null) return false;
    $champObj = GetZoneObject($champMZ);
    return strpos(CardName($champObj->CardID), "Jin") === 0;
}

/**
 * Add quest counters to the player's champion.
 * @param int $player The player whose champion gets quest counters.
 * @param int $amount Number of quest counters to add.
 * @return bool True if counters were added, false if no champion found.
 */
function AddQuestCounters($player, $amount = 1) {
    $champMZ = FindChampionMZ($player);
    if($champMZ === null) return false;
    AddCounters($player, $champMZ, "quest", $amount);
    return true;
}

/**
 * Get the number of quest counters on a player's champion.
 * @param int $player The player to check.
 * @return int The number of quest counters (0 if none or no champion).
 */
function GetQuestCounterCount($player) {
    $champMZ = FindChampionMZ($player);
    if($champMZ === null) return 0;
    $obj = GetZoneObject($champMZ);
    return isset($obj->Counters["quest"]) ? intval($obj->Counters["quest"]) : 0;
}

/**
 * Remove quest counters from the player's champion.
 * @param int $player The player whose champion loses quest counters.
 * @param int $amount Number of quest counters to remove.
 * @return bool True if counters were removed, false if not enough or no champion.
 */
function RemoveQuestCounters($player, $amount) {
    $champMZ = FindChampionMZ($player);
    if($champMZ === null) return false;
    $obj = &GetZoneObject($champMZ);
    $current = isset($obj->Counters["quest"]) ? intval($obj->Counters["quest"]) : 0;
    if($current < $amount) return false;
    $obj->Counters["quest"] = $current - $amount;
    if($obj->Counters["quest"] <= 0) unset($obj->Counters["quest"]);
    return true;
}

/**
 * Fabled Ruby Fatestone (mzf5dmpqbc): [Guo Jia Bonus] trigger check.
 * Whenever non-combat damage is dealt to a unit (ALLY or CHAMPION) by a fire element
 * source you control, put a quest counter on your champion.
 *
 * Call this after any non-combat damage to a unit resolves, passing the damage source.
 * The source may be an mzID (e.g. "myField-2", "EffectStack-0") or a plain CardID string.
 * If GetZoneObject returns null (e.g. the EffectStack entry was already removed), falls
 * back to walking the EffectStack for the topmost non-removed entry.
 *
 * @param string $source   The mzID or CardID of the damage source.
 * @param bool   $isUnit   True if the target is an ALLY or CHAMPION (pre-computed by caller).
 * @param int    $player   Fallback player when source controller cannot be determined.
 */
function CheckRubyFatestoneQuestCounter($source, $isUnit, $player) {
    if(!$isUnit) return;
    if($source === null || $source === "" || $source === "-") return;
    global $playerID;
    $sourceObj = GetZoneObject($source);
    $sourceElement = null;
    if($sourceObj !== null) {
        $sourceElement = EffectiveCardElement($sourceObj);
    } else if(is_string($source) && strpos($source, "-") === false) {
        // Some callers pass a raw CardID as source.
        $sourceElement = CardElement($source);
    }
    if($sourceElement === null || $sourceElement === "") return;
    if($sourceElement !== "FIRE") return;
    $sourceCtrl = intval($sourceObj->Controller ?? $player);
    $rubyZone = $sourceCtrl == $playerID ? "myField" : "theirField";
    foreach(GetZone($rubyZone) as $rubyObj) {
        if($rubyObj === null) continue;
        if(!$rubyObj->removed && $rubyObj->CardID === "mzf5dmpqbc" && !HasNoAbilities($rubyObj)
                && IsGuoJiaBonus($sourceCtrl)) {
            AddQuestCounters($sourceCtrl, 1);
            break;
        }
    }
}

/**
 * Think Deep (xw9w6y7vtz): put up to two cards from the top of your deck into your graveyard.
 * Queues a decision loop that lets the player choose to mill 0, 1, or 2 cards.
 */
function ThinkDeepMill($player) {
    $deck = GetDeck($player);
    if(empty($deck)) return;
    $maxMill = min(2, count($deck));
    DecisionQueueController::StoreVariable("thinkDeepRemaining", strval($maxMill));
    DecisionQueueController::AddDecision($player, "YESNO", "-", 1, tooltip:"Put_top_card_of_deck_into_graveyard?");
    DecisionQueueController::AddDecision($player, "CUSTOM", "ThinkDeepMillStep", 1);
}

function AvatarOfGenbuResolve($player) {
    if(!IsGuoJiaBonus($player)) return;
    AddQuestCounters($player, 2);
    $targets = [];
    foreach(ZoneSearch("myMaterial") as $mzID) {
        $obj = GetZoneObject($mzID);
        if($obj !== null && !$obj->removed && $obj->CardID === "6ce5rzrjd9") $targets[] = $mzID;
    }
    foreach(ZoneSearch("myBanish") as $mzID) {
        $obj = GetZoneObject($mzID);
        if($obj !== null && !$obj->removed && $obj->CardID === "6ce5rzrjd9") $targets[] = $mzID;
    }
    if(empty($targets)) return;
    if(count($targets) === 1) {
        MZMove($player, $targets[0], "myField");
        return;
    }
    DecisionQueueController::AddDecision($player, "MZMAYCHOOSE", implode("&", $targets), 1,
        tooltip:"Put_Fabled_Sapphire_Fatestone_onto_the_field?_(Avatar_of_Genbu)");
    DecisionQueueController::AddDecision($player, "CUSTOM", "AvatarGenbuFatestonePut", 1);
}

function ChimeOfEndlessDreamsRecycle($player) {
    $gy = &GetGraveyard($player);
    if(empty($gy)) return;
    $cardIDs = [];
    for($i = 0; $i < count($gy); ++$i) {
        if($gy[$i]->removed) continue;
        $cardIDs[] = $gy[$i]->CardID;
        $gy[$i]->Remove();
    }
    DecisionQueueController::CleanupRemovedCards();
    if(empty($cardIDs)) return;
    EngineShuffle($cardIDs);
    foreach($cardIDs as $cardID) {
        MZAddZone($player, "myDeck", $cardID);
    }
}

function LavastormDestroyAllAllies($player) {
    $targets = array_merge(ZoneSearch("myField", ["ALLY"]), ZoneSearch("theirField", ["ALLY"]));
    usort($targets, function($a, $b) {
        $ai = intval(explode("-", $a)[1] ?? 0);
        $bi = intval(explode("-", $b)[1] ?? 0);
        return $bi <=> $ai;
    });
    foreach($targets as $mzID) {
        $obj = GetZoneObject($mzID);
        if($obj === null || $obj->removed) continue;
        DoAllyDestroyed($player, $mzID);
    }
    DecisionQueueController::CleanupRemovedCards();
}

function ProfaneBindingsResolve($player) {
    QueueNegateActivation($player, [], "banish", -1, "ProfaneBindingsNegateResolve");
}

function SummonRetinueResolve($player) {
    for($i = 0; $i < 2; ++$i) {
        MZAddZone($player, "myField", "L67r0GlRHR");
        $field = &GetField($player);
        $field[count($field) - 1]->Status = 1;
    }
    if(GetOmenCount($player) < 3) return;
    $field = &GetField($player);
    for($i = 0; $i < count($field); ++$i) {
        if(!$field[$i]->removed && $field[$i]->CardID === "L67r0GlRHR") {
            WakeupCard($player, "myField-" . $i);
        }
    }
}

function SunderingMoonEnterResolve($player) {
    if(!IsJinBonus($player)) return;
    $windAllies = ZoneSearch("myField", ["ALLY"], cardElements: ["WIND"]);
    if(count($windAllies) < 2) return;
    $mzID = DecisionQueueController::GetVariable("currentMZID");
    if($mzID === null || $mzID === "") return;
    AddTurnEffect($mzID, "8677jq0hfm-POWER");
}

function SunderingMoonPreventResolve($player) {
    if(!IsJinBonus($player)) return;
    $targets = ZoneSearch("myField", ["ALLY", "CHAMPION"]);
    if(empty($targets)) return;
    if(count($targets) === 1) {
        AddTurnEffect($targets[0], "PREVENT_ALL_1");
        return;
    }
    DecisionQueueController::AddDecision($player, "MZCHOOSE", implode("&", $targets), 1,
        tooltip:"Prevent_the_next_1_damage_to_target_unit_(Sundering_Moon)");
    DecisionQueueController::AddDecision($player, "CUSTOM", "SunderingMoonPreventTarget", 1);
}

function FoundPowerResolve($player) {
    Empower($player, 3, "8pIXnuI1Df");
    if(!ZoneContainsCardID("myField", "k5wrAxBbF9")) return;
    $hand = ZoneSearch("myHand");
    if(empty($hand)) return;
    DecisionQueueController::StoreVariable("FoundPowerDiscarded", "0");
    DecisionQueueController::AddDecision($player, "MZMAYCHOOSE", implode("&", $hand), 1,
        tooltip:"Discard_a_card?_(Found_Power_1/2)");
    DecisionQueueController::AddDecision($player, "CUSTOM", "FoundPowerDiscard1", 1);
}

$customDQHandlers["CompanionFatestoneTransform"] = function($player, $parts, $lastDecision) {
    if($lastDecision !== "YES") return;
    $fieldIdx = intval($parts[0]);
    global $playerID;
    $zone = $player == $playerID ? "myField" : "theirField";
    $mzCard = $zone . "-" . $fieldIdx;
    $obj = GetZoneObject($mzCard);
    if($obj === null || $obj->removed || $obj->CardID !== "izf4wdsbz9") return;
    TransformCard($player, $mzCard);
};

$customDQHandlers["ThinkDeepMillStep"] = function($player, $parts, $lastDecision) {
    $remaining = intval(DecisionQueueController::GetVariable("thinkDeepRemaining"));
    if($lastDecision !== "YES" || $remaining <= 0) return;
    $deck = GetDeck($player);
    if(empty($deck)) return;
    MZMove($player, "myDeck-0", "myGraveyard");
    $remaining--;
    if($remaining > 0) {
        $deck2 = GetDeck($player);
        if(!empty($deck2)) {
            DecisionQueueController::StoreVariable("thinkDeepRemaining", strval($remaining));
            DecisionQueueController::AddDecision($player, "YESNO", "-", 1, tooltip:"Put_another_card_into_graveyard?");
            DecisionQueueController::AddDecision($player, "CUSTOM", "ThinkDeepMillStep", 1);
        }
    }
};

// ============================================================================
// Fabled Azurite Fatestone (6ce5rzrjd9) â€” end-phase DQ handler + memory-banish hook
// ============================================================================

$customDQHandlers["FabledAzuriteFatestoneEndPhase"] = function($player, $parts, $lastDecision) {
    if($lastDecision !== "YES") return;
    $memory = &GetMemory($player);
    if(count($memory) === 0) return;
    // Banish a random card from memory
    $randIdx = EngineRandomInt(0, count($memory) - 1);
    MZMove($player, "myMemory-" . $randIdx, "myBanish");
    Draw($player, 1);
};

/**
 * Computes the effective reserve cost for $obj as if $player were activating it.
 * When $dryRun is true (default), one-shot global effects are read but NOT consumed â€”
 * safe to call for display purposes (e.g. hand cost badge).
 * When $dryRun is false, one-shot effects are consumed exactly as DoActivateCard would.
 */
function CalculateActivationReserveCost($player, $obj, $dryRun = true) {
    $cardID    = $obj->CardID;
    $cardType  = CardType($cardID);
    $opponent  = ($player == 1) ? 2 : 1;
    $turnPlayer = &GetTurnPlayer();
    global $playerID, $Efficiency_Cards;

    $reserveCost = intval(CardCost_reserve($cardID));
    if($cardID === "4yqL9xtzVi") $reserveCost = 2;
    // Ephemerate override
    $wasEphemerated = DecisionQueueController::GetVariable("wasEphemerated");
    if($wasEphemerated === "YES") {
        $reserveCost = GetEphemerateCost($player, $cardID);
    }

    $reserveCost = ApplyGeneratedReserveLikeCostModifiers($player, $obj, $reserveCost, "activate");

    // Wayfinder's Map (porhlq2kkv): Domain cards you activate cost 1 less.
    if(PropertyContains($cardType, "DOMAIN")) {
        foreach(GetZone("myField") as $fieldObj) {
            if($fieldObj === null || $fieldObj->removed) continue;
            if($fieldObj->CardID !== "porhlq2kkv" || HasNoAbilities($fieldObj)) continue;
            $reserveCost = max(0, $reserveCost - 1);
            break;
        }
    }

    // Class Bonus: reduce cost if champion's class matches card's class
    $classBonusDiscount = ClassBonusActivateCostReduction($cardID);
    if($classBonusDiscount > 0 && IsClassBonusActive($player, explode(",", CardClasses($cardID)))) {
        $reserveCost = max(0, $reserveCost - $classBonusDiscount);
    }

    $isSpellActivation = PropertyContains(CardSubtypes($cardID), "SPELL");
    $pendingEmpowerLevel = 0;
    if($isSpellActivation) {
        foreach($obj->TurnEffects ?? [] as $effectID) {
            if(strpos($effectID, "EMPOWER_PLUS_") !== 0) continue;
            $pendingEmpowerLevel += intval(substr($effectID, strlen("EMPOWER_PLUS_")));
        }
        if($pendingEmpowerLevel <= 0 && IsEmpowered($player)) {
            $pendingEmpowerLevel = PendingEmpowerAmount($player);
        }
    }

    // Efficiency: reduce cost by champion's current level
    if(isset($Efficiency_Cards[$cardID])) {
        foreach(GetZone("myField") as $fieldObj) {
            if($fieldObj !== null && PropertyContains(EffectiveCardType($fieldObj), "CHAMPION")) {
                $effectiveLevel = ObjectCurrentLevel($fieldObj) + $pendingEmpowerLevel;
                $reserveCost = max(0, $reserveCost - $effectiveLevel);
                break;
            }
        }
    }

    // Strategem of Myriad Ice (id0ybub247): conditional efficiency when SC faces East
    if($cardID === "id0ybub247" && GetShiftingCurrents($player) === "EAST") {
        foreach(GetZone("myField") as $fieldObj) {
            if($fieldObj !== null && PropertyContains(EffectiveCardType($fieldObj), "CHAMPION")) {
                $effectiveLevel = ObjectCurrentLevel($fieldObj) + $pendingEmpowerLevel;
                $reserveCost = max(0, $reserveCost - $effectiveLevel);
                break;
            }
        }
    }

    // Command the Hunt (rxxwQT054x): next card costs 2 less (one-shot)
    if(GlobalEffectCount($player, "rxxwQT054x_COST") > 0) {
        $reserveCost = max(0, $reserveCost - 2);
        if(!$dryRun) RemoveGlobalEffect($player, "rxxwQT054x_COST");
    }

    // Exia Sight (1fy8l4pxs9): [Damage 20+] next card costs 1 less (one-shot)
    if(GlobalEffectCount($player, "1fy8l4pxs9_COST") > 0) {
        $reserveCost = max(0, $reserveCost - 1);
        if(!$dryRun) RemoveGlobalEffect($player, "1fy8l4pxs9_COST");
    }

    // Steady Verse Harmony Discount: next Harmony card costs 1 less (one-shot)
    if(GlobalEffectCount($player, "STEADY_VERSE_HARMONY_DISCOUNT") > 0
        && PropertyContains(CardSubtypes($cardID), "HARMONY")) {
        $reserveCost = max(0, $reserveCost - 1);
        if(!$dryRun) RemoveGlobalEffect($player, "STEADY_VERSE_HARMONY_DISCOUNT");
    }

    // Briar's Spindle (9ooAGDhBj7): next Chessman card activated this turn costs 2 less (one-shot)
    if(GlobalEffectCount($player, "9ooAGDhBj7_COST") > 0
        && PropertyContains(CardSubtypes($cardID), "CHESSMAN")) {
        $reserveCost = max(0, $reserveCost - 2);
        if(!$dryRun) RemoveGlobalEffect($player, "9ooAGDhBj7_COST");
    }

    // Viridian Protective Trinket (s3572j3oda): during opponent's turn, water cards cost 2 more
    if($player !== $turnPlayer) {
        $oppFieldZone = ($turnPlayer == $playerID) ? "myField" : "theirField";
        foreach(GetZone($oppFieldZone) as $oppObj) {
            if($oppObj !== null && !$oppObj->removed && $oppObj->CardID === "s3572j3oda") {
                if(CardElement($cardID) === "WATER") $reserveCost += 2;
                break;
            }
        }
    }

    // Nia, Mistveiled Scout (PZM9uvCFai): named card costs 1 more
    foreach(array_merge(GetZone("myField"), GetZone("theirField")) as $niaObj) {
        if($niaObj === null || $niaObj->removed || $niaObj->CardID !== "PZM9uvCFai") continue;
        foreach($niaObj->TurnEffects as $niaTe) {
            if(strpos($niaTe, "PZM9uvCFai-") === 0
                && $cardID === substr($niaTe, strlen("PZM9uvCFai-"))) {
                $reserveCost += 1;
                break 2;
            }
        }
    }

    // Dawn of Ashes (4coy34bro8): non-norm element cards cost 1 more
    if(CardElement($cardID) !== "NORM") {
        foreach(array_merge(GetZone("myField"), GetZone("theirField")) as $fObj) {
            if($fObj !== null && !$fObj->removed && $fObj->CardID === "4coy34bro8") { $reserveCost += 1; break; }
        }
    }

    // Xuchang, Frozen Citadel: next card costs 2 more (one-shot)
    if(GlobalEffectCount($player, "XUCHANG_COST_INCREASE") > 0) {
        $reserveCost += 2;
        if(!$dryRun) RemoveGlobalEffect($player, "XUCHANG_COST_INCREASE");
    }

    // Burnished Obelith (mz1dJZExOk): next card costs 2 more (one-shot)
    if(GlobalEffectCount($player, "mz1dJZExOk_COST") > 0) {
        $reserveCost += 2;
        if(!$dryRun) RemoveGlobalEffect($player, "mz1dJZExOk_COST");
    }

    // Consumption Ring (g8q7imka92): non-ally cards opponents activate cost 4 more
    if(!PropertyContains($cardType, "ALLY") && GlobalEffectCount($opponent, "CONSUMPTION_RING_COST") > 0) {
        $reserveCost += 4;
    }

    // Optical Control (j4U5Tu76Lz): chosen card type opponents activate costs 4 more
    foreach(array_merge(GetZone("myField"), GetZone("theirField")) as $ocObj) {
        if($ocObj === null || $ocObj->removed || $ocObj->CardID !== "j4U5Tu76Lz" || HasNoAbilities($ocObj)) continue;
        if($ocObj->Controller == $player) continue;
        foreach($ocObj->TurnEffects ?? [] as $effect) {
            if(strpos($effect, "j4U5Tu76Lz-") !== 0) continue;
            if(PropertyContains($cardType, substr($effect, strlen("j4U5Tu76Lz-")))) {
                $reserveCost += 4; break;
            }
        }
    }

    if(GlobalEffectCount($opponent, "llQe0cg4xJ_COST") > 0)          $reserveCost += 1;
    if(GlobalEffectCount($opponent, "CRYSTALLIZED_DESTINY_COST") > 0)  $reserveCost += 2;

    // Jianyu, Fate's Premonition (qv0vn6tuow): chosen card name costs 2+X more
    foreach(array_merge(GetZone("myField"), GetZone("theirField")) as $fieldObj) {
        if($fieldObj === null || $fieldObj->removed || $fieldObj->CardID !== "qv0vn6tuow" || HasNoAbilities($fieldObj)) continue;
        foreach($fieldObj->TurnEffects ?? [] as $effect) {
            if(strpos($effect, "qv0vn6tuow-") !== 0) continue;
            if($cardID !== substr($effect, strlen("qv0vn6tuow-"))) continue;
            $fz = $fieldObj->Controller == $playerID ? "myField" : "theirField";
            $reserveCost += 2 + count(ZoneSearch($fz, ["PHANTASIA"]));
            break 2;
        }
    }

    // Kingdom's Divide (qy34r8gffr): chosen card name costs 2 more
    foreach(array_merge(GetZone("myField"), GetZone("theirField")) as $fieldObj) {
        if($fieldObj === null || $fieldObj->removed || !PropertyContains(EffectiveCardType($fieldObj), "CHAMPION")) continue;
        foreach($fieldObj->TurnEffects ?? [] as $effect) {
            if(strpos($effect, "qy34r8gffr-") !== 0) continue;
            if($cardID === substr($effect, strlen("qy34r8gffr-"))) { $reserveCost += 2; break 2; }
        }
    }

    // Break Apart (4ns2jbt4hq): costs 2 more only when ALL valid targets are regalias
    if($cardID === "4ns2jbt4hq") {
        $bpTargets = array_merge(
            ZoneSearch("myField", ["ITEM"]), ZoneSearch("myField", ["WEAPON"]),
            ZoneSearch("theirField", ["ITEM"]), ZoneSearch("theirField", ["WEAPON"])
        );
        $bpRegalias = 0; $bpNonRegalias = 0;
        foreach($bpTargets as $bpMZ) {
            $bpObj = GetZoneObject($bpMZ);
            if(PropertyContains(CardType($bpObj->CardID), "REGALIA")) $bpRegalias++;
            else $bpNonRegalias++;
        }
        if($bpRegalias > 0 && $bpNonRegalias == 0) $reserveCost += 2;
    }

    // Coronation Ceremony (y4PZCiE26a): costs 2 less only when ALL valid targets are unique allies
    if($cardID === "y4PZCiE26a") {
        $allUnits = FilterSpellshroudTargets(array_merge(
            ZoneSearch("myField", ["ALLY", "CHAMPION"]),
            ZoneSearch("theirField", ["ALLY", "CHAMPION"])
        ));
        $ccUnique = 0; $ccNonUnique = 0;
        foreach($allUnits as $uMZ) {
            $uObj = GetZoneObject($uMZ);
            if(PropertyContains(EffectiveCardType($uObj), "ALLY")
                && PropertyContains(EffectiveCardType($uObj), "UNIQUE")) $ccUnique++;
            else $ccNonUnique++;
        }
        if($ccUnique > 0 && $ccNonUnique == 0) $reserveCost = max(0, $reserveCost - 2);
    }

    // Gearstride Gloves (lcb6jhxctx): next Reaction card costs 1 less (one-shot)
    if(GlobalEffectCount($player, "lcb6jhxctx_REACTION_DISCOUNT") > 0
        && PropertyContains(CardSubtypes($cardID), "REACTION")) {
        $reserveCost = max(0, $reserveCost - 1);
        if(!$dryRun) RemoveGlobalEffect($player, "lcb6jhxctx_REACTION_DISCOUNT");
    }

    // Paired Minds, Kindred Souls (7qjnqww067): next Horse ally costs 2 less (one-shot)
    if(GlobalEffectCount($player, "7qjnqww067") > 0
        && PropertyContains(CardType($cardID), "ALLY")
        && PropertyContains(CardSubtypes($cardID), "HORSE")) {
        $reserveCost = max(0, $reserveCost - 2);
        if(!$dryRun) RemoveGlobalEffect($player, "7qjnqww067");
    }

    // Slime Calling (dc8P58gmjR): Slime ally chosen via Slime Calling costs 1 less (one-shot per use)
    if(GlobalEffectCount($player, "dc8P58gmjR_SLIME_DISCOUNT") > 0
        && PropertyContains(CardType($cardID), "ALLY")
        && PropertyContains(CardSubtypes($cardID), "SLIME")) {
        $reserveCost = max(0, $reserveCost - 1);
        if(!$dryRun) RemoveGlobalEffect($player, "dc8P58gmjR_SLIME_DISCOUNT");
    }

    // Umbral Tithe (2snsdwmxz1): costs 1 less per Curse in any champion's lineage
    if($cardID === "2snsdwmxz1") {
        $reserveCost = max(0, $reserveCost - CountCursesInLineage($player) - CountCursesInLineage($opponent));
    }

    // Debilitating Grasp (wbsmks4etk): first card each turn costs 1 more
    if(!AreCurseLineageAbilitiesSuppressed($player) && ChampionHasInLineage($player, "wbsmks4etk")
        && CardActivatedCallCount($player) == 0) {
        $reserveCost += 1;
    }

    // Mordred, Burnished Avenger (OWCdWq3mXY): first attack card costs 2 less when Mordred leveled up this turn
    if(ChampionHasInLineage($player, "OWCdWq3mXY")
        && GlobalEffectCount($player, "LEVELED_UP_THIS_TURN") > 0
        && AttackCardActivatedCount($player) === 0
        && PropertyContains(CardType($cardID), "ATTACK")) {
        $reserveCost = max(0, $reserveCost - 2);
    }

    // Waited Accord (xF9phlSAkE): first advanced element card each turn costs 2 more per active copy
    if(IsAdvancedElementCard($cardID) && AdvancedElementActivatedCount($player) == 0) {
        foreach(array_merge(GetField(1), GetField(2)) as $fieldObj) {
            if($fieldObj === null || $fieldObj->removed || $fieldObj->CardID !== "xF9phlSAkE" || HasNoAbilities($fieldObj)) continue;
            if(intval($fieldObj->Counters["waitedAccordActive"] ?? 0) > 0) $reserveCost += 2;
        }
    }

    // Keep of the Golden Sashes (gjhv2etytr): first card opponents activate each turn costs 1 more
    if($player !== $turnPlayer) {
        $keepZone = ($turnPlayer == $playerID) ? "myField" : "theirField";
        foreach(GetZone($keepZone) as $kObj) {
            if($kObj !== null && !$kObj->removed && $kObj->CardID === "gjhv2etytr" && !HasNoAbilities($kObj)) {
                if(CardActivatedCallCount($player) == 0) $reserveCost += 1;
                break;
            }
        }
    }

    // Calamity Cannon (lwabipl6gt): [Polkhawk Bonus] costs 3 less
    if($cardID === "lwabipl6gt") {
        foreach(GetZone("myField") as $fObj) {
            if($fObj !== null && !$fObj->removed && PropertyContains(EffectiveCardType($fObj), "CHAMPION")) {
                if(in_array($fObj->CardID, ["ryvfq3huqj", "8eyeqhc37y"])) $reserveCost = max(0, $reserveCost - 3);
                break;
            }
        }
    }

    // Obsequious Blow next-turn cost increase (one-shot)
    if(GlobalEffectCount($player, "OBSEQUIOUS_BLOW_COST") > 0) {
        $reserveCost += 2;
        if(!$dryRun) RemoveGlobalEffect($player, "OBSEQUIOUS_BLOW_COST");
    }

    // Mana Resonance: store final reserve cost so its ability can reference how much was paid
    if($cardID === "qp65vbdw7c" && !$dryRun) {
        DecisionQueueController::StoreVariable("manaResonanceReservePaid", strval(max(0, $reserveCost)));
    }

    return max(0, $reserveCost);
}

/**
 * Virtual property for Hand zone: returns the card's current effective activation cost
 * when it differs from the base cost, or -1 when the cost is unchanged.
 * The badge uses ShowNegative=false to hide the -1 sentinel, so it only appears
 * when there is an actual discount or surcharge. When cost is reduced to 0 the
 * badge correctly shows "0" instead of being hidden.
 */

function NormalizeMZ($mzID, $player) {
    global $playerID;
    $mzArr = explode("-", $mzID);
    $mzZoneName = $mzArr[0] ?? "";
    if(str_starts_with($mzZoneName, "my")) $mzZoneName = substr($mzZoneName, 2);
    else if(str_starts_with($mzZoneName, "their")) $mzZoneName = substr($mzZoneName, 5);
    if($player == $playerID) return "my" . $mzZoneName . "-" . ($mzArr[1] ?? "");
    else return "their" . $mzZoneName . "-" . ($mzArr[1] ?? "");
}

?>
